-- Mutation metadata guards and registry/version triggers are installed centrally.
do $$ declare item record; pair text[]; begin
  for item in select table_name from information_schema.columns where table_schema = 'tonde'
      and table_name::text = any(array['workspaces','workspace_members','profiles','user_preferences','objects','projects','series','series_collections','productions','series_episodes','acts','sequences','assets','scenes','shots','scene_participants','production_resources','resource_compatibility','equipment_kits','kit_resources','media_files','asset_media','production_references','creative_documents','dialogue_lines','execution_plans','scope_bindings','object_versions','object_dependencies','director_threads','director_messages','results','shot_match_reports','jobs','exports','integration_connections','billing_accounts','usage_events','audit_events']) and column_name = 'updated_at' loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item.table_name);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()',item.table_name);
  end loop;
  foreach pair slice 1 in array array[
    ['projects','project'],['productions','production'],['series','series'],['series_collections','collection'],
    ['acts','act'],['sequences','sequence'],['scenes','scene'],['shots','shot'],['assets','asset'],
    ['production_references','reference'],['creative_documents','creative_document'],['dialogue_lines','dialogue_line'],
    ['execution_plans','execution_plan'],['results','result']
  ] loop
    execute format('drop trigger if exists a_register_object on tonde.%I', pair[1]);
execute format('create trigger a_register_object after insert on tonde.%I for each row execute function tonde_private.register_object(%L)',pair[1],pair[2]);
    if exists (select 1 from information_schema.columns where table_schema = 'tonde'
      and table_name::text = any(array['workspaces','workspace_members','profiles','user_preferences','objects','projects','series','series_collections','productions','series_episodes','acts','sequences','assets','scenes','shots','scene_participants','production_resources','resource_compatibility','equipment_kits','kit_resources','media_files','asset_media','production_references','creative_documents','dialogue_lines','execution_plans','scope_bindings','object_versions','object_dependencies','director_threads','director_messages','results','shot_match_reports','jobs','exports','integration_connections','billing_accounts','usage_events','audit_events']) and table_name = pair[1] and column_name = 'revision') then
      execute format('drop trigger if exists b_capture_revision on tonde.%I', pair[1]);
execute format('create trigger b_capture_revision after insert or update on tonde.%I for each row execute function tonde_private.capture_revision()',pair[1]);
    end if;
  end loop;
  foreach pair slice 1 in array array[['projects'],['productions'],['assets'],['integration_connections'],['exports'],['workspace_members']] loop
    execute format('drop trigger if exists c_audit on tonde.%I', pair[1]);
execute format('create trigger c_audit after insert or update or delete on tonde.%I for each row execute function tonde_private.record_audit()',pair[1]);
  end loop;
end $$;


-- Atomic creation avoids orphan projects when a second browser request fails.
create or replace function tonde.create_project_with_production(target_workspace uuid, production_title text, kind tonde.production_type default 'custom')
returns uuid language plpgsql security definer set search_path = '' as $$
declare project_id uuid; production_id uuid;
begin
  if not tonde.can_edit_workspace(target_workspace) then raise exception 'Workspace access denied' using errcode = '42501'; end if;
  insert into tonde.projects(workspace_id,title,created_by) values(target_workspace,production_title,auth.uid()) returning id into project_id;
  insert into tonde.productions(workspace_id,project_id,title,production_type,created_by)
    values(target_workspace,project_id,production_title,kind,auth.uid()) returning id into production_id;
  return production_id;
end;
$$;

-- Functions are NOT globally executable by default.
