    and to_regprocedure('tonde.bootstrap_workspace()') is not null
    and to_regprocedure('tonde.create_project_with_production(uuid,text,tonde.production_type)') is not null then
    execute $tonde_idem_ddl$grant execute on function tonde.is_workspace_member(uuid), tonde.can_edit_workspace(uuid), tonde.is_workspace_admin(uuid), tonde.bootstrap_workspace(), tonde.create_project_with_production(uuid,text,tonde.production_type) to authenticated$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

