begin;

-- Keep durations exact AND representable in browser Number arithmetic.
do $$ declare entity text; field text; begin
  foreach entity in array array['productions','acts','sequences','scenes','shots'] loop
    foreach field in array array['planned_duration_ms','calculated_duration_ms','start_ms','end_ms'] loop
      if not exists (
      select 1 from pg_constraint
      where conrelid = format('tonde.%I', entity)::regclass
        and conname = entity || '_' || field || '_safe_integer'
    ) then
      execute format('alter table tonde.%I add constraint %I check (%I <= 9007199254740991)',entity,entity || '_' || field || '_safe_integer',field);
    end if;
    end loop;
  end loop;
end $$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint c
    where c.conrelid = to_regclass('tonde.media_files')
      and regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(pg_get_constraintdef(c.oid)), 'tonde\.', '', 'g'), '::[a-z_][a-z0-9_.]*', '', 'g'), '[\s()\[\]]', '', 'g'), '''', '', 'g'), '<>allarray', 'notin', 'g'), '=anyarray', 'in', 'g')
        = 'checkduration_ms<=9007199254740991'
  ) then
    execute $tonde_idem_ddl$alter table tonde.media_files add check (duration_ms <= 9007199254740991)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint c
    where c.conrelid = to_regclass('tonde.dialogue_lines')
      and regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(pg_get_constraintdef(c.oid)), 'tonde\.', '', 'g'), '::[a-z_][a-z0-9_.]*', '', 'g'), '[\s()\[\]]', '', 'g'), '''', '', 'g'), '<>allarray', 'notin', 'g'), '=anyarray', 'in', 'g')
        = 'checkstart_ms<=9007199254740991andduration_ms<=9007199254740991-start_ms'
  ) then
    execute $tonde_idem_ddl$alter table tonde.dialogue_lines add check (start_ms <= 9007199254740991 and duration_ms <= 9007199254740991 - start_ms)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint c
    where c.conrelid = to_regclass('tonde.series_episodes')
