        = 'checkruntime_target_ms<=9007199254740991'
  ) then
    execute $tonde_idem_ddl$alter table tonde.series_episodes add check (runtime_target_ms <= 9007199254740991)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

