-- ==========================================================================
-- 202610050007_human_acceptance.sql
-- ==========================================================================

begin;

create or replace function tonde_private.guard_human_acceptance() returns trigger
language plpgsql set search_path = '' as $$
declare old_row jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  new_row jsonb := to_jsonb(new); accepting boolean := false;
begin
  accepting := (new_row->>'approval' = 'approved' and old_row->>'approval' is distinct from 'approved')
    or (tg_table_name = 'results' and new_row->>'state' in ('approved','final') and old_row->>'state' is distinct from new_row->>'state');
  if accepting and (auth.uid() is null or current_user = 'service_role' or not tonde.can_edit_workspace((new_row->>'workspace_id')::uuid)) then
    raise exception 'Approval requires an authenticated creator decision' using errcode = '42501';
  end if;
  -- A combined content-change + approval request does not approve unseen work.
  if tg_op = 'UPDATE' and accepting and
    (new_row - array['approval','state','locked_at','updated_at','revision']) is distinct from
    (old_row - array['approval','state','locked_at','updated_at','revision']) then
    raise exception 'Review the changed version before approving it' using errcode = '23514';
  end if;
  if tg_table_name = 'results' and tg_op = 'UPDATE' and old_row->>'state' in ('approved','final') and
    (new_row - array['approval','state','locked_at','updated_at','revision']) is distinct from
    (old_row - array['approval','state','locked_at','updated_at','revision']) then
    new := jsonb_populate_record(new, jsonb_build_object('state','needs_review'));
  end if;
  return new;
end;
$$;

do $$ declare entity text; begin
  for entity in select table_name from information_schema.columns where table_schema='tonde'
      and table_name::text = any(array['workspaces','workspace_members','profiles','user_preferences','objects','projects','series','series_collections','productions','series_episodes','acts','sequences','assets','scenes','shots','scene_participants','production_resources','resource_compatibility','equipment_kits','kit_resources','media_files','asset_media','production_references','creative_documents','dialogue_lines','execution_plans','scope_bindings','object_versions','object_dependencies','director_threads','director_messages','results','shot_match_reports','jobs','exports','integration_connections','billing_accounts','usage_events','audit_events']) and column_name='approval' loop
    execute format('drop trigger if exists a_human_acceptance on tonde.%I', entity);
execute format('create trigger a_human_acceptance before insert or update on tonde.%I for each row execute function tonde_private.guard_human_acceptance()',entity);
  end loop;
end $$;

revoke all on function tonde_private.guard_human_acceptance() from public, anon, authenticated;

commit;

-- ==========================================================================
-- 202610050008_tonde_schema_usage.sql
-- ==========================================================================

-- PostgREST introspection requires USAGE on exposed schemas for the anon role:
-- without it, hosted Data API requests with the publishable key returned
-- PGRST205 even after `tonde` was added to exposed schemas. Only schema-level
-- USAGE is granted; no table/sequence/routine privileges are added, so
-- anonymous users still cannot read or mutate TONDE data (RLS and explicit
-- table grants remain the access boundary). Verified: anonymous reads return
-- HTTP 401, and the hosted two-user acceptance suite passes 20/20 with this
-- grant applied.

grant usage on schema tonde to anon;

-- ==========================================================================
-- 202610050009_revoke_public_rls_admin.sql
-- ==========================================================================

-- Supabase platform event-trigger helper discovered during hosted review.
-- Keep it external to the clean TONDE schema lineage, but remove inherited/client
-- EXECUTE rights wherever it exists. It is absent in isolated local installs.
begin;

do $$
begin
  if to_regprocedure('public.rls_auto_enable()') is not null then
    execute 'revoke execute on function public.rls_auto_enable() from public, anon, authenticated, service_role';
  end if;
end
$$;

commit;

-- ==========================================================================
-- 202610050010_hide_policy_helpers.sql
-- ==========================================================================

-- These SECURITY DEFINER helpers are required by RLS and private Storage
-- policies, but are not user-facing RPCs. Move them out of the exposed API.
begin;

grant usage on schema tonde_private to authenticated;


-- Move routines without rewriting dependency expressions, then recreate every
-- policy/function whose SQL text referred to the old exposed names.
do $tonde_idem$
begin
  if to_regprocedure('tonde.is_workspace_member(uuid)') is not null
    and to_regprocedure('tonde_private.is_workspace_member(uuid)') is null then
    execute $tonde_idem_ddl$alter function tonde.is_workspace_member(uuid) set schema tonde_private$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if to_regprocedure('tonde.can_edit_workspace(uuid)') is not null
    and to_regprocedure('tonde_private.can_edit_workspace(uuid)') is null then
    execute $tonde_idem_ddl$alter function tonde.can_edit_workspace(uuid) set schema tonde_private$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if to_regprocedure('tonde.is_workspace_admin(uuid)') is not null
    and to_regprocedure('tonde_private.is_workspace_admin(uuid)') is null then
    execute $tonde_idem_ddl$alter function tonde.is_workspace_admin(uuid) set schema tonde_private$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if to_regprocedure('tonde.can_read_storage_object(text, text)') is not null
    and to_regprocedure('tonde_private.can_read_storage_object(text, text)') is null then
    execute $tonde_idem_ddl$alter function tonde.can_read_storage_object(text, text) set schema tonde_private$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if to_regprocedure('tonde.can_upload_storage_object(text, text)') is not null
    and to_regprocedure('tonde_private.can_upload_storage_object(text, text)') is null then
    execute $tonde_idem_ddl$alter function tonde.can_upload_storage_object(text, text) set schema tonde_private$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;


revoke all on function tonde_private.is_workspace_member(uuid),
  tonde_private.can_edit_workspace(uuid), tonde_private.is_workspace_admin(uuid),
  tonde_private.can_read_storage_object(text, text),
  tonde_private.can_upload_storage_object(text, text)
  from public, anon, authenticated, service_role;

grant execute on function tonde_private.is_workspace_member(uuid),
  tonde_private.can_edit_workspace(uuid), tonde_private.is_workspace_admin(uuid),
  tonde_private.can_read_storage_object(text, text),
  tonde_private.can_upload_storage_object(text, text)
  to authenticated;


-- Membership-check functions are stored as SQL expressions by Postgres and
-- keep the old qualified name after ALTER FUNCTION SET SCHEMA.
do $$
declare policy_row record; rewritten_qual text; rewritten_check text;
begin
  for policy_row in
    select schemaname, tablename, policyname, cmd, roles, qual, with_check
    from pg_policies
    where (schemaname = 'tonde' and (
      coalesce(qual, '') like '%tonde.is_workspace_member(%'
      or coalesce(qual, '') like '%tonde.can_edit_workspace(%'
      or coalesce(qual, '') like '%tonde.is_workspace_admin(%'
      or coalesce(with_check, '') like '%tonde.is_workspace_member(%'
      or coalesce(with_check, '') like '%tonde.can_edit_workspace(%'
      or coalesce(with_check, '') like '%tonde.is_workspace_admin(%'
    )) or (schemaname = 'storage' and (
      coalesce(qual, '') like '%tonde.can_read_storage_object(%'
      or coalesce(with_check, '') like '%tonde.can_upload_storage_object(%'
    ))
  loop
    rewritten_qual := policy_row.qual;
    rewritten_check := policy_row.with_check;
    if rewritten_qual is not null then
      rewritten_qual := replace(replace(replace(rewritten_qual,
        'tonde.is_workspace_member(', 'tonde_private.is_workspace_member('),
        'tonde.can_edit_workspace(', 'tonde_private.can_edit_workspace('),
        'tonde.is_workspace_admin(', 'tonde_private.is_workspace_admin(');
      rewritten_qual := replace(rewritten_qual, 'tonde.can_read_storage_object(', 'tonde_private.can_read_storage_object(');
    end if;
    if rewritten_check is not null then
      rewritten_check := replace(replace(replace(rewritten_check,
        'tonde.is_workspace_member(', 'tonde_private.is_workspace_member('),
        'tonde.can_edit_workspace(', 'tonde_private.can_edit_workspace('),
        'tonde.is_workspace_admin(', 'tonde_private.is_workspace_admin(');
      rewritten_check := replace(rewritten_check, 'tonde.can_upload_storage_object(', 'tonde_private.can_upload_storage_object(');
    end if;
    execute format('drop policy %I on %I.%I', policy_row.policyname, policy_row.schemaname, policy_row.tablename);
    execute format('create policy %I on %I.%I as permissive for %s to %s%s%s',
      policy_row.policyname, policy_row.schemaname, policy_row.tablename, policy_row.cmd,
      array_to_string(policy_row.roles, ', '),
      case when rewritten_qual is not null then ' using (' || rewritten_qual || ')' else '' end,
      case when rewritten_check is not null then ' with check (' || rewritten_check || ')' else '' end);
  end loop;
end
$$;


create or replace function tonde_private.can_read_storage_object(target_bucket text, target_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from tonde.media_files m where m.storage_provider = 'supabase'
    and m.bucket = target_bucket and m.object_key = target_name and m.upload_state <> 'deleted'
    and (m.expires_at is null or m.expires_at > now())
    and tonde_private.is_workspace_member(m.workspace_id));
$$;

create or replace function tonde_private.can_upload_storage_object(target_bucket text, target_name text) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists(select 1 from tonde.media_files m where m.storage_provider = 'supabase'
    and m.bucket = target_bucket and m.object_key = target_name and m.upload_state = 'pending'
    and m.created_by = (select auth.uid()) and tonde_private.can_edit_workspace(m.workspace_id)
    and target_bucket <> 'tonde-exports' and (m.expires_at is null or m.expires_at > now()));
$$;

create or replace function tonde_private.guard_mutation() returns trigger
language plpgsql set search_path = '' as $$
declare old_row jsonb; new_row jsonb; field text;
begin
  new_row := to_jsonb(new);
  if tg_op = 'UPDATE' then
    old_row := to_jsonb(old);
    foreach field in array array['id','workspace_id','production_id','created_by','created_at','user_id','owner_user_id'] loop
      if old_row ? field and new_row->field is distinct from old_row->field then
        raise exception 'Identity and ownership are immutable' using errcode = '23514';
      end if;
    end loop;
    if old_row ? 'locked_at' and old_row->>'locked_at' is not null
      and (new_row - array['locked_at','updated_at','revision','approval']) is distinct from (old_row - array['locked_at','updated_at','revision','approval']) then
      raise exception 'Unlock this object before editing' using errcode = '23514';
    end if;
    if old_row ? 'revision' then
      if (new_row->>'revision')::integer <> (old_row->>'revision')::integer then
        raise exception 'Revision is managed by the database' using errcode = '23514';
      end if;
      new := jsonb_populate_record(new, jsonb_build_object('revision', (old_row->>'revision')::integer + 1));
      if old_row->>'approval' = 'approved'
        and (new_row - array['approval','locked_at','updated_at','revision']) is distinct from (old_row - array['approval','locked_at','updated_at','revision']) then
        new := jsonb_populate_record(new, jsonb_build_object('approval','changed_after_approval'));
      end if;
    end if;
  elsif new_row ? 'revision' and (new_row->>'revision')::integer <> 1 then
    raise exception 'Initial revision must be one' using errcode = '23514';
  end if;
  if new_row ? 'updated_at' then new := jsonb_populate_record(new, jsonb_build_object('updated_at', now())); end if;
  if tg_op = 'INSERT' and new_row ? 'created_by' and auth.uid() is not null
    and new_row->>'created_by' is distinct from auth.uid()::text then
    raise exception 'Creator does not match authenticated user' using errcode = '42501';
  end if;
  if tg_table_name = 'profiles' and new_row->>'default_workspace_id' is not null
    and auth.uid() is not null and not tonde_private.is_workspace_member((new_row->>'default_workspace_id')::uuid) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  return new;
end;
$$;

create or replace function tonde_private.guard_human_acceptance() returns trigger
language plpgsql set search_path = '' as $$
declare old_row jsonb := case when tg_op = 'UPDATE' then to_jsonb(old) else '{}'::jsonb end;
  new_row jsonb := to_jsonb(new); accepting boolean := false;
begin
  accepting := (new_row->>'approval' = 'approved' and old_row->>'approval' is distinct from 'approved')
    or (tg_table_name = 'results' and new_row->>'state' in ('approved','final') and old_row->>'state' is distinct from new_row->>'state');
  if accepting and (auth.uid() is null or (select auth.role()) = 'service_role' or not tonde_private.can_edit_workspace((new_row->>'workspace_id')::uuid)) then
    raise exception 'Approval requires an authenticated creator decision' using errcode = '42501';
  end if;
  if tg_op = 'UPDATE' and accepting and
    (new_row - array['approval','state','locked_at','updated_at','revision']) is distinct from
    (old_row - array['approval','state','locked_at','updated_at','revision']) then
    raise exception 'Review the changed version before approving it' using errcode = '23514';
  end if;
  if tg_table_name = 'results' and tg_op = 'UPDATE' and old_row->>'state' in ('approved','final') and
    (new_row - array['approval','state','locked_at','updated_at','revision']) is distinct from
    (old_row - array['approval','state','locked_at','updated_at','revision']) then
    new := jsonb_populate_record(new, jsonb_build_object('state','needs_review'));
  end if;
  return new;
end;
$$;

create or replace function tonde.create_project_with_production(target_workspace uuid, production_title text, kind tonde.production_type default 'custom')
returns uuid language plpgsql security definer set search_path = '' as $$
declare project_id uuid; production_id uuid;
begin
  if not tonde_private.can_edit_workspace(target_workspace) then raise exception 'Workspace access denied' using errcode = '42501'; end if;
  insert into tonde.projects(workspace_id,title,created_by) values(target_workspace,production_title,auth.uid()) returning id into project_id;
  insert into tonde.productions(workspace_id,project_id,title,production_type,created_by)
    values(target_workspace,project_id,production_title,kind,auth.uid()) returning id into production_id;
  return production_id;
end;
$$;


-- These are authenticated user APIs, not system/service-role entry points.
revoke execute on function tonde.bootstrap_workspace(),
  tonde.create_project_with_production(uuid, text, tonde.production_type)
  from public, anon, service_role;

grant execute on function tonde.bootstrap_workspace(),
  tonde.create_project_with_production(uuid, text, tonde.production_type)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050011_director_intake.sql
-- ==========================================================================

begin;


create table if not exists tonde.director_intakes (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  collaboration_mode text not null default 'stop_at_major_decisions'
    check (collaboration_mode in ('guide_step_by_step','stop_at_major_decisions','complete_first_draft')),
  status text not null default 'intake'
    check (status in ('intake','draft_ready','ready_for_studio')),
  intent jsonb not null check (jsonb_typeof(intent) = 'object'),
  plan jsonb not null default '{}' check (jsonb_typeof(plan) = 'object'),
  applied_operation_id uuid,
  proposal_operation_id uuid,
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, production_id),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);

create index if not exists director_intakes_status on tonde.director_intakes(workspace_id, status, updated_at desc);

alter table tonde.director_intakes enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'director_intakes'
      and policyname = 'director_intakes_read'
  ) then
    execute $tonde_idem_ddl$create policy director_intakes_read on tonde.director_intakes for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.director_intakes to authenticated;

drop trigger if exists guard_director_intake on tonde.director_intakes;
create trigger guard_director_intake before insert or update on tonde.director_intakes
  for each row execute function tonde_private.guard_mutation();


create table if not exists tonde.director_plan_proposals (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  intake_id uuid not null,
  operation_id uuid not null,
  source_production_revision integer not null check (source_production_revision > 0),
  source_intake_revision integer not null check (source_intake_revision > 0),
  state text not null default 'proposed' check (state in ('proposed','applied','superseded')),
  plan jsonb not null check (jsonb_typeof(plan) = 'object'),
  created_at timestamptz not null default now(),
  unique (workspace_id, operation_id),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, intake_id) references tonde.director_intakes(workspace_id, id) on delete restrict
);

create index if not exists director_plan_proposals_current on tonde.director_plan_proposals(workspace_id, production_id, created_at desc);

alter table tonde.director_plan_proposals enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'director_plan_proposals'
      and policyname = 'director_plan_proposals_read'
  ) then
    execute $tonde_idem_ddl$create policy director_plan_proposals_read on tonde.director_plan_proposals for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.director_plan_proposals to authenticated;


create or replace function tonde.save_director_intake(
  target_workspace uuid, target_production uuid, expected_intake_revision integer, intake jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare current_row tonde.director_intakes;
  reference_id_text text;
begin
  if auth.uid() is null or (select auth.role()) <> 'authenticated'
    or not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Authenticated workspace editor required' using errcode = '42501';
  end if;
  if jsonb_typeof(intake) <> 'object' or pg_column_size(intake) > 40000
    or coalesce(length(btrim(intake->>'goal')),0) = 0 or length(intake->>'goal') > 10000
    or intake->>'collaboration_mode' not in ('guide_step_by_step','stop_at_major_decisions','complete_first_draft') then
    raise exception 'Invalid Director intake' using errcode = '22023';
  end if;
  if jsonb_typeof(intake->'constraints') <> 'object' or pg_column_size(intake)>40000
    or jsonb_typeof(intake->'answered_decisions') <> 'object'
    or (intake ? 'selected_reference_ids' and (jsonb_typeof(intake->'selected_reference_ids') <> 'array' or jsonb_array_length(intake->'selected_reference_ids') > 12)) then
    raise exception 'Invalid Director structured intent' using errcode = '22023';
  end if;
  if intake ? 'selected_reference_ids' then
    if jsonb_typeof(intake->'selected_reference_ids') <> 'array' or jsonb_array_length(intake->'selected_reference_ids') > 12 then
      raise exception 'Invalid Director reference selection' using errcode = '22023';
    end if;
    for reference_id_text in select jsonb_array_elements_text(intake->'selected_reference_ids') loop
      if not exists (select 1 from tonde.production_references r where r.workspace_id=target_workspace
        and r.production_id=target_production and r.id=reference_id_text::uuid) then
        raise exception 'Reference is unavailable in this Production' using errcode = '42501';
      end if;
    end loop;
  end if;
  select * into current_row from tonde.director_intakes
    where workspace_id=target_workspace and production_id=target_production for update;
  if found then
    if expected_intake_revision is null or current_row.revision <> expected_intake_revision then
      raise exception 'Director intake changed; reload before saving' using errcode = '40001';
    end if;
    if current_row.status='ready_for_studio' then
      raise exception 'A Studio draft already exists; start a reviewed revision instead' using errcode = '55000';
    end if;
    update tonde.director_plan_proposals set state='superseded'
      where workspace_id=target_workspace and intake_id=current_row.id and state='proposed';
    update tonde.director_intakes set intent=intake, plan='{}'::jsonb, status='intake', proposal_operation_id=null,
      collaboration_mode=intake->>'collaboration_mode', updated_at=now()
      where id=current_row.id;
    select * into current_row from tonde.director_intakes where id=current_row.id;
  else
    if expected_intake_revision is not null then
      raise exception 'Director intake changed; reload before saving' using errcode = '40001';
    end if;
    insert into tonde.director_intakes(workspace_id,production_id,intent,collaboration_mode)
      values(target_workspace,target_production,intake,intake->>'collaboration_mode') returning * into current_row;
  end if;
  return jsonb_build_object('id',current_row.id,'revision',current_row.revision,'status',current_row.status);
end;
$$;


create or replace function tonde.save_director_plan_proposal(
  target_workspace uuid, target_production uuid, expected_production_revision integer,
  expected_intake_revision integer, operation_id uuid, proposal_plan jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare production_row tonde.productions;
  intake_row tonde.director_intakes;
  existing_proposal tonde.director_plan_proposals;
  target_duration bigint;
  scene jsonb;
  scene_total bigint := 0;
  duration bigint;
begin
  if auth.uid() is null or (select auth.role()) <> 'authenticated'
    or not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Authenticated workspace editor required' using errcode = '42501';
  end if;
  select * into existing_proposal from tonde.director_plan_proposals p
    where p.workspace_id=target_workspace and p.operation_id=save_director_plan_proposal.operation_id;
  if found then
    if existing_proposal.production_id <> target_production or existing_proposal.plan <> proposal_plan then
      raise exception 'An idempotency key cannot be reused for different plan content' using errcode = '23505';
    end if;
    return jsonb_build_object('intake_id',existing_proposal.intake_id,'status',
      case when existing_proposal.state='applied' then 'ready_for_studio' else 'draft_ready' end,
      'revision', (select revision from tonde.director_intakes where id=existing_proposal.intake_id),
      'idempotent',true);
  end if;
  select * into production_row from tonde.productions where workspace_id=target_workspace and id=target_production for update;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if production_row.revision <> expected_production_revision or production_row.approval <> 'draft' or production_row.locked_at is not null then
    raise exception 'Production changed or is protected; reload before planning' using errcode = '40001';
  end if;
  select * into intake_row from tonde.director_intakes where workspace_id=target_workspace and production_id=target_production for update;
  if not found or intake_row.revision <> expected_intake_revision or intake_row.status='ready_for_studio' then
    raise exception 'Director intake changed; reload before planning' using errcode = '40001';
  end if;
  select * into existing_proposal from tonde.director_plan_proposals p
    where p.workspace_id=target_workspace and p.production_id=target_production and p.state='proposed' for update;
  if found then raise exception 'A plan proposal is already pending; retry its operation or create a revised brief' using errcode = '55000'; end if;
  if jsonb_typeof(proposal_plan) <> 'object' or pg_column_size(proposal_plan)>100000
    or coalesce(length(btrim(proposal_plan->>'title')),0)=0 or length(proposal_plan->>'title')>160
    or coalesce(length(btrim(proposal_plan->>'creative_objective')),0)=0
    or jsonb_typeof(proposal_plan->'scenes') <> 'array' or jsonb_array_length(proposal_plan->'scenes')>40 then
    raise exception 'Invalid Director production plan' using errcode = '22023';
  end if;
  if not exists(select 1 from unnest(enum_range(null::tonde.production_type)) as v(value) where v::text=proposal_plan->>'production_type')
    or not exists(select 1 from unnest(enum_range(null::tonde.execution_method)) as v(value) where v::text=proposal_plan->>'execution_method') then
    raise exception 'Unsupported Production classification or execution method' using errcode = '22023';
  end if;
  if proposal_plan->>'planned_duration_ms' is not null then
    if proposal_plan->>'planned_duration_ms' !~ '^[0-9]{1,16}$' then raise exception 'Runtime must use integer milliseconds' using errcode = '22023'; end if;
    target_duration := (proposal_plan->>'planned_duration_ms')::bigint;    if target_duration > 9007199254740991 or jsonb_array_length(proposal_plan->'scenes')=0 then raise exception 'Invalid timed plan' using errcode = '22023'; end if;
  end if;
  for scene in select value from jsonb_array_elements(proposal_plan->'scenes') loop
    if jsonb_typeof(scene)<>'object' or coalesce(length(btrim(scene->>'title')),0)=0 or length(scene->>'title')>160 then
      raise exception 'Invalid planned Scene' using errcode = '22023';
    end if;
    if target_duration is not null then
      if scene->>'duration_ms' is null or scene->>'duration_ms' !~ '^[0-9]{1,16}$' then raise exception 'Timed Scene required' using errcode = '22023'; end if;
      duration := (scene->>'duration_ms')::bigint;
      if duration>9007199254740991 then raise exception 'Scene duration exceeds safe integer range' using errcode = '22023'; end if;
      if scene_total > 9007199254740991 - duration then raise exception 'Scene duration sum exceeds safe integer range' using errcode = '22003'; end if;
      scene_total := scene_total+duration;
    end if;
  end loop;
  if target_duration is not null and scene_total<>target_duration then raise exception 'Scene durations must equal the Production target exactly' using errcode = '23514'; end if;
  if scene_total > 9007199254740991 then raise exception 'Scene duration sum exceeds safe integer range' using errcode = '22003'; end if;
  if target_duration is null and exists(select 1 from jsonb_array_elements(proposal_plan->'scenes') s where s->>'duration_ms' is not null) then
    raise exception 'Scene durations require a Production target runtime' using errcode = '22023';
  end if;
  update tonde.director_plan_proposals p set state='superseded'
    where p.workspace_id=target_workspace and p.production_id=target_production and p.state='proposed';
  insert into tonde.director_plan_proposals(workspace_id,production_id,intake_id,operation_id,
    source_production_revision,source_intake_revision,plan)
    values(target_workspace,target_production,intake_row.id,save_director_plan_proposal.operation_id,
      expected_production_revision,expected_intake_revision,proposal_plan);
  update tonde.director_intakes set plan=proposal_plan,status='draft_ready',
    proposal_operation_id=save_director_plan_proposal.operation_id,updated_at=now()
    where id=intake_row.id;
  select * into intake_row from tonde.director_intakes where id=intake_row.id;
  return jsonb_build_object('intake_id',intake_row.id,'revision',intake_row.revision,'status',intake_row.status,'idempotent',false);
end;
$$;


create or replace function tonde.apply_director_plan(
  target_workspace uuid, target_production uuid, expected_production_revision integer,
  expected_intake_revision integer, operation_id uuid, explicit_confirmation boolean
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare production_row tonde.productions;
  intake_row tonde.director_intakes;
  proposal_row tonde.director_plan_proposals;
  scene jsonb;
  scene_count integer := 0;
  scene_total bigint := 0;
  target_duration bigint;
  scene_duration bigint;
  scene_order bigint := 1024;
  story_content text;
begin
  if auth.uid() is null or (select auth.role()) <> 'authenticated'
    or not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Authenticated workspace editor required' using errcode = '42501';
  end if;
  if explicit_confirmation is not true then
    raise exception 'Creator confirmation is required to build this Production' using errcode = '42501';
  end if;
  select * into production_row from tonde.productions
    where workspace_id=target_workspace and id=target_production for update;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  select * into intake_row from tonde.director_intakes
    where workspace_id=target_workspace and production_id=target_production for update;
  if not found then
    raise exception 'Director intake unavailable' using errcode = 'P0002';
  end if;
  if intake_row.status='ready_for_studio' and intake_row.applied_operation_id=operation_id then
    return jsonb_build_object('production_id',target_production,'intake_id',intake_row.id,'idempotent',true);
  end if;
  if production_row.revision <> expected_production_revision or intake_row.revision <> expected_intake_revision then
    raise exception 'Production or Director intake changed; reload before applying this draft' using errcode = '40001';
  end if;
  if production_row.approval <> 'draft' or production_row.locked_at is not null then
    raise exception 'Only an unlocked Draft Production can receive its initial Director plan' using errcode = '55000';
  end if;
  if intake_row.status='ready_for_studio' then
    raise exception 'An initial plan already exists; regeneration must be a reviewed proposal' using errcode = '55000';
  end if;
  if intake_row.status <> 'draft_ready' or intake_row.proposal_operation_id is distinct from operation_id then
    raise exception 'Review the current plan proposal before applying it' using errcode = '55000';
  end if;
  select * into proposal_row from tonde.director_plan_proposals p
    where p.workspace_id=target_workspace and p.production_id=target_production
      and p.operation_id=apply_director_plan.operation_id for update;
  if not found or proposal_row.state <> 'proposed'
    or proposal_row.source_production_revision <> production_row.revision
    or proposal_row.source_intake_revision + 1 <> intake_row.revision then
    raise exception 'This plan proposal is stale or no longer current' using errcode = '40001';
  end if;
  if production_row.approval <> 'draft' or production_row.locked_at is not null then
    raise exception 'Only an unlocked Draft Production can receive its initial Director plan' using errcode = '55000';
  end if;
  if jsonb_typeof(intake_row.plan) <> 'object' or pg_column_size(intake_row.plan) > 100000
    or coalesce(length(btrim(intake_row.plan->>'title')),0)=0 or length(intake_row.plan->>'title') > 160
    or coalesce(length(btrim(intake_row.plan->>'creative_objective')),0)=0
    or not (intake_row.plan ? 'scenes') or jsonb_typeof(intake_row.plan->'scenes') <> 'array'
    or jsonb_array_length(intake_row.plan->'scenes') > 40 then
    raise exception 'Invalid Director production plan' using errcode = '22023';
  end if;
  if not exists (select 1 from unnest(enum_range(null::tonde.production_type)) t where t::text=intake_row.plan->>'production_type')
    or not exists (select 1 from unnest(enum_range(null::tonde.execution_method)) t where t::text=intake_row.plan->>'execution_method') then
    raise exception 'Unsupported Production classification or execution method' using errcode = '22023';
  end if;
  target_duration := case when intake_row.plan->>'planned_duration_ms' is null then null else (intake_row.plan->>'planned_duration_ms')::bigint end;
  if intake_row.plan->>'planned_duration_ms' is not null then
    if intake_row.plan->>'planned_duration_ms' !~ '^[0-9]{1,16}$' or target_duration > 9007199254740991 then
      raise exception 'Runtime must use safe integer milliseconds' using errcode = '22023';
    end if;
  end if;
  for scene in select value from jsonb_array_elements(intake_row.plan->'scenes') loop
    scene_count := scene_count + 1;
    if jsonb_typeof(scene) <> 'object' or coalesce(length(btrim(scene->>'title')),0)=0
      or length(scene->>'title') > 160 or coalesce(length(scene->>'purpose'),0) > 2000 then
      raise exception 'Invalid planned Scene' using errcode = '22023';
    end if;
    if target_duration is not null then
      if scene->>'duration_ms' is null or scene->>'duration_ms' !~ '^[0-9]{1,16}$' then
        raise exception 'Every timed Scene needs integer milliseconds' using errcode = '22023';
      end if;
      scene_duration := (scene->>'duration_ms')::bigint;
      if scene_duration > 9007199254740991 then raise exception 'Scene duration exceeds safe integer range' using errcode = '22023'; end if;
      if scene_total > 9007199254740991 - scene_duration then
        raise exception 'Scene duration sum exceeds safe integer range' using errcode = '22003';
      end if;
      scene_total := scene_total + scene_duration;
    end if;
  end loop;
  if target_duration is not null and scene_total <> target_duration then
    raise exception 'Scene durations must equal the Production target exactly' using errcode = '23514';
  end if;
  if scene_total > 9007199254740991 then
    raise exception 'Scene duration sum exceeds safe integer range' using errcode = '22003';
  end if;
  if target_duration is null and exists(select 1 from jsonb_array_elements(intake_row.plan->'scenes') s where s->>'duration_ms' is not null) then
    raise exception 'Scene durations require a Production target runtime' using errcode = '22023';
  end if;
  if exists(select 1 from tonde.scenes where workspace_id=target_workspace and production_id=target_production and lifecycle='active') then
    raise exception 'Production already contains Scenes; initial plan cannot replace existing work' using errcode = '55000';
  end if;

  update tonde.productions set title=intake_row.plan->>'title', production_type=(intake_row.plan->>'production_type')::tonde.production_type,
    execution_method=(intake_row.plan->>'execution_method')::tonde.execution_method,
    planned_duration_ms=target_duration where id=target_production and workspace_id=target_workspace;
  update tonde.director_plan_proposals p set state='applied' where p.id=proposal_row.id;
  update tonde.director_intakes set status='ready_for_studio',
    applied_operation_id=apply_director_plan.operation_id, updated_at=now()
      where id=intake_row.id;
  if scene_count > 0 then
    for scene in select value from jsonb_array_elements(intake_row.plan->'scenes') loop
      insert into tonde.scenes(workspace_id,production_id,title,purpose,description,sort_order,planned_duration_ms)
      values(target_workspace,target_production,scene->>'title',coalesce(scene->>'purpose',''),
        coalesce(scene->>'description',''),scene_order,
        case when scene->>'duration_ms' is null then null else (scene->>'duration_ms')::bigint end);
      scene_order := scene_order + 1024;
    end loop;
  end if;
  insert into tonde.creative_documents(workspace_id,production_id,scope_object_id,document_type,title,content)
    values(target_workspace,target_production,target_production,'brief','Production Brief',intake_row.plan->>'creative_objective');
  if intake_row.plan->'story' is not null and intake_row.plan->'story' <> 'null'::jsonb then
    story_content := coalesce(intake_row.plan->'story'->>'summary','');
    insert into tonde.creative_documents(workspace_id,production_id,scope_object_id,document_type,title,content)
      values(target_workspace,target_production,target_production,'story','Director Structure',story_content);
  end if;
  return jsonb_build_object('production_id',target_production,'intake_id',intake_row.id,'idempotent',false);
end;
$$;


grant usage on schema tonde_private to authenticated;

revoke all on function tonde.save_director_intake(uuid,uuid,integer,jsonb),
  tonde.save_director_plan_proposal(uuid,uuid,integer,integer,uuid,jsonb),
  tonde.apply_director_plan(uuid,uuid,integer,integer,uuid,boolean)
  from public, anon, authenticated, service_role;

grant execute on function tonde.save_director_intake(uuid,uuid,integer,jsonb),
  tonde.save_director_plan_proposal(uuid,uuid,integer,integer,uuid,jsonb),  tonde.apply_director_plan(uuid,uuid,integer,integer,uuid,boolean)
 to authenticated;

commit;

-- ==========================================================================
-- 202610050012_director_intelligence.sql
-- ==========================================================================

-- Additive migration: Prompt 4 Director intelligence persistence.
-- Never rewrites an applied migration. Migrations 009/010 were applied manually by
-- the creator; this migration is additive only and does not touch them.
begin;


-- Scene-level creative detail. Canonical Scenes stay the single Scene model.
alter table tonde.scenes add column if not exists story_beat text not null default '' check (length(story_beat) <= 200);

alter table tonde.scenes add column if not exists opening_state text not null default '' check (length(opening_state) <= 400);

alter table tonde.scenes add column if not exists ending_state text not null default '' check (length(ending_state) <= 400);

alter table tonde.scenes add column if not exists visual_intent text not null default '' check (length(visual_intent) <= 900);

alter table tonde.scenes add column if not exists dialogue_notes text not null default '' check (length(dialogue_notes) <= 900);

alter table tonde.scenes add column if not exists action_lines jsonb not null default '[]' check (jsonb_typeof(action_lines) = 'array' and jsonb_array_length(action_lines) <= 16);

alter table tonde.scenes add column if not exists scene_detail jsonb not null default '{}' check (jsonb_typeof(scene_detail) = 'object' and pg_column_size(scene_detail) <= 40000);

alter table tonde.scenes add column if not exists source_operation_id uuid;


-- Dialogue lines keep first-class delivery direction, not only the spoken text.
alter table tonde.dialogue_lines add column if not exists intention text not null default '' check (length(intention) <= 300);

alter table tonde.dialogue_lines add column if not exists delivery text not null default '' check (length(delivery) <= 300);

alter table tonde.dialogue_lines add column if not exists subtext text not null default '' check (length(subtext) <= 300);

alter table tonde.dialogue_lines add column if not exists pause_after_ms bigint not null default 0 check (pause_after_ms between 0 and 60000);

alter table tonde.dialogue_lines add column if not exists line_flags jsonb not null default '{}' check (jsonb_typeof(line_flags) = 'object');


-- Every Director operation carries the full operation contract and its provenance.
create table if not exists tonde.director_operations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  operation_id uuid not null,
  operation_type text not null check (operation_type in (
    'intent_interpretation','brief_generation','question_planning','reference_preprocessing','reference_analysis',
    'transcription','technique_extraction','style_extraction','story_generation','story_alternative','script_generation',
    'dialogue_operation','domain_content_generation','scene_generation','runtime_validation','reality_check',
    'production_plan','apply_production_plan','director_command','causal_explanation','reference_role_assignment'
  )),
  scope text not null default 'production' check (scope in ('production','brief','reference','story','script','dialogue','scene','reality')),
  schema_version text not null default 'tonde.director.1' check (length(schema_version) between 1 and 40),
  source_revision integer not null check (source_revision > 0),
  source_intake_revision integer check (source_intake_revision is null or source_intake_revision > 0),
  status text not null default 'queued' check (status in ('queued','preprocessing','analyzing','synthesizing','succeeded','partial','failed','cancelled')),
  producer text not null default 'deterministic' check (producer in ('deterministic','model','domain')),
  provider text check (provider is null or length(provider) <= 80),
  model text check (model is null or length(model) <= 120),
  model_profile text not null default 'default' check (length(model_profile) <= 120),
  attempts integer not null default 0 check (attempts between 0 and 10),
  repaired boolean not null default false,
  idempotency_key text not null check (length(idempotency_key) between 1 and 200),
  collaboration_mode text not null default 'stop_at_major_decisions'
    check (collaboration_mode in ('guide_step_by_step','stop_at_major_decisions','complete_first_draft')),
  reference_ids uuid[] not null default '{}',
  constraint_summary jsonb not null default '{}' check (jsonb_typeof(constraint_summary) = 'object'),
  rationale text not null default '' check (length(rationale) <= 1200),
  limitations jsonb not null default '[]' check (jsonb_typeof(limitations) = 'array' and jsonb_array_length(limitations) <= 12),
  payload jsonb not null default '{}' check (jsonb_typeof(payload) = 'object' and pg_column_size(payload) <= 400000),
  payload_hash text check (payload_hash is null or length(payload_hash) = 32),
  error_code text check (error_code is null or length(error_code) <= 80),
  error_message text check (error_message is null or length(error_message) <= 600),
  started_at timestamptz, completed_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, operation_id),
  unique (workspace_id, idempotency_key),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);

create index if not exists director_operations_recent on tonde.director_operations(workspace_id, production_id, created_at desc);

create index if not exists director_operations_status on tonde.director_operations(workspace_id, status, updated_at desc);


-- One current structured Brief per Production, versioned by revision.
create table if not exists tonde.director_briefs (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  brief jsonb not null check (jsonb_typeof(brief) = 'object' and pg_column_size(brief) <= 200000),
  producer text not null default 'deterministic' check (producer in ('deterministic','model')),
  source_operation_id uuid,
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, production_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);


-- Answered decisions are persisted so the Director never re-asks a settled question.
create table if not exists tonde.director_decisions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  decision_id text not null check (length(decision_id) between 1 and 80),
  question text not null default '' check (length(question) <= 400),
  answer text not null default '' check (length(answer) <= 500),
  priority text not null default 'high_impact' check (priority in ('blocking','high_impact','optional')),
  impact text not null default 'high' check (impact in ('critical','high','medium','low')),
  decided_by text not null default 'creator' check (decided_by in ('creator','tonde')),
  decision_source text not null default 'intake' check (decision_source in ('intake','studio','correction','tonde_default')),
  is_correction boolean not null default false,
  source_operation_id uuid,
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (production_id, decision_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);

create index if not exists director_decisions_production on tonde.director_decisions(workspace_id, production_id, priority);


-- Reference capability, staged progress and analysis output.
create table if not exists tonde.reference_analyses (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  reference_id uuid not null,
  role text not null default 'style' check (role in ('camera','lighting','pacing','character','product','color','edit','sound','style','story','composition','environment')),
  capability text not null default 'metadata_only'
    check (capability in ('full_media_available','partial_media_available','metadata_only','text_only','unavailable')),
  status text not null default 'not_started'
    check (status in ('not_started','queued','preprocessing','analyzing','synthesizing','complete','partial','failed')),
  stages text[] not null default '{}',
  progress integer not null default 0 check (progress between 0 and 100),
  summary text not null default '' check (length(summary) <= 1600),
  capabilities jsonb not null default '{}' check (jsonb_typeof(capabilities) = 'object'),
  style jsonb not null default '{}' check (jsonb_typeof(style) = 'object'),
  causal jsonb not null default '[]' check (jsonb_typeof(causal) = 'array'),
  adaptation_notes jsonb not null default '[]' check (jsonb_typeof(adaptation_notes) = 'array'),
  limitations jsonb not null default '[]' check (jsonb_typeof(limitations) = 'array'),
  media_metadata jsonb not null default '{}' check (jsonb_typeof(media_metadata) = 'object'),
  producer text not null default 'deterministic' check (producer in ('deterministic','model')),
  model_profile text not null default 'default' check (length(model_profile) <= 120),
  producer_note text not null default '' check (length(producer_note) <= 600),
  source_operation_id uuid,
  revision integer not null default 1 check (revision > 0),
  analyzed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, reference_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, reference_id) references tonde.production_references(workspace_id, id) on delete restrict
);

create index if not exists reference_analyses_status on tonde.reference_analyses(workspace_id, production_id, status);


create table if not exists tonde.reference_findings (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  analysis_id uuid not null,
  finding_id text not null check (length(finding_id) between 1 and 120),
  category text not null check (category in ('camera','composition','lighting','blocking','performance','product','edit','transition','sound','color','story','typography','text','music','dialogue','voice','pacing','environment')),
  statement text not null check (length(statement) between 1 and 1200),
  epistemic text not null check (epistemic in ('observed','estimated','recommended','unknown')),
  confidence text not null check (confidence in ('high','medium','low')),
  evidence jsonb not null default '[]' check (jsonb_typeof(evidence) = 'array' and jsonb_array_length(evidence) <= 8),
  technique_id text check (technique_id is null or length(technique_id) <= 120),
  limitations jsonb not null default '[]' check (jsonb_typeof(limitations) = 'array'),
  sort_order bigint not null default 1024 check (sort_order >= 0),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (analysis_id, finding_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, analysis_id) references tonde.reference_analyses(workspace_id, id) on delete restrict,
  constraint observed_findings_cite_evidence check (epistemic <> 'observed' or jsonb_array_length(evidence) > 0 or category = 'story')
);

create index if not exists reference_findings_analysis on tonde.reference_findings(workspace_id, analysis_id, sort_order);


-- Reusable technique catalogue: workspace-scoped, never a copy of one reference.
create table if not exists tonde.creative_techniques (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  canonical_id text not null check (canonical_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(canonical_id) between 3 and 120),
  name text not null check (length(name) between 1 and 160),
  category text not null check (category in ('camera','composition','lighting','blocking','performance','product','edit','transition','sound','color','story','typography')),
  description text not null check (length(description) between 1 and 1200),
  purpose text not null check (length(purpose) between 1 and 600),
  effect text not null check (length(effect) between 1 and 600),
  conditions jsonb not null default '[]' check (jsonb_typeof(conditions) = 'array'),
  practical_concept text not null default '' check (length(practical_concept) <= 900),
  ai_concept text not null default '' check (length(ai_concept) <= 900),
  limitations jsonb not null default '[]' check (jsonb_typeof(limitations) = 'array'),
  importance text not null default 'supporting' check (importance in ('essential','supporting','optional')),
  confidence text not null default 'medium' check (confidence in ('high','medium','low')),
  technique_source text not null default 'reference' check (technique_source in ('reference','creator','story','style')),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, canonical_id)
);

create index if not exists creative_techniques_category on tonde.creative_techniques(workspace_id, category, importance);


create table if not exists tonde.reference_technique_links (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  analysis_id uuid not null,
  technique_id uuid not null,
  reference_id uuid not null,
  importance text not null default 'supporting' check (importance in ('essential','supporting','optional')),
  evidence jsonb not null default '[]' check (jsonb_typeof(evidence) = 'array' and jsonb_array_length(evidence) <= 8),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (analysis_id, technique_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, analysis_id) references tonde.reference_analyses(workspace_id, id) on delete restrict,
  foreign key (workspace_id, technique_id) references tonde.creative_techniques(workspace_id, id) on delete restrict,
  foreign key (workspace_id, reference_id) references tonde.production_references(workspace_id, id) on delete restrict
);


-- The selected Story for a Production. Alternatives never overwrite it.
create table if not exists tonde.creative_stories (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  story jsonb not null check (jsonb_typeof(story) = 'object' and pg_column_size(story) <= 200000),
  variation text not null default 'original' check (length(variation) <= 60),
  producer text not null default 'deterministic' check (producer in ('deterministic','model')),
  source_operation_id uuid,
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, production_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);


-- Reality Check result against the creator's real Setup.
create table if not exists tonde.director_reality_checks (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  report jsonb not null check (jsonb_typeof(report) = 'object' and pg_column_size(report) <= 200000),
  feasibility text not null default 'ready' check (feasibility in ('ready','adapt','blocked')),
  complexity text not null default 'simple' check (complexity in ('simple','moderate','complex')),
  recommended_mode text not null default 'real' check (recommended_mode in ('real','ai','hybrid')),
  source_operation_id uuid,
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, production_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);


-- RLS: clients read their own workspace rows; every write goes through a guarded RPC.
alter table tonde.director_operations enable row level security;

alter table tonde.director_briefs enable row level security;

alter table tonde.director_decisions enable row level security;

alter table tonde.reference_analyses enable row level security;

alter table tonde.reference_findings enable row level security;

alter table tonde.creative_techniques enable row level security;

alter table tonde.reference_technique_links enable row level security;

alter table tonde.creative_stories enable row level security;

alter table tonde.director_reality_checks enable row level security;


do $$ declare table_name text; begin
  foreach table_name in array array['director_operations','director_briefs','director_decisions','reference_analyses',
    'reference_findings','creative_techniques','reference_technique_links','creative_stories','director_reality_checks'] loop
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = table_name and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', table_name);
    end if;
    execute format('grant select on tonde.%I to authenticated', table_name);
    execute format('drop trigger if exists guard_mutation on tonde.%I', table_name);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', table_name);
  end loop;
end $$;


-- One authorization gate for every Director write path.
create or replace function tonde_private.director_guard(target_workspace uuid) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null or (select auth.role()) <> 'authenticated' or not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Authenticated workspace editor required' using errcode = '42501';
  end if;
end;
$$;


-- 1. AI operation ledger: idempotent claim and completion of one Director operation.
create or replace function tonde.record_director_operation(
  target_workspace uuid, target_production uuid, operation_record jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare existing tonde.director_operations; saved tonde.director_operations;
  desired_status text;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(operation_record) <> 'object' or pg_column_size(operation_record) > 500000
    or coalesce(length(operation_record->>'operation_id'), 0) <> 36
    or coalesce(length(btrim(operation_record->>'operation_type')), 0) = 0
    or coalesce(length(btrim(operation_record->>'idempotency_key')), 0) = 0 then
    raise exception 'Invalid Director operation record' using errcode = '22023';
  end if;
  if not exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production) then
    raise exception 'Production unavailable' using errcode = 'P0002';
  end if;
  desired_status := coalesce(operation_record->>'status', 'queued');
  if desired_status not in ('queued','preprocessing','analyzing','synthesizing','succeeded','partial','failed','cancelled') then
    raise exception 'Unsupported operation status' using errcode = '22023';
  end if;
  select * into existing from tonde.director_operations
    where workspace_id = target_workspace and operation_id = (operation_record->>'operation_id')::uuid for update;
  if found then
    if existing.idempotency_key <> operation_record->>'idempotency_key' then
      raise exception 'An operation id cannot be reused with a different idempotency key' using errcode = '23505';
    end if;
    if existing.status in ('succeeded','partial') and existing.payload_hash is not null
      and operation_record->>'payload_hash' is not null and existing.payload_hash <> operation_record->>'payload_hash' then
      raise exception 'A completed operation cannot be rewritten with different content' using errcode = '23505';
    end if;
    update tonde.director_operations set status = desired_status,
      producer = coalesce(operation_record->>'producer', producer),
      provider = coalesce(operation_record->>'provider', provider),
      model = coalesce(operation_record->>'model', model),
      model_profile = coalesce(operation_record->>'model_profile', model_profile),
      attempts = coalesce((operation_record->>'attempts')::integer, attempts),
      repaired = coalesce((operation_record->>'repaired')::boolean, repaired),
      rationale = coalesce(operation_record->>'rationale', rationale),
      limitations = coalesce(operation_record->'limitations', limitations),
      payload = coalesce(operation_record->'payload', payload),
      payload_hash = coalesce(operation_record->>'payload_hash', payload_hash),
      error_code = coalesce(operation_record->>'error_code', error_code),
      error_message = coalesce(operation_record->>'error_message', error_message),
      completed_at = case when desired_status in ('succeeded','partial','failed','cancelled') then now() else completed_at end
      where id = existing.id returning * into saved;
    return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
      'revision', saved.revision, 'idempotent', true);
  end if;
  insert into tonde.director_operations(workspace_id, production_id, operation_id, operation_type, scope, schema_version,
    source_revision, source_intake_revision, status, producer, provider, model, model_profile, attempts, repaired,
    idempotency_key, collaboration_mode, reference_ids, constraint_summary, rationale, limitations, payload, payload_hash,
    error_code, error_message, started_at, completed_at, created_by)
  values (target_workspace, target_production, (operation_record->>'operation_id')::uuid, operation_record->>'operation_type',
    coalesce(operation_record->>'scope', 'production'), coalesce(operation_record->>'schema_version', 'tonde.director.1'),
    (operation_record->>'source_revision')::integer, nullif(operation_record->>'source_intake_revision','')::integer,
    desired_status, coalesce(operation_record->>'producer', 'deterministic'), operation_record->>'provider', operation_record->>'model',
    coalesce(operation_record->>'model_profile', 'default'), coalesce((operation_record->>'attempts')::integer, 0),
    coalesce((operation_record->>'repaired')::boolean, false), operation_record->>'idempotency_key',
    coalesce(operation_record->>'collaboration_mode', 'stop_at_major_decisions'),
    coalesce((select array_agg(value::uuid) from jsonb_array_elements_text(coalesce(operation_record->'reference_ids','[]'::jsonb)) as value), '{}'),
    coalesce(operation_record->'constraint_summary','{}'::jsonb), coalesce(operation_record->>'rationale',''),
    coalesce(operation_record->'limitations','[]'::jsonb), coalesce(operation_record->'payload','{}'::jsonb),
    operation_record->>'payload_hash', operation_record->>'error_code', operation_record->>'error_message',
    now(), case when desired_status in ('succeeded','partial','failed','cancelled') then now() else null end, auth.uid())
  returning * into saved;
  return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
    'revision', saved.revision, 'idempotent', false);
end;
$$;


-- 2. Structured Brief version with optimistic revision.
create or replace function tonde.save_director_brief(
  target_workspace uuid, target_production uuid, expected_brief_revision integer, brief_content jsonb,
  source_operation uuid default null, producer_kind text default 'deterministic'
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare existing tonde.director_briefs; saved tonde.director_briefs; production_row tonde.productions;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(brief_content) <> 'object' or pg_column_size(brief_content) > 200000
    or coalesce(length(btrim(brief_content->>'production_goal')), 0) = 0 or length(brief_content->>'production_goal') > 10000 then
    raise exception 'Invalid structured Brief' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(brief_content->'assumptions','[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(brief_content->'open_decisions','[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(brief_content->'conflicts','[]'::jsonb)) <> 'array'
    or jsonb_typeof(coalesce(brief_content->'runtime','{}'::jsonb)) <> 'object' then
    raise exception 'Invalid Brief structure' using errcode = '22023';
  end if;
  if producer_kind not in ('deterministic','model') then
    raise exception 'Unsupported Brief producer' using errcode = '22023';
  end if;
  select * into production_row from tonde.productions where workspace_id = target_workspace and id = target_production for update;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if production_row.locked_at is not null or production_row.approval <> 'draft' then
    raise exception 'This Production is protected; unlock a draft revision before editing the Brief' using errcode = '55000';
  end if;
  select * into existing from tonde.director_briefs where workspace_id = target_workspace and production_id = target_production for update;
  if found then
    if expected_brief_revision is null or existing.revision <> expected_brief_revision then
      raise exception 'The Brief changed; reload before saving' using errcode = '40001';
    end if;
    update tonde.director_briefs set brief = brief_content, producer = producer_kind,
      source_operation_id = coalesce(source_operation, source_operation_id)
      where id = existing.id returning * into saved;
  else
    if expected_brief_revision is not null then
      raise exception 'The Brief changed; reload before saving' using errcode = '40001';
    end if;
    insert into tonde.director_briefs(workspace_id, production_id, brief, producer, source_operation_id)
      values(target_workspace, target_production, brief_content, producer_kind, source_operation) returning * into saved;
  end if;
  return jsonb_build_object('id', saved.id, 'revision', saved.revision, 'producer', saved.producer);
end;
$$;


-- 3. Decision ledger: settled decisions are recorded once and re-used, never re-asked.
create or replace function tonde.record_director_decisions(
  target_workspace uuid, target_production uuid, decision_list jsonb, decision_source text default 'studio'
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare item jsonb; stored integer := 0;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(decision_list) <> 'array' or jsonb_array_length(decision_list) > 40 then
    raise exception 'Invalid decision list' using errcode = '22023';
  end if;
  if decision_source not in ('intake','studio','correction','tonde_default') then
    raise exception 'Unsupported decision source' using errcode = '22023';
  end if;
  if not exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production) then
    raise exception 'Production unavailable' using errcode = 'P0002';
  end if;
  for item in select value from jsonb_array_elements(decision_list) loop
    if jsonb_typeof(item) <> 'object' or coalesce(length(btrim(item->>'decision_id')), 0) = 0
      or length(item->>'decision_id') > 80 or length(coalesce(item->>'answer','')) > 500 then
      raise exception 'Invalid decision' using errcode = '22023';
    end if;
    insert into tonde.director_decisions as d (workspace_id, production_id, decision_id, question, answer, priority, impact, decided_by, decision_source, is_correction)
      values (target_workspace, target_production, item->>'decision_id', coalesce(item->>'question',''), coalesce(item->>'answer',''),
        coalesce(item->>'priority','high_impact'), coalesce(item->>'impact','high'),
        case when item->>'answer' = 'TONDE decides' then 'tonde' else coalesce(item->>'decided_by','creator') end,
        decision_source, coalesce((item->>'is_correction')::boolean, false))
      on conflict (production_id, decision_id) do update set
        answer = excluded.answer,
        question = case when excluded.question = '' then d.question else excluded.question end,
        priority = excluded.priority,
        impact = excluded.impact,
        decided_by = excluded.decided_by,
        decision_source = excluded.decision_source,
        is_correction = excluded.is_correction or d.is_correction;
    stored := stored + 1;
  end loop;
  return jsonb_build_object('stored', stored, 'decision_source', decision_source);
end;
$$;


revoke all on function tonde_private.director_guard(uuid) from public, anon, authenticated;

revoke all on function tonde.record_director_operation(uuid,uuid,jsonb),
  tonde.save_director_brief(uuid,uuid,integer,jsonb,uuid,text),
  tonde.record_director_decisions(uuid,uuid,jsonb,text) from public, anon, authenticated, service_role;

grant execute on function tonde.record_director_operation(uuid,uuid,jsonb),
  tonde.save_director_brief(uuid,uuid,integer,jsonb,uuid,text),
  tonde.record_director_decisions(uuid,uuid,jsonb,text) to authenticated;

commit;

-- ==========================================================================
-- 202610050013_director_reference_and_apply.sql
-- ==========================================================================

-- Additive migration: Prompt 4 reference analysis persistence and atomic creative apply.
begin;


-- 4. Reference analysis: capability, staged status, findings and technique links.
create or replace function tonde.save_reference_analysis(
  target_workspace uuid, target_production uuid, target_reference uuid, analysis jsonb,
  findings jsonb, techniques jsonb, source_operation uuid default null
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare reference_row tonde.production_references;
  saved tonde.reference_analyses;
  item jsonb;
  linked_technique_id uuid;
  technique_count integer := 0;
  finding_count integer := 0;
  desired_capability text := coalesce(analysis->>'capability', 'metadata_only');
  desired_status text := coalesce(analysis->>'status', 'not_started');
  desired_progress integer;
  reference_state text;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(analysis) <> 'object' or jsonb_typeof(findings) <> 'array' or jsonb_typeof(techniques) <> 'array'
    or jsonb_array_length(findings) > 80 or jsonb_array_length(techniques) > 40 then
    raise exception 'Invalid reference analysis payload' using errcode = '22023';
  end if;
  if desired_capability not in ('full_media_available','partial_media_available','metadata_only','text_only','unavailable')
    or desired_status not in ('not_started','queued','preprocessing','analyzing','synthesizing','complete','partial','failed') then
    raise exception 'Unsupported reference capability or analysis state' using errcode = '22023';
  end if;
  select * into reference_row from tonde.production_references
    where workspace_id = target_workspace and production_id = target_production and id = target_reference for update;
  if not found then raise exception 'Reference unavailable in this Production' using errcode = 'P0002'; end if;
  desired_progress := greatest(0, least(100, coalesce((analysis->>'progress')::integer, case when desired_status = 'complete' then 100 else 0 end)));
  -- An observed finding must cite evidence, exactly as the domain model requires.
  for item in select value from jsonb_array_elements(findings) loop
    if jsonb_typeof(item) <> 'object' or coalesce(length(btrim(item->>'statement')), 0) = 0 or length(item->>'statement') > 1200
      or coalesce(item->>'epistemic','') not in ('observed','estimated','recommended','unknown')
      or coalesce(item->>'confidence','') not in ('high','medium','low')
      or jsonb_typeof(coalesce(item->'evidence','[]'::jsonb)) <> 'array' then
      raise exception 'Invalid reference finding' using errcode = '22023';
    end if;
    if item->>'epistemic' = 'observed' and jsonb_array_length(coalesce(item->'evidence','[]'::jsonb)) = 0
      and item->>'category' <> 'story' then
      raise exception 'An observed finding must cite evidence' using errcode = '23514';
    end if;
  end loop;
  insert into tonde.reference_analyses as ra (workspace_id, production_id, reference_id, role, capability, status, stages,
    progress, summary, capabilities, style, causal, adaptation_notes, limitations, media_metadata, producer, model_profile,
    producer_note, source_operation_id, analyzed_at)
  values (target_workspace, target_production, target_reference,
    coalesce(analysis->>'role','style'), desired_capability, desired_status,
    coalesce((select array_agg(value) from jsonb_array_elements_text(coalesce(analysis->'stages','[]'::jsonb)) as value), '{}'),
    desired_progress, left(coalesce(analysis->>'summary',''),1600),
    coalesce(analysis->'capabilities','{}'::jsonb), coalesce(analysis->'style','{}'::jsonb),
    coalesce(analysis->'causal','[]'::jsonb), coalesce(analysis->'adaptation_notes','[]'::jsonb),
    coalesce(analysis->'limitations','[]'::jsonb), coalesce(analysis->'media_metadata','{}'::jsonb),
    coalesce(analysis->>'producer','deterministic'), coalesce(analysis->>'model_profile','default'),
    left(coalesce(analysis->>'producer_note',''),600), source_operation,
    case when desired_status in ('complete','partial','failed') then now() else null end)
  on conflict (workspace_id, reference_id) do update set
    role = excluded.role, capability = excluded.capability, status = excluded.status, stages = excluded.stages,
    progress = excluded.progress, summary = excluded.summary, capabilities = excluded.capabilities, style = excluded.style,
    causal = excluded.causal, adaptation_notes = excluded.adaptation_notes, limitations = excluded.limitations,
    media_metadata = excluded.media_metadata, producer = excluded.producer, model_profile = excluded.model_profile,
    producer_note = excluded.producer_note, source_operation_id = coalesce(excluded.source_operation_id, ra.source_operation_id),
    analyzed_at = coalesce(excluded.analyzed_at, ra.analyzed_at)
  returning * into saved;
  delete from tonde.reference_findings where workspace_id = target_workspace and analysis_id = saved.id;
  for item in select value from jsonb_array_elements(findings) loop
    finding_count := finding_count + 1;
    insert into tonde.reference_findings(workspace_id, production_id, analysis_id, finding_id, category, statement,
      epistemic, confidence, evidence, technique_id, limitations, sort_order)
    values (target_workspace, target_production, saved.id, left(item->>'finding_id',120),
      coalesce(item->>'category','story'), left(item->>'statement',1200), item->>'epistemic', item->>'confidence',
      coalesce(item->'evidence','[]'::jsonb), nullif(left(coalesce(item->>'technique_id',''),120),''),
      coalesce(item->'limitations','[]'::jsonb), finding_count * 1024);
  end loop;
  delete from tonde.reference_technique_links where workspace_id = target_workspace and analysis_id = saved.id;
  for item in select value from jsonb_array_elements(techniques) loop
    if jsonb_typeof(item) <> 'object' or coalesce(length(btrim(item->>'canonical_id')),0) < 3
      or coalesce(length(btrim(item->>'name')),0) = 0 or coalesce(length(btrim(item->>'description')),0) = 0
      or coalesce(length(btrim(item->>'purpose')),0) = 0 or coalesce(length(btrim(item->>'effect')),0) = 0
      or coalesce(item->>'category','') not in ('camera','composition','lighting','blocking','performance','product','edit','transition','sound','color','story','typography') then
      raise exception 'Invalid technique payload' using errcode = '22023';
    end if;
    insert into tonde.creative_techniques as ct (workspace_id, canonical_id, name, category, description, purpose, effect,
      conditions, practical_concept, ai_concept, limitations, importance, confidence, technique_source, created_by)
    values (target_workspace, left(item->>'canonical_id',120), left(item->>'name',160), item->>'category',
      left(item->>'description',1200), left(item->>'purpose',600), left(item->>'effect',600),
      coalesce(item->'conditions','[]'::jsonb), left(coalesce(item->>'practical_concept',''),900),
      left(coalesce(item->>'ai_concept',''),900), coalesce(item->'limitations','[]'::jsonb),
      coalesce(item->>'importance','supporting'), coalesce(item->>'confidence','medium'),
      coalesce(item->>'technique_source','reference'), auth.uid())
    on conflict (workspace_id, canonical_id) do update set
      name = excluded.name, category = excluded.category, description = excluded.description, purpose = excluded.purpose,
      effect = excluded.effect, conditions = excluded.conditions, practical_concept = excluded.practical_concept,
      ai_concept = excluded.ai_concept, limitations = excluded.limitations, importance = excluded.importance,
      confidence = excluded.confidence
    returning id into linked_technique_id;
    technique_count := technique_count + 1;
    insert into tonde.reference_technique_links(workspace_id, production_id, analysis_id, technique_id, reference_id, importance, evidence)
      values (target_workspace, target_production, saved.id, linked_technique_id, target_reference,
        coalesce(item->>'importance','supporting'), coalesce(item->'evidence','[]'::jsonb))
      on conflict (analysis_id, technique_id) do update set importance = excluded.importance, evidence = excluded.evidence;
  end loop;
  reference_state := case desired_status
    when 'complete' then 'analyzed'
    when 'partial' then 'partially_analyzed'
    when 'failed' then 'failed'
    when 'unavailable' then 'inaccessible'
    else 'processing' end;
  if desired_status = 'complete' and desired_capability <> 'full_media_available' then
    reference_state := 'partially_analyzed';
  end if;
  update tonde.production_references set state = reference_state::tonde.reference_state where id = target_reference and workspace_id = target_workspace;
  return jsonb_build_object('analysis_id', saved.id, 'revision', saved.revision, 'status', saved.status,
    'capability', saved.capability, 'findings', finding_count, 'techniques', technique_count, 'reference_state', reference_state);
end;
$$;


-- 5. Staged progress for long media work without touching finished findings.
create or replace function tonde.claim_reference_analysis(
  target_workspace uuid, target_production uuid, target_reference uuid, stage_status text,
  stage_list text[] default '{}', progress_pct integer default 0, producer_note text default ''
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare saved tonde.reference_analyses; reference_state text;
begin
  perform tonde_private.director_guard(target_workspace);
  if stage_status not in ('queued','preprocessing','analyzing','synthesizing','partial','failed','cancelled') then
    raise exception 'Unsupported analysis stage status' using errcode = '22023';
  end if;
  if not exists(select 1 from tonde.production_references r where r.workspace_id = target_workspace
    and r.production_id = target_production and r.id = target_reference) then
    raise exception 'Reference unavailable in this Production' using errcode = 'P0002';
  end if;
  insert into tonde.reference_analyses as ra (workspace_id, production_id, reference_id, status, stages, progress, producer_note)
  values (target_workspace, target_production, target_reference, stage_status, coalesce(stage_list, '{}'),
    greatest(0, least(100, coalesce(progress_pct, 0))), left(coalesce(producer_note,''),600))
  on conflict (workspace_id, reference_id) do update set
    status = excluded.status, stages = excluded.stages, progress = excluded.progress,
    producer_note = case when excluded.producer_note = '' then ra.producer_note else excluded.producer_note end
  returning * into saved;
  reference_state := case stage_status when 'failed' then 'failed' when 'partial' then 'partially_analyzed' else 'processing' end;
  update tonde.production_references set state = reference_state::tonde.reference_state where id = target_reference and workspace_id = target_workspace;
  return jsonb_build_object('analysis_id', saved.id, 'status', saved.status, 'progress', saved.progress, 'stages', saved.stages);
end;
$$;


-- Creative domain content becomes canonical Assets and scope bindings, never a second entity model.
create or replace function tonde_private.director_apply_assets(
  target_workspace uuid, target_production uuid, operation_id uuid, bundle jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
-- The block is labelled so the asset_id variable can be qualified against the
-- asset_id column of scope_bindings inside the existence checks below.
<<assets>>
declare item jsonb; asset_id uuid; binding text; asset_kind tonde.asset_type;
  environment_ids jsonb := '{}'::jsonb;
  character_ids jsonb := '{}'::jsonb;
  scene_row record; character_name text; environment_name text;
  characters integer := 0; environments integer := 0; products integer := 0; wardrobe integer := 0;
begin
  for item in select value from jsonb_array_elements(coalesce(bundle->'characters','[]'::jsonb)) loop
    characters := characters + 1;
    select id into asset_id from tonde.assets where workspace_id = target_workspace and asset_type = 'character'
      and name = left(item->>'name',160) and lifecycle = 'active' limit 1;
    if asset_id is null then
      insert into tonde.assets(workspace_id, asset_type, name, description, metadata, provenance, created_by)
      values (target_workspace, 'character', left(item->>'name',160), left(coalesce(item->>'story_function',''),10000),
        jsonb_build_object('role', item->>'role', 'story_function', item->>'story_function', 'objective', item->>'objective',
          'visual_description', item->>'visual_description', 'performance_direction', item->>'performance_direction',
          'relationships', coalesce(item->'relationships','[]'::jsonb), 'recurring', coalesce((item->>'recurring')::boolean, false)),
        jsonb_build_object('source','director','operation_id', operation_id::text), auth.uid())
      returning id into asset_id;
    else
      update tonde.assets set metadata = jsonb_build_object('role', item->>'role', 'story_function', item->>'story_function',
          'objective', item->>'objective', 'visual_description', item->>'visual_description',
          'performance_direction', item->>'performance_direction', 'relationships', coalesce(item->'relationships','[]'::jsonb),
          'recurring', coalesce((item->>'recurring')::boolean, false)),
        provenance = provenance || jsonb_build_object('last_operation_id', operation_id::text)
        where id = asset_id;
    end if;
    character_ids := character_ids || jsonb_build_object(lower(left(item->>'name',160)), asset_id::text);
    if not exists(select 1 from tonde.scope_bindings b where b.scope_object_id = target_production and b.binding_role = 'character' and b.asset_id = assets.asset_id) then
      insert into tonde.scope_bindings(workspace_id, production_id, scope_object_id, asset_id, binding_role, inheritance)
        values (target_workspace, target_production, target_production, asset_id, 'character', 'inherit');
    end if;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(bundle->'environments','[]'::jsonb)) loop
    environments := environments + 1;
    select id into asset_id from tonde.assets where workspace_id = target_workspace and asset_type = 'environment'
      and name = left(item->>'name',160) and lifecycle = 'active' limit 1;
    if asset_id is null then
      insert into tonde.assets(workspace_id, asset_type, name, description, metadata, provenance, created_by)
      values (target_workspace, 'environment', left(item->>'name',160), left(coalesce(item->>'story_purpose',''),10000),
        jsonb_build_object('visual_requirements', coalesce(item->'visual_requirements','[]'::jsonb),
          'story_purpose', item->>'story_purpose', 'spatial_needs', coalesce(item->'spatial_needs','[]'::jsonb),
          'lighting_context', item->>'lighting_context', 'scene_usage', coalesce(item->'scene_usage','[]'::jsonb)),
        jsonb_build_object('source','director','operation_id', operation_id::text), auth.uid())
      returning id into asset_id;
    else
      update tonde.assets set metadata = jsonb_build_object('visual_requirements', coalesce(item->'visual_requirements','[]'::jsonb),
          'story_purpose', item->>'story_purpose', 'spatial_needs', coalesce(item->'spatial_needs','[]'::jsonb),
          'lighting_context', item->>'lighting_context', 'scene_usage', coalesce(item->'scene_usage','[]'::jsonb)),
        provenance = provenance || jsonb_build_object('last_operation_id', operation_id::text)
        where id = asset_id;
    end if;
    environment_ids := environment_ids || jsonb_build_object(lower(left(item->>'name',160)), asset_id::text);
    if not exists(select 1 from tonde.scope_bindings b where b.scope_object_id = target_production and b.binding_role = 'world' and b.asset_id = assets.asset_id) then
      insert into tonde.scope_bindings(workspace_id, production_id, scope_object_id, asset_id, binding_role, inheritance)
        values (target_workspace, target_production, target_production, asset_id, 'world', 'inherit');
    end if;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(bundle->'products','[]'::jsonb)) loop
    products := products + 1;
    select id into asset_id from tonde.assets where workspace_id = target_workspace and asset_type = 'product'
      and name = left(item->>'name',160) and lifecycle = 'active' limit 1;
    if asset_id is null then
      insert into tonde.assets(workspace_id, asset_type, name, description, metadata, provenance, created_by)
      values (target_workspace, 'product', left(item->>'name',160), left(coalesce(item->>'role',''),10000),
        jsonb_build_object('role', item->>'role', 'required_visibility', item->>'required_visibility',
          'hero_moments', coalesce(item->'hero_moments','[]'::jsonb), 'fidelity_importance', item->>'fidelity_importance',
          'interactions', coalesce(item->'interactions','[]'::jsonb), 'packaging_notes', coalesce(item->'packaging_notes','[]'::jsonb)),
        jsonb_build_object('source','director','operation_id', operation_id::text), auth.uid())
      returning id into asset_id;
    else
      update tonde.assets set metadata = jsonb_build_object('role', item->>'role', 'required_visibility', item->>'required_visibility',
          'hero_moments', coalesce(item->'hero_moments','[]'::jsonb), 'fidelity_importance', item->>'fidelity_importance',
          'interactions', coalesce(item->'interactions','[]'::jsonb), 'packaging_notes', coalesce(item->'packaging_notes','[]'::jsonb)),
        provenance = provenance || jsonb_build_object('last_operation_id', operation_id::text)
        where id = asset_id;
    end if;
    if not exists(select 1 from tonde.scope_bindings b where b.scope_object_id = target_production and b.binding_role = 'product' and b.asset_id = assets.asset_id) then
      insert into tonde.scope_bindings(workspace_id, production_id, scope_object_id, asset_id, binding_role, inheritance)
        values (target_workspace, target_production, target_production, asset_id, 'product', 'inherit');
    end if;
  end loop;
  for item in select value from jsonb_array_elements(coalesce(bundle->'wardrobe_props','[]'::jsonb)) loop
    wardrobe := wardrobe + 1;
    asset_kind := case when item->>'kind' = 'wardrobe' then 'wardrobe' else 'prop' end;
    binding := case when item->>'kind' = 'wardrobe' then 'wardrobe' else 'prop' end;
    select id into asset_id from tonde.assets where workspace_id = target_workspace and asset_type = asset_kind
      and name = left(item->>'name',160) and lifecycle = 'active' limit 1;
    if asset_id is null then
      insert into tonde.assets(workspace_id, asset_type, name, description, metadata, provenance, created_by)
      values (target_workspace, asset_kind, left(item->>'name',160), left(coalesce(item->>'requirement',''),10000),
        jsonb_build_object('requirement', item->>'requirement', 'scene_usage', coalesce(item->'scene_usage','[]'::jsonb),
          'content_source', coalesce(item->>'source','derived')),
        jsonb_build_object('source','director','operation_id', operation_id::text), auth.uid())
      returning id into asset_id;
    else
      update tonde.assets set metadata = jsonb_build_object('requirement', item->>'requirement',
          'scene_usage', coalesce(item->'scene_usage','[]'::jsonb), 'content_source', coalesce(item->>'source','derived')),
        provenance = provenance || jsonb_build_object('last_operation_id', operation_id::text)
        where id = asset_id;
    end if;
    if not exists(select 1 from tonde.scope_bindings b where b.scope_object_id = target_production and b.binding_role = binding::tonde.binding_role and b.asset_id = assets.asset_id) then
      insert into tonde.scope_bindings(workspace_id, production_id, scope_object_id, asset_id, binding_role, inheritance)
        values (target_workspace, target_production, target_production, asset_id, binding::tonde.binding_role, 'inherit');
    end if;
  end loop;
  if jsonb_typeof(bundle->'style_bible') = 'object' and coalesce(length(btrim(bundle->'style_bible'->>'title')),0) > 0 then
    -- The Style Bible is deduplicated by name like every other creative Asset: re-applying a plan
    -- updates the existing Style record instead of accumulating a new one per operation.
    select id into asset_id from tonde.assets where workspace_id = target_workspace and asset_type = 'style_bible'
      and name = left(bundle->'style_bible'->>'title',160) and lifecycle = 'active' limit 1;
    if asset_id is null then
      insert into tonde.assets(workspace_id, asset_type, name, description, metadata, provenance, created_by)
      values (target_workspace, 'style_bible', left(bundle->'style_bible'->>'title',160),
        left(coalesce(bundle->'style_bible'->>'summary',''),10000),
        jsonb_build_object('sections', coalesce(bundle->'style_bible'->'sections','[]'::jsonb),
          'producer', coalesce(bundle->'style_bible'->>'producer','deterministic')),
        jsonb_build_object('source','director','operation_id', operation_id::text), auth.uid())
      returning id into asset_id;
    else
      update tonde.assets set description = left(coalesce(bundle->'style_bible'->>'summary',''),10000),
          metadata = jsonb_build_object('sections', coalesce(bundle->'style_bible'->'sections','[]'::jsonb),
            'producer', coalesce(bundle->'style_bible'->>'producer','deterministic')),
          provenance = provenance || jsonb_build_object('last_operation_id', operation_id::text)
        where id = asset_id;
    end if;
    if not exists(select 1 from tonde.scope_bindings b where b.scope_object_id = target_production and b.binding_role = 'style' and b.asset_id = assets.asset_id) then
      insert into tonde.scope_bindings(workspace_id, production_id, scope_object_id, asset_id, binding_role, inheritance)
        values (target_workspace, target_production, target_production, asset_id, 'style', 'inherit');
    end if;
  end if;
  -- Link Scenes to their creative Environment and register on-camera participants.
  for scene_row in select id, sort_order, scene_detail from tonde.scenes
    where workspace_id = target_workspace and production_id = target_production and lifecycle = 'active' loop
    environment_name := lower(coalesce(scene_row.scene_detail->>'environment',''));
    if environment_name <> '' and environment_ids ? environment_name then
      update tonde.scenes set environment_asset_id = (environment_ids->>environment_name)::uuid where id = scene_row.id;
    end if;
    for character_name in select value from jsonb_array_elements_text(coalesce(scene_row.scene_detail->'characters','[]'::jsonb)) loop
      if character_ids ? lower(character_name)
        and not exists(select 1 from tonde.scene_participants sp
          where sp.scene_id = scene_row.id and sp.asset_id = (character_ids->>lower(character_name))::uuid) then
        insert into tonde.scene_participants(workspace_id, production_id, scene_id, asset_id, role)
          values (target_workspace, target_production, scene_row.id, (character_ids->>lower(character_name))::uuid, 'participant');
      end if;
    end loop;
  end loop;
  return jsonb_build_object('characters', characters, 'environments', environments, 'products', products, 'wardrobe_props', wardrobe,
    'character_assets', character_ids, 'environment_assets', environment_ids);
end;
$$;


revoke all on function tonde_private.director_apply_assets(uuid,uuid,uuid,jsonb) from public, anon, authenticated;

revoke all on function tonde.save_reference_analysis(uuid,uuid,uuid,jsonb,jsonb,jsonb,uuid),
  tonde.claim_reference_analysis(uuid,uuid,uuid,text,text[],integer,text) from public, anon, authenticated, service_role;

grant execute on function tonde.save_reference_analysis(uuid,uuid,uuid,jsonb,jsonb,jsonb,uuid),
  tonde.claim_reference_analysis(uuid,uuid,uuid,text,text[],integer,text) to authenticated;

commit;

-- ==========================================================================
-- 202610050014_director_apply_operation.sql
-- ==========================================================================

-- Additive migration: the atomic Director apply path for one creative bundle.
begin;


-- The operation parameter is named target_operation so it can never be ambiguous with the
-- director_operations.operation_id column inside the upsert and its conflict target.
create or replace function tonde.apply_director_operation(
  target_workspace uuid, target_production uuid, expected_production_revision integer,
  target_operation uuid, operation_type text, bundle jsonb, explicit_confirmation boolean
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare production_row tonde.productions;
  existing tonde.director_operations;
  plan jsonb;
  brief jsonb;
  story jsonb;
  script jsonb;
  target_duration bigint;
  scene jsonb;
  scene_index integer := 0;
  scene_count integer := 0;
  scene_total bigint := 0;
  scene_duration bigint;
  scene_order bigint := 1024;
  scene_id uuid;
  scene_ids jsonb := '{}'::jsonb;
  scene_id_text text;
  assets_result jsonb;
  character_assets jsonb := '{}'::jsonb;
  document_row tonde.creative_documents;
  document_id uuid;
  script_scene jsonb;
  line jsonb;
  script_scene_index integer := 0;
  line_order bigint;
  dialogue_count integer := 0;
  speaker_id uuid;
  item jsonb;
  production_revision_out integer;
  bundle_hash text := md5(bundle::text);
  brief_content text;
  story_content text;
  script_content text;
  producer_kind text;
begin
  perform tonde_private.director_guard(target_workspace);
  if explicit_confirmation is not true then
    raise exception 'Creator confirmation is required to apply this Director operation' using errcode = '42501';
  end if;
  if operation_type not in ('apply_production_plan','director_command','story_generation','script_generation',
    'scene_generation','domain_content_generation','runtime_validation','reality_check') then
    raise exception 'Unsupported Director operation type' using errcode = '22023';
  end if;
  if jsonb_typeof(bundle) <> 'object' or pg_column_size(bundle) > 4000000 then
    raise exception 'Invalid Director operation bundle' using errcode = '22023';
  end if;
  plan := coalesce(bundle->'production','{}'::jsonb);
  brief := coalesce(bundle->'brief','{}'::jsonb);
  story := case when jsonb_typeof(bundle->'story') = 'object' then bundle->'story' else null end;
  script := case when jsonb_typeof(bundle->'script') = 'object' then bundle->'script' else null end;
  select * into production_row from tonde.productions
    where workspace_id = target_workspace and id = target_production for update;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  -- Idempotency first: a retried operation with identical content never duplicates content.
  select * into existing from tonde.director_operations
    where workspace_id = target_workspace and operation_id = target_operation for update;
  if found and existing.status in ('succeeded','partial') and existing.payload_hash is not null then
    if existing.payload_hash is distinct from bundle_hash then
      raise exception 'This operation id was already applied with different content' using errcode = '23505';
    end if;
    return jsonb_build_object('production_id', target_production, 'operation_id', target_operation, 'idempotent', true,
      'production_revision', production_row.revision, 'duplicate_applied', true);
  end if;
  if production_row.revision <> expected_production_revision then
    raise exception 'Production changed; reload before applying this operation' using errcode = '40001';
  end if;
  if production_row.locked_at is not null or production_row.approval <> 'draft' then
    raise exception 'Apply Director operations to an unlocked Draft Production' using errcode = '55000';
  end if;
  producer_kind := case when bundle->>'producer' = 'model' then 'model' else 'deterministic' end;
  if coalesce(length(btrim(plan->>'title')),0) = 0 or length(plan->>'title') > 160
    or coalesce(length(btrim(brief->>'production_goal')),0) = 0 or length(brief->>'production_goal') > 10000 then
    raise exception 'Invalid Director production plan' using errcode = '22023';
  end if;
  if not exists(select 1 from unnest(enum_range(null::tonde.production_type)) t where t::text = plan->>'production_type')
    or not exists(select 1 from unnest(enum_range(null::tonde.execution_method)) t where t::text = plan->>'execution_method') then
    raise exception 'Unsupported Production classification or execution method' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(bundle->'scenes','[]'::jsonb)) <> 'array' or jsonb_array_length(coalesce(bundle->'scenes','[]'::jsonb)) > 40 then
    raise exception 'Invalid Scene list' using errcode = '22023';
  end if;
  if plan->>'planned_duration_ms' is not null then
    if plan->>'planned_duration_ms' !~ '^[0-9]{1,16}$' then raise exception 'Runtime must use integer milliseconds' using errcode = '22023'; end if;
    target_duration := (plan->>'planned_duration_ms')::bigint;
    if target_duration > 9007199254740991 then raise exception 'Runtime exceeds the safe integer range' using errcode = '22023'; end if;
    if jsonb_array_length(coalesce(bundle->'scenes','[]'::jsonb)) = 0 then raise exception 'A timed Production needs at least one Scene' using errcode = '22023'; end if;
  else
    target_duration := null;
  end if;
  for scene in select value from jsonb_array_elements(coalesce(bundle->'scenes','[]'::jsonb)) loop
    scene_index := scene_index + 1;
    if jsonb_typeof(scene) <> 'object' or coalesce(length(btrim(scene->>'title')),0) = 0 or length(scene->>'title') > 160
      or length(coalesce(scene->>'purpose','')) > 1200 or length(coalesce(scene->>'story_beat','')) > 200
      or jsonb_typeof(coalesce(scene->'action_lines','[]'::jsonb)) <> 'array'
      or jsonb_array_length(coalesce(scene->'action_lines','[]'::jsonb)) > 16 then
      raise exception 'Invalid planned Scene' using errcode = '22023';
    end if;
    if target_duration is not null then
      if scene->>'duration_ms' is null or scene->>'duration_ms' !~ '^[0-9]{1,16}$' then
        raise exception 'Every timed Scene needs integer milliseconds' using errcode = '22023';
      end if;
      scene_duration := (scene->>'duration_ms')::bigint;
      if scene_duration > 9007199254740991 then raise exception 'Scene duration exceeds the safe integer range' using errcode = '22023'; end if;
      if scene_total > 9007199254740991 - scene_duration then raise exception 'Scene duration sum exceeds the safe integer range' using errcode = '22003'; end if;
      scene_total := scene_total + scene_duration;
    elsif scene->>'duration_ms' is not null then
      raise exception 'Scene durations require a Production runtime target' using errcode = '22023';
    end if;
  end loop;
  if target_duration is not null and scene_total <> target_duration then
    raise exception 'Scene durations must equal the Production target exactly' using errcode = '23514';
  end if;
  -- Prior Scenes are archived (never hard-deleted) and moved out of the live ordering range.
  update tonde.scenes s set lifecycle = 'archived',
    sort_order = (select coalesce(max(x.sort_order), 0) from tonde.scenes x
      where x.workspace_id = target_workspace and x.production_id = target_production) + 1000000 + s.sort_order
    where s.workspace_id = target_workspace and s.production_id = target_production and s.lifecycle = 'active';
  for scene in select value from jsonb_array_elements(coalesce(bundle->'scenes','[]'::jsonb)) loop
    scene_count := scene_count + 1;
    insert into tonde.scenes(workspace_id, production_id, title, purpose, description, story_beat, opening_state,
      ending_state, visual_intent, dialogue_notes, action_lines, scene_detail, sort_order, planned_duration_ms, source_operation_id)
    values (target_workspace, target_production, left(scene->>'title',160), left(coalesce(scene->>'purpose',''),1200),
      left(coalesce(scene->>'description',''),4000), left(coalesce(scene->>'story_beat',''),200),
      left(coalesce(scene->>'opening_state',''),400), left(coalesce(scene->>'ending_state',''),400),
      left(coalesce(scene->>'visual_intent',''),900), left(coalesce(scene->>'dialogue_notes',''),900),
      coalesce(scene->'action_lines','[]'::jsonb),
      jsonb_build_object('environment', coalesce(scene->>'environment',''), 'characters', coalesce(scene->'characters','[]'::jsonb),
        'products', coalesce(scene->'products','[]'::jsonb), 'techniques', coalesce(scene->'techniques','[]'::jsonb),
        'shots', coalesce(scene->'shots','[]'::jsonb), 'plan_order', scene_count),
      scene_order, case when target_duration is null then null else (scene->>'duration_ms')::bigint end, target_operation)
    returning id into scene_id;
    scene_ids := scene_ids || jsonb_build_object(coalesce(nullif(scene->>'order',''), scene_count::text), scene_id::text);
    scene_order := scene_order + 1024;
  end loop;
  assets_result := tonde_private.director_apply_assets(target_workspace, target_production, target_operation, bundle);
  character_assets := coalesce(assets_result->'character_assets','{}'::jsonb);
  -- Creative documents are the readable record of the same structured content.
  delete from tonde.dialogue_lines where workspace_id = target_workspace and production_id = target_production;
  delete from tonde.creative_documents where workspace_id = target_workspace and production_id = target_production
    and document_type in ('brief','story','script');
  brief_content := concat_ws(E'\n\n', 'PRODUCTION GOAL: ' || (brief->>'production_goal'),
    case when coalesce(brief->>'audience','') <> '' then 'AUDIENCE: ' || (brief->>'audience') end,
    case when coalesce(brief->>'core_message','') <> '' then 'CORE MESSAGE: ' || (brief->>'core_message') end,
    case when coalesce(brief->>'call_to_action','') <> '' then 'CALL TO ACTION: ' || (brief->>'call_to_action') end,
    case when coalesce(brief->>'story_approach','') <> '' then 'STORY APPROACH: ' || (brief->>'story_approach') end,
    case when coalesce(brief->>'dialogue_approach','') <> '' then 'DIALOGUE: ' || (brief->>'dialogue_approach') end,
    case when jsonb_typeof(brief->'hard_constraints') = 'array' and jsonb_array_length(brief->'hard_constraints') > 0
      then 'HARD CONSTRAINTS: ' || (select string_agg(value, '; ') from jsonb_array_elements_text(brief->'hard_constraints') as value) end,
    case when jsonb_typeof(brief->'assumptions') = 'array' and jsonb_array_length(brief->'assumptions') > 0
      then 'ASSUMPTIONS: ' || (select string_agg(value->>'statement', '; ') from jsonb_array_elements(brief->'assumptions') as value) end);
  insert into tonde.creative_documents(workspace_id, production_id, scope_object_id, document_type, title, content)
    values (target_workspace, target_production, target_production, 'brief', 'Production Brief', left(brief_content, 1000000));
  if story is not null then
    story_content := concat_ws(E'\n\n', 'LOGLINE: ' || coalesce(story->>'logline',''),
      case when coalesce(story->>'premise','') <> '' then 'PREMISE: ' || (story->>'premise') end,
      case when coalesce(story->>'central_question','') <> '' then 'CENTRAL QUESTION: ' || (story->>'central_question') end,
      case when jsonb_typeof(story->'beats') = 'array' then (select string_agg((value->>'order') || '. ' || (value->>'name') || E'\n' || (value->>'content'), E'\n\n')
        from jsonb_array_elements(story->'beats') as value) end,
      case when coalesce(story->>'call_to_action','') <> '' then 'CTA: ' || (story->>'call_to_action') end);
    insert into tonde.creative_documents(workspace_id, production_id, scope_object_id, document_type, title, content)
      values (target_workspace, target_production, target_production, 'story', left(coalesce(story->>'title','Story'),160), left(story_content, 1000000));
    insert into tonde.creative_stories as cs (workspace_id, production_id, story, variation, producer, source_operation_id)
      values (target_workspace, target_production, story, left(coalesce(story->>'variation','original'),60), producer_kind, target_operation)
      on conflict (workspace_id, production_id) do update set story = excluded.story, variation = excluded.variation,
        producer = excluded.producer, source_operation_id = excluded.source_operation_id;
  end if;
  if script is not null then
    script_content := coalesce(script->>'title','Script') || E'\n\n' ||
      coalesce((select string_agg(
        (value->>'heading') || E'\n\n' ||
        coalesce((select string_agg(action, E'\n') from jsonb_array_elements_text(coalesce(value->'action','[]'::jsonb)) as action), '') ||
        E'\n\n' ||
        coalesce((select string_agg(
          case when coalesce(script_line->>'speaker','') = '' then '' else upper(script_line->>'speaker') || E'\n' end ||
          case when coalesce(script_line->>'kind','') = 'dialogue' then '  ' || coalesce(script_line->>'content','')
            else '[' || upper(coalesce(script_line->>'kind','dialogue')) || '] ' || coalesce(script_line->>'content','') end,
          E'\n') from jsonb_array_elements(coalesce(value->'lines','[]'::jsonb)) as script_line), '') ||
        E'\n\n' ||
        case when coalesce(value->>'transition','') = '' then '' else '>> ' || (value->>'transition') end,
        E'\n\n') from jsonb_array_elements(coalesce(script->'scenes','[]'::jsonb)) as value), '');
    insert into tonde.creative_documents(workspace_id, production_id, scope_object_id, document_type, title, content)
      values (target_workspace, target_production, target_production, 'script', left(coalesce(script->>'title','Script'),160), left(script_content, 1000000))
      returning * into document_row;
    document_id := document_row.id;
    for script_scene in select value from jsonb_array_elements(coalesce(script->'scenes','[]'::jsonb)) loop
      script_scene_index := script_scene_index + 1;
      scene_id_text := nullif(script_scene->>'scene_order','');
      scene_id := null;
      if scene_id_text is not null and scene_ids ? scene_id_text then
        scene_id := (scene_ids->>scene_id_text)::uuid;
      end if;
      line_order := 1;
      for line in select value from jsonb_array_elements(coalesce(script_scene->'lines','[]'::jsonb)) loop
        if jsonb_typeof(line) <> 'object'
          or not exists(select 1 from unnest(enum_range(null::tonde.dialogue_kind)) k where k::text = coalesce(line->>'kind','dialogue')) then
          raise exception 'Unsupported dialogue line kind' using errcode = '22023';
        end if;
        dialogue_count := dialogue_count + 1;
        speaker_id := null;
        if coalesce(line->>'speaker','') <> '' and character_assets ? lower(line->>'speaker') then
          speaker_id := (character_assets->>lower(line->>'speaker'))::uuid;
        end if;
        insert into tonde.dialogue_lines(workspace_id, production_id, document_id, scene_id, speaker_asset_id,
          line_type, content, sort_order, start_ms, duration_ms, intention, delivery, subtext, pause_after_ms, line_flags)
        values (target_workspace, target_production, document_id, scene_id, speaker_id,
          coalesce(line->>'kind','dialogue')::tonde.dialogue_kind, left(coalesce(line->>'content',''),4000),
          (coalesce(nullif(scene_id_text,'')::bigint, script_scene_index::bigint) * 1000) + line_order,
          0, greatest(0, least(9007199254740991, coalesce((line->>'estimated_ms')::bigint, 0))),
          left(coalesce(line->>'intention',''),300), left(coalesce(line->>'delivery',''),300),
          left(coalesce(line->>'subtext',''),300), greatest(0, least(60000, coalesce((line->>'pause_after_ms')::bigint, 0))),
          jsonb_build_object('interruption', coalesce((line->>'interruption')::boolean, false),
            'overlap', coalesce((line->>'overlap')::boolean, false),
            'reaction_to', line->'reaction_to', 'order', line->'order'));
        line_order := line_order + 1;
      end loop;
    end loop;
  end if;
  insert into tonde.director_briefs as db (workspace_id, production_id, brief, producer, source_operation_id)
    values (target_workspace, target_production, brief, producer_kind, target_operation)
    on conflict (workspace_id, production_id) do update set brief = excluded.brief, producer = excluded.producer,
      source_operation_id = excluded.source_operation_id;
  for item in select value from jsonb_array_elements(coalesce(bundle->'decisions','[]'::jsonb)) loop
    if jsonb_typeof(item) = 'object' and coalesce(length(btrim(item->>'decision_id')),0) > 0 then
      insert into tonde.director_decisions as d (workspace_id, production_id, decision_id, question, answer, priority, impact, decided_by, decision_source)
        values (target_workspace, target_production, left(item->>'decision_id',80), left(coalesce(item->>'question',''),400),
          left(coalesce(item->>'answer',''),500), coalesce(item->>'priority','high_impact'), coalesce(item->>'impact','high'),
          case when item->>'answer' = 'TONDE decides' then 'tonde' else coalesce(item->>'decided_by','creator') end, 'studio')
        on conflict (production_id, decision_id) do update set answer = excluded.answer, priority = excluded.priority,
          impact = excluded.impact, decided_by = excluded.decided_by, decision_source = excluded.decision_source;
    end if;
  end loop;
  if jsonb_typeof(bundle->'reality') = 'object' then
    insert into tonde.director_reality_checks as rc (workspace_id, production_id, report, feasibility, complexity, recommended_mode, source_operation_id)
      values (target_workspace, target_production, bundle->'reality',
        coalesce(bundle->'reality'->>'feasibility','ready'), coalesce(bundle->'reality'->>'complexity','simple'),
        coalesce(bundle->'reality'->'mode'->>'method','real'), target_operation)
      on conflict (workspace_id, production_id) do update set report = excluded.report, feasibility = excluded.feasibility,
        complexity = excluded.complexity, recommended_mode = excluded.recommended_mode, source_operation_id = excluded.source_operation_id;
  end if;
  update tonde.productions set title = left(plan->>'title',160),
    production_type = (plan->>'production_type')::tonde.production_type,
    execution_method = (plan->>'execution_method')::tonde.execution_method,
    planned_duration_ms = target_duration
    where workspace_id = target_workspace and id = target_production;
  insert into tonde.director_operations(workspace_id, production_id, operation_id, operation_type, scope, source_revision,
    source_intake_revision, status, producer, provider, model, model_profile, idempotency_key, collaboration_mode, rationale,
    limitations, payload, payload_hash, started_at, completed_at, created_by)
  values (target_workspace, target_production, target_operation, operation_type, 'production', expected_production_revision,
    null, 'succeeded', producer_kind, bundle->'operation'->>'provider', bundle->'operation'->>'model',
    coalesce(bundle->'operation'->>'model_profile','default'),
    coalesce(bundle->'operation'->>'idempotency_key', 'apply:' || target_operation::text),
    coalesce(bundle->'operation'->>'collaboration_mode','stop_at_major_decisions'),
    left(coalesce(bundle->'operation'->>'rationale',''),1200),
    coalesce(bundle->'operation'->'limitations','[]'::jsonb),
    jsonb_build_object('scenes', scene_count, 'dialogue_lines', dialogue_count, 'assets', assets_result),
    bundle_hash, now(), now(), auth.uid())
  on conflict (workspace_id, operation_id) do update set
    status = 'succeeded', producer = excluded.producer, provider = excluded.provider, model = excluded.model,
    model_profile = excluded.model_profile, rationale = excluded.rationale, limitations = excluded.limitations,
    payload = excluded.payload, payload_hash = excluded.payload_hash, completed_at = now(),
    error_code = null, error_message = null;
  select revision into production_revision_out from tonde.productions
    where workspace_id = target_workspace and id = target_production;
  return jsonb_build_object('production_id', target_production, 'operation_id', target_operation, 'idempotent', false,
    'production_revision', production_revision_out, 'scenes', scene_count, 'dialogue_lines', dialogue_count,
    'assets', assets_result, 'runtime_ms', target_duration);
end;
$$;


revoke all on function tonde.apply_director_operation(uuid,uuid,integer,uuid,text,jsonb,boolean) from public, anon, authenticated, service_role;

grant execute on function tonde.apply_director_operation(uuid,uuid,integer,uuid,text,jsonb,boolean) to authenticated;

commit;

-- ==========================================================================
-- 202610050015_studio_workspace.sql
-- ==========================================================================

-- Additive migration: Prompt 5 Studio workspace.
-- Shots become first-class canonical objects (Prompt 4 stored shot plans inside
-- scenes.scene_detail only). Adds guarded Studio mutation RPCs; no hosted
-- migration is rewritten and no existing column changes meaning.
begin;


-- 1. Shot creative fields (5B). Bounded, defaulted, additive.
alter table tonde.shots add column if not exists purpose text not null default '' check (length(purpose) <= 200);

alter table tonde.shots add column if not exists subject text not null default '' check (length(subject) <= 200);

alter table tonde.shots add column if not exists framing text not null default '' check (length(framing) <= 120);

alter table tonde.shots add column if not exists angle text not null default '' check (length(angle) <= 120);

alter table tonde.shots add column if not exists movement text not null default '' check (length(movement) <= 160);

alter table tonde.shots add column if not exists composition text not null default '' check (length(composition) <= 300);

alter table tonde.shots add column if not exists transition text not null default '' check (length(transition) <= 200);

alter table tonde.shots add column if not exists story_relationship text not null default '' check (length(story_relationship) <= 300);

alter table tonde.shots add column if not exists creative_notes text not null default '' check (length(creative_notes) <= 1200);

alter table tonde.shots add column if not exists source_operation_id uuid;

alter table tonde.shots add column if not exists story_beat text not null default '' check (length(story_beat) <= 200);

create index if not exists shots_live_order on tonde.shots(workspace_id, production_id, scene_id, lifecycle, sort_order)
  where lifecycle = 'active';


-- 2. Scenes and Shots are already registered as scoped objects by the existing
-- a_register_object trigger (migration 002), so Scope bindings, Director threads and
-- documents can address a Scene or Shot by its own id. Prompt 5 relies on that rather
-- than duplicating identity.
create or replace function tonde_private.assert_scope_object(target_workspace uuid, target_production uuid, target_id uuid, target_kind text)
returns void language plpgsql security definer set search_path = '' as $$
begin
  if not exists(select 1 from tonde.objects o where o.workspace_id = target_workspace
    and o.id = target_id and o.kind = target_kind and o.production_id is not distinct from target_production) then
    raise exception 'Studio object identity is missing for this %', target_kind using errcode = '23514';
  end if;
end $$;

revoke all on function tonde_private.assert_scope_object(uuid,uuid,uuid,text) from public, anon, authenticated, service_role;


-- 3. One guard for every Studio write: authenticated editor, live Production, revision match.
create or replace function tonde_private.studio_guard(target_workspace uuid, target_production uuid, expected_revision integer)
returns tonde.productions language plpgsql security definer set search_path = '' as $$
declare current tonde.productions;
begin
  perform tonde_private.director_guard(target_workspace);
  select * into current from tonde.productions
    where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if current.lifecycle <> 'active' then
    raise exception 'This Production is archived' using errcode = '23514';
  end if;
  if expected_revision is not null and current.revision <> expected_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  return current;
end $$;

revoke all on function tonde_private.studio_guard(uuid,uuid,integer) from public, anon, authenticated, service_role;


-- Scenes and Shots carry their own revision, lock and approval.
create or replace function tonde_private.studio_revision_guard(target_workspace uuid, target_production uuid, target_id uuid, object_kind text, expected_revision integer)
returns void language plpgsql security definer set search_path = '' as $$
declare row_revision integer; row_locked timestamptz; row_lifecycle tonde.lifecycle;
begin
  if object_kind = 'scene' then
    select revision, locked_at, lifecycle into row_revision, row_locked, row_lifecycle from tonde.scenes
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
  elsif object_kind = 'shot' then
    select revision, locked_at, lifecycle into row_revision, row_locked, row_lifecycle from tonde.shots
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
  else
    raise exception 'Unsupported Studio object kind' using errcode = '22023';
  end if;
  if not found then raise exception 'That % is unavailable in this Production', object_kind using errcode = 'P0002'; end if;
  if row_lifecycle <> 'active' then raise exception 'That % is archived', object_kind using errcode = '23514'; end if;
  if row_locked is not null then raise exception 'That % is locked. Unlock it before editing.', object_kind using errcode = '23514'; end if;
  if expected_revision is not null and row_revision <> expected_revision then
    raise exception 'That % changed since you loaded it', object_kind using errcode = '40001';
  end if;
end $$;

revoke all on function tonde_private.studio_revision_guard(uuid,uuid,uuid,text,integer) from public, anon, authenticated, service_role;


-- 4. Timing authority: a Scene's duration is derived from its Shots only when every
-- Shot in that Scene has a duration. Otherwise the Scene keeps its planned value and
-- is reported as incomplete. Derived timing is COMPUTED, never stored: writing derived
-- columns would bump content revisions and invalidate every client revision handle.
create or replace function tonde_private.studio_timing(target_workspace uuid, target_production uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare target_ms bigint; total_ms bigint; scene_states jsonb;
begin
  select planned_duration_ms into target_ms from tonde.productions
    where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  with scene_rollup as (
    select s.id, s.sort_order, s.planned_duration_ms,
      count(h.id) as shot_count,
      count(h.id) filter (where h.planned_duration_ms is null) as missing,
      coalesce(sum(h.planned_duration_ms), 0) as shot_total
    from tonde.scenes s
    left join tonde.shots h on h.workspace_id = s.workspace_id and h.production_id = s.production_id
      and h.scene_id = s.id and h.lifecycle = 'active'
    where s.workspace_id = target_workspace and s.production_id = target_production and s.lifecycle = 'active'
    group by s.id, s.sort_order, s.planned_duration_ms
  )
  select coalesce(sum(case when shot_count > 0 and missing = 0 then shot_total else coalesce(planned_duration_ms, 0) end), 0),
    coalesce(jsonb_agg(jsonb_build_object(
      'scene_id', id,
      'order', sort_order,
      'duration_ms', case when shot_count > 0 and missing = 0 then shot_total else coalesce(planned_duration_ms, 0) end,
      'shots', shot_count,
      'timing', case when shot_count > 0 and missing = 0 then 'derived' when shot_count > 0 then 'incomplete' else 'planned' end)
      order by sort_order, id), '[]'::jsonb)
  into total_ms, scene_states from scene_rollup;
  return jsonb_build_object(
    'total_ms', total_ms,
    'target_ms', target_ms,
    'delta_ms', case when target_ms is null then null else total_ms - target_ms end,
    'status', case when target_ms is null then 'unresolved' when total_ms = target_ms then 'fits'
      when total_ms > target_ms then 'over' else 'under' end,
    'scene_states', scene_states);
end $$;

revoke all on function tonde_private.studio_timing(uuid,uuid) from public, anon, authenticated, service_role;

create or replace function tonde.studio_timing(target_workspace uuid, target_production uuid, expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare current_revision integer;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select revision into current_revision from tonde.productions where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and current_revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  return tonde_private.studio_timing(target_workspace, target_production);
end $$;


-- 5. Scene operations.
create or replace function tonde.create_studio_scene(target_workspace uuid, target_production uuid, expected_production_revision integer, scene jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare created tonde.scenes; next_order bigint; scene_title text; env_id uuid; desired_duration bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if jsonb_typeof(scene) <> 'object' then raise exception 'Invalid Scene payload' using errcode = '22023'; end if;
  scene_title := btrim(coalesce(scene->>'title',''));
  if length(scene_title) = 0 or length(scene_title) > 160 then
    raise exception 'A Scene needs a title of 1 to 160 characters' using errcode = '22023';
  end if;
  if coalesce(scene->>'environment_asset_id','') <> '' then
    env_id := (scene->>'environment_asset_id')::uuid;
    if not exists(select 1 from tonde.assets a where a.workspace_id = target_workspace and a.id = env_id
      and a.asset_type = 'environment' and a.lifecycle = 'active') then
      raise exception 'A Scene environment must be an active environment asset' using errcode = '23514';
    end if;
  end if;
  if scene->>'duration_ms' is not null then
    if scene->>'duration_ms' !~ '^[0-9]{1,16}$' then
      raise exception 'Scene duration must be whole milliseconds' using errcode = '22023';
    end if;
    desired_duration := (scene->>'duration_ms')::bigint;
    if desired_duration > 9007199254740991 then raise exception 'Scene duration exceeds the safe integer range' using errcode = '22023'; end if;
  end if;
  select coalesce(max(s.sort_order), 0) + 1024 into next_order from tonde.scenes s
    where s.workspace_id = target_workspace and s.production_id = target_production;
  insert into tonde.scenes(workspace_id, production_id, title, purpose, description, story_beat, opening_state,
    ending_state, visual_intent, dialogue_notes, action_lines, scene_detail, environment_asset_id, sort_order, planned_duration_ms)
  values (target_workspace, target_production, left(scene_title,160), left(coalesce(scene->>'purpose',''),1200),
    left(coalesce(scene->>'description',''),4000), left(coalesce(scene->>'story_beat',''),200),
    left(coalesce(scene->>'opening_state',''),400), left(coalesce(scene->>'ending_state',''),400),
    left(coalesce(scene->>'visual_intent',''),900), left(coalesce(scene->>'dialogue_notes',''),900),
    '[]'::jsonb, '{}'::jsonb, env_id, next_order, desired_duration)
  returning * into created;
  perform tonde_private.assert_scope_object(target_workspace, target_production, created.id, 'scene');
  return jsonb_build_object(
    'scene_id', created.id, 'title', created.title, 'sort_order', created.sort_order,
    'revision', created.revision, 'approval', created.approval,
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.update_studio_scene(target_workspace uuid, target_production uuid, target_scene uuid, expected_revision integer, patch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare updated tonde.scenes; current tonde.scenes; desired_duration bigint; title_value text; env_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(patch) <> 'object' then raise exception 'Invalid Scene patch' using errcode = '22023'; end if;
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_scene, 'scene', expected_revision);
  select * into current from tonde.scenes where workspace_id = target_workspace and production_id = target_production and id = target_scene;
  title_value := current.title;
  if patch ? 'title' then
    title_value := btrim(coalesce(patch->>'title',''));
    if length(title_value) = 0 or length(title_value) > 160 then
      raise exception 'A Scene needs a title of 1 to 160 characters' using errcode = '22023';
    end if;
  end if;
  env_value := current.environment_asset_id::text;
  if patch ? 'environment_asset_id' then
    env_value := nullif(coalesce(patch->>'environment_asset_id',''), '');
    if env_value is not null and not exists(select 1 from tonde.assets a where a.workspace_id = target_workspace
      and a.id = env_value::uuid and a.asset_type = 'environment' and a.lifecycle = 'active') then
      raise exception 'A Scene environment must be an active environment asset' using errcode = '23514';
    end if;
  end if;
  desired_duration := current.planned_duration_ms;
  if patch ? 'duration_ms' then
    if patch->>'duration_ms' is null then
      desired_duration := null;
    elsif patch->>'duration_ms' !~ '^[0-9]{1,16}$' then
      raise exception 'Scene duration must be whole milliseconds' using errcode = '22023';
    else
      desired_duration := (patch->>'duration_ms')::bigint;
      if desired_duration > 9007199254740991 then raise exception 'Scene duration exceeds the safe integer range' using errcode = '22023'; end if;
    end if;
  end if;
  update tonde.scenes set
    title = title_value,
    purpose = case when patch ? 'purpose' then left(coalesce(patch->>'purpose',''),1200) else purpose end,
    description = case when patch ? 'description' then left(coalesce(patch->>'description',''),4000) else description end,
    story_beat = case when patch ? 'story_beat' then left(coalesce(patch->>'story_beat',''),200) else story_beat end,
    opening_state = case when patch ? 'opening_state' then left(coalesce(patch->>'opening_state',''),400) else opening_state end,
    ending_state = case when patch ? 'ending_state' then left(coalesce(patch->>'ending_state',''),400) else ending_state end,
    visual_intent = case when patch ? 'visual_intent' then left(coalesce(patch->>'visual_intent',''),900) else visual_intent end,
    dialogue_notes = case when patch ? 'dialogue_notes' then left(coalesce(patch->>'dialogue_notes',''),900) else dialogue_notes end,
    environment_asset_id = env_value::uuid,
    planned_duration_ms = desired_duration
  where workspace_id = target_workspace and production_id = target_production and id = target_scene
  returning * into updated;
  return jsonb_build_object(
    'scene_id', updated.id, 'revision', updated.revision, 'approval', updated.approval,
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.reorder_studio_scenes(target_workspace uuid, target_production uuid, expected_production_revision integer, ordered_ids uuid[])
returns jsonb language plpgsql security definer set search_path = '' as $$
declare live_count integer; provided_count integer; base_order bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if ordered_ids is null or array_length(ordered_ids, 1) is null then
    raise exception 'Provide the complete Scene order' using errcode = '22023';
  end if;
  select count(*) into live_count from tonde.scenes
    where workspace_id = target_workspace and production_id = target_production and lifecycle = 'active';
  select count(distinct value) into provided_count from unnest(ordered_ids) as value;
  if provided_count <> array_length(ordered_ids, 1) then
    raise exception 'Scene order contains duplicates' using errcode = '22023';
  end if;
  if provided_count <> live_count or exists(
    select 1 from unnest(ordered_ids) as value
    where not exists(select 1 from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.id = value and s.lifecycle = 'active')) then
    raise exception 'The Scene order must list exactly the live Scenes of this Production' using errcode = '22023';
  end if;
  select coalesce(max(s.sort_order), 0) + 1024 into base_order from tonde.scenes s
    where s.workspace_id = target_workspace and s.production_id = target_production;
  set constraints all deferred;
  update tonde.scenes s set sort_order = base_order + ranked.position * 1024
    from (select value as id, row_number() over () as position from unnest(ordered_ids) as value) as ranked
    where s.workspace_id = target_workspace and s.production_id = target_production and s.id = ranked.id;
  return jsonb_build_object('scenes', live_count, 'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.archive_studio_scene(target_workspace uuid, target_production uuid, target_scene uuid, expected_revision integer, cascade boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare next_order bigint; live_shots integer; shot_floor bigint; archived_shots integer := 0;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_scene, 'scene', expected_revision);
  select count(*) into live_shots from tonde.shots
    where workspace_id = target_workspace and production_id = target_production and scene_id = target_scene and lifecycle = 'active';
  if live_shots > 0 and not coalesce(cascade, false) then
    raise exception 'This Scene still has % Shot(s). Archive them too, or move them first.', live_shots using errcode = '23514';
  end if;
  -- Scenes and Shots each own a production-wide ordering namespace; never mix them.
  select coalesce(max(s.sort_order), 0) + 1024 into next_order from tonde.scenes s
    where s.workspace_id = target_workspace and s.production_id = target_production;
  if coalesce(cascade, false) and live_shots > 0 then
    select coalesce(max(h.sort_order), 0) + 1024 into shot_floor from tonde.shots h
      where h.workspace_id = target_workspace and h.production_id = target_production;
    set constraints all deferred;
    update tonde.shots h set lifecycle = 'archived', sort_order = shot_floor + ranked.position * 1024
      from (select id, row_number() over (order by sort_order, id) as position from tonde.shots
        where workspace_id = target_workspace and production_id = target_production
          and scene_id = target_scene and lifecycle = 'active') as ranked
      where h.workspace_id = target_workspace and h.production_id = target_production and h.id = ranked.id;
    archived_shots := live_shots;
  end if;
  update tonde.scenes set lifecycle = 'archived', sort_order = next_order, planned_duration_ms = null
    where workspace_id = target_workspace and production_id = target_production and id = target_scene;
  return jsonb_build_object('scene_id', target_scene, 'archived_shots', archived_shots,
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


-- 6. Shot operations.
create or replace function tonde.create_studio_shot(target_workspace uuid, target_production uuid, target_scene uuid,
  expected_production_revision integer, shot jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare created tonde.shots; next_order bigint; shot_title text; desired_duration bigint; desired_method text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if jsonb_typeof(shot) <> 'object' then raise exception 'Invalid Shot payload' using errcode = '22023'; end if;
  if target_scene is not null and not exists(select 1 from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.id = target_scene and s.lifecycle = 'active') then
    raise exception 'Shot target Scene is unavailable in this Production' using errcode = 'P0002';
  end if;
  shot_title := btrim(coalesce(shot->>'title',''));
  if length(shot_title) = 0 or length(shot_title) > 160 then
    raise exception 'A Shot needs a title of 1 to 160 characters' using errcode = '22023';
  end if;
  if shot->>'duration_ms' is not null then
    if shot->>'duration_ms' !~ '^[0-9]{1,16}$' then raise exception 'Shot duration must be whole milliseconds' using errcode = '22023'; end if;
    desired_duration := (shot->>'duration_ms')::bigint;
    if desired_duration > 9007199254740991 then raise exception 'Shot duration exceeds the safe integer range' using errcode = '22023'; end if;
  end if;
  desired_method := coalesce(nullif(shot->>'execution_method',''), 'real');
  if desired_method not in ('real','ai','hybrid') then
    raise exception 'Shot execution method must be real, ai or hybrid' using errcode = '22023';
  end if;
  -- sort_order is unique per Production (not per Scene), so the next free slot is
  -- computed across the whole Production including archived rows.
  select coalesce(max(h.sort_order), 0) + 1024 into next_order from tonde.shots h
    where h.workspace_id = target_workspace and h.production_id = target_production;
  insert into tonde.shots(workspace_id, production_id, scene_id, title, description, action, purpose, subject,
    framing, angle, movement, composition, transition, story_relationship, creative_notes, story_beat,
    execution_method, sort_order, planned_duration_ms)
  values (target_workspace, target_production, target_scene, left(shot_title,160),
    left(coalesce(shot->>'description',''),4000), left(coalesce(shot->>'action',''),4000),
    left(coalesce(shot->>'purpose',''),200), left(coalesce(shot->>'subject',''),200),
    left(coalesce(shot->>'framing',''),120), left(coalesce(shot->>'angle',''),120),
    left(coalesce(shot->>'movement',''),160), left(coalesce(shot->>'composition',''),300),
    left(coalesce(shot->>'transition',''),200), left(coalesce(shot->>'story_relationship',''),300),
    left(coalesce(shot->>'creative_notes',''),1200), left(coalesce(shot->>'story_beat',''),200),
    desired_method::tonde.execution_method, next_order, desired_duration)
  returning * into created;
  perform tonde_private.assert_scope_object(target_workspace, target_production, created.id, 'shot');
  return jsonb_build_object(
    'shot_id', created.id, 'title', created.title, 'sort_order', created.sort_order,
    'revision', created.revision, 'approval', created.approval, 'execution_method', created.execution_method,
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.update_studio_shot(target_workspace uuid, target_production uuid, target_shot uuid, expected_revision integer, patch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare updated tonde.shots; current tonde.shots; desired_duration bigint; title_value text; method_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(patch) <> 'object' then raise exception 'Invalid Shot patch' using errcode = '22023'; end if;
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_revision);
  select * into current from tonde.shots where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  title_value := current.title;
  if patch ? 'title' then
    title_value := btrim(coalesce(patch->>'title',''));
    if length(title_value) = 0 or length(title_value) > 160 then
      raise exception 'A Shot needs a title of 1 to 160 characters' using errcode = '22023';
    end if;
  end if;
  method_value := current.execution_method::text;
  if patch ? 'execution_method' then
    method_value := coalesce(nullif(patch->>'execution_method',''), 'real');
    if method_value not in ('real','ai','hybrid') then
      raise exception 'Shot execution method must be real, ai or hybrid' using errcode = '22023';
    end if;
  end if;
  desired_duration := current.planned_duration_ms;
  if patch ? 'duration_ms' then
    if patch->>'duration_ms' is null then
      desired_duration := null;
    elsif patch->>'duration_ms' !~ '^[0-9]{1,16}$' then
      raise exception 'Shot duration must be whole milliseconds' using errcode = '22023';
    else
      desired_duration := (patch->>'duration_ms')::bigint;
      if desired_duration > 9007199254740991 then raise exception 'Shot duration exceeds the safe integer range' using errcode = '22023'; end if;
    end if;
  end if;
  update tonde.shots set
    title = title_value,
    description = case when patch ? 'description' then left(coalesce(patch->>'description',''),4000) else description end,
    action = case when patch ? 'action' then left(coalesce(patch->>'action',''),4000) else action end,
    purpose = case when patch ? 'purpose' then left(coalesce(patch->>'purpose',''),200) else purpose end,
    subject = case when patch ? 'subject' then left(coalesce(patch->>'subject',''),200) else subject end,
    framing = case when patch ? 'framing' then left(coalesce(patch->>'framing',''),120) else framing end,
    angle = case when patch ? 'angle' then left(coalesce(patch->>'angle',''),120) else angle end,
    movement = case when patch ? 'movement' then left(coalesce(patch->>'movement',''),160) else movement end,
    composition = case when patch ? 'composition' then left(coalesce(patch->>'composition',''),300) else composition end,
    transition = case when patch ? 'transition' then left(coalesce(patch->>'transition',''),200) else transition end,
    story_relationship = case when patch ? 'story_relationship' then left(coalesce(patch->>'story_relationship',''),300) else story_relationship end,
    creative_notes = case when patch ? 'creative_notes' then left(coalesce(patch->>'creative_notes',''),1200) else creative_notes end,
    story_beat = case when patch ? 'story_beat' then left(coalesce(patch->>'story_beat',''),200) else story_beat end,
    execution_method = method_value::tonde.execution_method,
    planned_duration_ms = desired_duration
  where workspace_id = target_workspace and production_id = target_production and id = target_shot
  returning * into updated;
  return jsonb_build_object(
    'shot_id', updated.id, 'revision', updated.revision, 'approval', updated.approval,
    'execution_method', updated.execution_method, 'scene_id', updated.scene_id,
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.move_studio_shot(target_workspace uuid, target_production uuid, target_shot uuid, target_scene uuid, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare moved tonde.shots; next_order bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_revision);
  if target_scene is not null and not exists(select 1 from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.id = target_scene and s.lifecycle = 'active') then
    raise exception 'Target Scene is unavailable in this Production' using errcode = 'P0002';
  end if;
  select coalesce(max(h.sort_order), 0) + 1024 into next_order from tonde.shots h
    where h.workspace_id = target_workspace and h.production_id = target_production;
  update tonde.shots set scene_id = target_scene, sort_order = next_order
    where workspace_id = target_workspace and production_id = target_production and id = target_shot
    returning * into moved;
  return jsonb_build_object('shot_id', moved.id, 'scene_id', moved.scene_id, 'sort_order', moved.sort_order,
    'revision', moved.revision, 'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.reorder_studio_shots(target_workspace uuid, target_production uuid, target_scene uuid, expected_production_revision integer, ordered_ids uuid[])
returns jsonb language plpgsql security definer set search_path = '' as $$
declare live_count integer; provided_count integer; base_order bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if ordered_ids is null or array_length(ordered_ids, 1) is null then
    raise exception 'Provide the complete Shot order' using errcode = '22023';
  end if;
  select count(*) into live_count from tonde.shots
    where workspace_id = target_workspace and production_id = target_production
      and scene_id is not distinct from target_scene and lifecycle = 'active';
  select count(distinct value) into provided_count from unnest(ordered_ids) as value;
  if provided_count <> array_length(ordered_ids, 1) then
    raise exception 'Shot order contains duplicates' using errcode = '22023';
  end if;
  if provided_count <> live_count or exists(
    select 1 from unnest(ordered_ids) as value
    where not exists(select 1 from tonde.shots h where h.workspace_id = target_workspace
      and h.production_id = target_production and h.id = value and h.lifecycle = 'active'
      and h.scene_id is not distinct from target_scene)) then
    raise exception 'The Shot order must list exactly the live Shots of this Scene' using errcode = '22023';
  end if;
  -- Reassign above every existing row so the shared Production-wide ordering never collides.
  select coalesce(max(h.sort_order), 0) + 1024 into base_order from tonde.shots h
    where h.workspace_id = target_workspace and h.production_id = target_production;
  set constraints all deferred;
  update tonde.shots h set sort_order = base_order + ranked.position * 1024
    from (select value as id, row_number() over () as position from unnest(ordered_ids) as value) as ranked
    where h.workspace_id = target_workspace and h.production_id = target_production and h.id = ranked.id;
  return jsonb_build_object('shots', live_count, 'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


create or replace function tonde.archive_studio_shot(target_workspace uuid, target_production uuid, target_shot uuid, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare next_order bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_revision);
  select coalesce(max(h.sort_order), 0) + 1024 into next_order from tonde.shots h
    where h.workspace_id = target_workspace and h.production_id = target_production;
  -- Archive over hard delete: the Shot leaves the live order but remains readable.
  update tonde.shots set lifecycle = 'archived', sort_order = next_order
    where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  return jsonb_build_object('shot_id', target_shot, 'archived', true,
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


-- 7. Approval and lock. Approval stays the canonical enum; a changed approved row
-- already reports changed_after_approval through the integrity guard.
create or replace function tonde.set_studio_approval(target_workspace uuid, target_production uuid, target_scope text,
  target_id uuid, desired_approval text, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare resulting_revision integer; resulting_approval tonde.approval;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_scope not in ('production','scene','shot') then
    raise exception 'Approval scope must be production, scene or shot' using errcode = '22023';
  end if;
  if desired_approval not in ('draft','needs_review','approved','changed_after_approval') then
    raise exception 'Unsupported approval state' using errcode = '22023';
  end if;
  if target_scope = 'production' then
    update tonde.productions set approval = desired_approval::tonde.approval
      where workspace_id = target_workspace and id = target_production
        and (expected_revision is null or revision = expected_revision)
      returning revision, approval into resulting_revision, resulting_approval;
  elsif target_scope = 'scene' then
    perform tonde_private.studio_revision_guard(target_workspace, target_production, target_id, 'scene', expected_revision);
    update tonde.scenes set approval = desired_approval::tonde.approval
      where workspace_id = target_workspace and production_id = target_production and id = target_id
      returning revision, approval into resulting_revision, resulting_approval;
  else
    perform tonde_private.studio_revision_guard(target_workspace, target_production, target_id, 'shot', expected_revision);
    update tonde.shots set approval = desired_approval::tonde.approval
      where workspace_id = target_workspace and production_id = target_production and id = target_id
      returning revision, approval into resulting_revision, resulting_approval;
  end if;
  if resulting_revision is null then
    raise exception 'That object changed since you loaded it' using errcode = '40001';
  end if;
  return jsonb_build_object('scope', target_scope, 'id', target_id, 'approval', resulting_approval, 'revision', resulting_revision);
end $$;


create or replace function tonde.set_studio_lock(target_workspace uuid, target_production uuid, target_scope text,
  target_id uuid, locked boolean, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare resulting_revision integer; resulting_locked timestamptz;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_scope not in ('production','scene','shot') then
    raise exception 'Lock scope must be production, scene or shot' using errcode = '22023';
  end if;
  if target_scope = 'production' then
    update tonde.productions set locked_at = case when coalesce(locked,false) then now() else null end
      where workspace_id = target_workspace and id = target_production
        and (expected_revision is null or revision = expected_revision)
      returning revision, locked_at into resulting_revision, resulting_locked;
  elsif target_scope = 'scene' then
    update tonde.scenes set locked_at = case when coalesce(locked,false) then now() else null end
      where workspace_id = target_workspace and production_id = target_production and id = target_id
        and (expected_revision is null or revision = expected_revision)
      returning revision, locked_at into resulting_revision, resulting_locked;
  else
    update tonde.shots set locked_at = case when coalesce(locked,false) then now() else null end
      where workspace_id = target_workspace and production_id = target_production and id = target_id
        and (expected_revision is null or revision = expected_revision)
      returning revision, locked_at into resulting_revision, resulting_locked;
  end if;
  if resulting_revision is null then
    raise exception 'That object changed since you loaded it' using errcode = '40001';
  end if;
  return jsonb_build_object('scope', target_scope, 'id', target_id, 'locked', resulting_locked is not null, 'revision', resulting_revision);
end $$;


-- 8. Runtime reconciliation: the creator names the Scene that absorbs the delta and
-- its trailing Shot takes the exact adjustment. Nothing is redistributed silently.
create or replace function tonde.reconcile_studio_runtime(target_workspace uuid, target_production uuid, absorb_scene uuid, expected_production_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare timing jsonb; delta bigint; scene_row tonde.scenes; trailing_shot tonde.shots; new_duration bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  timing := tonde_private.studio_timing(target_workspace, target_production);
  delta := coalesce((timing->>'delta_ms')::bigint, 0);
  if timing->>'target_ms' is null then
    raise exception 'Set a Production runtime target before reconciling timing' using errcode = '23514';
  end if;
  if delta = 0 then
    return jsonb_build_object('adjusted_ms', 0, 'timing', timing);
  end if;
  select * into scene_row from tonde.scenes where workspace_id = target_workspace and production_id = target_production
    and id = absorb_scene and lifecycle = 'active';
  if not found then raise exception 'The absorbing Scene is unavailable' using errcode = 'P0002'; end if;
  if scene_row.locked_at is not null then raise exception 'That Scene is locked. Unlock it before editing.' using errcode = '23514'; end if;
  select * into trailing_shot from tonde.shots where workspace_id = target_workspace and production_id = target_production
    and scene_id = absorb_scene and lifecycle = 'active' and planned_duration_ms is not null
    order by sort_order desc, id desc limit 1;
  if not found then
    raise exception 'The absorbing Scene needs at least one Shot with a duration' using errcode = '23514';
  end if;
  if trailing_shot.locked_at is not null then raise exception 'That Shot is locked. Unlock it before editing.' using errcode = '23514'; end if;
  new_duration := trailing_shot.planned_duration_ms - delta;
  if new_duration < 0 then
    raise exception 'That adjustment would make the last Shot of the absorbing Scene negative. Choose a different Scene.' using errcode = '23514';
  end if;
  update tonde.shots set planned_duration_ms = new_duration
    where workspace_id = target_workspace and production_id = target_production and id = trailing_shot.id;
  return jsonb_build_object('adjusted_ms', -delta, 'shot_id', trailing_shot.id, 'scene_id', absorb_scene,
    'shot_duration_ms', new_duration, 'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


-- 9. Privileges: authenticated only, never anon or service_role, private helper hidden.
revoke all on function tonde.studio_timing(uuid,uuid,integer),
  tonde.create_studio_scene(uuid,uuid,integer,jsonb),
  tonde.update_studio_scene(uuid,uuid,uuid,integer,jsonb),
  tonde.reorder_studio_scenes(uuid,uuid,integer,uuid[]),
  tonde.archive_studio_scene(uuid,uuid,uuid,integer,boolean),
  tonde.create_studio_shot(uuid,uuid,uuid,integer,jsonb),
  tonde.update_studio_shot(uuid,uuid,uuid,integer,jsonb),
  tonde.move_studio_shot(uuid,uuid,uuid,uuid,integer),
  tonde.reorder_studio_shots(uuid,uuid,uuid,integer,uuid[]),
  tonde.archive_studio_shot(uuid,uuid,uuid,integer),
  tonde.set_studio_approval(uuid,uuid,text,uuid,text,integer),
  tonde.set_studio_lock(uuid,uuid,text,uuid,boolean,integer),
  tonde.reconcile_studio_runtime(uuid,uuid,uuid,integer)
  from public, anon, authenticated, service_role;

grant execute on function tonde.studio_timing(uuid,uuid,integer),
  tonde.create_studio_scene(uuid,uuid,integer,jsonb),
  tonde.update_studio_scene(uuid,uuid,uuid,integer,jsonb),
  tonde.reorder_studio_scenes(uuid,uuid,integer,uuid[]),
  tonde.archive_studio_scene(uuid,uuid,uuid,integer,boolean),
  tonde.create_studio_shot(uuid,uuid,uuid,integer,jsonb),
  tonde.update_studio_shot(uuid,uuid,uuid,integer,jsonb),
  tonde.move_studio_shot(uuid,uuid,uuid,uuid,integer),
  tonde.reorder_studio_shots(uuid,uuid,uuid,integer,uuid[]),
  tonde.archive_studio_shot(uuid,uuid,uuid,integer),
  tonde.set_studio_approval(uuid,uuid,text,uuid,text,integer),
  tonde.set_studio_lock(uuid,uuid,text,uuid,boolean,integer),
  tonde.reconcile_studio_runtime(uuid,uuid,uuid,integer)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050016_real_production.sql
-- ==========================================================================

-- Additive migration: Prompt 6 Real Production Director.
-- The Real Execution Plan is the SAME per-Shot plan row (tonde.execution_plans,
-- execution_method = 'real'); this migration adds its structured body plus the
-- relational detail Prompt 6 needs (Setup matching, practical alternatives,
-- capture state, Takes, field deviations). No hosted migration is rewritten, no
-- second Real-only Shot model is created, and no existing column changes meaning.
begin;


-- 1. Real Execution Plan body. One Shot has at most one real plan row
-- (unique (shot_id, execution_method) already exists), so these are genuinely
-- per-plan single values rather than another table.
--
-- Exposure values (shutter / aperture / ISO / WB / ND) are RECOMMENDATIONS and
-- STARTING POINTS by contract: they are stored as the bounded text the director
-- produced, and the surface labels them. Nothing here claims measured truth.
alter table tonde.execution_plans add column if not exists plan_status text not null default 'draft'
  check (plan_status in ('draft','ready','ready_with_substitution','needs_decision','missing_resource','safety_blocked'));

alter table tonde.execution_plans add column if not exists readiness_note text not null default '' check (length(readiness_note) <= 600);

alter table tonde.execution_plans add column if not exists complexity text check (complexity in ('quick','moderate','complex'));

alter table tonde.execution_plans add column if not exists complexity_is_estimate boolean not null default true;

alter table tonde.execution_plans add column if not exists generated_by text not null default 'deterministic'
  check (generated_by in ('deterministic','model','creator'));

alter table tonde.execution_plans add column if not exists source_operation_id uuid;

-- Camera and lens geometry.
alter table tonde.execution_plans add column if not exists shot_size text not null default '' check (length(shot_size) <= 80);

alter table tonde.execution_plans add column if not exists camera_position text not null default '' check (length(camera_position) <= 400);

alter table tonde.execution_plans add column if not exists camera_height text not null default '' check (length(camera_height) <= 200);

alter table tonde.execution_plans add column if not exists camera_angle text not null default '' check (length(camera_angle) <= 200);

alter table tonde.execution_plans add column if not exists framing text not null default '' check (length(framing) <= 300);

alter table tonde.execution_plans add column if not exists composition text not null default '' check (length(composition) <= 400);

alter table tonde.execution_plans add column if not exists perspective_note text not null default '' check (length(perspective_note) <= 600);

-- Movement.
alter table tonde.execution_plans add column if not exists movement text not null default '' check (length(movement) <= 200);

alter table tonde.execution_plans add column if not exists movement_purpose text not null default '' check (length(movement_purpose) <= 600);

alter table tonde.execution_plans add column if not exists stabilization text not null default '' check (length(stabilization) <= 200);

-- Exposure starting points.
alter table tonde.execution_plans add column if not exists capture_fps text not null default '' check (length(capture_fps) <= 80);

alter table tonde.execution_plans add column if not exists delivery_fps text not null default '' check (length(delivery_fps) <= 80);

alter table tonde.execution_plans add column if not exists shutter text not null default '' check (length(shutter) <= 120);

alter table tonde.execution_plans add column if not exists aperture text not null default '' check (length(aperture) <= 120);

alter table tonde.execution_plans add column if not exists iso_range text not null default '' check (length(iso_range) <= 120);

alter table tonde.execution_plans add column if not exists white_balance text not null default '' check (length(white_balance) <= 160);

alter table tonde.execution_plans add column if not exists nd_filter text not null default '' check (length(nd_filter) <= 200);

alter table tonde.execution_plans add column if not exists exposure_note text not null default '' check (length(exposure_note) <= 600);

-- Focus.
alter table tonde.execution_plans add column if not exists focus_strategy text not null default '' check (length(focus_strategy) <= 600);

alter table tonde.execution_plans add column if not exists depth_of_field text not null default '' check (length(depth_of_field) <= 400);

-- Light, blocking, performance, Product.
alter table tonde.execution_plans add column if not exists lighting_intent text not null default '' check (length(lighting_intent) <= 400);

alter table tonde.execution_plans add column if not exists lighting_plan text not null default '' check (length(lighting_plan) <= 2000);

-- A structured diagram foundation (subject / camera / lights / modifiers / direction /
-- purpose) that can later render visually. Empty object is valid and means "no diagram".
alter table tonde.execution_plans add column if not exists lighting_diagram jsonb not null default '{}'::jsonb
  check (jsonb_typeof(lighting_diagram) = 'object');

alter table tonde.execution_plans add column if not exists blocking text not null default '' check (length(blocking) <= 2000);

alter table tonde.execution_plans add column if not exists performance text not null default '' check (length(performance) <= 2000);

alter table tonde.execution_plans add column if not exists product_direction text not null default '' check (length(product_direction) <= 1200);

-- Sound.
alter table tonde.execution_plans add column if not exists sound_plan text not null default '' check (length(sound_plan) <= 2000);

alter table tonde.execution_plans add column if not exists microphone_plan text not null default '' check (length(microphone_plan) <= 1200);

alter table tonde.execution_plans add column if not exists sync_strategy text not null default '' check (length(sync_strategy) <= 600);

-- Crew, solo feasibility, Environment and Location requirements.
alter table tonde.execution_plans add column if not exists solo_feasibility text
  check (solo_feasibility in ('solo','solo_with_simplification','second_person_recommended','crew_required'));

alter table tonde.execution_plans add column if not exists crew_roles text[] not null default '{}';

alter table tonde.execution_plans add column if not exists environment_requirements text[] not null default '{}';

alter table tonde.execution_plans add column if not exists location_requirements text[] not null default '{}';

-- Safety and purpose.
alter table tonde.execution_plans add column if not exists safety_notes text[] not null default '{}';

alter table tonde.execution_plans add column if not exists safety_flags text[] not null default '{}';

alter table tonde.execution_plans add column if not exists editorial_intent text not null default '' check (length(editorial_intent) <= 300);

alter table tonde.execution_plans add column if not exists setup_steps text[] not null default '{}';

alter table tonde.execution_plans add column if not exists capture_checklist text[] not null default '{}';

alter table tonde.execution_plans add column if not exists expected_duration_ms bigint check (expected_duration_ms >= 0);

create index if not exists execution_plans_real_by_shot on tonde.execution_plans(workspace_id, production_id, shot_id)
  where execution_method = 'real';


-- 2. Setup matching. One row per thing a Shot needs. This is where "owned",
-- "owned substitute" and "missing" are recorded as separate facts instead of a
-- single optimistic assumption that the creator owns everything.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.requirement_kind as enum ('camera','lens','stabilization','light','modifier','stand',
  'microphone','recorder','wireless_audio','filter','monitor','rigging','accessory','power','space',
  'sound','talent','crew','product','prop','wardrobe','environment','runtime')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.requirement_status as enum ('owned','substitute','missing','unverified','not_required')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.epistemic as enum ('REQUIRED','RECOMMENDED','STARTING POINT','OPTIONAL','UNKNOWN')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

create table if not exists tonde.real_plan_requirements (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  shot_id uuid not null, plan_id uuid not null,
  requirement_kind tonde.requirement_kind not null,
  label text not null check (length(btrim(label)) between 1 and 160),
  ideal_name text not null default '' check (length(ideal_name) <= 200),
  detail text not null default '' check (length(detail) <= 1200),
  setup_note text not null default '' check (length(setup_note) <= 600),
  alternative text not null default '' check (length(alternative) <= 600),
  status tonde.requirement_status not null,
  epistemic tonde.epistemic not null default 'REQUIRED',
  resource_type tonde.resource_type, resource_id uuid, substitute_resource_id uuid,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (plan_id, requirement_kind, label),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict,
  foreign key (workspace_id, resource_id) references tonde.production_resources(workspace_id, id) on delete restrict,
  foreign key (workspace_id, substitute_resource_id) references tonde.production_resources(workspace_id, id) on delete restrict,
  -- Two NULLs are both "not named" and must be allowed; only naming the same
  -- resource twice is contradictory.
  check (resource_id is null or substitute_resource_id is null or resource_id <> substitute_resource_id),
  check (status <> 'owned' or resource_id is not null)
);

create index if not exists real_plan_requirements_by_plan on tonde.real_plan_requirements(workspace_id, plan_id);


-- 3. Practical alternatives for a Shot (best quality / fastest / solo / lowest
-- equipment / safest / available light / substitute / AI foundation).
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.alternative_kind as enum ('best_quality','fastest','solo','lowest_equipment','safest',
  'available_light','substitute','ai_foundation')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

create table if not exists tonde.real_plan_alternatives (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  shot_id uuid not null, plan_id uuid not null,
  kind tonde.alternative_kind not null,
  label text not null check (length(btrim(label)) between 1 and 160),
  description text not null default '' check (length(description) <= 1200),
  expected_impact text not null default '' check (length(expected_impact) <= 600),
  tradeoffs text[] not null default '{}',
  sort_order integer not null default 0,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (plan_id, kind),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict
);


-- 4. Capture state. "Captured" is explicitly NOT "approved final"; approval stays
-- on the plan and the Shot.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.capture_status as enum ('not_started','setup','shooting','captured','pickup_needed')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

create table if not exists tonde.shot_capture_state (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  shot_id uuid not null, status tonde.capture_status not null default 'not_started',
  notes text not null default '' check (length(notes) <= 1200),
  captured_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, production_id, shot_id),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict
);


-- 5. Take log. A Take is a field record, not a Result: it may point at the media
-- abstraction once a file exists, and it may exist with no media at all.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.take_status as enum ('recorded','review','good','preferred','unusable','pickup_required')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

create table if not exists tonde.shot_takes (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  shot_id uuid not null, plan_id uuid,
  take_number integer not null check (take_number between 1 and 999),
  status tonde.take_status not null default 'recorded',
  notes text not null default '' check (length(notes) <= 1200),
  media_id uuid,
  recorded_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, shot_id, take_number),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict,
  foreign key (workspace_id, media_id) references tonde.media_files(workspace_id, id) on delete restrict
);

-- At most one preferred Take per Shot, enforced by the database rather than the UI.
create unique index if not exists shot_takes_one_preferred on tonde.shot_takes(workspace_id, shot_id) where status = 'preferred';


-- 6. Field deviation: what was planned vs what actually happened on set.
create table if not exists tonde.shot_deviations (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  shot_id uuid not null, plan_id uuid,
  field text not null check (field in ('camera','lens','movement','stabilization','camera_position','lighting',
    'sound','location','performance','product','duration','other')),
  planned_value text not null default '' check (length(planned_value) <= 600),
  actual_value text not null default '' check (length(actual_value) <= 600),
  reason text not null default '' check (length(reason) <= 600),
  recorded_at timestamptz not null default now(),
  carried boolean not null default true,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict
);


-- 7. Row guards for the new tables: the shared mutation guard (identity immutability,
-- revision management, lock enforcement, approval invalidation) plus the field-level
-- validators the existing tables already receive.
do $$ declare item text; begin
  foreach item in array array['real_plan_requirements','real_plan_alternatives','shot_capture_state','shot_takes','shot_deviations'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;


-- 8. RLS: identical membership/editor model as every other Production entity.
-- Enabling RLS is not optional: policies are inert without it.
do $$ declare item text; begin
  foreach item in array array['real_plan_requirements','real_plan_alternatives','shot_capture_state','shot_takes','shot_deviations'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select, insert, update on tonde.%I to authenticated', item);
  end loop;
end $$;

-- A Take is a log entry, so a genuinely mis-tapped Take may be removed by an editor.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'shot_takes'
      and policyname = 'tenant_delete'
  ) then
    execute $tonde_idem_ddl$create policy tenant_delete on tonde.shot_takes for delete to authenticated using (tonde_private.can_edit_workspace(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant delete on tonde.shot_takes to authenticated;


-- 9. Shared helpers. Not user-facing: revoked from every role and reachable only
-- through the security-definer RPCs below.
create or replace function tonde_private.json_text_array(source jsonb, key text) returns text[]
language sql immutable set search_path = '' as $$
  select coalesce(array(select jsonb_array_elements_text(coalesce(source -> key, '[]'::jsonb))), '{}'::text[]);
$$;

create or replace function tonde_private.json_text(source jsonb, key text, max_length integer) returns text
language sql immutable set search_path = '' as $$
  select left(coalesce(btrim(source ->> key), ''), max_length);
$$;

revoke all on function tonde_private.json_text_array(jsonb,text), tonde_private.json_text(jsonb,text,integer)
  from public, anon, authenticated, service_role;


-- Read-only Setup inventory projection: what the creator actually owns.
create or replace function tonde_private.real_setup_inventory(target_workspace uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
      'id', r.id, 'resource_type', r.resource_type, 'name', r.name, 'manufacturer', r.manufacturer,
      'model', r.model, 'mount', r.mount, 'stabilization', r.stabilization, 'metadata', r.metadata)
      order by r.resource_type, r.name), '[]'::jsonb)
  from tonde.production_resources r
  where r.workspace_id = target_workspace and r.lifecycle = 'active';
$$;

revoke all on function tonde_private.real_setup_inventory(uuid) from public, anon, authenticated, service_role;


-- Deterministic readiness. Explicit requirement facts only; no arbitrary score.
create or replace function tonde_private.real_readiness_state(target_workspace uuid, target_production uuid, target_shot uuid)
returns text language sql stable security definer set search_path = '' as $$
  select case
    when not exists (select 1 from tonde.execution_plans p where p.workspace_id = target_workspace
      and p.production_id = target_production and p.shot_id = target_shot and p.execution_method = 'real') then 'unplanned'
    when exists (select 1 from tonde.execution_plans p where p.workspace_id = target_workspace
      and p.production_id = target_production and p.shot_id = target_shot and p.execution_method = 'real'
      and cardinality(p.safety_flags) > 0) then 'safety_blocked'
    when exists (select 1 from tonde.real_plan_requirements r join tonde.execution_plans p on p.id = r.plan_id
      where r.workspace_id = target_workspace and p.shot_id = target_shot and r.status = 'missing') then 'missing_resource'
    when exists (select 1 from tonde.real_plan_requirements r join tonde.execution_plans p on p.id = r.plan_id
      where r.workspace_id = target_workspace and p.shot_id = target_shot and r.status = 'unverified')
      or exists (select 1 from tonde.execution_plans p where p.workspace_id = target_workspace
        and p.production_id = target_production and p.shot_id = target_shot and p.execution_method = 'real'
        and p.plan_status = 'needs_decision') then 'needs_decision'
    when exists (select 1 from tonde.real_plan_requirements r join tonde.execution_plans p on p.id = r.plan_id
      where r.workspace_id = target_workspace and p.shot_id = target_shot and r.status = 'substitute') then 'ready_with_substitution'
    else 'ready'
  end;
$$;

revoke all on function tonde_private.real_readiness_state(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- One Shot's requirement rollup, used by the Scene and Production summaries.
create or replace function tonde_private.real_requirement_rollup(target_workspace uuid, target_plan uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'owned', count(*) filter (where status = 'owned'),
    'substitute', count(*) filter (where status = 'substitute'),
    'missing', count(*) filter (where status = 'missing'),
    'unverified', count(*) filter (where status = 'unverified'))
  from tonde.real_plan_requirements where workspace_id = target_workspace and plan_id = target_plan;
$$;

revoke all on function tonde_private.real_requirement_rollup(uuid,uuid) from public, anon, authenticated, service_role;


-- The Real plan row for a Shot, as a stable JSON document.
-- jsonb_build_object is variadic but a call may not exceed 100 arguments, so the
-- document is assembled in two halves and concatenated.
create or replace function tonde_private.real_plan_document(target_workspace uuid, target_production uuid, target_shot uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'plan_id', p.id, 'shot_id', p.shot_id, 'execution_method', p.execution_method,
    'approval', p.approval, 'locked', p.locked_at is not null, 'revision', p.revision,
    'plan_status', p.plan_status, 'readiness_note', p.readiness_note,
    'complexity', p.complexity, 'complexity_is_estimate', p.complexity_is_estimate,
    'generated_by', p.generated_by, 'source_operation_id', p.source_operation_id,
    'camera_resource_id', p.camera_resource_id, 'lens_resource_id', p.lens_resource_id,
    'shot_size', p.shot_size, 'camera_position', p.camera_position, 'camera_height', p.camera_height,
    'camera_angle', p.camera_angle, 'framing', p.framing, 'composition', p.composition,
    'perspective_note', p.perspective_note,
    'movement', p.movement, 'movement_purpose', p.movement_purpose, 'stabilization', p.stabilization,
    'capture_fps', p.capture_fps, 'delivery_fps', p.delivery_fps, 'shutter', p.shutter,
    'aperture', p.aperture, 'iso_range', p.iso_range, 'white_balance', p.white_balance,
    'nd_filter', p.nd_filter, 'exposure_note', p.exposure_note,
    'focus_strategy', p.focus_strategy, 'depth_of_field', p.depth_of_field,
    'lighting_intent', p.lighting_intent, 'lighting_plan', p.lighting_plan) || jsonb_build_object(
    'lighting_diagram', p.lighting_diagram,
    'blocking', p.blocking, 'performance', p.performance, 'product_direction', p.product_direction,
    'sound_plan', p.sound_plan, 'microphone_plan', p.microphone_plan, 'sync_strategy', p.sync_strategy,
    'solo_feasibility', p.solo_feasibility, 'crew_roles', to_jsonb(p.crew_roles),
    'environment_requirements', to_jsonb(p.environment_requirements),
    'location_requirements', to_jsonb(p.location_requirements),
    'safety_notes', to_jsonb(p.safety_notes), 'safety_flags', to_jsonb(p.safety_flags),
    'editorial_intent', p.editorial_intent, 'setup_steps', to_jsonb(p.setup_steps),
    'capture_checklist', to_jsonb(p.capture_checklist), 'expected_duration_ms', p.expected_duration_ms,
    'updated_at', p.updated_at)
  from tonde.execution_plans p
  where p.workspace_id = target_workspace and p.production_id = target_production
    and p.shot_id = target_shot and p.execution_method = 'real';
$$;

revoke all on function tonde_private.real_plan_document(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- 10. Read model: the Real execution surface for a whole Production. One round trip
-- for the Studio REAL face, On-Set Mode and the readiness queue.
create or replace function tonde.real_execution_surface(target_workspace uuid, target_production uuid,
  expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare current tonde.productions; payload jsonb;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into current from tonde.productions where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and current.revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  with live_shot as (
    select h.id as shot_id, h.scene_id, h.title, h.purpose, h.subject, h.framing as shot_framing,
      h.execution_method, h.approval, h.locked_at, h.planned_duration_ms, h.sort_order,
      s.title as scene_title, s.sort_order as scene_order,
      p.id as plan_id, p.revision as plan_revision, p.plan_status, p.readiness_note, p.complexity,
      p.expected_duration_ms, p.camera_resource_id, p.lens_resource_id, p.solo_feasibility,
      p.crew_roles, p.safety_flags, p.movement, p.stabilization, p.lighting_intent,
      p.sound_plan, p.updated_at as plan_updated_at,
      tonde_private.real_readiness_state(target_workspace, target_production, h.id) as readiness,
      cs.status as capture_status, cs.notes as capture_notes, cs.captured_at, cs.revision as capture_revision
    from tonde.shots h
    join tonde.scenes s on s.workspace_id = h.workspace_id and s.id = h.scene_id
    left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
      and p.execution_method = 'real'
    left join tonde.shot_capture_state cs on cs.workspace_id = h.workspace_id and cs.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'
  ), shot_row as (
    select live_shot.*,
      (select tonde_private.real_requirement_rollup(target_workspace, live_shot.plan_id)) as requirements,
      (select count(*) from tonde.shot_takes t where t.workspace_id = target_workspace and t.shot_id = live_shot.shot_id) as take_count,
      (select t.id from tonde.shot_takes t where t.workspace_id = target_workspace
        and t.shot_id = live_shot.shot_id and t.status = 'preferred') as preferred_take_id,
      (select count(*) from tonde.shot_deviations d where d.workspace_id = target_workspace
        and d.shot_id = live_shot.shot_id) as deviation_count
    from live_shot
  ),
  -- Each aggregate lives in its own CTE. Nesting an aggregate inside another
  -- aggregate is not legal at one query level, so the rollups are kept separate.
  scene_notes as (
    select scene_id, string_agg(distinct readiness_note, ' · ') as note
    from shot_row where readiness in ('missing_resource','safety_blocked','needs_decision') and readiness_note <> ''
    group by scene_id
  ), scene_rollup as (
    select scene_id, scene_order, scene_title, count(*) as shots,
      count(*) filter (where readiness in ('ready','ready_with_substitution')) as ready,
      count(*) filter (where readiness in ('needs_decision','missing_resource','safety_blocked','unplanned')) as unresolved,
      count(*) filter (where capture_status = 'captured') as captured,
      count(*) filter (where capture_status = 'pickup_needed') as pickup_needed,
      case when count(*) filter (where complexity = 'complex') > 0 then 'complex'
        when count(*) filter (where complexity = 'moderate') > 0 then 'moderate'
        when count(*) filter (where complexity is not null) > 0 then 'quick' end as complexity
    from shot_row group by scene_id, scene_order, scene_title
  ), scenes_json as (
    select coalesce(jsonb_agg(jsonb_build_object('scene_id', r.scene_id, 'order', r.scene_order,
        'title', r.scene_title, 'shots', r.shots, 'ready', r.ready, 'unresolved', r.unresolved,
        'captured', r.captured, 'pickup_needed', r.pickup_needed, 'complexity', r.complexity,
        'unresolved_note', n.note) order by r.scene_order), '[]'::jsonb) as value
    from scene_rollup r left join scene_notes n on n.scene_id = r.scene_id
  ), shots_json as (
    select coalesce(jsonb_agg(jsonb_build_object(
        'shot_id', shot_id, 'scene_id', scene_id, 'scene_order', scene_order, 'scene_title', scene_title,
        'order', sort_order, 'title', title, 'purpose', purpose, 'subject', subject, 'framing', shot_framing,
        'execution_method', execution_method, 'approval', approval, 'locked', locked_at is not null,
        'planned_duration_ms', planned_duration_ms, 'expected_duration_ms', expected_duration_ms,
        'plan_id', plan_id, 'plan_revision', plan_revision, 'plan_status', plan_status,
        'readiness', readiness, 'readiness_note', readiness_note, 'complexity', complexity,
        'camera_resource_id', camera_resource_id, 'lens_resource_id', lens_resource_id,
        'movement', movement, 'stabilization', stabilization, 'lighting_intent', lighting_intent,
        'sound_plan', sound_plan, 'solo_feasibility', solo_feasibility, 'crew_roles', to_jsonb(crew_roles),
        'safety_flags', to_jsonb(safety_flags),
        'requirements', requirements,
        'capture', case when capture_status is null then null else jsonb_build_object(
          'status', capture_status, 'notes', capture_notes, 'captured_at', captured_at, 'revision', capture_revision) end,
        'takes', jsonb_build_object('count', take_count, 'preferred_take_id', preferred_take_id),
        'deviations', deviation_count,
        'plan_updated_at', plan_updated_at)
        order by scene_order, sort_order, shot_id), '[]'::jsonb) as value
    from shot_row
  ), crew_json as (
    select coalesce(jsonb_agg(distinct role), '[]'::jsonb) as value from shot_row, unnest(crew_roles) as role
  ), safety_json as (
    select coalesce(jsonb_agg(distinct flag), '[]'::jsonb) as value from shot_row, unnest(safety_flags) as flag
  ), summary_json as (
    select jsonb_build_object(
        'shots', count(*),
        'planned', count(*) filter (where plan_id is not null),
        'unplanned', count(*) filter (where readiness = 'unplanned'),
        'ready', count(*) filter (where readiness = 'ready'),
        'ready_with_substitution', count(*) filter (where readiness = 'ready_with_substitution'),
        'needs_decision', count(*) filter (where readiness = 'needs_decision'),
        'missing_resource', count(*) filter (where readiness = 'missing_resource'),
        'safety_blocked', count(*) filter (where readiness = 'safety_blocked'),
        'captured', count(*) filter (where capture_status = 'captured'),
        'pickup_needed', count(*) filter (where capture_status = 'pickup_needed'),
        'in_progress', count(*) filter (where capture_status in ('setup','shooting')),
        'approved_plans', count(*) filter (where approval = 'approved' and plan_id is not null),
        'changed_after_approval', count(*) filter (where approval = 'changed_after_approval' and plan_id is not null),
        'crew_roles', (select value from crew_json),
        'safety_flags', (select value from safety_json),
        'complexity', case
          when count(*) filter (where complexity = 'complex') > 0 then 'complex'
          when count(*) filter (where complexity = 'moderate') > 0 then 'moderate'
          when count(*) filter (where complexity is not null) > 0 then 'quick' end) as value
    from shot_row
  ), queue_json as (
    select jsonb_build_object(
      'ready_to_shoot', coalesce(jsonb_agg(shot_id order by scene_order, sort_order) filter (where readiness in ('ready','ready_with_substitution')), '[]'::jsonb),
      'needs_decision', coalesce(jsonb_agg(shot_id order by scene_order, sort_order) filter (where readiness in ('needs_decision','unplanned')), '[]'::jsonb),
      'missing_resource', coalesce(jsonb_agg(shot_id order by scene_order, sort_order) filter (where readiness = 'missing_resource'), '[]'::jsonb),
      'pickup_required', coalesce(jsonb_agg(shot_id order by scene_order, sort_order) filter (where capture_status = 'pickup_needed'
        or exists (select 1 from tonde.shot_takes t where t.workspace_id = target_workspace
          and t.shot_id = shot_row.shot_id and t.status = 'pickup_required')), '[]'::jsonb)) as value
    from shot_row
  )
  select jsonb_build_object(
    'production', jsonb_build_object('id', current.id, 'workspace_id', current.workspace_id, 'title', current.title,
      'production_type', current.production_type, 'execution_method', current.execution_method,
      'planned_duration_ms', current.planned_duration_ms, 'approval', current.approval,
      'locked_at', current.locked_at, 'revision', current.revision, 'lifecycle', current.lifecycle,
      'updated_at', current.updated_at),
    'execution_faces', jsonb_build_array('real','ai'),
    'setup', tonde_private.real_setup_inventory(target_workspace),
    'timing', tonde_private.studio_timing(target_workspace, target_production),
    'scenes', (select value from scenes_json),
    'shots', (select value from shots_json),
    'summary', (select value from summary_json),
    'readiness_queue', (select value from queue_json)
  ) into payload;
  return payload;
end $$;


-- 11. One Shot's full Real plan, including Setup requirements and alternatives.
-- Progressive disclosure: the surface is compact, this is the detail.
create or replace function tonde.real_shot_detail(target_workspace uuid, target_production uuid, target_shot uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare plan jsonb; payload jsonb;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  if not exists (select 1 from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.id = target_shot) then
    raise exception 'Shot unavailable' using errcode = 'P0002';
  end if;
  plan := tonde_private.real_plan_document(target_workspace, target_production, target_shot);
  select jsonb_build_object(
    'shot', (select jsonb_build_object('shot_id', h.id, 'scene_id', h.scene_id, 'title', h.title,
        'purpose', h.purpose, 'subject', h.subject, 'framing', h.framing, 'movement', h.movement,
        'execution_method', h.execution_method, 'approval', h.approval, 'locked', h.locked_at is not null,
        'revision', h.revision, 'planned_duration_ms', h.planned_duration_ms, 'story_beat', h.story_beat,
        'creative_notes', h.creative_notes)
      from tonde.shots h where h.id = target_shot),
    'scene', (select jsonb_build_object('scene_id', s.id, 'title', s.title, 'order', s.sort_order,
        'purpose', s.purpose, 'description', s.description, 'environment_asset_id', s.environment_asset_id)
      from tonde.scenes s join tonde.shots h on h.scene_id = s.id where h.id = target_shot),
    'plan', plan,
    'readiness', tonde_private.real_readiness_state(target_workspace, target_production, target_shot),
    'requirements', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'requirement_kind', r.requirement_kind, 'label', r.label, 'ideal_name', r.ideal_name,
        'detail', r.detail, 'setup_note', r.setup_note, 'alternative', r.alternative, 'status', r.status,
        'epistemic', r.epistemic, 'resource_type', r.resource_type, 'resource_id', r.resource_id,
        'substitute_resource_id', r.substitute_resource_id,
        'resource_name', (select pr.name from tonde.production_resources pr where pr.id = r.resource_id),
        'substitute_name', (select pr.name from tonde.production_resources pr where pr.id = r.substitute_resource_id))
        order by r.sort_order, r.label) from tonde.real_plan_requirements r
        where r.workspace_id = target_workspace and r.shot_id = target_shot), '[]'::jsonb),
    'alternatives', coalesce((select jsonb_agg(jsonb_build_object(
        'id', a.id, 'kind', a.kind, 'label', a.label, 'description', a.description,
        'expected_impact', a.expected_impact, 'tradeoffs', to_jsonb(a.tradeoffs)) order by a.sort_order, a.kind)
        from tonde.real_plan_alternatives a
        where a.workspace_id = target_workspace and a.shot_id = target_shot), '[]'::jsonb),
    'capture', (select jsonb_build_object('id', c.id, 'status', c.status, 'notes', c.notes,
        'captured_at', c.captured_at, 'revision', c.revision)
      from tonde.shot_capture_state c where c.workspace_id = target_workspace and c.shot_id = target_shot),
    'takes', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'take_number', t.take_number,
        'status', t.status, 'notes', t.notes, 'media_id', t.media_id, 'preferred', t.status = 'preferred',
        'recorded_at', t.recorded_at, 'revision', t.revision) order by t.take_number)
      from tonde.shot_takes t where t.workspace_id = target_workspace and t.shot_id = target_shot), '[]'::jsonb),
    'deviations', coalesce((select jsonb_agg(jsonb_build_object('id', d.id, 'field', d.field,
        'planned_value', d.planned_value, 'actual_value', d.actual_value, 'reason', d.reason,
        'recorded_at', d.recorded_at) order by d.recorded_at)
      from tonde.shot_deviations d where d.workspace_id = target_workspace and d.shot_id = target_shot), '[]'::jsonb),
    'setup', tonde_private.real_setup_inventory(target_workspace),
    -- The Brief and the first script line for this Shot, so the Real plan can honour
    -- the creative intent without re-deriving it.
    'brief', (select b.brief from tonde.director_briefs b where b.workspace_id = target_workspace
      and b.production_id = target_production),
    'script_line', (select jsonb_build_object('id', d.id, 'kind', d.line_type, 'content', d.content,
        'duration_ms', d.duration_ms, 'speaker_asset_id', d.speaker_asset_id)
      from tonde.dialogue_lines d where d.workspace_id = target_workspace and d.shot_id = target_shot
      order by d.sort_order, d.id limit 1)
  ) into payload;
  return payload;
end $$;


-- 12. Save a Real plan. Upsert the plan row, then replace its Setup requirements and
-- alternatives in the same transaction. Locks and approvals are enforced by the
-- existing guards, not re-implemented here.
create or replace function tonde.save_real_plan(target_workspace uuid, target_production uuid, target_shot uuid,
  expected_shot_revision integer, plan jsonb, requirements jsonb default '[]'::jsonb,
  alternatives jsonb default '[]'::jsonb, operation_id uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.execution_plans; item jsonb; shot_duration bigint; plan_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_shot_revision);
  if plan is null or jsonb_typeof(plan) <> 'object' then
    raise exception 'A Real plan must be a JSON object' using errcode = '22023';
  end if;

  insert into tonde.execution_plans(workspace_id, production_id, shot_id, execution_method,
    camera_resource_id, lens_resource_id, plan_status, readiness_note, complexity, complexity_is_estimate,
    generated_by, source_operation_id,
    shot_size, camera_position, camera_height, camera_angle, framing, composition, perspective_note,
    movement, movement_purpose, stabilization,
    capture_fps, delivery_fps, shutter, aperture, iso_range, white_balance, nd_filter, exposure_note,
    focus_strategy, depth_of_field,
    lighting_intent, lighting_plan, lighting_diagram, blocking, performance, product_direction,
    sound_plan, microphone_plan, sync_strategy,
    solo_feasibility, crew_roles, environment_requirements, location_requirements,
    safety_notes, safety_flags, editorial_intent, setup_steps, capture_checklist, expected_duration_ms)
  values (target_workspace, target_production, target_shot, 'real',
    nullif(plan->>'camera_resource_id','')::uuid, nullif(plan->>'lens_resource_id','')::uuid,
    coalesce(nullif(plan->>'plan_status',''), 'draft'),
    tonde_private.json_text(plan, 'readiness_note', 600),
    nullif(plan->>'complexity',''),
    coalesce((plan->>'complexity_is_estimate')::boolean, true),
    coalesce(nullif(plan->>'generated_by',''), 'deterministic'), operation_id,
    tonde_private.json_text(plan,'shot_size',80), tonde_private.json_text(plan,'camera_position',400),
    tonde_private.json_text(plan,'camera_height',200), tonde_private.json_text(plan,'camera_angle',200),
    tonde_private.json_text(plan,'framing',300), tonde_private.json_text(plan,'composition',400),
    tonde_private.json_text(plan,'perspective_note',600),
    tonde_private.json_text(plan,'movement',200), tonde_private.json_text(plan,'movement_purpose',600),
    tonde_private.json_text(plan,'stabilization',200),
    tonde_private.json_text(plan,'capture_fps',80), tonde_private.json_text(plan,'delivery_fps',80),
    tonde_private.json_text(plan,'shutter',120), tonde_private.json_text(plan,'aperture',120),
    tonde_private.json_text(plan,'iso_range',120), tonde_private.json_text(plan,'white_balance',160),
    tonde_private.json_text(plan,'nd_filter',200), tonde_private.json_text(plan,'exposure_note',600),
    tonde_private.json_text(plan,'focus_strategy',600), tonde_private.json_text(plan,'depth_of_field',400),
    tonde_private.json_text(plan,'lighting_intent',400), tonde_private.json_text(plan,'lighting_plan',2000),
    coalesce(plan->'lighting_diagram', '{}'::jsonb), tonde_private.json_text(plan,'blocking',2000),
    tonde_private.json_text(plan,'performance',2000), tonde_private.json_text(plan,'product_direction',1200),
    tonde_private.json_text(plan,'sound_plan',2000), tonde_private.json_text(plan,'microphone_plan',1200),
    tonde_private.json_text(plan,'sync_strategy',600),
    nullif(plan->>'solo_feasibility',''), tonde_private.json_text_array(plan,'crew_roles'),
    tonde_private.json_text_array(plan,'environment_requirements'),
    tonde_private.json_text_array(plan,'location_requirements'),
    tonde_private.json_text_array(plan,'safety_notes'), tonde_private.json_text_array(plan,'safety_flags'),
    tonde_private.json_text(plan,'editorial_intent',300), tonde_private.json_text_array(plan,'setup_steps'),
    tonde_private.json_text_array(plan,'capture_checklist'),
    nullif(plan->>'expected_duration_ms','')::bigint)
  on conflict (shot_id, execution_method) do update set
    camera_resource_id = excluded.camera_resource_id, lens_resource_id = excluded.lens_resource_id,
    plan_status = excluded.plan_status, readiness_note = excluded.readiness_note,
    complexity = excluded.complexity, complexity_is_estimate = excluded.complexity_is_estimate,
    generated_by = excluded.generated_by,
    source_operation_id = coalesce(excluded.source_operation_id, tonde.execution_plans.source_operation_id),
    shot_size = excluded.shot_size, camera_position = excluded.camera_position,
    camera_height = excluded.camera_height, camera_angle = excluded.camera_angle,
    framing = excluded.framing, composition = excluded.composition, perspective_note = excluded.perspective_note,
    movement = excluded.movement, movement_purpose = excluded.movement_purpose,
    stabilization = excluded.stabilization,
    capture_fps = excluded.capture_fps, delivery_fps = excluded.delivery_fps, shutter = excluded.shutter,
    aperture = excluded.aperture, iso_range = excluded.iso_range, white_balance = excluded.white_balance,
    nd_filter = excluded.nd_filter, exposure_note = excluded.exposure_note,
    focus_strategy = excluded.focus_strategy, depth_of_field = excluded.depth_of_field,
    lighting_intent = excluded.lighting_intent, lighting_plan = excluded.lighting_plan,
    lighting_diagram = excluded.lighting_diagram, blocking = excluded.blocking,
    performance = excluded.performance, product_direction = excluded.product_direction,
    sound_plan = excluded.sound_plan, microphone_plan = excluded.microphone_plan,
    sync_strategy = excluded.sync_strategy, solo_feasibility = excluded.solo_feasibility,
    crew_roles = excluded.crew_roles, environment_requirements = excluded.environment_requirements,
    location_requirements = excluded.location_requirements, safety_notes = excluded.safety_notes,
    safety_flags = excluded.safety_flags, editorial_intent = excluded.editorial_intent,
    setup_steps = excluded.setup_steps, capture_checklist = excluded.capture_checklist,
    expected_duration_ms = excluded.expected_duration_ms
  returning * into saved;

  delete from tonde.real_plan_requirements where workspace_id = target_workspace and plan_id = saved.id;
  for item in select * from jsonb_array_elements(coalesce(requirements, '[]'::jsonb)) loop
    insert into tonde.real_plan_requirements(workspace_id, production_id, shot_id, plan_id,
      requirement_kind, label, ideal_name, detail, setup_note, alternative, status, epistemic,
      resource_type, resource_id, substitute_resource_id, sort_order)
    values (target_workspace, target_production, target_shot, saved.id,
      (item->>'kind')::tonde.requirement_kind, left(btrim(coalesce(item->>'label','')), 160),
      tonde_private.json_text(item,'ideal_name',200), tonde_private.json_text(item,'detail',1200),
      tonde_private.json_text(item,'setup_note',600), tonde_private.json_text(item,'alternative',600),
      (item->>'status')::tonde.requirement_status,
      coalesce(nullif(item->>'epistemic',''), 'REQUIRED')::tonde.epistemic,
      nullif(item->>'resource_type','')::tonde.resource_type,
      nullif(item->>'resource_id','')::uuid, nullif(item->>'substitute_resource_id','')::uuid,
      coalesce((item->>'sort_order')::integer, 0));
  end loop;

  delete from tonde.real_plan_alternatives where workspace_id = target_workspace and plan_id = saved.id;
  for item in select * from jsonb_array_elements(coalesce(alternatives, '[]'::jsonb)) loop
    insert into tonde.real_plan_alternatives(workspace_id, production_id, shot_id, plan_id, kind, label,
      description, expected_impact, tradeoffs, sort_order)
    values (target_workspace, target_production, target_shot, saved.id,
      (item->>'kind')::tonde.alternative_kind, left(btrim(coalesce(item->>'label','')), 160),
      tonde_private.json_text(item,'description',1200), tonde_private.json_text(item,'expected_impact',600),
      tonde_private.json_text_array(item,'tradeoffs'), coalesce((item->>'sort_order')::integer, 0));
  end loop;

  -- §123: a Real plan may change how long the Shot actually takes. The Shot keeps
  -- timing authority, so the plan writes the Shot's planned duration and returns the
  -- recomputed runtime rather than storing a second, competing duration.
  shot_duration := nullif(plan->>'expected_duration_ms','')::bigint;
  if shot_duration is not null then
    update tonde.shots set planned_duration_ms = shot_duration
      where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  end if;

  select revision into plan_revision from tonde.execution_plans where id = saved.id;
  return jsonb_build_object('plan_id', saved.id, 'shot_id', target_shot, 'plan_revision', plan_revision,
    'approval', (select approval from tonde.execution_plans where id = saved.id),
    'plan_status', saved.plan_status,
    'readiness', tonde_private.real_readiness_state(target_workspace, target_production, target_shot),
    'requirements', (select count(*) from tonde.real_plan_requirements where plan_id = saved.id),
    'alternatives', (select count(*) from tonde.real_plan_alternatives where plan_id = saved.id),
    'timing', tonde_private.studio_timing(target_workspace, target_production));
end $$;


-- 13. Plan approval and locks. Approval requires a creator decision and an unchanged
-- version, which the existing human-acceptance guard enforces.
create or replace function tonde.set_real_plan_approval(target_workspace uuid, target_production uuid, target_shot uuid,
  desired_approval text, expected_shot_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare target_plan tonde.execution_plans; saved tonde.execution_plans;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_shot_revision);
  if desired_approval not in ('draft','needs_review','approved') then
    raise exception 'Unsupported approval state' using errcode = '22023';
  end if;
  select * into target_plan from tonde.execution_plans where workspace_id = target_workspace
    and production_id = target_production and shot_id = target_shot and execution_method = 'real';
  if not found then raise exception 'This Shot has no Real plan to approve' using errcode = 'P0002'; end if;
  if target_plan.locked_at is not null then
    raise exception 'That plan is locked. Unlock it before changing approval.' using errcode = '23514';
  end if;
  update tonde.execution_plans set approval = desired_approval::tonde.approval where id = target_plan.id
    returning * into saved;
  return jsonb_build_object('plan_id', saved.id, 'shot_id', target_shot, 'approval', saved.approval,
    'revision', saved.revision);
end $$;


create or replace function tonde.set_real_plan_lock(target_workspace uuid, target_production uuid, target_shot uuid,
  locked boolean, expected_shot_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.execution_plans;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_shot_revision);
  update tonde.execution_plans set locked_at = case when locked then now() else null end
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'real'
    returning * into saved;
  if saved is null then raise exception 'This Shot has no Real plan to lock' using errcode = 'P0002'; end if;
  return jsonb_build_object('plan_id', saved.id, 'shot_id', target_shot, 'locked', saved.locked_at is not null,
    'revision', saved.revision);
end $$;


-- 14. Capture state. Marking a Shot captured never approves it.
create or replace function tonde.set_shot_capture_state(target_workspace uuid, target_production uuid, target_shot uuid,
  status text, notes text default '', expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.shot_capture_state; current_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', null);
  if status not in ('not_started','setup','shooting','captured','pickup_needed') then
    raise exception 'Unsupported capture status' using errcode = '22023';
  end if;
  if length(coalesce(notes,'')) > 1200 then raise exception 'Capture note is too long' using errcode = '22001'; end if;
  select revision into current_revision from tonde.shot_capture_state
    where workspace_id = target_workspace and shot_id = target_shot;
  if found and expected_revision is not null and current_revision <> expected_revision then
    raise exception 'The capture state changed since you loaded it' using errcode = '40001';
  end if;
  insert into tonde.shot_capture_state(workspace_id, production_id, shot_id, status, notes, captured_at)
  values (target_workspace, target_production, target_shot, status::tonde.capture_status, coalesce(notes,''),
    case when status = 'captured' then now() else null end)
  on conflict (workspace_id, production_id, shot_id) do update set
    status = excluded.status, notes = excluded.notes,
    captured_at = case when excluded.status = 'captured'
      then coalesce(tonde.shot_capture_state.captured_at, now()) else null end
  returning * into saved;
  return jsonb_build_object('shot_id', target_shot, 'status', saved.status, 'notes', saved.notes,
    'captured_at', saved.captured_at, 'revision', saved.revision);
end $$;


-- 15. Take logging. Preferred is exclusive per Shot, enforced by index and upheld here.
create or replace function tonde.save_shot_take(target_workspace uuid, target_production uuid, target_shot uuid,
  take jsonb, expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.shot_takes; target_plan uuid; take_id uuid; wanted_number integer; current_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', null);
  if take is null or jsonb_typeof(take) <> 'object' then
    raise exception 'A Take must be a JSON object' using errcode = '22023';
  end if;
  wanted_number := (take->>'take_number')::integer;
  if wanted_number is null or wanted_number < 1 or wanted_number > 999 then
    raise exception 'A Take needs a number between 1 and 999' using errcode = '22023';
  end if;
  if coalesce(take->>'status','recorded') not in ('recorded','review','good','preferred','unusable','pickup_required') then
    raise exception 'Unsupported Take status' using errcode = '22023';
  end if;
  if length(coalesce(take->>'notes','')) > 1200 then raise exception 'Take note is too long' using errcode = '22001'; end if;
  select id into target_plan from tonde.execution_plans where workspace_id = target_workspace
    and production_id = target_production and shot_id = target_shot and execution_method = 'real';
  take_id := nullif(take->>'id','')::uuid;
  if take_id is not null then
    select revision into current_revision from tonde.shot_takes
      where workspace_id = target_workspace and id = take_id and shot_id = target_shot;
    if not found then raise exception 'That Take is unavailable' using errcode = 'P0002'; end if;
    if expected_revision is not null and current_revision <> expected_revision then
      raise exception 'That Take changed since you loaded it' using errcode = '40001';
    end if;
  end if;
  -- Clear the previous preferred Take first so the exclusive index is never violated.
  if coalesce(take->>'status','recorded') = 'preferred' then
    update tonde.shot_takes set status = 'good'
      where workspace_id = target_workspace and shot_id = target_shot and status = 'preferred'
        and (take_id is null or id <> take_id);
  end if;
  insert into tonde.shot_takes(workspace_id, production_id, shot_id, plan_id, take_number, status, notes, media_id, recorded_at)
  values (target_workspace, target_production, target_shot, target_plan, wanted_number,
    coalesce(take->>'status','recorded')::tonde.take_status, coalesce(take->>'notes',''),
    nullif(take->>'media_id','')::uuid, coalesce((take->>'recorded_at')::timestamptz, now()))
  on conflict (workspace_id, shot_id, take_number) do update set
    status = excluded.status, notes = excluded.notes, media_id = excluded.media_id,
    plan_id = coalesce(excluded.plan_id, tonde.shot_takes.plan_id)
  returning * into saved;
  return jsonb_build_object('take_id', saved.id, 'shot_id', target_shot, 'take_number', saved.take_number,
    'status', saved.status, 'preferred', saved.status = 'preferred', 'revision', saved.revision,
    'capture', (select jsonb_build_object('status', c.status, 'revision', c.revision)
      from tonde.shot_capture_state c where c.workspace_id = target_workspace and c.shot_id = target_shot));
end $$;


create or replace function tonde.delete_shot_take(target_workspace uuid, target_production uuid, target_shot uuid, target_take uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare removed tonde.shot_takes;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', null);
  delete from tonde.shot_takes where workspace_id = target_workspace and production_id = target_production
    and shot_id = target_shot and id = target_take returning * into removed;
  if removed is null then raise exception 'That Take is unavailable' using errcode = 'P0002'; end if;
  return jsonb_build_object('take_id', removed.id, 'shot_id', target_shot, 'take_number', removed.take_number);
end $$;


-- 16. Field deviations: the original plan is never destroyed by recording what
-- actually happened on set.
create or replace function tonde.record_shot_deviation(target_workspace uuid, target_production uuid, target_shot uuid,
  deviation jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.shot_deviations; target_plan uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', null);
  if deviation is null or jsonb_typeof(deviation) <> 'object' then
    raise exception 'A deviation must be a JSON object' using errcode = '22023';
  end if;
  if coalesce(deviation->>'field','') not in ('camera','lens','movement','stabilization','camera_position',
    'lighting','sound','location','performance','product','duration','other') then
    raise exception 'Unsupported deviation field' using errcode = '22023';
  end if;
  select id into target_plan from tonde.execution_plans where workspace_id = target_workspace
    and production_id = target_production and shot_id = target_shot and execution_method = 'real';
  insert into tonde.shot_deviations(workspace_id, production_id, shot_id, plan_id, field, planned_value,
    actual_value, reason)
  values (target_workspace, target_production, target_shot, target_plan, deviation->>'field',
    tonde_private.json_text(deviation,'planned_value',600), tonde_private.json_text(deviation,'actual_value',600),
    tonde_private.json_text(deviation,'reason',600))
  returning * into saved;
  return jsonb_build_object('deviation_id', saved.id, 'shot_id', target_shot, 'field', saved.field,
    'planned_value', saved.planned_value, 'actual_value', saved.actual_value, 'recorded_at', saved.recorded_at);
end $$;


-- 17. Privileges: authenticated only, never anon or service_role. Private helpers
-- stay unreachable from the API.
revoke all on function tonde.real_execution_surface(uuid,uuid,integer),
  tonde.real_shot_detail(uuid,uuid,uuid),
  tonde.save_real_plan(uuid,uuid,uuid,integer,jsonb,jsonb,jsonb,uuid),
  tonde.set_real_plan_approval(uuid,uuid,uuid,text,integer),
  tonde.set_real_plan_lock(uuid,uuid,uuid,boolean,integer),
  tonde.set_shot_capture_state(uuid,uuid,uuid,text,text,integer),
  tonde.save_shot_take(uuid,uuid,uuid,jsonb,integer),
  tonde.delete_shot_take(uuid,uuid,uuid,uuid),
  tonde.record_shot_deviation(uuid,uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.real_execution_surface(uuid,uuid,integer),
  tonde.real_shot_detail(uuid,uuid,uuid),
  tonde.save_real_plan(uuid,uuid,uuid,integer,jsonb,jsonb,jsonb,uuid),
  tonde.set_real_plan_approval(uuid,uuid,uuid,text,integer),
  tonde.set_real_plan_lock(uuid,uuid,uuid,boolean,integer),
  tonde.set_shot_capture_state(uuid,uuid,uuid,text,text,integer),
  tonde.save_shot_take(uuid,uuid,uuid,jsonb,integer),
  tonde.delete_shot_take(uuid,uuid,uuid,uuid),
  tonde.record_shot_deviation(uuid,uuid,uuid,jsonb)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050017_ai_creation.sql
-- ==========================================================================

-- 017 - Prompt 7 -- TONDE AI CREATION & HYBRID DIRECTOR
--
-- One Master Production. AI Creation is a face of the same Production, and SHOOT /
-- GENERATE / SHOOT + AI are execution methods of the same canonical Shot. This
-- migration adds no second Production, Scene or Shot model.
--
-- Capability truth is a first-class rule here. TONDE holds NO vendor capability
-- facts of its own: a model profile carries capability metadata only when it was
-- declared for a workspace or reported by a connected provider. Everything else is
-- UNKNOWN or REQUIRES CONNECTION, and routing says so rather than guessing from a
-- model name. No pricing is fabricated: cost is 'known' only when a profile carries
-- a verified amount, otherwise it is 'unknown'.
--
-- Additive and forward-only. Migrations 001-016 are untouched.
begin;


-- 1. Vocabulary. Uppercase capability states match the epistemic labels migration 016
-- already uses for claims.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_capability_state as enum
  ('SUPPORTED','PARTIALLY SUPPORTED','UNSUPPORTED','UNKNOWN','REQUIRES CONNECTION')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_operation as enum
  ('image','video','image_to_video','video_to_video','voice','speech','music','sound_effect',
   'upscale','background_removal','image_edit','frame_interpolation','lipsync','compositing')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_connection_state as enum ('not_connected','connected','unavailable')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_readiness as enum
  ('unplanned','stale','needs_reference','needs_model','needs_decision','unsupported',
   'provider_not_connected','cost_confirmation','ready_to_generate','manual_export')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_attempt_status as enum
  ('planned','queued','submitted','processing','succeeded','partial','failed','cancelled','expired')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_attempt_mode as enum ('live','manual')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_lock_scope as enum ('character','world','product','style')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_continuity_priority as enum ('MUST PRESERVE','SHOULD PRESERVE','FLEXIBLE')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_reference_role as enum
  ('face','full_body','profile','wardrobe','expression','pose','lighting_neutral',
   'environment','product','style','first_frame','last_frame','storyboard','plate','voice')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_batch_scope as enum ('shot','scene','selection','production')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_batch_state as enum ('confirmed','running','partial','succeeded','failed','cancelled')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.ai_batch_item_state as enum ('pending','blocked','submitted','succeeded','failed','skipped')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Provider catalog. Identity only: which providers exist and whether using them
-- needs a connection. There is deliberately no capability column here, so a provider
-- name can never imply a capability.
create table if not exists tonde.ai_providers (
  key text primary key check (length(key) between 1 and 60),
  label text not null check (length(label) between 1 and 120),
  connection_required boolean not null default true,
  manual_export_supported boolean not null default true,
  note text not null default '' check (length(note) <= 600),
  created_at timestamptz not null default now()
);

insert into tonde.ai_providers(key, label, connection_required, note) values
  ('manual', 'Manual export', false, 'No connection. TONDE compiles the prompt, references and settings for you to run yourself.'),
  ('runway', 'Runway', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.'),
  ('kling', 'Kling', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.'),
  ('veo', 'Veo', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.'),
  ('sora', 'Sora', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.'),
  ('midjourney', 'Midjourney', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.'),
  ('flux', 'FLUX', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.'),
  ('elevenlabs', 'ElevenLabs', true, 'TONDE holds no capability facts for this provider until you declare them or it reports them.')
on conflict (key) do nothing;


-- 3. Model capability profiles, separate from provider account configuration.
-- workspace_id is null for TONDE's own catalog and non-null for a model the creator
-- declared. 'TONDE KNOWS THIS MODEL', 'USER HAS THIS MODEL AVAILABLE' and 'TONDE IS
-- CONNECTED TO THIS PROVIDER' are three different facts and are never conflated.
create table if not exists tonde.ai_model_profiles (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid references tonde.workspaces(id) on delete restrict,
  provider_key text not null references tonde.ai_providers(key) on delete restrict,
  model_key text not null check (length(model_key) between 1 and 120),
  label text not null default '' check (length(label) <= 160),
  operation tonde.ai_operation not null,
  capability_state tonde.ai_capability_state not null default 'UNKNOWN',
  modalities text[] not null default '{}',
  supports_image_reference boolean not null default false,
  max_reference_images integer check (max_reference_images >= 0),
  supports_first_frame boolean not null default false,
  supports_last_frame boolean not null default false,
  supports_seed boolean not null default false,
  supports_negative_prompt boolean not null default false,
  supports_camera_control boolean not null default false,
  supports_audio boolean not null default false,
  supports_image_edit boolean not null default false,
  supports_lipsync boolean not null default false,
  max_duration_ms bigint check (max_duration_ms is null or max_duration_ms > 0),
  aspect_ratios text[] not null default '{}',
  resolutions text[] not null default '{}',
  cost_unit text not null default '' check (length(cost_unit) <= 80),
  cost_amount numeric(12,4) check (cost_amount is null or cost_amount >= 0),
  cost_currency text not null default '' check (length(cost_currency) <= 8),
  cost_known boolean not null default false,
  speed_note text not null default '' check (length(speed_note) <= 300),
  identity_note text not null default '' check (length(identity_note) <= 300),
  product_fidelity_note text not null default '' check (length(product_fidelity_note) <= 300),
  availability text not null default 'unknown' check (availability in ('available','deprecated','unknown')),
  safety_note text not null default '' check (length(safety_note) <= 600),
  capability_notes jsonb not null default '{}'::jsonb check (jsonb_typeof(capability_notes) = 'object'),
  source text not null default 'declared' check (source in ('declared','provider','catalog')),
  declared_by uuid references auth.users(id) on delete set null,
  lifecycle tonde.lifecycle not null default 'active',
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  -- A capability claim is only as strong as its declaration: a profile that claims
  -- SUPPORTED must say where the claim came from.
  check (capability_state <> 'SUPPORTED' or source in ('declared','provider'))
);

create unique index if not exists ai_model_profiles_global_key on tonde.ai_model_profiles(provider_key, model_key, operation)
  where workspace_id is null;

create unique index if not exists ai_model_profiles_workspace_key on tonde.ai_model_profiles(workspace_id, provider_key, model_key, operation)
  where workspace_id is not null;

create index if not exists ai_model_profiles_by_workspace on tonde.ai_model_profiles(workspace_id, provider_key);


-- 4. Provider connection state, per workspace. A credential *reference* only: the
-- migration stores no secret and TONDE reads none.
create table if not exists tonde.ai_provider_connections (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references tonde.workspaces(id) on delete restrict,
  provider_key text not null references tonde.ai_providers(key) on delete restrict,
  state tonde.ai_connection_state not null default 'not_connected',
  credential_reference text not null default '' check (length(credential_reference) <= 200),
  note text not null default '' check (length(note) <= 600),
  last_checked_at timestamptz,
  connected_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, provider_key), unique (workspace_id, id)
);


-- 5. AI execution plans extend the existing per-Shot execution plan, exactly as the
-- Real plan does. One Shot, one AI plan; the shared camera/lighting/performance
-- columns are reused so both faces describe the same Shot in the same language.
-- Readiness is COMPUTED from declared facts and never stored, exactly as derived timing
-- is computed in migration 015: a cached readiness column would go stale the moment a
-- reference, connection or Shot revision changed.
alter table tonde.execution_plans add column if not exists prompt_version integer not null default 0 check (prompt_version >= 0);

alter table tonde.execution_plans add column if not exists source_shot_revision integer
  check (source_shot_revision is null or source_shot_revision > 0);

alter table tonde.execution_plans add column if not exists source_versions jsonb not null default '{}'::jsonb
  check (jsonb_typeof(source_versions) = 'object');

alter table tonde.execution_plans add column if not exists canonical_prompt jsonb not null default '{}'::jsonb
  check (jsonb_typeof(canonical_prompt) = 'object');

alter table tonde.execution_plans add column if not exists provider_prompt text not null default ''
  check (length(provider_prompt) <= 8000);

alter table tonde.execution_plans add column if not exists provider_prompt_edited boolean not null default false;

alter table tonde.execution_plans add column if not exists provider_prompt_edited_at timestamptz;

alter table tonde.execution_plans add column if not exists provider_target text;

alter table tonde.execution_plans add column if not exists model_profile_id uuid;

alter table tonde.execution_plans add column if not exists fallback_model_profile_id uuid;

alter table tonde.execution_plans add column if not exists routing jsonb not null default '{}'::jsonb
  check (jsonb_typeof(routing) = 'object');

alter table tonde.execution_plans add column if not exists first_frame jsonb not null default '{}'::jsonb
  check (jsonb_typeof(first_frame) = 'object');

alter table tonde.execution_plans add column if not exists last_frame jsonb not null default '{}'::jsonb
  check (jsonb_typeof(last_frame) = 'object');

alter table tonde.execution_plans add column if not exists motion jsonb not null default '{}'::jsonb
  check (jsonb_typeof(motion) = 'object');

alter table tonde.execution_plans add column if not exists audio jsonb not null default '{}'::jsonb
  check (jsonb_typeof(audio) = 'object');

alter table tonde.execution_plans add column if not exists continuity jsonb not null default '{}'::jsonb
  check (jsonb_typeof(continuity) = 'object');

alter table tonde.execution_plans add column if not exists hybrid jsonb not null default '{}'::jsonb
  check (jsonb_typeof(hybrid) = 'object');

alter table tonde.execution_plans add column if not exists negative_constraints text[] not null default '{}';

alter table tonde.execution_plans add column if not exists limitations text[] not null default '{}';

alter table tonde.execution_plans add column if not exists aspect_ratio text not null default ''
  check (length(aspect_ratio) <= 20);

alter table tonde.execution_plans add column if not exists cost_state text not null default 'unknown'
  check (cost_state in ('known','unknown'));

alter table tonde.execution_plans add column if not exists cost_amount numeric(12,4)
  check (cost_amount is null or cost_amount >= 0);

alter table tonde.execution_plans add column if not exists cost_currency text not null default ''
  check (length(cost_currency) <= 8);

alter table tonde.execution_plans add column if not exists cost_note text not null default ''
  check (length(cost_note) <= 400);

alter table tonde.execution_plans add column if not exists model_version text not null default ''
  check (length(model_version) <= 120);


-- 6. Reference assets attached to one AI plan, with the role they serve. Prompts
-- carry only the references that are relevant; the continuity packet selects them.
create table if not exists tonde.ai_shot_references (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, shot_id uuid not null, plan_id uuid not null,
  reference_role tonde.ai_reference_role not null,
  priority tonde.ai_continuity_priority not null default 'SHOULD PRESERVE',
  asset_id uuid, media_id uuid,
  origin text not null default 'asset'
    check (origin in ('asset','upload','generated_result','storyboard','captured_frame','composite')),
  source_attempt_id uuid,
  note text not null default '' check (length(note) <= 400),
  sort_order bigint not null default 1024 check (sort_order >= 0),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  check (num_nonnulls(asset_id, media_id) = 1),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict,
  foreign key (workspace_id, asset_id) references tonde.assets(workspace_id, id) on delete restrict,
  foreign key (workspace_id, media_id) references tonde.media_files(workspace_id, id) on delete restrict
);

create index if not exists ai_shot_references_by_plan on tonde.ai_shot_references(workspace_id, plan_id);


-- 7. Continuity locks. A lock states what must stay true across Shots and what the
-- Director may vary without asking.
create table if not exists tonde.ai_continuity_locks (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  scope tonde.ai_lock_scope not null,
  subject_id uuid, label text not null default '' check (length(label) <= 200),
  locked boolean not null default true,
  priority tonde.ai_continuity_priority not null default 'MUST PRESERVE',
  locked_traits text[] not null default '{}',
  allowed_variations text[] not null default '{}',
  prohibited_changes text[] not null default '{}',
  identity_truth text not null default '' check (length(identity_truth) <= 400),
  consent_note text not null default '' check (length(consent_note) <= 400),
  note text not null default '' check (length(note) <= 600),
  locked_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, subject_id) references tonde.assets(workspace_id, id) on delete restrict
);

create unique index if not exists ai_continuity_locks_by_subject on tonde.ai_continuity_locks(workspace_id, production_id, scope, subject_id)
  where subject_id is not null;

create unique index if not exists ai_continuity_locks_by_scope on tonde.ai_continuity_locks(workspace_id, production_id, scope)
  where subject_id is null;

create index if not exists ai_continuity_locks_by_production on tonde.ai_continuity_locks(workspace_id, production_id);


-- 8. Generation attempts. Every external generation is a first-class record, and the
-- idempotency key is what stops a retry from spending money twice.
create table if not exists tonde.ai_generation_attempts (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, shot_id uuid not null,
  plan_id uuid not null,
  operation tonde.ai_operation not null,
  attempt_number integer not null check (attempt_number > 0),
  provider_key text not null,
  model_profile_id uuid,
  model_key text not null default '' check (length(model_key) <= 120),
  model_version text not null default '' check (length(model_version) <= 120),
  prompt_version integer not null default 0 check (prompt_version >= 0),
  source_shot_revision integer check (source_shot_revision is null or source_shot_revision > 0),
  idempotency_key text not null check (length(idempotency_key) between 8 and 200),
  mode tonde.ai_attempt_mode not null default 'live',
  status tonde.ai_attempt_status not null default 'planned',
  external_job_id text check (external_job_id is null or length(external_job_id) <= 200),
  seed bigint,
  settings jsonb not null default '{}'::jsonb check (jsonb_typeof(settings) = 'object'),
  input_references jsonb not null default '[]'::jsonb check (jsonb_typeof(input_references) = 'array'),
  request_summary jsonb not null default '{}'::jsonb check (jsonb_typeof(request_summary) = 'object'),
  cost_state text not null default 'unknown' check (cost_state in ('known','unknown')),
  cost_amount numeric(12,4) check (cost_amount is null or cost_amount >= 0),
  cost_currency text not null default '' check (length(cost_currency) <= 8),
  retryable boolean not null default false,
  retry_of uuid,
  started_at timestamptz, completed_at timestamptz,
  failure_code text not null default '' check (length(failure_code) <= 80),
  failure_message text not null default '' check (length(failure_message) <= 800),
  output_media_id uuid, result_id uuid,
  result_state tonde.result_state not null default 'raw',
  selected boolean not null default false,
  creator_rating integer check (creator_rating between 1 and 5),
  creator_decision text not null default '' check (creator_decision in ('','keep','reject','needs_review')),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, idempotency_key), unique (workspace_id, id),
  unique (workspace_id, shot_id, attempt_number),
  -- Cost is either a known amount or unknown. There is no third state and no zero.
  check (cost_state <> 'known' or (cost_amount is not null and cost_currency <> '')),
  check (cost_state <> 'unknown' or cost_amount is null),
  -- A finished attempt named a real output; a failed one says why.
  check (status not in ('succeeded','partial') or output_media_id is not null),
  check (status <> 'failed' or failure_code <> ''),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict,
  foreign key (workspace_id, model_profile_id) references tonde.ai_model_profiles(workspace_id, id) on delete restrict,
  foreign key (workspace_id, retry_of) references tonde.ai_generation_attempts(workspace_id, id) on delete restrict,
  foreign key (workspace_id, output_media_id) references tonde.media_files(workspace_id, id) on delete restrict,
  foreign key (workspace_id, result_id) references tonde.results(workspace_id, id) on delete restrict
);

-- One selected Result per Shot. Selected means "chosen current output", not approved.
create unique index if not exists ai_generation_attempts_selected on tonde.ai_generation_attempts(workspace_id, shot_id)
  where selected;

create index if not exists ai_generation_attempts_by_shot on tonde.ai_generation_attempts(workspace_id, production_id, shot_id, attempt_number);

create index if not exists ai_generation_attempts_by_job on tonde.ai_generation_attempts(workspace_id, external_job_id)
  where external_job_id is not null;

-- Submission dedupe that does not depend on the provider: one live attempt per
-- (shot, prompt version, model) may be in flight at a time.
create unique index if not exists ai_generation_attempts_in_flight on tonde.ai_generation_attempts(workspace_id, shot_id, prompt_version, provider_key, model_key)
  where status in ('queued','submitted','processing');


-- 9. Batch generation. A batch is a durable job with per-Shot items, so eight of ten
-- successes are preserved when two fail.
create table if not exists tonde.ai_generation_batches (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  scope tonde.ai_batch_scope not null,
  scene_id uuid,
  state tonde.ai_batch_state not null default 'confirmed',
  confirmation_required boolean not null default false,
  confirmation_note text not null default '' check (length(confirmation_note) <= 400),
  confirmed_at timestamptz, confirmed_by uuid,
  cost_state text not null default 'unknown' check (cost_state in ('known','unknown')),
  estimated_cost_amount numeric(12,4),
  estimated_cost_currency text not null default '' check (length(estimated_cost_currency) <= 8),
  shot_count integer not null default 0 check (shot_count >= 0),
  blocked_count integer not null default 0 check (blocked_count >= 0),
  unknown_cost_count integer not null default 0 check (unknown_cost_count >= 0),
  note text not null default '' check (length(note) <= 600),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  check (cost_state <> 'known' or estimated_cost_amount is not null),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, scene_id) references tonde.scenes(workspace_id, id) on delete restrict
);

create table if not exists tonde.ai_generation_batch_items (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  batch_id uuid not null, shot_id uuid not null,
  state tonde.ai_batch_item_state not null default 'pending',
  blocked_reason text not null default '' check (length(blocked_reason) <= 200),
  attempt_id uuid,
  cost_state text not null default 'unknown' check (cost_state in ('known','unknown')),
  cost_amount numeric(12,4),
  cost_currency text not null default '' check (length(cost_currency) <= 8),
  failure_code text not null default '' check (length(failure_code) <= 80),
  failure_message text not null default '' check (length(failure_message) <= 800),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (batch_id, shot_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, batch_id) references tonde.ai_generation_batches(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, attempt_id) references tonde.ai_generation_attempts(workspace_id, id) on delete restrict
);

create index if not exists ai_generation_batch_items_by_batch on tonde.ai_generation_batch_items(workspace_id, batch_id);


-- Material external spend is confirmed by a creator, not assumed. Confirmation is kept
-- beside the plan rather than inside it so that confirming cost never rewrites plan
-- content or invalidates an approval.
create table if not exists tonde.ai_cost_confirmations (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, shot_id uuid not null,
  prompt_version integer not null check (prompt_version > 0),
  provider_key text not null, model_key text not null default '' check (length(model_key) <= 120),
  cost_state text not null default 'unknown' check (cost_state in ('known','unknown')),
  cost_amount numeric(12,4), cost_currency text not null default '' check (length(cost_currency) <= 8),
  note text not null default '' check (length(note) <= 400),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, shot_id, prompt_version),
  check (cost_state <> 'known' or (cost_amount is not null and cost_currency <> '')),
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict
);


-- 10. Row guards: the shared mutation guard (identity immutability, revision
-- management, lock enforcement, approval invalidation) on every new table.
do $$ declare item text; begin
  foreach item in array array['ai_model_profiles','ai_provider_connections','ai_shot_references',
    'ai_continuity_locks','ai_generation_attempts','ai_generation_batches','ai_generation_batch_items',
    'ai_cost_confirmations'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;


-- 11. RLS. Enabling RLS is not optional: policies are inert without it. The provider
-- catalog is global reference data; every other table is tenant-scoped.
alter table tonde.ai_providers enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'ai_providers'
      and policyname = 'catalog_read'
  ) then
    execute $tonde_idem_ddl$create policy catalog_read on tonde.ai_providers for select to authenticated using (true)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.ai_providers to authenticated;


alter table tonde.ai_model_profiles enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'ai_model_profiles'
      and policyname = 'catalog_read'
  ) then
    execute $tonde_idem_ddl$create policy catalog_read on tonde.ai_model_profiles for select to authenticated
  using (workspace_id is null or tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'ai_model_profiles'
      and policyname = 'tenant_insert'
  ) then
    execute $tonde_idem_ddl$create policy tenant_insert on tonde.ai_model_profiles for insert to authenticated
  with check (workspace_id is not null and tonde_private.can_edit_workspace(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'ai_model_profiles'
      and policyname = 'tenant_update'
  ) then
    execute $tonde_idem_ddl$create policy tenant_update on tonde.ai_model_profiles for update to authenticated
  using (workspace_id is not null and tonde_private.can_edit_workspace(workspace_id))
  with check (workspace_id is not null and tonde_private.can_edit_workspace(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select, insert, update on tonde.ai_model_profiles to authenticated;


do $$ declare item text; begin
  foreach item in array array['ai_provider_connections','ai_shot_references','ai_continuity_locks',
    'ai_generation_attempts','ai_generation_batches','ai_generation_batch_items',
    'ai_cost_confirmations'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select, insert, update on tonde.%I to authenticated', item);
  end loop;
end $$;

-- A planned attempt that was never submitted is a log entry the creator may remove;
-- a submitted one is spend and history, and stays.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'ai_generation_attempts'
      and policyname = 'tenant_delete'
  ) then
    execute $tonde_idem_ddl$create policy tenant_delete on tonde.ai_generation_attempts for delete to authenticated
  using (tonde_private.can_edit_workspace(workspace_id) and status in ('planned','cancelled','expired'))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant delete on tonde.ai_generation_attempts to authenticated;


-- 12. Private helpers. Not user-facing: revoked from every role and reachable only
-- through the security-definer RPCs below.
create or replace function tonde_private.ai_json_bool(source jsonb, key text, fallback boolean) returns boolean
language sql immutable set search_path = '' as $$
  select case when source ? key and jsonb_typeof(source -> key) = 'boolean'
    then (source ->> key)::boolean else fallback end;
$$;

create or replace function tonde_private.ai_json_int(source jsonb, key text) returns integer
language sql immutable set search_path = '' as $$
  select case when source ? key and jsonb_typeof(source -> key) = 'number'
    then (source ->> key)::integer else null end;
$$;

create or replace function tonde_private.ai_json_text_array(source jsonb, key text) returns text[]
language sql immutable set search_path = '' as $$
  select coalesce(array(select jsonb_array_elements_text(coalesce(source -> key, '[]'::jsonb))), '{}'::text[]);
$$;

revoke all on function tonde_private.ai_json_bool(jsonb,text,boolean), tonde_private.ai_json_int(jsonb,text),
  tonde_private.ai_json_text_array(jsonb,text) from public, anon, authenticated, service_role;


-- Connection truth for one provider in one workspace, as a stable JSON document.
create or replace function tonde_private.ai_connection(target_workspace uuid, target_provider text) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((
    select jsonb_build_object('provider_key', c.provider_key, 'state', c.state,
      'credential_reference', c.credential_reference, 'note', c.note,
      'connected_at', c.connected_at, 'last_checked_at', c.last_checked_at)
    from tonde.ai_provider_connections c
    where c.workspace_id = target_workspace and c.provider_key = target_provider),
    jsonb_build_object('provider_key', target_provider, 'state', 'not_connected',
      'credential_reference', '', 'note', 'No connection is declared for this provider in this workspace.',
      'connected_at', null, 'last_checked_at', null));
$$;

revoke all on function tonde_private.ai_connection(uuid,text) from public, anon, authenticated, service_role;


-- Primary operation required by a Shot's intent, derived from what the Shot asks for.
create or replace function tonde_private.ai_primary_operation(target_workspace uuid, target_production uuid, target_shot uuid)
returns tonde.ai_operation language sql stable security definer set search_path = '' as $$
  select case
    when h.execution_method = 'hybrid' then 'image_to_video'::tonde.ai_operation
    when coalesce(pl.audio -> 'narration' ->> 'needed', 'false') = 'true' then 'speech'::tonde.ai_operation
    when coalesce(pl.motion ->> 'needed', 'false') = 'true' then 'image_to_video'::tonde.ai_operation
    else 'video'::tonde.ai_operation
  end
  from tonde.shots h
  left join tonde.execution_plans pl on pl.workspace_id = h.workspace_id and pl.shot_id = h.id
    and pl.execution_method = 'ai'
  where h.workspace_id = target_workspace and h.production_id = target_production and h.id = target_shot;
$$;

revoke all on function tonde_private.ai_primary_operation(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- Deterministic AI readiness. Declared facts only, and every blocking reason is a
-- fact the creator can act on rather than a score.
create or replace function tonde_private.ai_readiness_state(target_workspace uuid, target_production uuid, target_shot uuid)
returns tonde.ai_readiness language plpgsql stable security definer set search_path = '' as $$
declare plan_row tonde.execution_plans; shot_revision integer; shot_method tonde.execution_method;
  connection_state tonde.ai_connection_state; profile tonde.ai_model_profiles;
  must_references integer; present_references integer;
begin
  select revision, execution_method into shot_revision, shot_method from tonde.shots
    where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  if not found then return 'unplanned'; end if;
  if shot_method = 'real' then return 'unplanned'; end if;
  select * into plan_row from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  if not found then return 'unplanned'; end if;
  if plan_row.plan_status = 'needs_decision' then return 'needs_decision'; end if;
  -- A prompt compiled against a Shot revision that has since changed is stale, never
  -- quietly current.
  if plan_row.source_shot_revision is not null and plan_row.source_shot_revision <> shot_revision then
    return 'stale';
  end if;
  if plan_row.prompt_version = 0 then return 'needs_model'; end if;
  -- MUST PRESERVE references are the ones generation cannot proceed without.
  select count(*) filter (where priority = 'MUST PRESERVE'),
    count(*) filter (where priority = 'MUST PRESERVE' and (asset_id is not null or media_id is not null))
    into must_references, present_references
  from tonde.ai_shot_references
  where workspace_id = target_workspace and plan_id = plan_row.id;
  if must_references > present_references then return 'needs_reference'; end if;
  if plan_row.model_profile_id is null then return 'needs_model'; end if;
  select * into profile from tonde.ai_model_profiles
    where workspace_id in (target_workspace) and id = plan_row.model_profile_id;
  if not found then return 'needs_model'; end if;
  if profile.capability_state = 'UNSUPPORTED' or profile.availability = 'deprecated' then return 'unsupported'; end if;
  if profile.lifecycle <> 'active' then return 'needs_model'; end if;
  if plan_row.model_version = '' and profile.capability_state = 'UNKNOWN' then return 'needs_decision'; end if;
  -- Capability truth: a control the selected profile does not support is never
  -- presented as usable, so the plan cannot be ready while it relies on one.
  if length(coalesce(plan_row.first_frame ->> 'source','')) > 0 and not profile.supports_first_frame then
    return 'unsupported';
  end if;
  if length(coalesce(plan_row.last_frame ->> 'source','')) > 0 and not profile.supports_last_frame then
    return 'unsupported';
  end if;
  if coalesce(plan_row.audio ->> 'needed','false') = 'true' and not profile.supports_audio then
    return 'unsupported';
  end if;
  if coalesce(plan_row.routing -> 'cost_confirmation' ->> 'required','false') = 'true'
    and not exists (select 1 from tonde.ai_cost_confirmations cc
      where cc.workspace_id = target_workspace and cc.shot_id = target_shot
        and cc.prompt_version = plan_row.prompt_version) then
    return 'cost_confirmation';
  end if;
  select c.state into connection_state from tonde.ai_provider_connections c
    where c.workspace_id = target_workspace and c.provider_key = plan_row.provider_target;
  if plan_row.provider_target is null or plan_row.provider_target = ''
    or plan_row.provider_target = 'manual' then
    return 'manual_export';
  end if;
  if connection_state is null or connection_state <> 'connected' then return 'provider_not_connected'; end if;
  if not profile.supports_image_reference
    and exists (select 1 from tonde.ai_shot_references r where r.workspace_id = target_workspace
      and r.plan_id = plan_row.id and r.priority = 'MUST PRESERVE') then
    return 'unsupported';
  end if;
  return 'ready_to_generate';
end $$;

revoke all on function tonde_private.ai_readiness_state(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- Does a declared profile cover what this Shot requires? Returns the capability
-- verdict and the reasons, so the Model Router and the UI cannot disagree.
create or replace function tonde_private.ai_capability_check(target_workspace uuid, target_profile uuid, target_production uuid, target_shot uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare profile tonde.ai_model_profiles; plan_row tonde.execution_plans; shot_row tonde.shots;
  reasons text[] := '{}'; partial text[] := '{}'; state tonde.ai_capability_state;
  blocking text[] := '{}'; needs_audio boolean; must_references integer; duration_ms bigint;
begin
  select * into profile from tonde.ai_model_profiles
    where id = target_profile and (workspace_id = target_workspace or workspace_id is null);
  if not found then
    return jsonb_build_object('state', 'UNKNOWN', 'reasons', to_jsonb(array['No model profile is declared for that identifier.']),
      'partial', '[]'::jsonb, 'blocking', to_jsonb(array['No model profile is declared for that identifier.']),
      'requires_connection', true);
  end if;
  select * into shot_row from tonde.shots
    where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  select * into plan_row from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  -- Capability is read from the profile, never inferred from the model name.
  if profile.capability_state = 'UNKNOWN' then
    reasons := array_append(reasons, 'This model''s capability is unknown to TONDE. Declare it in Setup before relying on it.');
  elsif profile.capability_state = 'UNSUPPORTED' then
    state := 'UNSUPPORTED';
    reasons := array_append(reasons, 'This model is declared as not supporting the operation this Shot needs.');
    blocking := array_append(blocking, 'This model is declared as not supporting the operation this Shot needs.');
    return jsonb_build_object('state', state, 'reasons', to_jsonb(reasons), 'partial', to_jsonb(partial),
      'blocking', to_jsonb(blocking), 'requires_connection', false);
  elsif profile.capability_state = 'REQUIRES CONNECTION' then
    reasons := array_append(reasons, 'This model needs a provider connection before its capability can be confirmed.');
  end if;
  if plan_row.id is not null then
    needs_audio := coalesce(plan_row.audio ->> 'needed','false') = 'true';
    if needs_audio and not profile.supports_audio then
      state := 'UNSUPPORTED'; reasons := array_append(reasons, 'The Shot needs audio and this model does not generate audio.');
    elsif needs_audio then partial := array_append(partial, 'Audio is generated separately and combined editorially.');
    end if;
    if length(coalesce(plan_row.first_frame ->> 'source','')) > 0 then
      if profile.supports_first_frame then partial := array_append(partial, 'First frame is supported.'); 
      else state := 'UNSUPPORTED'; reasons := array_append(reasons, 'The Shot specifies a first frame and this model does not accept one.'); end if;
    end if;
    if length(coalesce(plan_row.last_frame ->> 'source','')) > 0 then
      if profile.supports_last_frame then partial := array_append(partial, 'Last frame is supported.');
      else state := 'UNSUPPORTED'; reasons := array_append(reasons, 'The Shot specifies a last frame and this model does not accept one.'); end if;
    end if;
    duration_ms := plan_row.expected_duration_ms;
    if duration_ms is not null and profile.max_duration_ms is not null and duration_ms > profile.max_duration_ms then
      partial := array_append(partial, format('This model generates up to %s ms, so the Shot needs an extension or split.', profile.max_duration_ms));
    end if;
    if plan_row.aspect_ratio <> '' and cardinality(profile.aspect_ratios) > 0
      and not (plan_row.aspect_ratio = any(profile.aspect_ratios)) then
      state := 'UNSUPPORTED';
      reasons := array_append(reasons, format('The Production delivers %s and this model does not list that aspect ratio.', plan_row.aspect_ratio));
      blocking := array_append(blocking, format('The Production delivers %s and this model does not list that aspect ratio.', plan_row.aspect_ratio));
    end if;
    if coalesce(plan_row.negative_constraints, '{}') <> '{}' and not profile.supports_negative_prompt then
      partial := array_append(partial, 'Negative constraints are expressed in the prompt wording because this model has no negative-prompt field.');
    end if;
    select count(*) into must_references from tonde.ai_shot_references r
      where r.workspace_id = target_workspace and r.plan_id = plan_row.id and r.priority = 'MUST PRESERVE'
        and r.asset_id is not null;
    if must_references > 0 then
      if not profile.supports_image_reference then
        state := 'UNSUPPORTED';
        reasons := array_append(reasons, 'Reference images are required and this model does not accept image references.');
        blocking := array_append(blocking, 'Reference images are required and this model does not accept image references.');
      elsif profile.max_reference_images is not null and must_references > profile.max_reference_images then
        partial := array_append(partial, format('%s required references exceed the %s this model accepts; TONDE will select the strongest.', must_references, profile.max_reference_images));
      end if;
    end if;
  end if;
  if state is null then
    if profile.capability_state = 'PARTIALLY SUPPORTED' then state := 'PARTIALLY SUPPORTED';
    elsif profile.capability_state = 'REQUIRES CONNECTION' then state := 'REQUIRES CONNECTION';
    else state := 'SUPPORTED'; end if;
  end if;
  -- 'blocking' separates a mismatch that makes the plan unusable (wrong aspect, missing
  -- reference support, an operation this model does not do) from a control the model
  -- simply lacks. The first is refused at plan time; the second is stored and reported,
  -- because a plan the creator can see and correct is more useful than a silent failure.
  return jsonb_build_object('state', state, 'reasons', to_jsonb(reasons), 'partial', to_jsonb(partial),
    'blocking', to_jsonb(blocking),
    'requires_connection', profile.capability_state = 'REQUIRES CONNECTION');
end $$;

revoke all on function tonde_private.ai_capability_check(uuid,uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- The plan document for one Shot's AI plan, with prompt staleness computed from the
-- Shot revision it was compiled against.
create or replace function tonde_private.ai_plan_document(target_workspace uuid, target_production uuid, target_shot uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select case when p.id is null then null else
    jsonb_build_object(
      'plan_id', p.id, 'shot_id', p.shot_id, 'execution_method', p.execution_method,
      'approval', p.approval, 'locked', p.locked_at is not null, 'revision', p.revision,
      'plan_status', p.plan_status, 'readiness_note', p.readiness_note,
      'generated_by', p.generated_by,
      'prompt_version', p.prompt_version, 'source_shot_revision', p.source_shot_revision,
      'shot_revision', h.revision,
      'prompt_stale', p.source_shot_revision is not null and p.source_shot_revision <> h.revision,
      'source_versions', p.source_versions,
      'canonical_prompt', p.canonical_prompt, 'provider_prompt', p.provider_prompt,
      'provider_prompt_edited', p.provider_prompt_edited,
      'provider_prompt_edited_at', p.provider_prompt_edited_at,
      'provider_target', p.provider_target, 'model_profile_id', p.model_profile_id,
      'fallback_model_profile_id', p.fallback_model_profile_id, 'model_version', p.model_version,
      'model', p.model, 'provider', p.provider, 'routing', p.routing,
      'first_frame', p.first_frame, 'last_frame', p.last_frame, 'motion', p.motion,
      'audio', p.audio, 'continuity', p.continuity, 'hybrid', p.hybrid,
      'negative_constraints', to_jsonb(p.negative_constraints), 'limitations', to_jsonb(p.limitations),
      'aspect_ratio', p.aspect_ratio, 'expected_duration_ms', p.expected_duration_ms,
      'cost_state', p.cost_state, 'cost_amount', p.cost_amount, 'cost_currency', p.cost_currency,
      'cost_note', p.cost_note,
      'shot_size', p.shot_size, 'framing', p.framing, 'composition', p.composition,
      'movement', p.movement, 'movement_purpose', p.movement_purpose,
      'lighting_intent', p.lighting_intent, 'performance', p.performance,
      'product_direction', p.product_direction, 'sound_plan', p.sound_plan,
      'editorial_intent', p.editorial_intent, 'updated_at', p.updated_at)
    || jsonb_build_object(
      'model_profile', case when m.id is null then null else jsonb_build_object(
        'id', m.id, 'provider_key', m.provider_key, 'model_key', m.model_key, 'label', m.label,
        'operation', m.operation, 'capability_state', m.capability_state,
        'supports_image_reference', m.supports_image_reference, 'max_reference_images', m.max_reference_images,
        'supports_first_frame', m.supports_first_frame, 'supports_last_frame', m.supports_last_frame,
        'supports_seed', m.supports_seed, 'supports_negative_prompt', m.supports_negative_prompt,
        'supports_camera_control', m.supports_camera_control, 'supports_audio', m.supports_audio,
        'max_duration_ms', m.max_duration_ms, 'aspect_ratios', to_jsonb(m.aspect_ratios),
        'resolutions', to_jsonb(m.resolutions), 'cost_unit', m.cost_unit, 'cost_amount', m.cost_amount,
        'cost_currency', m.cost_currency, 'cost_known', m.cost_known, 'availability', m.availability,
        'source', m.source, 'identity_note', m.identity_note, 'product_fidelity_note', m.product_fidelity_note,
        'speed_note', m.speed_note, 'safety_note', m.safety_note) end,
      'connection', tonde_private.ai_connection(target_workspace, coalesce(p.provider_target, 'manual')))
  end
  from tonde.execution_plans p
  join tonde.shots h on h.workspace_id = p.workspace_id and h.id = p.shot_id
  left join tonde.ai_model_profiles m on m.id = p.model_profile_id
  where p.workspace_id = target_workspace and p.production_id = target_production
    and p.shot_id = target_shot and p.execution_method = 'ai';
$$;

revoke all on function tonde_private.ai_plan_document(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- One Shot's AI rollup for the Scene and Production summaries.
create or replace function tonde_private.ai_shot_rollup(target_workspace uuid, target_plan uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'attempts', (select count(*) from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = target_plan),
    'succeeded', (select count(*) from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = target_plan and a.status = 'succeeded'),
    'failed', (select count(*) from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = target_plan and a.status = 'failed'),
    'in_flight', (select count(*) from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = target_plan
        and a.status in ('queued','submitted','processing')),
    'selected_attempt_id', (select a.id from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = target_plan and a.selected limit 1),
    'references', (select count(*) from tonde.ai_shot_references r
      where r.workspace_id = target_workspace and r.plan_id = target_plan),
    'must_references', (select count(*) from tonde.ai_shot_references r
      where r.workspace_id = target_workspace and r.plan_id = target_plan and r.priority = 'MUST PRESERVE'));
$$;

revoke all on function tonde_private.ai_shot_rollup(uuid,uuid) from public, anon, authenticated, service_role;


-- The selected Result for a Shot, or null. Selected means chosen current output.
create or replace function tonde_private.ai_selected_attempt(target_workspace uuid, target_shot uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select a.id from tonde.ai_generation_attempts a
  where a.workspace_id = target_workspace and a.shot_id = target_shot and a.selected limit 1;
$$;

revoke all on function tonde_private.ai_selected_attempt(uuid,uuid) from public, anon, authenticated, service_role;


-- Continuity locks for a Production, as a stable JSON document.
create or replace function tonde_private.ai_locks_document(target_workspace uuid, target_production uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'lock_id', l.id, 'scope', l.scope, 'subject_id', l.subject_id, 'label', l.label,
    'locked', l.locked, 'priority', l.priority, 'locked_traits', to_jsonb(l.locked_traits),
    'allowed_variations', to_jsonb(l.allowed_variations), 'prohibited_changes', to_jsonb(l.prohibited_changes),
    'identity_truth', l.identity_truth, 'consent_note', l.consent_note, 'note', l.note,
    'locked_at', l.locked_at, 'revision', l.revision)
    order by l.scope, l.label), '[]'::jsonb)
  from tonde.ai_continuity_locks l
  where l.workspace_id = target_workspace and l.production_id = target_production;
$$;

revoke all on function tonde_private.ai_locks_document(uuid,uuid) from public, anon, authenticated, service_role;


-- 13. Read model: the AI Creation surface for a whole Production. One round trip for
-- the Studio AI face, the readiness queue and the batch preview.
create or replace function tonde.ai_creation_surface(target_workspace uuid, target_production uuid,
  expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare prod tonde.productions;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into prod from tonde.productions where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and prod.revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  return jsonb_build_object(
    'production', jsonb_build_object('id', prod.id, 'workspace_id', prod.workspace_id, 'title', prod.title,
      'production_type', prod.production_type, 'execution_method', prod.execution_method,
      'planned_duration_ms', prod.planned_duration_ms, 'approval', prod.approval,
      'locked_at', prod.locked_at, 'revision', prod.revision, 'lifecycle', prod.lifecycle),
    'execution_faces', to_jsonb(array['real','ai']),
    'connections', (select coalesce(jsonb_agg(jsonb_build_object(
        'provider_key', p.key, 'label', p.label, 'connection_required', p.connection_required,
        'manual_export_supported', p.manual_export_supported,
        'state', coalesce(c.state, 'not_connected'),
        'credential_reference', coalesce(c.credential_reference, ''),
        'connected_at', c.connected_at)
        order by p.key), '[]'::jsonb)
      from tonde.ai_providers p
      left join tonde.ai_provider_connections c on c.workspace_id = target_workspace and c.provider_key = p.key),
    'models', (select coalesce(jsonb_agg(jsonb_build_object(
        'model_profile_id', m.id, 'provider_key', m.provider_key, 'model_key', m.model_key,
        'label', m.label, 'operation', m.operation, 'capability_state', m.capability_state,
        'availability', m.availability, 'cost_known', m.cost_known, 'cost_unit', m.cost_unit,
        'cost_amount', m.cost_amount, 'cost_currency', m.cost_currency,
        'supports_image_reference', m.supports_image_reference,
        'supports_first_frame', m.supports_first_frame, 'supports_last_frame', m.supports_last_frame,
        'max_duration_ms', m.max_duration_ms, 'source', m.source)
        order by m.provider_key, m.model_key, m.operation), '[]'::jsonb)
      from tonde.ai_model_profiles m
      where m.workspace_id = target_workspace and m.lifecycle = 'active'),
    'known_models', (select coalesce(jsonb_agg(jsonb_build_object(
        'provider_key', m.provider_key, 'model_key', m.model_key, 'operation', m.operation,
        'declared', false, 'capability_state', m.capability_state)
        order by m.provider_key, m.model_key), '[]'::jsonb)
      from tonde.ai_model_profiles m where m.workspace_id is null),
    'locks', tonde_private.ai_locks_document(target_workspace, target_production),
    'scenes', (select coalesce(jsonb_agg(jsonb_build_object(
        'scene_id', s.id, 'order', s.sort_order, 'title', s.title, 'shots', s.shot_count,
        'ready', s.ready, 'blocked', s.blocked, 'unplanned', s.unplanned, 'selected', s.selected)
        order by s.sort_order, s.id), '[]'::jsonb)
      from (select sc.id, sc.sort_order, sc.title,
          count(h.id) as shot_count,
          count(h.id) filter (where r.readiness = 'ready_to_generate') as ready,
          count(h.id) filter (where r.readiness not in ('ready_to_generate','manual_export') and h.execution_method <> 'real') as blocked,
          count(h.id) filter (where h.execution_method in ('ai','hybrid') and r.readiness = 'unplanned') as unplanned,
          count(h.id) filter (where r.selected_attempt_id is not null) as selected
        from tonde.scenes sc
        left join tonde.shots h on h.workspace_id = sc.workspace_id and h.production_id = sc.production_id
          and h.scene_id = sc.id and h.lifecycle = 'active'
        left join lateral (select tonde_private.ai_readiness_state(target_workspace, target_production, h.id) as readiness,
          tonde_private.ai_selected_attempt(target_workspace, h.id) as selected_attempt_id) r on true
        where sc.workspace_id = target_workspace and sc.production_id = target_production and sc.lifecycle = 'active'
        group by sc.id, sc.sort_order, sc.title) s),
    'shots', (select coalesce(jsonb_agg(jsonb_build_object(
        'shot_id', h.id, 'scene_id', h.scene_id, 'title', h.title, 'purpose', h.purpose,
        'order', h.sort_order, 'execution_method', h.execution_method, 'approval', h.approval,
        'locked', h.locked_at is not null, 'revision', h.revision,
        'planned_duration_ms', h.planned_duration_ms,
        'readiness', tonde_private.ai_readiness_state(target_workspace, target_production, h.id),
        'plan_id', p.id, 'plan_revision', p.revision, 'plan_status', p.plan_status,
        'prompt_version', p.prompt_version, 'prompt_stale', p.source_shot_revision is not null and p.source_shot_revision <> h.revision,
        'provider_target', p.provider_target, 'model_profile_id', p.model_profile_id,
        'model_label', coalesce(m.label, m.model_key), 'model_key', m.model_key,
        'capability_state', m.capability_state,
        'cost_state', coalesce(p.cost_state, 'unknown'), 'cost_amount', p.cost_amount,
        'cost_currency', p.cost_currency,
        'aspect_ratio', coalesce(nullif(p.aspect_ratio, ''), ''),
        'expected_duration_ms', coalesce(p.expected_duration_ms, h.planned_duration_ms),
        'hybrid', p.hybrid)
        order by h.sort_order, h.id), '[]'::jsonb)
      from tonde.shots h
      left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
        and p.execution_method = 'ai'
      left join tonde.ai_model_profiles m on m.id = p.model_profile_id
      where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'),
    'summary', (select jsonb_build_object(
        'shots', count(*),
        'ai_or_hybrid', count(*) filter (where h.execution_method in ('ai','hybrid')),
        'real', count(*) filter (where h.execution_method = 'real'),
        'planned', count(*) filter (where p.id is not null),
        'ready', count(*) filter (where tonde_private.ai_readiness_state(target_workspace, target_production, h.id) = 'ready_to_generate'),
        'manual_export', count(*) filter (where tonde_private.ai_readiness_state(target_workspace, target_production, h.id) = 'manual_export'),
        'blocked', count(*) filter (where h.execution_method in ('ai','hybrid')
          and tonde_private.ai_readiness_state(target_workspace, target_production, h.id) not in ('ready_to_generate','manual_export')),
        'stale', count(*) filter (where p.source_shot_revision is not null and p.source_shot_revision <> h.revision),
        'with_selected_result', count(*) filter (where tonde_private.ai_selected_attempt(target_workspace, h.id) is not null),
        'connected_providers', (select count(*) from tonde.ai_provider_connections c
          where c.workspace_id = target_workspace and c.state = 'connected'),
        'declared_models', (select count(*) from tonde.ai_model_profiles m
          where m.workspace_id = target_workspace and m.lifecycle = 'active'))
      from tonde.shots h
      left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
        and p.execution_method = 'ai'
      where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'),
    'capabilities', jsonb_build_object(
      'prompt_compilation', true,
      'model_routing', true,
      'live_generation', exists (select 1 from tonde.ai_provider_connections c
        where c.workspace_id = target_workspace and c.state = 'connected'),
      'manual_export', true,
      'note', 'Provider-neutral. TONDE ranks only the models you have declared, and holds no vendor capability facts of its own.'));
end $$;

revoke all on function tonde.ai_creation_surface(uuid,uuid,integer) from public, anon, authenticated, service_role;


-- The Model Router's input. Three separate facts are reported separately: TONDE knows
-- this model, this workspace declared this model, and TONDE is connected to this
-- provider. Capability metadata is only ever what was declared.
create or replace function tonde.ai_model_catalog(target_workspace uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'providers', (select coalesce(jsonb_agg(jsonb_build_object(
        'provider_key', p.key, 'label', p.label, 'connection_required', p.connection_required,
        'manual_export_supported', p.manual_export_supported, 'note', p.note,
        'connection', tonde_private.ai_connection(target_workspace, p.key))
        order by p.key), '[]'::jsonb)
      from tonde.ai_providers p),
    'models', (select coalesce(jsonb_agg(jsonb_build_object(
        'model_profile_id', m.id, 'provider_key', m.provider_key, 'model_key', m.model_key,
        'label', m.label, 'operation', m.operation, 'capability_state', m.capability_state,
        'modalities', to_jsonb(m.modalities), 'source', m.source, 'availability', m.availability,
        'supports_image_reference', m.supports_image_reference, 'max_reference_images', m.max_reference_images,
        'supports_first_frame', m.supports_first_frame, 'supports_last_frame', m.supports_last_frame,
        'supports_seed', m.supports_seed, 'supports_negative_prompt', m.supports_negative_prompt,
        'supports_camera_control', m.supports_camera_control, 'supports_audio', m.supports_audio,
        'supports_image_edit', m.supports_image_edit, 'supports_lipsync', m.supports_lipsync,
        'max_duration_ms', m.max_duration_ms, 'aspect_ratios', to_jsonb(m.aspect_ratios),
        'resolutions', to_jsonb(m.resolutions), 'cost_unit', m.cost_unit, 'cost_amount', m.cost_amount,
        'cost_currency', m.cost_currency, 'cost_known', m.cost_known, 'speed_note', m.speed_note,
        'identity_note', m.identity_note, 'product_fidelity_note', m.product_fidelity_note,
        'safety_note', m.safety_note, 'capability_notes', m.capability_notes,
        'declared', true, 'known', true,
        'connected', coalesce((select c.state = 'connected' from tonde.ai_provider_connections c
          where c.workspace_id = target_workspace and c.provider_key = m.provider_key), false))
        order by m.provider_key, m.model_key, m.operation), '[]'::jsonb)
      from tonde.ai_model_profiles m
      where m.workspace_id = target_workspace and m.lifecycle = 'active'),
    'known_models', (select coalesce(jsonb_agg(jsonb_build_object(
        'provider_key', m.provider_key, 'model_key', m.model_key, 'operation', m.operation,
        'label', m.label, 'capability_state', m.capability_state, 'declared', false, 'known', true)
        order by m.provider_key, m.model_key), '[]'::jsonb)
      from tonde.ai_model_profiles m where m.workspace_id is null),
    'truth', jsonb_build_object(
      'known', 'TONDE recognises this model identifier.',
      'declared', 'This workspace declared what the model can do. Capability is never inferred from a name.',
      'connected', 'TONDE holds a connection for this provider in this workspace.',
      'manual', 'Manual export needs no connection and always remains available.'));
end $$;

revoke all on function tonde.ai_model_catalog(uuid) from public, anon, authenticated, service_role;


-- One Shot's AI Creation detail: the canvas data for section 112, including the Real plan it
-- must coordinate with when the Shot is Hybrid.
create or replace function tonde.ai_shot_detail(target_workspace uuid, target_production uuid, target_shot uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare shot_row tonde.shots; scene_row tonde.scenes; plan_row tonde.execution_plans;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into shot_row from tonde.shots
    where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  if not found then raise exception 'That Shot is unavailable in this Production' using errcode = 'P0002'; end if;
  select * into scene_row from tonde.scenes
    where workspace_id = target_workspace and production_id = target_production and id = shot_row.scene_id;
  select * into plan_row from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  return jsonb_build_object(
    'shot', jsonb_build_object('shot_id', shot_row.id, 'scene_id', shot_row.scene_id, 'title', shot_row.title,
      'description', shot_row.description, 'action', shot_row.action, 'purpose', shot_row.purpose,
      'subject', shot_row.subject, 'framing', shot_row.framing, 'angle', shot_row.angle,
      'movement', shot_row.movement, 'composition', shot_row.composition, 'transition', shot_row.transition,
      'story_relationship', shot_row.story_relationship, 'story_beat', shot_row.story_beat,
      'creative_notes', shot_row.creative_notes, 'execution_method', shot_row.execution_method,
      'approval', shot_row.approval, 'locked', shot_row.locked_at is not null, 'revision', shot_row.revision,
      'planned_duration_ms', shot_row.planned_duration_ms),
    'scene', jsonb_build_object('scene_id', scene_row.id, 'title', scene_row.title, 'order', scene_row.sort_order,
      'purpose', scene_row.purpose, 'description', scene_row.description,
      'environment_asset_id', scene_row.environment_asset_id),
    'readiness', tonde_private.ai_readiness_state(target_workspace, target_production, target_shot),
    'plan', tonde_private.ai_plan_document(target_workspace, target_production, target_shot),
    'real_plan', tonde_private.real_plan_document(target_workspace, target_production, target_shot),
    'references', (select coalesce(jsonb_agg(jsonb_build_object(
        'reference_id', r.id, 'role', r.reference_role, 'priority', r.priority,
        'asset_id', r.asset_id, 'media_id', r.media_id, 'origin', r.origin,
        'source_attempt_id', r.source_attempt_id, 'note', r.note, 'sort_order', r.sort_order,
        'asset_name', a.name, 'asset_type', a.asset_type)
        order by r.sort_order, r.reference_role), '[]'::jsonb)
      from tonde.ai_shot_references r
      left join tonde.assets a on a.workspace_id = r.workspace_id and a.id = r.asset_id
      where r.workspace_id = target_workspace and r.plan_id = plan_row.id),
    'locks', tonde_private.ai_locks_document(target_workspace, target_production),
    'attempts', (select coalesce(jsonb_agg(jsonb_build_object(
        'attempt_id', a.id, 'attempt_number', a.attempt_number, 'operation', a.operation,
        'provider_key', a.provider_key, 'model_key', a.model_key, 'model_version', a.model_version,
        'model_profile_id', a.model_profile_id, 'prompt_version', a.prompt_version,
        'source_shot_revision', a.source_shot_revision, 'mode', a.mode, 'status', a.status,
        'external_job_id', a.external_job_id, 'seed', a.seed, 'settings', a.settings,
        'input_references', a.input_references, 'cost_state', a.cost_state, 'cost_amount', a.cost_amount,
        'cost_currency', a.cost_currency, 'retryable', a.retryable, 'retry_of', a.retry_of,
        'started_at', a.started_at, 'completed_at', a.completed_at,
        'failure_code', a.failure_code, 'failure_message', a.failure_message,
        'output_media_id', a.output_media_id, 'result_id', a.result_id, 'result_state', a.result_state,
        'selected', a.selected, 'creator_rating', a.creator_rating, 'creator_decision', a.creator_decision,
        'idempotency_key', a.idempotency_key, 'created_at', a.created_at, 'revision', a.revision)
        order by a.attempt_number), '[]'::jsonb)
      from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = plan_row.id),
    'selected_result', (select case when a.id is null then null else jsonb_build_object(
        'attempt_id', a.id, 'attempt_number', a.attempt_number, 'status', a.status,
        'provider_key', a.provider_key, 'model_key', a.model_key, 'result_id', a.result_id,
        'output_media_id', a.output_media_id, 'result_state', a.result_state,
        'selected', a.selected, 'completed_at', a.completed_at) end
      from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.plan_id = plan_row.id and a.selected limit 1),
    'batch_items', (select coalesce(jsonb_agg(jsonb_build_object(
        'batch_id', i.batch_id, 'state', i.state, 'blocked_reason', i.blocked_reason,
        'attempt_id', i.attempt_id, 'failure_code', i.failure_code, 'failure_message', i.failure_message,
        'created_at', i.created_at) order by i.created_at desc), '[]'::jsonb)
      from tonde.ai_generation_batch_items i
      where i.workspace_id = target_workspace and i.shot_id = target_shot),
    'script_line', (select case when d.id is null then null else jsonb_build_object(
        'dialogue_id', d.id, 'line_type', d.line_type,
        'speaker', (select a.name from tonde.assets a
          where a.workspace_id = d.workspace_id and a.id = d.speaker_asset_id),
        'content', d.content, 'duration_ms', d.duration_ms) end
      from tonde.dialogue_lines d
      where d.workspace_id = target_workspace and d.production_id = target_production
        and d.scene_id = shot_row.scene_id and d.line_type in ('dialogue','voiceover','narration')
      order by d.sort_order limit 1));
end $$;

revoke all on function tonde.ai_shot_detail(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- 14. Declaring capability metadata. This is where capability truth comes from: the
-- creator declares what their tool can do, or a connected provider reports it. TONDE
-- never derives a capability from a model name.
create or replace function tonde.declare_ai_model(target_workspace uuid, payload jsonb,
  expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.ai_model_profiles; provider text; model_name text; op tonde.ai_operation;
begin
  perform tonde_private.director_guard(target_workspace);
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'A model declaration must be a JSON object' using errcode = '22023';
  end if;
  provider := coalesce(nullif(btrim(payload ->> 'provider_key'), ''), '');
  model_name := coalesce(nullif(btrim(payload ->> 'model_key'), ''), '');
  if not exists (select 1 from tonde.ai_providers p where p.key = provider) then
    raise exception 'That provider is not one TONDE recognises' using errcode = '22023';
  end if;
  if model_name = '' then raise exception 'A model identifier is required' using errcode = '22023'; end if;
  op := coalesce(nullif(payload ->> 'operation', ''), 'video')::tonde.ai_operation;
  insert into tonde.ai_model_profiles(workspace_id, provider_key, model_key, label, operation,
    capability_state, modalities, supports_image_reference, max_reference_images,
    supports_first_frame, supports_last_frame, supports_seed, supports_negative_prompt,
    supports_camera_control, supports_audio, supports_image_edit, supports_lipsync,
    max_duration_ms, aspect_ratios, resolutions, cost_unit, cost_amount, cost_currency, cost_known,
    speed_note, identity_note, product_fidelity_note, availability, safety_note, capability_notes,
    source, declared_by)
  values (target_workspace, provider, model_name,
    left(coalesce(payload ->> 'label', ''), 160), op,
    coalesce(nullif(payload ->> 'capability_state',''), 'UNKNOWN')::tonde.ai_capability_state,
    tonde_private.ai_json_text_array(payload, 'modalities'),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_image_reference', false), false),
    tonde_private.ai_json_int(payload, 'max_reference_images'),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_first_frame', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_last_frame', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_seed', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_negative_prompt', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_camera_control', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_audio', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_image_edit', false), false),
    coalesce(tonde_private.ai_json_bool(payload, 'supports_lipsync', false), false),
    case when payload ? 'max_duration_ms' and jsonb_typeof(payload -> 'max_duration_ms') = 'number'
      then (payload ->> 'max_duration_ms')::bigint end,
    tonde_private.ai_json_text_array(payload, 'aspect_ratios'), tonde_private.ai_json_text_array(payload, 'resolutions'),
    left(coalesce(payload ->> 'cost_unit', ''), 80),
    case when payload ? 'cost_amount' and jsonb_typeof(payload -> 'cost_amount') = 'number'
      then (payload ->> 'cost_amount')::numeric(12,4) end,
    left(coalesce(payload ->> 'cost_currency', ''), 8),
    -- Cost is known only when an amount and a currency were actually given.
    (payload ? 'cost_amount' and jsonb_typeof(payload -> 'cost_amount') = 'number'
      and coalesce(payload ->> 'cost_currency','') <> ''),
    left(coalesce(payload ->> 'speed_note', ''), 300), left(coalesce(payload ->> 'identity_note', ''), 300),
    left(coalesce(payload ->> 'product_fidelity_note', ''), 300),
    coalesce(nullif(payload ->> 'availability',''), 'unknown'), left(coalesce(payload ->> 'safety_note', ''), 600),
    coalesce(payload -> 'capability_notes', '{}'::jsonb),
    coalesce(nullif(payload ->> 'source',''), 'declared'), auth.uid())
  on conflict do nothing
  returning * into saved;
  if saved.id is null then
    select * into saved from tonde.ai_model_profiles m
      where m.workspace_id = target_workspace and m.provider_key = provider
        and m.model_key = model_name and m.operation = op;
    if expected_revision is not null and saved.revision <> expected_revision then
      raise exception 'That model declaration changed since you loaded it' using errcode = '40001';
    end if;
    update tonde.ai_model_profiles m set
      label = left(coalesce(payload ->> 'label', m.label), 160),
      capability_state = coalesce(nullif(payload ->> 'capability_state','')::tonde.ai_capability_state,
        m.capability_state),
      modalities = case when payload ? 'modalities' then tonde_private.ai_json_text_array(payload,'modalities') else m.modalities end,
      supports_image_reference = coalesce(tonde_private.ai_json_bool(payload,'supports_image_reference', m.supports_image_reference), m.supports_image_reference),
      supports_first_frame = coalesce(tonde_private.ai_json_bool(payload,'supports_first_frame', m.supports_first_frame), m.supports_first_frame),
      supports_last_frame = coalesce(tonde_private.ai_json_bool(payload,'supports_last_frame', m.supports_last_frame), m.supports_last_frame),
      supports_seed = coalesce(tonde_private.ai_json_bool(payload,'supports_seed', m.supports_seed), m.supports_seed),
      supports_negative_prompt = coalesce(tonde_private.ai_json_bool(payload,'supports_negative_prompt', m.supports_negative_prompt), m.supports_negative_prompt),
      supports_camera_control = coalesce(tonde_private.ai_json_bool(payload,'supports_camera_control', m.supports_camera_control), m.supports_camera_control),
      supports_audio = coalesce(tonde_private.ai_json_bool(payload,'supports_audio', m.supports_audio), m.supports_audio),
      -- Every declared capability must be correctable, or a wrong fact could never be fixed.
      supports_image_edit = coalesce(tonde_private.ai_json_bool(payload,'supports_image_edit', m.supports_image_edit), m.supports_image_edit),
      supports_lipsync = coalesce(tonde_private.ai_json_bool(payload,'supports_lipsync', m.supports_lipsync), m.supports_lipsync),
      max_duration_ms = case when payload ? 'max_duration_ms' and jsonb_typeof(payload -> 'max_duration_ms') = 'number'
        then (payload ->> 'max_duration_ms')::bigint else m.max_duration_ms end,
      aspect_ratios = case when payload ? 'aspect_ratios' then tonde_private.ai_json_text_array(payload,'aspect_ratios') else m.aspect_ratios end,
      cost_unit = left(coalesce(payload ->> 'cost_unit', m.cost_unit), 80),
      cost_amount = case when payload ? 'cost_amount' and jsonb_typeof(payload -> 'cost_amount') = 'number'
        then (payload ->> 'cost_amount')::numeric(12,4) else m.cost_amount end,
      cost_currency = left(coalesce(payload ->> 'cost_currency', m.cost_currency), 8),
      availability = coalesce(nullif(payload ->> 'availability',''), m.availability),
      speed_note = left(coalesce(payload ->> 'speed_note', m.speed_note), 300),
      identity_note = left(coalesce(payload ->> 'identity_note', m.identity_note), 300),
      product_fidelity_note = left(coalesce(payload ->> 'product_fidelity_note', m.product_fidelity_note), 300),
      capability_notes = coalesce(payload -> 'capability_notes', m.capability_notes),
      -- Cost is known only when both an amount and a currency are present. Computed in the same
      -- statement as the rest of the declaration, so one edit is exactly one revision.
      cost_known = (case when payload ? 'cost_amount' and jsonb_typeof(payload -> 'cost_amount') = 'number'
          then (payload ->> 'cost_amount')::numeric(12,4) else m.cost_amount end is not null
        and left(coalesce(payload ->> 'cost_currency', m.cost_currency), 8) <> '')
    where m.id = saved.id returning * into saved;
  end if;
  return jsonb_build_object('model_profile_id', saved.id, 'provider_key', saved.provider_key,
    'model_key', saved.model_key, 'operation', saved.operation, 'capability_state', saved.capability_state,
    'cost_known', saved.cost_known, 'cost_amount', saved.cost_amount, 'cost_currency', saved.cost_currency,
    'revision', saved.revision);
end $$;

revoke all on function tonde.declare_ai_model(uuid,jsonb,integer) from public, anon, authenticated, service_role;


-- Provider connection state. A reference only: no secret is stored or read here.
create or replace function tonde.set_ai_connection(target_workspace uuid, target_provider text,
  target_state text, credential_reference text default '', note text default '', expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.ai_provider_connections;
begin
  perform tonde_private.director_guard(target_workspace);
  if not exists (select 1 from tonde.ai_providers p where p.key = target_provider) then
    raise exception 'That provider is not one TONDE recognises' using errcode = '22023';
  end if;
  if target_state not in ('not_connected','connected','unavailable') then
    raise exception 'That connection state is not valid' using errcode = '22023';
  end if;
  if length(coalesce(credential_reference, '')) > 0 and credential_reference ~* '(sk-|secret|password|bearer )' then
    raise exception 'Store only a reference to the credential, never the credential itself' using errcode = '22023';
  end if;
  insert into tonde.ai_provider_connections(workspace_id, provider_key, state, credential_reference, note,
    last_checked_at, connected_at)
  values (target_workspace, target_provider, target_state::tonde.ai_connection_state,
    left(coalesce(credential_reference,''), 200), left(coalesce(note,''), 600), now(),
    case when target_state = 'connected' then now() end)
  on conflict (workspace_id, provider_key) do update set
    state = excluded.state, credential_reference = excluded.credential_reference, note = excluded.note,
    last_checked_at = now(),
    connected_at = case when excluded.state = 'connected' then coalesce(tonde.ai_provider_connections.connected_at, now()) end
  returning * into saved;
  if expected_revision is not null and saved.revision <> expected_revision + 1 then
    raise exception 'That connection changed since you loaded it' using errcode = '40001';
  end if;
  return jsonb_build_object('provider_key', saved.provider_key, 'state', saved.state,
    'credential_reference', saved.credential_reference, 'note', saved.note,
    'connected_at', saved.connected_at, 'revision', saved.revision);
end $$;

revoke all on function tonde.set_ai_connection(uuid,text,text,text,text,integer) from public, anon, authenticated, service_role;


-- The capability verdict for one declared model against one Shot, exposed so the Model
-- Router and the creator see exactly the same truth. This is where 'can this model
-- actually do this Shot' is answered, and it is answered from declared facts only.
create or replace function tonde.ai_capability_verdict(target_workspace uuid, target_production uuid,
  target_shot uuid, target_profile uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare shot_row tonde.shots;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into shot_row from tonde.shots
    where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  if not found then raise exception 'That Shot is unavailable in this Production' using errcode = 'P0002'; end if;
  return tonde_private.ai_capability_check(target_workspace, target_profile, target_production, target_shot)
    || jsonb_build_object('model_profile_id', target_profile, 'shot_id', target_shot);
end $$;

revoke all on function tonde.ai_capability_verdict(uuid,uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- 15. Saving an AI plan. The database is the last line of defence for four rules the
-- engine also holds: a capability the selected model does not support is never stored
-- as usable, a locked trait is never changed silently, a hand-edited provider prompt is
-- never overwritten without confirmation, and a prompt always records the Shot revision
-- it was compiled against.
create or replace function tonde.save_ai_plan(target_workspace uuid, target_production uuid, target_shot uuid,
  expected_shot_revision integer, plan jsonb, references_json jsonb default '[]'::jsonb,
  expected_plan_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare previous tonde.execution_plans; saved tonde.execution_plans; item jsonb; change_item jsonb;
  lock_row tonde.ai_continuity_locks; shot_row tonde.shots; capability jsonb; next_version integer;
  profile tonde.ai_model_profiles; reference_count integer := 0; duration_ms bigint; aspect text;
  conflict_fields text[] := '{}'; effective_shot_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_shot, 'shot', expected_shot_revision);
  if plan is null or jsonb_typeof(plan) <> 'object' then
    raise exception 'An AI plan must be a JSON object' using errcode = '22023';
  end if;
  select * into shot_row from tonde.shots
    where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  select * into previous from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  if previous.id is not null then
    if previous.locked_at is not null then
      raise exception 'This AI plan is locked. Unlock it before editing.' using errcode = '23514';
    end if;
    if expected_plan_revision is not null and previous.revision <> expected_plan_revision then
      raise exception 'That AI plan changed since you loaded it' using errcode = '40001';
    end if;
    if previous.provider_prompt_edited and plan ? 'provider_prompt'
      and coalesce(plan ->> 'accept_provider_prompt', 'false') <> 'true' then
      raise exception 'This provider prompt was edited by hand. Confirm the replacement before TONDE overwrites it.'
        using errcode = '23514';
    end if;
  end if;

  -- Continuity locks: a locked trait is not changed without an explicit proposal.
  if jsonb_typeof(plan -> 'continuity') = 'object' and jsonb_typeof(plan -> 'continuity' -> 'changes') = 'array' then
    for change_item in select jsonb_array_elements(plan -> 'continuity' -> 'changes') loop
      if coalesce(change_item ->> 'scope','') in ('character','world','product','style') then
        select * into lock_row from tonde.ai_continuity_locks l
          where l.workspace_id = target_workspace and l.production_id = target_production
            and l.scope = (change_item ->> 'scope')::tonde.ai_lock_scope and l.locked
            and (change_item ->> 'subject_id' is null or l.subject_id = (change_item ->> 'subject_id')::uuid)
          order by l.priority limit 1;
        if lock_row.id is not null then
          if coalesce(change_item ->> 'field','') = any(lock_row.prohibited_changes)
            or (lock_row.priority = 'MUST PRESERVE'
              and not (coalesce(change_item ->> 'field','') = any(lock_row.allowed_variations))) then
            conflict_fields := conflict_fields || (lock_row.scope::text || ' - ' || coalesce(change_item ->> 'field',''));
          end if;
        end if;
      end if;
    end loop;
  end if;
  if cardinality(conflict_fields) > 0 then
    raise exception 'These changes touch a locked continuity trait: %. Propose the change explicitly or unlock the scope first.',
      array_to_string(conflict_fields, ', ') using errcode = '23514';
  end if;

  -- The selected model must be one this workspace declared. The capability verdict itself
  -- is taken after the plan is stored, so it judges exactly the plan being saved rather
  -- than the one it replaces.
  if plan ? 'model_profile_id' and coalesce(plan ->> 'model_profile_id','') <> '' then
    select * into profile from tonde.ai_model_profiles m
      where m.id = (plan ->> 'model_profile_id')::uuid and m.workspace_id = target_workspace and m.lifecycle = 'active';
    if profile.id is null then
      raise exception 'That model is not declared for this workspace' using errcode = '23514';
    end if;
  end if;

  duration_ms := case when plan ? 'expected_duration_ms' and jsonb_typeof(plan -> 'expected_duration_ms') = 'number'
    then (plan ->> 'expected_duration_ms')::bigint end;
  aspect := left(coalesce(plan ->> 'aspect_ratio', ''), 20);
  -- Duration authority: the Shot carries the timing, exactly as the Real plan does. The
  -- write happens before the plan so the revision the prompt records is the Shot state
  -- the compiled plan actually describes -- otherwise the timing write alone would mark
  -- every compiled prompt stale.
  effective_shot_revision := shot_row.revision;
  if duration_ms is not null and duration_ms is distinct from shot_row.planned_duration_ms then
    update tonde.shots set planned_duration_ms = duration_ms
      where workspace_id = target_workspace and production_id = target_production and id = target_shot;
    select revision into effective_shot_revision from tonde.shots
      where workspace_id = target_workspace and production_id = target_production and id = target_shot;
  end if;
  next_version := coalesce(tonde_private.ai_json_int(plan, 'prompt_version'), coalesce(previous.prompt_version, 0) + 1);
  if next_version < 1 then next_version := coalesce(previous.prompt_version, 0) + 1; end if;

  insert into tonde.execution_plans(workspace_id, production_id, shot_id, execution_method,
    plan_status, readiness_note, generated_by, provider, model, model_version,
    provider_target, model_profile_id, fallback_model_profile_id,
    prompt_version, source_shot_revision, source_versions, canonical_prompt, provider_prompt,
    provider_prompt_edited, provider_prompt_edited_at, routing, first_frame, last_frame, motion, audio,
    continuity, hybrid, negative_constraints, limitations, aspect_ratio, expected_duration_ms,
    cost_state, cost_amount, cost_currency, cost_note,
    shot_size, framing, composition, movement, movement_purpose, lighting_intent, performance,
    product_direction, sound_plan, editorial_intent)
  values (target_workspace, target_production, target_shot, 'ai',
    coalesce(nullif(plan ->> 'plan_status',''), 'draft'), tonde_private.json_text(plan, 'readiness_note', 600),
    coalesce(nullif(plan ->> 'generated_by',''), 'deterministic'),
    nullif(plan ->> 'provider_target',''), nullif(plan ->> 'model_key',''),
    left(coalesce(plan ->> 'model_version',''), 120),
    nullif(plan ->> 'provider_target',''),
    nullif(plan ->> 'model_profile_id','')::uuid, nullif(plan ->> 'fallback_model_profile_id','')::uuid,
    next_version, effective_shot_revision,
    coalesce(plan -> 'source_versions', jsonb_build_object('shot_revision', effective_shot_revision)),
    coalesce(plan -> 'canonical_prompt', '{}'::jsonb), left(coalesce(plan ->> 'provider_prompt',''), 8000),
    coalesce(tonde_private.ai_json_bool(plan, 'provider_prompt_edited', false), false),
    case when coalesce(tonde_private.ai_json_bool(plan, 'provider_prompt_edited', false), false) then now() end,
    coalesce(plan -> 'routing', '{}'::jsonb), coalesce(plan -> 'first_frame','{}'::jsonb),
    coalesce(plan -> 'last_frame','{}'::jsonb), coalesce(plan -> 'motion','{}'::jsonb),
    coalesce(plan -> 'audio','{}'::jsonb), coalesce(plan -> 'continuity','{}'::jsonb),
    coalesce(plan -> 'hybrid','{}'::jsonb), tonde_private.ai_json_text_array(plan, 'negative_constraints'),
    tonde_private.ai_json_text_array(plan, 'limitations'), aspect, duration_ms,
    case when left(coalesce(plan ->> 'cost_currency',''),8) <> '' and plan ? 'cost_amount'
      and jsonb_typeof(plan -> 'cost_amount') = 'number' then 'known' else 'unknown' end,
    case when left(coalesce(plan ->> 'cost_currency',''),8) <> '' and plan ? 'cost_amount'
      and jsonb_typeof(plan -> 'cost_amount') = 'number' then (plan ->> 'cost_amount')::numeric(12,4) end,
    left(coalesce(plan ->> 'cost_currency',''), 8), left(coalesce(plan ->> 'cost_note',''), 400),
    tonde_private.json_text(plan,'shot_size',80), tonde_private.json_text(plan,'framing',300),
    tonde_private.json_text(plan,'composition',400), tonde_private.json_text(plan,'movement',200),
    tonde_private.json_text(plan,'movement_purpose',600), tonde_private.json_text(plan,'lighting_intent',400),
    tonde_private.json_text(plan,'performance',2000), tonde_private.json_text(plan,'product_direction',1200),
    tonde_private.json_text(plan,'sound_plan',2000), tonde_private.json_text(plan,'editorial_intent',300))
  on conflict (shot_id, execution_method) do update set
    plan_status = excluded.plan_status, readiness_note = excluded.readiness_note,
    generated_by = excluded.generated_by, provider = excluded.provider, model = excluded.model,
    model_version = excluded.model_version, provider_target = excluded.provider_target,
    model_profile_id = excluded.model_profile_id, fallback_model_profile_id = excluded.fallback_model_profile_id,
    prompt_version = excluded.prompt_version, source_shot_revision = excluded.source_shot_revision,
    source_versions = excluded.source_versions, canonical_prompt = excluded.canonical_prompt,
    provider_prompt = excluded.provider_prompt, provider_prompt_edited = excluded.provider_prompt_edited,
    provider_prompt_edited_at = coalesce(excluded.provider_prompt_edited_at, tonde.execution_plans.provider_prompt_edited_at),
    routing = excluded.routing, first_frame = excluded.first_frame, last_frame = excluded.last_frame,
    motion = excluded.motion, audio = excluded.audio, continuity = excluded.continuity,
    hybrid = excluded.hybrid, negative_constraints = excluded.negative_constraints,
    limitations = excluded.limitations, aspect_ratio = excluded.aspect_ratio,
    expected_duration_ms = excluded.expected_duration_ms, cost_state = excluded.cost_state,
    cost_amount = excluded.cost_amount, cost_currency = excluded.cost_currency, cost_note = excluded.cost_note,
    shot_size = excluded.shot_size, framing = excluded.framing, composition = excluded.composition,
    movement = excluded.movement, movement_purpose = excluded.movement_purpose,
    lighting_intent = excluded.lighting_intent, performance = excluded.performance,
    product_direction = excluded.product_direction, sound_plan = excluded.sound_plan,
    editorial_intent = excluded.editorial_intent
  returning * into saved;

  -- References are replaced wholesale: the plan's reference set is one decision.
  delete from tonde.ai_shot_references r where r.workspace_id = target_workspace and r.plan_id = saved.id;
  if jsonb_typeof(references_json) = 'array' then
    for item in select jsonb_array_elements(references_json) loop
      insert into tonde.ai_shot_references(workspace_id, production_id, shot_id, plan_id, reference_role,
        priority, asset_id, media_id, origin, source_attempt_id, note, sort_order)
      values (target_workspace, target_production, target_shot, saved.id,
        (item ->> 'role')::tonde.ai_reference_role,
        coalesce(nullif(item ->> 'priority',''), 'SHOULD PRESERVE')::tonde.ai_continuity_priority,
        nullif(item ->> 'asset_id','')::uuid, nullif(item ->> 'media_id','')::uuid,
        coalesce(nullif(item ->> 'origin',''), 'asset'), nullif(item ->> 'source_attempt_id','')::uuid,
        left(coalesce(item ->> 'note',''), 400), coalesce(tonde_private.ai_json_int(item, 'sort_order'), 1024));
      reference_count := reference_count + 1;
    end loop;
  end if;

  -- Capability truth, judged on what was actually stored. A blocking mismatch is refused
  -- and nothing is written; anything else is reported through readiness and limitations.
  if saved.model_profile_id is not null then
    capability := tonde_private.ai_capability_check(target_workspace, saved.model_profile_id, target_production, target_shot);
    if jsonb_array_length(coalesce(capability -> 'blocking', '[]'::jsonb)) > 0 then
      raise exception 'The selected model cannot do this: %',
        array_to_string(array(select jsonb_array_elements_text(capability -> 'blocking')), ' ') using errcode = '23514';
    end if;
  end if;
  return jsonb_build_object('plan_id', saved.id, 'shot_id', target_shot, 'prompt_version', saved.prompt_version,
    'source_shot_revision', saved.source_shot_revision, 'references', reference_count,
    'revision', saved.revision, 'approval', saved.approval,
    'readiness', tonde_private.ai_readiness_state(target_workspace, target_production, target_shot),
    'plan', tonde_private.ai_plan_document(target_workspace, target_production, target_shot));
end $$;

revoke all on function tonde.save_ai_plan(uuid,uuid,uuid,integer,jsonb,jsonb,integer) from public, anon, authenticated, service_role;


-- Plan approval and plan lock, mirroring the Real plan surface.
create or replace function tonde.set_ai_plan_approval(target_workspace uuid, target_production uuid, target_shot uuid,
  target_approval text, expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.execution_plans;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_approval not in ('draft','needs_review','approved','changed_after_approval') then
    raise exception 'That approval state is not valid' using errcode = '22023';
  end if;
  select * into saved from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  if saved.id is null then raise exception 'There is no AI plan for that Shot' using errcode = 'P0002'; end if;
  if expected_revision is not null and saved.revision <> expected_revision then
    raise exception 'That AI plan changed since you loaded it' using errcode = '40001';
  end if;
  update tonde.execution_plans set approval = target_approval::tonde.approval
    where id = saved.id returning * into saved;
  return jsonb_build_object('plan_id', saved.id, 'shot_id', target_shot, 'approval', saved.approval,
    'revision', saved.revision);
end $$;

revoke all on function tonde.set_ai_plan_approval(uuid,uuid,uuid,text,integer) from public, anon, authenticated, service_role;


create or replace function tonde.set_ai_plan_lock(target_workspace uuid, target_production uuid, target_shot uuid,
  target_locked boolean, expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.execution_plans;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into saved from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  if saved.id is null then raise exception 'There is no AI plan for that Shot' using errcode = 'P0002'; end if;
  if expected_revision is not null and saved.revision <> expected_revision then
    raise exception 'That AI plan changed since you loaded it' using errcode = '40001';
  end if;
  update tonde.execution_plans set locked_at = case when target_locked then now() end
    where id = saved.id returning * into saved;
  return jsonb_build_object('plan_id', saved.id, 'shot_id', target_shot, 'locked', saved.locked_at is not null,
    'revision', saved.revision);
end $$;

revoke all on function tonde.set_ai_plan_lock(uuid,uuid,uuid,boolean,integer) from public, anon, authenticated, service_role;


-- Creator confirmation for generation that may incur material external spend.
create or replace function tonde.confirm_ai_cost(target_workspace uuid, target_production uuid, target_shot uuid,
  note text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare plan_row tonde.execution_plans; saved tonde.ai_cost_confirmations;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into plan_row from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  if plan_row.id is null then raise exception 'There is no AI plan for that Shot' using errcode = 'P0002'; end if;
  if plan_row.prompt_version = 0 then
    raise exception 'Compile a prompt before confirming generation cost' using errcode = '23514';
  end if;
  insert into tonde.ai_cost_confirmations(workspace_id, production_id, shot_id, prompt_version,
    provider_key, model_key, cost_state, cost_amount, cost_currency, note)
  values (target_workspace, target_production, target_shot, plan_row.prompt_version,
    coalesce(plan_row.provider_target, 'manual'), coalesce(plan_row.model, ''),
    plan_row.cost_state, plan_row.cost_amount, plan_row.cost_currency, left(coalesce(note,''), 400))
  on conflict (workspace_id, shot_id, prompt_version) do update set
    provider_key = excluded.provider_key, model_key = excluded.model_key,
    cost_state = excluded.cost_state, cost_amount = excluded.cost_amount,
    cost_currency = excluded.cost_currency, note = excluded.note
  returning * into saved;
  return jsonb_build_object('shot_id', target_shot, 'prompt_version', saved.prompt_version,
    'provider_key', saved.provider_key, 'cost_state', saved.cost_state, 'cost_amount', saved.cost_amount,
    'cost_currency', saved.cost_currency, 'confirmed_at', saved.updated_at,
    'readiness', tonde_private.ai_readiness_state(target_workspace, target_production, target_shot));
end $$;

revoke all on function tonde.confirm_ai_cost(uuid,uuid,uuid,text) from public, anon, authenticated, service_role;


-- Continuity locks. A lock records what must stay true and what may vary, so the
-- Director can be helpful without quietly changing a locked identity.
create or replace function tonde.set_ai_lock(target_workspace uuid, target_production uuid, payload jsonb,
  expected_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.ai_continuity_locks; scope_value tonde.ai_lock_scope; subject uuid; existing_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'A continuity lock must be a JSON object' using errcode = '22023';
  end if;
  scope_value := coalesce(nullif(payload ->> 'scope',''), 'character')::tonde.ai_lock_scope;
  subject := nullif(payload ->> 'subject_id','')::uuid;
  if subject is not null and not exists (select 1 from tonde.assets a
    where a.workspace_id = target_workspace and a.id = subject) then
    raise exception 'That locked subject is not an Asset in this workspace' using errcode = '23514';
  end if;
  select l.revision into existing_revision from tonde.ai_continuity_locks l
    where l.workspace_id = target_workspace and l.production_id = target_production
      and l.scope = scope_value and l.subject_id is not distinct from subject;
  if existing_revision is not null then
    if expected_revision is not null and existing_revision <> expected_revision then
      raise exception 'That lock changed since you loaded it' using errcode = '40001';
    end if;
    update tonde.ai_continuity_locks l set
      label = left(coalesce(payload ->> 'label', l.label), 200),
      locked = coalesce(tonde_private.ai_json_bool(payload, 'locked', l.locked), l.locked),
      priority = coalesce(nullif(payload ->> 'priority',''), l.priority::text)::tonde.ai_continuity_priority,
      locked_traits = case when payload ? 'locked_traits' then tonde_private.ai_json_text_array(payload,'locked_traits') else l.locked_traits end,
      allowed_variations = case when payload ? 'allowed_variations' then tonde_private.ai_json_text_array(payload,'allowed_variations') else l.allowed_variations end,
      prohibited_changes = case when payload ? 'prohibited_changes' then tonde_private.ai_json_text_array(payload,'prohibited_changes') else l.prohibited_changes end,
      identity_truth = left(coalesce(payload ->> 'identity_truth', l.identity_truth), 400),
      consent_note = left(coalesce(payload ->> 'consent_note', l.consent_note), 400),
      note = left(coalesce(payload ->> 'note', l.note), 600),
      locked_at = case when coalesce(tonde_private.ai_json_bool(payload, 'locked', l.locked), l.locked) then now() end
    where l.id = (select l2.id from tonde.ai_continuity_locks l2
        where l2.workspace_id = target_workspace and l2.production_id = target_production
          and l2.scope = scope_value and l2.subject_id is not distinct from subject)
    returning * into saved;
  else
    insert into tonde.ai_continuity_locks(workspace_id, production_id, scope, subject_id, label, locked,
      priority, locked_traits, allowed_variations, prohibited_changes, identity_truth, consent_note, note, locked_at)
    values (target_workspace, target_production, scope_value, subject,
      left(coalesce(payload ->> 'label',''), 200),
      coalesce(tonde_private.ai_json_bool(payload, 'locked', true), true),
      coalesce(nullif(payload ->> 'priority',''), 'MUST PRESERVE')::tonde.ai_continuity_priority,
      tonde_private.ai_json_text_array(payload,'locked_traits'),
      tonde_private.ai_json_text_array(payload,'allowed_variations'),
      tonde_private.ai_json_text_array(payload,'prohibited_changes'),
      left(coalesce(payload ->> 'identity_truth',''), 400), left(coalesce(payload ->> 'consent_note',''), 400),
      left(coalesce(payload ->> 'note',''), 600),
      case when coalesce(tonde_private.ai_json_bool(payload, 'locked', true), true) then now() end)
    returning * into saved;
  end if;
  return jsonb_build_object('lock_id', saved.id, 'scope', saved.scope, 'subject_id', saved.subject_id,
    'label', saved.label, 'locked', saved.locked, 'priority', saved.priority,
    'locked_traits', to_jsonb(saved.locked_traits), 'allowed_variations', to_jsonb(saved.allowed_variations),
    'prohibited_changes', to_jsonb(saved.prohibited_changes), 'revision', saved.revision);
end $$;

revoke all on function tonde.set_ai_lock(uuid,uuid,jsonb,integer) from public, anon, authenticated, service_role;


-- 16. Generation attempts. Submission is idempotent, so a retry cannot spend twice.
create or replace function tonde.create_ai_attempt(target_workspace uuid, target_production uuid, target_shot uuid,
  payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare plan_row tonde.execution_plans; existing tonde.ai_generation_attempts; saved tonde.ai_generation_attempts;
  idem text; desired_status tonde.ai_attempt_status; mode_value tonde.ai_attempt_mode; op tonde.ai_operation;
  profile tonde.ai_model_profiles; capability jsonb; reference jsonb; next_number integer; provider text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'A generation request must be a JSON object' using errcode = '22023';
  end if;
  select * into plan_row from tonde.execution_plans
    where workspace_id = target_workspace and production_id = target_production
      and shot_id = target_shot and execution_method = 'ai';
  if plan_row.id is null then
    raise exception 'This Shot has no AI plan. Plan it before generating.' using errcode = '23514';
  end if;
  if plan_row.source_shot_revision is not null
    and plan_row.source_shot_revision <> (select revision from tonde.shots
      where workspace_id = target_workspace and production_id = target_production and id = target_shot) then
    raise exception 'The Shot changed after this prompt was compiled. Recompile the prompt before generating.'
      using errcode = '23514';
  end if;
  idem := coalesce(nullif(payload ->> 'idempotency_key',''), '');
  if length(idem) < 8 then
    raise exception 'A generation request needs an idempotency key of at least eight characters' using errcode = '22023';
  end if;
  -- Idempotency first: the same submission returns the same Attempt instead of buying
  -- the same generation again.
  select * into existing from tonde.ai_generation_attempts a
    where a.workspace_id = target_workspace and a.idempotency_key = idem;
  if existing.id is not null then
    return jsonb_build_object('attempt_id', existing.id, 'shot_id', existing.shot_id,
      'attempt_number', existing.attempt_number, 'status', existing.status, 'idempotent', true,
      'mode', existing.mode, 'provider_key', existing.provider_key, 'model_key', existing.model_key,
      'prompt_version', existing.prompt_version, 'cost_state', existing.cost_state,
      'cost_amount', existing.cost_amount, 'cost_currency', existing.cost_currency);
  end if;
  op := coalesce(nullif(payload ->> 'operation','')::tonde.ai_operation,
    tonde_private.ai_primary_operation(target_workspace, target_production, target_shot));
  mode_value := coalesce(nullif(payload ->> 'mode',''), 'live')::tonde.ai_attempt_mode;
  desired_status := coalesce(nullif(payload ->> 'status',''), 'planned')::tonde.ai_attempt_status;
  provider := coalesce(nullif(payload ->> 'provider_key',''), nullif(plan_row.provider_target,''), 'manual');
  if provider <> 'manual' and not exists (select 1 from tonde.ai_providers p where p.key = provider) then
    raise exception 'That provider is not one TONDE recognises' using errcode = '22023';
  end if;
  -- Live submission is the only path that needs a real connection. A model whose declared
  -- facts rule this Shot out is never submitted live, because GENERATE must only be
  -- enabled when capability is compatible.
  if mode_value = 'live' and desired_status in ('queued','submitted','processing')
    and tonde_private.ai_readiness_state(target_workspace, target_production, target_shot) = 'unsupported' then
    raise exception 'The selected model cannot do this Shot. Choose a compatible model before generating.'
      using errcode = '23514';
  end if;
  if mode_value = 'live' and desired_status in ('queued','submitted','processing')
    and not exists (select 1 from tonde.ai_provider_connections c
      where c.workspace_id = target_workspace and c.provider_key = provider and c.state = 'connected') then
    raise exception 'TONDE is not connected to %. Connect it in Setup, or export the prompt and run it yourself.',
      provider using errcode = '23514';
  end if;
  if payload ? 'model_profile_id' and coalesce(payload ->> 'model_profile_id','') <> '' then
    select * into profile from tonde.ai_model_profiles m
      where m.id = (payload ->> 'model_profile_id')::uuid and m.workspace_id = target_workspace and m.lifecycle = 'active';
    if profile.id is null then raise exception 'That model is not declared for this workspace' using errcode = '23514'; end if;
    capability := tonde_private.ai_capability_check(target_workspace, profile.id, target_production, target_shot);
    if capability ->> 'state' = 'UNSUPPORTED' then
      raise exception 'The selected model cannot do this: %',
        array_to_string(array(select jsonb_array_elements_text(capability -> 'reasons')), ' ') using errcode = '23514';
    end if;
  end if;
  -- Reference inputs are private workspace media, never public URLs.
  if jsonb_typeof(payload -> 'input_references') = 'array' then
    for reference in select jsonb_array_elements(payload -> 'input_references') loop
      if coalesce(reference ->> 'url','') ~* '^https?://' then
        raise exception 'Reference inputs must be workspace media, never a public URL' using errcode = '22023';
      end if;
      if reference ? 'asset_id' and not exists (select 1 from tonde.assets a
        where a.workspace_id = target_workspace and a.id = (reference ->> 'asset_id')::uuid) then
        raise exception 'A reference names an Asset outside this workspace' using errcode = '42501';
      end if;
      if reference ? 'media_id' and not exists (select 1 from tonde.media_files f
        where f.workspace_id = target_workspace and f.id = (reference ->> 'media_id')::uuid) then
        raise exception 'A reference names media outside this workspace' using errcode = '42501';
      end if;
    end loop;
  end if;
  -- One live attempt in flight per Shot, prompt version and model.
  if existing.id is null and desired_status in ('queued','submitted','processing') and mode_value = 'live' then
    if exists (select 1 from tonde.ai_generation_attempts a
      where a.workspace_id = target_workspace and a.shot_id = target_shot
        and a.prompt_version = plan_row.prompt_version and a.provider_key = provider
        and a.model_key = coalesce(payload ->> 'model_key', plan_row.model, '') and a.mode = 'live'
        and a.status in ('queued','submitted','processing')) then
      raise exception 'A live generation for this Shot and prompt is already in flight' using errcode = '23514';
    end if;
  end if;
  select coalesce(max(a.attempt_number), 0) + 1 into next_number from tonde.ai_generation_attempts a
    where a.workspace_id = target_workspace and a.shot_id = target_shot;
  insert into tonde.ai_generation_attempts(workspace_id, production_id, shot_id, plan_id, operation,
    attempt_number, provider_key, model_profile_id, model_key, model_version, prompt_version,
    source_shot_revision, idempotency_key, mode, status, external_job_id, seed, settings,
    input_references, request_summary, cost_state, cost_amount, cost_currency, retry_of,
    started_at, failure_code, failure_message)
  values (target_workspace, target_production, target_shot, plan_row.id, op, next_number,
    provider, nullif(payload ->> 'model_profile_id','')::uuid,
    left(coalesce(payload ->> 'model_key', plan_row.model, ''), 120),
    left(coalesce(payload ->> 'model_version', plan_row.model_version, ''), 120),
    coalesce(tonde_private.ai_json_int(payload, 'prompt_version'), plan_row.prompt_version),
    plan_row.source_shot_revision, idem, mode_value, desired_status,
    nullif(payload ->> 'external_job_id',''),
    case when payload ? 'seed' and jsonb_typeof(payload -> 'seed') = 'number' then (payload ->> 'seed')::bigint end,
    coalesce(payload -> 'settings', '{}'::jsonb), coalesce(payload -> 'input_references', '[]'::jsonb),
    coalesce(payload -> 'request_summary', jsonb_build_object('plan_id', plan_row.id,
      'prompt_version', plan_row.prompt_version, 'aspect_ratio', plan_row.aspect_ratio,
      'expected_duration_ms', plan_row.expected_duration_ms)),
    case when left(coalesce(payload ->> 'cost_currency',''),8) <> '' and payload ? 'cost_amount'
      and jsonb_typeof(payload -> 'cost_amount') = 'number' then 'known' else 'unknown' end,
    case when left(coalesce(payload ->> 'cost_currency',''),8) <> '' and payload ? 'cost_amount'
      and jsonb_typeof(payload -> 'cost_amount') = 'number' then (payload ->> 'cost_amount')::numeric(12,4) end,
    left(coalesce(payload ->> 'cost_currency',''), 8), nullif(payload ->> 'retry_of','')::uuid,
    case when desired_status in ('submitted','processing') then now() end,
    left(coalesce(payload ->> 'failure_code',''), 80), left(coalesce(payload ->> 'failure_message',''), 800))
  returning * into saved;
  return jsonb_build_object('attempt_id', saved.id, 'shot_id', saved.shot_id,
    'attempt_number', saved.attempt_number, 'status', saved.status, 'idempotent', false,
    'mode', saved.mode, 'provider_key', saved.provider_key, 'model_key', saved.model_key,
    'prompt_version', saved.prompt_version, 'cost_state', saved.cost_state,
    'cost_amount', saved.cost_amount, 'cost_currency', saved.cost_currency);
end $$;

revoke all on function tonde.create_ai_attempt(uuid,uuid,uuid,jsonb) from public, anon, authenticated, service_role;


-- Attempt progress and completion. Statuses are real transitions, never invented
-- success: a finished attempt named a real output media, and a failed one says why.
-- Retry classification is explicit so a policy refusal is never retried in a loop.
create or replace function tonde.update_ai_attempt(target_workspace uuid, target_production uuid, target_shot uuid,
  target_attempt uuid, payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare attempt tonde.ai_generation_attempts; saved tonde.ai_generation_attempts; media uuid;
  next_status tonde.ai_attempt_status; failure text; retryable_value boolean; result_row tonde.results;
  batch_key uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'An attempt update must be a JSON object' using errcode = '22023';
  end if;
  select * into attempt from tonde.ai_generation_attempts a
    where a.workspace_id = target_workspace and a.production_id = target_production
      and a.shot_id = target_shot and a.id = target_attempt;
  if attempt.id is null then raise exception 'That generation attempt is unavailable' using errcode = 'P0002'; end if;
  next_status := coalesce(nullif(payload ->> 'status','')::tonde.ai_attempt_status, attempt.status);
  if next_status <> attempt.status then
    if not (
      (attempt.status = 'planned' and next_status in ('queued','cancelled','failed'))
      -- In manual mode nothing was submitted to a provider, so a creator who ran the
      -- prompt themselves records the finished output directly. In live mode TONDE does
      -- not skip the submission it is supposedly tracking.
      or (attempt.status = 'planned' and attempt.mode = 'manual'
        and next_status in ('submitted','processing','succeeded','partial'))
      or (attempt.status = 'queued' and next_status in ('submitted','cancelled','failed','expired'))
      or (attempt.status = 'submitted' and next_status in ('processing','succeeded','partial','failed','expired','cancelled'))
      or (attempt.status = 'processing' and next_status in ('succeeded','partial','failed','expired'))
      or (attempt.status in ('succeeded','partial') and next_status in ('partial','failed'))) then
      raise exception 'A generation attempt cannot move from % to %', attempt.status, next_status using errcode = '23514';
    end if;
  end if;
  media := coalesce(nullif(payload ->> 'output_media_id','')::uuid, attempt.output_media_id);
  if next_status in ('succeeded','partial') then
    if media is null then
      raise exception 'A finished attempt must name the media it produced' using errcode = '23514';
    end if;
    if not exists (select 1 from tonde.media_files f
      where f.workspace_id = target_workspace and f.id = media) then
      raise exception 'That output media is not in this workspace' using errcode = '42501';
    end if;
  end if;
  failure := left(coalesce(nullif(payload ->> 'failure_code',''), attempt.failure_code), 80);
  if next_status = 'failed' and failure = '' then
    raise exception 'A failed attempt must say why it failed' using errcode = '23514';
  end if;
  -- Retryable is transient infrastructure only. Anything else is not retried blindly.
  if payload ? 'retryable' then
    retryable_value := tonde_private.ai_json_bool(payload, 'retryable', false);
  elsif next_status in ('failed','expired') and failure <> '' then
    retryable_value := failure = any(array['provider_5xx','rate_limited','network_timeout','provider_unavailable','expired_job']);
  else
    retryable_value := attempt.retryable;
  end if;
  update tonde.ai_generation_attempts a set
    status = next_status,
    external_job_id = left(coalesce(nullif(payload ->> 'external_job_id',''), a.external_job_id), 200),
    seed = case when payload ? 'seed' and jsonb_typeof(payload -> 'seed') = 'number'
      then (payload ->> 'seed')::bigint else a.seed end,
    settings = coalesce(payload -> 'settings', a.settings),
    failure_code = failure,
    failure_message = left(coalesce(nullif(payload ->> 'failure_message',''), a.failure_message), 800),
    retryable = retryable_value,
    cost_state = case when left(coalesce(payload ->> 'cost_currency',''),8) <> '' and payload ? 'cost_amount'
      and jsonb_typeof(payload -> 'cost_amount') = 'number' then 'known' else a.cost_state end,
    cost_amount = case when left(coalesce(payload ->> 'cost_currency',''),8) <> '' and payload ? 'cost_amount'
      and jsonb_typeof(payload -> 'cost_amount') = 'number' then (payload ->> 'cost_amount')::numeric(12,4) else a.cost_amount end,
    cost_currency = left(coalesce(nullif(payload ->> 'cost_currency',''), a.cost_currency), 8),
    output_media_id = media,
    started_at = case when a.started_at is null and next_status in ('submitted','processing','succeeded','partial')
      then now() else a.started_at end,
    completed_at = case when next_status in ('succeeded','partial','failed','cancelled','expired')
      then coalesce(a.completed_at, now()) else a.completed_at end,
    creator_rating = coalesce(tonde_private.ai_json_int(payload, 'creator_rating'), a.creator_rating),
    creator_decision = left(coalesce(nullif(payload ->> 'creator_decision',''), a.creator_decision), 40)
  where a.id = attempt.id returning * into saved;

  -- A finished attempt becomes a Result attached to its canonical Shot, with the
  -- provenance Prompt 9 will need. This does not approve anything.
  if next_status in ('succeeded','partial') and saved.result_id is null and media is not null then
    insert into tonde.results(workspace_id, production_id, scene_id, shot_id, media_id,
      execution_plan_id, state, provenance)
    values (target_workspace, target_production,
      (select h.scene_id from tonde.shots h where h.workspace_id = target_workspace and h.id = target_shot),
      target_shot, media, saved.plan_id, 'needs_review',
      jsonb_build_object('provider', saved.provider_key, 'model', saved.model_key,
        'model_version', saved.model_version, 'operation', saved.operation,
        'attempt_id', saved.id, 'attempt_number', saved.attempt_number,
        'prompt_version', saved.prompt_version, 'source_shot_revision', saved.source_shot_revision,
        'input_references', saved.input_references, 'seed', saved.seed,
        'mode', saved.mode, 'origin', 'ai_generation', 'generated_at', now()))
    returning * into result_row;
    update tonde.ai_generation_attempts a set result_id = result_row.id where a.id = saved.id
      returning * into saved;
  end if;

  -- Keep the batch item for this Shot current, so a partial batch shows real progress
  -- instead of being re-run from the start.
  if next_status in ('succeeded','partial','failed') then
    update tonde.ai_generation_batch_items i set state = case
        when next_status in ('succeeded','partial') then 'succeeded'::tonde.ai_batch_item_state
        else 'failed'::tonde.ai_batch_item_state end,
      attempt_id = saved.id,
      failure_code = case when next_status = 'failed' then failure else '' end,
      failure_message = case when next_status = 'failed'
        then left(coalesce(nullif(payload ->> 'failure_message',''), ''), 800) else '' end
    where i.workspace_id = target_workspace and i.attempt_id = saved.id;
    for batch_key in select distinct i.batch_id from tonde.ai_generation_batch_items i
      where i.workspace_id = target_workspace and i.attempt_id = saved.id loop
      perform tonde_private.ai_batch_refresh(target_workspace, batch_key);
    end loop;
  end if;
  return jsonb_build_object('attempt_id', saved.id, 'shot_id', saved.shot_id, 'status', saved.status,
    'previous_status', attempt.status, 'external_job_id', saved.external_job_id, 'seed', saved.seed,
    'cost_state', saved.cost_state, 'cost_amount', saved.cost_amount, 'cost_currency', saved.cost_currency,
    'retryable', saved.retryable, 'failure_code', saved.failure_code,
    'output_media_id', saved.output_media_id, 'result_id', saved.result_id,
    'result_state', saved.result_state, 'selected', saved.selected, 'revision', saved.revision);
end $$;

revoke all on function tonde.update_ai_attempt(uuid,uuid,uuid,uuid,jsonb) from public, anon, authenticated, service_role;


-- Selecting a Result means "this is the current output", never "this Shot is approved".
create or replace function tonde.select_ai_result(target_workspace uuid, target_production uuid, target_shot uuid,
  target_attempt uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare attempt tonde.ai_generation_attempts; result_state_value tonde.result_state; result_approval tonde.approval;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into attempt from tonde.ai_generation_attempts a
    where a.workspace_id = target_workspace and a.production_id = target_production
      and a.shot_id = target_shot and a.id = target_attempt;
  if attempt.id is null then raise exception 'That generation attempt is unavailable' using errcode = 'P0002'; end if;
  if attempt.output_media_id is null then
    raise exception 'That attempt has no output to select' using errcode = '23514';
  end if;
  -- Deselecting the previous output clears the selection only. The creator's earlier decision
  -- (needs_review, reject) is theirs to change, not something a new selection overwrites.
  update tonde.ai_generation_attempts a set selected = false
    where a.workspace_id = target_workspace and a.shot_id = target_shot and a.selected and a.id <> target_attempt;
  -- Selecting an output records the choice. A creator decision the creator already made is
  -- left exactly as it is; only an undecided Attempt defaults to 'keep'.
  update tonde.ai_generation_attempts a set selected = true,
    creator_decision = case when a.creator_decision = '' then 'keep' else a.creator_decision end
    where a.id = target_attempt;
  -- The Shot's own approval is untouched, and the Result keeps its own state.
  select state, approval into result_state_value, result_approval from tonde.results r where r.id = attempt.result_id;
  return jsonb_build_object('shot_id', target_shot, 'attempt_id', target_attempt, 'selected', true,
    'result_id', attempt.result_id, 'result_state', result_state_value, 'result_approval', result_approval,
    'shot_approval', (select h.approval from tonde.shots h
      where h.workspace_id = target_workspace and h.id = target_shot),
    'truthfulness', 'Selected means chosen current output. It is not a Shot approval.');
end $$;

revoke all on function tonde.select_ai_result(uuid,uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- Batch progress lives in one place, so the batch row and its per-Shot items can never
-- disagree about how far a job actually got.
create or replace function tonde_private.ai_batch_refresh(target_workspace uuid, target_batch uuid)
returns tonde.ai_batch_state language plpgsql security definer set search_path = '' as $$
declare succeeded integer; failed integer; active integer; total integer; state_value tonde.ai_batch_state;
begin
  select count(*) filter (where state = 'succeeded'), count(*) filter (where state = 'failed'),
    count(*) filter (where state in ('pending','submitted')), count(*)
    into succeeded, failed, active, total
  from tonde.ai_generation_batch_items i
  where i.workspace_id = target_workspace and i.batch_id = target_batch;
  if total = 0 then return 'confirmed'; end if;
  -- A batch claims success only when every Shot in it succeeded. A blocked or failed Shot
  -- keeps it partial, because eight of ten is not ten.
  state_value := case
    when active > 0 then 'running'::tonde.ai_batch_state
    when succeeded = total then 'succeeded'::tonde.ai_batch_state
    when failed > 0 and succeeded > 0 then 'partial'::tonde.ai_batch_state
    when failed > 0 and succeeded = 0 then 'failed'::tonde.ai_batch_state
    else 'partial'::tonde.ai_batch_state end;
  update tonde.ai_generation_batches b set state = state_value where b.id = target_batch;
  return state_value;
end $$;

revoke all on function tonde_private.ai_batch_refresh(uuid,uuid) from public, anon, authenticated, service_role;


-- 17. Batch generation. Preview first, so a paid batch is never launched blind, and
-- every Shot carries its own item so a partial failure preserves what worked.
create or replace function tonde_private.ai_batch_candidates(target_workspace uuid, target_production uuid,
  target_shot uuid, payload jsonb)
returns uuid[] language plpgsql stable security definer set search_path = '' as $$
declare scope_value tonde.ai_batch_scope; ids uuid[];
begin
  scope_value := coalesce(nullif(payload ->> 'scope',''), 'shot')::tonde.ai_batch_scope;
  if scope_value = 'shot' then
    return array[coalesce(nullif(payload ->> 'shot_id','')::uuid, target_shot)];
  elsif scope_value = 'selection' then
    if jsonb_typeof(payload -> 'shot_ids') <> 'array' then
      raise exception 'A selected batch needs the Shot identifiers it covers' using errcode = '22023';
    end if;
    select array(select (value)::uuid from jsonb_array_elements_text(payload -> 'shot_ids') as value)
      into ids;
    return coalesce(ids, '{}'::uuid[]);
  elsif scope_value = 'scene' then
    select array(select h.id from tonde.shots h
      where h.workspace_id = target_workspace and h.production_id = target_production
        and h.scene_id = coalesce(nullif(payload ->> 'scene_id','')::uuid, target_shot)
        and h.lifecycle = 'active' and h.execution_method in ('ai','hybrid')
      order by h.sort_order, h.id) into ids;
    return coalesce(ids, '{}'::uuid[]);
  else
    select array(select h.id from tonde.shots h
      where h.workspace_id = target_workspace and h.production_id = target_production
        and h.lifecycle = 'active' and h.execution_method in ('ai','hybrid')
      order by h.sort_order, h.id) into ids;
    return coalesce(ids, '{}'::uuid[]);
  end if;
end $$;

revoke all on function tonde_private.ai_batch_candidates(uuid,uuid,uuid,jsonb) from public, anon, authenticated, service_role;


create or replace function tonde.ai_batch_preview(target_workspace uuid, target_production uuid, target_shot uuid,
  payload jsonb default '{}'::jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare candidates uuid[]; shots jsonb; summary jsonb; cost jsonb; confirmation boolean; reasons text[] := '{}';
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  candidates := tonde_private.ai_batch_candidates(target_workspace, target_production, target_shot, coalesce(payload,'{}'::jsonb));
  if cardinality(candidates) = 0 then
    raise exception 'There are no AI or Hybrid Shots in that scope' using errcode = '23514';
  end if;
  with rows as (
    select h.id as shot_id, h.title, h.planned_duration_ms,
      tonde_private.ai_readiness_state(target_workspace, target_production, h.id) as readiness,
      p.provider_target, p.model as model_key, p.model_profile_id, p.expected_duration_ms,
      p.aspect_ratio,
      -- Cost truth: the plan's own recorded cost, or the pricing declared on the model it
      -- selected. If neither exists the batch says unknown rather than inventing a number.
      case when coalesce(p.cost_state,'unknown') = 'known'
        or (m.cost_amount is not null and coalesce(m.cost_currency,'') <> '') then 'known' else 'unknown' end as cost_state,
      coalesce(p.cost_amount, m.cost_amount) as cost_amount,
      coalesce(nullif(p.cost_currency,''), m.cost_currency, '') as cost_currency,
      coalesce(p.routing -> 'cost_confirmation' ->> 'required','false') = 'true' as wants_confirmation,
      m.label as model_label,
      exists (select 1 from tonde.ai_provider_connections c where c.workspace_id = target_workspace
        and c.provider_key = p.provider_target and c.state = 'connected') as live,
      (select count(*) from tonde.ai_shot_references r where r.workspace_id = target_workspace
        and r.plan_id = p.id and r.priority = 'MUST PRESERVE') as must_references,
      (select count(*) from tonde.ai_shot_references r where r.workspace_id = target_workspace
        and r.plan_id = p.id and r.priority = 'MUST PRESERVE' and r.asset_id is not null) as held_references
    from unnest(candidates) c(shot_id)
    join tonde.shots h on h.workspace_id = target_workspace and h.id = c.shot_id
    left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
      and p.execution_method = 'ai'
    left join tonde.ai_model_profiles m on m.id = p.model_profile_id
  )
  select coalesce(jsonb_agg(jsonb_build_object(
      'shot_id', shot_id, 'title', title, 'readiness', readiness,
      'blocked', readiness not in ('ready_to_generate','manual_export'),
      'blocked_reason', case
        when readiness = 'unplanned' then 'No AI plan yet.'
        when readiness = 'needs_model' then 'No compatible model is selected.'
        when readiness = 'needs_reference' then 'Required references are missing.'
        when readiness = 'provider_not_connected' then 'The provider is not connected.'
        when readiness = 'unsupported' then 'The selected model cannot do this.'
        when readiness = 'needs_decision' then 'A decision is required before generating.'
        when readiness = 'stale' then 'The Shot changed after the prompt was compiled.'
        when readiness = 'cost_confirmation' then 'Generation cost needs your confirmation.'
        else '' end,
      'provider_key', provider_target, 'model_key', model_key, 'model_label', model_label,
      'model_profile_id', model_profile_id, 'live', coalesce(live, false),
      'cost_state', coalesce(cost_state, 'unknown'), 'cost_amount', cost_amount,
      'cost_currency', cost_currency, 'duration_ms', coalesce(expected_duration_ms, planned_duration_ms),
      'aspect_ratio', coalesce(aspect_ratio, ''), 'must_references', coalesce(must_references, 0),
      'held_references', coalesce(held_references, 0), 'manual_export', readiness = 'manual_export')
      order by shot_id), '[]'::jsonb),
    jsonb_build_object(
      'shots', count(*),
      'ready', count(*) filter (where readiness = 'ready_to_generate'),
      'manual_export', count(*) filter (where readiness = 'manual_export'),
      'blocked', count(*) filter (where readiness not in ('ready_to_generate','manual_export')),
      'live', count(*) filter (where coalesce(live,false)),
      'known_cost', count(*) filter (where cost_state = 'known'),
      'unknown_cost', count(*) filter (where coalesce(cost_state,'unknown') <> 'known'))
  into shots, summary from rows;
  with rows as (
    select case when coalesce(p.cost_state,'unknown') = 'known'
        or (m.cost_amount is not null and coalesce(m.cost_currency,'') <> '') then 'known' else 'unknown' end as cost_state,
      coalesce(p.cost_amount, m.cost_amount) as cost_amount,
      coalesce(nullif(p.cost_currency,''), m.cost_currency, '') as cost_currency,
      p.provider_target,
      coalesce(p.routing -> 'cost_confirmation' ->> 'required','false') = 'true' as wants_confirmation,
      exists (select 1 from tonde.ai_provider_connections c where c.workspace_id = target_workspace
        and c.provider_key = p.provider_target and c.state = 'connected') as live
    from unnest(candidates) c(shot_id)
    join tonde.execution_plans p on p.workspace_id = target_workspace
      and p.production_id = target_production and p.shot_id = c.shot_id and p.execution_method = 'ai'
    left join tonde.ai_model_profiles m on m.id = p.model_profile_id
  )
  select jsonb_build_object(
      'state', case when count(*) filter (where cost_state <> 'known') > 0 then 'unknown' else 'known' end,
      'amount', case when count(*) filter (where cost_state <> 'known') = 0 then sum(cost_amount) end,
      'currency', case when count(*) filter (where cost_state <> 'known') = 0
        then min(cost_currency) end,
      'known_subtotal_amount', coalesce(sum(cost_amount) filter (where cost_state = 'known'), 0),
      'known_subtotal_currency', coalesce(min(cost_currency) filter (where cost_state = 'known'), ''),
      'unknown_count', count(*) filter (where cost_state <> 'known'),
      'note', case when count(*) filter (where cost_state <> 'known') > 0
        then 'Some selected models have no verified pricing. TONDE will not invent an amount.'
        else 'Based on the pricing you declared for each model.' end),
    (count(*) filter (where coalesce(live,false) and coalesce(wants_confirmation,false))) > 0
      or (count(*) filter (where coalesce(live,false) and cost_state = 'known' and cost_amount > 0)) > 0
  into cost, confirmation from rows;
  if confirmation then
    reasons := array_append(reasons, 'A connected provider with declared pricing is included, so this batch spends real money.');
  end if;
  if (summary ->> 'unknown_cost')::integer > 0 then
    reasons := array_append(reasons, 'Some Shots have no verified pricing, so TONDE reports COST UNKNOWN rather than a number.');
  end if;
  return jsonb_build_object('production_id', target_production, 'scope',
    coalesce(nullif(payload ->> 'scope',''), 'shot'), 'shots', shots, 'summary', summary,
    'cost', cost, 'confirmation_required', confirmation,
    'confirmation_reasons', to_jsonb(reasons),
    'partial_failure_policy', 'Each Shot keeps its own Attempt, so a failure preserves the Shots that succeeded.');
end $$;

revoke all on function tonde.ai_batch_preview(uuid,uuid,uuid,jsonb) from public, anon, authenticated, service_role;


create or replace function tonde.create_ai_batch(target_workspace uuid, target_production uuid, target_shot uuid,
  payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare preview jsonb; saved tonde.ai_generation_batches; item jsonb; scope_value tonde.ai_batch_scope;
  shot_key uuid; attempt_saved tonde.ai_generation_attempts; plan_row tonde.execution_plans;
  next_number integer; blocked boolean; item_state tonde.ai_batch_item_state;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if payload is null or jsonb_typeof(payload) <> 'object' then
    raise exception 'A batch request must be a JSON object' using errcode = '22023';
  end if;
  preview := tonde.ai_batch_preview(target_workspace, target_production, target_shot, payload);
  -- Material external spend needs the creator, always.
  if (preview ->> 'confirmation_required')::boolean
    and coalesce(payload ->> 'confirmed','false') <> 'true' then
    raise exception 'This batch spends real money at the provider. Confirm the batch before it is created.'
      using errcode = '23514';
  end if;
  scope_value := coalesce(nullif(payload ->> 'scope',''), 'shot')::tonde.ai_batch_scope;
  insert into tonde.ai_generation_batches(workspace_id, production_id, scope, scene_id, state,
    confirmation_required, confirmation_note, confirmed_at, confirmed_by,
    cost_state, estimated_cost_amount, estimated_cost_currency,
    shot_count, blocked_count, unknown_cost_count, note)
  values (target_workspace, target_production, scope_value,
    nullif(payload ->> 'scene_id','')::uuid, 'confirmed',
    (preview ->> 'confirmation_required')::boolean, left(coalesce(payload ->> 'note',''), 400),
    case when (preview ->> 'confirmation_required')::boolean then now() end,
    case when (preview ->> 'confirmation_required')::boolean then auth.uid() end,
    preview -> 'cost' ->> 'state',
    case when preview -> 'cost' ->> 'state' = 'known'
      then (preview -> 'cost' ->> 'amount')::numeric(12,4) end,
    coalesce(preview -> 'cost' ->> 'currency', ''),
    (preview -> 'summary' ->> 'shots')::integer, (preview -> 'summary' ->> 'blocked')::integer,
    (preview -> 'summary' ->> 'unknown_cost')::integer, left(coalesce(payload ->> 'note',''), 600))
  returning * into saved;
  -- One item per Shot, and a planned Attempt for everything that is not blocked, so the
  -- batch is a durable job rather than a loop that holds a request open.
  for item in select jsonb_array_elements(preview -> 'shots') loop
    shot_key := (item ->> 'shot_id')::uuid;
    blocked := (item ->> 'blocked')::boolean;
    item_state := case when blocked then 'blocked'::tonde.ai_batch_item_state else 'pending'::tonde.ai_batch_item_state end;
    attempt_saved := null;
    if not blocked then
      select * into plan_row from tonde.execution_plans p
        where p.workspace_id = target_workspace and p.production_id = target_production
          and p.shot_id = shot_key and p.execution_method = 'ai';
      select coalesce(max(a.attempt_number), 0) + 1 into next_number from tonde.ai_generation_attempts a
        where a.workspace_id = target_workspace and a.shot_id = shot_key;
      insert into tonde.ai_generation_attempts(workspace_id, production_id, shot_id, plan_id, operation,
        attempt_number, provider_key, model_profile_id, model_key, model_version, prompt_version,
        source_shot_revision, idempotency_key, mode, status, settings, input_references, request_summary,
        cost_state, cost_amount, cost_currency)
      -- The operation the Shot actually needs, not a blanket 'video': a narration Shot batched
      -- through here is recorded as the speech attempt it is.
      values (target_workspace, target_production, shot_key, plan_row.id,
        tonde_private.ai_primary_operation(target_workspace, target_production, shot_key), next_number,
        coalesce(plan_row.provider_target, 'manual'), plan_row.model_profile_id, coalesce(plan_row.model, ''),
        plan_row.model_version, plan_row.prompt_version, plan_row.source_shot_revision,
        'batch:' || saved.id::text || ':' || shot_key::text,
        case when plan_row.provider_target is null or plan_row.provider_target in ('','manual')
          then 'manual'::tonde.ai_attempt_mode else 'live'::tonde.ai_attempt_mode end,
        'planned', '{}'::jsonb,
        coalesce((select jsonb_agg(jsonb_build_object('role', r.reference_role, 'asset_id', r.asset_id,
            'media_id', r.media_id) order by r.sort_order)
          from tonde.ai_shot_references r where r.workspace_id = target_workspace and r.plan_id = plan_row.id), '[]'::jsonb),
        jsonb_build_object('batch_id', saved.id, 'prompt_version', plan_row.prompt_version),
        coalesce(plan_row.cost_state, 'unknown'), plan_row.cost_amount,
        coalesce(plan_row.cost_currency, ''))
      on conflict (workspace_id, idempotency_key) do nothing
      returning * into attempt_saved;
      if attempt_saved.id is null then
        select * into attempt_saved from tonde.ai_generation_attempts a
          where a.workspace_id = target_workspace
            and a.idempotency_key = 'batch:' || saved.id::text || ':' || shot_key::text;
      end if;
    end if;
    insert into tonde.ai_generation_batch_items(workspace_id, production_id, batch_id, shot_id, state,
      blocked_reason, attempt_id, cost_state, cost_amount, cost_currency)
    values (target_workspace, target_production, saved.id, shot_key, item_state,
      case when blocked then left(coalesce(item ->> 'blocked_reason',''), 200) else '' end,
      attempt_saved.id, coalesce(item ->> 'cost_state','unknown'),
      case when item ->> 'cost_state' = 'known' then (item ->> 'cost_amount')::numeric(12,4) end,
      coalesce(item ->> 'cost_currency',''))
    on conflict (batch_id, shot_id) do nothing;
  end loop;
  return jsonb_build_object('batch_id', saved.id, 'production_id', target_production, 'scope', saved.scope,
    'state', saved.state, 'confirmation_required', saved.confirmation_required,
    'confirmed_at', saved.confirmed_at, 'cost_state', saved.cost_state,
    'estimated_cost_amount', saved.estimated_cost_amount,
    'estimated_cost_currency', saved.estimated_cost_currency,
    'summary', preview -> 'summary', 'cost', preview -> 'cost',
    'items', (select coalesce(jsonb_agg(jsonb_build_object('shot_id', i.shot_id, 'state', i.state,
        'blocked_reason', i.blocked_reason, 'attempt_id', i.attempt_id,
        'cost_state', i.cost_state, 'cost_amount', i.cost_amount,
        'cost_currency', i.cost_currency) order by i.shot_id), '[]'::jsonb)
      from tonde.ai_generation_batch_items i
      where i.workspace_id = target_workspace and i.batch_id = saved.id));
end $$;

revoke all on function tonde.create_ai_batch(uuid,uuid,uuid,jsonb) from public, anon, authenticated, service_role;


-- Per-item progress. A partial batch keeps its successes and retries only what failed.
create or replace function tonde.record_ai_batch_item(target_workspace uuid, target_production uuid,
  target_batch uuid, target_shot uuid, payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare item tonde.ai_generation_batch_items; batch tonde.ai_generation_batches;
  next_state tonde.ai_batch_item_state; succeeded integer; failed integer; running integer; total integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into item from tonde.ai_generation_batch_items i
    where i.workspace_id = target_workspace and i.production_id = target_production
      and i.batch_id = target_batch and i.shot_id = target_shot;
  if item.id is null then raise exception 'That Shot is not part of that batch' using errcode = 'P0002'; end if;
  select * into batch from tonde.ai_generation_batches b
    where b.workspace_id = target_workspace and b.id = target_batch;
  -- Failed and partial batches stay open on purpose: that is where a retry lives. A batch
  -- whose every Shot succeeded has nothing left to record.
  if batch.state in ('succeeded','cancelled') then
    raise exception 'That batch is already closed' using errcode = '23514';
  end if;
  next_state := coalesce(nullif(payload ->> 'state','')::tonde.ai_batch_item_state, item.state);
  update tonde.ai_generation_batch_items i set
    state = next_state,
    blocked_reason = left(coalesce(payload ->> 'blocked_reason', i.blocked_reason), 200),
    attempt_id = coalesce(nullif(payload ->> 'attempt_id','')::uuid, i.attempt_id),
    failure_code = left(coalesce(payload ->> 'failure_code', i.failure_code), 80),
    failure_message = left(coalesce(payload ->> 'failure_message', i.failure_message), 800)
  where i.id = item.id returning * into item;
  -- The Attempt carries the same failure, so the batch item and the Attempt never
  -- disagree about why a Shot did not generate.
  if next_state = 'failed' and item.attempt_id is not null then
    update tonde.ai_generation_attempts a set
      status = 'failed',
      failure_code = left(coalesce(payload ->> 'failure_code', 'provider_error'), 80),
      failure_message = left(coalesce(payload ->> 'failure_message', ''), 800),
      retryable = left(coalesce(payload ->> 'failure_code', ''), 80) = any(array['provider_5xx','rate_limited','network_timeout','provider_unavailable','expired_job']),
      completed_at = coalesce(a.completed_at, now())
    where a.workspace_id = target_workspace and a.id = item.attempt_id
      and a.status in ('planned','queued','submitted','processing');
  end if;
  perform tonde_private.ai_batch_refresh(target_workspace, target_batch);
  select * into batch from tonde.ai_generation_batches b where b.id = target_batch;
  select count(*) filter (where state = 'succeeded'), count(*) filter (where state = 'failed'),
    count(*) filter (where state in ('pending','submitted')), count(*)
    into succeeded, failed, running, total
  from tonde.ai_generation_batch_items i
  where i.workspace_id = target_workspace and i.batch_id = target_batch;
  return jsonb_build_object('batch_id', batch.id, 'state', batch.state, 'shot_id', target_shot,
    'item_state', item.state, 'attempt_id', item.attempt_id,
    'failure_code', item.failure_code, 'failure_message', item.failure_message,
    'progress', jsonb_build_object('succeeded', succeeded, 'failed', failed, 'total', total),
    'partial_failure_policy', 'Retry only the failed Shots; the successful Attempts are kept.');
end $$;

revoke all on function tonde.record_ai_batch_item(uuid,uuid,uuid,uuid,jsonb) from public, anon, authenticated, service_role;


-- 18. Privileges: authenticated only, never anon or service_role. Private helpers stay
-- unreachable from the API.
revoke all on function tonde.ai_creation_surface(uuid,uuid,integer),
  tonde.ai_shot_detail(uuid,uuid,uuid),
  tonde.ai_model_catalog(uuid),
  tonde.ai_capability_verdict(uuid,uuid,uuid,uuid),
  tonde.declare_ai_model(uuid,jsonb,integer),
  tonde.set_ai_connection(uuid,text,text,text,text,integer),
  tonde.save_ai_plan(uuid,uuid,uuid,integer,jsonb,jsonb,integer),
  tonde.set_ai_plan_approval(uuid,uuid,uuid,text,integer),
  tonde.set_ai_plan_lock(uuid,uuid,uuid,boolean,integer),
  tonde.confirm_ai_cost(uuid,uuid,uuid,text),
  tonde.set_ai_lock(uuid,uuid,jsonb,integer),
  tonde.create_ai_attempt(uuid,uuid,uuid,jsonb),
  tonde.update_ai_attempt(uuid,uuid,uuid,uuid,jsonb),
  tonde.select_ai_result(uuid,uuid,uuid,uuid),
  tonde.ai_batch_preview(uuid,uuid,uuid,jsonb),
  tonde.create_ai_batch(uuid,uuid,uuid,jsonb),
  tonde.record_ai_batch_item(uuid,uuid,uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_creation_surface(uuid,uuid,integer),
  tonde.ai_capability_verdict(uuid,uuid,uuid,uuid),
  tonde.ai_shot_detail(uuid,uuid,uuid),
  tonde.ai_model_catalog(uuid),
  tonde.declare_ai_model(uuid,jsonb,integer),
  tonde.set_ai_connection(uuid,text,text,text,text,integer),
  tonde.save_ai_plan(uuid,uuid,uuid,integer,jsonb,jsonb,integer),
  tonde.set_ai_plan_approval(uuid,uuid,uuid,text,integer),
  tonde.set_ai_plan_lock(uuid,uuid,uuid,boolean,integer),
  tonde.confirm_ai_cost(uuid,uuid,uuid,text),
  tonde.set_ai_lock(uuid,uuid,jsonb,integer),
  tonde.create_ai_attempt(uuid,uuid,uuid,jsonb),
  tonde.update_ai_attempt(uuid,uuid,uuid,uuid,jsonb),
  tonde.select_ai_result(uuid,uuid,uuid,uuid),
  tonde.ai_batch_preview(uuid,uuid,uuid,jsonb),
  tonde.create_ai_batch(uuid,uuid,uuid,jsonb),
  tonde.record_ai_batch_item(uuid,uuid,uuid,uuid,jsonb)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050018_long_form_series.sql
-- ==========================================================================

-- Additive migration: Prompt 8 long-form, Movie Mode, Series and Production Line.
-- Canonical hierarchy only: Production -> optional Act -> optional Sequence -> Scene -> Shot,
-- and Series -> optional Season/Collection -> Episode/Production.
-- No movie_scenes / series_scenes / episode_shots table exists or ever will: the same
-- canonical Scene and Shot are reused, and every derived number below is COMPUTED at read
-- time so no rollup silently overwrites a creator's planned runtime.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.series_kind as enum ('narrative','recurring')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.planning_depth as enum
  ('idea','outlined','story_defined','scripted','scenes_planned','shots_planned','execution_planned','in_progress')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.sequence_kind as enum
  ('narrative','mission','location','topic','montage','action','documentary','thematic','custom')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.structure_level as enum ('production','act','sequence','scene','shot')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.generate_horizon as enum ('tomorrow','next_7','next_14','next_30','entire_series','custom')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.generate_depth as enum ('ideas_only','briefs','story','script','complete_plan')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Act: narrative purpose. Acts group lower structure; they are not a second Production.
alter table tonde.acts add column if not exists purpose text not null default '' check (length(purpose) <= 1200);

alter table tonde.acts add column if not exists narrative_goal text not null default '' check (length(narrative_goal) <= 1200);

alter table tonde.acts add column if not exists opening_state text not null default '' check (length(opening_state) <= 600);

alter table tonde.acts add column if not exists ending_state text not null default '' check (length(ending_state) <= 600);

alter table tonde.acts add column if not exists summary jsonb not null default '{}' check (jsonb_typeof(summary) = 'object');

alter table tonde.acts add column if not exists lifecycle tonde.lifecycle not null default 'active';

create index if not exists acts_live_order on tonde.acts(workspace_id, production_id, lifecycle, sort_order) where lifecycle = 'active';


-- 3. Sequence: related Scenes. Kind covers narrative, documentary, topic and montage use.
alter table tonde.sequences add column if not exists purpose text not null default '' check (length(purpose) <= 1200);

alter table tonde.sequences add column if not exists kind tonde.sequence_kind not null default 'narrative';

alter table tonde.sequences add column if not exists summary jsonb not null default '{}' check (jsonb_typeof(summary) = 'object');

alter table tonde.sequences add column if not exists lifecycle tonde.lifecycle not null default 'active';

create index if not exists sequences_live_order on tonde.sequences(workspace_id, production_id, lifecycle, act_id, sort_order)
  where lifecycle = 'active';


-- 4. A Scene may sit directly inside an Act (Production -> Act -> Scene) without inventing a
-- placeholder Sequence. sequence_id stays the primary parent when both are set, and a
-- consistency guard below keeps act_id equal to the Sequence's Act.
alter table tonde.scenes add column if not exists act_id uuid;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.scenes') and conname = 'scenes_act_scope'
  ) then
    execute $tonde_idem_ddl$alter table tonde.scenes add constraint scenes_act_scope
  foreign key (workspace_id, production_id, act_id) references tonde.acts(workspace_id, production_id, id) on delete restrict$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

create index if not exists scenes_live_act_order on tonde.scenes(workspace_id, production_id, act_id, lifecycle, sort_order)
  where lifecycle = 'active';


-- 5. Series. Recurring organization around canonical Productions. Season/Collection stays
-- optional and keep its existing `series_collections` home.
alter table tonde.series add column if not exists series_kind tonde.series_kind not null default 'recurring';

alter table tonde.series add column if not exists format jsonb not null default '{}' check (jsonb_typeof(format) = 'object');

alter table tonde.series add column if not exists timezone text not null default 'UTC' check (length(btrim(timezone)) between 1 and 60);

alter table tonde.series add column if not exists revision integer not null default 1 check (revision > 0);

alter table tonde.series add column if not exists summary jsonb not null default '{}' check (jsonb_typeof(summary) = 'object');

alter table tonde.series_collections add column if not exists purpose text not null default '' check (length(purpose) <= 1200);

alter table tonde.series_collections add column if not exists lifecycle tonde.lifecycle not null default 'active';

alter table tonde.series_collections add column if not exists revision integer not null default 1 check (revision > 0);


-- 6. Episode is an association around the same canonical Production, never a second content model.
alter table tonde.series_episodes add column if not exists title text not null default '' check (length(title) <= 160);

alter table tonde.series_episodes add column if not exists slot_key text check (length(slot_key) between 1 and 80);

alter table tonde.series_episodes add column if not exists requested_depth tonde.generate_depth;

alter table tonde.series_episodes add column if not exists brief jsonb not null default '{}' check (jsonb_typeof(brief) = 'object');

alter table tonde.series_episodes add column if not exists lifecycle tonde.lifecycle not null default 'active';

alter table tonde.series_episodes add column if not exists revision integer not null default 1 check (revision > 0);

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.series_episodes') and conname = 'series_episodes_workspace_identity'
  ) then
    execute $tonde_idem_ddl$alter table tonde.series_episodes add constraint series_episodes_workspace_identity unique (workspace_id, id)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

create unique index if not exists series_episodes_slot_key on tonde.series_episodes(series_id, slot_key) where slot_key is not null;

create index if not exists series_episodes_schedule on tonde.series_episodes(workspace_id, series_id, lifecycle, planned_date, episode_number);


-- 7. Derived summaries. A summary records the revision it was derived from; when the object
-- moves on, the summary is reported stale instead of being treated as current truth.
create table if not exists tonde.structure_summaries (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, scope_object_id uuid not null,
  scope_level tonde.structure_level not null check (scope_level <> 'shot'),
  source_revision integer not null check (source_revision > 0),
  content jsonb not null default '{}' check (jsonb_typeof(content) = 'object'),
  generated_by text not null default 'creator' check (generated_by in ('creator','tonde','system')),
  note text not null default '' check (length(note) <= 400),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, scope_object_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, scope_object_id) references tonde.objects(workspace_id, id) on delete restrict
);


-- 8. Generate Ahead is a durable job with per-slot items so partial success persists and a
-- retry only touches what is missing. The same job also appears in the shared `jobs` surface.
do $tonde_idem$
begin
  if not exists (select 1 from pg_constraint c where c.conrelid=to_regclass('tonde.jobs')
        and c.conname='jobs_job_type_check' and regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(pg_get_constraintdef(c.oid)), 'tonde\.', '', 'g'), '::[a-z_][a-z0-9_.]*', '', 'g'), '[\s()\[\]]', '', 'g'), '''', '', 'g'), '<>allarray', 'notin', 'g'), '=anyarray', 'in', 'g')='checkjob_typeinmedia_preprocessing,transcription,reference_analysis,story_generation,production_generation,prompt_compilation,shot_match,export,thumbnail,proxy,cloud_import,long_form_generation,media_scan,media_derivation,publication_submission,provider_reconciliation,notification_delivery,retention_sweep,deletion_orchestration,knowledge_ingestion') then
    execute $tonde_idem_ddl$alter table tonde.jobs drop constraint if exists jobs_job_type_check$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (select 1 from pg_constraint c where c.conrelid=to_regclass('tonde.jobs')
        and c.conname='jobs_job_type_check' and regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(pg_get_constraintdef(c.oid)), 'tonde\.', '', 'g'), '::[a-z_][a-z0-9_.]*', '', 'g'), '[\s()\[\]]', '', 'g'), '''', '', 'g'), '<>allarray', 'notin', 'g'), '=anyarray', 'in', 'g')='checkjob_typeinmedia_preprocessing,transcription,reference_analysis,story_generation,production_generation,prompt_compilation,shot_match,export,thumbnail,proxy,cloud_import,long_form_generation,media_scan,media_derivation,publication_submission,provider_reconciliation,notification_delivery,retention_sweep,deletion_orchestration,knowledge_ingestion') then
    execute $tonde_idem_ddl$alter table tonde.jobs add constraint jobs_job_type_check check (job_type in
  ('media_preprocessing','transcription','reference_analysis','story_generation','production_generation',
   'prompt_compilation','shot_match','export','thumbnail','proxy','cloud_import','long_form_generation'))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

create table if not exists tonde.generate_ahead_jobs (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, series_id uuid not null,
  job_id uuid,
  horizon tonde.generate_horizon not null, depth tonde.generate_depth not null,
  requested_count integer not null default 0 check (requested_count between 0 and 400),
  base_date date, timezone text not null default 'UTC' check (length(btrim(timezone)) between 1 and 60),
  state tonde.job_state not null default 'queued',    preview jsonb not null default '{}' check (jsonb_typeof(preview) = 'object'),
  created_count integer not null default 0 check (created_count >= 0),
  preserved_count integer not null default 0 check (preserved_count >= 0),
  blocked_count integer not null default 0 check (blocked_count >= 0),
  failed_count integer not null default 0 check (failed_count >= 0),
  note text not null default '' check (length(note) <= 400),
  revision integer not null default 1 check (revision > 0),
  requested_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, series_id) references tonde.series(workspace_id, id) on delete restrict,
  foreign key (workspace_id, job_id) references tonde.jobs(workspace_id, id) on delete restrict
);

create index if not exists generate_ahead_jobs_series on tonde.generate_ahead_jobs(workspace_id, series_id, created_at desc);

create table if not exists tonde.generate_ahead_items (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, job_id uuid not null,
  slot_key text not null check (length(slot_key) between 1 and 80), planned_date date,
  episode_number bigint check (episode_number > 0),
  state text not null default 'pending' check (state in ('pending','created','preserved','blocked','failed')),
  -- Named for what they are: this row is a durable job item, not a Production record, so the
  -- shared mutation guard must never read these as an owner identity.
  created_production_id uuid, created_episode_id uuid,
  error_code text check (length(error_code) <= 40), error_message text check (length(error_message) <= 400),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, job_id, slot_key),
  foreign key (workspace_id, job_id) references tonde.generate_ahead_jobs(workspace_id, id) on delete restrict,
  foreign key (workspace_id, created_production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, created_episode_id) references tonde.series_episodes(workspace_id, id) on delete restrict
);

create index if not exists generate_ahead_items_state on tonde.generate_ahead_items(workspace_id, job_id, state);


