do $$ declare item text; begin
  foreach item in array array['structure_summaries','generate_ahead_jobs','generate_ahead_items'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;


-- 10. Semantic link guard: a Scene's Act must be the Act of its Sequence when both are set.
create or replace function tonde_private.lf_scene_parent_guard() returns trigger
language plpgsql security definer set search_path = '' as $$
declare sequence_act uuid;
begin
  if new.sequence_id is not null then
    select act_id into sequence_act from tonde.sequences
      where workspace_id = new.workspace_id and production_id = new.production_id and id = new.sequence_id;
    -- A missing or cross-Production Sequence is left to the canonical foreign key, which reports
    -- it with the standard ownership error. This guard only keeps Act and Sequence consistent.
    if found and new.act_id is distinct from sequence_act then
      raise exception 'A Scene in a Sequence belongs to that Sequence''s Act' using errcode = '23514';
    end if;
  end if;
  return new;
end $$;

revoke all on function tonde_private.lf_scene_parent_guard() from public, anon, authenticated, service_role;

drop trigger if exists zz_scene_parent_guard on tonde.scenes;
create trigger zz_scene_parent_guard before insert or update on tonde.scenes
  for each row execute function tonde_private.lf_scene_parent_guard();


-- 11. Shared helpers (not user-facing).
create or replace function tonde_private.lf_label(total_ms bigint) returns text
language sql immutable set search_path = '' as $$
  select case when total_ms is null then null else
    (case when total_ms < 0 then '-' else '' end) ||
    case when abs(total_ms) >= 3600000
      then (abs(total_ms)/3600000)::text || ':' || lpad(((abs(total_ms)%3600000)/60000)::text,2,'0') || ':' || lpad(((abs(total_ms)%60000)/1000)::text,2,'0')
      else (abs(total_ms)/60000)::text || ':' || lpad(((abs(total_ms)%60000)/1000)::text,2,'0') end
  end;
$$;


create or replace function tonde_private.lf_scene_duration(target_workspace uuid, target_production uuid, target_scene uuid)
returns bigint language sql stable security definer set search_path = '' as $$
  select case when coalesce(agg.shots,0) > 0 and coalesce(agg.missing,0) = 0 then agg.total
    else coalesce(s.planned_duration_ms, 0) end
  from tonde.scenes s
  left join (
    select h.scene_id, count(*) as shots, count(*) filter (where h.planned_duration_ms is null) as missing,
      coalesce(sum(h.planned_duration_ms),0) as total
    from tonde.shots h where h.workspace_id = target_workspace and h.production_id = target_production
      and h.lifecycle = 'active' and h.scene_id is not null group by h.scene_id) agg on agg.scene_id = s.id
  where s.workspace_id = target_workspace and s.production_id = target_production and s.id = target_scene;
$$;


-- Calculated runtime for one structural node. Shots feed a Scene only when every Shot has a
-- duration; a Sequence/Act uses its children when it has any, otherwise its planned value.
create or replace function tonde_private.lf_scope_duration(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid) returns bigint
language plpgsql stable security definer set search_path = '' as $$
declare total bigint; children integer; planned bigint;
begin
  if target_level = 'shot' then
    select coalesce(planned_duration_ms,0) into total from tonde.shots
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
    return coalesce(total,0);
  elsif target_level = 'scene' then
    return coalesce(tonde_private.lf_scene_duration(target_workspace, target_production, target_id),0);
  elsif target_level = 'sequence' then
    select coalesce(planned_duration_ms,0) into planned from tonde.sequences
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
    select count(*), coalesce(sum(tonde_private.lf_scene_duration(target_workspace, target_production, s.id)),0)
      into children, total from tonde.scenes s
      where s.workspace_id = target_workspace and s.production_id = target_production
        and s.sequence_id = target_id and s.lifecycle = 'active';
    return case when children > 0 then total else coalesce(planned,0) end;
  elsif target_level = 'act' then
    select coalesce(planned_duration_ms,0) into planned from tonde.acts
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
    select count(*), coalesce(sum(part),0) into children, total from (
      select tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id) as part
        from tonde.sequences q where q.workspace_id = target_workspace and q.production_id = target_production
          and q.act_id = target_id and q.lifecycle = 'active'
      union all
      select tonde_private.lf_scene_duration(target_workspace, target_production, s.id)
        from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
          and s.act_id = target_id and s.sequence_id is null and s.lifecycle = 'active') as parts;
    return case when children > 0 then total else coalesce(planned,0) end;
  end if;
  -- Production: Acts, then Sequences with no Act, then Scenes with neither parent.
  select coalesce(sum(part),0) into total from (
    select tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id) as part
      from tonde.acts a where a.workspace_id = target_workspace and a.production_id = target_production
        and a.lifecycle = 'active'
    union all
    select tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id)
      from tonde.sequences q where q.workspace_id = target_workspace and q.production_id = target_production
        and q.act_id is null and q.lifecycle = 'active'
    union all
    select tonde_private.lf_scene_duration(target_workspace, target_production, s.id)
      from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
        and s.sequence_id is null and s.act_id is null and s.lifecycle = 'active') as parts;
  return coalesce(total,0);
end $$;


create or replace function tonde_private.lf_status(target_ms bigint, calculated_ms bigint) returns text
language sql immutable set search_path = '' as $$
  select case when target_ms is null then 'unresolved' when calculated_ms = target_ms then 'fits'
    when calculated_ms > target_ms then 'over' else 'under' end;
$$;


-- Planning depth is derived from real content, never declared by hand and never a percentage.
create or replace function tonde_private.lf_depth(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid) returns tonde.planning_depth
language plpgsql stable security definer set search_path = '' as $$
declare depth tonde.planning_depth := 'idea'; doc_kind text; shots integer; planned_shots integer;
  scenes integer; activity integer;
begin
  if target_level = 'shot' then
    select case when cs.status in ('setup','shooting','captured','pickup_needed') then 'in_progress'
      when p.id is not null then 'execution_planned' else 'shots_planned' end into depth
    from tonde.shots h
    left join tonde.shot_capture_state cs on cs.workspace_id = h.workspace_id and cs.shot_id = h.id
    left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.id = target_id;
    return coalesce(depth,'idea');
  end if;
  -- Story/Script documents are the canonical narrative depth signal.
  select document_type into doc_kind from tonde.creative_documents d
    where d.workspace_id = target_workspace and d.production_id = target_production
      and d.scope_object_id = target_id
      and d.document_type in ('script','treatment','story','brief','scene_description')
    order by case d.document_type when 'script' then 1 when 'scene_description' then 2 when 'treatment' then 3
      when 'story' then 4 else 5 end
    limit 1;
  depth := case doc_kind when 'script' then 'scripted' when 'scene_description' then 'scripted'
    when 'treatment' then 'story_defined' when 'story' then 'story_defined'
    when 'brief' then 'story_defined' else 'idea' end;
  if target_level = 'scene' then
    select count(*), count(*) filter (where p.id is not null) into shots, planned_shots
      from tonde.shots h left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
      where h.workspace_id = target_workspace and h.production_id = target_production
        and h.scene_id = target_id and h.lifecycle = 'active';
    select count(*) into activity from tonde.shots h
      left join tonde.shot_capture_state cs on cs.workspace_id = h.workspace_id and cs.shot_id = h.id
      where h.workspace_id = target_workspace and h.production_id = target_production and h.scene_id = target_id
        and h.lifecycle = 'active' and cs.status in ('setup','shooting','captured','pickup_needed');
    if shots > 0 then depth := greatest(depth, 'shots_planned'::tonde.planning_depth); end if;
    if shots > 0 and planned_shots = shots then depth := greatest(depth, 'execution_planned'::tonde.planning_depth); end if;
    if activity > 0 then depth := 'in_progress'; end if;
    return depth;
  end if;
  -- Act / Sequence / Production aggregate their descendants, plus the production's own documents.
  select count(*) into scenes from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.lifecycle = 'active'
    and case target_level when 'production' then true when 'act' then s.act_id = target_id
      else s.sequence_id = target_id end;
  if scenes > 0 then depth := greatest(depth, 'scenes_planned'::tonde.planning_depth); end if;
  select count(*) into shots from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.lifecycle = 'active'
    and case target_level when 'production' then true when 'act' then h.scene_id in (
        select s.id from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
          and s.act_id = target_id)
      else h.scene_id in (select s.id from tonde.scenes s where s.workspace_id = target_workspace
        and s.production_id = target_production and s.sequence_id = target_id) end;
  if shots > 0 then depth := greatest(depth, 'shots_planned'::tonde.planning_depth); end if;
  select count(*) into planned_shots from tonde.shots h join tonde.execution_plans p
    on p.workspace_id = h.workspace_id and p.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'
    and case target_level when 'production' then true when 'act' then h.scene_id in (
        select s.id from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
          and s.act_id = target_id)
      else h.scene_id in (select s.id from tonde.scenes s where s.workspace_id = target_workspace
        and s.production_id = target_production and s.sequence_id = target_id) end;
  if shots > 0 and planned_shots = shots then depth := greatest(depth, 'execution_planned'::tonde.planning_depth); end if;
  select count(*) into activity from tonde.shots h
    left join tonde.shot_capture_state cs on cs.workspace_id = h.workspace_id and cs.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'
    and cs.status in ('setup','shooting','captured','pickup_needed')
    and case target_level when 'production' then true when 'act' then h.scene_id in (
        select s.id from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
          and s.act_id = target_id)
      else h.scene_id in (select s.id from tonde.scenes s where s.workspace_id = target_workspace
        and s.production_id = target_production and s.sequence_id = target_id) end;
  if activity > 0 then depth := 'in_progress'; end if;
  if target_level <> 'production' and exists(
      select 1 from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
        and s.lifecycle = 'active'
        and case target_level when 'act' then s.act_id = target_id else s.sequence_id = target_id end)
    then depth := greatest(depth, 'outlined'::tonde.planning_depth); end if;
  return depth;
end $$;


create or replace function tonde_private.lf_scope_revision(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid) returns integer
language plpgsql stable security definer set search_path = '' as $$
declare value integer;
begin
  if target_level = 'production' then
    select revision into value from tonde.productions where workspace_id = target_workspace and id = target_id;
  elsif target_level = 'act' then
    select revision into value from tonde.acts where workspace_id = target_workspace and production_id = target_production and id = target_id;
  elsif target_level = 'sequence' then
    select revision into value from tonde.sequences where workspace_id = target_workspace and production_id = target_production and id = target_id;
  elsif target_level = 'scene' then
    select revision into value from tonde.scenes where workspace_id = target_workspace and production_id = target_production and id = target_id;
  else
    select revision into value from tonde.shots where workspace_id = target_workspace and production_id = target_production and id = target_id;
  end if;
  return value;
end $$;


-- One structural handle for the whole Production: any Act/Sequence/Scene/Shot change moves it,
-- so a stale reorder or structural write is rejected instead of silently reordered.
create or replace function tonde_private.lf_structure_revision(target_workspace uuid, target_production uuid) returns bigint
language sql stable security definer set search_path = '' as $$
  select coalesce((select revision from tonde.productions where workspace_id = target_workspace and id = target_production), 0)
    + coalesce((select sum(revision) from tonde.acts where workspace_id = target_workspace and production_id = target_production), 0)
    + coalesce((select sum(revision) from tonde.sequences where workspace_id = target_workspace and production_id = target_production), 0)
    + coalesce((select sum(revision) from tonde.scenes where workspace_id = target_workspace and production_id = target_production), 0)
    + coalesce((select sum(revision) from tonde.shots where workspace_id = target_workspace and production_id = target_production), 0);
$$;


-- Documents attached to a scope, with staleness of the stored summary. Bounded excerpt only.
create or replace function tonde_private.lf_documents(target_workspace uuid, target_production uuid, target_id uuid)
returns jsonb language sql stable security definer set search_path = '' as $$
  select coalesce(jsonb_agg(jsonb_build_object('document_id', d.id, 'document_type', d.document_type,
    'title', d.title, 'revision', d.revision, 'approval', d.approval, 'locked', d.locked_at is not null,
    'length', length(d.content)) order by d.document_type), '[]'::jsonb)
  from tonde.creative_documents d
  where d.workspace_id = target_workspace and d.production_id = target_production and d.scope_object_id = target_id;
$$;


create or replace function tonde_private.lf_summary(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid) returns jsonb
language sql stable security definer set search_path = '' as $$
  select coalesce((select jsonb_build_object('summary_id', sm.id, 'text', coalesce(sm.content->>'text',''),
      'content', sm.content, 'generated_by', sm.generated_by, 'note', sm.note,
      'source_revision', sm.source_revision, 'current_revision', tonde_private.lf_scope_revision(target_workspace, target_production, target_level, target_id),
      'stale', sm.source_revision <> coalesce(tonde_private.lf_scope_revision(target_workspace, target_production, target_level, target_id), sm.source_revision),
      'revision', sm.revision)
    from tonde.structure_summaries sm where sm.workspace_id = target_workspace
      and sm.production_id = target_production and sm.scope_object_id = target_id), 'null'::jsonb);
$$;


revoke all on function tonde_private.lf_label(bigint),
  tonde_private.lf_scene_duration(uuid,uuid,uuid),
  tonde_private.lf_scope_duration(uuid,uuid,tonde.structure_level,uuid),
  tonde_private.lf_status(bigint,bigint),
  tonde_private.lf_depth(uuid,uuid,tonde.structure_level,uuid),
  tonde_private.lf_scope_revision(uuid,uuid,tonde.structure_level,uuid),
  tonde_private.lf_structure_revision(uuid,uuid),
  tonde_private.lf_documents(uuid,uuid,uuid),
  tonde_private.lf_summary(uuid,uuid,tonde.structure_level,uuid)
  from public, anon, authenticated, service_role;

create or replace function tonde_private.lf_read_guard(target_workspace uuid) returns void
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
end $$;


-- Revision/lock guard for Acts and Sequences, matching the Scene/Shot guard from Prompt 5.
create or replace function tonde_private.lf_node_guard(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid, expected_revision integer) returns void
language plpgsql security definer set search_path = '' as $$
declare row_revision integer; row_locked timestamptz; row_lifecycle tonde.lifecycle;
begin
  if target_level = 'act' then
    select revision, locked_at, lifecycle into row_revision, row_locked, row_lifecycle from tonde.acts
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
  elsif target_level = 'sequence' then
    select revision, locked_at, lifecycle into row_revision, row_locked, row_lifecycle from tonde.sequences
      where workspace_id = target_workspace and production_id = target_production and id = target_id;
  else
    raise exception 'Unsupported structure level' using errcode = '22023';
  end if;
  if not found then raise exception 'That structure object is unavailable in this Production' using errcode = 'P0002'; end if;
  if row_lifecycle <> 'active' then raise exception 'That structure object is archived' using errcode = '23514'; end if;
  if row_locked is not null then raise exception 'That object is locked. Unlock it before editing.' using errcode = '23514'; end if;
  if expected_revision is not null and row_revision <> expected_revision then
    raise exception 'That object changed since you loaded it' using errcode = '40001';
  end if;
end $$;


create or replace function tonde_private.lf_bounded(target_limit integer, target_offset integer) returns table(out_limit integer, out_offset integer)
language sql immutable set search_path = '' as $$
  select least(greatest(coalesce(target_limit, 50), 1), 200), greatest(coalesce(target_offset, 0), 0);
$$;

revoke all on function tonde_private.lf_read_guard(uuid), tonde_private.lf_node_guard(uuid,uuid,tonde.structure_level,uuid,integer),
  tonde_private.lf_bounded(integer,integer) from public, anon, authenticated, service_role;


-- Deterministic runtime rollup with truthful conflict reporting. Planned targets are never
-- overwritten by calculated child totals: both are reported, with the real discrepancy.
create or replace function tonde_private.lf_production_timing(target_workspace uuid, target_production uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare target_ms bigint; calculated bigint; acts jsonb; conflicts jsonb; overall text;
  counts jsonb;
begin
  select planned_duration_ms into target_ms from tonde.productions
    where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  calculated := tonde_private.lf_scope_duration(target_workspace, target_production, 'production', target_production);
  select coalesce(jsonb_agg(jsonb_build_object(
      'act_id', a.id, 'title', a.title, 'order', a.sort_order,
      'target_ms', a.planned_duration_ms,
      'calculated_ms', tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id),
      'delta_ms', case when a.planned_duration_ms is null then null
        else tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id) - a.planned_duration_ms end,
      'status', tonde_private.lf_status(a.planned_duration_ms, tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id)),
      'sequences', (select count(*) from tonde.sequences q where q.workspace_id = target_workspace
        and q.production_id = target_production and q.act_id = a.id and q.lifecycle = 'active'),
      'scenes', (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
        and s.production_id = target_production and s.act_id = a.id and s.lifecycle = 'active'))
    order by a.sort_order, a.id), '[]'::jsonb) into acts
  from tonde.acts a
  where a.workspace_id = target_workspace and a.production_id = target_production and a.lifecycle = 'active';
  select coalesce(jsonb_agg(jsonb_build_object('level', c.level, 'id', c.id, 'title', c.title,
      'target_ms', c.target_ms, 'calculated_ms', c.calculated_ms,
      'over_by_ms', case when c.target_ms is null then null else c.calculated_ms - c.target_ms end,
      'over_by_label', case when c.target_ms is null then null
        else tonde_private.lf_label(c.calculated_ms - c.target_ms) end,
      'status', tonde_private.lf_status(c.target_ms, c.calculated_ms), 'reason', c.reason)
    order by c.level, c.title), '[]'::jsonb) into conflicts
  from (
    select 'act'::text as level, a.id, a.title, a.planned_duration_ms as target_ms,
      tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id) as calculated_ms,
      'Act target and current child total differ.'::text as reason
    from tonde.acts a where a.workspace_id = target_workspace and a.production_id = target_production
      and a.lifecycle = 'active' and a.planned_duration_ms is not null
      and tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id) <> a.planned_duration_ms
    union all
    select 'sequence', q.id, q.title, q.planned_duration_ms,
      tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id),
      'Sequence target and current child total differ.'
    from tonde.sequences q where q.workspace_id = target_workspace and q.production_id = target_production
      and q.lifecycle = 'active' and q.planned_duration_ms is not null
      and tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id) <> q.planned_duration_ms
    limit 50) c;
  select jsonb_build_object(
    'acts', (select count(*) from tonde.acts a where a.workspace_id = target_workspace
      and a.production_id = target_production and a.lifecycle = 'active'),
    'sequences', (select count(*) from tonde.sequences q where q.workspace_id = target_workspace
      and q.production_id = target_production and q.lifecycle = 'active'),
    'scenes', (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.lifecycle = 'active'),
    'shots', (select count(*) from tonde.shots h where h.workspace_id = target_workspace
      and h.production_id = target_production and h.lifecycle = 'active'),
    'scenes_incomplete_timing', (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.lifecycle = 'active' and exists(
        select 1 from tonde.shots h where h.workspace_id = target_workspace and h.production_id = target_production
          and h.scene_id = s.id and h.lifecycle = 'active' and h.planned_duration_ms is null)),
    'scenes_without_shots', (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.lifecycle = 'active' and not exists(
        select 1 from tonde.shots h where h.workspace_id = target_workspace and h.production_id = target_production
          and h.scene_id = s.id and h.lifecycle = 'active'))) into counts;
  overall := tonde_private.lf_status(target_ms, calculated);
  return jsonb_build_object('production', jsonb_build_object(
      'target_ms', target_ms, 'calculated_ms', calculated,
      'delta_ms', case when target_ms is null then null else calculated - target_ms end,
      'target_label', tonde_private.lf_label(target_ms), 'calculated_label', tonde_private.lf_label(calculated),
      'delta_label', case when target_ms is null then null else tonde_private.lf_label(calculated - target_ms) end,
      'status', overall),
    'acts', acts, 'conflicts', conflicts, 'counts', counts, 'status', overall,
    'note', case when target_ms is null then 'This Production has no runtime target yet, so total runtime is reported without a fit verdict.'
      else 'Planned target and calculated child runtime are reported separately; nothing was overwritten.' end);
end $$;

revoke all on function tonde_private.lf_production_timing(uuid,uuid) from public, anon, authenticated, service_role;


-- 12. Hierarchical reads. Children of one scope only: a 120-minute Production is never
-- rendered as one giant card graph, and every level is paginated and bounded.
create or replace function tonde.long_form_structure(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level default 'production', target_id uuid default null,
  target_limit integer default 50, target_offset integer default 0, expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; revision integer; scope_title text;
  breadcrumb jsonb; scope_id uuid; scope jsonb;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  select b.out_limit, b.out_offset into lim, off from tonde_private.lf_bounded(target_limit, target_offset) b;
  select p.revision, p.title into revision, scope_title from tonde.productions p
    where p.workspace_id = target_workspace and p.id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  if target_level = 'production' then
    scope_id := target_production;
    select jsonb_agg(item order by ord, ord_id), count(*) into items, total from (
      select a.sort_order as ord, a.id as ord_id, jsonb_build_object(
        'id', a.id, 'level', 'act', 'title', a.title, 'display', 'Act ' || ranked.position,
        'display_index', ranked.position, 'order', a.sort_order, 'purpose', a.purpose,
        'narrative_goal', a.narrative_goal, 'planned_duration_ms', a.planned_duration_ms,
        'calculated_duration_ms', tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id),
        'label', tonde_private.lf_label(tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id)),
        'delta_ms', case when a.planned_duration_ms is null then null
          else tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id) - a.planned_duration_ms end,
        'status', tonde_private.lf_status(a.planned_duration_ms, tonde_private.lf_scope_duration(target_workspace, target_production, 'act', a.id)),
        'depth', tonde_private.lf_depth(target_workspace, target_production, 'act', a.id),
        'approval', a.approval, 'locked', a.locked_at is not null, 'revision', a.revision,
        'summary', tonde_private.lf_summary(target_workspace, target_production, 'act', a.id),
        'documents', tonde_private.lf_documents(target_workspace, target_production, a.id),
        'child_counts', jsonb_build_object(
          'sequences', (select count(*) from tonde.sequences q where q.workspace_id = target_workspace
            and q.production_id = target_production and q.act_id = a.id and q.lifecycle = 'active'),
          'scenes', (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
            and s.production_id = target_production and s.act_id = a.id and s.lifecycle = 'active'))
      ) as item
      from tonde.acts a
      join (select id, row_number() over (order by sort_order, id) as position from tonde.acts
        where workspace_id = target_workspace and production_id = target_production and lifecycle = 'active') ranked
        on ranked.id = a.id
      where a.workspace_id = target_workspace and a.production_id = target_production and a.lifecycle = 'active'
      order by a.sort_order, a.id limit lim offset off) t;
    select count(*) into total from tonde.acts a where a.workspace_id = target_workspace
      and a.production_id = target_production and a.lifecycle = 'active';
    scope := jsonb_build_object('level', 'production', 'id', target_production, 'title', scope_title,
      'display', 'Production', 'orphan_sequences', (select count(*) from tonde.sequences q where q.workspace_id = target_workspace
        and q.production_id = target_production and q.act_id is null and q.lifecycle = 'active'),
      'orphan_scenes', (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
        and s.production_id = target_production and s.sequence_id is null and s.act_id is null and s.lifecycle = 'active'),
      'depth', tonde_private.lf_depth(target_workspace, target_production, 'production', target_production),
      'summary', tonde_private.lf_summary(target_workspace, target_production, 'production', target_production));
    breadcrumb := jsonb_build_array(jsonb_build_object('level','production','id',target_production,'title',scope_title));
  elsif target_level = 'act' then
    scope_id := target_id;
    select a.title into scope_title from tonde.acts a where a.workspace_id = target_workspace
      and a.production_id = target_production and a.id = target_id;
    if not found then raise exception 'Act unavailable' using errcode = 'P0002'; end if;
    select jsonb_agg(item order by ord, ord_id), count(*) into items, total from (
      select part.sort_order as ord, part.id as ord_id, part.item from (
        select q.sort_order, q.id, jsonb_build_object(
          'id', q.id, 'level', 'sequence', 'title', q.title, 'kind', q.kind::text,
          'display', 'Sequence ' || ranked.position, 'display_index', ranked.position, 'order', q.sort_order,
          'purpose', q.purpose, 'planned_duration_ms', q.planned_duration_ms,
          'calculated_duration_ms', tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id),
          'label', tonde_private.lf_label(tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id)),
          'delta_ms', case when q.planned_duration_ms is null then null
            else tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id) - q.planned_duration_ms end,
          'status', tonde_private.lf_status(q.planned_duration_ms, tonde_private.lf_scope_duration(target_workspace, target_production, 'sequence', q.id)),
          'depth', tonde_private.lf_depth(target_workspace, target_production, 'sequence', q.id),
          'approval', q.approval, 'locked', q.locked_at is not null, 'revision', q.revision,
          'summary', tonde_private.lf_summary(target_workspace, target_production, 'sequence', q.id),
          'documents', tonde_private.lf_documents(target_workspace, target_production, q.id),
          'child_counts', jsonb_build_object('scenes', (select count(*) from tonde.scenes s
            where s.workspace_id = target_workspace and s.production_id = target_production
              and s.sequence_id = q.id and s.lifecycle = 'active'))) as item
        from tonde.sequences q
        join (select id, row_number() over (order by sort_order, id) as position from tonde.sequences
          where workspace_id = target_workspace and production_id = target_production and act_id = target_id
            and lifecycle = 'active') ranked on ranked.id = q.id
        where q.workspace_id = target_workspace and q.production_id = target_production and q.act_id = target_id
          and q.lifecycle = 'active'
        union all
        select s.sort_order, s.id, jsonb_build_object(
          'id', s.id, 'level', 'scene', 'title', s.title, 'display', 'Scene ' || ranked.position,
          'display_index', ranked.position, 'order', s.sort_order, 'purpose', s.purpose,
          'planned_duration_ms', s.planned_duration_ms,
          'calculated_duration_ms', tonde_private.lf_scene_duration(target_workspace, target_production, s.id),
          'label', tonde_private.lf_label(tonde_private.lf_scene_duration(target_workspace, target_production, s.id)),
          'delta_ms', case when s.planned_duration_ms is null then null
            else tonde_private.lf_scene_duration(target_workspace, target_production, s.id) - s.planned_duration_ms end,
          'status', tonde_private.lf_status(s.planned_duration_ms, tonde_private.lf_scene_duration(target_workspace, target_production, s.id)),
          'depth', tonde_private.lf_depth(target_workspace, target_production, 'scene', s.id),
          'approval', s.approval, 'locked', s.locked_at is not null, 'revision', s.revision,
          'summary', tonde_private.lf_summary(target_workspace, target_production, 'scene', s.id),
          'documents', tonde_private.lf_documents(target_workspace, target_production, s.id),
          'child_counts', jsonb_build_object('shots', (select count(*) from tonde.shots h
            where h.workspace_id = target_workspace and h.production_id = target_production
              and h.scene_id = s.id and h.lifecycle = 'active'))) as item
        from tonde.scenes s
        join (select id, row_number() over (order by sort_order, id) as position from tonde.scenes
          where workspace_id = target_workspace and production_id = target_production and act_id = target_id
            and sequence_id is null and lifecycle = 'active') ranked on ranked.id = s.id
        where s.workspace_id = target_workspace and s.production_id = target_production and s.act_id = target_id
          and s.sequence_id is null and s.lifecycle = 'active') part
      order by part.sort_order, part.id limit lim offset off) t;
    select (select count(*) from tonde.sequences q where q.workspace_id = target_workspace
        and q.production_id = target_production and q.act_id = target_id and q.lifecycle = 'active')
      + (select count(*) from tonde.scenes s where s.workspace_id = target_workspace
        and s.production_id = target_production and s.act_id = target_id and s.sequence_id is null
        and s.lifecycle = 'active') into total;
    scope := jsonb_build_object('level', 'act', 'id', target_id, 'title', scope_title, 'display', 'Act',
      'depth', tonde_private.lf_depth(target_workspace, target_production, 'act', target_id),
      'summary', tonde_private.lf_summary(target_workspace, target_production, 'act', target_id));
    breadcrumb := jsonb_build_array(
      jsonb_build_object('level','production','id',target_production,'title',
        (select title from tonde.productions where id = target_production)),
      jsonb_build_object('level','act','id',target_id,'title',scope_title));
  elsif target_level = 'sequence' then
    scope_id := target_id;
    select q.title, q.act_id into scope_title, scope_id from tonde.sequences q where q.workspace_id = target_workspace
      and q.production_id = target_production and q.id = target_id;
    if not found then raise exception 'Sequence unavailable' using errcode = 'P0002'; end if;
    select jsonb_agg(item order by ord, ord_id), count(*) into items, total from (
      select s.sort_order as ord, s.id as ord_id, jsonb_build_object(
        'id', s.id, 'level', 'scene', 'title', s.title, 'display', 'Scene ' || ranked.position,
        'display_index', ranked.position, 'order', s.sort_order, 'purpose', s.purpose,
        'planned_duration_ms', s.planned_duration_ms,
        'calculated_duration_ms', tonde_private.lf_scene_duration(target_workspace, target_production, s.id),
        'label', tonde_private.lf_label(tonde_private.lf_scene_duration(target_workspace, target_production, s.id)),
        'delta_ms', case when s.planned_duration_ms is null then null
          else tonde_private.lf_scene_duration(target_workspace, target_production, s.id) - s.planned_duration_ms end,
        'status', tonde_private.lf_status(s.planned_duration_ms, tonde_private.lf_scene_duration(target_workspace, target_production, s.id)),
        'depth', tonde_private.lf_depth(target_workspace, target_production, 'scene', s.id),
        'approval', s.approval, 'locked', s.locked_at is not null, 'revision', s.revision,
        'summary', tonde_private.lf_summary(target_workspace, target_production, 'scene', s.id),
        'documents', tonde_private.lf_documents(target_workspace, target_production, s.id),
        'child_counts', jsonb_build_object('shots', (select count(*) from tonde.shots h
          where h.workspace_id = target_workspace and h.production_id = target_production
            and h.scene_id = s.id and h.lifecycle = 'active'))) as item
      from tonde.scenes s
      join (select id, row_number() over (order by sort_order, id) as position from tonde.scenes
        where workspace_id = target_workspace and production_id = target_production and sequence_id = target_id
          and lifecycle = 'active') ranked on ranked.id = s.id
      where s.workspace_id = target_workspace and s.production_id = target_production and s.sequence_id = target_id
        and s.lifecycle = 'active'
      order by s.sort_order, s.id limit lim offset off) t;
    select count(*) into total from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.sequence_id = target_id and s.lifecycle = 'active';
    scope := jsonb_build_object('level', 'sequence', 'id', target_id, 'title', scope_title, 'display', 'Sequence',
      'depth', tonde_private.lf_depth(target_workspace, target_production, 'sequence', target_id),
      'summary', tonde_private.lf_summary(target_workspace, target_production, 'sequence', target_id));
    breadcrumb := jsonb_build_array(
      jsonb_build_object('level','production','id',target_production,'title',
        (select title from tonde.productions where id = target_production)),
      jsonb_build_object('level','act','id',scope_id,'title',(select title from tonde.acts where id = scope_id)),
      jsonb_build_object('level','sequence','id',target_id,'title',scope_title));
  else
    select s.title into scope_title from tonde.scenes s
      where s.workspace_id = target_workspace and s.production_id = target_production and s.id = target_id;
    if not found then raise exception 'Scene unavailable' using errcode = 'P0002'; end if;
    select jsonb_agg(item order by ord, ord_id), count(*) into items, total from (
      select h.sort_order as ord, h.id as ord_id, jsonb_build_object(
        'id', h.id, 'level', 'shot', 'title', h.title, 'display', 'Shot ' || ranked.position,
        'display_index', ranked.position, 'order', h.sort_order, 'purpose', h.purpose,
        'planned_duration_ms', h.planned_duration_ms, 'calculated_duration_ms', coalesce(h.planned_duration_ms,0),
        'label', tonde_private.lf_label(coalesce(h.planned_duration_ms,0)),
        'delta_ms', null, 'status', case when h.planned_duration_ms is null then 'unresolved' else 'fits' end,
        'depth', tonde_private.lf_depth(target_workspace, target_production, 'shot', h.id),
        'execution_method', h.execution_method, 'approval', h.approval, 'locked', h.locked_at is not null,
        'revision', h.revision, 'summary', 'null'::jsonb, 'documents', tonde_private.lf_documents(target_workspace, target_production, h.id),
        'child_counts', jsonb_build_object('takes', (select count(*) from tonde.shot_takes t
          where t.workspace_id = target_workspace and t.shot_id = h.id),
          'attempts', (select count(*) from tonde.ai_generation_attempts at where at.workspace_id = target_workspace
            and at.shot_id = h.id),
          'results', (select count(*) from tonde.results r where r.workspace_id = target_workspace and r.shot_id = h.id))) as item
      from tonde.shots h
      join (select id, row_number() over (order by sort_order, id) as position from tonde.shots
        where workspace_id = target_workspace and production_id = target_production and scene_id = target_id
          and lifecycle = 'active') ranked on ranked.id = h.id
      where h.workspace_id = target_workspace and h.production_id = target_production and h.scene_id = target_id
        and h.lifecycle = 'active'
      order by h.sort_order, h.id limit lim offset off) t;
    select count(*) into total from tonde.shots h where h.workspace_id = target_workspace
      and h.production_id = target_production and h.scene_id = target_id and h.lifecycle = 'active';
    scope := jsonb_build_object('level', 'scene', 'id', target_id, 'title', scope_title, 'display', 'Scene',
      'depth', tonde_private.lf_depth(target_workspace, target_production, 'scene', target_id),
      'summary', tonde_private.lf_summary(target_workspace, target_production, 'scene', target_id),
      'opening_state', (select opening_state from tonde.scenes where id = target_id),
      'ending_state', (select ending_state from tonde.scenes where id = target_id));
    breadcrumb := jsonb_build_array(
      jsonb_build_object('level','production','id',target_production,'title',
        (select title from tonde.productions where id = target_production)),
      jsonb_build_object('level','act','id',(select act_id from tonde.scenes where id = target_id),
        'title',(select a.title from tonde.acts a where a.id = (select act_id from tonde.scenes where id = target_id))),
      jsonb_build_object('level','sequence','id',(select sequence_id from tonde.scenes where id = target_id),
        'title',(select q.title from tonde.sequences q where q.id = (select sequence_id from tonde.scenes where id = target_id))),
      jsonb_build_object('level','scene','id',target_id,'title',scope_title));
  end if;
  return jsonb_build_object('production_id', target_production, 'production_revision', revision,
    'structure_revision', tonde_private.lf_structure_revision(target_workspace, target_production),
    'level', target_level, 'scope', scope, 'breadcrumb', breadcrumb,
    'items', coalesce(items, '[]'::jsonb), 'total', coalesce(total, 0),
    'limit', lim, 'offset', off,
    'truncated', coalesce(total, 0) > off + jsonb_array_length(coalesce(items, '[]'::jsonb)),
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;

create or replace function tonde_private.lf_ms(source jsonb, target_key text) returns bigint
language plpgsql immutable set search_path = '' as $$
declare value bigint;
begin
  if not source ? target_key or source->>target_key is null or source->>target_key = '' then return null; end if;
  if source->>target_key !~ '^[0-9]{1,16}$' then
    raise exception 'Durations must be whole milliseconds' using errcode = '22023';
  end if;
  value := (source->>target_key)::bigint;
  if value > 9007199254740991 then raise exception 'Duration exceeds the safe integer range' using errcode = '22023'; end if;
  return value;
end $$;

revoke all on function tonde_private.lf_ms(jsonb,text) from public, anon, authenticated, service_role;


-- 13. Public reads.
create or replace function tonde.long_form_timing(target_workspace uuid, target_production uuid, expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare revision integer;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  select p.revision into revision from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  return tonde_private.lf_production_timing(target_workspace, target_production)
    || jsonb_build_object('production_revision', revision,
      'structure_revision', tonde_private.lf_structure_revision(target_workspace, target_production));
end $$;


-- Structured search: relational filters first, actual object references returned, never prose.
create or replace function tonde.long_form_search(target_workspace uuid, target_production uuid, search_query text,
  filters jsonb default '{}'::jsonb, target_limit integer default 40, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare term text; lim integer; off integer; items jsonb; total integer; levels text[];
  character_filter uuid; environment_filter uuid; method_filter text; approval_filter text;
  text_only boolean; bound_only boolean;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  term := lower(btrim(coalesce(search_query, '')));
  if length(term) < 2 then raise exception 'Search needs at least two characters' using errcode = '22023'; end if;
  if not exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production) then
    raise exception 'Production unavailable' using errcode = 'P0002';
  end if;
  select b.out_limit, b.out_offset into lim, off from tonde_private.lf_bounded(target_limit, target_offset) b;
  levels := case when filters ? 'levels'
    then coalesce(array(select jsonb_array_elements_text(filters->'levels')), '{}'::text[]) else null end;
  character_filter := nullif(coalesce(filters->>'character_asset_id',''),'')::uuid;
  environment_filter := nullif(coalesce(filters->>'environment_asset_id',''),'')::uuid;
  method_filter := nullif(coalesce(filters->>'execution_method',''),'');
  approval_filter := nullif(coalesce(filters->>'approval',''),'');
  bound_only := character_filter is not null or environment_filter is not null or method_filter is not null;
  with matches as (
    select 'act'::text as level, a.id, a.title, a.purpose as snippet, 'act purpose'::text as match_field,
      null::uuid as scene_id, null::uuid as shot_id, a.approval, a.locked_at is not null as locked, a.sort_order as ord
    from tonde.acts a where a.workspace_id = target_workspace and a.production_id = target_production
      and a.lifecycle = 'active' and (position(term in lower(a.title || ' ' || a.purpose || ' ' || a.narrative_goal)) > 0)
    union all
    select 'sequence', q.id, q.title, q.purpose, 'sequence purpose', null, null, q.approval, q.locked_at is not null, q.sort_order
    from tonde.sequences q where q.workspace_id = target_workspace and q.production_id = target_production
      and q.lifecycle = 'active' and position(term in lower(q.title || ' ' || q.purpose)) > 0
    union all
    select 'scene', s.id, s.title, s.description, 'scene', s.id, null, s.approval, s.locked_at is not null, s.sort_order
    from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
      and s.lifecycle = 'active' and position(term in lower(s.title || ' ' || s.purpose || ' ' || s.description || ' ' || s.story_beat)) > 0
    union all
    select 'shot', h.id, h.title, h.description, 'shot', h.scene_id, h.id, h.approval, h.locked_at is not null, h.sort_order
    from tonde.shots h where h.workspace_id = target_workspace and h.production_id = target_production
      and h.lifecycle = 'active' and position(term in lower(h.title || ' ' || h.description || ' ' || h.action || ' ' || h.subject || ' ' || h.purpose)) > 0
    union all
    select 'document', d.id, d.title, left(d.content, 200), 'document', null, null, d.approval, d.locked_at is not null, 0
    from tonde.creative_documents d where d.workspace_id = target_workspace and d.production_id = target_production
      and position(term in lower(d.title || ' ' || left(d.content, 200000))) > 0),
  resolved as (
    select m.*, case when m.level = 'shot' then tonde_private.lf_depth(target_workspace, target_production, 'shot', m.id)
      when m.level = 'scene' then tonde_private.lf_depth(target_workspace, target_production, 'scene', m.id)
      when m.level = 'sequence' then tonde_private.lf_depth(target_workspace, target_production, 'sequence', m.id)
      when m.level = 'act' then tonde_private.lf_depth(target_workspace, target_production, 'act', m.id)
      else null end as depth,
      case when m.scene_id is not null then (select s.title from tonde.scenes s where s.id = m.scene_id) end as scene_title,
      case when m.level = 'shot' then (select count(*) from tonde.shot_takes t where t.workspace_id = target_workspace and t.shot_id = m.id) end as take_count,
      case when m.level = 'shot' then (select count(*) from tonde.results r where r.workspace_id = target_workspace and r.shot_id = m.id) end as result_count,
      case when m.level = 'shot' then (select count(*) from tonde.ai_generation_attempts at where at.workspace_id = target_workspace and at.shot_id = m.id) end as attempt_count,
      case when m.level = 'shot' then (select h.execution_method::text from tonde.shots h where h.id = m.id) end as execution_method
    from matches m),
  filtered as (
    select r.* from resolved r
    where (levels is null or r.level = any(levels))
      and (approval_filter is null or r.approval::text = approval_filter)
      and (method_filter is null or r.execution_method = method_filter)
      and (character_filter is null or (r.level in ('scene','shot') and r.scene_id is not null
        and exists(select 1 from tonde.scene_participants sp where sp.scene_id = r.scene_id and sp.asset_id = character_filter)))
      and (environment_filter is null or (r.level = 'scene'
        and exists(select 1 from tonde.scenes s where s.id = r.id and s.environment_asset_id = environment_filter))))
  select coalesce(jsonb_agg(jsonb_build_object('level', r.level, 'id', r.id, 'title', r.title,
      'snippet', left(coalesce(r.snippet,''), 240), 'match_field', r.match_field,
      'scene_id', r.scene_id, 'shot_id', r.shot_id, 'scene_title', r.scene_title,
      'approval', r.approval, 'locked', r.locked, 'depth', r.depth, 'execution_method', r.execution_method,
      'takes', r.take_count, 'results', r.result_count, 'attempts', r.attempt_count)
      order by r.level, r.ord, r.id), '[]'::jsonb), count(*) into items, total
  from filtered r;
  total := coalesce(total, 0);
  return jsonb_build_object('query', btrim(search_query), 'items', items, 'total', total,
    'limit', lim, 'offset', off, 'truncated', total > off + jsonb_array_length(items),
    'binding_filter', case when bound_only then jsonb_build_object('character_asset_id', character_filter,
      'environment_asset_id', environment_filter, 'execution_method', method_filter, 'scoped_to', 'scenes/shots')
      else 'null'::jsonb end,
    'filters', coalesce(filters, '{}'::jsonb),
    'note', 'Structured relational matches on the canonical Production, never a semantic guess.');
end $$;


-- 14. Summaries are derived, versioned and explicitly stale rather than silently current.
create or replace function tonde.save_structure_summary(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid, content jsonb, expected_production_revision integer,
  note text default '', generated_by text default 'creator')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare revision integer; scope_revision integer; saved tonde.structure_summaries;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if target_level = 'shot' then raise exception 'Summaries cover Production, Act, Sequence and Scene' using errcode = '22023'; end if;
  if jsonb_typeof(content) <> 'object' then raise exception 'Invalid summary payload' using errcode = '22023'; end if;
  if length(coalesce(content->>'text','')) > 4000 then
    raise exception 'A summary text is limited to 4000 characters' using errcode = '22023';
  end if;
  if generated_by not in ('creator','tonde','system') then raise exception 'Unsupported summary author' using errcode = '22023'; end if;
  if not exists(select 1 from tonde.objects o where o.workspace_id = target_workspace and o.id = target_id
    and o.kind = target_level::text and o.production_id = target_production) then
    raise exception 'That scope is unavailable in this Production' using errcode = 'P0002';
  end if;
  revision := tonde_private.lf_scope_revision(target_workspace, target_production, target_level, target_id);
  scope_revision := revision;
  insert into tonde.structure_summaries(workspace_id, production_id, scope_object_id, scope_level,
    source_revision, content, generated_by, note)
  values (target_workspace, target_production, target_id, target_level, scope_revision, content, generated_by,
    left(coalesce(note,''), 400))
  on conflict (workspace_id, scope_object_id) do update
    set source_revision = excluded.source_revision, content = excluded.content,
      generated_by = excluded.generated_by, note = excluded.note
  returning * into saved;
  return jsonb_build_object('summary_id', saved.id, 'scope_level', saved.scope_level, 'scope_object_id', saved.scope_object_id,
    'source_revision', saved.source_revision, 'revision', saved.revision, 'stale', false,
    'note', 'Derived summary stored against the revision it was derived from.');
end $$;


create or replace function tonde.long_form_summaries(target_workspace uuid, target_production uuid,
  target_limit integer default 100, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  select b.out_limit, b.out_offset into lim, off from tonde_private.lf_bounded(target_limit, target_offset) b;
  select coalesce(jsonb_agg(jsonb_build_object('summary_id', sm.id, 'scope_level', sm.scope_level,
      'scope_object_id', sm.scope_object_id, 'generated_by', sm.generated_by, 'note', sm.note,
      'source_revision', sm.source_revision, 'current_revision',
        tonde_private.lf_scope_revision(target_workspace, target_production, sm.scope_level, sm.scope_object_id),
      'stale', sm.source_revision <> coalesce(tonde_private.lf_scope_revision(target_workspace, target_production, sm.scope_level, sm.scope_object_id), sm.source_revision),
      'text', left(coalesce(sm.content->>'text',''), 400)) order by sm.scope_level, sm.id), '[]'::jsonb), count(*)
    into items, total
  from tonde.structure_summaries sm where sm.workspace_id = target_workspace and sm.production_id = target_production;
  return jsonb_build_object('items', items, 'total', coalesce(total,0), 'limit', lim, 'offset', off,
    'truncated', coalesce(total,0) > off + jsonb_array_length(items));
end $$;


-- Script navigation by scope, with measured length and a bounded excerpt. One giant Script
-- text area is never required, and no prose is parsed to invent structure.
create or replace function tonde.long_form_script_index(target_workspace uuid, target_production uuid,
  target_limit integer default 50, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  select b.out_limit, b.out_offset into lim, off from tonde_private.lf_bounded(target_limit, target_offset) b;
  select coalesce(jsonb_agg(jsonb_build_object('document_id', d.id, 'document_type', d.document_type,
      'title', d.title, 'scope_object_id', d.scope_object_id, 'scope_level', o.kind,
      'revision', d.revision, 'approval', d.approval, 'locked', d.locked_at is not null,
      'characters', length(d.content), 'lines', (select count(*) from tonde.dialogue_lines l
        where l.workspace_id = target_workspace and l.document_id = d.id),
      'line_duration_ms', (select coalesce(sum(l.duration_ms),0) from tonde.dialogue_lines l
        where l.workspace_id = target_workspace and l.document_id = d.id),
      'excerpt', left(d.content, 400)) order by d.document_type, d.title), '[]'::jsonb), count(*)
    into items, total
  from tonde.creative_documents d join tonde.objects o on o.workspace_id = d.workspace_id and o.id = d.scope_object_id
  where d.workspace_id = target_workspace and d.production_id = target_production;
  return jsonb_build_object('items', items, 'total', coalesce(total,0), 'limit', lim, 'offset', off,
    'truncated', coalesce(total,0) > off + jsonb_array_length(items),
    'note', 'Dialogue stays first-class: line durations are measured, never inferred from paragraphs.');
end $$;


-- Bounded hierarchical context for AI/ Director reasoning. Never the whole Production.
create or replace function tonde.long_form_context(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid, budget_chars integer default 4000)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare budget integer; scope jsonb; path jsonb; siblings jsonb; assets jsonb; documents jsonb;
  timing jsonb; character_names text; world_name uuid; dialogue jsonb; production_title text;
  parent_act uuid; parent_sequence uuid; parent_scene uuid; shot_ref uuid; scope_title text;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  budget := least(greatest(coalesce(budget_chars, 4000), 400), 20000);
  select p.title into production_title from tonde.productions p
    where p.workspace_id = target_workspace and p.id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  -- Resolve the scope's place in the hierarchy once, then build the breadcrumb from it.
  if target_level = 'production' then
    scope_title := production_title;
  elsif target_level = 'act' then
    select a.title into scope_title from tonde.acts a where a.workspace_id = target_workspace and a.id = target_id;
    parent_act := target_id;
  elsif target_level = 'sequence' then
    select q.title, q.act_id into scope_title, parent_act from tonde.sequences q
      where q.workspace_id = target_workspace and q.id = target_id;
    parent_sequence := target_id;
  elsif target_level = 'scene' then
    select s.title, s.act_id, s.sequence_id into scope_title, parent_act, parent_sequence from tonde.scenes s
      where s.workspace_id = target_workspace and s.id = target_id;
    parent_scene := target_id;
  else
    select h.title, s.act_id, s.sequence_id, s.id into scope_title, parent_act, parent_sequence, parent_scene
      from tonde.shots h join tonde.scenes s on s.workspace_id = h.workspace_id and s.id = h.scene_id
      where h.workspace_id = target_workspace and h.id = target_id;
    shot_ref := target_id;
  end if;
  if scope_title is null and target_level <> 'production' then
    raise exception 'That scope is unavailable in this Production' using errcode = 'P0002';
  end if;
  scope := jsonb_build_object('level', target_level::text, 'id', target_id, 'title', scope_title);
  path := (case when target_level <> 'production' then jsonb_build_array(jsonb_build_object(
      'level','production','id',target_production,'title',production_title)) else '[]'::jsonb end)
    || (case when parent_act is not null then jsonb_build_array(jsonb_build_object('level','act','id',parent_act,
      'title',(select a.title from tonde.acts a where a.id = parent_act))) else '[]'::jsonb end)
    || (case when parent_sequence is not null then jsonb_build_array(jsonb_build_object('level','sequence','id',parent_sequence,
      'title',(select q.title from tonde.sequences q where q.id = parent_sequence))) else '[]'::jsonb end)
    || (case when parent_scene is not null then jsonb_build_array(jsonb_build_object('level','scene','id',parent_scene,
      'title',(select s.title from tonde.scenes s where s.id = parent_scene))) else '[]'::jsonb end)
    || (case when shot_ref is not null then jsonb_build_array(jsonb_build_object('level','shot','id',shot_ref,
      'title',(select h.title from tonde.shots h where h.id = shot_ref))) else '[]'::jsonb end);
  -- Siblings: titles only, bounded, so a 100-Scene Act never enters the model call wholesale.
  siblings := case target_level
    when 'production' then (select coalesce(jsonb_agg(jsonb_build_object('level','act','id',a.id,'title',a.title)),'[]'::jsonb)
      from (select id, title from tonde.acts where workspace_id = target_workspace and production_id = target_production
        and lifecycle = 'active' order by sort_order limit 12) a)
    when 'act' then (select coalesce(jsonb_agg(jsonb_build_object('level','sequence','id',q.id,'title',q.title)),'[]'::jsonb)
      from (select id, title from tonde.sequences where workspace_id = target_workspace and production_id = target_production
        and act_id = target_id and lifecycle = 'active' order by sort_order limit 12) q)
    when 'sequence' then (select coalesce(jsonb_agg(jsonb_build_object('level','scene','id',s.id,'title',s.title)),'[]'::jsonb)
      from (select id, title from tonde.scenes where workspace_id = target_workspace and production_id = target_production
        and sequence_id = target_id and lifecycle = 'active' order by sort_order limit 12) s)
    else (select coalesce(jsonb_agg(jsonb_build_object('level','shot','id',h.id,'title',h.title)),'[]'::jsonb)
      from (select id, title from tonde.shots where workspace_id = target_workspace and production_id = target_production
        and scene_id = (select scene_id from tonde.shots where id = target_id) and lifecycle = 'active'
        order by sort_order limit 12) h) end;
  select coalesce(jsonb_agg(jsonb_build_object('role', b.binding_role, 'asset_id', b.asset_id,
      'name', a.name, 'asset_type', a.asset_type, 'inheritance', b.inheritance)), '[]'::jsonb)
    into assets
  from tonde.scope_bindings b join tonde.assets a on a.workspace_id = b.workspace_id and a.id = b.asset_id
  where b.workspace_id = target_workspace and b.production_id = target_production
    and b.scope_object_id in (target_id, target_production) limit 12;
  select coalesce(jsonb_agg(jsonb_build_object('document_type', d.document_type, 'title', d.title,
      'revision', d.revision, 'approval', d.approval, 'locked', d.locked_at is not null,
      'excerpt', left(d.content, greatest(budget / 8, 200)))), '[]'::jsonb) into documents
  from tonde.creative_documents d where d.workspace_id = target_workspace and d.production_id = target_production
    and d.scope_object_id in (target_id, target_production)
    and d.document_type in ('brief','story','treatment','script','scene_description','series_bible') limit 6;
  select coalesce(jsonb_agg(jsonb_build_object('speaker_asset_id', l.speaker_asset_id, 'line_type', l.line_type,
      'content', left(l.content, 200), 'start_ms', l.start_ms, 'duration_ms', l.duration_ms)), '[]'::jsonb)
    into dialogue
  from (select * from tonde.dialogue_lines l where l.workspace_id = target_workspace and l.production_id = target_production
    and l.scene_id = parent_scene order by l.start_ms limit 20) l;
  select string_agg(distinct a.name, ', ') into character_names from tonde.scene_participants sp
    join tonde.assets a on a.workspace_id = sp.workspace_id and a.id = sp.asset_id
  where sp.workspace_id = target_workspace and sp.scene_id = parent_scene;
  select s.environment_asset_id into world_name from tonde.scenes s
    where s.workspace_id = target_workspace and s.id = parent_scene;
  timing := tonde_private.lf_production_timing(target_workspace, target_production);
  return jsonb_build_object('scope', scope, 'path', path, 'siblings', siblings, 'assets', assets,
    'documents', documents, 'dialogue', dialogue, 'characters', coalesce(character_names, ''),
    'environment', (select jsonb_build_object('asset_id', w.id, 'name', w.name) from tonde.assets w where w.id = world_name),
    'timing', jsonb_build_object('production', timing->'production', 'counts', timing->'counts'),
    'depth', tonde_private.lf_depth(target_workspace, target_production, target_level, target_id),
    'summary', tonde_private.lf_summary(target_workspace, target_production, target_level, target_id),
    'budget_chars', budget, 'truncated', true,
    'note', 'Scoped context only: parent chain, bounded siblings, bound assets and relevant documents.');
end $$;


-- 15. Structure writes. Act/Sequence are real structural objects with revision, approval and
-- lock, and Scenes/Shots keep their existing identity through every move.
create or replace function tonde.create_long_form_act(target_workspace uuid, target_production uuid,
  expected_production_revision integer, act jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare created tonde.acts; next_order bigint; title_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if jsonb_typeof(act) <> 'object' then raise exception 'Invalid Act payload' using errcode = '22023'; end if;
  title_value := btrim(coalesce(act->>'title',''));
  if length(title_value) = 0 or length(title_value) > 160 then
    raise exception 'An Act needs a title of 1 to 160 characters' using errcode = '22023';
  end if;
  select coalesce(max(a.sort_order), 0) + 1024 into next_order from tonde.acts a
    where a.workspace_id = target_workspace and a.production_id = target_production;
  insert into tonde.acts(workspace_id, production_id, title, purpose, narrative_goal, opening_state, ending_state,
    sort_order, planned_duration_ms)
  values (target_workspace, target_production, left(title_value,160), left(coalesce(act->>'purpose',''),1200),
    left(coalesce(act->>'narrative_goal',''),1200), left(coalesce(act->>'opening_state',''),600),
    left(coalesce(act->>'ending_state',''),600), next_order,
    tonde_private.lf_ms(act, 'duration_ms'))
  returning * into created;
  return jsonb_build_object('act_id', created.id, 'title', created.title, 'sort_order', created.sort_order,
    'revision', created.revision, 'approval', created.approval, 'planned_duration_ms', created.planned_duration_ms,
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


create or replace function tonde.update_long_form_act(target_workspace uuid, target_production uuid, target_act uuid,
  expected_revision integer, patch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare updated tonde.acts; current tonde.acts; title_value text; lifecycle_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(patch) <> 'object' then raise exception 'Invalid Act patch' using errcode = '22023'; end if;
  perform tonde_private.lf_node_guard(target_workspace, target_production, 'act', target_act, expected_revision);
  select * into current from tonde.acts where workspace_id = target_workspace and production_id = target_production and id = target_act;
  title_value := current.title;
  if patch ? 'title' then
    title_value := btrim(coalesce(patch->>'title',''));
    if length(title_value) = 0 or length(title_value) > 160 then
      raise exception 'An Act needs a title of 1 to 160 characters' using errcode = '22023';
    end if;
  end if;
  lifecycle_value := current.lifecycle::text;
  if patch ? 'lifecycle' then
    lifecycle_value := coalesce(nullif(patch->>'lifecycle',''), 'active');
    if lifecycle_value not in ('active','archived') then raise exception 'Acts archive rather than delete' using errcode = '22023'; end if;
    if lifecycle_value = 'archived' and exists(select 1 from tonde.sequences q where q.workspace_id = target_workspace
      and q.production_id = target_production and q.act_id = target_act and q.lifecycle = 'active') then
      raise exception 'This Act still has live Sequences. Archive or move them first.' using errcode = '23514';
    end if;
  end if;
  update tonde.acts set title = title_value,
    purpose = case when patch ? 'purpose' then left(coalesce(patch->>'purpose',''),1200) else purpose end,
    narrative_goal = case when patch ? 'narrative_goal' then left(coalesce(patch->>'narrative_goal',''),1200) else narrative_goal end,
    opening_state = case when patch ? 'opening_state' then left(coalesce(patch->>'opening_state',''),600) else opening_state end,
    ending_state = case when patch ? 'ending_state' then left(coalesce(patch->>'ending_state',''),600) else ending_state end,
    planned_duration_ms = case when patch ? 'duration_ms' then tonde_private.lf_ms(patch, 'duration_ms') else planned_duration_ms end,
    lifecycle = lifecycle_value::tonde.lifecycle
  where workspace_id = target_workspace and production_id = target_production and id = target_act
  returning * into updated;
  return jsonb_build_object('act_id', updated.id, 'revision', updated.revision, 'approval', updated.approval,
    'lifecycle', updated.lifecycle, 'planned_duration_ms', updated.planned_duration_ms,
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


create or replace function tonde.create_long_form_sequence(target_workspace uuid, target_production uuid,
  expected_production_revision integer, sequence jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare created tonde.sequences; next_order bigint; title_value text; act_value uuid; kind_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, expected_production_revision);
  if jsonb_typeof(sequence) <> 'object' then raise exception 'Invalid Sequence payload' using errcode = '22023'; end if;
  title_value := btrim(coalesce(sequence->>'title',''));
  if length(title_value) = 0 or length(title_value) > 160 then
    raise exception 'A Sequence needs a title of 1 to 160 characters' using errcode = '22023';
  end if;
  act_value := nullif(coalesce(sequence->>'act_id',''),'')::uuid;
  if act_value is not null and not exists(select 1 from tonde.acts a where a.workspace_id = target_workspace
    and a.production_id = target_production and a.id = act_value and a.lifecycle = 'active') then
    raise exception 'Sequence Act is unavailable in this Production' using errcode = 'P0002';
  end if;
  kind_value := coalesce(nullif(sequence->>'kind',''), 'narrative');
  if not (kind_value = any(enum_range(null::tonde.sequence_kind)::text[])) then
    raise exception 'Unsupported Sequence kind' using errcode = '22023';
  end if;
  select coalesce(max(q.sort_order), 0) + 1024 into next_order from tonde.sequences q
    where q.workspace_id = target_workspace and q.production_id = target_production;
  insert into tonde.sequences(workspace_id, production_id, act_id, title, purpose, kind, sort_order, planned_duration_ms)
  values (target_workspace, target_production, act_value, left(title_value,160),
    left(coalesce(sequence->>'purpose',''),1200), kind_value::tonde.sequence_kind, next_order,
    tonde_private.lf_ms(sequence, 'duration_ms'))
  returning * into created;
  return jsonb_build_object('sequence_id', created.id, 'title', created.title, 'act_id', created.act_id,
    'sort_order', created.sort_order, 'revision', created.revision, 'approval', created.approval,
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


create or replace function tonde.update_long_form_sequence(target_workspace uuid, target_production uuid, target_sequence uuid,
  expected_revision integer, patch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare updated tonde.sequences; current tonde.sequences; title_value text; lifecycle_value text; act_value uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(patch) <> 'object' then raise exception 'Invalid Sequence patch' using errcode = '22023'; end if;
  perform tonde_private.lf_node_guard(target_workspace, target_production, 'sequence', target_sequence, expected_revision);
  select * into current from tonde.sequences where workspace_id = target_workspace and production_id = target_production and id = target_sequence;
  title_value := current.title;
  if patch ? 'title' then
    title_value := btrim(coalesce(patch->>'title',''));
    if length(title_value) = 0 or length(title_value) > 160 then
      raise exception 'A Sequence needs a title of 1 to 160 characters' using errcode = '22023';
    end if;
  end if;
  lifecycle_value := current.lifecycle::text;
  if patch ? 'lifecycle' then
    lifecycle_value := coalesce(nullif(patch->>'lifecycle',''), 'active');
    if lifecycle_value not in ('active','archived') then raise exception 'Sequences archive rather than delete' using errcode = '22023'; end if;
    if lifecycle_value = 'archived' and exists(select 1 from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.sequence_id = target_sequence and s.lifecycle = 'active') then
      raise exception 'This Sequence still has live Scenes. Move or archive them first.' using errcode = '23514';
    end if;
  end if;
  act_value := current.act_id;
  if patch ? 'act_id' then
    act_value := nullif(coalesce(patch->>'act_id',''),'')::uuid;
    if act_value is not null and not exists(select 1 from tonde.acts a where a.workspace_id = target_workspace
      and a.production_id = target_production and a.id = act_value and a.lifecycle = 'active') then
      raise exception 'Sequence Act is unavailable in this Production' using errcode = 'P0002';
    end if;
    if exists(select 1 from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production
      and s.sequence_id = target_sequence and s.lifecycle = 'active' and s.act_id is distinct from act_value) then
      raise exception 'This Sequence holds Scenes in another Act. Move the Sequence instead of its Act.' using errcode = '23514';
    end if;
  end if;
  update tonde.sequences set title = title_value,
    purpose = case when patch ? 'purpose' then left(coalesce(patch->>'purpose',''),1200) else purpose end,
    kind = case when patch ? 'kind' then coalesce(nullif(patch->>'kind',''),'narrative')::tonde.sequence_kind else kind end,
    act_id = act_value,
    planned_duration_ms = case when patch ? 'duration_ms' then tonde_private.lf_ms(patch, 'duration_ms') else planned_duration_ms end,
    lifecycle = lifecycle_value::tonde.lifecycle
  where workspace_id = target_workspace and production_id = target_production and id = target_sequence
  returning * into updated;
  return jsonb_build_object('sequence_id', updated.id, 'revision', updated.revision, 'approval', updated.approval,
    'act_id', updated.act_id, 'lifecycle', updated.lifecycle,
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


-- Moving a Scene between Sequences or Acts preserves the Scene UUID and every Shot in it.
create or replace function tonde.move_long_form_scene(target_workspace uuid, target_production uuid, target_scene uuid,
  expected_revision integer, target_sequence uuid default null, target_act uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare moved tonde.scenes; next_order bigint; sequence_act uuid; desired_act uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.studio_revision_guard(target_workspace, target_production, target_scene, 'scene', expected_revision);
  desired_act := target_act;
  if target_sequence is not null then
    select q.act_id into sequence_act from tonde.sequences q where q.workspace_id = target_workspace
      and q.production_id = target_production and q.id = target_sequence and q.lifecycle = 'active';
    if not found then raise exception 'Target Sequence is unavailable in this Production' using errcode = 'P0002'; end if;
    if desired_act is not null and desired_act is distinct from sequence_act then
      raise exception 'The Scene moves with its Sequence''s Act' using errcode = '23514';
    end if;
    desired_act := sequence_act;
  elsif desired_act is not null and not exists(select 1 from tonde.acts a where a.workspace_id = target_workspace
    and a.production_id = target_production and a.id = desired_act and a.lifecycle = 'active') then
    raise exception 'Target Act is unavailable in this Production' using errcode = 'P0002';
  end if;
  select coalesce(max(s.sort_order), 0) + 1024 into next_order from tonde.scenes s
    where s.workspace_id = target_workspace and s.production_id = target_production;
  update tonde.scenes set sequence_id = target_sequence, act_id = desired_act, sort_order = next_order
    where workspace_id = target_workspace and production_id = target_production and id = target_scene
  returning * into moved;
  return jsonb_build_object('scene_id', moved.id, 'sequence_id', moved.sequence_id, 'act_id', moved.act_id,
    'sort_order', moved.sort_order, 'revision', moved.revision, 'shots_unchanged',
      (select count(*) from tonde.shots h where h.workspace_id = target_workspace and h.production_id = target_production
        and h.scene_id = target_scene),
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


create or replace function tonde.move_long_form_sequence(target_workspace uuid, target_production uuid, target_sequence uuid,
  expected_revision integer, target_act uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare moved tonde.sequences; next_order bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  perform tonde_private.lf_node_guard(target_workspace, target_production, 'sequence', target_sequence, expected_revision);
  if target_act is not null and not exists(select 1 from tonde.acts a where a.workspace_id = target_workspace
    and a.production_id = target_production and a.id = target_act and a.lifecycle = 'active') then
    raise exception 'Target Act is unavailable in this Production' using errcode = 'P0002';
  end if;
  select coalesce(max(q.sort_order), 0) + 1024 into next_order from tonde.sequences q
    where q.workspace_id = target_workspace and q.production_id = target_production;
  update tonde.sequences set act_id = target_act, sort_order = next_order
    where workspace_id = target_workspace and production_id = target_production and id = target_sequence
  returning * into moved;
  update tonde.scenes set act_id = target_act where workspace_id = target_workspace
    and production_id = target_production and sequence_id = target_sequence and lifecycle = 'active';
  return jsonb_build_object('sequence_id', moved.id, 'act_id', moved.act_id, 'sort_order', moved.sort_order,
    'revision', moved.revision, 'scenes_moved', (select count(*) from tonde.scenes s
      where s.workspace_id = target_workspace and s.production_id = target_production and s.sequence_id = target_sequence),
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


-- Explicit split: children at or after the split order move into a NEW Act/Sequence. No Scene
-- or Shot is duplicated, and the split point is the creator's declared order.
create or replace function tonde.split_long_form_structure(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid, split_order bigint, expected_revision integer,
  new_title text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare source_title text; created_id uuid; next_order bigint; moved_sequences integer := 0;
  moved_scenes integer := 0; source_act uuid; title_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_level not in ('act','sequence') then
    raise exception 'Split applies to an Act or a Sequence' using errcode = '22023';
  end if;
  perform tonde_private.lf_node_guard(target_workspace, target_production, target_level, target_id, expected_revision);
  if target_level = 'act' then
    select a.title into source_title from tonde.acts a where a.workspace_id = target_workspace
      and a.production_id = target_production and a.id = target_id;
    title_value := left(coalesce(nullif(btrim(new_title),''), source_title || ' - part 2'), 160);
    select coalesce(max(a.sort_order), 0) + 1024 into next_order from tonde.acts a
      where a.workspace_id = target_workspace and a.production_id = target_production;
    insert into tonde.acts(workspace_id, production_id, title, purpose, sort_order)
    values (target_workspace, target_production, title_value, '', next_order) returning id into created_id;
    update tonde.sequences set act_id = created_id where workspace_id = target_workspace
      and production_id = target_production and act_id = target_id and lifecycle = 'active' and sort_order >= split_order;
    get diagnostics moved_sequences = row_count;
    update tonde.scenes set act_id = created_id where workspace_id = target_workspace
      and production_id = target_production and act_id = target_id and sequence_id is null
      and lifecycle = 'active' and sort_order >= split_order;
    get diagnostics moved_scenes = row_count;
  else
    select q.title, q.act_id into source_title, source_act from tonde.sequences q where q.workspace_id = target_workspace
      and q.production_id = target_production and q.id = target_id;
    title_value := left(coalesce(nullif(btrim(new_title),''), source_title || ' - part 2'), 160);
    select coalesce(max(q.sort_order), 0) + 1024 into next_order from tonde.sequences q
      where q.workspace_id = target_workspace and q.production_id = target_production;
    insert into tonde.sequences(workspace_id, production_id, act_id, title, purpose, sort_order)
    values (target_workspace, target_production, source_act, title_value, '', next_order) returning id into created_id;
    update tonde.scenes set sequence_id = created_id where workspace_id = target_workspace
      and production_id = target_production and sequence_id = target_id and lifecycle = 'active' and sort_order >= split_order;
    get diagnostics moved_scenes = row_count;
  end if;
  return jsonb_build_object('level', target_level, 'source_id', target_id, 'created_id', created_id,
    'title', title_value, 'moved_sequences', moved_sequences, 'moved_scenes', moved_scenes,
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


create or replace function tonde.reorder_long_form(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, ordered_ids uuid[], expected_production_revision integer,
  parent_id uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare live_count integer; provided_count integer; base_order bigint;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_level not in ('act','sequence') then raise exception 'Reorder applies to Acts or Sequences' using errcode = '22023'; end if;
  if expected_production_revision is not null
    and tonde_private.lf_structure_revision(target_workspace, target_production) <> expected_production_revision then
    raise exception 'The structure changed since you loaded it' using errcode = '40001';
  end if;
  if ordered_ids is null or array_length(ordered_ids, 1) is null then
    raise exception 'Provide the complete order' using errcode = '22023';
  end if;
  select count(distinct value) into provided_count from unnest(ordered_ids) as value;
  if provided_count <> array_length(ordered_ids, 1) then raise exception 'The order contains duplicates' using errcode = '22023'; end if;
  if target_level = 'act' then
    select count(*) into live_count from tonde.acts a where a.workspace_id = target_workspace
      and a.production_id = target_production and a.lifecycle = 'active';
    if provided_count <> live_count or exists(select 1 from unnest(ordered_ids) as value
      where not exists(select 1 from tonde.acts a where a.workspace_id = target_workspace
        and a.production_id = target_production and a.id = value and a.lifecycle = 'active')) then
      raise exception 'The order must list exactly the live Acts of this Production' using errcode = '22023';
    end if;
    select coalesce(max(a.sort_order), 0) + 1024 into base_order from tonde.acts a
      where a.workspace_id = target_workspace and a.production_id = target_production;
    set constraints all deferred;
    update tonde.acts a set sort_order = base_order + ranked.position * 1024
      from (select value as id, row_number() over () as position from unnest(ordered_ids) as value) ranked
      where a.workspace_id = target_workspace and a.production_id = target_production and a.id = ranked.id;
  else
    select count(*) into live_count from tonde.sequences q where q.workspace_id = target_workspace
      and q.production_id = target_production and q.lifecycle = 'active' and q.act_id is not distinct from parent_id;
    if provided_count <> live_count or exists(select 1 from unnest(ordered_ids) as value
      where not exists(select 1 from tonde.sequences q where q.workspace_id = target_workspace
        and q.production_id = target_production and q.id = value and q.lifecycle = 'active'
        and q.act_id is not distinct from parent_id)) then
      raise exception 'The order must list exactly the live Sequences of this Act' using errcode = '22023';
    end if;
    select coalesce(max(q.sort_order), 0) + 1024 into base_order from tonde.sequences q
      where q.workspace_id = target_workspace and q.production_id = target_production;
    set constraints all deferred;
    update tonde.sequences q set sort_order = base_order + ranked.position * 1024
      from (select value as id, row_number() over () as position from unnest(ordered_ids) as value) ranked
      where q.workspace_id = target_workspace and q.production_id = target_production and q.id = ranked.id;
  end if;
  return jsonb_build_object('level', target_level, 'items', live_count,
    'timing', tonde_private.lf_production_timing(target_workspace, target_production));
end $$;


create or replace function tonde.set_long_form_approval(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid, desired_approval text, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare resulting tonde.approval; resulting_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_level not in ('act','sequence') then raise exception 'Approval scope must be act or sequence here' using errcode = '22023'; end if;
  if desired_approval not in ('draft','needs_review','approved','changed_after_approval') then
    raise exception 'Unsupported approval state' using errcode = '22023';
  end if;
  perform tonde_private.lf_node_guard(target_workspace, target_production, target_level, target_id, expected_revision);
  if target_level = 'act' then
    update tonde.acts set approval = desired_approval::tonde.approval
      where workspace_id = target_workspace and production_id = target_production and id = target_id
      returning approval, revision into resulting, resulting_revision;
  else
    update tonde.sequences set approval = desired_approval::tonde.approval
      where workspace_id = target_workspace and production_id = target_production and id = target_id
      returning approval, revision into resulting, resulting_revision;
  end if;
  return jsonb_build_object('level', target_level, 'id', target_id, 'approval', resulting, 'revision', resulting_revision);
end $$;


create or replace function tonde.set_long_form_lock(target_workspace uuid, target_production uuid,
  target_level tonde.structure_level, target_id uuid, locked boolean, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare resulting_revision integer; resulting_locked timestamptz;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if target_level not in ('act','sequence') then raise exception 'Lock scope must be act or sequence here' using errcode = '22023'; end if;
  if expected_revision is not null and tonde_private.lf_scope_revision(target_workspace, target_production, target_level, target_id) <> expected_revision then
    raise exception 'That object changed since you loaded it' using errcode = '40001';
  end if;
  if target_level = 'act' then
    update tonde.acts set locked_at = case when coalesce(locked,false) then now() else null end
      where workspace_id = target_workspace and production_id = target_production and id = target_id
      returning revision, locked_at into resulting_revision, resulting_locked;
  else
    update tonde.sequences set locked_at = case when coalesce(locked,false) then now() else null end
      where workspace_id = target_workspace and production_id = target_production and id = target_id
      returning revision, locked_at into resulting_revision, resulting_locked;
  end if;
  if resulting_revision is null then raise exception 'That object is unavailable in this Production' using errcode = 'P0002'; end if;
  return jsonb_build_object('level', target_level, 'id', target_id, 'locked', resulting_locked is not null,
    'revision', resulting_revision);
end $$;


-- 16. Series helpers. Series context is REFERENCED, never copied into every Episode row.
create or replace function tonde_private.lf_series_for(target_workspace uuid, target_series uuid) returns tonde.series
language plpgsql stable security definer set search_path = '' as $$
declare row_value tonde.series;
begin
  select * into row_value from tonde.series where workspace_id = target_workspace and id = target_series;
  if not found then raise exception 'Series unavailable' using errcode = 'P0002'; end if;
  return row_value;
end $$;


create or replace function tonde_private.lf_series_revision_guard(target_workspace uuid, target_series uuid, expected_revision integer)
returns tonde.series language plpgsql security definer set search_path = '' as $$
declare row_value tonde.series;
begin
  perform tonde_private.director_guard(target_workspace);
  row_value := tonde_private.lf_series_for(target_workspace, target_series);
  if row_value.lifecycle <> 'active' then raise exception 'This Series is archived' using errcode = '23514'; end if;
  if expected_revision is not null and row_value.revision <> expected_revision then
    raise exception 'The Series changed since you loaded it' using errcode = '40001';
  end if;
  return row_value;
end $$;


create or replace function tonde_private.lf_bind_asset(target_workspace uuid, target_production uuid, target_asset uuid,
  role_value text, expected_type tonde.asset_type) returns boolean
language plpgsql security definer set search_path = '' as $$
begin
  if target_asset is null then return false; end if;
  if not exists(select 1 from tonde.assets a where a.workspace_id = target_workspace and a.id = target_asset
    and a.asset_type = expected_type and a.lifecycle = 'active') then return false; end if;
  if exists(select 1 from tonde.scope_bindings b where b.workspace_id = target_workspace
    and b.production_id = target_production and b.scope_object_id = target_production
    and b.asset_id = target_asset and b.binding_role = role_value::tonde.binding_role) then return true; end if;
  insert into tonde.scope_bindings(workspace_id, production_id, scope_object_id, asset_id, binding_role, inheritance)
  values (target_workspace, target_production, target_production, target_asset, role_value::tonde.binding_role, 'inherit');
  return true;
end $$;


-- Episode inheritance: series-level reusable context flows into the Episode Production as an
-- inheriting binding on the canonical Asset. A production-specific override adds its own
-- binding later and never mutates the Series row.
create or replace function tonde_private.lf_inherit_series_context(target_workspace uuid, series_row tonde.series, target_production uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare format jsonb := coalesce(series_row.format, '{}'::jsonb); item text; bound integer := 0;
begin
  if tonde_private.lf_bind_asset(target_workspace, target_production,
      nullif(format->>'style_bible_id','')::uuid, 'style', 'style_bible') then bound := bound + 1; end if;
  if tonde_private.lf_bind_asset(target_workspace, target_production,
      nullif(format->>'host_asset_id','')::uuid, 'character', 'character') then bound := bound + 1; end if;
  for item in select jsonb_array_elements_text(coalesce(format->'character_ids','[]'::jsonb)) loop
    if tonde_private.lf_bind_asset(target_workspace, target_production, item::uuid, 'character', 'character')
      then bound := bound + 1; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(format->'environment_ids','[]'::jsonb)) loop
    if tonde_private.lf_bind_asset(target_workspace, target_production, item::uuid, 'world', 'environment')
      then bound := bound + 1; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(format->'product_ids','[]'::jsonb)) loop
    if tonde_private.lf_bind_asset(target_workspace, target_production, item::uuid, 'product', 'product')
      then bound := bound + 1; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(format->'wardrobe_ids','[]'::jsonb)) loop
    if tonde_private.lf_bind_asset(target_workspace, target_production, item::uuid, 'wardrobe', 'wardrobe')
      then bound := bound + 1; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(format->'prop_ids','[]'::jsonb)) loop
    if tonde_private.lf_bind_asset(target_workspace, target_production, item::uuid, 'prop', 'prop')
      then bound := bound + 1; end if;
  end loop;
  for item in select jsonb_array_elements_text(coalesce(format->'voice_ids','[]'::jsonb)) loop
    if tonde_private.lf_bind_asset(target_workspace, target_production, item::uuid, 'voice', 'voice')
      then bound := bound + 1; end if;
  end loop;
  return jsonb_build_object('bound', bound, 'note', 'Canonical Assets are referenced through inheriting bindings, not copied.');
end $$;


-- Deterministic slot calculation. Dates come from the Series' own timezone and cadence, never
-- from server UTC, and an occupied slot is always reported instead of being reused.
create or replace function tonde_private.lf_slots(target_workspace uuid, target_series uuid,
  target_horizon tonde.generate_horizon, requested_count integer, base_date date)
returns table(out_slot_key text, out_planned_date date, out_episode_number bigint, out_occupancy text,
  out_existing_episode_id uuid)
language plpgsql stable security definer set search_path = '' as $$
declare series_row tonde.series; cadence jsonb; kind text; step_days integer; weekdays integer[];
  wanted integer; produced integer := 0; cursor_date date; next_number bigint;
  key_value text; date_value date; number_value bigint; state_value text; existing_value uuid;
begin
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  cadence := coalesce(series_row.cadence_metadata, '{}'::jsonb);
  kind := coalesce(nullif(cadence->>'kind',''), 'daily');
  if kind not in ('daily','weekdays','weekly','selected_weekdays','custom','none') then
    raise exception 'Unsupported cadence kind' using errcode = '22023';
  end if;
  step_days := greatest(coalesce(nullif(cadence->>'every_days','')::integer, case when kind = 'weekly' then 7 else 1 end), 1);
  weekdays := coalesce((select array_agg(value::integer order by value::integer)
    from jsonb_array_elements_text(coalesce(cadence->'weekdays','[]'::jsonb)) as value), '{}'::integer[]);
  if kind in ('weekdays','selected_weekdays') and coalesce(array_length(weekdays,1), 0) = 0 then
    if kind = 'weekdays' then weekdays := array[1,2,3,4,5];
    else raise exception 'This cadence needs at least one weekday' using errcode = '23514'; end if;
  end if;
  if target_horizon = 'tomorrow' then wanted := 1;
  elsif target_horizon = 'next_7' then wanted := 7;
  elsif target_horizon = 'next_14' then wanted := 14;
  elsif target_horizon = 'next_30' then wanted := 30;
  elsif target_horizon = 'custom' then wanted := requested_count;
  else
    wanted := nullif(coalesce(nullif(series_row.format->>'planned_episodes','')::integer, 0), 0);
    if wanted is null then
      raise exception 'This Series is open-ended. Choose a finite horizon or a custom count instead.' using errcode = '23514';
    end if;
  end if;
  if wanted is null or wanted < 1 or wanted > 400 then
    raise exception 'Generate Ahead needs between 1 and 400 slots' using errcode = '22023';
  end if;
  select coalesce(max(e.episode_number), 0) into number_value from tonde.series_episodes e
    where e.series_id = target_series;
  next_number := number_value + 1;
  if kind = 'none' then
    cursor_date := null;
  else
    cursor_date := coalesce(base_date, (now() at time zone series_row.timezone)::date + 1);
  end if;
  while produced < wanted loop
    if kind = 'none' then
      key_value := 'count:' || next_number::text;
      date_value := null;
    else
      if kind in ('weekdays','selected_weekdays') then
        while not (extract(isodow from cursor_date)::integer = any(weekdays)) loop
          cursor_date := cursor_date + 1;
        end loop;
      end if;
      key_value := to_char(cursor_date, 'YYYY-MM-DD');
      date_value := cursor_date;
    end if;
    select e.id into existing_value from tonde.series_episodes e
      where e.series_id = target_series and e.workspace_id = target_workspace
        and (e.slot_key = key_value or (e.planned_date is not null and e.planned_date = date_value))
      order by e.episode_number limit 1;
    if existing_value is not null then
      select e.episode_number into number_value from tonde.series_episodes e where e.id = existing_value;
      state_value := 'occupied';
    else
      number_value := next_number;
      next_number := next_number + 1;
      state_value := 'open';
    end if;
    out_slot_key := key_value; out_planned_date := date_value; out_episode_number := number_value;
    out_occupancy := state_value; out_existing_episode_id := existing_value;
    produced := produced + 1;
    return next;
    if kind <> 'none' then cursor_date := cursor_date + step_days; end if;
  end loop;
end $$;


create or replace function tonde_private.lf_episode_title(series_row tonde.series, slot_date date, slot_number bigint, topic text)
returns text language plpgsql immutable set search_path = '' as $$
declare pattern text; value text;
begin
  if coalesce(btrim(topic), '') <> '' then return left(btrim(topic), 160); end if;
  pattern := coalesce(nullif(series_row.format->>'title_pattern',''), '{series} {n}');
  value := replace(replace(replace(pattern, '{series}', series_row.title), '{n}', slot_number::text),
    '{date}', coalesce(to_char(slot_date, 'YYYY-MM-DD'), 'entry ' || slot_number::text));
  if value = pattern then value := value || ' ' || slot_number::text; end if;
  return left(value, 160);
end $$;


create or replace function tonde_private.lf_line_state(target_workspace uuid, target_production uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
declare live_shots integer; planned_shots integer; scene_count integer; activity integer; reviewed integer;
  complete_plan boolean; approved_result integer;
begin
  select count(*) into scene_count from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.lifecycle = 'active';
  select count(*), count(*) filter (where p.id is not null) into live_shots, planned_shots
    from tonde.shots h left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active';
  select count(*) into reviewed from tonde.results r where r.workspace_id = target_workspace
    and r.production_id = target_production and r.state in ('raw','needs_review');
  select count(*) into approved_result from tonde.results r where r.workspace_id = target_workspace
    and r.production_id = target_production and r.state in ('approved','final');
  select count(*) into activity from tonde.shots h
    left join tonde.shot_capture_state cs on cs.workspace_id = h.workspace_id and cs.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'
      and cs.status in ('setup','shooting','captured','pickup_needed');
  if scene_count = 0 and live_shots = 0 then
    if exists(select 1 from tonde.creative_documents d where d.workspace_id = target_workspace and d.production_id = target_production
      and d.document_type = 'brief') then return 'brief'; end if;
    if exists(select 1 from tonde.creative_documents d where d.workspace_id = target_workspace and d.production_id = target_production
      and d.document_type in ('story','treatment')) then return 'story'; end if;
    return 'idea';
  end if;
  if scene_count > 0 and live_shots = 0 then
    if exists(select 1 from tonde.creative_documents d where d.workspace_id = target_workspace and d.production_id = target_production
      and d.document_type = 'script') and scene_count > 0 then return 'script'; end if;
    return 'scene_plan';
  end if;
  complete_plan := live_shots > 0 and planned_shots = live_shots;
  if reviewed > 0 then return 'review'; end if;
  if complete_plan and exists(select 1 from tonde.productions p where p.workspace_id = target_workspace
    and p.id = target_production and p.approval = 'approved') and live_shots > 0
    and approved_result >= live_shots then return 'complete'; end if;
  if exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production
    and p.approval = 'approved') then return 'approved'; end if;
  if activity > 0 or exists(select 1 from tonde.ai_generation_attempts a where a.workspace_id = target_workspace
    and a.production_id = target_production and a.status in ('planned','submitted','succeeded')) then return 'in_production'; end if;
  if complete_plan then return 'ready_to_execute'; end if;
  return 'shot_plan';
end $$;


revoke all on function tonde_private.lf_series_for(uuid,uuid), tonde_private.lf_series_revision_guard(uuid,uuid,integer),
  tonde_private.lf_bind_asset(uuid,uuid,uuid,text,tonde.asset_type),
  tonde_private.lf_inherit_series_context(uuid,tonde.series,uuid),
  tonde_private.lf_slots(uuid,uuid,tonde.generate_horizon,integer,date),
  tonde_private.lf_episode_title(tonde.series,date,bigint,text),
  tonde_private.lf_line_state(uuid,uuid) from public, anon, authenticated, service_role;


create or replace function tonde_private.lf_blockers(target_workspace uuid, target_production uuid, requested tonde.generate_depth)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare items jsonb := '[]'::jsonb; depth tonde.planning_depth; timing jsonb; scenes integer;
  shots integer; unplanned integer; planned_ms bigint;
begin
  depth := tonde_private.lf_depth(target_workspace, target_production, 'production', target_production);
  timing := tonde_private.lf_production_timing(target_workspace, target_production);
  select count(*) into scenes from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.lifecycle = 'active';
  select count(*), count(*) filter (where p.id is null) into shots, unplanned
    from tonde.shots h left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active';
  select planned_duration_ms into planned_ms from tonde.productions
    where workspace_id = target_workspace and id = target_production;
  if scenes = 0 then
    items := items || jsonb_build_array(jsonb_build_object('code','no_scenes','severity',
      case when requested in ('story','script','complete_plan') then 'blocking' else 'warning' end,
      'message','This Episode has no Scenes yet.','action','Build or generate the Scene plan.'));
  end if;
  if requested in ('story','script','complete_plan') and depth < 'story_defined' then
    items := items || jsonb_build_array(jsonb_build_object('code','requested_depth_missing','severity','blocking',
      'message','Generate Ahead recorded ' || requested::text || ' as the requested depth, but the Story is not written yet.',
      'action','Write or generate the Story for this Episode.'));
  end if;
  if requested in ('script','complete_plan') and depth < 'scripted' and scenes > 0 then
    items := items || jsonb_build_array(jsonb_build_object('code','script_missing','severity','warning',
      'message','No Script document exists for this Episode yet.','action','Write or generate the Script.'));
  end if;
  if scenes > 0 and planned_ms is null then
    items := items || jsonb_build_array(jsonb_build_object('code','runtime_target_missing','severity','warning',
      'message','This Episode has no runtime target, so its fit cannot be judged.','action','Set a planned runtime.'));
  end if;
  if (timing->'production'->>'status') = 'over' then
    items := items || jsonb_build_array(jsonb_build_object('code','runtime_conflict','severity','blocking',
      'message','Planned runtime is ' || coalesce(timing->'production'->>'target_label','?') || ' but the current child total is '
        || coalesce(timing->'production'->>'calculated_label','?') || ' (' || coalesce(timing->'production'->>'delta_label','?') || ').',
      'action','Shorten or reassign runtime in the affected Scenes.'));
  end if;
  if (timing->'counts'->>'scenes_without_shots')::integer > 0 then
    items := items || jsonb_build_array(jsonb_build_object('code','scenes_without_shots','severity','warning',
      'message',(timing->'counts'->>'scenes_without_shots') || ' Scene(s) still have no Shots.',
      'action','Plan the Shots for those Scenes.'));
  end if;
  if shots > 0 and unplanned > 0 then
    items := items || jsonb_build_array(jsonb_build_object('code','shots_without_execution_plan','severity','warning',
      'message',unplanned || ' Shot(s) have no execution plan.',
      'action','Direct those Shots in Real Production or AI Creation.'));
  end if;
  if (timing->'counts'->>'scenes_incomplete_timing')::integer > 0 then
    items := items || jsonb_build_array(jsonb_build_object('code','timing_incomplete','severity','warning',
      'message',(timing->'counts'->>'scenes_incomplete_timing') || ' Scene(s) have Shots without durations, so their runtime is planned rather than derived.',
      'action','Give every Shot an exact duration.'));
  end if;
  if exists(select 1 from tonde.shots h join tonde.shot_capture_state cs
      on cs.workspace_id = h.workspace_id and cs.shot_id = h.id
      where h.workspace_id = target_workspace and h.production_id = target_production
        and h.lifecycle = 'active' and cs.status = 'pickup_needed') then
    items := items || jsonb_build_array(jsonb_build_object('code','pickup_required','severity','blocking',
      'message','A Shot is marked pickup required.','action','Schedule the pickup or record a new take.'));
  end if;
  return items;
end $$;


-- One shared planner for preview and apply, so the preview cannot disagree with the result.
create or replace function tonde_private.lf_generate_plan(target_workspace uuid, series_row tonde.series, request jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare horizon tonde.generate_horizon; depth tonde.generate_depth; slots jsonb; counts jsonb;
  holds text[]; reuse jsonb; recent jsonb; depth_label text;
begin
  horizon := coalesce(nullif(request->>'horizon',''), '')::tonde.generate_horizon;
  if horizon is null or not (horizon::text = any(enum_range(null::tonde.generate_horizon)::text[])) then
    raise exception 'Choose a Generate Ahead horizon' using errcode = '22023';
  end if;
  depth := coalesce(nullif(request->>'depth',''), '')::tonde.generate_depth;
  if depth is null or not (depth::text = any(enum_range(null::tonde.generate_depth)::text[])) then
    raise exception 'Choose a Generate Ahead depth' using errcode = '22023';
  end if;
  holds := coalesce(array(select jsonb_array_elements_text(coalesce(request->'hold_slots','[]'::jsonb))), '{}'::text[]);
  select coalesce(jsonb_agg(jsonb_build_object('slot_key', s.out_slot_key, 'planned_date', s.out_planned_date,
      'episode_number', s.out_episode_number,
      'state', case when s.out_occupancy = 'occupied' then 'preserved'
        when s.out_slot_key = any(holds) then 'held' else 'open' end,
      'existing_episode_id', s.out_existing_episode_id)
      order by s.out_planned_date nulls last, s.out_episode_number), '[]'::jsonb),
    jsonb_build_object(
      'open', count(*) filter (where s.out_occupancy = 'open' and not (s.out_slot_key = any(holds))),
      'preserved', count(*) filter (where s.out_occupancy = 'occupied'),
      'held', count(*) filter (where s.out_occupancy = 'open' and s.out_slot_key = any(holds)),
      'total', count(*))
    into slots, counts
  from tonde_private.lf_slots(target_workspace, series_row.id, horizon,
    coalesce(nullif(request->>'count','')::integer, 0), nullif(request->>'base_date','')::date) s;
  select coalesce(jsonb_agg(jsonb_build_object('asset_id', b.asset_id, 'name', a.name, 'asset_type', a.asset_type,
      'role', b.binding_role) order by a.name), '[]'::jsonb) into reuse
  from tonde.scope_bindings b join tonde.assets a on a.workspace_id = b.workspace_id and a.id = b.asset_id
  where b.workspace_id = target_workspace and b.asset_id in (
    select nullif(series_row.format->>'style_bible_id','')::uuid
    union all select nullif(series_row.format->>'host_asset_id','')::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'character_ids','[]'::jsonb))::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'environment_ids','[]'::jsonb))::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'product_ids','[]'::jsonb))::uuid);
  select coalesce(jsonb_agg(jsonb_build_object('episode_number', e.episode_number, 'title', e.title,
      'planned_date', e.planned_date) order by e.episode_number desc), '[]'::jsonb) into recent
  from (select * from tonde.series_episodes e where e.workspace_id = target_workspace and e.series_id = series_row.id
    and e.lifecycle = 'active' order by e.episode_number desc limit 5) e;
  depth_label := case depth when 'ideas_only' then 'Ideas Only' when 'briefs' then 'Briefs' when 'story' then 'Story'
    when 'script' then 'Script' else 'Complete Production Plan' end;
  return jsonb_build_object('horizon', horizon, 'depth', depth, 'depth_label', depth_label,
    'timezone', series_row.timezone, 'today', (now() at time zone series_row.timezone)::date,
    'slots', slots, 'counts', counts, 'reuse', reuse, 'recent_titles', recent,
    'requires_confirmation', (counts->>'open')::integer > 0,
    'reuse_note', 'Series-level Assets are referenced through inheriting bindings; this Episode is a new Production.',
    'depth_note', 'Generate Ahead records the requested depth and creates the Production shell. It never fabricates Story, Script, Scenes, Shots or paid generation attempts.',
    'do_not_overwrite', 'Existing Episodes at these slots are preserved and never overwritten.');
end $$;

revoke all on function tonde_private.lf_blockers(uuid,uuid,tonde.generate_depth),
  tonde_private.lf_generate_plan(uuid,tonde.series,jsonb) from public, anon, authenticated, service_role;


-- 17. Series RPCs.
create or replace function tonde.create_series(target_workspace uuid, target_project uuid, series jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare created tonde.series; title_value text; kind_value text; tz_value text;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(series) <> 'object' then raise exception 'Invalid Series payload' using errcode = '22023'; end if;
  if not exists(select 1 from tonde.projects p where p.workspace_id = target_workspace and p.id = target_project
    and p.lifecycle = 'active') then raise exception 'Project unavailable' using errcode = 'P0002'; end if;
  title_value := btrim(coalesce(series->>'title',''));
  if length(title_value) = 0 or length(title_value) > 160 then
    raise exception 'A Series needs a title of 1 to 160 characters' using errcode = '22023';
  end if;
  kind_value := coalesce(nullif(series->>'series_kind',''), 'recurring');
  if kind_value not in ('narrative','recurring') then raise exception 'Series kind must be narrative or recurring' using errcode = '22023'; end if;
  tz_value := btrim(coalesce(nullif(series->>'timezone',''), 'UTC'));
  if length(tz_value) = 0 or length(tz_value) > 60 then raise exception 'A Series needs a timezone' using errcode = '22023'; end if;
  if coalesce(series->'format','{}'::jsonb) is not null and jsonb_typeof(coalesce(series->'format','{}'::jsonb)) <> 'object' then
    raise exception 'Invalid Series format' using errcode = '22023';
  end if;
  insert into tonde.series(workspace_id, project_id, title, series_kind, format, timezone, cadence_metadata)
  values (target_workspace, target_project, left(title_value,160), kind_value::tonde.series_kind,
    coalesce(series->'format','{}'::jsonb), tz_value, coalesce(series->'cadence_metadata','{}'::jsonb))
  returning * into created;
  return jsonb_build_object('series_id', created.id, 'title', created.title, 'series_kind', created.series_kind,
    'timezone', created.timezone, 'revision', created.revision,
    'cadence_metadata', created.cadence_metadata, 'format', created.format);
end $$;


create or replace function tonde.update_series(target_workspace uuid, target_series uuid, expected_revision integer, patch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare current tonde.series; updated tonde.series; title_value text; tz_value text; lifecycle_value text;
begin
  if jsonb_typeof(patch) <> 'object' then raise exception 'Invalid Series patch' using errcode = '22023'; end if;
  current := tonde_private.lf_series_revision_guard(target_workspace, target_series, expected_revision);
  title_value := current.title;
  if patch ? 'title' then
    title_value := btrim(coalesce(patch->>'title',''));
    if length(title_value) = 0 or length(title_value) > 160 then
      raise exception 'A Series needs a title of 1 to 160 characters' using errcode = '22023';
    end if;
  end if;
  tz_value := current.timezone;
  if patch ? 'timezone' then
    tz_value := btrim(coalesce(nullif(patch->>'timezone',''), 'UTC'));
    if length(tz_value) = 0 or length(tz_value) > 60 then raise exception 'A Series needs a timezone' using errcode = '22023'; end if;
  end if;
  lifecycle_value := current.lifecycle::text;
  if patch ? 'lifecycle' then
    lifecycle_value := coalesce(nullif(patch->>'lifecycle',''), 'active');
    if lifecycle_value not in ('active','archived') then raise exception 'Series archive rather than delete' using errcode = '22023'; end if;
  end if;
  if patch ? 'series_kind' and coalesce(nullif(patch->>'series_kind',''),'recurring') not in ('narrative','recurring') then
    raise exception 'Series kind must be narrative or recurring' using errcode = '22023';
  end if;
  update tonde.series set title = title_value, timezone = tz_value, lifecycle = lifecycle_value::tonde.lifecycle,
    series_kind = case when patch ? 'series_kind' then coalesce(nullif(patch->>'series_kind',''),'recurring')::tonde.series_kind else series_kind end,
    format = case when patch ? 'format' then coalesce(patch->'format','{}'::jsonb) else format end,
    cadence_metadata = case when patch ? 'cadence_metadata' then coalesce(patch->'cadence_metadata','{}'::jsonb) else cadence_metadata end,
    summary = case when patch ? 'summary' then coalesce(patch->'summary','{}'::jsonb) else summary end,
    bible_document_id = case when patch ? 'bible_document_id' then nullif(coalesce(patch->>'bible_document_id',''),'')::uuid else bible_document_id end
  where workspace_id = target_workspace and id = target_series returning * into updated;
  return jsonb_build_object('series_id', updated.id, 'revision', updated.revision, 'title', updated.title,
    'series_kind', updated.series_kind, 'timezone', updated.timezone, 'lifecycle', updated.lifecycle,
    'cadence_metadata', updated.cadence_metadata, 'format', updated.format);
end $$;


create or replace function tonde.save_series_collection(target_workspace uuid, target_series uuid, collection jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare created tonde.series_collections; title_value text; target uuid; next_order bigint;
begin
  perform tonde_private.director_guard(target_workspace);
  perform tonde_private.lf_series_for(target_workspace, target_series);
  if jsonb_typeof(collection) <> 'object' then raise exception 'Invalid Collection payload' using errcode = '22023'; end if;
  title_value := btrim(coalesce(collection->>'title',''));
  if length(title_value) = 0 or length(title_value) > 160 then
    raise exception 'A Season or Collection needs a title of 1 to 160 characters' using errcode = '22023';
  end if;
  target := nullif(coalesce(collection->>'collection_id',''),'')::uuid;
  if target is null then
    select coalesce(max(c.sort_order), 0) + 1024 into next_order from tonde.series_collections c
      where c.workspace_id = target_workspace and c.series_id = target_series;
    insert into tonde.series_collections(workspace_id, series_id, title, purpose, sort_order)
    values (target_workspace, target_series, left(title_value,160), left(coalesce(collection->>'purpose',''),1200), next_order)
    returning * into created;
  else
    update tonde.series_collections set title = left(title_value,160),
      purpose = case when collection ? 'purpose' then left(coalesce(collection->>'purpose',''),1200) else purpose end,
      lifecycle = case when collection ? 'lifecycle' then coalesce(nullif(collection->>'lifecycle',''),'active')::tonde.lifecycle else lifecycle end
    where workspace_id = target_workspace and series_id = target_series and id = target
    returning * into created;
    if not found then raise exception 'Collection unavailable' using errcode = 'P0002'; end if;
  end if;
  return jsonb_build_object('collection_id', created.id, 'title', created.title, 'sort_order', created.sort_order,
    'lifecycle', created.lifecycle, 'revision', created.revision);
end $$;


create or replace function tonde.series_overview(target_workspace uuid, target_series uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare series_row tonde.series; collections jsonb; counts jsonb; reuse jsonb; upcoming jsonb; last_job jsonb;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  select coalesce(jsonb_agg(jsonb_build_object('collection_id', c.id, 'title', c.title, 'purpose', c.purpose,
      'sort_order', c.sort_order, 'lifecycle', c.lifecycle,
      'episodes', (select count(*) from tonde.series_episodes e where e.workspace_id = target_workspace
        and e.collection_id = c.id and e.lifecycle = 'active')) order by c.sort_order, c.id), '[]'::jsonb)
    into collections from tonde.series_collections c
  where c.workspace_id = target_workspace and c.series_id = target_series;
  select jsonb_build_object(
    'episodes_active', (select count(*) from tonde.series_episodes e where e.workspace_id = target_workspace
      and e.series_id = target_series and e.lifecycle = 'active'),
    'episodes_archived', (select count(*) from tonde.series_episodes e where e.workspace_id = target_workspace
      and e.series_id = target_series and e.lifecycle <> 'active'),
    'collections', (select count(*) from tonde.series_collections c where c.workspace_id = target_workspace
      and c.series_id = target_series),
    'planned_episodes', nullif(series_row.format->>'planned_episodes',''),
    'next_episode_number', (select coalesce(max(e.episode_number), 0) + 1 from tonde.series_episodes e
      where e.workspace_id = target_workspace and e.series_id = target_series)) into counts;
  select coalesce(jsonb_agg(jsonb_build_object('asset_id', a.id, 'name', a.name, 'asset_type', a.asset_type,
      'missing', false) order by a.name), '[]'::jsonb) into reuse
  from tonde.assets a where a.workspace_id = target_workspace and a.id in (
    select nullif(series_row.format->>'style_bible_id','')::uuid
    union all select nullif(series_row.format->>'host_asset_id','')::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'character_ids','[]'::jsonb))::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'environment_ids','[]'::jsonb))::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'product_ids','[]'::jsonb))::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'wardrobe_ids','[]'::jsonb))::uuid
    union all select jsonb_array_elements_text(coalesce(series_row.format->'prop_ids','[]'::jsonb))::uuid);
  select coalesce(jsonb_agg(jsonb_build_object('episode_id', e.id, 'episode_number', e.episode_number,
      'title', e.title, 'planned_date', e.planned_date, 'production_id', e.production_id,
      'production_line_state', tonde_private.lf_line_state(target_workspace, e.production_id),
      'depth', tonde_private.lf_depth(target_workspace, e.production_id, 'production', e.production_id))
      order by e.planned_date nulls last, e.episode_number), '[]'::jsonb) into upcoming
  from (select * from tonde.series_episodes e where e.workspace_id = target_workspace and e.series_id = target_series
    and e.lifecycle = 'active' order by coalesce(e.planned_date, '9999-12-31'::date), e.episode_number limit 10) e;
  select jsonb_build_object('job_id', j.id, 'state', j.state, 'horizon', j.horizon, 'depth', j.depth,
      'created_count', j.created_count, 'preserved_count', j.preserved_count, 'blocked_count', j.blocked_count,
      'failed_count', j.failed_count, 'created_at', j.created_at)
    into last_job from tonde.generate_ahead_jobs j
    where j.workspace_id = target_workspace and j.series_id = target_series order by j.created_at desc limit 1;
  return jsonb_build_object('series_id', series_row.id, 'title', series_row.title, 'series_kind', series_row.series_kind,
    'timezone', series_row.timezone, 'lifecycle', series_row.lifecycle, 'revision', series_row.revision,
    'cadence_metadata', series_row.cadence_metadata, 'format', series_row.format, 'summary', series_row.summary,
    'bible_document_id', series_row.bible_document_id, 'collections', collections, 'counts', counts,
    'reuse', reuse, 'upcoming', upcoming, 'last_generate_ahead', last_job,
    'note', 'Recurring context is referenced, never copied: each Episode stays its own canonical Production.');
end $$;


create or replace function tonde_private.lf_new_shell(target_workspace uuid, series_row tonde.series, title text,
  runtime_target_ms bigint) returns uuid language plpgsql security definer set search_path = '' as $$
declare prod uuid; type_value text; method_value text; format jsonb := coalesce(series_row.format, '{}'::jsonb);
begin
  type_value := coalesce(nullif(format->>'production_type',''), 'recurring_content');
  if not (type_value = any(enum_range(null::tonde.production_type)::text[])) then
    raise exception 'Unsupported Series production type' using errcode = '22023';
  end if;
  method_value := coalesce(nullif(format->>'execution_method',''), 'real');
  if method_value not in ('real','ai','hybrid') then
    raise exception 'Series execution method must be real, ai or hybrid' using errcode = '22023';
  end if;
  if runtime_target_ms is null then
    runtime_target_ms := tonde_private.lf_ms(format, 'runtime_target_ms');
  end if;
  insert into tonde.productions(workspace_id, project_id, title, production_type, execution_method,
    planned_duration_ms, created_by)
  values (target_workspace, series_row.project_id, left(title,160), type_value::tonde.production_type,
    method_value::tonde.execution_method, runtime_target_ms, auth.uid()) returning id into prod;
  perform tonde_private.lf_inherit_series_context(target_workspace, series_row, prod);
  return prod;
end $$;

revoke all on function tonde_private.lf_new_shell(uuid,tonde.series,text,bigint) from public, anon, authenticated, service_role;


create or replace function tonde.create_series_episode(target_workspace uuid, target_series uuid, episode jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare series_row tonde.series; created tonde.series_episodes; prod uuid; title_value text;
  number_value bigint; slot_value text; existing uuid; runtime_value bigint; topic text; note text;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(episode) <> 'object' then raise exception 'Invalid Episode payload' using errcode = '22023'; end if;
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  if series_row.lifecycle <> 'active' then raise exception 'This Series is archived' using errcode = '23514'; end if;
  slot_value := nullif(btrim(coalesce(episode->>'slot_key','')), '');
  if slot_value is not null then
    select e.id into existing from tonde.series_episodes e where e.workspace_id = target_workspace
      and e.series_id = target_series and e.slot_key = slot_value limit 1;
    if existing is not null then
      select * into created from tonde.series_episodes where id = existing;
      return jsonb_build_object('episode_id', created.id, 'created', false, 'state', 'preserved',
        'production_id', created.production_id, 'episode_number', created.episode_number,
        'note', 'An Episode already occupies this slot, so nothing was overwritten.');
    end if;
  end if;
  topic := nullif(btrim(coalesce(episode->>'topic','')), '');
  note := left(coalesce(episode->>'note',''), 400);
  runtime_value := tonde_private.lf_ms(episode, 'runtime_target_ms');
  prod := nullif(coalesce(episode->>'production_id',''),'')::uuid;
  if prod is null then
    title_value := tonde_private.lf_episode_title(series_row, nullif(coalesce(episode->>'planned_date',''),'')::date,
      coalesce(nullif(coalesce(episode->>'episode_number',''),'')::bigint,
        (select coalesce(max(e.episode_number), 0) + 1 from tonde.series_episodes e
          where e.workspace_id = target_workspace and e.series_id = target_series)), topic);
    if coalesce(episode->>'title','') <> '' then title_value := left(btrim(episode->>'title'), 160); end if;
    prod := tonde_private.lf_new_shell(target_workspace, series_row, title_value, runtime_value);
  else
    if not exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = prod
      and p.project_id = series_row.project_id) then
      raise exception 'Episode Production must belong to the Series project' using errcode = '23514';
    end if;
    title_value := left(coalesce(nullif(btrim(coalesce(episode->>'title','')),''), series_row.title), 160);
  end if;
  number_value := nullif(coalesce(episode->>'episode_number',''),'')::bigint;
  if number_value is null then
    select coalesce(max(e.episode_number), 0) + 1 into number_value from tonde.series_episodes e
      where e.workspace_id = target_workspace and e.series_id = target_series;
  end if;
  insert into tonde.series_episodes(workspace_id, series_id, collection_id, production_id, episode_number,
    planned_date, runtime_target_ms, title, slot_key, requested_depth, brief)
  values (target_workspace, target_series, nullif(coalesce(episode->>'collection_id',''),'')::uuid, prod,
    number_value, nullif(coalesce(episode->>'planned_date',''),'')::date, runtime_value, title_value, slot_value,
    case when coalesce(episode->>'requested_depth','') = '' then null
      else (episode->>'requested_depth')::tonde.generate_depth end,
    jsonb_build_object('topic', topic, 'note', note))
  returning * into created;
  return jsonb_build_object('episode_id', created.id, 'created', true, 'state', 'created',
    'production_id', created.production_id, 'episode_number', created.episode_number, 'title', created.title,
    'planned_date', created.planned_date, 'requested_depth', created.requested_depth);
end $$;


create or replace function tonde.update_series_episode(target_workspace uuid, target_series uuid, target_episode uuid,
  expected_revision integer, patch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare series_row tonde.series; current tonde.series_episodes; updated tonde.series_episodes; title_value text;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(patch) <> 'object' then raise exception 'Invalid Episode patch' using errcode = '22023'; end if;
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  select * into current from tonde.series_episodes where workspace_id = target_workspace and series_id = target_series
    and id = target_episode;
  if not found then raise exception 'Episode unavailable' using errcode = 'P0002'; end if;
  if current.locked_at is not null then raise exception 'Unlock this Episode before editing' using errcode = '23514'; end if;
  if expected_revision is not null and current.revision <> expected_revision then
    raise exception 'The Episode changed since you loaded it' using errcode = '40001';
  end if;
  title_value := current.title;
  if patch ? 'title' then
    title_value := btrim(coalesce(patch->>'title',''));
    if length(title_value) = 0 or length(title_value) > 160 then
      raise exception 'An Episode title is 1 to 160 characters' using errcode = '22023';
    end if;
  end if;
  update tonde.series_episodes set title = title_value,
    planned_date = case when patch ? 'planned_date' then nullif(coalesce(patch->>'planned_date',''),'')::date else planned_date end,
    runtime_target_ms = case when patch ? 'runtime_target_ms' then tonde_private.lf_ms(patch, 'runtime_target_ms') else runtime_target_ms end,
    collection_id = case when patch ? 'collection_id' then nullif(coalesce(patch->>'collection_id',''),'')::uuid else collection_id end,
    slot_key = case when patch ? 'slot_key' then nullif(btrim(coalesce(patch->>'slot_key','')),'') else slot_key end,
    requested_depth = case when patch ? 'requested_depth' then
      case when coalesce(patch->>'requested_depth','') = '' then null else (patch->>'requested_depth')::tonde.generate_depth end
      else requested_depth end,
    brief = case when patch ? 'brief' then coalesce(patch->'brief','{}'::jsonb) else brief end,
    episode_number = case when patch ? 'episode_number' then coalesce(nullif(patch->>'episode_number','')::bigint, episode_number) else episode_number end,
    lifecycle = case when patch ? 'lifecycle' then coalesce(nullif(patch->>'lifecycle',''),'active')::tonde.lifecycle else lifecycle end
  where workspace_id = target_workspace and series_id = target_series and id = target_episode
  returning * into updated;
  return jsonb_build_object('episode_id', updated.id, 'revision', updated.revision, 'title', updated.title,
    'episode_number', updated.episode_number, 'planned_date', updated.planned_date,
    'requested_depth', updated.requested_depth, 'lifecycle', updated.lifecycle,
    'production_line_state', tonde_private.lf_line_state(target_workspace, updated.production_id));
end $$;


create or replace function tonde.series_slots(target_workspace uuid, target_series uuid, target_horizon tonde.generate_horizon,
  requested_count integer default 0, base_date date default null, hold_slots text[] default '{}'::text[])
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare series_row tonde.series; slots jsonb; counts jsonb;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  select coalesce(jsonb_agg(jsonb_build_object('slot_key', s.out_slot_key, 'planned_date', s.out_planned_date,
      'episode_number', s.out_episode_number,
      'state', case when s.out_occupancy = 'occupied' then 'preserved'
        when s.out_slot_key = any(coalesce(hold_slots,'{}'::text[])) then 'held' else 'open' end,
      'existing_episode_id', s.out_existing_episode_id)
      order by s.out_planned_date nulls last, s.out_episode_number), '[]'::jsonb),
    jsonb_build_object('open', count(*) filter (where s.out_occupancy = 'open'
        and not (s.out_slot_key = any(coalesce(hold_slots,'{}'::text[])))),
      'preserved', count(*) filter (where s.out_occupancy = 'occupied'),
      'held', count(*) filter (where s.out_occupancy = 'open' and s.out_slot_key = any(coalesce(hold_slots,'{}'::text[]))),
      'total', count(*)) into slots, counts
  from tonde_private.lf_slots(target_workspace, target_series, target_horizon, requested_count, base_date) s;
  return jsonb_build_object('horizon', target_horizon, 'timezone', series_row.timezone,
    'today', (now() at time zone series_row.timezone)::date, 'slots', slots, 'counts', counts,
    'cadence_metadata', series_row.cadence_metadata,
    'note', 'Slot dates come from the Series timezone and cadence, never from server UTC.');
end $$;


create or replace function tonde.generate_ahead_preview(target_workspace uuid, target_series uuid, request jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare series_row tonde.series; plan jsonb; jobs jsonb;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  plan := tonde_private.lf_generate_plan(target_workspace, series_row, coalesce(request, '{}'::jsonb));
  select coalesce(jsonb_agg(jsonb_build_object('job_id', j.id, 'state', j.state, 'created_count', j.created_count,
      'preserved_count', j.preserved_count, 'blocked_count', j.blocked_count, 'failed_count', j.failed_count,
      'created_at', j.created_at) order by j.created_at desc), '[]'::jsonb) into jobs
  from (select * from tonde.generate_ahead_jobs j where j.workspace_id = target_workspace and j.series_id = target_series
    order by j.created_at desc limit 3) j;
  return plan || jsonb_build_object('recent_jobs', jobs,
    'series_revision', series_row.revision,
    'note', 'Preview only: nothing was created. Existing Episodes are preserved, held slots are skipped.');
end $$;


create or replace function tonde.generate_ahead(target_workspace uuid, target_series uuid, request jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare series_row tonde.series; plan jsonb; horizon tonde.generate_horizon; depth tonde.generate_depth;
  holds text[]; topics text[]; slot record; item_id uuid; prod uuid; episode uuid; title_value text;
  topic_value text; made integer := 0; kept integer := 0; held integer := 0;
  broke integer := 0; index_value integer := 0; job uuid; shared_job uuid; tz_value text;
  base date; count_value integer; created_episodes jsonb := '[]'::jsonb; blocked_slots jsonb := '[]'::jsonb;
  state_value tonde.job_state; progress_value integer;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(request) <> 'object' then raise exception 'Invalid Generate Ahead request' using errcode = '22023'; end if;
  if not coalesce((request->>'confirm')::boolean, false) then
    raise exception 'Generate Ahead needs explicit creator confirmation' using errcode = '22023';
  end if;
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  if series_row.lifecycle <> 'active' then raise exception 'This Series is archived' using errcode = '23514'; end if;
  if series_row.revision <> coalesce((request->>'expected_series_revision')::integer, series_row.revision) then
    raise exception 'The Series changed since you loaded it' using errcode = '40001';
  end if;
  plan := tonde_private.lf_generate_plan(target_workspace, series_row, request);
  horizon := (plan->>'horizon')::tonde.generate_horizon;
  depth := (plan->>'depth')::tonde.generate_depth;
  holds := coalesce(array(select jsonb_array_elements_text(coalesce(request->'hold_slots','[]'::jsonb))), '{}'::text[]);
  topics := coalesce(array(select jsonb_array_elements_text(coalesce(request->'topics','[]'::jsonb))), '{}'::text[]);
  tz_value := series_row.timezone;
  base := nullif(request->>'base_date','')::date;
  count_value := coalesce(nullif(request->>'count','')::integer, 0);
  insert into tonde.jobs(workspace_id, job_type, status, progress, input_metadata, requested_by,
    started_at, lease_owner, lease_expires_at)
  values (target_workspace, 'long_form_generation', 'running', 0,
    jsonb_build_object('series_id', target_series, 'horizon', horizon, 'depth', depth), auth.uid(),
    now(), 'tonde:long_form_generation', now() + interval '1 hour')
  returning id into shared_job;
  insert into tonde.generate_ahead_jobs(workspace_id, series_id, job_id, horizon, depth, requested_count,
    base_date, timezone, state, preview)
  values (target_workspace, target_series, shared_job, horizon, depth, count_value, base, tz_value, 'running', plan)
  returning id into job;
  for slot in select * from tonde_private.lf_slots(target_workspace, target_series, horizon, count_value, base)
    order by out_planned_date nulls last, out_episode_number
  loop
    insert into tonde.generate_ahead_items(workspace_id, job_id, slot_key, planned_date, episode_number, state)
    values (target_workspace, job, slot.out_slot_key, slot.out_planned_date, slot.out_episode_number, 'pending')
    returning id into item_id;
    if slot.out_occupancy = 'occupied' then
      update tonde.generate_ahead_items set state = 'preserved', created_episode_id = slot.out_existing_episode_id
        where id = item_id;
      kept := kept + 1;
      continue;
    end if;
    if slot.out_slot_key = any(holds) then
      update tonde.generate_ahead_items set state = 'blocked', error_code = 'held_by_creator',
        error_message = 'This slot is held by the creator.' where id = item_id;
      held := held + 1;
      blocked_slots := blocked_slots || jsonb_build_array(slot.out_slot_key);
      continue;
    end if;
    begin
      index_value := index_value + 1;
      topic_value := case when coalesce(array_length(topics, 1), 0) >= index_value then topics[index_value] else null end;
      title_value := tonde_private.lf_episode_title(series_row, slot.out_planned_date, slot.out_episode_number, topic_value);
      prod := tonde_private.lf_new_shell(target_workspace, series_row, title_value,
        tonde_private.lf_ms(coalesce(series_row.format,'{}'::jsonb), 'runtime_target_ms'));
      insert into tonde.series_episodes(workspace_id, series_id, collection_id, production_id, episode_number,
        planned_date, runtime_target_ms, title, slot_key, requested_depth, brief)
      values (target_workspace, target_series, nullif(coalesce(request->>'collection_id',''),'')::uuid, prod,
        slot.out_episode_number, slot.out_planned_date,
        tonde_private.lf_ms(coalesce(series_row.format,'{}'::jsonb), 'runtime_target_ms'), title_value,
        slot.out_slot_key, depth,
        jsonb_build_object('topic', topic_value, 'note', left(coalesce(request->>'note',''),400),
          'source', 'generate_ahead'))
      returning id into episode;
      update tonde.generate_ahead_items set state = 'created', created_production_id = prod,
        created_episode_id = episode where id = item_id;
      made := made + 1;
      created_episodes := created_episodes || jsonb_build_array(jsonb_build_object('episode_id', episode,
        'episode_number', slot.out_episode_number, 'production_id', prod, 'title', title_value,
        'planned_date', slot.out_planned_date, 'slot_key', slot.out_slot_key, 'topic_source',
        case when topic_value is null then 'title_pattern' else 'creator_topic' end));
    exception when others then
      update tonde.generate_ahead_items set state = 'failed', error_code = left(sqlstate, 40),
        error_message = left(sqlerrm, 400) where id = item_id;
      broke := broke + 1;
    end;
  end loop;
  state_value := (case when broke > 0 or held > 0 then 'retrying' else 'succeeded' end)::tonde.job_state;
  progress_value := least(100, ((made + kept + held + broke) * 100)
    / greatest((plan->'counts'->>'total')::integer, 1));
  update tonde.generate_ahead_jobs set state = state_value, created_count = made,
    preserved_count = kept, blocked_count = held, failed_count = broke,
    note = case when broke > 0 then 'Some slots failed and can be retried without touching created Episodes.'
      when held > 0 then 'Some slots are held by the creator and were skipped.'
      else 'Every open slot was created.' end
    where id = job;
  update tonde.jobs set status = (case when broke > 0 then 'failed' else 'succeeded' end)::tonde.job_state,
    progress = case when broke > 0 then progress_value else 100 end,
    completed_at = now(), lease_owner = null, lease_expires_at = null where id = shared_job;
  return jsonb_build_object('job_id', job, 'shared_job_id', shared_job, 'state', state_value,
    'horizon', horizon, 'depth', depth, 'timezone', tz_value,
    'counts', jsonb_build_object('created', made, 'preserved', kept, 'blocked', held,
      'failed', broke, 'planned', (plan->'counts'->>'total')::integer),
    'created_episodes', created_episodes, 'blocked_slots', blocked_slots,
    'preview', plan,
    'note', 'Existing Episodes and approved work were preserved. Retry only touches blocked or failed slots.');
end $$;


create or replace function tonde.retry_generate_ahead(target_workspace uuid, target_job uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare job_row tonde.generate_ahead_jobs; series_row tonde.series; item record; prod uuid; episode uuid;
  title_value text; made integer := 0; kept integer := 0;
  broke integer := 0; held integer := 0; state_value tonde.job_state;
begin
  perform tonde_private.director_guard(target_workspace);
  select * into job_row from tonde.generate_ahead_jobs where workspace_id = target_workspace and id = target_job;
  if not found then raise exception 'Generate Ahead job unavailable' using errcode = 'P0002'; end if;
  series_row := tonde_private.lf_series_for(target_workspace, job_row.series_id);
  for item in select * from tonde.generate_ahead_items i where i.workspace_id = target_workspace
    and i.job_id = target_job and i.state in ('blocked','failed') order by i.planned_date nulls last, i.episode_number
  loop
    if exists(select 1 from tonde.series_episodes e where e.workspace_id = target_workspace
      and e.series_id = job_row.series_id and (e.slot_key = item.slot_key
        or (item.planned_date is not null and e.planned_date = item.planned_date))) then
      update tonde.generate_ahead_items set state = 'preserved', error_code = null, error_message = null
        where id = item.id;
      kept := kept + 1;
      continue;
    end if;
    if item.state = 'blocked' then
      held := held + 1;
      continue;
    end if;
    begin
      -- A retry rebuilds the title from the Series title pattern: the original topic is not
      -- re-invented, and nothing about the already-created Episodes is touched.
      title_value := tonde_private.lf_episode_title(series_row, item.planned_date, item.episode_number, null);
      prod := tonde_private.lf_new_shell(target_workspace, series_row, title_value,
        tonde_private.lf_ms(coalesce(series_row.format,'{}'::jsonb), 'runtime_target_ms'));
      insert into tonde.series_episodes(workspace_id, series_id, production_id, episode_number, planned_date,
        runtime_target_ms, title, slot_key, requested_depth, brief)
      values (target_workspace, job_row.series_id, prod, item.episode_number, item.planned_date,
        tonde_private.lf_ms(coalesce(series_row.format,'{}'::jsonb), 'runtime_target_ms'), title_value,
        item.slot_key, job_row.depth, jsonb_build_object('source','generate_ahead_retry'))
      returning id into episode;
      update tonde.generate_ahead_items set state = 'created', created_production_id = prod,
        created_episode_id = episode, error_code = null, error_message = null where id = item.id;
      made := made + 1;
    exception when others then
      update tonde.generate_ahead_items set state = 'failed', error_code = left(sqlstate, 40),
        error_message = left(sqlerrm, 400) where id = item.id;
      broke := broke + 1;
    end;
  end loop;
  state_value := (case when broke > 0 or held > 0 then 'retrying' else 'succeeded' end)::tonde.job_state;
  update tonde.generate_ahead_jobs set state = state_value,
    created_count = (select count(*) from tonde.generate_ahead_items i
      where i.job_id = target_job and i.state = 'created'),
    preserved_count = (select count(*) from tonde.generate_ahead_items i
      where i.job_id = target_job and i.state = 'preserved'),
    blocked_count = (select count(*) from tonde.generate_ahead_items i where i.job_id = target_job and i.state = 'blocked'),
    failed_count = (select count(*) from tonde.generate_ahead_items i where i.job_id = target_job and i.state = 'failed')
    where id = target_job;
  return jsonb_build_object('job_id', target_job, 'state', state_value,
    'counts', jsonb_build_object('created', made, 'preserved', kept,
      'blocked', held, 'failed', broke),
    'note', 'Only blocked and failed slots were retried. Already created Episodes were untouched.');
end $$;


create or replace function tonde.generate_ahead_jobs(target_workspace uuid, target_series uuid, target_limit integer default 10)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare items jsonb;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  perform tonde_private.lf_series_for(target_workspace, target_series);
  select coalesce(jsonb_agg(jsonb_build_object('job_id', j.id, 'shared_job_id', j.job_id, 'state', j.state,
      'horizon', j.horizon, 'depth', j.depth, 'timezone', j.timezone, 'created_at', j.created_at,
      'created_count', j.created_count, 'preserved_count', j.preserved_count, 'blocked_count', j.blocked_count,
      'failed_count', j.failed_count, 'note', j.note,
      'items', (select coalesce(jsonb_agg(jsonb_build_object('slot_key', i.slot_key, 'planned_date', i.planned_date,
          'episode_number', i.episode_number, 'state', i.state, 'created_production_id', i.created_production_id,
          'created_episode_id', i.created_episode_id, 'error_message', i.error_message)
          order by i.planned_date nulls last, i.episode_number), '[]'::jsonb)
        from tonde.generate_ahead_items i where i.workspace_id = target_workspace and i.job_id = j.id))
      order by j.created_at desc), '[]'::jsonb) into items
  from (select * from tonde.generate_ahead_jobs j where j.workspace_id = target_workspace and j.series_id = target_series
    order by j.created_at desc limit least(greatest(coalesce(target_limit, 10), 1), 50)) j;
  return jsonb_build_object('jobs', items);
end $$;


-- Production Line: real production stages from real domain state, and no vanity percentage.
create or replace function tonde.series_production_line(target_workspace uuid, target_series uuid,
  target_limit integer default 30, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  perform tonde_private.lf_series_for(target_workspace, target_series);
  select b.out_limit, b.out_offset into lim, off from tonde_private.lf_bounded(target_limit, target_offset) b;
  select coalesce(jsonb_agg(jsonb_build_object('episode_id', e.id, 'episode_number', e.episode_number,
      'title', e.title, 'planned_date', e.planned_date, 'production_id', e.production_id,
      'production_title', p.title, 'lifecycle', e.lifecycle, 'production_lifecycle', p.lifecycle,
      'requested_depth', e.requested_depth, 'depth', tonde_private.lf_depth(target_workspace, e.production_id, 'production', e.production_id),
      'line_state', tonde_private.lf_line_state(target_workspace, e.production_id),
      'approval', p.approval, 'locked', p.locked_at is not null, 'production_revision', p.revision,
      'episode_revision', e.revision,
      'collection_id', e.collection_id,
      'execution_summary', jsonb_build_object(
        'real', (select count(*) from tonde.shots h where h.workspace_id = target_workspace
          and h.production_id = e.production_id and h.lifecycle = 'active' and h.execution_method = 'real'),
        'ai', (select count(*) from tonde.shots h where h.workspace_id = target_workspace
          and h.production_id = e.production_id and h.lifecycle = 'active' and h.execution_method = 'ai'),
        'hybrid', (select count(*) from tonde.shots h where h.workspace_id = target_workspace
          and h.production_id = e.production_id and h.lifecycle = 'active' and h.execution_method = 'hybrid')),
      'timing', jsonb_build_object('production', tonde_private.lf_production_timing(target_workspace, e.production_id)->'production',
        'counts', tonde_private.lf_production_timing(target_workspace, e.production_id)->'counts'),
      'blockers', tonde_private.lf_blockers(target_workspace, e.production_id, e.requested_depth),
      'readiness', jsonb_build_object(
        'blocking', (select count(*) from jsonb_array_elements(tonde_private.lf_blockers(target_workspace, e.production_id, e.requested_depth)) b
          where b->>'severity' = 'blocking'),
        'warnings', (select count(*) from jsonb_array_elements(tonde_private.lf_blockers(target_workspace, e.production_id, e.requested_depth)) b
          where b->>'severity' = 'warning'),
        'state', case
          when (select count(*) from jsonb_array_elements(tonde_private.lf_blockers(target_workspace, e.production_id, e.requested_depth)) b
            where b->>'severity' = 'blocking') > 0 then 'BLOCKED'
          when p.approval in ('needs_review','changed_after_approval') then 'NEEDS REVIEW'
          when (select count(*) from jsonb_array_elements(tonde_private.lf_blockers(target_workspace, e.production_id, e.requested_depth)) b
            where b->>'severity' = 'warning') > 0 then 'READY WITH WARNINGS'
          else 'READY' end))
      order by e.planned_date nulls last, e.episode_number), '[]'::jsonb), count(*)
    into items, total
  from (select * from tonde.series_episodes e where e.workspace_id = target_workspace and e.series_id = target_series
    and e.lifecycle = 'active' order by coalesce(e.planned_date, '9999-12-31'::date), e.episode_number
    limit lim offset off) e
  join tonde.productions p on p.workspace_id = e.workspace_id and p.id = e.production_id;
  return jsonb_build_object('items', items, 'total', coalesce(total,0), 'limit', lim, 'offset', off,
    'truncated', coalesce(total,0) > off + jsonb_array_length(items),
    'note', 'States come from real domain state (documents, Scenes, Shots, plans, captures, Results, approval). No percentage is invented.');
end $$;


create or replace function tonde.series_director_context(target_workspace uuid, target_series uuid, target_limit integer default 10)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare series_row tonde.series; recent jsonb; upcoming jsonb; lim integer;
begin
  perform tonde_private.lf_read_guard(target_workspace);
  series_row := tonde_private.lf_series_for(target_workspace, target_series);
  lim := least(greatest(coalesce(target_limit, 10), 1), 30);
  select coalesce(jsonb_agg(jsonb_build_object('episode_number', e.episode_number, 'title', e.title,
      'planned_date', e.planned_date, 'line_state', tonde_private.lf_line_state(target_workspace, e.production_id))
      order by e.episode_number desc), '[]'::jsonb) into recent
  from (select * from tonde.series_episodes e where e.workspace_id = target_workspace and e.series_id = target_series
    order by e.episode_number desc limit lim) e;
  select coalesce(jsonb_agg(jsonb_build_object('episode_number', e.episode_number, 'title', e.title,
      'planned_date', e.planned_date, 'state', tonde_private.lf_line_state(target_workspace, e.production_id))
      order by e.episode_number), '[]'::jsonb) into upcoming
  from (select * from tonde.series_episodes e where e.workspace_id = target_workspace and e.series_id = target_series
    and e.planned_date >= (now() at time zone series_row.timezone)::date order by e.planned_date limit lim) e;
  return jsonb_build_object('series_id', series_row.id, 'title', series_row.title,
    'series_kind', series_row.series_kind, 'timezone', series_row.timezone,
    'cadence_metadata', series_row.cadence_metadata, 'format_metadata_keys',
      coalesce((select jsonb_agg(key) from jsonb_object_keys(coalesce(series_row.format,'{}'::jsonb)) as key), '[]'::jsonb),
    'recent_titles', recent, 'upcoming', upcoming,
    'avoid_list', coalesce((select jsonb_agg(value->>'title') from jsonb_array_elements(recent) as value), '[]'::jsonb),
    'note', 'Bounded Series context: titles, dates and states only. No full historical Scripts or Story text.');
end $$;


-- 18. RLS. Every new workspace-owned table is isolated; enabling RLS is not optional.
do $$ declare item text; begin
  foreach item in array array['structure_summaries','generate_ahead_jobs','generate_ahead_items'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select, insert, update on tonde.%I to authenticated', item);
  end loop;
end $$;


-- 19. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.long_form_structure(uuid,uuid,tonde.structure_level,uuid,integer,integer,integer),
  tonde.long_form_timing(uuid,uuid,integer),
  tonde.long_form_search(uuid,uuid,text,jsonb,integer,integer),
  tonde.long_form_summaries(uuid,uuid,integer,integer),
  tonde.long_form_script_index(uuid,uuid,integer,integer),
  tonde.long_form_context(uuid,uuid,tonde.structure_level,uuid,integer),
  tonde.save_structure_summary(uuid,uuid,tonde.structure_level,uuid,jsonb,integer,text,text),
  tonde.create_long_form_act(uuid,uuid,integer,jsonb),
  tonde.update_long_form_act(uuid,uuid,uuid,integer,jsonb),
  tonde.create_long_form_sequence(uuid,uuid,integer,jsonb),
  tonde.update_long_form_sequence(uuid,uuid,uuid,integer,jsonb),
  tonde.move_long_form_scene(uuid,uuid,uuid,integer,uuid,uuid),
  tonde.move_long_form_sequence(uuid,uuid,uuid,integer,uuid),
  tonde.split_long_form_structure(uuid,uuid,tonde.structure_level,uuid,bigint,integer,text),
  tonde.reorder_long_form(uuid,uuid,tonde.structure_level,uuid[],integer,uuid),
  tonde.set_long_form_approval(uuid,uuid,tonde.structure_level,uuid,text,integer),
  tonde.set_long_form_lock(uuid,uuid,tonde.structure_level,uuid,boolean,integer),
  tonde.create_series(uuid,uuid,jsonb),
  tonde.update_series(uuid,uuid,integer,jsonb),
  tonde.save_series_collection(uuid,uuid,jsonb),
  tonde.series_overview(uuid,uuid),
  tonde.create_series_episode(uuid,uuid,jsonb),
  tonde.update_series_episode(uuid,uuid,uuid,integer,jsonb),
  tonde.series_slots(uuid,uuid,tonde.generate_horizon,integer,date,text[]),
  tonde.generate_ahead_preview(uuid,uuid,jsonb),
  tonde.generate_ahead(uuid,uuid,jsonb),
  tonde.retry_generate_ahead(uuid,uuid),
  tonde.generate_ahead_jobs(uuid,uuid,integer),
  tonde.series_production_line(uuid,uuid,integer,integer),
  tonde.series_director_context(uuid,uuid,integer)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.long_form_structure(uuid,uuid,tonde.structure_level,uuid,integer,integer,integer),
  tonde.long_form_timing(uuid,uuid,integer),
  tonde.long_form_search(uuid,uuid,text,jsonb,integer,integer),
  tonde.long_form_summaries(uuid,uuid,integer,integer),
  tonde.long_form_script_index(uuid,uuid,integer,integer),
  tonde.long_form_context(uuid,uuid,tonde.structure_level,uuid,integer),
  tonde.save_structure_summary(uuid,uuid,tonde.structure_level,uuid,jsonb,integer,text,text),
  tonde.create_long_form_act(uuid,uuid,integer,jsonb),
  tonde.update_long_form_act(uuid,uuid,uuid,integer,jsonb),
  tonde.create_long_form_sequence(uuid,uuid,integer,jsonb),
  tonde.update_long_form_sequence(uuid,uuid,uuid,integer,jsonb),
  tonde.move_long_form_scene(uuid,uuid,uuid,integer,uuid,uuid),
  tonde.move_long_form_sequence(uuid,uuid,uuid,integer,uuid),
  tonde.split_long_form_structure(uuid,uuid,tonde.structure_level,uuid,bigint,integer,text),
  tonde.reorder_long_form(uuid,uuid,tonde.structure_level,uuid[],integer,uuid),
  tonde.set_long_form_approval(uuid,uuid,tonde.structure_level,uuid,text,integer),
  tonde.set_long_form_lock(uuid,uuid,tonde.structure_level,uuid,boolean,integer),
  tonde.create_series(uuid,uuid,jsonb),
  tonde.update_series(uuid,uuid,integer,jsonb),
  tonde.save_series_collection(uuid,uuid,jsonb),
  tonde.series_overview(uuid,uuid),
  tonde.create_series_episode(uuid,uuid,jsonb),
  tonde.update_series_episode(uuid,uuid,uuid,integer,jsonb),
  tonde.series_slots(uuid,uuid,tonde.generate_horizon,integer,date,text[]),
  tonde.generate_ahead_preview(uuid,uuid,jsonb),
  tonde.generate_ahead(uuid,uuid,jsonb),
  tonde.retry_generate_ahead(uuid,uuid),
  tonde.generate_ahead_jobs(uuid,uuid,integer),
  tonde.series_production_line(uuid,uuid,integer,integer),
  tonde.series_director_context(uuid,uuid,integer)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050019_dependencies_impact.sql
-- ==========================================================================

-- Additive migration: Prompt 9A dependency graph, impact engine and stale artifacts.
-- The canonical `object_dependencies` table is EXTENDED, never replaced: no second graph
-- system, no hidden JSON blob. Edges keep one direction (SOURCE is depended on, TARGET is the
-- dependent object), carry structured metadata, and are never deleted - they are deactivated.
-- Impact is COMPUTED with a bounded, cycle-safe traversal and never mutates anything; only an
-- explicit apply changes state, and an approved or locked dependent is reported rather than
-- silently rewritten.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.dependency_strength as enum ('hard','soft','advisory')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.dependency_origin as enum ('explicit','derived','inferred')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.impact_class as enum ('direct','downstream','potential','unaffected','unknown')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.impact_mode as enum ('preview','update_all','review_changes','change_only_this')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.artifact_kind as enum
  ('real_plan','ai_plan','prompt','first_frame','last_frame','generation_context','result_comparison',
   'derived_summary','continuity_state','continuity_analysis','deliverable','dependent_object','other')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.stale_state as enum ('current','stale','conflicted')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Dependency edge metadata. The relation vocabulary gains the categories the product
-- actually needs (runtime, asset, result, state) instead of overloading existing strings.
alter table tonde.object_dependencies drop constraint if exists object_dependencies_relation_check;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.object_dependencies') and conname = 'object_dependencies_relation_check'
  ) then
    execute $tonde_idem_ddl$alter table tonde.object_dependencies add constraint object_dependencies_relation_check check (relation in
  ('creative','continuity','execution','reference','derived_from','runtime','asset','result','state'))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

alter table tonde.object_dependencies add column if not exists reason text not null default '' check (length(reason) <= 600);

alter table tonde.object_dependencies add column if not exists strength tonde.dependency_strength not null default 'soft';

alter table tonde.object_dependencies add column if not exists origin tonde.dependency_origin not null default 'explicit';

alter table tonde.object_dependencies add column if not exists affected_fields text[] not null default '{}';

alter table tonde.object_dependencies add column if not exists source_version integer check (source_version is null or source_version > 0);

alter table tonde.object_dependencies add column if not exists target_version integer check (target_version is null or target_version > 0);

alter table tonde.object_dependencies add column if not exists active boolean not null default true;

alter table tonde.object_dependencies add column if not exists note text not null default '' check (length(note) <= 400);

alter table tonde.object_dependencies add column if not exists evidence jsonb not null default '{}' check (jsonb_typeof(evidence) = 'object');

alter table tonde.object_dependencies add column if not exists created_by uuid references auth.users(id) on delete set null;

alter table tonde.object_dependencies add column if not exists created_at timestamptz not null default now();

alter table tonde.object_dependencies add column if not exists updated_at timestamptz not null default now();

alter table tonde.object_dependencies add column if not exists revision integer not null default 1 check (revision > 0);

create index if not exists object_dependencies_source on tonde.object_dependencies(workspace_id, source_object_id, relation) where active;

create index if not exists object_dependencies_target on tonde.object_dependencies(workspace_id, target_object_id, relation) where active;


-- 3. Stale artifacts. A changed source never deletes derived work: the artifact is marked and
-- keeps its reason, the causing object, and both revisions so the mismatch is inspectable.
create table if not exists tonde.stale_artifacts (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  artifact_kind tonde.artifact_kind not null,
  artifact_ref uuid, object_id uuid not null,
  state tonde.stale_state not null default 'stale',
  reason text not null check (length(btrim(reason)) between 1 and 600),
  caused_by_object_id uuid, caused_by_revision integer check (caused_by_revision is null or caused_by_revision > 0),
  source_revision integer check (source_revision is null or source_revision > 0),
  current_revision integer check (current_revision is null or current_revision > 0),
  note text not null default '' check (length(note) <= 400),
  revision integer not null default 1 check (revision > 0),
  resolved_at timestamptz, resolved_by uuid,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, object_id) references tonde.objects(workspace_id, id) on delete restrict,
  foreign key (workspace_id, caused_by_object_id) references tonde.objects(workspace_id, id) on delete restrict
);

create unique index if not exists stale_artifacts_identity on tonde.stale_artifacts(workspace_id, artifact_kind, object_id, coalesce(artifact_ref, object_id));

create index if not exists stale_artifacts_open on tonde.stale_artifacts(workspace_id, production_id, state) where state <> 'current';


-- 4. Impact analyses. A preview is a durable record pinned to the root revision it was
-- computed from, so a later apply can reject a stale operation instead of guessing.
create table if not exists tonde.impact_analyses (
  id uuid primary key default gen_random_uuid(), workspace_id uuid not null, production_id uuid not null,
  root_object_id uuid not null, root_label text not null default '' check (length(root_label) <= 160),
  root_kind text not null default '' check (length(root_kind) <= 40),
  root_revision integer not null check (root_revision > 0),
  structure_revision integer check (structure_revision is null or structure_revision > 0),
  direction text not null default 'forward' check (direction in ('forward','reverse')),
  requested_depth integer not null default 2 check (requested_depth between 1 and 8),
  mode tonde.impact_mode not null default 'preview',
  classifications jsonb not null default '{}' check (jsonb_typeof(classifications) = 'object'),
  counts jsonb not null default '{}' check (jsonb_typeof(counts) = 'object'),
  locked_ids uuid[] not null default '{}',
  approved_ids uuid[] not null default '{}',
  explanation text not null default '' check (length(explanation) <= 1200),
  unresolved_count integer not null default 0 check (unresolved_count >= 0),
  note text not null default '' check (length(note) <= 400),
  applied_mode tonde.impact_mode, applied_at timestamptz,
  created_by uuid not null default auth.uid(),
  revision integer not null default 1 check (revision > 0),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, root_object_id) references tonde.objects(workspace_id, id) on delete restrict
);

create index if not exists impact_analyses_recent on tonde.impact_analyses(workspace_id, production_id, created_at desc);


-- 5. Shared helpers (not user-facing).
create or replace function tonde_private.pi_read_guard(target_workspace uuid) returns void
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
end $$;

revoke all on function tonde_private.pi_read_guard(uuid) from public, anon, authenticated, service_role;


-- The creator-facing name of an object. Never invented: an unknown kind falls back to its kind.
create or replace function tonde_private.pi_label(target_workspace uuid, target_object uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
declare kind text; label text;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  if kind is null then return null; end if;
  case kind
    when 'production' then select title into label from tonde.productions where id = target_object;
    when 'act' then select title into label from tonde.acts where id = target_object;
    when 'sequence' then select title into label from tonde.sequences where id = target_object;
    when 'scene' then select title into label from tonde.scenes where id = target_object;
    when 'shot' then select title into label from tonde.shots where id = target_object;
    when 'asset' then select name into label from tonde.assets where id = target_object;
    when 'reference' then select coalesce(nullif(source_description,''), source_url, 'Reference')
      into label from tonde.production_references where id = target_object;
    when 'execution_plan' then select case when execution_method = 'ai' then 'AI plan' else 'Real plan' end
      into label from tonde.execution_plans where id = target_object;
    when 'creative_document' then select coalesce(nullif(title,''),'Document') into label from tonde.creative_documents where id = target_object;
    when 'dialogue_line' then select left(coalesce(content,''), 60) into label from tonde.dialogue_lines where id = target_object;
    when 'result' then select 'Result' into label from tonde.results where id = target_object;
    when 'episode' then select title into label from tonde.series_episodes where id = target_object;
    when 'series' then select title into label from tonde.series where id = target_object;
    when 'project' then select title into label from tonde.projects where id = target_object;
    else label := kind;
  end case;
  return coalesce(nullif(btrim(coalesce(label,'')),''), kind);
end $$;

revoke all on function tonde_private.pi_label(uuid,uuid) from public, anon, authenticated, service_role;


-- The revision of any canonical object, read from the table that owns it.
create or replace function tonde_private.pi_object_revision(target_workspace uuid, target_object uuid) returns integer
language plpgsql stable security definer set search_path = '' as $$
declare kind text; value integer;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  case kind
    when 'production' then select revision into value from tonde.productions where id = target_object;
    when 'act' then select revision into value from tonde.acts where id = target_object;
    when 'sequence' then select revision into value from tonde.sequences where id = target_object;
    when 'scene' then select revision into value from tonde.scenes where id = target_object;
    when 'shot' then select revision into value from tonde.shots where id = target_object;
    when 'asset' then select revision into value from tonde.assets where id = target_object;
    when 'reference' then select 1 into value;
    when 'execution_plan' then select revision into value from tonde.execution_plans where id = target_object;
    when 'creative_document' then select revision into value from tonde.creative_documents where id = target_object;
    when 'dialogue_line' then select revision into value from tonde.dialogue_lines where id = target_object;
    when 'result' then select revision into value from tonde.results where id = target_object;
    when 'episode' then select revision into value from tonde.series_episodes where id = target_object;
    when 'series' then select revision into value from tonde.series where id = target_object;
    else value := null;
  end case;
  return value;
end $$;

revoke all on function tonde_private.pi_object_revision(uuid,uuid) from public, anon, authenticated, service_role;


-- Is a canonical object locked? An object is locked when its own lock column is set or when an
-- enclosing scope (Shot -> Scene -> Act -> Sequence -> Production) is locked by the creator.
create or replace function tonde_private.pi_is_locked(target_workspace uuid, target_object uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare kind text; locked boolean := false; scene_ref uuid; act_ref uuid; sequence_ref uuid;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  if kind = 'shot' then
    select locked_at is not null, scene_id into locked, scene_ref from tonde.shots where id = target_object;
    if not locked and scene_ref is not null then
      select locked_at is not null into locked from tonde.scenes where id = scene_ref;
    end if;
  elsif kind = 'scene' then
    select locked_at is not null into locked from tonde.scenes where id = target_object;
  elsif kind = 'act' then
    select locked_at is not null into locked from tonde.acts where id = target_object;
  elsif kind = 'sequence' then
    select locked_at is not null into locked from tonde.sequences where id = target_object;
  elsif kind = 'asset' then
    select locked_at is not null into locked from tonde.assets where id = target_object;
  elsif kind = 'execution_plan' then
    select locked_at is not null into locked from tonde.execution_plans where id = target_object;
  elsif kind = 'dialogue_line' then
    select locked_at is not null into locked from tonde.dialogue_lines where id = target_object;
  elsif kind = 'creative_document' then
    select locked_at is not null into locked from tonde.creative_documents where id = target_object;
  end if;
  return coalesce(locked, false);
end $$;

revoke all on function tonde_private.pi_is_locked(uuid,uuid) from public, anon, authenticated, service_role;


create or replace function tonde_private.pi_is_approved(target_workspace uuid, target_object uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare kind text; status text;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  case kind
    when 'production' then select approval::text into status from tonde.productions where id = target_object;
    when 'act' then select approval::text into status from tonde.acts where id = target_object;
    when 'sequence' then select approval::text into status from tonde.sequences where id = target_object;
    when 'scene' then select approval::text into status from tonde.scenes where id = target_object;
    when 'shot' then select approval::text into status from tonde.shots where id = target_object;
    when 'execution_plan' then select approval::text into status from tonde.execution_plans where id = target_object;
    when 'dialogue_line' then select approval::text into status from tonde.dialogue_lines where id = target_object;
    when 'creative_document' then select approval::text into status from tonde.creative_documents where id = target_object;
    when 'result' then select approval::text into status from tonde.results where id = target_object;
    else status := null;
  end case;
  return status in ('approved','changed_after_approval');
end $$;

revoke all on function tonde_private.pi_is_approved(uuid,uuid) from public, anon, authenticated, service_role;


-- Bounded, cycle-safe traversal. `seen` carries the visited path so a legitimate creative
-- cycle (A depends on B depends on A) terminates instead of recursing forever.
create or replace function tonde_private.pi_walk(target_workspace uuid, root uuid, max_depth integer, direction text)
returns table (object_id uuid, depth integer, relation text, via uuid)
language sql stable security definer set search_path = '' as $$
  with recursive walk as (
    select case when direction = 'reverse' then d.source_object_id else d.target_object_id end as object_id,
      1 as depth, d.relation, case when direction = 'reverse' then d.target_object_id else d.source_object_id end as via,
      array[root, case when direction = 'reverse' then d.source_object_id else d.target_object_id end] as seen
    from tonde.object_dependencies d
    where d.workspace_id = target_workspace and d.active
      and ((direction = 'reverse' and d.target_object_id = root) or (direction <> 'reverse' and d.source_object_id = root))
    union all
    select case when direction = 'reverse' then d.source_object_id else d.target_object_id end,
      w.depth + 1, d.relation, case when direction = 'reverse' then d.target_object_id else d.source_object_id end,
      w.seen || case when direction = 'reverse' then d.source_object_id else d.target_object_id end
    from tonde.object_dependencies d
    join walk w on (case when direction = 'reverse' then d.target_object_id else d.source_object_id end) = w.object_id
    where d.workspace_id = target_workspace and d.active and w.depth < greatest(coalesce(max_depth, 1), 1)
      and not (case when direction = 'reverse' then d.source_object_id else d.target_object_id end = any(w.seen))
  )
  select w.object_id, min(w.depth) as depth, (array_agg(w.relation order by w.depth))[1] as relation,
    (array_agg(w.via order by w.depth))[1] as via
  from walk w group by w.object_id;
$$;

revoke all on function tonde_private.pi_walk(uuid,uuid,integer,text) from public, anon, authenticated, service_role;


-- A creator-facing sentence, built from the real direct edges, never from a generic template.
create or replace function tonde_private.pi_explain(target_workspace uuid, target_object uuid, direct_count integer,
  downstream_count integer, sample_reason text) returns text
language plpgsql stable security definer set search_path = '' as $$
declare label text; kind text; sentence text;
begin
  label := tonde_private.pi_label(target_workspace, target_object);
  select o.kind into kind from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  if direct_count = 0 and downstream_count = 0 then
    return 'Changing ' || coalesce(label, 'this object') || ' has no known dependents in this Production.';
  end if;
  sentence := 'Changing ' || coalesce(label, 'this object') || ' affects ' || direct_count::text || ' direct object'
    || case when direct_count = 1 then '' else 's' end;
  if downstream_count > 0 then
    sentence := sentence || ' and ' || downstream_count::text || ' further downstream object'
      || case when downstream_count = 1 then '' else 's' end;
  end if;
  if coalesce(nullif(btrim(sample_reason), ''), '') <> '' then
    sentence := sentence || ' because ' || left(btrim(sample_reason), 400);
  else
    sentence := sentence || ' through recorded ' || coalesce(kind, 'production') || ' dependencies.';
  end if;
  return sentence;
end $$;

revoke all on function tonde_private.pi_explain(uuid,uuid,integer,integer,text) from public, anon, authenticated, service_role;


-- Mark (or refresh) a stale artifact. Never deletes, never rewrites the artifact itself.
create or replace function tonde_private.pi_mark_stale(target_workspace uuid, target_production uuid, target_object uuid,
  kind tonde.artifact_kind, reference uuid, reason_text text, caused_by uuid, caused_rev integer,
  source_rev integer, current_rev integer, desired_state tonde.stale_state default 'stale')
returns uuid language plpgsql security definer set search_path = '' as $$
declare marker uuid; ref uuid := coalesce(reference, target_object);
begin
  insert into tonde.stale_artifacts as artifact(workspace_id, production_id, artifact_kind, artifact_ref, object_id, state, reason,
    caused_by_object_id, caused_by_revision, source_revision, current_revision)
  values (target_workspace, target_production, kind, reference, target_object, desired_state, left(reason_text, 600),
    caused_by, caused_rev, source_rev, current_rev)
  on conflict (workspace_id, artifact_kind, object_id, (coalesce(artifact_ref, object_id))) do update
    set state = case when artifact.state = 'conflicted' and desired_state = 'stale'
        then 'conflicted'::tonde.stale_state else desired_state end,
      reason = left(reason_text, 600), caused_by_object_id = coalesce(caused_by, artifact.caused_by_object_id),
      caused_by_revision = coalesce(caused_rev, artifact.caused_by_revision),
      source_revision = coalesce(source_rev, artifact.source_revision),
      current_revision = coalesce(current_rev, artifact.current_revision),
      resolved_at = null, resolved_by = null
  returning artifact.id into marker;
  return marker;
end $$;

revoke all on function tonde_private.pi_mark_stale(uuid,uuid,uuid,tonde.artifact_kind,uuid,text,uuid,integer,integer,integer,tonde.stale_state)
  from public, anon, authenticated, service_role;


-- 6. When a canonical object changes, artifacts derived from it are marked stale in place.
-- Nothing is deleted, and the marker records which revision caused the mismatch.
create or replace function tonde_private.pi_stale_on_source_change() returns trigger
language plpgsql security definer set search_path = '' as $$
declare object_kind text := tg_argv[0]; changed boolean;
begin
  changed := to_jsonb(new) - array['revision','updated_at'] is distinct from to_jsonb(old) - array['revision','updated_at'];
  if not changed then return new; end if;
  update tonde.stale_artifacts
    set state = 'stale', reason = left('The ' || object_kind || ' changed after this artifact was derived.', 600),
      caused_by_object_id = new.id, caused_by_revision = new.revision,
      current_revision = new.revision, resolved_at = null, resolved_by = null
  where workspace_id = new.workspace_id and object_id = new.id and state = 'current'
    and artifact_kind in ('real_plan','ai_plan','prompt','first_frame','last_frame','generation_context','result_comparison','derived_summary');
  return new;
end $$;

revoke all on function tonde_private.pi_stale_on_source_change() from public, anon, authenticated, service_role;


-- 7. Derived edges: an explicit relationship the database already knows. A Shot that binds a
-- Character Asset depends on that Asset; a plan depends on its Shot; a dialogue line feeds its
-- Scene runtime. No AI inference is involved in creating these.
create or replace function tonde.dependency_sync(target_workspace uuid, target_production uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare made integer := 0; binding record; plan_row record; line_row record; desired boolean; edge_reason text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  for binding in
    select b.scope_object_id, b.asset_id, b.reference_id, b.binding_role, b.inheritance
    from tonde.scope_bindings b
    where b.workspace_id = target_workspace and b.production_id = target_production
  loop
    desired := binding.inheritance <> 'exclude';
    edge_reason := case
      when binding.inheritance = 'exclude' then 'This scope excluded the ' || binding.binding_role || ' binding.'
      else 'This ' || binding.binding_role || ' binding references the source directly.' end;
    if binding.asset_id is not null then
      insert into tonde.object_dependencies(workspace_id, source_object_id, target_object_id, relation, reason,
        strength, origin, affected_fields, active, created_by, updated_at)
      values (target_workspace, binding.asset_id, binding.scope_object_id, 'asset', edge_reason,
        (case when binding.binding_role in ('character','product','world','style') then 'hard' else 'soft' end)::tonde.dependency_strength,
        'derived'::tonde.dependency_origin, array[binding.binding_role], desired, auth.uid(), now())
      on conflict (source_object_id, target_object_id, relation) do update
        set reason = edge_reason, active = desired, updated_at = now();
      made := made + 1;
    elsif binding.reference_id is not null then
      insert into tonde.object_dependencies(workspace_id, source_object_id, target_object_id, relation, reason,
        strength, origin, affected_fields, active, created_by, updated_at)
      values (target_workspace, binding.reference_id, binding.scope_object_id, 'reference', edge_reason,
        'soft'::tonde.dependency_strength, 'derived'::tonde.dependency_origin, array[binding.binding_role], desired, auth.uid(), now())
      on conflict (source_object_id, target_object_id, relation) do update
        set reason = edge_reason, active = desired, updated_at = now();
      made := made + 1;
    end if;
  end loop;
  for plan_row in
    select p.id, p.shot_id, p.execution_method from tonde.execution_plans p
    where p.workspace_id = target_workspace and p.production_id = target_production
  loop
    insert into tonde.object_dependencies(workspace_id, source_object_id, target_object_id, relation, reason,
      strength, origin, affected_fields, active, created_by, updated_at)
    values (target_workspace, plan_row.shot_id, plan_row.id, 'execution',
      'This ' || plan_row.execution_method::text || ' plan executes the Shot direction.',
      'hard'::tonde.dependency_strength, 'derived'::tonde.dependency_origin,
      array['direction','framing','duration'], true, auth.uid(), now())
    on conflict (source_object_id, target_object_id, relation) do update set active = true, updated_at = now();
    made := made + 1;
  end loop;
  for line_row in
    select l.id, l.scene_id from tonde.dialogue_lines l
    where l.workspace_id = target_workspace and l.production_id = target_production and l.scene_id is not null
  loop
    insert into tonde.object_dependencies(workspace_id, source_object_id, target_object_id, relation, reason,
      strength, origin, affected_fields, active, created_by, updated_at)
    values (target_workspace, line_row.id, line_row.scene_id, 'runtime',
      'This Dialogue line contributes to the Scene runtime.',
      'soft'::tonde.dependency_strength, 'derived'::tonde.dependency_origin,
      array['planned_duration_ms'], true, auth.uid(), now())
    on conflict (source_object_id, target_object_id, relation) do update set active = true, updated_at = now();
    made := made + 1;
  end loop;
  return jsonb_build_object('production_id', target_production, 'edges_considered', made,
    'note', 'Derived edges come from real bindings, plans and dialogue. Nothing was inferred here.');
end $$;


-- 8. Explicit or AI-inferred edges. An inferred edge keeps its rationale, confidence and origin
-- so it is never presented as canonical certainty.
create or replace function tonde.dependency_edge(target_workspace uuid, target_production uuid, source_object uuid,
  target_object uuid, relation_value text, strength_value text default 'soft', origin_value text default 'explicit',
  reason_value text default '', fields_value text[] default '{}', evidence_value jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if source_object = target_object then
    raise exception 'An object cannot depend on itself' using errcode = '22023';
  end if;
  if relation_value not in ('creative','continuity','execution','reference','derived_from','runtime','asset','result','state') then
    raise exception 'Unsupported dependency relation' using errcode = '22023';
  end if;
  if strength_value not in ('hard','soft','advisory') then raise exception 'Unsupported dependency strength' using errcode = '22023'; end if;
  if origin_value not in ('explicit','derived','inferred') then raise exception 'Unsupported dependency origin' using errcode = '22023'; end if;
  if not exists (select 1 from tonde.objects o where o.workspace_id = target_workspace and o.id = source_object)
    or not exists (select 1 from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object) then
    raise exception 'Dependency edge needs two real objects in this workspace' using errcode = 'P0002';
  end if;
  insert into tonde.object_dependencies as edge(workspace_id, source_object_id, target_object_id, relation, reason, strength,
    origin, affected_fields, active, evidence, created_by, updated_at)
  values (target_workspace, source_object, target_object, relation_value, left(coalesce(reason_value,''), 600),
    strength_value::tonde.dependency_strength, origin_value::tonde.dependency_origin, coalesce(fields_value,'{}'), true,
    coalesce(evidence_value,'{}'::jsonb), auth.uid(), now())
  on conflict (source_object_id, target_object_id, relation) do update
    set reason = left(coalesce(nullif(reason_value,''), edge.reason), 600),
      strength = strength_value::tonde.dependency_strength, origin = origin_value::tonde.dependency_origin,
      affected_fields = coalesce(nullif(fields_value,'{}'), edge.affected_fields),
      evidence = coalesce(nullif(evidence_value,'{}'::jsonb), edge.evidence),
      active = true, updated_at = now()
  returning edge.revision into saved;
  return jsonb_build_object('source_object_id', source_object, 'target_object_id', target_object, 'relation', relation_value,
    'strength', strength_value, 'origin', origin_value, 'active', true, 'revision', saved,
    'note', 'An inferred edge is a proposal with its rationale, not canonical certainty.');
end $$;


create or replace function tonde.dependency_active(target_workspace uuid, target_production uuid, edge_ids uuid[],
  desired_active boolean, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare changed integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  update tonde.object_dependencies d set active = coalesce(desired_active, true),
    note = left(coalesce(note_text,''), 400), updated_at = now()
  where d.workspace_id = target_workspace
    and (d.source_object_id = any(edge_ids) or d.target_object_id = any(edge_ids));
  get diagnostics changed = row_count;
  return jsonb_build_object('changed', changed, 'active', coalesce(desired_active,true),
    'note', 'Edges are deactivated, never deleted: the history of a relationship stays readable.');
end $$;


-- 9. Graph read: forward (what does this affect) and reverse (what does this depend on),
-- bounded by depth and page size, with the classification of every reachable object.
create or replace function tonde.dependency_graph(target_workspace uuid, target_production uuid, target_object uuid,
  direction text default 'forward', target_depth integer default 2, target_limit integer default 200)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare depth_value integer; lim integer; nodes jsonb; edges jsonb; total integer; root_kind text; root_label text;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  if direction not in ('forward','reverse') then raise exception 'Direction must be forward or reverse' using errcode = '22023'; end if;
  depth_value := least(greatest(coalesce(target_depth, 2), 1), 8);
  lim := least(greatest(coalesce(target_limit, 200), 1), 500);
  select o.kind, tonde_private.pi_label(target_workspace, target_object) into root_kind, root_label
    from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  if root_kind is null then raise exception 'That object is unavailable in this workspace' using errcode = 'P0002'; end if;
  select count(*) into total from tonde_private.pi_walk(target_workspace, target_object, depth_value, direction);
  select coalesce(jsonb_agg(jsonb_build_object(
      'object_id', w.object_id, 'level', o.kind, 'label', tonde_private.pi_label(target_workspace, w.object_id),
      'depth', w.depth, 'relation', w.relation,
      -- An inferred relationship is a POTENTIAL impact even when it is one hop away: the
      -- deterministic graph alone does not prove it must change.
      'classification', case when (select d.origin from tonde.object_dependencies d where d.workspace_id = target_workspace and d.active
          and d.relation = w.relation
          and ((direction = 'reverse' and d.source_object_id = w.object_id and d.target_object_id = w.via)
            or (direction <> 'reverse' and d.target_object_id = w.object_id and d.source_object_id = w.via))
          limit 1) = 'inferred' then 'potential'
        when w.depth = 1 then 'direct' else 'downstream' end,
      'locked', tonde_private.pi_is_locked(target_workspace, w.object_id),
      'approved', tonde_private.pi_is_approved(target_workspace, w.object_id),
      'revision', tonde_private.pi_object_revision(target_workspace, w.object_id)) order by w.depth, w.object_id), '[]'::jsonb)
    into nodes
  from (select * from tonde_private.pi_walk(target_workspace, target_object, depth_value, direction) order by depth, object_id limit lim) w
  join tonde.objects o on o.workspace_id = target_workspace and o.id = w.object_id;
  select coalesce(jsonb_agg(jsonb_build_object('source_object_id', d.source_object_id, 'target_object_id', d.target_object_id,
      'relation', d.relation, 'strength', d.strength, 'origin', d.origin, 'reason', d.reason,
      'affected_fields', d.affected_fields, 'active', d.active, 'revision', d.revision)), '[]'::jsonb)
    into edges
  from tonde.object_dependencies d
  where d.workspace_id = target_workspace and d.active
    and (d.source_object_id = target_object or d.target_object_id = target_object
      or d.source_object_id in (select w.object_id from tonde_private.pi_walk(target_workspace, target_object, depth_value, direction) w)
      or d.target_object_id in (select w.object_id from tonde_private.pi_walk(target_workspace, target_object, depth_value, direction) w));
  return jsonb_build_object('root_object_id', target_object, 'root_kind', root_kind, 'root_label', root_label,
    'direction', direction, 'depth', depth_value, 'nodes', nodes, 'edges', edges, 'total', total,
    'truncated', total > lim, 'cycles_safe', true,
    'note', 'Traversal is bounded and cycle-safe. Edges only ever mean: the source is relied upon, the target depends on it.');
end $$;


create or replace function tonde.dependency_edges(target_workspace uuid, target_production uuid, target_object uuid,
  target_limit integer default 100, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 100), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  select coalesce(jsonb_agg(jsonb_build_object('source_object_id', d.source_object_id, 'target_object_id', d.target_object_id,
      'relation', d.relation, 'strength', d.strength, 'origin', d.origin, 'reason', d.reason,
      'affected_fields', d.affected_fields, 'active', d.active, 'note', d.note, 'evidence', d.evidence,
      'revision', d.revision, 'updated_at', d.updated_at,
      'source_label', tonde_private.pi_label(target_workspace, d.source_object_id),
      'target_label', tonde_private.pi_label(target_workspace, d.target_object_id)) order by d.active desc, d.updated_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.object_dependencies d
    where d.workspace_id = target_workspace and (d.source_object_id = target_object or d.target_object_id = target_object)
    order by d.active desc, d.updated_at desc limit lim offset off) d;
  return jsonb_build_object('object_id', target_object, 'items', items, 'limit', lim, 'offset', off);
end $$;


-- 10. Impact preview. Computes and records the analysis; it never changes a Production object.
create or replace function tonde.impact_preview(target_workspace uuid, target_production uuid, target_object uuid,
  target_depth integer default 2, target_limit integer default 200)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare graph jsonb; nodes jsonb; node jsonb; direct integer := 0; downstream integer := 0; potential integer := 0;
  locked_ids uuid[] := '{}'; approved_ids uuid[] := '{}'; counts jsonb := '{}'::jsonb; kind text; label text;
  root_revision integer; locked uuid[] := '{}'; approved uuid[] := '{}'; analysis uuid; sample_reason text;
  explanation text; group_counts jsonb := '{}'::jsonb; structure_rev integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  graph := tonde.dependency_graph(target_workspace, target_production, target_object, 'forward', target_depth, target_limit);
  nodes := graph->'nodes';
  select o.kind, tonde_private.pi_label(target_workspace, target_object), tonde_private.pi_object_revision(target_workspace, target_object)
    into kind, label, root_revision
    from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  if kind is null then raise exception 'That object is unavailable in this workspace' using errcode = 'P0002'; end if;
  select coalesce(sum(revision), 0) into structure_rev from (
    select revision from tonde.productions where workspace_id = target_workspace and id = target_production
    union all select revision from tonde.acts where workspace_id = target_workspace and production_id = target_production
    union all select revision from tonde.sequences where workspace_id = target_workspace and production_id = target_production
    union all select revision from tonde.scenes where workspace_id = target_workspace and production_id = target_production
    union all select revision from tonde.shots where workspace_id = target_workspace and production_id = target_production) summed;
  for node in select * from jsonb_array_elements(nodes) loop
    if node->>'classification' = 'direct' then
      direct := direct + 1;
      if coalesce((node->>'locked')::boolean, false) then locked := locked || (node->>'object_id')::uuid; end if;
      if coalesce((node->>'approved')::boolean, false) then approved := approved || (node->>'object_id')::uuid; end if;
    elsif node->>'classification' = 'potential' then
      potential := potential + 1;
    else
      downstream := downstream + 1;
    end if;
    counts := jsonb_set(counts, array[node->>'level'], to_jsonb(coalesce((counts->>(node->>'level'))::integer, 0) + 1), true);
  end loop;
  select d.reason into sample_reason
    from tonde.object_dependencies d
    where d.workspace_id = target_workspace and d.source_object_id = target_object and d.active and d.reason <> ''
    order by case d.strength when 'hard' then 1 when 'soft' then 2 else 3 end, d.relation limit 1;
  explanation := tonde_private.pi_explain(target_workspace, target_object, direct, downstream, coalesce(sample_reason, ''));
  group_counts := jsonb_build_object('direct', direct, 'downstream', downstream, 'potential', potential,
    'locked', coalesce(array_length(locked, 1), 0), 'approved', coalesce(array_length(approved, 1), 0),
    'by_level', counts, 'total', jsonb_array_length(nodes));
  insert into tonde.impact_analyses(workspace_id, production_id, root_object_id, root_label, root_kind, root_revision,
    structure_revision, direction, requested_depth, mode, classifications, counts, locked_ids, approved_ids, explanation)
  values (target_workspace, target_production, target_object, coalesce(label,''), coalesce(kind,''), root_revision,
    structure_rev, 'forward', least(greatest(coalesce(target_depth,2),1),8), 'preview',
    jsonb_build_object('nodes', nodes, 'edges', graph->'edges'), group_counts, locked, approved, explanation)
  returning id into analysis;
  return jsonb_build_object('analysis_id', analysis, 'root_object_id', target_object, 'root_kind', kind, 'root_label', label,
    'root_revision', root_revision, 'structure_revision', structure_rev, 'depth', least(greatest(coalesce(target_depth,2),1),8),
    'nodes', nodes, 'counts', group_counts, 'locked_ids', to_jsonb(locked), 'approved_ids', to_jsonb(approved),
    'explanation', explanation, 'applied', false,
    'rule', 'Impact is computed, never applied. Nothing in this Production changed yet.');
end $$;


create or replace function tonde.impact_history(target_workspace uuid, target_production uuid, target_limit integer default 20,
  target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 20), 1), 100);
  off := greatest(coalesce(target_offset, 0), 0);
  select count(*) into total from tonde.impact_analyses where workspace_id = target_workspace and production_id = target_production;
  select coalesce(jsonb_agg(jsonb_build_object('analysis_id', a.id, 'root_object_id', a.root_object_id, 'root_label', a.root_label,
      'root_kind', a.root_kind, 'root_revision', a.root_revision, 'structure_revision', a.structure_revision,
      'mode', a.mode, 'applied_mode', a.applied_mode, 'applied_at', a.applied_at, 'counts', a.counts,
      'explanation', a.explanation, 'unresolved_count', a.unresolved_count, 'created_at', a.created_at) order by a.created_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.impact_analyses where workspace_id = target_workspace and production_id = target_production
    order by created_at desc limit lim offset off) a;
  return jsonb_build_object('items', items, 'total', total, 'limit', lim, 'offset', off, 'truncated', total > off + lim);
end $$;


-- 11. Applying an impact. Three modes that mean something:
--   update_all        mark every affected dependent's derived artifacts (locked objects reported,
--                     approved objects flagged for review rather than rewritten)
--   review_changes    only the selected dependent ids
--   change_only_this  the change stays local: direct dependents keep their work but it is marked
--                     stale and the remaining downstream impact is recorded as unresolved
create or replace function tonde.apply_impact(target_workspace uuid, target_production uuid, target_analysis uuid,
  desired_mode text, selected_ids uuid[] default '{}', expected_root_revision integer default null, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare analysis tonde.impact_analyses; current_revision integer; node jsonb; target uuid; marked integer := 0;
  locked_skipped jsonb := '[]'::jsonb; requiring_review jsonb := '[]'::jsonb; direct_ids uuid[] := '{}';
  downstream_count integer := 0; unresolved integer := 0; kinds text[] := array['real_plan','ai_plan','prompt','first_frame',
  'last_frame','generation_context','result_comparison','derived_summary','continuity_state'];
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into analysis from tonde.impact_analyses
    where workspace_id = target_workspace and production_id = target_production and id = target_analysis;
  if not found then raise exception 'That impact analysis is unavailable' using errcode = 'P0002'; end if;
  if analysis.applied_mode is not null then
    raise exception 'That impact analysis was already applied' using errcode = '23514';
  end if;
  current_revision := tonde_private.pi_object_revision(target_workspace, analysis.root_object_id);
  if current_revision is distinct from analysis.root_revision
    or (expected_root_revision is not null and expected_root_revision <> analysis.root_revision) then
    raise exception 'The source changed since this impact was computed. Preview the impact again.' using errcode = '40001';
  end if;
  if desired_mode not in ('update_all','review_changes','change_only_this') then
    raise exception 'Unsupported impact mode' using errcode = '22023';
  end if;
  for node in select * from jsonb_array_elements(analysis.classifications->'nodes') loop
    target := (node->>'object_id')::uuid;
    -- Every proposal pins the revisions it was computed from: if a dependent moved on since the
    -- preview, this operation is stale and is rejected instead of applied against newer content.
    if (node->>'revision') is not null
      and tonde_private.pi_object_revision(target_workspace, target) is distinct from (node->>'revision')::integer then
      raise exception 'A dependent object changed since this impact was computed. Preview the impact again.' using errcode = '40001';
    end if;
    if coalesce((node->>'depth')::integer, 1) > 1 then downstream_count := downstream_count + 1; end if;
    if node->>'classification' = 'direct' then direct_ids := direct_ids || target; end if;
    if desired_mode = 'review_changes' and not (target = any(selected_ids)) then continue; end if;
    if desired_mode = 'change_only_this' then
      -- The direct dependents keep their artifacts (nothing is rewritten) but they stop claiming
      -- to be current; everything further downstream stays explicitly unresolved.
      if node->>'classification' <> 'direct' then continue; end if;
      if tonde_private.pi_is_locked(target_workspace, target) then
        locked_skipped := locked_skipped || to_jsonb(jsonb_build_object('object_id', target, 'label', node->>'label',
          'reason', 'locked')); continue;
      end if;
      marked := marked + 1;
      perform tonde_private.pi_mark_stale(target_workspace, target_production, target, 'dependent_object', null,
        'CHANGE ONLY THIS: the source changed and this dependent was intentionally left as it was.', analysis.root_object_id,
        analysis.root_revision, analysis.root_revision, tonde_private.pi_object_revision(target_workspace, target), 'stale');
      continue;
    end if;
    if tonde_private.pi_is_locked(target_workspace, target) then
      locked_skipped := locked_skipped || to_jsonb(jsonb_build_object('object_id', target, 'label', node->>'label',
        'reason', 'The dependent object is locked. Unlock it before TONDE updates it.'));
      continue;
    end if;
    if tonde_private.pi_is_approved(target_workspace, target) then
      requiring_review := requiring_review || to_jsonb(jsonb_build_object('object_id', target, 'label', node->>'label',
        'revision', tonde_private.pi_object_revision(target_workspace, target),
        'reason', 'Approved content is never rewritten silently.'));
      perform tonde_private.pi_mark_stale(target_workspace, target_production, target, 'dependent_object', null,
        'Approved content depends on a changed source and needs review.', analysis.root_object_id, analysis.root_revision,
        analysis.root_revision, tonde_private.pi_object_revision(target_workspace, target), 'conflicted');
      marked := marked + 1;
      continue;
    end if;
    marked := marked + 1;
    perform tonde_private.pi_mark_stale(target_workspace, target_production, target, 'dependent_object', null,
      'The source ' || coalesce(analysis.root_label,'object') || ' changed after this artifact was derived.',
      analysis.root_object_id, analysis.root_revision, analysis.root_revision,
      tonde_private.pi_object_revision(target_workspace, target), 'stale');
  end loop;
  unresolved := case when desired_mode = 'change_only_this' then greatest(downstream_count, 0) else 0 end;
  update tonde.impact_analyses a set mode = desired_mode::tonde.impact_mode,
    applied_mode = desired_mode::tonde.impact_mode, applied_at = now(),
    unresolved_count = unresolved, note = left(coalesce(note_text,''), 400)
  where a.id = analysis.id;
  return jsonb_build_object('analysis_id', analysis.id, 'mode', desired_mode, 'marked', marked,
    'locked_skipped', locked_skipped, 'requiring_review', requiring_review,
    'direct_count', coalesce(array_length(direct_ids, 1), 0), 'downstream_count', downstream_count,
    'unresolved_count', unresolved,
    'note', case when desired_mode = 'update_all'
        then 'Affected derived artifacts were marked. Approved content and locked objects were reported, not rewritten.'
      when desired_mode = 'review_changes'
        then 'Only the selected dependents were marked.'
      else 'CHANGE ONLY THIS: the change stayed local and the remaining downstream impact is recorded as unresolved.' end);
end $$;


-- 12. Stale artifacts: read and explicit resolution. A stale artifact is never resurrected by
-- changing its own row: the creator resolves it (or re-derives it), and the record stays.
create or replace function tonde.stale_artifact_list(target_workspace uuid, target_production uuid, target_state text default null,
  target_limit integer default 100, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; open_count integer;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 100), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  select count(*) into total from tonde.stale_artifacts
    where workspace_id = target_workspace and production_id = target_production
      and (target_state is null or state = target_state::tonde.stale_state);
  select count(*) into open_count from tonde.stale_artifacts
    where workspace_id = target_workspace and production_id = target_production and state <> 'current';
  select coalesce(jsonb_agg(jsonb_build_object('artifact_id', s.id, 'artifact_kind', s.artifact_kind, 'artifact_ref', s.artifact_ref,
      'object_id', s.object_id, 'object_label', tonde_private.pi_label(target_workspace, s.object_id),
      'object_kind', (select kind from tonde.objects where workspace_id = target_workspace and id = s.object_id),
      'state', s.state, 'reason', s.reason, 'caused_by_object_id', s.caused_by_object_id,
      'caused_by_label', tonde_private.pi_label(target_workspace, s.caused_by_object_id),
      'caused_by_revision', s.caused_by_revision, 'source_revision', s.source_revision, 'current_revision', s.current_revision,
      'resolved_at', s.resolved_at, 'created_at', s.created_at) order by s.created_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.stale_artifacts where workspace_id = target_workspace and production_id = target_production
    and (target_state is null or state = target_state::tonde.stale_state)
    order by created_at desc limit lim offset off) s;
  return jsonb_build_object('items', items, 'total', total, 'open', open_count, 'limit', lim, 'offset', off,
    'note', 'Stale means the artifact may no longer match its source. Nothing was deleted.');
end $$;


create or replace function tonde.resolve_stale_artifact(target_workspace uuid, target_production uuid, target_artifact uuid,
  note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare marker tonde.stale_artifacts; current_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into marker from tonde.stale_artifacts
    where workspace_id = target_workspace and production_id = target_production and id = target_artifact;
  if not found then raise exception 'That artifact marker is unavailable' using errcode = 'P0002'; end if;
  current_revision := tonde_private.pi_object_revision(target_workspace, marker.object_id);
  update tonde.stale_artifacts s set state = 'current', note = left(coalesce(note_text,''), 400),
    resolved_at = now(), resolved_by = auth.uid()
  where s.id = marker.id;
  return jsonb_build_object('artifact_id', marker.id, 'state', 'current',
    'note', 'The creator resolved this artifact. Historical markers stay readable.');
end $$;


create or replace function tonde.mark_stale_artifact(target_workspace uuid, target_production uuid, target_object uuid,
  kind_value text, reason_text text, reference uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare marker uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if kind_value not in ('real_plan','ai_plan','prompt','first_frame','last_frame','generation_context','result_comparison',
      'derived_summary','continuity_state','continuity_analysis','deliverable','dependent_object','other') then
    raise exception 'Unsupported artifact kind' using errcode = '22023';
  end if;
  marker := tonde_private.pi_mark_stale(target_workspace, target_production, target_object, kind_value::tonde.artifact_kind, reference,
    left(coalesce(reason_text,''), 600), null, null, null, tonde_private.pi_object_revision(target_workspace, target_object), 'stale');
  return jsonb_build_object('artifact_id', marker, 'state', 'stale');
end $$;


-- 13. RLS. Every new workspace-owned table is isolated; enabling RLS is not optional.
do $$ declare item text; begin
  foreach item in array array['stale_artifacts','impact_analyses'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select, insert, update on tonde.%I to authenticated', item);
  end loop;
end $$;

alter table tonde.object_dependencies enable row level security;

do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'tonde' and tablename = 'object_dependencies' and policyname = 'tenant_read') then
    create policy tenant_read on tonde.object_dependencies for select to authenticated
      using (tonde_private.is_workspace_member(workspace_id));
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'tonde' and tablename = 'object_dependencies' and policyname = 'tenant_insert') then
    create policy tenant_insert on tonde.object_dependencies for insert to authenticated
      with check (tonde_private.can_edit_workspace(workspace_id));
  end if;
  if not exists (select 1 from pg_policies where schemaname = 'tonde' and tablename = 'object_dependencies' and policyname = 'tenant_update') then
    create policy tenant_update on tonde.object_dependencies for update to authenticated
      using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id));
  end if;
end $$;

grant select, insert, update on tonde.object_dependencies to authenticated;


-- 14. Mutation guards on the new tables (nothing here rewrites identity or bypasses a lock).
do $$ declare item text; begin
  foreach item in array array['stale_artifacts','impact_analyses'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;

drop trigger if exists guard_mutation on tonde.object_dependencies;
create trigger guard_mutation before insert or update on tonde.object_dependencies
  for each row execute function tonde_private.guard_mutation();


-- 15. Stale markers follow real source changes.
drop trigger if exists zz_stale_on_shot_change on tonde.shots;
create trigger zz_stale_on_shot_change after update on tonde.shots
  for each row execute function tonde_private.pi_stale_on_source_change('Shot');

drop trigger if exists zz_stale_on_scene_change on tonde.scenes;
create trigger zz_stale_on_scene_change after update on tonde.scenes
  for each row execute function tonde_private.pi_stale_on_source_change('Scene');

drop trigger if exists zz_stale_on_document_change on tonde.creative_documents;
create trigger zz_stale_on_document_change after update on tonde.creative_documents
  for each row execute function tonde_private.pi_stale_on_source_change('document');

drop trigger if exists zz_stale_on_plan_change on tonde.execution_plans;
create trigger zz_stale_on_plan_change after update on tonde.execution_plans
  for each row execute function tonde_private.pi_stale_on_source_change('plan');


-- 16. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.dependency_sync(uuid,uuid),
  tonde.dependency_edge(uuid,uuid,uuid,uuid,text,text,text,text,text[],jsonb),
  tonde.dependency_active(uuid,uuid,uuid[],boolean,text),
  tonde.dependency_graph(uuid,uuid,uuid,text,integer,integer),
  tonde.dependency_edges(uuid,uuid,uuid,integer,integer),
  tonde.impact_preview(uuid,uuid,uuid,integer,integer),
  tonde.impact_history(uuid,uuid,integer,integer),
  tonde.apply_impact(uuid,uuid,uuid,text,uuid[],integer,text),
  tonde.stale_artifact_list(uuid,uuid,text,integer,integer),
  tonde.resolve_stale_artifact(uuid,uuid,uuid,text),
  tonde.mark_stale_artifact(uuid,uuid,uuid,text,text,uuid)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.dependency_sync(uuid,uuid),
  tonde.dependency_edge(uuid,uuid,uuid,uuid,text,text,text,text,text[],jsonb),
  tonde.dependency_active(uuid,uuid,uuid[],boolean,text),
  tonde.dependency_graph(uuid,uuid,uuid,text,integer,integer),
  tonde.dependency_edges(uuid,uuid,uuid,integer,integer),
  tonde.impact_preview(uuid,uuid,uuid,integer,integer),
  tonde.impact_history(uuid,uuid,integer,integer),
  tonde.apply_impact(uuid,uuid,uuid,text,uuid[],integer,text),
  tonde.stale_artifact_list(uuid,uuid,text,integer,integer),
  tonde.resolve_stale_artifact(uuid,uuid,uuid,text),
  tonde.mark_stale_artifact(uuid,uuid,uuid,text,text,uuid)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050020_continuity_engine.sql
-- ==========================================================================

-- Additive migration: Prompt 9B continuity engine.
-- Continuity is TEMPORAL. A statement records what is true about one trait of one subject at one
-- point in Production order, and the engine understands that state CHANGES as the Production
-- progresses: an injury, a wardrobe change or a new time of day is declared, not inferred.
-- Statements are never overwritten. A newer statement supersedes an older one and both stay
-- readable, so "what did we decide before?" has an answer.
--
-- The engine compares DECLARED statements only. It never claims to have analysed media: a clean
-- check means the declarations agree, not that the footage is consistent. That limitation is
-- returned with every check and stored on the check row.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.continuity_domain as enum
  ('character','wardrobe','prop','product','vehicle','injury','hair_makeup','weather','time_of_day',
   'environment','lighting','story_knowledge','dialogue_fact','screen_direction','eyeline',
   'camera_geography','position','product_condition','other')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.continuity_anchor as enum ('production','scene_opening','scene_ending','shot')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.continuity_transition as enum ('baseline','continuous','changed')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.continuity_origin as enum ('declared','derived','inferred')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.continuity_finding_kind as enum
  ('unexplained_change','boundary_break','missing_reason','lock_conflict','unverified_after')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.continuity_finding_state as enum ('open','acknowledged','resolved','waived')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Continuity statements. One trait, one subject, one point in the timeline.
create table if not exists tonde.continuity_states (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  domain tonde.continuity_domain not null,
  subject_object_id uuid,
  trait text not null check (length(btrim(trait)) between 1 and 120),
  anchor tonde.continuity_anchor not null default 'production',
  scene_id uuid, shot_id uuid,
  value text not null check (length(btrim(value)) between 1 and 400),
  transition tonde.continuity_transition not null default 'baseline',
  origin tonde.continuity_origin not null default 'declared',
  epistemic text not null default 'observed' check (epistemic in ('observed','estimated','recommended','unknown')),
  confidence text not null default 'high' check (confidence in ('high','medium','low')),
  reason text not null default '' check (length(reason) <= 600),
  evidence jsonb not null default '[]'::jsonb check (jsonb_typeof(evidence) = 'array'),
  note text not null default '' check (length(note) <= 400),
  supersedes_id uuid,
  retired_at timestamptz, retired_by uuid,
  retire_reason text not null default '' check (length(retire_reason) <= 400),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, production_id, id),
  check ((anchor = 'shot') = (shot_id is not null)),
  check (anchor in ('production','shot') or scene_id is not null),
  check (anchor <> 'production' or (scene_id is null and shot_id is null)),
  -- A creator declares a fact of their own Production; only an INFERRED observation must cite evidence.
  check (epistemic <> 'observed' or origin <> 'inferred' or jsonb_array_length(evidence) > 0),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, scene_id) references tonde.scenes(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, subject_object_id) references tonde.objects(workspace_id, id) on delete restrict,
  foreign key (workspace_id, supersedes_id) references tonde.continuity_states(workspace_id, id) on delete restrict
);

-- One live statement per trait per point. A different value is a new version, never a rewrite.
create unique index if not exists continuity_states_live_identity on tonde.continuity_states
  (workspace_id, production_id, domain, coalesce(subject_object_id, '00000000-0000-0000-0000-000000000000'::uuid), trait, anchor,
   coalesce(scene_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(shot_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where retired_at is null;

create index if not exists continuity_states_by_subject on tonde.continuity_states(workspace_id, production_id, subject_object_id, domain, trait)
  where retired_at is null;

create index if not exists continuity_states_by_production on tonde.continuity_states(workspace_id, production_id, created_at desc);


-- 3. A recorded check. It pins the revision, the statement count and the statement watermark it
-- was computed from, so "is this check still current?" is a comparison, not a guess.
create table if not exists tonde.continuity_checks (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  production_revision integer not null check (production_revision > 0),
  state_count integer not null default 0 check (state_count >= 0),
  state_watermark timestamptz,
  finding_count integer not null default 0 check (finding_count >= 0),
  critical_count integer not null default 0 check (critical_count >= 0),
  warning_count integer not null default 0 check (warning_count >= 0),
  info_count integer not null default 0 check (info_count >= 0),
  counts jsonb not null default '{}'::jsonb check (jsonb_typeof(counts) = 'object'),
  verdict text not null default 'consistent' check (verdict in ('consistent','needs_review','conflict')),
  explanation text not null default '' check (length(explanation) <= 1200),
  limitations text not null default '' check (length(limitations) <= 1200),
  note text not null default '' check (length(note) <= 400),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, production_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict
);

create index if not exists continuity_checks_recent on tonde.continuity_checks(workspace_id, production_id, created_at desc);


-- 4. Findings. A finding is a statement about the recorded declarations. A deterministic finding
-- is observed and cites the statements it compared; an inferred proposal can never claim to be an
-- observation and can never resolve itself.
create table if not exists tonde.continuity_findings (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  check_id uuid,
  kind tonde.continuity_finding_kind not null,
  severity text not null default 'info' check (severity in ('info','warning','critical')),
  domain tonde.continuity_domain not null,
  subject_object_id uuid,
  trait text not null default '' check (length(trait) <= 120),
  earlier_state_id uuid, later_state_id uuid,
  at_scene_id uuid, at_shot_id uuid,
  explanation text not null check (length(explanation) between 1 and 1200),
  suggested_resolution text not null default '' check (length(suggested_resolution) <= 1200),
  origin tonde.continuity_origin not null default 'derived',
  rationale text not null default '' check (length(rationale) <= 1200),
  epistemic text not null default 'observed' check (epistemic in ('observed','estimated','recommended','unknown')),
  confidence text not null default 'high' check (confidence in ('high','medium','low')),
  evidence jsonb not null default '[]'::jsonb check (jsonb_typeof(evidence) = 'array'),
  state tonde.continuity_finding_state not null default 'open',
  resolution_note text not null default '' check (length(resolution_note) <= 800),
  resolved_by uuid, resolved_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  check (epistemic <> 'observed' or jsonb_array_length(evidence) > 0),
  check (origin = 'inferred' or epistemic = 'observed'),
  check (origin <> 'inferred' or epistemic <> 'observed'),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, check_id) references tonde.continuity_checks(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, subject_object_id) references tonde.objects(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, earlier_state_id) references tonde.continuity_states(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, production_id, later_state_id) references tonde.continuity_states(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, at_scene_id) references tonde.scenes(workspace_id, id) on delete restrict,
  foreign key (workspace_id, at_shot_id) references tonde.shots(workspace_id, id) on delete restrict
);

create index if not exists continuity_findings_by_check on tonde.continuity_findings(workspace_id, check_id, severity);

create index if not exists continuity_findings_open on tonde.continuity_findings(workspace_id, production_id, severity)
  where state in ('open','acknowledged');

-- A re-run of the same rules inside one check cannot double-report: proposals (no check) are exempt.
create unique index if not exists continuity_findings_identity on tonde.continuity_findings
  (check_id, kind, domain, coalesce(subject_object_id, '00000000-0000-0000-0000-000000000000'::uuid), trait,
   coalesce(later_state_id, earlier_state_id, at_shot_id, at_scene_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where check_id is not null;


-- 5. Shared helpers (not user-facing; reachable only through the security-definer RPCs below).
create or replace function tonde_private.ci_text(source jsonb, key_name text, max_length integer, required boolean default false)
returns text language plpgsql immutable set search_path = '' as $$
declare value text;
begin
  value := btrim(coalesce(source ->> key_name, ''));
  if value = '' then
    if required then raise exception 'The field % is required', key_name using errcode = '22023'; end if;
    return '';
  end if;
  if length(value) > max_length then
    raise exception 'The field % is longer than % characters', key_name, max_length using errcode = '22001';
  end if;
  return value;
end $$;

revoke all on function tonde_private.ci_text(jsonb,text,integer,boolean) from public, anon, authenticated, service_role;


-- The order of the Scenes of a Production: Act, then Sequence, then Scene order.
create or replace function tonde_private.ci_scene_rank(target_workspace uuid, target_production uuid)
returns table (scene_id uuid, scene_position bigint)
language sql stable security definer set search_path = '' as $$
  select s.id,
    row_number() over (order by coalesce(a.sort_order, 0), coalesce(q.sort_order, 0), s.sort_order, s.created_at, s.id)
  from tonde.scenes s
  left join tonde.acts a on a.id = s.act_id
  left join tonde.sequences q on q.id = s.sequence_id
  where s.workspace_id = target_workspace and s.production_id = target_production and s.lifecycle = 'active';
$$;

revoke all on function tonde_private.ci_scene_rank(uuid,uuid) from public, anon, authenticated, service_role;


-- The order of the Shots of a Production: inside their Scene, by Shot order.
create or replace function tonde_private.ci_shot_rank(target_workspace uuid, target_production uuid)
returns table (shot_id uuid, scene_id uuid, scene_position bigint, shot_order bigint, shot_position bigint)
language sql stable security definer set search_path = '' as $$
  select sh.id, sh.scene_id, r.scene_position, sh.sort_order,
    row_number() over (order by coalesce(r.scene_position, 0), sh.sort_order, sh.created_at, sh.id)
  from tonde.shots sh
  left join tonde_private.ci_scene_rank(target_workspace, target_production) r on r.scene_id = sh.scene_id
  where sh.workspace_id = target_workspace and sh.production_id = target_production and sh.lifecycle = 'active';
$$;

revoke all on function tonde_private.ci_shot_rank(uuid,uuid) from public, anon, authenticated, service_role;


-- The live statements of a Production in Production order. A Scene's opening state sorts before
-- its Shots and its ending state sorts after them, so the timeline reads the way the film plays.
create or replace function tonde_private.ci_timeline(target_workspace uuid, target_production uuid)
returns table (
  state_id uuid, domain tonde.continuity_domain, subject_object_id uuid, subject_label text,
  trait text, anchor tonde.continuity_anchor, scene_id uuid, shot_id uuid,
  scene_label text, shot_label text, value text, transition tonde.continuity_transition,
  origin tonde.continuity_origin, epistemic text, confidence text, reason text,
  effective_scene bigint, effective_position bigint, position_label text, created_at timestamptz
)
language sql stable security definer set search_path = '' as $$
  with scene_order as (select * from tonde_private.ci_scene_rank(target_workspace, target_production)),
  shot_order as (select * from tonde_private.ci_shot_rank(target_workspace, target_production)),
  scene_shots as (
    select o.scene_id, min(o.shot_position) as first_shot, max(o.shot_position) as last_shot
    from shot_order o where o.scene_id is not null group by o.scene_id
  )
  select s.id, s.domain, s.subject_object_id, tonde_private.pi_label(target_workspace, s.subject_object_id),
    s.trait, s.anchor, s.scene_id, s.shot_id,
    (select sc.title from tonde.scenes sc where sc.id = s.scene_id),
    (select sh.title from tonde.shots sh where sh.id = s.shot_id),
    s.value, s.transition, s.origin, s.epistemic, s.confidence, s.reason,
    -- A Shot statement takes its place from the Shot's real position, so the timeline is ordered
    -- by where the object actually sits in the film rather than by what the caller supplied.
    case s.anchor
      when 'shot' then coalesce(o.scene_position, 0)
      when 'production' then 0
      else coalesce(so.scene_position, 0)
    end,
    case s.anchor
      when 'shot' then coalesce(o.shot_position, 0)
      when 'scene_opening' then coalesce(ss.first_shot, 0) - 1
      when 'scene_ending' then coalesce(ss.last_shot, 0) + 1
      else 0
    end,
    case s.anchor
      when 'production' then 'Production'
      when 'shot' then 'Shot ' || coalesce((select sh.title from tonde.shots sh where sh.id = s.shot_id), '')
      when 'scene_opening' then 'Scene ' || coalesce((select sc.title from tonde.scenes sc where sc.id = s.scene_id), '') || ' opening'
      else 'Scene ' || coalesce((select sc.title from tonde.scenes sc where sc.id = s.scene_id), '') || ' ending'
    end,
    s.created_at
  from tonde.continuity_states s
  left join scene_order so on so.scene_id = s.scene_id
  left join shot_order o on o.shot_id = s.shot_id
  left join scene_shots ss on ss.scene_id = s.scene_id
  where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null;
$$;

revoke all on function tonde_private.ci_timeline(uuid,uuid) from public, anon, authenticated, service_role;


-- A statement written after a check makes that check out of date. The marker is the same durable
-- artifact marker the rest of Production intelligence uses; nothing is deleted.
create or replace function tonde_private.ci_mark_stale(target_workspace uuid, target_production uuid, reason_text text, caused_by uuid)
returns void language plpgsql security definer set search_path = '' as $$
begin
  perform tonde_private.pi_mark_stale(target_workspace, target_production, target_production, 'continuity_analysis', null,
    left(coalesce(reason_text,''), 600), caused_by, null, null, null, 'stale');
end $$;

revoke all on function tonde_private.ci_mark_stale(uuid,uuid,text,uuid) from public, anon, authenticated, service_role;


-- 6. Writing a statement. The creator's current statement for a trait at a point is one live row:
-- an identical restatement refreshes it, a different value supersedes it and keeps the old one.
create or replace function tonde.continuity_state_set(target_workspace uuid, target_production uuid, state_record jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  desired_domain tonde.continuity_domain; desired_anchor tonde.continuity_anchor; desired_transition tonde.continuity_transition;
  desired_epistemic text; desired_confidence text; desired_trait text; desired_value text;
  subject_id uuid; scene_ref uuid; shot_ref uuid; supersedes uuid; saved tonde.continuity_states; existing tonde.continuity_states;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(state_record) <> 'object' then
    raise exception 'A continuity statement must be a JSON object' using errcode = '22023';
  end if;
  -- Validate the controlled vocabulary before casting: an unknown code is a rejected request,
  -- not a database type error.
  if coalesce(nullif(state_record ->> 'domain',''), 'other') not in
      ('character','wardrobe','prop','product','vehicle','injury','hair_makeup','weather','time_of_day',
       'environment','lighting','story_knowledge','dialogue_fact','screen_direction','eyeline',
       'camera_geography','position','product_condition','other') then
    raise exception 'Unsupported continuity domain' using errcode = '22023';
  end if;
  if coalesce(nullif(state_record ->> 'anchor',''), 'production') not in ('production','scene_opening','scene_ending','shot') then
    raise exception 'Unsupported continuity anchor' using errcode = '22023';
  end if;
  if coalesce(nullif(state_record ->> 'transition',''), 'baseline') not in ('baseline','continuous','changed') then
    raise exception 'Unsupported continuity transition' using errcode = '22023';
  end if;
  desired_domain := coalesce(nullif(state_record ->> 'domain',''), 'other')::tonde.continuity_domain;
  desired_anchor := coalesce(nullif(state_record ->> 'anchor',''), 'production')::tonde.continuity_anchor;
  desired_transition := coalesce(nullif(state_record ->> 'transition',''), 'baseline')::tonde.continuity_transition;
  desired_epistemic := coalesce(nullif(state_record ->> 'epistemic',''), 'observed');
  desired_confidence := coalesce(nullif(state_record ->> 'confidence',''), 'high');
  if desired_epistemic not in ('observed','estimated','recommended','unknown') then
    raise exception 'Unsupported epistemic status' using errcode = '22023';
  end if;
  if desired_confidence not in ('high','medium','low') then
    raise exception 'Unsupported confidence' using errcode = '22023';
  end if;
  desired_trait := tonde_private.ci_text(state_record, 'trait', 120, true);
  desired_value := tonde_private.ci_text(state_record, 'value', 400, true);
  subject_id := nullif(state_record ->> 'subject_object_id','')::uuid;
  scene_ref := nullif(state_record ->> 'scene_id','')::uuid;
  shot_ref := nullif(state_record ->> 'shot_id','')::uuid;
  if desired_anchor = 'shot' then
    select sh.scene_id into scene_ref from tonde.shots sh where sh.workspace_id = target_workspace
      and sh.production_id = target_production and sh.id = shot_ref and sh.lifecycle = 'active';
    if not found then
      raise exception 'The Shot for this statement is not in this Production' using errcode = '22023';
    end if;
  else
    shot_ref := null;
    if desired_anchor = 'production' then
      scene_ref := null;
    elsif scene_ref is null or not exists (select 1 from tonde.scenes sc where sc.workspace_id = target_workspace
      and sc.production_id = target_production and sc.id = scene_ref and sc.lifecycle = 'active') then
      raise exception 'The Scene for this statement is not in this Production' using errcode = '22023';
    end if;
  end if;
  if subject_id is not null and not exists (select 1 from tonde.objects o
      where o.workspace_id = target_workspace and o.id = subject_id) then
    raise exception 'The subject of this statement is not in this workspace' using errcode = '22023';
  end if;

  select * into existing from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null
      and s.domain = desired_domain and s.trait = desired_trait and s.anchor = desired_anchor
      and s.subject_object_id is not distinct from subject_id
      and s.scene_id is not distinct from scene_ref and s.shot_id is not distinct from shot_ref;
  if found then
    if existing.value = desired_value and existing.transition = desired_transition then
      update tonde.continuity_states s set
        reason = tonde_private.ci_text(state_record, 'reason', 600, false),
        note = tonde_private.ci_text(state_record, 'note', 400, false),
        epistemic = desired_epistemic, confidence = desired_confidence,
        evidence = coalesce(state_record -> 'evidence', '[]'::jsonb)
      where s.id = existing.id returning * into saved;
      return jsonb_build_object('state_id', saved.id, 'updated', true, 'superseded_state_id', null,
        'anchor', saved.anchor, 'trait', saved.trait, 'value', saved.value,
        'note', 'The statement was already recorded at this point, so it was refreshed in place.');
    end if;
    supersedes := existing.id;
  end if;

  -- Retire the older statement first: one live statement per trait per point is a constraint, not
  -- a convention, and the history row must exist before the new version takes its place.
  if supersedes is not null then
    update tonde.continuity_states s set retired_at = now(), retired_by = auth.uid(),
      retire_reason = left('Superseded by a newer statement at the same point in the Production.', 400)
    where s.id = supersedes;
  end if;
  insert into tonde.continuity_states(workspace_id, production_id, domain, subject_object_id, trait, anchor, scene_id, shot_id,
    value, transition, origin, epistemic, confidence, reason, evidence, note, supersedes_id)
  values (target_workspace, target_production, desired_domain, subject_id, desired_trait, desired_anchor, scene_ref, shot_ref,
    desired_value, desired_transition, 'declared', desired_epistemic, desired_confidence,
    tonde_private.ci_text(state_record, 'reason', 600, false),
    coalesce(state_record -> 'evidence', '[]'::jsonb),
    tonde_private.ci_text(state_record, 'note', 400, false), supersedes)
  returning * into saved;

  -- The marker names the real canonical object it can point at (the Scene or Shot), never a
  -- statement id, which is not an object in the registry.
  perform tonde_private.ci_mark_stale(target_workspace, target_production,
    'A continuity statement changed after this check was run.', coalesce(saved.shot_id, saved.scene_id));
  return jsonb_build_object('state_id', saved.id, 'updated', false, 'superseded_state_id', supersedes,
    'anchor', saved.anchor, 'trait', saved.trait, 'value', saved.value, 'transition', saved.transition,
    'note', case when supersedes is null then 'The statement is recorded.'
      else 'The previous statement at this point was kept and marked as superseded.' end);
end $$;


create or replace function tonde.continuity_state_retire(target_workspace uuid, target_production uuid, target_state uuid,
  reason_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.continuity_states;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into saved from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.id = target_state;
  if not found then raise exception 'That continuity statement is unavailable' using errcode = 'P0002'; end if;
  if saved.retired_at is not null then
    raise exception 'That continuity statement was already retired' using errcode = '23514';
  end if;
  update tonde.continuity_states s set retired_at = now(), retired_by = auth.uid(),
    retire_reason = left(coalesce(nullif(btrim(reason_text), ''), 'The creator retired this statement.'), 400)
  where s.id = saved.id;
  perform tonde_private.ci_mark_stale(target_workspace, target_production,
    'A continuity statement was retired after this check was run.', coalesce(saved.shot_id, saved.scene_id));
  return jsonb_build_object('state_id', saved.id, 'retired', true,
    'note', 'The statement is retired, not deleted: its history stays readable.');
end $$;


-- 7. Reading. Membership is re-checked in the database; knowing an id is not authorization.
create or replace function tonde.continuity_state_list(target_workspace uuid, target_production uuid, target_subject uuid default null,
  target_domain text default null, include_retired boolean default false, target_limit integer default 100,
  target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; live_count integer;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 100), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  select count(*) into total from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production
      and (include_retired or s.retired_at is null)
      and (target_subject is null or s.subject_object_id = target_subject)
      and (target_domain is null or s.domain = target_domain::tonde.continuity_domain);
  select count(*) into live_count from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null;
  select coalesce(jsonb_agg(jsonb_build_object(
      'state_id', s.id, 'domain', s.domain, 'subject_object_id', s.subject_object_id,
      'subject_label', tonde_private.pi_label(target_workspace, s.subject_object_id),
      'subject_kind', (select o.kind from tonde.objects o where o.workspace_id = target_workspace and o.id = s.subject_object_id),
      'trait', s.trait, 'anchor', s.anchor, 'scene_id', s.scene_id, 'shot_id', s.shot_id,
      'scene_label', (select sc.title from tonde.scenes sc where sc.id = s.scene_id),
      'shot_label', (select sh.title from tonde.shots sh where sh.id = s.shot_id),
      'value', s.value, 'transition', s.transition, 'origin', s.origin, 'epistemic', s.epistemic,
      'confidence', s.confidence, 'reason', s.reason, 'note', s.note,
      'retired', s.retired_at is not null, 'retire_reason', s.retire_reason, 'revision', s.revision,
      'created_at', s.created_at) order by s.created_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production
      and (include_retired or s.retired_at is null)
      and (target_subject is null or s.subject_object_id = target_subject)
      and (target_domain is null or s.domain = target_domain::tonde.continuity_domain)
    order by s.created_at desc limit lim offset off) s;
  return jsonb_build_object('items', items, 'total', total, 'live', live_count, 'limit', lim, 'offset', off,
    'truncated', total > off + lim);
end $$;


-- The timeline of one subject: what changed, when, and why.
create or replace function tonde.continuity_chain(target_workspace uuid, target_production uuid, target_subject uuid,
  target_domain text default null, target_trait text default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare items jsonb; statement_count integer;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select coalesce(jsonb_agg(jsonb_build_object(
      'state_id', t.state_id, 'domain', t.domain, 'trait', t.trait, 'anchor', t.anchor,
      'position_label', t.position_label, 'scene_id', t.scene_id, 'shot_id', t.shot_id,
      'value', t.value, 'transition', t.transition, 'origin', t.origin, 'epistemic', t.epistemic,
      'confidence', t.confidence, 'reason', t.reason) order by t.effective_scene, t.effective_position, t.created_at, t.state_id),
    '[]'::jsonb), count(*)
    into items, statement_count
  from tonde_private.ci_timeline(target_workspace, target_production) t
  where t.subject_object_id = target_subject
    and (target_domain is null or t.domain = target_domain::tonde.continuity_domain)
    and (target_trait is null or t.trait = target_trait);
  return jsonb_build_object('subject_object_id', target_subject,
    'subject_label', tonde_private.pi_label(target_workspace, target_subject),
    'statements', coalesce(items, '[]'::jsonb), 'statement_count', coalesce(statement_count, 0),
    'note', 'This is the recorded timeline of the subject. It lists declared statements in Production order.');
end $$;


-- 8. The check. Deterministic, bounded, and truthful about what it did not look at.
create or replace function tonde.continuity_check(target_workspace uuid, target_production uuid, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current_production tonde.productions; saved tonde.continuity_checks;
  live_states integer; retired_states integer; watermark timestamptz;
  critical_found integer; warning_found integer; info_found integer; total_found integer;
  verdict_value text; explanation_text text;
  limitations constant text := 'This check compares the continuity statements recorded for this Production. It does not analyse media, so a clean result means the declarations agree, not that the footage is consistent.';
begin
  current_production := tonde_private.studio_guard(target_workspace, target_production, null);
  select count(*) filter (where s.retired_at is null), count(*) filter (where s.retired_at is not null), max(s.updated_at)
    into live_states, retired_states, watermark
  from tonde.continuity_states s
  where s.workspace_id = target_workspace and s.production_id = target_production;
  insert into tonde.continuity_checks(workspace_id, production_id, production_revision, state_count, state_watermark, note, limitations)
  values (target_workspace, target_production, current_production.revision, coalesce(live_states, 0), watermark,
    left(coalesce(note_text, ''), 400), limitations)
  returning * into saved;

  -- An undeclared value change inside one Scene: a caution the creator should confirm.
  with lagged as (
    select t.*, lag(t.value) over w as previous_value, lag(t.state_id) over w as previous_state_id,
      lag(t.effective_scene) over w as previous_scene
    from tonde_private.ci_timeline(target_workspace, target_production) t
    window w as (partition by t.subject_object_id, t.domain, t.trait
      order by t.effective_scene, t.effective_position, t.created_at, t.state_id)
  )
  insert into tonde.continuity_findings(workspace_id, production_id, check_id, kind, severity, domain, subject_object_id, trait,
    earlier_state_id, later_state_id, at_scene_id, at_shot_id, explanation, suggested_resolution, origin, epistemic, confidence, evidence)
  select target_workspace, target_production, saved.id, 'unexplained_change', 'warning', g.domain, g.subject_object_id, g.trait,
    g.previous_state_id, g.state_id, g.scene_id, g.shot_id,
    'The statement for "' || g.trait || '" at ' || g.position_label || ' says "' || g.value
      || '" but the earlier statement said "' || g.previous_value || '", and no change was declared.',
    'Declare the change explicitly with a reason, or correct the statement so the trait keeps one value.',
    'derived', 'observed', 'high',
    jsonb_build_array(jsonb_build_object('kind', 'continuity_state', 'object_id', g.previous_state_id),
      jsonb_build_object('kind', 'continuity_state', 'object_id', g.state_id))
  from lagged g
  where g.previous_state_id is not null and g.previous_value is distinct from g.value
    and g.transition <> 'changed'
    and coalesce(g.previous_scene, -1) = coalesce(g.effective_scene, -1);

  -- The same undeclared change across a Scene boundary: the state did not carry over.
  with lagged as (
    select t.*, lag(t.value) over w as previous_value, lag(t.state_id) over w as previous_state_id,
      lag(t.position_label) over w as previous_label, lag(t.effective_scene) over w as previous_scene
    from tonde_private.ci_timeline(target_workspace, target_production) t
    window w as (partition by t.subject_object_id, t.domain, t.trait
      order by t.effective_scene, t.effective_position, t.created_at, t.state_id)
  )
  insert into tonde.continuity_findings(workspace_id, production_id, check_id, kind, severity, domain, subject_object_id, trait,
    earlier_state_id, later_state_id, at_scene_id, at_shot_id, explanation, suggested_resolution, origin, epistemic, confidence, evidence)
  select target_workspace, target_production, saved.id, 'boundary_break', 'critical', g.domain, g.subject_object_id, g.trait,
    g.previous_state_id, g.state_id, g.scene_id, g.shot_id,
    'The trait "' || g.trait || '" was "' || g.previous_value || '" at ' || coalesce(g.previous_label, 'an earlier point')
      || ' and is "' || g.value || '" at ' || g.position_label || ' across a Scene boundary, and no change was declared.',
    'Confirm the state actually carries over, or declare the change and the reason for it.',
    'derived', 'observed', 'high',
    jsonb_build_array(jsonb_build_object('kind', 'continuity_state', 'object_id', g.previous_state_id),
      jsonb_build_object('kind', 'continuity_state', 'object_id', g.state_id))
  from lagged g
  where g.previous_state_id is not null and g.previous_value is distinct from g.value
    and g.transition <> 'changed'
    and coalesce(g.previous_scene, -1) <> coalesce(g.effective_scene, -1);

  -- A declared change with no reason: later Shots cannot be checked against why it happened.
  insert into tonde.continuity_findings(workspace_id, production_id, check_id, kind, severity, domain, subject_object_id, trait,
    earlier_state_id, later_state_id, at_scene_id, at_shot_id, explanation, suggested_resolution, origin, epistemic, confidence, evidence)
  select target_workspace, target_production, saved.id, 'missing_reason', 'warning', t.domain, t.subject_object_id, t.trait,
    null, t.state_id, t.scene_id, t.shot_id,
    'The change of "' || t.trait || '" to "' || t.value || '" at ' || t.position_label || ' was declared without a reason.',
    'Record why the trait changed, so later Shots can be checked against it.',
    'derived', 'observed', 'high',
    jsonb_build_array(jsonb_build_object('kind', 'continuity_state', 'object_id', t.state_id))
  from tonde_private.ci_timeline(target_workspace, target_production) t
  where t.transition = 'changed' and btrim(t.reason) = '';

  -- A declared change to a subject the creator protected with a continuity lock.
  insert into tonde.continuity_findings(workspace_id, production_id, check_id, kind, severity, domain, subject_object_id, trait,
    earlier_state_id, later_state_id, at_scene_id, at_shot_id, explanation, suggested_resolution, origin, epistemic, confidence, evidence)
  select target_workspace, target_production, saved.id, 'lock_conflict', 'critical', t.domain, t.subject_object_id, t.trait,
    null, t.state_id, t.scene_id, t.shot_id,
    'The declared change of "' || t.trait || '" at ' || t.position_label || ' touches '
      || coalesce(t.subject_label, 'a subject') || ', which is protected by a continuity lock ('
      || l.priority::text || ').',
    'Propose the change explicitly, or unlock the scope first: a locked decision is not changed incidentally.',
    'derived', 'observed', 'high',
    jsonb_build_array(jsonb_build_object('kind', 'continuity_lock', 'object_id', l.id),
      jsonb_build_object('kind', 'continuity_state', 'object_id', t.state_id))
  from tonde_private.ci_timeline(target_workspace, target_production) t
  join tonde.ai_continuity_locks l on l.workspace_id = target_workspace and l.production_id = target_production
    and l.locked and l.subject_id is not null and l.subject_id = t.subject_object_id
  where t.transition = 'changed';

  -- The last recorded statement for a trait is a declared change and work continues after it:
  -- continuity for that trait is unknown from there on, and it says so instead of guessing.
  with timeline as (select * from tonde_private.ci_timeline(target_workspace, target_production)),
  last_statement as (
    select distinct on (t.subject_object_id, t.domain, t.trait) t.*
    from timeline t
    order by t.subject_object_id, t.domain, t.trait, t.effective_scene desc, t.effective_position desc, t.created_at desc, t.state_id desc
  )
  insert into tonde.continuity_findings(workspace_id, production_id, check_id, kind, severity, domain, subject_object_id, trait,
    earlier_state_id, later_state_id, at_scene_id, at_shot_id, explanation, suggested_resolution, origin, epistemic, confidence, evidence)
  select target_workspace, target_production, saved.id, 'unverified_after', 'info', l.domain, l.subject_object_id, l.trait,
    l.state_id, null, l.scene_id, l.shot_id,
    'The last recorded statement for "' || l.trait || '" is a declared change at ' || l.position_label
      || ' and there is later work in the Production with no statement after it.',
    'Add the state for the later work, or accept that continuity for this trait is unknown after that point.',
    'derived', 'observed', 'high',
    jsonb_build_array(jsonb_build_object('kind', 'continuity_state', 'object_id', l.state_id))
  from last_statement l
  where l.transition = 'changed'
    and exists (select 1 from tonde_private.ci_shot_rank(target_workspace, target_production) o
      where (coalesce(o.scene_position, 0), o.shot_position) > (coalesce(l.effective_scene, 0), coalesce(l.effective_position, 0)));

  select count(*) filter (where f.severity = 'critical'), count(*) filter (where f.severity = 'warning'),
    count(*) filter (where f.severity = 'info'), count(*)
    into critical_found, warning_found, info_found, total_found
  from tonde.continuity_findings f
  where f.workspace_id = target_workspace and f.check_id = saved.id;
  verdict_value := case when coalesce(critical_found, 0) > 0 then 'conflict'
    when coalesce(warning_found, 0) > 0 then 'needs_review' else 'consistent' end;
  explanation_text := case
    when coalesce(live_states, 0) = 0 then 'No continuity statements are recorded for this Production, so there was nothing to compare.'
    when coalesce(total_found, 0) = 0 then 'The recorded continuity statements agree at every point they describe.'
    when coalesce(critical_found, 0) > 0 then coalesce(critical_found, 0)::text || ' continuity conflict'
      || case when critical_found = 1 then '' else 's' end || ' need a creator decision.'
    when coalesce(warning_found, 0) > 0 then coalesce(warning_found, 0)::text || ' statement'
      || case when warning_found = 1 then '' else 's' end || ' should be confirmed.'
    else coalesce(info_found, 0)::text || ' trait' || case when info_found = 1 then '' else 's' end
      || ' have no statement after a declared change, so continuity there is unknown rather than consistent.'
    end;
  update tonde.continuity_checks c set finding_count = coalesce(total_found, 0),
    critical_count = coalesce(critical_found, 0), warning_count = coalesce(warning_found, 0),
    info_count = coalesce(info_found, 0),
    counts = jsonb_build_object('critical', coalesce(critical_found, 0), 'warning', coalesce(warning_found, 0),
      'info', coalesce(info_found, 0), 'live_states', coalesce(live_states, 0), 'retired_states', coalesce(retired_states, 0)),
    verdict = verdict_value, explanation = explanation_text
  where c.id = saved.id returning * into saved;

  -- A fresh check addresses the recorded analysis: the marker closes, the history stays.
  update tonde.stale_artifacts a set state = 'current', resolved_at = now(), resolved_by = auth.uid()
    where a.workspace_id = target_workspace and a.production_id = target_production
      and a.artifact_kind = 'continuity_analysis' and a.object_id = target_production and a.state <> 'current';

  return jsonb_build_object('check_id', saved.id, 'verdict', saved.verdict, 'counts', saved.counts,
    'finding_count', saved.finding_count, 'state_count', saved.state_count, 'production_revision', saved.production_revision,
    'state_watermark', saved.state_watermark, 'explanation', saved.explanation, 'limitations', saved.limitations,
    'created_at', saved.created_at,
    'findings', (select coalesce(jsonb_agg(jsonb_build_object(
        'finding_id', f.id, 'kind', f.kind, 'severity', f.severity, 'domain', f.domain, 'trait', f.trait,
        'subject_object_id', f.subject_object_id, 'subject_label', tonde_private.pi_label(target_workspace, f.subject_object_id),
        'earlier_state_id', f.earlier_state_id, 'later_state_id', f.later_state_id,
        'scene_id', f.at_scene_id, 'shot_id', f.at_shot_id,        'explanation', f.explanation, 'suggested_resolution', f.suggested_resolution, 'origin', f.origin, 'state', f.state,
        'epistemic', f.epistemic, 'confidence', f.confidence, 'evidence', f.evidence, 'rationale', f.rationale,
        'created_at', f.created_at) order by
          case f.severity when 'critical' then 0 when 'warning' then 1 else 2 end, f.created_at), '[]'::jsonb)
      from tonde.continuity_findings f where f.workspace_id = target_workspace and f.check_id = saved.id));
end $$;


-- 9. Findings: read, and a creator decision. Nothing here approves work or rewrites a statement.
create or replace function tonde.continuity_finding_list(target_workspace uuid, target_production uuid, target_state text default null,
  target_severity text default null, target_check uuid default null, target_limit integer default 100,
  target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; latest uuid; latest_check jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 100), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  select c.id into latest from tonde.continuity_checks c
    where c.workspace_id = target_workspace and c.production_id = target_production
    order by c.created_at desc, c.id desc limit 1;
  -- Whether a check is still current is a comparison against the recorded statements, never a guess.
  select jsonb_build_object('check_id', c.id, 'verdict', c.verdict, 'counts', c.counts,
      'explanation', c.explanation, 'limitations', c.limitations, 'created_at', c.created_at,
      'state_count', c.state_count, 'state_watermark', c.state_watermark,
      'is_current', c.state_watermark is not distinct from (select max(s.updated_at) from tonde.continuity_states s
          where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null)
        and c.state_count = (select count(*) from tonde.continuity_states s
          where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null))
    into latest_check
  from tonde.continuity_checks c
  where c.workspace_id = target_workspace and c.production_id = target_production
    and c.id = coalesce(target_check, latest);
  select count(*) into total from tonde.continuity_findings f
    where f.workspace_id = target_workspace and f.production_id = target_production
      and (target_state is null or f.state = target_state::tonde.continuity_finding_state)
      and (target_severity is null or f.severity = target_severity)
      -- A recorded check's findings, or a proposal that belongs to no check. A proposal is never
      -- hidden merely because a deterministic check exists.
      and (f.check_id = coalesce(target_check, latest) or (target_check is null and f.check_id is null));
  select coalesce(jsonb_agg(jsonb_build_object(
      'finding_id', f.id, 'kind', f.kind, 'severity', f.severity, 'domain', f.domain, 'trait', f.trait,
      'subject_object_id', f.subject_object_id, 'subject_label', tonde_private.pi_label(target_workspace, f.subject_object_id),
      'earlier_state_id', f.earlier_state_id, 'later_state_id', f.later_state_id,
      'scene_id', f.at_scene_id, 'shot_id', f.at_shot_id, 'scene_label', (select sc.title from tonde.scenes sc where sc.id = f.at_scene_id),
      'shot_label', (select sh.title from tonde.shots sh where sh.id = f.at_shot_id),
      'explanation', f.explanation, 'suggested_resolution', f.suggested_resolution,
      'origin', f.origin, 'rationale', f.rationale, 'epistemic', f.epistemic, 'confidence', f.confidence,
      'evidence', f.evidence, 'state', f.state, 'resolution_note', f.resolution_note,
      'resolved_at', f.resolved_at, 'check_id', f.check_id, 'created_at', f.created_at) order by
        case f.severity when 'critical' then 0 when 'warning' then 1 else 2 end, f.created_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.continuity_findings f
    where f.workspace_id = target_workspace and f.production_id = target_production
      and (target_state is null or f.state = target_state::tonde.continuity_finding_state)
      and (target_severity is null or f.severity = target_severity)
      and (f.check_id = coalesce(target_check, latest) or (target_check is null and f.check_id is null))
    order by case f.severity when 'critical' then 0 when 'warning' then 1 else 2 end, f.created_at desc
    limit lim offset off) f;
  return jsonb_build_object('items', items, 'total', total, 'limit', lim, 'offset', off, 'truncated', total > off + lim,
    'check', coalesce(latest_check, 'null'::jsonb), 'checks_available', (select count(*) from tonde.continuity_checks c
      where c.workspace_id = target_workspace and c.production_id = target_production),
    'open_count', (select count(*) from tonde.continuity_findings f
      where f.workspace_id = target_workspace and f.production_id = target_production and f.state in ('open','acknowledged')),
    'note', 'A finding describes the recorded statements. Resolving it is a creator decision and does not change the statements.');
end $$;


create or replace function tonde.continuity_finding_update(target_workspace uuid, target_production uuid, target_finding uuid,
  desired_state text, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.continuity_findings; desired tonde.continuity_finding_state;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if desired_state not in ('open','acknowledged','resolved','waived') then
    raise exception 'Unsupported finding state' using errcode = '22023';
  end if;
  desired := desired_state::tonde.continuity_finding_state;
  select * into saved from tonde.continuity_findings f
    where f.workspace_id = target_workspace and f.production_id = target_production and f.id = target_finding;
  if not found then raise exception 'That continuity finding is unavailable' using errcode = 'P0002'; end if;
  update tonde.continuity_findings f set state = desired,
    resolution_note = tonde_private.ci_text(jsonb_build_object('note', note_text), 'note', 800, false),
    resolved_by = case when desired in ('resolved','waived') then auth.uid() else null end,
    resolved_at = case when desired in ('resolved','waived') then now() else null end
  where f.id = saved.id returning * into saved;
  return jsonb_build_object('finding_id', saved.id, 'state', saved.state, 'resolution_note', saved.resolution_note,
    'resolved_at', saved.resolved_at,
    'note', 'The finding was recorded. The continuity statements and any approval are unchanged.');
end $$;


-- An inferred proposal. It can never claim to be an observation, and it cannot resolve itself.
create or replace function tonde.continuity_finding_record(target_workspace uuid, target_production uuid, finding_record jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  desired_kind tonde.continuity_finding_kind; desired_domain tonde.continuity_domain; desired_severity text;
  desired_epistemic text; desired_confidence text; subject_id uuid; scene_ref uuid; shot_ref uuid;
  explanation_text text; resolution_text text; rationale_text text; evidence_value jsonb; saved tonde.continuity_findings;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(finding_record) <> 'object' then
    raise exception 'A continuity proposal must be a JSON object' using errcode = '22023';
  end if;
  if coalesce(nullif(finding_record ->> 'kind',''), 'unexplained_change') not in
      ('unexplained_change','boundary_break','missing_reason','lock_conflict','unverified_after') then
    raise exception 'Unsupported continuity finding kind' using errcode = '22023';
  end if;
  if coalesce(nullif(finding_record ->> 'domain',''), 'other') not in
      ('character','wardrobe','prop','product','vehicle','injury','hair_makeup','weather','time_of_day',
       'environment','lighting','story_knowledge','dialogue_fact','screen_direction','eyeline',
       'camera_geography','position','product_condition','other') then
    raise exception 'Unsupported continuity domain' using errcode = '22023';
  end if;
  desired_kind := coalesce(nullif(finding_record ->> 'kind',''), 'unexplained_change')::tonde.continuity_finding_kind;
  desired_domain := coalesce(nullif(finding_record ->> 'domain',''), 'other')::tonde.continuity_domain;
  desired_severity := coalesce(nullif(finding_record ->> 'severity',''), 'info');
  desired_epistemic := coalesce(nullif(finding_record ->> 'epistemic',''), 'estimated');
  desired_confidence := coalesce(nullif(finding_record ->> 'confidence',''), 'low');
  if desired_severity not in ('info','warning','critical') then
    raise exception 'Unsupported severity' using errcode = '22023';
  end if;
  -- A proposal is an estimate or a recommendation. Observation requires evidence this path cannot produce.
  if desired_epistemic not in ('estimated','recommended','unknown') then
    raise exception 'A proposal cannot claim an observation' using errcode = '23514';
  end if;
  if desired_confidence not in ('high','medium','low') then
    raise exception 'Unsupported confidence' using errcode = '22023';
  end if;
  explanation_text := tonde_private.ci_text(finding_record, 'explanation', 1200, true);
  resolution_text := tonde_private.ci_text(finding_record, 'suggested_resolution', 1200, false);
  rationale_text := tonde_private.ci_text(finding_record, 'rationale', 1200, true);
  evidence_value := coalesce(finding_record -> 'evidence', '[]'::jsonb);
  if jsonb_typeof(evidence_value) <> 'array' or jsonb_array_length(evidence_value) = 0 then
    raise exception 'An estimated proposal must disclose its basis' using errcode = '23514';
  end if;
  subject_id := nullif(finding_record ->> 'subject_object_id','')::uuid;
  scene_ref := nullif(finding_record ->> 'scene_id','')::uuid;
  shot_ref := nullif(finding_record ->> 'shot_id','')::uuid;
  if subject_id is not null and not exists (select 1 from tonde.objects o
      where o.workspace_id = target_workspace and o.id = subject_id) then
    raise exception 'The subject of this proposal is not in this workspace' using errcode = '22023';
  end if;
  if scene_ref is not null and not exists (select 1 from tonde.scenes sc
      where sc.workspace_id = target_workspace and sc.production_id = target_production and sc.id = scene_ref) then
    raise exception 'The Scene of this proposal is not in this Production' using errcode = '22023';
  end if;
  if shot_ref is not null and not exists (select 1 from tonde.shots sh
      where sh.workspace_id = target_workspace and sh.production_id = target_production and sh.id = shot_ref) then
    raise exception 'The Shot of this proposal is not in this Production' using errcode = '22023';
  end if;
  insert into tonde.continuity_findings(workspace_id, production_id, check_id, kind, severity, domain, subject_object_id, trait,
    at_scene_id, at_shot_id, explanation, suggested_resolution, origin, rationale, epistemic, confidence, evidence, state)
  values (target_workspace, target_production, null, desired_kind, desired_severity, desired_domain, subject_id,
    tonde_private.ci_text(finding_record, 'trait', 120, false), scene_ref, shot_ref, explanation_text, resolution_text,
    'inferred', rationale_text, desired_epistemic, desired_confidence, evidence_value, 'open')
  returning * into saved;
  return jsonb_build_object('finding_id', saved.id, 'state', saved.state, 'origin', saved.origin,
    'epistemic', saved.epistemic, 'confidence', saved.confidence,
    'note', 'This is a proposal, not a finding of fact. It does not change any continuity statement.');
end $$;


-- 10. Summary: the readiness input, and the honest answer to "is the last check still true?".
create or replace function tonde.continuity_summary(target_workspace uuid, target_production uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  live_states integer; retired_states integer; subject_count integer; domains jsonb;
  latest tonde.continuity_checks; current_watermark timestamptz; current_count integer;
  open_findings integer; acknowledged_findings integer; critical_open integer; marker_state text;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select count(*) filter (where s.retired_at is null), count(*) filter (where s.retired_at is not null),
    count(distinct s.subject_object_id) filter (where s.retired_at is null and s.subject_object_id is not null),
    max(s.updated_at)
    into live_states, retired_states, subject_count, current_watermark
  from tonde.continuity_states s
  where s.workspace_id = target_workspace and s.production_id = target_production;
  select count(*) into current_count from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null;
  select coalesce(jsonb_agg(jsonb_build_object('domain', d.domain, 'count', d.count) order by d.count desc, d.domain), '[]'::jsonb)
    into domains
  from (select s.domain, count(*) as count from tonde.continuity_states s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null
    group by s.domain) d;
  select * into latest from tonde.continuity_checks c
    where c.workspace_id = target_workspace and c.production_id = target_production
    order by c.created_at desc, c.id desc limit 1;
  select count(*) filter (where f.state = 'open'), count(*) filter (where f.state = 'acknowledged'),
    count(*) filter (where f.state in ('open','acknowledged') and f.severity = 'critical')
    into open_findings, acknowledged_findings, critical_open
  from tonde.continuity_findings f
  where f.workspace_id = target_workspace and f.production_id = target_production;
  select a.state::text into marker_state from tonde.stale_artifacts a
    where a.workspace_id = target_workspace and a.production_id = target_production
      and a.artifact_kind = 'continuity_analysis' and a.object_id = target_production
    order by a.created_at desc limit 1;
  return jsonb_build_object(
    'live_states', coalesce(live_states, 0), 'retired_states', coalesce(retired_states, 0),
    'subject_count', coalesce(subject_count, 0), 'domains', domains,
    'check', case when latest.id is null then 'null'::jsonb else jsonb_build_object(
      'check_id', latest.id, 'verdict', latest.verdict, 'counts', latest.counts, 'explanation', latest.explanation,
      'limitations', latest.limitations, 'created_at', latest.created_at,
      'is_current', latest.state_watermark is not distinct from current_watermark and latest.state_count = coalesce(current_count, 0),
      'state_count_at_check', latest.state_count) end,
    'findings', jsonb_build_object('open', coalesce(open_findings, 0), 'acknowledged', coalesce(acknowledged_findings, 0),
      'critical_open', coalesce(critical_open, 0)),
    'analysis_stale', coalesce(marker_state, 'none') in ('stale','conflicted'),
    'limitations', 'Continuity here is what the Production records. It is not a claim about analysed media, and an unrecorded trait is unknown rather than consistent.');
end $$;


-- 11. RLS. Every new table is workspace-isolated; enabling RLS is not optional.
do $$ declare item text; begin
  foreach item in array array['continuity_states','continuity_checks','continuity_findings'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select, insert, update on tonde.%I to authenticated', item);
  end loop;
end $$;


-- 12. Mutation guards: identity stays immutable and no statement is rewritten by an edit.
do $$ declare item text; begin
  foreach item in array array['continuity_states','continuity_checks','continuity_findings'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;


-- 13. A changed Scene or Shot makes the recorded continuity analysis out of date. Nothing is
-- deleted and no statement is touched: the marker says the analysis needs to run again.
create or replace function tonde_private.ci_stale_on_change() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if to_jsonb(new) - array['revision','updated_at'] is not distinct from to_jsonb(old) - array['revision','updated_at'] then
    return new;
  end if;
  perform tonde_private.ci_mark_stale(new.workspace_id, new.production_id,
    'The ' || tg_argv[0] || ' changed after this continuity analysis was run.', new.id);
  return new;
end $$;

revoke all on function tonde_private.ci_stale_on_change() from public, anon, authenticated, service_role;

drop trigger if exists zz_continuity_on_scene_change on tonde.scenes;
create trigger zz_continuity_on_scene_change after update on tonde.scenes
  for each row execute function tonde_private.ci_stale_on_change('Scene');

drop trigger if exists zz_continuity_on_shot_change on tonde.shots;
create trigger zz_continuity_on_shot_change after update on tonde.shots
  for each row execute function tonde_private.ci_stale_on_change('Shot');


-- 14. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.continuity_state_set(uuid,uuid,jsonb),
  tonde.continuity_state_retire(uuid,uuid,uuid,text),
  tonde.continuity_state_list(uuid,uuid,uuid,text,boolean,integer,integer),
  tonde.continuity_chain(uuid,uuid,uuid,text,text),
  tonde.continuity_check(uuid,uuid,text),
  tonde.continuity_finding_list(uuid,uuid,text,text,uuid,integer,integer),
  tonde.continuity_finding_update(uuid,uuid,uuid,text,text),
  tonde.continuity_finding_record(uuid,uuid,jsonb),
  tonde.continuity_summary(uuid,uuid)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.continuity_state_set(uuid,uuid,jsonb),
  tonde.continuity_state_retire(uuid,uuid,uuid,text),
  tonde.continuity_state_list(uuid,uuid,uuid,text,boolean,integer,integer),
  tonde.continuity_chain(uuid,uuid,uuid,text,text),
  tonde.continuity_check(uuid,uuid,text),
  tonde.continuity_finding_list(uuid,uuid,text,text,uuid,integer,integer),
  tonde.continuity_finding_update(uuid,uuid,uuid,text,text),
  tonde.continuity_finding_record(uuid,uuid,jsonb),
  tonde.continuity_summary(uuid,uuid)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050021_production_memory.sql
-- ==========================================================================

-- Additive migration: Prompt 9C Production memory and structured search.
-- Production memory is STRUCTURED, INSPECTABLE production knowledge, not hidden conversational
-- memory. Every remembered item says what it says, where it came from, which scope it applies to,
-- whether a creator confirmed it, and whether it is still in force. Nothing here profiles the
-- creator in the background and nothing is applied behind their back.
--
-- Knowledge is NOT a duplicate of canonical state. A memory item points at the real object and
-- revision it was drawn from; it never becomes a second copy of a Character, a plan or a decision.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
-- The source IS the authority tier, in the order the constitution fixes: a current creator
-- instruction outranks a current Production decision, which outranks an explicit saved
-- preference, which outranks a historical pattern, which outranks an inference.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.memory_scope as enum ('production','series','workspace')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.memory_kind as enum
  ('preference','decision','pattern','technique','setup_fact','asset_usage','model_outcome','series_rule','correction','other')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.memory_source as enum
  ('creator_instruction','production_decision','saved_preference','historical_pattern','inference')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

-- Declared = the creator wrote it. Accepted = the creator accepted a candidate. Inferred = TONDE
-- derived it and nobody has confirmed it.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.memory_origin as enum ('declared','accepted','inferred')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Memory policies. One explicit row per scope when the creator sets one. The default, when no
-- row exists, is recorded in mi_policy: candidates may be RECORDED (recording is not saving) and
-- nothing is accepted automatically. An inferred successful pattern becomes reusable memory only
-- through this policy or through an explicit creator decision.
create table if not exists tonde.memory_policies (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references tonde.workspaces(id) on delete restrict,
  scope tonde.memory_scope not null,
  production_id uuid, series_id uuid,
  candidate_capture boolean not null default true,
  auto_accept_candidates boolean not null default false,
  note text not null default '' check (length(note) <= 600),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  check ((scope = 'production' and production_id is not null and series_id is null)
      or (scope = 'series' and series_id is not null)
      or (scope = 'workspace' and production_id is null and series_id is null)),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, series_id) references tonde.series(workspace_id, id) on delete restrict
);

create unique index if not exists memory_policies_identity on tonde.memory_policies
  (workspace_id, scope, coalesce(production_id, '00000000-0000-0000-0000-000000000000'::uuid),
   coalesce(series_id, '00000000-0000-0000-0000-000000000000'::uuid));


-- 3. Successful-pattern candidates. A candidate is a PROPOSAL drawn from real evidence: the
-- object and revision it was observed on, how many times it was observed, and the basis. It never
-- claims creator authority and it changes no behaviour until it is accepted.
create table if not exists tonde.memory_candidates (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references tonde.workspaces(id) on delete restrict,
  production_id uuid not null,
  scope tonde.memory_scope not null default 'production',
  kind tonde.memory_kind not null,
  subject_key text not null check (length(btrim(subject_key)) between 1 and 160),
  statement text not null check (length(btrim(statement)) between 1 and 600),
  proposed_source tonde.memory_source not null default 'historical_pattern',
  basis jsonb not null default '[]'::jsonb
    check (jsonb_typeof(basis) = 'array' and jsonb_array_length(basis) >= 1),
  observed_count integer not null default 1 check (observed_count >= 1),
  source_object_id uuid not null,
  source_revision integer not null check (source_revision > 0),
  state tonde.proposal_state not null default 'proposed',
  decided_by uuid, decided_at timestamptz,
  decision_note text not null default '' check (length(decision_note) <= 800),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  -- A candidate may never propose creator authority: only a creator writes an instruction.
  check (proposed_source <> 'creator_instruction'),
  check (state = 'proposed' or decided_at is not null),
  check (scope = 'production'),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, source_object_id) references tonde.objects(workspace_id, id) on delete restrict
);

create unique index if not exists memory_candidates_open on tonde.memory_candidates
  (workspace_id, production_id, subject_key, kind, source_object_id) where state = 'proposed';

create index if not exists memory_candidates_recent on tonde.memory_candidates(workspace_id, production_id, state, created_at desc);


-- 4. Memory items. The inspectable record itself.
create table if not exists tonde.memory_items (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references tonde.workspaces(id) on delete restrict,
  production_id uuid, series_id uuid,
  scope tonde.memory_scope not null,
  kind tonde.memory_kind not null,
  subject_key text not null check (length(btrim(subject_key)) between 1 and 160),
  statement text not null check (length(btrim(statement)) between 1 and 600),
  source tonde.memory_source not null,
  origin tonde.memory_origin not null,
  rationale text not null default '' check (length(rationale) <= 800),
  evidence jsonb not null default '[]'::jsonb check (jsonb_typeof(evidence) = 'array'),
  source_object_id uuid, source_revision integer,
  candidate_id uuid,
  confirmed_by uuid, confirmed_at timestamptz,
  state tonde.lifecycle not null default 'active',
  supersedes_id uuid,
  retired_at timestamptz, retired_by uuid,
  retire_reason text not null default '' check (length(retire_reason) <= 400),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  -- Scope is a real scope: a Production item names its Production, a Series item its Series, a
  -- workspace item neither.
  check ((scope = 'production' and production_id is not null and series_id is null)
      or (scope = 'series' and series_id is not null)
      or (scope = 'workspace' and production_id is null and series_id is null)),
  -- Only an inference may be unconfirmed; creator-confirmed knowledge names who confirmed it.
  check (origin = 'inferred' or (confirmed_by is not null and confirmed_at is not null)),
  -- An inference discloses its basis.
  check (origin <> 'inferred' or jsonb_array_length(evidence) > 0),
  -- Human authority cannot be claimed by an inference.
  check (origin <> 'inferred' or source in ('saved_preference','historical_pattern','inference')),
  -- A pinned version comes with the object that version belongs to.
  check (source_revision is null or source_object_id is not null),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, series_id) references tonde.series(workspace_id, id) on delete restrict,
  foreign key (workspace_id, source_object_id) references tonde.objects(workspace_id, id) on delete restrict,
  foreign key (workspace_id, candidate_id) references tonde.memory_candidates(workspace_id, id) on delete restrict,
  foreign key (workspace_id, supersedes_id) references tonde.memory_items(workspace_id, id) on delete restrict
);

-- One live item per subject, per scope key, per authority tier. Restating the same tier replaces
-- the older statement of that tier; a HIGHER tier does not delete the lower one, it outranks it.
create unique index if not exists memory_items_live_identity on tonde.memory_items
  (workspace_id, scope, coalesce(production_id, '00000000-0000-0000-0000-000000000000'::uuid),
   coalesce(series_id, '00000000-0000-0000-0000-000000000000'::uuid), subject_key, source)
  where retired_at is null and state = 'active';

create index if not exists memory_items_by_subject on tonde.memory_items(workspace_id, production_id, subject_key, kind)
  where retired_at is null;

create index if not exists memory_items_by_scope on tonde.memory_items(workspace_id, scope, kind, updated_at desc);

create index if not exists memory_items_history on tonde.memory_items(workspace_id, subject_key, created_at desc);

create index if not exists memory_items_by_source on tonde.memory_items(workspace_id, source_object_id)
  where source_object_id is not null;


-- 5. Private helpers (not user-facing; reachable only through the security-definer RPCs below).
create or replace function tonde_private.mi_rank(target_source tonde.memory_source) returns integer
language sql immutable set search_path = '' as $$
  select case target_source::text
    when 'creator_instruction' then 1
    when 'production_decision' then 2
    when 'saved_preference' then 3
    when 'historical_pattern' then 4
    else 5 end;
$$;

revoke all on function tonde_private.mi_rank(tonde.memory_source) from public, anon, authenticated, service_role;


-- A caller-supplied uuid. A malformed id is a rejected request, not an unhandled cast error.
create or replace function tonde_private.mi_uuid(source jsonb, key_name text, required boolean default false)
returns uuid language plpgsql immutable set search_path = '' as $$
declare value text; parsed uuid;
begin
  value := btrim(coalesce(source ->> key_name, ''));
  if value = '' then
    if required then raise exception 'The field % is required', key_name using errcode = '22023'; end if;
    return null;
  end if;
  if value !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    raise exception 'The field % is not a valid identifier', key_name using errcode = '22023';
  end if;
  parsed := value::uuid;
  return parsed;
end $$;

revoke all on function tonde_private.mi_uuid(jsonb,text,boolean) from public, anon, authenticated, service_role;


-- Search patterns. Deterministic and disclosed: lower-cased, whitespace-split, at most six terms,
-- each at most 80 characters. There is no stemming, no fuzzy matching and no embedding.
create or replace function tonde_private.mi_patterns(source text) returns text[]
language sql immutable set search_path = '' as $$
  select coalesce(array_agg(t.pattern order by t.ord), '{}'::text[])
  from (
    select '%' || left(lower(btrim(u.part)), 80) || '%' as pattern, u.ord
    from unnest(regexp_split_to_array(coalesce(source, ''), '\s+')) with ordinality as u(part, ord)
    where btrim(u.part) <> ''
    order by u.ord
    limit 6
  ) t;
$$;

revoke all on function tonde_private.mi_patterns(text) from public, anon, authenticated, service_role;


-- The Series a Production belongs to, if any. Series memory applies to that Series only.
create or replace function tonde_private.mi_series_of(target_workspace uuid, target_production uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select e.series_id from tonde.series_episodes e
  where e.workspace_id = target_workspace and e.production_id = target_production limit 1;
$$;

revoke all on function tonde_private.mi_series_of(uuid,uuid) from public, anon, authenticated, service_role;


-- The effective memory policy for a scope. Resolution is most-specific-explicit-first and always
-- says which of the two it returned, so "capture is on" is never a guess.
create or replace function tonde_private.mi_policy(target_workspace uuid, target_scope tonde.memory_scope,
  target_production uuid, target_series uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare found_policy tonde.memory_policies;
begin
  select * into found_policy from tonde.memory_policies p
    where p.workspace_id = target_workspace and p.scope = target_scope
      and p.production_id is not distinct from case when target_scope = 'production' then target_production else null end
      and p.series_id is not distinct from case when target_scope = 'series' then target_series else null end
    order by p.revision desc limit 1;
  if found_policy.id is not null then
    return jsonb_build_object('scope', found_policy.scope, 'explicit', true,
      'candidate_capture', found_policy.candidate_capture,
      'auto_accept_candidates', found_policy.auto_accept_candidates,
      'note', found_policy.note, 'updated_at', found_policy.updated_at);
  end if;
  return jsonb_build_object('scope', target_scope, 'explicit', false,
    'candidate_capture', true, 'auto_accept_candidates', false,
    'note', 'Default: candidates may be recorded for your review, and nothing becomes memory automatically.',
    'updated_at', null);
end $$;

revoke all on function tonde_private.mi_policy(uuid,tonde.memory_scope,uuid,uuid) from public, anon, authenticated, service_role;


-- One search lane. Each lane is a fixed template chosen by name inside this function, so no caller
-- text ever becomes SQL. Returned rows are real object references with the reason they matched.
create or replace function tonde_private.mi_search_lane(target_workspace uuid, target_production uuid, lane text, q jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  patterns text[]; lim integer;
  f_asset uuid; f_asset_type text; f_env text; f_approval text; f_method text;
  f_provider text; f_model text; f_lens text; f_cstate text; f_severity text; f_domain text;
  f_rstate text; f_mkind text;
  items jsonb := '[]'::jsonb; total integer := 0;
begin
  lim := least(greatest(coalesce((q ->> 'limit')::integer, 50), 1), 100);
  patterns := tonde_private.mi_patterns(q ->> 'text');
  if cardinality(patterns) = 0 then patterns := null; end if;
  f_asset := nullif(q ->> '_resolved_asset_id','')::uuid;
  f_asset_type := nullif(q ->> 'asset_type','');
  f_env := nullif(btrim(coalesce(q ->> 'environment','')), '');
  f_approval := nullif(q ->> 'approval','');
  f_method := nullif(q ->> 'execution_method','');
  f_provider := nullif(q ->> 'provider','');
  f_model := nullif(q ->> 'model','');
  f_lens := nullif(q ->> 'lens','');
  f_cstate := nullif(q ->> 'continuity_state','');
  f_severity := nullif(q ->> 'severity','');
  f_domain := nullif(q ->> 'domain','');
  f_rstate := nullif(q ->> 'result_state','');
  f_mkind := nullif(q ->> 'memory_kind','');

  if lane = 'shot' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','shot','entity_id', sh.id,'label', sh.title,
        'context', coalesce(sc.title, 'Standalone Shot'),
        'detail', left(coalesce(nullif(sh.action,''), sh.description), 200),
        'approval', sh.approval::text, 'execution_method', sh.execution_method::text,
        'revision', sh.revision, 'locked', sh.locked_at is not null,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'shot text' end,
          case when f_asset is not null then 'Character/Product binding or Scene participant' end,
          case when f_approval is not null then 'approval' end,
          case when f_method is not null then 'execution face' end,
          case when f_provider is not null or f_model is not null then 'AI Attempt provider/model' end,
          case when f_lens is not null then 'Real plan lens name' end,
          case when f_cstate is not null or f_severity is not null or f_domain is not null then 'continuity finding' end,
          case when f_rstate is not null then 'Result state' end], null), ', '))
      order by coalesce(so.scene_position, 2147483647), sh.sort_order, sh.created_at), '[]'::jsonb), count(*)
      into items, total
    from tonde.shots sh
    left join tonde.scenes sc on sc.id = sh.scene_id
    left join tonde_private.ci_scene_rank(target_workspace, target_production) so on so.scene_id = sh.scene_id
    where sh.workspace_id = target_workspace and sh.production_id = target_production and sh.lifecycle = 'active'
      and (patterns is null or (sh.title || ' ' || sh.description || ' ' || sh.action) ilike all (patterns))
      and (f_approval is null
           or (f_approval = 'not_approved' and sh.approval::text not in ('approved','changed_after_approval'))
           or (f_approval <> 'not_approved' and sh.approval::text = f_approval))
      and (f_method is null or sh.execution_method::text = f_method)
      and (f_asset is null
           or exists (select 1 from tonde.scene_participants p
                where p.workspace_id = target_workspace and p.scene_id = sh.scene_id and p.asset_id = f_asset)
           or exists (select 1 from tonde.scope_bindings b
                where b.workspace_id = target_workspace and b.asset_id = f_asset
                  and (b.scope_object_id = sh.id or b.scope_object_id = sh.scene_id)))
      and (f_provider is null or exists (select 1 from tonde.ai_generation_attempts a
            where a.workspace_id = target_workspace and a.shot_id = sh.id and a.provider_key = f_provider))
      and (f_model is null or exists (select 1 from tonde.ai_generation_attempts a
            where a.workspace_id = target_workspace and a.shot_id = sh.id
              and (a.model_key = f_model or a.model_version = f_model)))
      and (f_lens is null or exists (select 1 from tonde.execution_plans p
            join tonde.production_resources r on r.id = p.lens_resource_id
            where p.workspace_id = target_workspace and p.shot_id = sh.id
              and p.execution_method = 'real' and r.name ilike '%' || f_lens || '%'))
      and ((f_cstate is null and f_severity is null and f_domain is null)
           or exists (select 1 from tonde.continuity_findings f
                where f.workspace_id = target_workspace and f.production_id = target_production
                  and (f.at_shot_id = sh.id or (sh.scene_id is not null and f.at_scene_id = sh.scene_id))
                  and (f_cstate is null or f.state::text = f_cstate)
                  and (f_severity is null or f.severity = f_severity)
                  and (f_domain is null or f.domain::text = f_domain)))
      and (f_rstate is null or exists (select 1 from tonde.results rs
            where rs.workspace_id = target_workspace and rs.shot_id = sh.id and rs.state::text = f_rstate));

  elsif lane = 'scene' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','scene','entity_id', sc.id,'label', sc.title,
        'context', coalesce(env.name, 'Production'),
        'detail', left(coalesce(nullif(sc.purpose,''), sc.description), 200),
        'approval', sc.approval::text, 'revision', sc.revision, 'locked', sc.locked_at is not null,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'scene text' end,
          case when f_asset is not null then 'Character/Product binding or Scene participant' end,
          case when f_env is not null then 'Environment name' end,
          case when f_approval is not null then 'approval' end,
          case when f_cstate is not null or f_severity is not null or f_domain is not null then 'continuity finding' end],
          null), ', '))
      order by coalesce(so.scene_position, 2147483647), sc.created_at), '[]'::jsonb), count(*)
      into items, total
    from tonde.scenes sc
    left join tonde.assets env on env.id = sc.environment_asset_id
    left join tonde_private.ci_scene_rank(target_workspace, target_production) so on so.scene_id = sc.id
    where sc.workspace_id = target_workspace and sc.production_id = target_production and sc.lifecycle = 'active'
      and (patterns is null or (sc.title || ' ' || sc.purpose || ' ' || sc.description) ilike all (patterns))
      and (f_approval is null
           or (f_approval = 'not_approved' and sc.approval::text not in ('approved','changed_after_approval'))
           or (f_approval <> 'not_approved' and sc.approval::text = f_approval))
      and (f_asset is null
           or exists (select 1 from tonde.scene_participants p
                where p.workspace_id = target_workspace and p.scene_id = sc.id and p.asset_id = f_asset)
           or exists (select 1 from tonde.scope_bindings b
                where b.workspace_id = target_workspace and b.asset_id = f_asset and b.scope_object_id = sc.id))
      and (f_env is null or env.name ilike '%' || f_env || '%')
      and ((f_cstate is null and f_severity is null and f_domain is null)
           or exists (select 1 from tonde.continuity_findings f
                where f.workspace_id = target_workspace and f.production_id = target_production
                  and f.at_scene_id = sc.id
                  and (f_cstate is null or f.state::text = f_cstate)
                  and (f_severity is null or f.severity = f_severity)
                  and (f_domain is null or f.domain::text = f_domain)));

  elsif lane = 'plan' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','execution_plan','entity_id', pl.id,
        'label', (case when pl.execution_method = 'ai' then 'AI plan' else 'Real plan' end) || ' - ' || sh.title,
        'context', sh.title,
        'detail', left(concat_ws(' - ', nullif(pl.shot_size,''), nullif(pl.movement,''), nullif(lens.name,'')), 200),
        'approval', pl.approval::text, 'execution_method', pl.execution_method::text,
        'provider', pl.provider, 'model', pl.model, 'revision', pl.revision, 'locked', pl.locked_at is not null,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'plan text' end,
          case when f_method is not null then 'execution face' end,
          case when f_lens is not null then 'lens resource name' end,
          case when f_provider is not null then 'plan provider' end,
          case when f_model is not null then 'plan model' end,
          case when f_approval is not null then 'approval' end], null), ', '))
      order by coalesce(so.scene_position, 2147483647), sh.sort_order, pl.created_at), '[]'::jsonb), count(*)
      into items, total
    from tonde.execution_plans pl
    join tonde.shots sh on sh.id = pl.shot_id
    left join tonde.production_resources lens on lens.id = pl.lens_resource_id
    left join tonde_private.ci_scene_rank(target_workspace, target_production) so on so.scene_id = sh.scene_id
    where pl.workspace_id = target_workspace and pl.production_id = target_production and sh.lifecycle = 'active'
      and (patterns is null or (pl.shot_size || ' ' || pl.camera_position || ' ' || pl.camera_height || ' '
            || pl.camera_angle || ' ' || pl.framing || ' ' || pl.composition || ' ' || pl.perspective_note || ' '
            || pl.movement || ' ' || pl.movement_purpose || ' ' || pl.lighting_intent || ' ' || pl.lighting_plan || ' '
            || pl.blocking || ' ' || pl.performance || ' ' || pl.product_direction || ' ' || pl.depth_of_field
            || ' ' || pl.focus_strategy || ' ' || pl.sound_plan) ilike all (patterns))
      and (f_method is null or pl.execution_method::text = f_method)
      and (f_lens is null or lens.name ilike '%' || f_lens || '%')
      and (f_provider is null or pl.provider = f_provider)
      and (f_model is null or pl.model = f_model)
      and (f_approval is null
           or (f_approval = 'not_approved' and pl.approval::text not in ('approved','changed_after_approval'))
           or (f_approval <> 'not_approved' and pl.approval::text = f_approval));

  elsif lane = 'result' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','result','entity_id', rs.id,
        'label', 'Result' || coalesce(' for ' || sh.title, ''),
        'context', coalesce(sh.title, 'Production'),
        'detail', rs.state::text || ' - ' || to_char(rs.created_at, 'YYYY-MM-DD')
          || case when rs.reference_id is not null then ' - compared against a Reference' else ' - no Reference' end,
        'state', rs.state::text, 'approval', rs.approval::text, 'revision', rs.revision,
        'has_plan', rs.execution_plan_id is not null, 'has_media', rs.media_id is not null,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'Shot text' end,
          case when f_rstate is not null then 'Result state' end,
          case when f_asset is not null then 'Shot Character/Product binding' end,
          case when f_approval is not null then 'approval' end], null), ', '))
      order by rs.created_at desc), '[]'::jsonb), count(*)
      into items, total
    from tonde.results rs
    left join tonde.shots sh on sh.id = rs.shot_id
    where rs.workspace_id = target_workspace and rs.production_id = target_production
      and (patterns is null or (coalesce(sh.title,'') || ' ' || coalesce(sh.action,'') || ' ' || coalesce(sh.description,'')) ilike all (patterns))
      and (f_rstate is null or rs.state::text = f_rstate)
      and (f_approval is null
           or (f_approval = 'not_approved' and rs.approval::text not in ('approved','changed_after_approval'))
           or (f_approval <> 'not_approved' and rs.approval::text = f_approval))
      and (f_asset is null or exists (select 1 from tonde.scene_participants p
            where p.workspace_id = target_workspace and p.scene_id = sh.scene_id and p.asset_id = f_asset));

  elsif lane = 'continuity_finding' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','continuity_finding','entity_id', f.id,
        'label', left(f.explanation, 200),
        'context', coalesce('Scene ' || sc.title, 'Shot ' || sh.title, 'Production'),
        'detail', f.severity || ' - ' || f.state::text || ' - ' || f.kind::text,
        'state', f.state::text, 'severity', f.severity, 'domain', f.domain::text, 'finding_kind', f.kind::text,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'finding text' end,
          case when f_cstate is not null then 'finding state' end,
          case when f_severity is not null then 'severity' end,
          case when f_domain is not null then 'domain' end], null), ', '))
      order by case f.severity when 'critical' then 0 when 'warning' then 1 else 2 end, f.created_at desc), '[]'::jsonb), count(*)
      into items, total
    from tonde.continuity_findings f
    left join tonde.scenes sc on sc.id = f.at_scene_id
    left join tonde.shots sh on sh.id = f.at_shot_id
    where f.workspace_id = target_workspace and f.production_id = target_production
      and (patterns is null or (f.explanation || ' ' || f.trait || ' ' || f.suggested_resolution || ' ' || f.rationale) ilike all (patterns))
      and (f_cstate is null or f.state::text = f_cstate)
      and (f_severity is null or f.severity = f_severity)
      and (f_domain is null or f.domain::text = f_domain)
      and (f_asset is null or exists (select 1 from tonde.scene_participants p
            where p.workspace_id = target_workspace and p.asset_id = f_asset
              and p.scene_id = coalesce(f.at_scene_id, sh.scene_id)));

  elsif lane = 'continuity_state' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','continuity_state','entity_id', s.id,
        'label', s.trait || ': ' || s.value,
        'context', coalesce('Scene ' || sc.title, 'Shot ' || sh.title, 'Production'),
        'detail', s.domain::text || ' - ' || s.transition::text || ' - ' || s.epistemic,
        'state', case when s.retired_at is null then 'live' else 'retired' end,
        'domain', s.domain::text, 'transition', s.transition::text,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'trait/value text' end,
          case when f_domain is not null then 'domain' end,
          case when f_asset is not null then 'subject' end], null), ', '))
      order by s.created_at desc), '[]'::jsonb), count(*)
      into items, total
    from tonde.continuity_states s
    left join tonde.scenes sc on sc.id = s.scene_id
    left join tonde.shots sh on sh.id = s.shot_id
    where s.workspace_id = target_workspace and s.production_id = target_production and s.retired_at is null
      and (patterns is null or (s.trait || ' ' || s.value || ' ' || s.reason) ilike all (patterns))
      and (f_domain is null or s.domain::text = f_domain)
      and (f_asset is null or s.subject_object_id = f_asset);

  elsif lane = 'memory' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','memory_item','entity_id', m.id,
        'label', m.statement,
        'context', case m.scope when 'workspace' then 'Workspace' when 'series' then 'Series' else 'This Production' end,
        'detail', m.kind::text || ' - ' || m.source::text || ' - ' || m.origin::text,
        'scope', m.scope, 'memory_kind', m.kind, 'source', m.source, 'origin', m.origin,
        'authority_rank', tonde_private.mi_rank(m.source),
        'in_force', not exists (
          select 1 from tonde.memory_items better
          where better.workspace_id = m.workspace_id and better.retired_at is null and better.state = 'active'
            and better.subject_key = m.subject_key and better.id <> m.id
            and ((better.production_id = target_production)
                 or (better.production_id is null and better.series_id is null)
                 or (better.series_id is not null and better.series_id = tonde_private.mi_series_of(m.workspace_id, target_production)))
            and (tonde_private.mi_rank(better.source) < tonde_private.mi_rank(m.source)
                 or (tonde_private.mi_rank(better.source) = tonde_private.mi_rank(m.source)
                     and better.created_at > m.created_at))),
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'memory text' end,
          case when f_mkind is not null then 'memory kind' end,
          case when f_asset is not null then 'source object' end], null), ', '))
      order by tonde_private.mi_rank(m.source), m.created_at desc), '[]'::jsonb), count(*)
      into items, total
    from tonde.memory_items m
    where m.workspace_id = target_workspace and m.retired_at is null and m.state = 'active'
      and ((m.production_id = target_production)
           or (m.production_id is null and m.series_id is null)
           or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)))
      and (patterns is null or (m.statement || ' ' || m.subject_key || ' ' || m.rationale) ilike all (patterns))
      and (f_mkind is null or m.kind::text = f_mkind)
      and (f_asset is null or m.source_object_id = f_asset);

  elsif lane = 'asset' then
    select coalesce(jsonb_agg(jsonb_build_object(
        'entity_type','asset','entity_id', a.id,'label', a.name,
        'context', a.asset_type::text,
        'detail', left(a.description, 200),
        'asset_type', a.asset_type::text, 'approval', a.approval::text, 'revision', a.revision,
        'locked', a.locked_at is not null,
        'matched_on', array_to_string(array_remove(array[
          case when patterns is not null then 'asset name or description' end,
          case when f_asset_type is not null then 'asset type' end,
          case when f_asset is not null then 'named asset' end], null), ', '))
      order by a.name), '[]'::jsonb), count(*)
      into items, total
    from tonde.assets a
    where a.workspace_id = target_workspace and a.lifecycle = 'active'
      and (patterns is null or (a.name || ' ' || a.description) ilike all (patterns))
      and (f_asset_type is null or a.asset_type::text = f_asset_type)
      and (f_asset is null or a.id = f_asset);
  end if;

  return jsonb_build_object('lane', lane, 'items', items, 'total', total, 'returned', jsonb_array_length(items));
end $$;

revoke all on function tonde_private.mi_search_lane(uuid,uuid,text,jsonb) from public, anon, authenticated, service_role;


-- 6. Policy surface. Only a workspace editor may change what TONDE is allowed to remember.
create or replace function tonde.memory_policy_set(target_workspace uuid, target_production uuid, policy_record jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  desired_scope tonde.memory_scope; scope_ref uuid; series_ref uuid; saved tonde.memory_policies;
  capture_value boolean; auto_value boolean; note_value text; series_input uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(policy_record) <> 'object' then
    raise exception 'A memory policy must be a JSON object' using errcode = '22023';
  end if;
  if coalesce(nullif(policy_record ->> 'scope',''), 'production') not in ('production','series','workspace') then
    raise exception 'Unsupported memory scope' using errcode = '22023';
  end if;
  desired_scope := coalesce(nullif(policy_record ->> 'scope',''), 'production')::tonde.memory_scope;
  if desired_scope = 'production' then
    scope_ref := target_production;
    series_ref := null;
  elsif desired_scope = 'series' then
    series_input := tonde_private.mi_uuid(policy_record, 'series_id', false);
    series_ref := series_input;
    if series_ref is null then
      select e.series_id into series_ref from tonde.series_episodes e
        where e.workspace_id = target_workspace and e.production_id = target_production;
    end if;
    if series_ref is null or not exists (select 1 from tonde.series s
        where s.workspace_id = target_workspace and s.id = series_ref) then
      raise exception 'This Production does not belong to a Series in this workspace' using errcode = '22023';
    end if;
    scope_ref := null;
  else
    scope_ref := null;
    series_ref := null;
  end if;
  capture_value := coalesce((policy_record ->> 'candidate_capture')::boolean, true);
  auto_value := coalesce((policy_record ->> 'auto_accept_candidates')::boolean, false);
  note_value := tonde_private.ci_text(policy_record, 'note', 600, false);
  insert into tonde.memory_policies(workspace_id, scope, production_id, series_id,
      candidate_capture, auto_accept_candidates, note)
    values (target_workspace, desired_scope, scope_ref, series_ref, capture_value, auto_value, note_value)
  on conflict (workspace_id, scope,
      coalesce(production_id, '00000000-0000-0000-0000-000000000000'::uuid),
      coalesce(series_id, '00000000-0000-0000-0000-000000000000'::uuid))
    do update set candidate_capture = excluded.candidate_capture,
      auto_accept_candidates = excluded.auto_accept_candidates, note = excluded.note
  returning * into saved;
  return jsonb_build_object('policy_id', saved.id, 'scope', saved.scope,
    'candidate_capture', saved.candidate_capture, 'auto_accept_candidates', saved.auto_accept_candidates,
    'note', saved.note, 'updated_at', saved.updated_at,
    'note_text', case when saved.candidate_capture then
        'TONDE may record pattern candidates for your review in this scope.'
      else 'TONDE will not record pattern candidates in this scope.' end
      || case when saved.auto_accept_candidates then ' Accepted candidates become memory automatically.' else ' Nothing becomes memory without your explicit decision.' end);
end $$;


create or replace function tonde.memory_policy_get(target_workspace uuid, target_production uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare series_ref uuid; scopes jsonb := '[]'::jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  series_ref := tonde_private.mi_series_of(target_workspace, target_production);
  scopes := jsonb_build_array(
    tonde_private.mi_policy(target_workspace, 'production', target_production, null),
    tonde_private.mi_policy(target_workspace, 'workspace', null, null));
  if series_ref is not null then
    scopes := scopes || jsonb_build_array(tonde_private.mi_policy(target_workspace, 'series', null, series_ref));
  end if;
  return jsonb_build_object('production_id', target_production, 'series_id', series_ref, 'policies', scopes,
    'note', 'Memory policy decides whether TONDE may record pattern candidates and whether an accepted candidate becomes memory automatically. It never decides what you are allowed to instruct.');
end $$;


-- 7. Writing memory. An identical restatement refreshes the row; a different statement of the same
-- authority tier supersedes it and keeps the old one readable.
create or replace function tonde.memory_item_set(target_workspace uuid, target_production uuid, item jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  desired_scope tonde.memory_scope; desired_kind tonde.memory_kind; desired_source tonde.memory_source;
  desired_origin tonde.memory_origin;  subject_text text; statement_text text; rationale_text text;
  scope_production uuid; scope_series uuid; source_ref uuid; source_rev integer; evidence_value jsonb;
  series_input uuid;
  existing tonde.memory_items; saved tonde.memory_items; superseded_id uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(item) <> 'object' then
    raise exception 'A memory item must be a JSON object' using errcode = '22023';
  end if;
  if coalesce(nullif(item ->> 'scope',''), 'production') not in ('production','series','workspace') then
    raise exception 'Unsupported memory scope' using errcode = '22023';
  end if;
  if coalesce(nullif(item ->> 'kind',''), 'other') not in
      ('preference','decision','pattern','technique','setup_fact','asset_usage','model_outcome','series_rule','correction','other') then
    raise exception 'Unsupported memory kind' using errcode = '22023';
  end if;
  if coalesce(nullif(item ->> 'source',''), 'saved_preference') not in
      ('creator_instruction','production_decision','saved_preference','historical_pattern','inference') then
    raise exception 'Unsupported memory source' using errcode = '22023';
  end if;
  if coalesce(nullif(item ->> 'origin',''), 'declared') not in ('declared','accepted','inferred') then
    raise exception 'Unsupported memory origin' using errcode = '22023';
  end if;
  desired_scope := coalesce(nullif(item ->> 'scope',''), 'production')::tonde.memory_scope;
  desired_kind := coalesce(nullif(item ->> 'kind',''), 'other')::tonde.memory_kind;
  desired_source := coalesce(nullif(item ->> 'source',''), 'saved_preference')::tonde.memory_source;
  desired_origin := coalesce(nullif(item ->> 'origin',''), 'declared')::tonde.memory_origin;
  if desired_origin = 'accepted' then
    raise exception 'An accepted memory item is created by accepting a candidate' using errcode = '22023';
  end if;
  -- Human authority cannot be claimed by an inference.
  if desired_origin = 'inferred' and desired_source in ('creator_instruction','production_decision') then
    raise exception 'An inference cannot claim creator authority' using errcode = '23514';
  end if;
  subject_text := tonde_private.ci_text(item, 'subject_key', 160, true);
  statement_text := tonde_private.ci_text(item, 'statement', 600, true);
  rationale_text := tonde_private.ci_text(item, 'rationale', 800, false);
  evidence_value := coalesce(item -> 'evidence', '[]'::jsonb);
  if jsonb_typeof(evidence_value) <> 'array' then
    raise exception 'The evidence of a memory item must be a list' using errcode = '22023';
  end if;
  if desired_origin = 'inferred' and jsonb_array_length(evidence_value) = 0 then
    raise exception 'An inferred memory item must disclose its basis' using errcode = '23514';
  end if;
  if desired_scope = 'production' then
    scope_production := target_production; scope_series := null;
  elsif desired_scope = 'series' then
    series_input := tonde_private.mi_uuid(item, 'series_id', false);
    scope_series := series_input;
    if scope_series is null then
      select e.series_id into scope_series from tonde.series_episodes e
        where e.workspace_id = target_workspace and e.production_id = target_production;
    end if;
    if scope_series is null or not exists (select 1 from tonde.series s
        where s.workspace_id = target_workspace and s.id = scope_series) then
      raise exception 'This Production does not belong to a Series in this workspace' using errcode = '22023';
    end if;
    scope_production := null;
  else
    scope_production := null; scope_series := null;
  end if;
  source_ref := tonde_private.mi_uuid(item, 'source_object_id', false);
  if source_ref is not null and not exists (select 1 from tonde.objects o
      where o.workspace_id = target_workspace and o.id = source_ref) then
    raise exception 'The source object of this memory is not in this workspace' using errcode = '22023';
  end if;
  source_rev := nullif(item ->> 'source_revision','')::integer;
  if source_rev is null and source_ref is not null then
    source_rev := tonde_private.pi_object_revision(target_workspace, source_ref);
  end if;

  select * into existing from tonde.memory_items m
    where m.workspace_id = target_workspace and m.retired_at is null and m.state = 'active'
      and m.scope = desired_scope and m.subject_key = subject_text and m.source = desired_source
      and m.production_id is not distinct from scope_production
      and m.series_id is not distinct from scope_series
    order by m.created_at desc limit 1;
  if existing.id is not null then
    if existing.statement = statement_text and existing.kind = desired_kind then
      -- Restating the same knowledge refreshes it; it does not create a second live item.
      update tonde.memory_items m set rationale = coalesce(nullif(rationale_text,''), m.rationale)
        where m.id = existing.id returning * into saved;
      return jsonb_build_object('item_id', saved.id, 'updated', true, 'superseded_id', null,
        'authority_rank', tonde_private.mi_rank(saved.source), 'scope', saved.scope, 'source', saved.source,
        'origin', saved.origin, 'in_force', true,
        'note_text', 'The same knowledge was already remembered; the record was refreshed instead of duplicated.');
    end if;
    -- Retire first: one live item per subject and tier is enforced by the database, not by hope.
    update tonde.memory_items m set state = 'archived', retired_at = now(), retired_by = auth.uid(),
      retire_reason = 'Superseded by a newer statement of the same authority on ' || to_char(now(), 'YYYY-MM-DD')
      where m.id = existing.id;
    superseded_id := existing.id;
  end if;

  insert into tonde.memory_items(workspace_id, production_id, series_id, scope, kind, subject_key, statement,
      source, origin, rationale, evidence, source_object_id, source_revision, confirmed_by, confirmed_at, supersedes_id)
    values (target_workspace, scope_production, scope_series, desired_scope, desired_kind, subject_text, statement_text,
      desired_source, desired_origin, rationale_text, evidence_value, source_ref, source_rev,
      case when desired_origin in ('declared','accepted') then auth.uid() else null end,
      case when desired_origin in ('declared','accepted') then now() else null end,
      superseded_id)
    returning * into saved;
  return jsonb_build_object('item_id', saved.id, 'updated', false, 'superseded_id', superseded_id,
    'authority_rank', tonde_private.mi_rank(saved.source), 'scope', saved.scope, 'source', saved.source,
    'origin', saved.origin, 'in_force', true,
    'note_text', case when saved.origin = 'inferred'
      then 'This is an inferred memory item. It is inspectable and it can be retired, and it does not outrank anything you said or decided.'
      else 'Remembered with your authority at tier ' || tonde_private.mi_rank(saved.source) || ' of 5.' end);
end $$;


create or replace function tonde.memory_item_retire(target_workspace uuid, target_production uuid, target_item uuid,
  reason_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.memory_items;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into saved from tonde.memory_items m where m.workspace_id = target_workspace and m.id = target_item;
  if not found then raise exception 'That memory item is unavailable' using errcode = 'P0002'; end if;
  if saved.retired_at is null then
    update tonde.memory_items m set state = 'archived', retired_at = now(), retired_by = auth.uid(),
      retire_reason = coalesce(nullif(tonde_private.ci_text(jsonb_build_object('reason', reason_text), 'reason', 400, false), ''),
        'Retired by the creator without a stated reason')
      where m.id = saved.id returning * into saved;
  end if;
  return jsonb_build_object('item_id', saved.id, 'state', saved.state, 'retired_at', saved.retired_at,
    'retire_reason', saved.retire_reason,
    'note_text', 'The item stays readable as history. Nothing TONDE recorded was deleted.');
end $$;


-- 8. Reading memory. Every row carries its provenance, its authority tier and whether it is in
-- force, and whether the object it was drawn from has changed since.
create or replace function tonde.memory_item_list(target_workspace uuid, target_production uuid,
  target_scope text default null, target_kind text default null, target_subject text default null,
  target_state text default null, target_limit integer default 100, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; desired_state text;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 100), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  desired_state := coalesce(nullif(target_state,''), 'active');
  if desired_state not in ('active','archived','all') then
    raise exception 'Unsupported memory state filter' using errcode = '22023';
  end if;
  if target_scope is not null and target_scope not in ('production','series','workspace') then
    raise exception 'Unsupported memory scope filter' using errcode = '22023';
  end if;
  select count(*) into total from tonde.memory_items m
    where m.workspace_id = target_workspace
      and ((m.production_id = target_production)
           or (m.production_id is null and m.series_id is null)
           or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)))
      and (target_scope is null or m.scope::text = target_scope)
      and (target_kind is null or m.kind::text = target_kind)
      and (target_subject is null or m.subject_key = target_subject)
      and (desired_state = 'all'
           or (desired_state = 'active' and m.retired_at is null and m.state = 'active')
           or (desired_state = 'archived' and (m.retired_at is not null or m.state <> 'active')));
  select coalesce(jsonb_agg(jsonb_build_object(
      'item_id', r.id, 'scope', r.scope, 'kind', r.kind, 'subject_key', r.subject_key, 'statement', r.statement,
      'source', r.source, 'origin', r.origin, 'authority_rank', tonde_private.mi_rank(r.source),
      'rationale', r.rationale, 'evidence', r.evidence,
      'source_object_id', r.source_object_id, 'source_object_label', tonde_private.pi_label(target_workspace, r.source_object_id),
      'source_revision', r.source_revision, 'source_object_revision',
        case when r.source_object_id is null then null else tonde_private.pi_object_revision(target_workspace, r.source_object_id) end,
      'source_changed', case when r.source_object_id is null or r.source_revision is null then null
        else tonde_private.pi_object_revision(target_workspace, r.source_object_id) is distinct from r.source_revision end,
      'candidate_id', r.candidate_id, 'confirmed_by', r.confirmed_by, 'confirmed_at', r.confirmed_at,
      'state', r.state, 'retired_at', r.retired_at, 'retire_reason', r.retire_reason,
      'supersedes_id', r.supersedes_id,
      'superseded_by', (select s.id from tonde.memory_items s where s.supersedes_id = r.id order by s.created_at desc limit 1),
      'in_force', not exists (
        select 1 from tonde.memory_items better
        where better.workspace_id = r.workspace_id and better.retired_at is null and better.state = 'active'
          and better.subject_key = r.subject_key and better.id <> r.id
          and ((better.production_id = target_production)
               or (better.production_id is null and better.series_id is null)
               or (better.series_id is not null and better.series_id = tonde_private.mi_series_of(r.workspace_id, target_production)))
          and (tonde_private.mi_rank(better.source) < tonde_private.mi_rank(r.source)
               or (tonde_private.mi_rank(better.source) = tonde_private.mi_rank(r.source)
                   and better.created_at > r.created_at))),
      'production_id', r.production_id, 'series_id', r.series_id,
      'created_at', r.created_at, 'updated_at', r.updated_at, 'created_by', r.created_by) order by
        case when r.retired_at is null and r.state = 'active' then 0 else 1 end,
        tonde_private.mi_rank(r.source), r.created_at desc), '[]'::jsonb)
    into items
  from (select m.* from tonde.memory_items m
    where m.workspace_id = target_workspace
      and ((m.production_id = target_production)
           or (m.production_id is null and m.series_id is null)
           or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)))
      and (target_scope is null or m.scope::text = target_scope)
      and (target_kind is null or m.kind::text = target_kind)
      and (target_subject is null or m.subject_key = target_subject)
      and (desired_state = 'all'
           or (desired_state = 'active' and m.retired_at is null and m.state = 'active')
           or (desired_state = 'archived' and (m.retired_at is not null or m.state <> 'active')))
    order by case when m.retired_at is null and m.state = 'active' then 0 else 1 end,
      tonde_private.mi_rank(m.source), m.created_at desc
    limit lim offset off) r;
  return jsonb_build_object('items', items, 'total', total, 'limit', lim, 'offset', off, 'truncated', total > off + lim,
    'note', 'Memory shows what TONDE remembers, where it came from, and whether it is currently in force. It is not a behavioural profile.');
end $$;


-- The authority question: "why is TONDE using this, and what did it outrank?"
create or replace function tonde.memory_resolve(target_workspace uuid, target_production uuid,
  target_subject text, target_kind text default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare subject_text text; considered jsonb := '[]'::jsonb; winner jsonb := 'null'::jsonb; explanation text;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  subject_text := tonde_private.ci_text(jsonb_build_object('subject', target_subject), 'subject', 160, true);
  if target_kind is not null and target_kind not in
      ('preference','decision','pattern','technique','setup_fact','asset_usage','model_outcome','series_rule','correction','other') then
    raise exception 'Unsupported memory kind filter' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'item_id', r.id, 'statement', r.statement, 'kind', r.kind, 'scope', r.scope, 'source', r.source,
      'origin', r.origin, 'authority_rank', tonde_private.mi_rank(r.source),
      'confirmed', r.origin <> 'inferred', 'created_at', r.created_at, 'retired_at', r.retired_at,
      'in_force', r.position = 1) order by r.position), '[]'::jsonb)
    into considered
  from (
    select m.*, rank() over (order by tonde_private.mi_rank(m.source), m.created_at desc) as position
    from tonde.memory_items m
    where m.workspace_id = target_workspace and m.subject_key = subject_text
      and m.retired_at is null and m.state = 'active'
      and ((m.production_id = target_production)
           or (m.production_id is null and m.series_id is null)
           or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)))
      and (target_kind is null or m.kind::text = target_kind)
  ) r;
  if jsonb_array_length(considered) = 0 then
    return jsonb_build_object('subject_key', subject_text, 'resolved', 'null'::jsonb, 'considered', considered,
      'explanation', 'TONDE remembers nothing about this subject. Nothing is being reused.');
  end if;
  select value into winner from jsonb_array_elements(considered) value where (value ->> 'in_force')::boolean limit 1;
  explanation := 'Using the ' || replace(winner ->> 'source', '_', ' ') || ' recorded on '
    || to_char((winner ->> 'created_at')::timestamptz, 'YYYY-MM-DD')
    || ' (' || case when (winner ->> 'confirmed')::boolean then 'creator-confirmed' else 'inferred and unconfirmed' end || ').';
  if jsonb_array_length(considered) > 1 then
    explanation := explanation || ' It outranks: ' || (
      select string_agg(x.v ->> 'source', ', ' order by (x.v ->> 'authority_rank')::integer)
      from jsonb_array_elements(considered) x(v) where not (x.v ->> 'in_force')::boolean) || '.';
  end if;
  return jsonb_build_object('subject_key', subject_text, 'resolved', winner, 'considered', considered,
    'explanation', explanation,
    'note_text', 'A current creator instruction outranks a Production decision, which outranks an explicit saved preference, which outranks a historical pattern, which outranks an inference.');
end $$;


-- 9. Pattern candidates. Real evidence, a policy decision, and a creator decision. Nothing becomes
-- reusable memory from one Shot without that decision.
create or replace function tonde.memory_candidate_record(target_workspace uuid, target_production uuid, candidate jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  desired_kind tonde.memory_kind; subject_text text; statement_text text; proposed text;
  basis_value jsonb; observed integer; source_ref uuid; source_rev integer; current_rev integer;
  policy jsonb; saved tonde.memory_candidates; existing tonde.memory_candidates; created_item tonde.memory_items;
  auto_origin tonde.memory_origin;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(candidate) <> 'object' then
    raise exception 'A memory candidate must be a JSON object' using errcode = '22023';
  end if;
  if coalesce(nullif(candidate ->> 'kind',''), 'other') not in
      ('preference','decision','pattern','technique','setup_fact','asset_usage','model_outcome','series_rule','correction','other') then
    raise exception 'Unsupported memory kind' using errcode = '22023';
  end if;
  desired_kind := coalesce(nullif(candidate ->> 'kind',''), 'other')::tonde.memory_kind;
  proposed := coalesce(nullif(candidate ->> 'proposed_source',''), 'historical_pattern');
  if proposed not in ('saved_preference','historical_pattern','inference') then
    raise exception 'A candidate may only propose saved preference, historical pattern or inference' using errcode = '22023';
  end if;
  subject_text := tonde_private.ci_text(candidate, 'subject_key', 160, true);
  statement_text := tonde_private.ci_text(candidate, 'statement', 600, true);
  basis_value := coalesce(candidate -> 'basis', '[]'::jsonb);
  if jsonb_typeof(basis_value) <> 'array' or jsonb_array_length(basis_value) = 0 then
    raise exception 'A candidate must cite the evidence it was observed on' using errcode = '23514';
  end if;
  observed := greatest(coalesce((candidate ->> 'observed_count')::integer, 1), 1);
  source_ref := tonde_private.mi_uuid(candidate, 'source_object_id', false);
  if source_ref is null or not exists (select 1 from tonde.objects o
      where o.workspace_id = target_workspace and o.id = source_ref) then
    raise exception 'A candidate must name the object it was observed on' using errcode = '22023';
  end if;
  source_rev := nullif(candidate ->> 'source_revision','')::integer;
  current_rev := tonde_private.pi_object_revision(target_workspace, source_ref);
  if source_rev is null then source_rev := current_rev; end if;
  -- Section 163: a proposal pins the revision it was drawn from.
  if source_rev is null or current_rev is null or source_rev <> current_rev then
    raise exception 'The evidence changed before this candidate was recorded; record it from the current revision' using errcode = '40001';
  end if;
  policy := tonde_private.mi_policy(target_workspace, 'production', target_production, null);
  if not (policy ->> 'candidate_capture')::boolean then
    raise exception 'The memory policy for this scope does not allow recording candidates' using errcode = '23514';
  end if;
  auto_origin := case when (policy ->> 'auto_accept_candidates')::boolean then 'inferred'::tonde.memory_origin else null end;
  -- Retrying the same observation must not duplicate it, and a candidate whose evidence has moved on
  -- must not silently block the current revision from being proposed. The old candidate is retired
  -- as superseded - kept as history - and a new one is recorded against the revision that is real now.
  select * into existing from tonde.memory_candidates c
    where c.workspace_id = target_workspace and c.production_id = target_production and c.state = 'proposed'
      and c.subject_key = subject_text and c.kind = desired_kind and c.source_object_id = source_ref;
  if existing.id is not null then
    if existing.source_revision = source_rev then
      return jsonb_build_object('candidate_id', existing.id, 'state', existing.state, 'duplicate', true,
        'observed_count', existing.observed_count, 'policy', policy,
        'note_text', 'This candidate was already recorded from the same evidence. Nothing new was created.');
    end if;
    update tonde.memory_candidates c set state = 'rejected', decided_by = auth.uid(), decided_at = now(),
      decision_note = 'Superseded: the object it was observed on moved from revision ' || existing.source_revision
        || ' to revision ' || source_rev || '.'
      where c.id = existing.id;
  end if;
  insert into tonde.memory_candidates(workspace_id, production_id, scope, kind, subject_key, statement,
      proposed_source, basis, observed_count, source_object_id, source_revision)
    values (target_workspace, target_production, 'production', desired_kind, subject_text, statement_text,
      proposed::tonde.memory_source, basis_value, observed, source_ref, source_rev)
    returning * into saved;
  if auto_origin is not null then
    insert into tonde.memory_items(workspace_id, production_id, scope, kind, subject_key, statement,
        source, origin, rationale, evidence, source_object_id, source_revision, candidate_id)
      values (target_workspace, target_production, 'production', desired_kind, subject_text, statement_text,
        proposed::tonde.memory_source, auto_origin,
        'Recorded automatically under the memory policy for this Production scope.',
        basis_value, source_ref, source_rev, saved.id)
      returning * into created_item;
    update tonde.memory_candidates c set state = 'applied', decided_by = auth.uid(), decided_at = now(),
      decision_note = 'Accepted automatically by the memory policy for this Production scope.'
      where c.id = saved.id returning * into saved;
    return jsonb_build_object('candidate_id', saved.id, 'state', saved.state, 'duplicate', false,
      'memory_item_id', created_item.id, 'policy', policy,
      'note_text', 'The memory policy for this scope accepts candidates automatically, so this one is remembered as an inference until you confirm or retire it.');
  end if;
  return jsonb_build_object('candidate_id', saved.id, 'state', saved.state, 'duplicate', false,
    'memory_item_id', null, 'policy', policy,
    'note_text', 'Recorded for review. Nothing becomes memory until you accept it.');
end $$;


create or replace function tonde.memory_candidate_list(target_workspace uuid, target_production uuid,
  target_state text default null, target_limit integer default 50, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; desired_state text; policy jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 50), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  desired_state := coalesce(nullif(target_state,''), 'proposed');
  if desired_state not in ('proposed','applied','rejected','all') then
    raise exception 'Unsupported candidate state filter' using errcode = '22023';
  end if;
  policy := tonde_private.mi_policy(target_workspace, 'production', target_production, null);
  select count(*) into total from tonde.memory_candidates c
    where c.workspace_id = target_workspace and c.production_id = target_production
      and (desired_state = 'all' or c.state::text = desired_state);
  select coalesce(jsonb_agg(jsonb_build_object(
      'candidate_id', c.id, 'kind', c.kind, 'subject_key', c.subject_key, 'statement', c.statement,
      'proposed_source', c.proposed_source, 'basis', c.basis, 'observed_count', c.observed_count,
      'source_object_id', c.source_object_id, 'source_object_label', tonde_private.pi_label(target_workspace, c.source_object_id),
      'source_revision', c.source_revision,
      'source_changed', tonde_private.pi_object_revision(target_workspace, c.source_object_id) is distinct from c.source_revision,
      'state', c.state, 'decided_by', c.decided_by, 'decided_at', c.decided_at, 'decision_note', c.decision_note,
      'created_at', c.created_at) order by c.created_at desc), '[]'::jsonb)
    into items
  from (select c.* from tonde.memory_candidates c
    where c.workspace_id = target_workspace and c.production_id = target_production
      and (desired_state = 'all' or c.state::text = desired_state)
    order by c.created_at desc limit lim offset off) c;
  return jsonb_build_object('items', items, 'total', total, 'limit', lim, 'offset', off, 'truncated', total > off + lim,
    'policy', policy,
    'note', 'A candidate is a proposal drawn from real evidence. It is never a creator preference until you accept it.');
end $$;


create or replace function tonde.memory_candidate_decide(target_workspace uuid, target_production uuid, target_candidate uuid,
  decision text, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare candidate tonde.memory_candidates; created_item tonde.memory_items; saved tonde.memory_candidates;
  current_rev integer; decision_note_value text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if decision not in ('accept','dismiss') then
    raise exception 'Unsupported candidate decision' using errcode = '22023';
  end if;
  select * into candidate from tonde.memory_candidates c
    where c.workspace_id = target_workspace and c.production_id = target_production and c.id = target_candidate;
  if not found then raise exception 'That memory candidate is unavailable' using errcode = 'P0002'; end if;
  if candidate.state <> 'proposed' then
    return jsonb_build_object('candidate_id', candidate.id, 'state', candidate.state, 'memory_item_id', null,
      'note_text', 'This candidate was already decided.');
  end if;
  decision_note_value := tonde_private.ci_text(jsonb_build_object('note', note_text), 'note', 800, false);
  if decision = 'dismiss' then
    update tonde.memory_candidates c set state = 'rejected', decided_by = auth.uid(), decided_at = now(),
      decision_note = coalesce(nullif(decision_note_value,''), 'Dismissed by the creator')
      where c.id = candidate.id returning * into saved;
    return jsonb_build_object('candidate_id', saved.id, 'state', saved.state, 'memory_item_id', null,
      'note_text', 'Dismissed. Nothing was remembered and the candidate stays readable as history.');
  end if;
  -- Section 163: accepting pins the revision the candidate was drawn from. A changed source rejects.
  current_rev := tonde_private.pi_object_revision(target_workspace, candidate.source_object_id);
  if current_rev is distinct from candidate.source_revision then
    raise exception 'The evidence this candidate was drawn from changed; record a new candidate from the current revision' using errcode = '40001';
  end if;
  insert into tonde.memory_items(workspace_id, production_id, scope, kind, subject_key, statement,
      source, origin, rationale, evidence, source_object_id, source_revision, candidate_id,
      confirmed_by, confirmed_at)
    values (target_workspace, target_production, candidate.scope, candidate.kind, candidate.subject_key,
      candidate.statement, candidate.proposed_source, 'accepted',
      'Accepted from a pattern candidate observed on ' || to_char(candidate.created_at, 'YYYY-MM-DD') || '.',
      candidate.basis, candidate.source_object_id, candidate.source_revision, candidate.id, auth.uid(), now())
    returning * into created_item;
  update tonde.memory_candidates c set state = 'applied', decided_by = auth.uid(), decided_at = now(),
    decision_note = coalesce(nullif(decision_note_value,''), 'Accepted by the creator')
    where c.id = candidate.id returning * into saved;
  return jsonb_build_object('candidate_id', saved.id, 'state', saved.state, 'memory_item_id', created_item.id,
    'authority_rank', tonde_private.mi_rank(created_item.source),
    'note_text', 'Remembered with your authority. It outranks an inference and any unconfirmed pattern, and a later instruction of yours outranks it.');
end $$;


-- 10. Summary: what TONDE remembers, and what it is waiting for a decision on.
create or replace function tonde.memory_summary(target_workspace uuid, target_production uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  active_items integer; archived_items integer; subjects integer; confirmed integer; inferred integer;
  changed_sources integer; proposed integer; applied integer; rejected integer; policy jsonb; series_ref uuid;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select count(*) filter (where m.retired_at is null and m.state = 'active'),
    count(*) filter (where m.retired_at is not null or m.state <> 'active'),
    count(distinct m.subject_key) filter (where m.retired_at is null and m.state = 'active'),
    count(*) filter (where m.retired_at is null and m.state = 'active' and m.origin <> 'inferred'),
    count(*) filter (where m.retired_at is null and m.state = 'active' and m.origin = 'inferred'),
    count(*) filter (where m.retired_at is null and m.state = 'active' and m.source_object_id is not null
      and m.source_revision is not null
      and tonde_private.pi_object_revision(target_workspace, m.source_object_id) is distinct from m.source_revision)
    into active_items, archived_items, subjects, confirmed, inferred, changed_sources
  from tonde.memory_items m
  where m.workspace_id = target_workspace
    and ((m.production_id = target_production)
         or (m.production_id is null and m.series_id is null)
         or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)));
  select count(*) filter (where c.state = 'proposed'), count(*) filter (where c.state = 'applied'),
    count(*) filter (where c.state = 'rejected')
    into proposed, applied, rejected
  from tonde.memory_candidates c
  where c.workspace_id = target_workspace and c.production_id = target_production;
  series_ref := tonde_private.mi_series_of(target_workspace, target_production);
  policy := tonde_private.mi_policy(target_workspace, 'production', target_production, null);
  return jsonb_build_object(
    'items', jsonb_build_object('active', coalesce(active_items,0), 'archived', coalesce(archived_items,0),
      'subjects', coalesce(subjects,0), 'creator_confirmed', coalesce(confirmed,0), 'inferred', coalesce(inferred,0),
      'sources_changed', coalesce(changed_sources,0)),
    'by_scope', (select coalesce(jsonb_object_agg(x.scope, x.count), '{}'::jsonb) from (
      select m.scope::text as scope, count(*) as count from tonde.memory_items m
      where m.workspace_id = target_workspace and m.retired_at is null and m.state = 'active'
        and ((m.production_id = target_production)
             or (m.production_id is null and m.series_id is null)
             or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)))
      group by m.scope) x),
    'by_source', (select coalesce(jsonb_object_agg(x.source, x.count), '{}'::jsonb) from (
      select m.source::text as source, count(*) as count from tonde.memory_items m
      where m.workspace_id = target_workspace and m.retired_at is null and m.state = 'active'
        and ((m.production_id = target_production)
             or (m.production_id is null and m.series_id is null)
             or (m.series_id is not null and m.series_id = tonde_private.mi_series_of(target_workspace, target_production)))
      group by m.source) x),
    'candidates', jsonb_build_object('proposed', coalesce(proposed,0), 'applied', coalesce(applied,0),
      'rejected', coalesce(rejected,0)),
    'policy', policy, 'series_id', series_ref,
    'limitations', 'Memory is what the Production recorded and what you confirmed. An unconfirmed inference is labelled as an inference, and nothing here is a hidden behavioural profile.');
end $$;


-- 11. Structured production search. Relational and indexed data first; there is no embedding path.
create or replace function tonde.production_search(target_workspace uuid, target_production uuid, query jsonb)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  lim integer; lane text; lane_json jsonb; all_items jsonb := '[]'::jsonb; lane_counts jsonb := '[]'::jsonb;
  total integer := 0; returned integer := 0; requested text[]; known text[] :=
    array['shot','scene','plan','result','continuity_finding','continuity_state','memory','asset'];
  patterns text[]; tokens jsonb; facet_list jsonb := '[]'::jsonb;
  asset_ref uuid; asset_name text; asset_type_value text; unresolved text;
  effective jsonb; series_ref uuid;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  if jsonb_typeof(query) is distinct from 'object' then
    raise exception 'A search request must be a JSON object' using errcode = '22023';
  end if;
  if not exists (select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production) then
    raise exception 'Production unavailable' using errcode = 'P0002';
  end if;
  lim := least(greatest(coalesce((query ->> 'limit')::integer, 50), 1), 100);
  -- Validate every controlled facet before any lane runs: an unknown code is a rejected request.
  if nullif(query ->> 'approval','') is not null and (query ->> 'approval') not in
      ('draft','needs_review','approved','changed_after_approval','not_approved') then
    raise exception 'Unsupported approval filter' using errcode = '22023';
  end if;
  if nullif(query ->> 'execution_method','') is not null and (query ->> 'execution_method') not in ('real','ai','hybrid') then
    raise exception 'Unsupported execution filter' using errcode = '22023';
  end if;
  if nullif(query ->> 'continuity_state','') is not null and (query ->> 'continuity_state') not in
      ('open','acknowledged','resolved','waived') then
    raise exception 'Unsupported continuity state filter' using errcode = '22023';
  end if;
  if nullif(query ->> 'severity','') is not null and (query ->> 'severity') not in ('info','warning','critical') then
    raise exception 'Unsupported severity filter' using errcode = '22023';
  end if;
  if nullif(query ->> 'result_state','') is not null and (query ->> 'result_state') not in
      ('raw','needs_review','approved','rejected','final') then
    raise exception 'Unsupported Result state filter' using errcode = '22023';
  end if;
  if nullif(query ->> 'domain','') is not null and (query ->> 'domain') not in
      ('character','wardrobe','prop','product','vehicle','injury','hair_makeup','weather','time_of_day',
       'environment','lighting','story_knowledge','dialogue_fact','screen_direction','eyeline',
       'camera_geography','position','product_condition','other') then
    raise exception 'Unsupported continuity domain filter' using errcode = '22023';
  end if;
  if nullif(query ->> 'memory_kind','') is not null and (query ->> 'memory_kind') not in
      ('preference','decision','pattern','technique','setup_fact','asset_usage','model_outcome','series_rule','correction','other') then
    raise exception 'Unsupported memory kind filter' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(query -> 'kinds', '[]'::jsonb)) <> 'array' then
    raise exception 'Search kinds must be a list' using errcode = '22023';
  end if;
  if jsonb_array_length(coalesce(query -> 'kinds', '[]'::jsonb)) = 0 then
    requested := known;
  else
    select array_agg(value) into requested from jsonb_array_elements_text(query -> 'kinds') value;
    if exists (select 1 from unnest(requested) r where r <> all (known)) then
      raise exception 'Unsupported search kind' using errcode = '22023';
    end if;
    -- Keep a stable lane order regardless of what the caller listed.
    select array_agg(k order by array_position(known, k)) into requested from unnest(requested) k;
  end if;

  patterns := tonde_private.mi_patterns(query ->> 'text');
  tokens := to_jsonb(array(select btrim(p, '%') from unnest(patterns) p));

  -- An identity facet that names nothing is answered honestly instead of being ignored.
  asset_name := nullif(btrim(coalesce(query ->> 'asset_name','')), '');
  asset_ref := tonde_private.mi_uuid(query, 'asset_id', false);
  asset_type_value := nullif(query ->> 'asset_type','');
  if asset_type_value is not null and asset_type_value not in
      ('character','voice','product','environment','wardrobe','prop','vehicle','style_bible','brand') then
    raise exception 'Unsupported Asset type filter' using errcode = '22023';
  end if;
  if asset_ref is null and asset_name is not null then
    select a.id into asset_ref from tonde.assets a
      where a.workspace_id = target_workspace and a.lifecycle = 'active' and a.name ilike '%' || asset_name || '%'
      order by (a.name ilike asset_name || '%') desc, a.name limit 1;
    if asset_ref is null then unresolved := asset_name; end if;
  end if;
  if asset_ref is not null and asset_type_value is not null
    and not exists (select 1 from tonde.assets a where a.workspace_id = target_workspace
      and a.id = asset_ref and a.asset_type::text = asset_type_value) then
    unresolved := coalesce(asset_name, asset_ref::text);
  end if;

  effective := query || jsonb_build_object('limit', lim);
  if asset_ref is not null then effective := effective || jsonb_build_object('_resolved_asset_id', asset_ref::text); end if;

  facet_list := '[]'::jsonb;
  if patterns is not null and array_length(patterns, 1) > 0 then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','text',
      'value', array_to_string(array(select btrim(p,'%') from unnest(patterns) p), ' '),
      'meaning','Words matched against the visible production text of the searched kinds. No stemming and no embeddings.'));
  end if;
  if asset_ref is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','asset','value',
      coalesce((select a.name from tonde.assets a where a.id = asset_ref), asset_ref::text),
      'meaning','Objects whose Scene includes this Asset, or that bind this Asset directly.'));
  end if;
  if asset_type_value is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','asset_type','value', asset_type_value,
      'meaning','Assets of this type in the workspace.'));
  end if;
  if nullif(query ->> 'environment','') is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','environment','value', query ->> 'environment',
      'meaning','Scenes whose Environment Asset name contains this text.'));
  end if;
  if nullif(query ->> 'approval','') is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','approval','value', query ->> 'approval',
      'meaning', case when query ->> 'approval' = 'not_approved'
        then 'Objects whose approval is neither Approved nor Changed After Approval.' else 'Objects at this approval state.' end));
  end if;
  if nullif(query ->> 'execution_method','') is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','execution_method','value', query ->> 'execution_method',
      'meaning','Shots and plans on this execution face.'));
  end if;
  if coalesce(nullif(query ->> 'provider',''), nullif(query ->> 'model','')) is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','provider_model','value',
      coalesce(nullif(query ->> 'provider',''), query ->> 'model'),
      'meaning','Shots with a recorded AI Attempt, or plans naming this provider or model.'));
  end if;
  if nullif(query ->> 'lens','') is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','lens','value', query ->> 'lens',
      'meaning','Lens resource names containing this text, on Real plans. A lens name is what your Setup records; TONDE does not claim a measured focal length.'));
  end if;
  if coalesce(nullif(query ->> 'continuity_state',''), nullif(query ->> 'severity',''), nullif(query ->> 'domain','')) is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','continuity','value',
      concat_ws(' - ', nullif(query ->> 'continuity_state',''), nullif(query ->> 'severity',''), nullif(query ->> 'domain','')),
      'meaning','Continuity findings and declared states matching these filters.'));
  end if;
  if nullif(query ->> 'result_state','') is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','result_state','value', query ->> 'result_state',
      'meaning','Results at this state.'));
  end if;
  if nullif(query ->> 'memory_kind','') is not null then
    facet_list := facet_list || jsonb_build_array(jsonb_build_object('facet','memory_kind','value', query ->> 'memory_kind',
      'meaning','Remembered items of this kind that apply to this Production.'));
  end if;

  if unresolved is not null then
    return jsonb_build_object('interpretation', jsonb_build_object('text', nullif(query ->> 'text',''),
        'tokens', tokens, 'kinds', to_jsonb(requested), 'facets', facet_list, 'limit', lim,
        'limit_note', 'Empty: the named Asset was not found, so no lane ran.'),
      'lanes', '[]'::jsonb, 'results', '[]'::jsonb, 'total', 0, 'returned', 0, 'truncated', false,
      'notes', jsonb_build_array('No Asset in this workspace matches "' || unresolved || '". Nothing was searched, because ignoring the filter would return unrelated objects.'));
  end if;

  series_ref := tonde_private.mi_series_of(target_workspace, target_production);

  foreach lane in array requested loop
    lane_json := tonde_private.mi_search_lane(target_workspace, target_production, lane, effective);
    all_items := all_items || (lane_json -> 'items');
    total := total + (lane_json ->> 'total')::integer;
    lane_counts := lane_counts || jsonb_build_array(jsonb_build_object('lane', lane,
      'total', (lane_json ->> 'total')::integer, 'returned', (lane_json ->> 'returned')::integer));
  end loop;
  returned := jsonb_array_length(all_items);

  return jsonb_build_object(
    'interpretation', jsonb_build_object('text', nullif(query ->> 'text',''), 'tokens', tokens,
      'kinds', to_jsonb(requested), 'facets', facet_list, 'limit', lim, 'series_id', series_ref),
    'lanes', lane_counts, 'results', all_items, 'total', total, 'returned', returned,
    'truncated', total > returned,
    'notes', jsonb_build_array(
      'Search reads structured production state and returns real object references. It does not use embeddings and it does not read media.',
      'Memory results say whether the remembered item is currently in force, so what TONDE is reusing is visible rather than implied.',
      'Assets are workspace-wide reusable entities; they are returned for the whole workspace rather than only this Production.'));
end $$;


-- 12. RLS. Every new table is workspace-isolated; enabling RLS is not optional.
do $$ declare item text; begin
  foreach item in array array['memory_items','memory_candidates','memory_policies'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select on tonde.%I to authenticated', item);
  end loop;
end $$;


-- 13. Mutation guards: identity stays immutable, revisions auto-bump, no row is rewritten.
do $$ declare item text; begin
  foreach item in array array['memory_items','memory_candidates','memory_policies'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;


-- 14. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.memory_policy_set(uuid,uuid,jsonb),
  tonde.memory_policy_get(uuid,uuid),
  tonde.memory_item_set(uuid,uuid,jsonb),
  tonde.memory_item_retire(uuid,uuid,uuid,text),
  tonde.memory_item_list(uuid,uuid,text,text,text,text,integer,integer),
  tonde.memory_resolve(uuid,uuid,text,text),
  tonde.memory_candidate_record(uuid,uuid,jsonb),
  tonde.memory_candidate_list(uuid,uuid,text,integer,integer),
  tonde.memory_candidate_decide(uuid,uuid,uuid,text,text),
  tonde.memory_summary(uuid,uuid),
  tonde.production_search(uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.memory_policy_set(uuid,uuid,jsonb),
  tonde.memory_policy_get(uuid,uuid),
  tonde.memory_item_set(uuid,uuid,jsonb),
  tonde.memory_item_retire(uuid,uuid,uuid,text),
  tonde.memory_item_list(uuid,uuid,text,text,text,text,integer,integer),
  tonde.memory_resolve(uuid,uuid,text,text),
  tonde.memory_candidate_record(uuid,uuid,jsonb),
  tonde.memory_candidate_list(uuid,uuid,text,integer,integer),
  tonde.memory_candidate_decide(uuid,uuid,uuid,text,text),
  tonde.memory_summary(uuid,uuid),
  tonde.production_search(uuid,uuid,jsonb)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050022_versioning_branches.sql
-- ==========================================================================

-- Additive migration: Prompt 9D versioning, creative branches, restore, merge and change impact.
-- Practical creative history, NOT a database git clone. Version history already exists on the
-- canonical `object_versions` table (captured by `capture_revision`); 9D makes it usable: versions
-- are immutable and listed, a compare shows meaningful changed fields rather than a raw JSON diff,
-- restore creates a NEW current revision instead of rewinding, and a branch is an object-level
-- alternative that mutates nothing on the mainline until an explicit, reviewed merge.
--
-- Change impact is not duplicated here either: a consequential apply (merge) records a real impact
-- analysis and propagates through the Prompt 9A engine (`impact_preview` + `apply_impact`), so
-- approved content is flagged for review and locked objects are reported rather than rewritten.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.branch_state as enum ('open','merged','abandoned')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.branch_change_state as enum ('pending','applied','conflicted','rejected')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.merge_state as enum ('proposed','merged','rejected')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Historical versions are immutable. A version records what a row was; it is never rewritten.
-- `capture_revision` only ever inserts, so nothing legitimate updates or deletes a version.
create or replace function tonde_private.versions_immutable() returns trigger
language plpgsql set search_path = '' as $$
begin
  raise exception 'Historical versions are immutable' using errcode = '23514';
end $$;

revoke all on function tonde_private.versions_immutable() from public, anon, authenticated, service_role;

drop trigger if exists versions_immutable on tonde.object_versions;
create trigger versions_immutable before update or delete on tonde.object_versions
  for each row execute function tonde_private.versions_immutable();


-- 3. A restore or a merge creates a normal current revision through the canonical update path, so
-- `guard_mutation` and `capture_revision` still run. The trigger reads a transaction-local action
-- so the version says honestly what produced it, instead of guessing from the SQL verb.
create or replace function tonde_private.capture_revision() returns trigger
language plpgsql security definer set search_path = '' as $$
declare parent_id uuid; action text := nullif(current_setting('tonde.version_action', true), '');
begin
  select id into parent_id from tonde.object_versions where object_id = new.id and branch_name = 'main'
    order by revision desc limit 1;
  insert into tonde.object_versions(workspace_id,object_id,revision,parent_version_id,actor_type,actor_user_id,source_action,snapshot)
    values(new.workspace_id,new.id,new.revision,parent_id,
      case when auth.uid() is null then 'system' else 'user' end, auth.uid(),
      left(coalesce(action, lower(tg_op)), 60), to_jsonb(new));
  return new;
end $$;


-- 4. Creative branches. A branch originates from a known version of a scope object, records its
-- name, scope, source version and reason, and carries object-level alternatives. It is NOT a
-- duplicate Production.
create table if not exists tonde.object_branches (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  scope_object_id uuid not null,
  scope text not null check (scope in ('story','script','act','sequence','scene','shot','execution_plan','asset')),
  name text not null check (length(btrim(name)) between 1 and 160),
  source_version_id uuid,
  source_revision integer check (source_revision is null or source_revision > 0),
  reason text not null default '' check (length(reason) <= 600),
  state tonde.branch_state not null default 'open',
  merged_at timestamptz, merged_by uuid, merged_proposal_id uuid,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, scope_object_id) references tonde.objects(workspace_id, id) on delete restrict,
  foreign key (workspace_id, source_version_id) references tonde.object_versions(workspace_id, id) on delete restrict
);

-- A branch name is unique per scope object while the branch is open; history may reuse the name.
create unique index if not exists object_branches_open on tonde.object_branches(workspace_id, scope_object_id, lower(btrim(name)))
  where state = 'open';

create index if not exists object_branches_by_production on tonde.object_branches(workspace_id, production_id, state, created_at desc);


-- 5. Proposed edits on a branch. A branch change is a field patch for one object, computed against
-- the mainline revision it was written from. It touches nothing on the mainline until a merge.
create table if not exists tonde.branch_changes (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, branch_id uuid not null,
  target_object_id uuid not null,
  base_version_id uuid, base_revision integer check (base_revision is null or base_revision > 0),
  patch jsonb not null check (jsonb_typeof(patch) = 'object'),
  changed_fields text[] not null default '{}',
  note text not null default '' check (length(note) <= 600),
  state tonde.branch_change_state not null default 'pending',
  applied_version_id uuid, applied_revision integer,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, branch_id, target_object_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, branch_id) references tonde.object_branches(workspace_id, id) on delete restrict,
  foreign key (workspace_id, target_object_id) references tonde.objects(workspace_id, id) on delete restrict
);

create index if not exists branch_changes_by_branch on tonde.branch_changes(workspace_id, branch_id, state);


-- 6. Merge proposals. A merge is a REVIEWED proposal, never a silent copy: it pins every change's
-- base revision, records clean and conflicted items separately, and keeps the decision.
create table if not exists tonde.merge_proposals (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, branch_id uuid not null,
  items jsonb not null default '[]' check (jsonb_typeof(items) = 'array'),
  conflicts jsonb not null default '[]' check (jsonb_typeof(conflicts) = 'array'),
  counts jsonb not null default '{}' check (jsonb_typeof(counts) = 'object'),
  structure_revision integer check (structure_revision is null or structure_revision > 0),
  state tonde.merge_state not null default 'proposed',
  decided_by uuid, decided_at timestamptz,
  decision_note text not null default '' check (length(decision_note) <= 800),
  applied jsonb not null default '[]' check (jsonb_typeof(applied) = 'array'),
  impact jsonb not null default '{}' check (jsonb_typeof(impact) = 'object'),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, branch_id) references tonde.object_branches(workspace_id, id) on delete restrict
);

create index if not exists merge_proposals_recent on tonde.merge_proposals(workspace_id, production_id, created_at desc);


-- 7. Private helpers (not user-facing; reachable only through the security-definer RPCs below).
-- Which canonical fields a branch change may set, per object kind. A branch change is a field
-- patch, never a whole-row replacement, so identity, ordering, approval and locks stay untouched.
create or replace function tonde_private.vb_fields(kind_value text) returns jsonb
language sql immutable set search_path = '' as $$
  select case kind_value
    when 'creative_document' then jsonb_build_object('table','creative_documents','scope','production',
      'fields', jsonb_build_object('title','text','content','text'))
    when 'scene' then jsonb_build_object('table','scenes','scope','production',
      'fields', jsonb_build_object('title','text','description','text','purpose','text','planned_duration_ms','bigint'))
    when 'shot' then jsonb_build_object('table','shots','scope','production',
      'fields', jsonb_build_object('title','text','description','text','action','text','purpose','text','subject','text','planned_duration_ms','bigint'))
    when 'execution_plan' then jsonb_build_object('table','execution_plans','scope','production',
      'fields', jsonb_build_object('shot_size','text','movement','text','framing','text','composition','text',
        'camera_position','text','camera_height','text','camera_angle','text','lighting_intent','text','plan_metadata','jsonb'))
    when 'asset' then jsonb_build_object('table','assets','scope','workspace',
      'fields', jsonb_build_object('name','text','description','text','search_metadata','jsonb','consistency_metadata','jsonb'))
    else null end;
$$;

revoke all on function tonde_private.vb_fields(text) from public, anon, authenticated, service_role;


-- A readable label for a changed field. Names are product words, not column names.
create or replace function tonde_private.vb_field_label(field_name text) returns text
language sql immutable set search_path = '' as $$
  select case field_name
    when 'title' then 'Title' when 'content' then 'Content' when 'description' then 'Description'
    when 'purpose' then 'Purpose' when 'action' then 'Action' when 'subject' then 'Subject'
    when 'planned_duration_ms' then 'Planned duration' when 'shot_size' then 'Shot size'
    when 'movement' then 'Movement' when 'framing' then 'Framing' when 'composition' then 'Composition'
    when 'camera_position' then 'Camera position' when 'camera_height' then 'Camera height'
    when 'camera_angle' then 'Camera angle' when 'lighting_intent' then 'Lighting intent'
    when 'plan_metadata' then 'Plan metadata' when 'name' then 'Name'
    when 'search_metadata' then 'Search metadata' when 'consistency_metadata' then 'Consistency metadata'
    else initcap(replace(field_name, '_', ' ')) end;
$$;

revoke all on function tonde_private.vb_field_label(text) from public, anon, authenticated, service_role;


-- Resolve a version row, refusing a version that is not in this workspace.
create or replace function tonde_private.vb_version(target_workspace uuid, target_version uuid) returns tonde.object_versions
language plpgsql stable security definer set search_path = '' as $$
declare version_row tonde.object_versions;
begin
  select * into version_row from tonde.object_versions where workspace_id = target_workspace and id = target_version;
  if not found then raise exception 'That version is unavailable' using errcode = 'P0002'; end if;
  return version_row;
end $$;

revoke all on function tonde_private.vb_version(uuid,uuid) from public, anon, authenticated, service_role;


-- Resolve an object, requiring Production coherence. An Asset is workspace-level, so its object row
-- has no Production; every other kind must belong to the Production the caller named.
create or replace function tonde_private.vb_object(target_workspace uuid, target_production uuid, target_object uuid) returns tonde.objects
language plpgsql stable security definer set search_path = '' as $$
declare object_row tonde.objects;
begin
  select * into object_row from tonde.objects
    where workspace_id = target_workspace and id = target_object
      and (production_id is null or production_id = target_production);
  if not found then raise exception 'That object is unavailable in this Production' using errcode = 'P0002'; end if;
  return object_row;
end $$;

revoke all on function tonde_private.vb_object(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- The latest mainline version of an object, if it has been captured at least once.
create or replace function tonde_private.vb_latest_version(target_workspace uuid, target_object uuid) returns uuid
language sql stable security definer set search_path = '' as $$
  select (array_agg(v.id order by v.revision desc, v.created_at desc))[1]
  from tonde.object_versions v
  where v.workspace_id = target_workspace and v.object_id = target_object and v.branch_name = 'main';
$$;

revoke all on function tonde_private.vb_latest_version(uuid,uuid) from public, anon, authenticated, service_role;


-- Meaningful differences between two snapshots, limited to the fields a branch change can set for
-- the object's kind. A raw JSON diff is never what the creator sees.
create or replace function tonde_private.vb_diff(target_workspace uuid, kind_value text, left_snapshot jsonb, right_snapshot jsonb)
returns jsonb language plpgsql stable set search_path = '' as $$
declare fields jsonb; field_name text; items jsonb := '[]'::jsonb; before_value jsonb; after_value jsonb;
begin
  fields := tonde_private.vb_fields(kind_value);
  if fields is null then return items; end if;
  for field_name in select jsonb_object_keys(fields->'fields') order by 1 loop
    before_value := left_snapshot -> field_name;
    after_value := right_snapshot -> field_name;
    if before_value is distinct from after_value then
      items := items || jsonb_build_array(jsonb_build_object(
        'field', field_name, 'label', tonde_private.vb_field_label(field_name),
        'before', coalesce(before_value, 'null'::jsonb), 'after', coalesce(after_value, 'null'::jsonb)));
    end if;
  end loop;
  return items;
end $$;

revoke all on function tonde_private.vb_diff(uuid,text,jsonb,jsonb) from public, anon, authenticated, service_role;


-- Apply a validated patch to the canonical row. This is the ONLY place a version operation reaches
-- mainline, and it runs through the normal update path: guard_mutation and capture_revision still
-- apply. It refuses stale operations (40001) and unsupported fields (22023).
create or replace function tonde_private.vb_patch_apply(target_workspace uuid, target_production uuid, target_object uuid,
  patch jsonb, expected_revision integer default null, action text default 'update')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare object_row tonde.objects; map jsonb; field_name text; field_type text; assignments text := '';
  scope_kind text; new_revision integer; changed text[] := '{}'; value_text text;
begin
  object_row := tonde_private.vb_object(target_workspace, target_production, target_object);
  map := tonde_private.vb_fields(object_row.kind);
  if map is null then raise exception 'That object kind cannot be changed by a version operation' using errcode = '22023'; end if;
  if jsonb_typeof(patch) <> 'object' then raise exception 'A change is an object of fields' using errcode = '22023'; end if;
  for field_name in select jsonb_object_keys(patch) order by 1 loop
    if not (map->'fields' ? field_name) then
      raise exception 'The field % cannot be changed this way', field_name using errcode = '22023';
    end if;
    field_type := map->'fields'->>field_name;
    if patch->field_name = 'null'::jsonb then
      assignments := assignments || format(', %I = null', field_name);
    else
      value_text := case when field_type = 'jsonb' then (patch->field_name)::text else patch->>field_name end;
      assignments := assignments || format(', %I = %L::%s', field_name, value_text, field_type);
    end if;
    changed := changed || field_name;
  end loop;
  if assignments = '' then
    raise exception 'Provide at least one field to change' using errcode = '22023';
  end if;
  assignments := ltrim(assignments, ', ');
  scope_kind := map->>'scope';
  perform set_config('tonde.version_action', coalesce(nullif(action, ''), 'update'), true);
  if scope_kind = 'workspace' then
    execute format('update tonde.%I set %s where workspace_id = $1 and id = $2 and ($3 is null or revision = $3) returning revision',
      map->>'table', assignments) using target_workspace, target_object, expected_revision into new_revision;
  else
    execute format('update tonde.%I set %s where workspace_id = $1 and production_id = $2 and id = $3 and ($4 is null or revision = $4) returning revision',
      map->>'table', assignments) using target_workspace, target_production, target_object, expected_revision into new_revision;
  end if;
  perform set_config('tonde.version_action', '', true);
  if new_revision is null then
    raise exception 'That object changed since this change was written. Preview the merge again.' using errcode = '40001';
  end if;
  return jsonb_build_object('object_id', target_object, 'kind', object_row.kind, 'revision', new_revision,
    'changed_fields', to_jsonb(changed), 'action', coalesce(nullif(action,''),'update'));
end $$;

revoke all on function tonde_private.vb_patch_apply(uuid,uuid,uuid,jsonb,integer,text)
  from public, anon, authenticated, service_role;


-- A bounded "structure revision" for a Production, so a merge proposal can be rejected as stale
-- rather than merged against a timeline the creator never previewed.
create or replace function tonde_private.vb_structure_revision(target_workspace uuid, target_production uuid) returns integer
language sql stable security definer set search_path = '' as $$
  select coalesce(sum(revision), 0)::integer from (
    select revision from tonde.productions where workspace_id = target_workspace and id = target_production
    union all select revision from tonde.acts where workspace_id = target_workspace and production_id = target_production
    union all select revision from tonde.sequences where workspace_id = target_workspace and production_id = target_production
    union all select revision from tonde.scenes where workspace_id = target_workspace and production_id = target_production
    union all select revision from tonde.shots where workspace_id = target_workspace and production_id = target_production) summed;
$$;

revoke all on function tonde_private.vb_structure_revision(uuid,uuid) from public, anon, authenticated, service_role;


-- 8. Version read surface.
create or replace function tonde.version_list(target_workspace uuid, target_production uuid, target_object uuid,
  target_branch text default 'main', target_limit integer default 50, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer; current_revision integer; object_row tonde.objects; branch_value text;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  object_row := tonde_private.vb_object(target_workspace, target_production, target_object);
  lim := least(greatest(coalesce(target_limit, 50), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  branch_value := coalesce(nullif(btrim(coalesce(target_branch, '')), ''), 'main');
  select tonde_private.pi_object_revision(target_workspace, target_object) into current_revision;
  select count(*) into total from tonde.object_versions v
    where v.workspace_id = target_workspace and v.object_id = target_object and v.branch_name = branch_value;
  select coalesce(jsonb_agg(jsonb_build_object(
      'version_id', v.id, 'object_id', v.object_id, 'revision', v.revision, 'branch', v.branch_name,
      'parent_version_id', v.parent_version_id, 'actor_type', v.actor_type, 'actor_user_id', v.actor_user_id,
      'source_action', v.source_action, 'created_at', v.created_at,
      'is_current', case when v.branch_name = 'main' and v.revision = current_revision then true else false end)
      order by v.revision desc, v.created_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.object_versions v
    where v.workspace_id = target_workspace and v.object_id = target_object and v.branch_name = branch_value
    order by v.revision desc, v.created_at desc limit lim offset off) v;
  return jsonb_build_object('object_id', target_object, 'object_kind', object_row.kind, 'object_label',
    tonde_private.pi_label(target_workspace, target_object), 'branch', branch_value, 'current_revision', current_revision,
    'items', items, 'total', total, 'limit', lim, 'offset', off, 'truncated', total > off + lim,
    'note', 'Versions are immutable records of what the object was. Historical versions are never edited.');
end $$;


create or replace function tonde.version_get(target_workspace uuid, target_production uuid, target_version uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare version_row tonde.object_versions; object_row tonde.objects; current_revision integer;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  version_row := tonde_private.vb_version(target_workspace, target_version);
  object_row := tonde_private.vb_object(target_workspace, target_production, version_row.object_id);
  select tonde_private.pi_object_revision(target_workspace, version_row.object_id) into current_revision;
  return jsonb_build_object('version_id', version_row.id, 'object_id', version_row.object_id,
    'object_kind', object_row.kind, 'object_label', tonde_private.pi_label(target_workspace, version_row.object_id),
    'revision', version_row.revision, 'branch', version_row.branch_name, 'parent_version_id', version_row.parent_version_id,
    'actor_type', version_row.actor_type, 'actor_user_id', version_row.actor_user_id,
    'source_action', version_row.source_action, 'snapshot', version_row.snapshot, 'created_at', version_row.created_at,
    'is_current', version_row.branch_name = 'main' and version_row.revision = current_revision,
    'note', 'This is what the object was at revision ' || version_row.revision || '. It cannot be edited.');
end $$;


create or replace function tonde.version_compare(target_workspace uuid, target_production uuid, left_version uuid, right_version uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare left_row tonde.object_versions; right_row tonde.object_versions; object_row tonde.objects; changes jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  left_row := tonde_private.vb_version(target_workspace, left_version);
  right_row := tonde_private.vb_version(target_workspace, right_version);
  if left_row.object_id <> right_row.object_id then
    raise exception 'Only versions of the same object can be compared' using errcode = '22023';
  end if;
  object_row := tonde_private.vb_object(target_workspace, target_production, left_row.object_id);
  changes := tonde_private.vb_diff(target_workspace, object_row.kind, left_row.snapshot, right_row.snapshot);
  return jsonb_build_object('object_id', left_row.object_id, 'object_kind', object_row.kind,
    'object_label', tonde_private.pi_label(target_workspace, left_row.object_id),
    'left_version_id', left_row.id, 'left_revision', left_row.revision,
    'right_version_id', right_row.id, 'right_revision', right_row.revision,
    'changes', changes, 'change_count', jsonb_array_length(changes),
    'note', case when jsonb_array_length(changes) = 0 then 'No meaningful creative field changed between these versions.'
      else 'Only meaningful creative fields are shown, not a raw JSON diff.' end);
end $$;


-- 9. Restore: create a NEW current revision based on an older version. Intervening history stays.
create or replace function tonde.version_restore(target_workspace uuid, target_production uuid, target_version uuid,
  note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare version_row tonde.object_versions; object_row tonde.objects; map jsonb; field_name text; field_type text;
  patch jsonb := '{}'::jsonb; result jsonb; current_revision integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  version_row := tonde_private.vb_version(target_workspace, target_version);
  object_row := tonde_private.vb_object(target_workspace, target_production, version_row.object_id);
  map := tonde_private.vb_fields(object_row.kind);
  if map is null then raise exception 'That object kind cannot be restored' using errcode = '22023'; end if;
  for field_name in select jsonb_object_keys(map->'fields') order by 1 loop
    field_type := map->'fields'->>field_name;
    patch := jsonb_set(patch, array[field_name], coalesce(version_row.snapshot->field_name, 'null'::jsonb), true);
  end loop;
  current_revision := tonde_private.pi_object_revision(target_workspace, version_row.object_id);
  if current_revision = version_row.revision then
    raise exception 'That version is already the current revision' using errcode = '23514';
  end if;
  result := tonde_private.vb_patch_apply(target_workspace, target_production, version_row.object_id, patch, current_revision, 'restore');
  return jsonb_build_object('object_id', version_row.object_id, 'restored_from_version_id', version_row.id,
    'restored_from_revision', version_row.revision, 'new_revision', result->'revision',
    'changed_fields', result->'changed_fields', 'note_text', left(coalesce(note_text,''), 400),
    'note', 'A new current revision was created from an older version. Nothing was rewound and no history was deleted.');
end $$;


-- 10. Branches.
create or replace function tonde.branch_create(target_workspace uuid, target_production uuid, scope_object uuid, branch jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare object_row tonde.objects; created tonde.object_branches; scope_value text; name_value text;
  source_version uuid; source_rev integer; version_row tonde.object_versions;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(branch) <> 'object' then raise exception 'Invalid branch payload' using errcode = '22023'; end if;
  object_row := tonde_private.vb_object(target_workspace, target_production, scope_object);
  name_value := btrim(coalesce(branch->>'name', ''));
  if length(name_value) = 0 or length(name_value) > 160 then
    raise exception 'A branch needs a name of 1 to 160 characters' using errcode = '22023';
  end if;
  scope_value := coalesce(nullif(branch->>'scope',''), 'production');
  if scope_value not in ('story','script','act','sequence','scene','shot','execution_plan','asset') then
    raise exception 'Unsupported branch scope' using errcode = '22023';
  end if;
  -- The declared scope must describe the object actually being branched, or the branch would
  -- report a scope that is not true.
  if not ((object_row.kind = 'creative_document' and scope_value in ('story','script'))
    or (object_row.kind = 'scene' and scope_value = 'scene')
    or (object_row.kind = 'shot' and scope_value = 'shot')
    or (object_row.kind = 'execution_plan' and scope_value = 'execution_plan')
    or (object_row.kind = 'act' and scope_value = 'act')
    or (object_row.kind = 'sequence' and scope_value = 'sequence')
    or (object_row.kind = 'asset' and scope_value = 'asset')) then
    raise exception 'The branch scope must match the object it branches' using errcode = '22023';
  end if;
  if coalesce(branch->>'source_version_id','') <> '' then
    source_version := (branch->>'source_version_id')::uuid;
    version_row := tonde_private.vb_version(target_workspace, source_version);
    if version_row.object_id <> scope_object then
      raise exception 'A branch must originate from a version of its scope object' using errcode = '22023';
    end if;
    source_rev := version_row.revision;
  else
    source_version := tonde_private.vb_latest_version(target_workspace, scope_object);
    source_rev := case when source_version is null then null
      else tonde_private.pi_object_revision(target_workspace, scope_object) end;
  end if;
  insert into tonde.object_branches(workspace_id, production_id, scope_object_id, scope, name, source_version_id,
    source_revision, reason)
  values (target_workspace, target_production, scope_object, scope_value, left(name_value,160), source_version,
    source_rev, left(coalesce(branch->>'reason',''),600))
  returning * into created;
  return jsonb_build_object('branch_id', created.id, 'name', created.name, 'scope', created.scope,
    'scope_object_id', created.scope_object_id, 'source_version_id', created.source_version_id,
    'source_revision', created.source_revision, 'state', created.state,
    'note', 'The branch is an alternative. Nothing on the mainline changed.');
end $$;


create or replace function tonde.branch_list(target_workspace uuid, target_production uuid, target_state text default null,
  target_limit integer default 50, target_offset integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare lim integer; off integer; items jsonb; total integer;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  lim := least(greatest(coalesce(target_limit, 50), 1), 200);
  off := greatest(coalesce(target_offset, 0), 0);
  if target_state is not null and target_state not in ('open','merged','abandoned') then
    raise exception 'Unsupported branch state' using errcode = '22023';
  end if;
  select count(*) into total from tonde.object_branches b
    where b.workspace_id = target_workspace and b.production_id = target_production
      and (target_state is null or b.state = target_state::tonde.branch_state);
  select coalesce(jsonb_agg(jsonb_build_object(
      'branch_id', b.id, 'name', b.name, 'scope', b.scope, 'scope_object_id', b.scope_object_id,
      'scope_object_label', tonde_private.pi_label(target_workspace, b.scope_object_id),
      'source_version_id', b.source_version_id, 'source_revision', b.source_revision,
      'state', b.state, 'reason', b.reason, 'merged_at', b.merged_at, 'merged_proposal_id', b.merged_proposal_id,
      'changes', (select count(*) from tonde.branch_changes c where c.branch_id = b.id and c.state = 'pending'),
      'created_at', b.created_at, 'updated_at', b.updated_at) order by b.created_at desc), '[]'::jsonb)
    into items
  from (select * from tonde.object_branches b
    where b.workspace_id = target_workspace and b.production_id = target_production
      and (target_state is null or b.state = target_state::tonde.branch_state)
    order by b.created_at desc limit lim offset off) b;
  return jsonb_build_object('items', items, 'total', total, 'limit', lim, 'offset', off, 'truncated', total > off + lim,
    'note', 'A branch is an object-level alternative, not a duplicate Production.');
end $$;


create or replace function tonde.branch_detail(target_workspace uuid, target_production uuid, target_branch uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare b tonde.object_branches; changes jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select * into b from tonde.object_branches where workspace_id = target_workspace and id = target_branch
    and production_id = target_production;
  if not found then raise exception 'That branch is unavailable' using errcode = 'P0002'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'change_id', c.id, 'target_object_id', c.target_object_id,
      'target_label', tonde_private.pi_label(target_workspace, c.target_object_id),
      'target_kind', (select kind from tonde.objects where workspace_id = target_workspace and id = c.target_object_id),
      'base_version_id', c.base_version_id, 'base_revision', c.base_revision, 'patch', c.patch,
      'changed_fields', to_jsonb(c.changed_fields), 'note', c.note, 'state', c.state,
      'applied_version_id', c.applied_version_id, 'applied_revision', c.applied_revision,
      'current_revision', tonde_private.pi_object_revision(target_workspace, c.target_object_id),
      'created_at', c.created_at) order by c.created_at), '[]'::jsonb)
    into changes
  from tonde.branch_changes c where c.workspace_id = target_workspace and c.branch_id = b.id;
  return jsonb_build_object('branch_id', b.id, 'name', b.name, 'scope', b.scope, 'scope_object_id', b.scope_object_id,
    'scope_object_label', tonde_private.pi_label(target_workspace, b.scope_object_id),
    'source_version_id', b.source_version_id, 'source_revision', b.source_revision, 'reason', b.reason,
    'state', b.state, 'merged_at', b.merged_at, 'merged_proposal_id', b.merged_proposal_id,
    'changes', changes, 'change_count', jsonb_array_length(changes),
    'note', 'Branch edits never change the mainline. Only an accepted merge does.');
end $$;


-- Record or replace a proposed change on a branch. Nothing on the mainline is touched.
create or replace function tonde.branch_change_set(target_workspace uuid, target_production uuid, target_branch uuid, change jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare b tonde.object_branches; object_row tonde.objects; map jsonb; field_name text; target uuid;
  patch_value jsonb; note_value text; existing tonde.branch_changes; base_version uuid; base_rev integer; changed_list text[] := '{}';
  result tonde.branch_changes;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(change) <> 'object' then raise exception 'Invalid branch change payload' using errcode = '22023'; end if;
  select * into b from tonde.object_branches where workspace_id = target_workspace and id = target_branch
    and production_id = target_production;
  if not found then raise exception 'That branch is unavailable' using errcode = 'P0002'; end if;
  if b.state <> 'open' then raise exception 'That branch is not open' using errcode = '23514'; end if;
  if coalesce(change->>'target_object_id','') = '' then
    raise exception 'A branch change names the object it changes' using errcode = '22023';
  end if;
  target := (change->>'target_object_id')::uuid;
  object_row := tonde_private.vb_object(target_workspace, target_production, target);
  map := tonde_private.vb_fields(object_row.kind);
  if map is null then raise exception 'That object kind cannot change on a branch' using errcode = '22023'; end if;
  patch_value := coalesce(change->'patch', '{}'::jsonb);
  if jsonb_typeof(patch_value) <> 'object' then raise exception 'A branch change patch is an object of fields' using errcode = '22023'; end if;
  for field_name in select jsonb_object_keys(patch_value) order by 1 loop
    if not (map->'fields' ? field_name) then
      raise exception 'The field % cannot change on a branch', field_name using errcode = '22023';
    end if;
    changed_list := changed_list || field_name;
  end loop;
  if coalesce(array_length(changed_list, 1), 0) = 0 then
    raise exception 'Provide at least one field to change' using errcode = '22023';
  end if;
  note_value := left(coalesce(change->>'note',''), 600);
  base_version := tonde_private.vb_latest_version(target_workspace, target);
  base_rev := tonde_private.pi_object_revision(target_workspace, target);
  select * into existing from tonde.branch_changes
    where workspace_id = target_workspace and branch_id = b.id and target_object_id = target;
  if found then
    update tonde.branch_changes c set patch = patch_value, changed_fields = changed_list, note = note_value,
      base_version_id = base_version, base_revision = base_rev, state = 'pending',
      applied_version_id = null, applied_revision = null
    where c.id = existing.id returning * into result;
  else
    insert into tonde.branch_changes(workspace_id, production_id, branch_id, target_object_id, base_version_id,
      base_revision, patch, changed_fields, note)
    values (target_workspace, target_production, b.id, target, base_version, base_rev, patch_value, changed_list, note_value)
    returning * into result;
  end if;
  return jsonb_build_object('change_id', result.id, 'branch_id', b.id, 'target_object_id', result.target_object_id,
    'target_label', tonde_private.pi_label(target_workspace, result.target_object_id), 'target_kind', object_row.kind,
    'base_revision', result.base_revision, 'changed_fields', to_jsonb(result.changed_fields), 'state', result.state,
    'note', 'Recorded on the branch. The mainline is unchanged until a merge is accepted.');
end $$;


create or replace function tonde.branch_change_clear(target_workspace uuid, target_production uuid, target_branch uuid,
  target_change uuid, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare b tonde.object_branches; c tonde.branch_changes;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into b from tonde.object_branches where workspace_id = target_workspace and id = target_branch
    and production_id = target_production;
  if not found then raise exception 'That branch is unavailable' using errcode = 'P0002'; end if;
  select * into c from tonde.branch_changes where workspace_id = target_workspace and branch_id = b.id and id = target_change;
  if not found then raise exception 'That branch change is unavailable' using errcode = 'P0002'; end if;
  if c.state = 'applied' then raise exception 'That change was already merged' using errcode = '23514'; end if;
  update tonde.branch_changes ch set state = 'rejected', note = left(coalesce(note_text, ch.note), 600)
    where ch.id = c.id;
  return jsonb_build_object('change_id', c.id, 'state', 'rejected',
    'note', 'The proposed change was discarded. It stays readable as branch history.');
end $$;


create or replace function tonde.branch_state_set(target_workspace uuid, target_production uuid, target_branch uuid,
  desired_state text, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare b tonde.object_branches;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if desired_state not in ('open','abandoned') then
    raise exception 'A branch is opened or abandoned here; merging happens through a merge decision' using errcode = '22023';
  end if;
  select * into b from tonde.object_branches where workspace_id = target_workspace and id = target_branch
    and production_id = target_production;
  if not found then raise exception 'That branch is unavailable' using errcode = 'P0002'; end if;
  if b.state = 'merged' then raise exception 'A merged branch is closed history' using errcode = '23514'; end if;
  update tonde.object_branches br set state = desired_state::tonde.branch_state, reason = left(coalesce(nullif(note_text,''), br.reason), 600)
    where br.id = b.id;
  return jsonb_build_object('branch_id', b.id, 'state', desired_state,
    'note', case when desired_state = 'abandoned' then 'The branch was abandoned. Its history stays readable.'
      else 'The branch is open again.' end);
end $$;


-- 11. Merge preview. A reviewed proposal: every pending change is classified clean or conflicted,
-- pinned to the revision it was written from, and a dependency-aware impact summary is recorded.
create or replace function tonde.merge_preview(target_workspace uuid, target_production uuid, target_branch uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare b tonde.object_branches; change_row tonde.branch_changes; object_row tonde.objects; map jsonb;
  items jsonb := '[]'::jsonb; conflicts jsonb := '[]'::jsonb; clean_count integer := 0; conflict_count integer := 0;
  current_rev integer; field_name text; field_type text; field_conflicts jsonb; base_snapshot jsonb; current_snapshot jsonb;
  schema_table text; scope_kind text; base_ver tonde.object_versions; proposal uuid; structure_rev integer;
  impact_map jsonb := '{}'::jsonb; target_ids uuid[] := '{}';
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into b from tonde.object_branches where workspace_id = target_workspace and id = target_branch
    and production_id = target_production;
  if not found then raise exception 'That branch is unavailable' using errcode = 'P0002'; end if;
  if b.state <> 'open' then raise exception 'That branch is not open' using errcode = '23514'; end if;
  structure_rev := tonde_private.vb_structure_revision(target_workspace, target_production);
  for change_row in select * from tonde.branch_changes c
    where c.workspace_id = target_workspace and c.branch_id = b.id and c.state in ('pending','conflicted')
    order by c.created_at loop
    object_row := tonde_private.vb_object(target_workspace, target_production, change_row.target_object_id);
    map := tonde_private.vb_fields(object_row.kind);
    current_rev := tonde_private.pi_object_revision(target_workspace, change_row.target_object_id);
    base_ver := case when change_row.base_version_id is null then null
      else tonde_private.vb_version(target_workspace, change_row.base_version_id) end;
    base_snapshot := coalesce(base_ver.snapshot, '{}'::jsonb);
    schema_table := map->>'table';
    scope_kind := map->>'scope';
    if scope_kind = 'workspace' then
      execute format('select to_jsonb(t) from tonde.%I t where t.workspace_id = $1 and t.id = $2',
        schema_table) using target_workspace, change_row.target_object_id into current_snapshot;
    else
      execute format('select to_jsonb(t) from tonde.%I t where t.workspace_id = $1 and t.production_id = $2 and t.id = $3',
        schema_table) using target_workspace, target_production, change_row.target_object_id into current_snapshot;
    end if;
    field_conflicts := '[]'::jsonb;
    if change_row.base_revision is distinct from current_rev then
      for field_name in select unnest(change_row.changed_fields) order by 1 loop
        field_type := map->'fields'->>field_name;
        -- A real conflict: main moved AND the branch changes the same field to a different value.
        if (current_snapshot -> field_name) is distinct from (base_snapshot -> field_name)
          and (change_row.patch -> field_name) is distinct from (current_snapshot -> field_name) then
          field_conflicts := field_conflicts || jsonb_build_array(jsonb_build_object(
            'field', field_name, 'label', tonde_private.vb_field_label(field_name),
            'branch_value', coalesce(change_row.patch -> field_name, 'null'::jsonb),
            'main_value', coalesce(current_snapshot -> field_name, 'null'::jsonb),
            'base_value', coalesce(base_snapshot -> field_name, 'null'::jsonb)));
        end if;
      end loop;
    end if;
    if change_row.base_revision is distinct from current_rev then
      conflict_count := conflict_count + 1;
      items := items || jsonb_build_array(jsonb_build_object(
        'change_id', change_row.id, 'target_object_id', change_row.target_object_id,
        'target_label', tonde_private.pi_label(target_workspace, change_row.target_object_id),
        'target_kind', object_row.kind, 'base_revision', change_row.base_revision, 'current_revision', current_rev,
        'changed_fields', to_jsonb(change_row.changed_fields), 'status', 'conflict', 'conflicts', field_conflicts));
      conflicts := conflicts || jsonb_build_array(jsonb_build_object(
        'change_id', change_row.id, 'target_object_id', change_row.target_object_id,
        'target_label', tonde_private.pi_label(target_workspace, change_row.target_object_id),
        'base_revision', change_row.base_revision, 'current_revision', current_rev,
        'reason', 'The mainline moved after this branch change was written.',
        'fields', field_conflicts));
    else
      clean_count := clean_count + 1;
      items := items || jsonb_build_array(jsonb_build_object(
        'change_id', change_row.id, 'target_object_id', change_row.target_object_id,
        'target_label', tonde_private.pi_label(target_workspace, change_row.target_object_id),
        'target_kind', object_row.kind, 'base_revision', change_row.base_revision, 'current_revision', current_rev,
        'changed_fields', to_jsonb(change_row.changed_fields), 'status', 'clean', 'conflicts', '[]'::jsonb));
      target_ids := target_ids || change_row.target_object_id;
    end if;
  end loop;
  -- Dependency-aware impact of what the merge would touch, computed but not applied.
  if coalesce(array_length(target_ids, 1), 0) > 0 then
    select coalesce(jsonb_object_agg(entry.object_id::text, entry.summary), '{}'::jsonb) into impact_map
    from (
      select t as object_id,
        jsonb_build_object(
          'direct', (select count(*) from jsonb_array_elements(g->'nodes') n where n->>'classification' = 'direct'),
          'downstream', (select count(*) from jsonb_array_elements(g->'nodes') n where n->>'classification' = 'downstream'),
          'potential', (select count(*) from jsonb_array_elements(g->'nodes') n where n->>'classification' = 'potential'),
          'total', jsonb_array_length(g->'nodes'),
          'truncated', coalesce((g->>'truncated')::boolean, false)) as summary
      from unnest(target_ids) as t
      cross join lateral (select tonde.dependency_graph(target_workspace, target_production, t, 'forward', 2, 100) as g) graph_row
    ) entry;
  end if;
  insert into tonde.merge_proposals(workspace_id, production_id, branch_id, items, conflicts, counts, structure_revision, impact)
  values (target_workspace, target_production, b.id, items, conflicts,
    jsonb_build_object('clean', clean_count, 'conflicted', conflict_count, 'total', clean_count + conflict_count),
    structure_rev, jsonb_build_object('targets', impact_map, 'note', 'Impact is computed, never applied, by this preview.'))
  returning id into proposal;
  update tonde.branch_changes c set state = case when c.base_revision is distinct from
      tonde_private.pi_object_revision(target_workspace, c.target_object_id) then 'conflicted'::tonde.branch_change_state
      else 'pending'::tonde.branch_change_state end
    where c.workspace_id = target_workspace and c.branch_id = b.id and c.state in ('pending','conflicted');
  return jsonb_build_object('proposal_id', proposal, 'branch_id', b.id, 'branch_name', b.name,
    'structure_revision', structure_rev, 'items', items, 'conflicts', conflicts,
    'counts', jsonb_build_object('clean', clean_count, 'conflicted', conflict_count, 'total', clean_count + conflict_count),
    'impact', impact_map, 'state', 'proposed',
    'note', 'Merge is a proposal. Conflicted changes are never resolved automatically.');
end $$;


-- 12. Merge decision. Accepting applies only the selected clean changes as NEW mainline revisions,
-- then propagates the consequence through the 9A impact engine. Rejecting changes nothing.
create or replace function tonde.merge_decide(target_workspace uuid, target_production uuid, target_proposal uuid,
  decision text, selected_ids uuid[] default '{}', propagation text default 'change_only_this', note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare proposal tonde.merge_proposals; b tonde.object_branches; change_row tonde.branch_changes; applied_items jsonb := '[]'::jsonb;
  skipped jsonb := '[]'::jsonb; result jsonb; analysis jsonb; propagation_result jsonb; impact_summary jsonb := '[]'::jsonb;
  applied_count integer := 0; current_rev integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if decision not in ('merge','reject') then raise exception 'A merge decision is merge or reject' using errcode = '22023'; end if;
  if coalesce(propagation,'') not in ('update_all','review_changes','change_only_this') then
    raise exception 'Unsupported propagation mode' using errcode = '22023';
  end if;
  select * into proposal from tonde.merge_proposals
    where workspace_id = target_workspace and production_id = target_production and id = target_proposal;
  if not found then raise exception 'That merge proposal is unavailable' using errcode = 'P0002'; end if;
  if proposal.state <> 'proposed' then raise exception 'That merge proposal was already decided' using errcode = '23514'; end if;
  if proposal.structure_revision is distinct from tonde_private.vb_structure_revision(target_workspace, target_production) then
    raise exception 'The Production changed since this merge was previewed. Preview the merge again.' using errcode = '40001';
  end if;
  select * into b from tonde.object_branches where workspace_id = target_workspace and id = proposal.branch_id;
  if decision = 'reject' then
    update tonde.merge_proposals p set state = 'rejected', decided_by = auth.uid(), decided_at = now(),
      decision_note = left(coalesce(note_text,''), 800) where p.id = proposal.id;
    return jsonb_build_object('proposal_id', proposal.id, 'branch_id', b.id, 'state', 'rejected',
      'applied', '[]'::jsonb, 'note', 'The merge was rejected. The mainline and the branch are unchanged.');
  end if;
  for change_row in select * from tonde.branch_changes c
    where c.workspace_id = target_workspace and c.branch_id = b.id and c.state = 'pending'
    order by c.created_at loop
    if coalesce(array_length(selected_ids, 1), 0) > 0 and not (change_row.id = any(selected_ids)) then
      skipped := skipped || jsonb_build_array(jsonb_build_object('change_id', change_row.id,
        'target_object_id', change_row.target_object_id, 'reason', 'not selected'));
      continue;
    end if;
    result := tonde_private.vb_patch_apply(target_workspace, target_production, change_row.target_object_id,
      change_row.patch, change_row.base_revision, 'merge');
    update tonde.branch_changes c set state = 'applied', applied_revision = (result->>'revision')::integer,
      applied_version_id = tonde_private.vb_latest_version(target_workspace, change_row.target_object_id)
      where c.id = change_row.id;
    applied_count := applied_count + 1;
    applied_items := applied_items || jsonb_build_array(jsonb_build_object('change_id', change_row.id,
      'target_object_id', change_row.target_object_id,
      'target_label', tonde_private.pi_label(target_workspace, change_row.target_object_id),
      'revision', (result->>'revision')::integer, 'changed_fields', result->'changed_fields'));
    -- Propagate the consequence through the dependency-aware impact engine.
    analysis := tonde.impact_preview(target_workspace, target_production, change_row.target_object_id, 2, 200);
    propagation_result := tonde.apply_impact(target_workspace, target_production, (analysis->>'analysis_id')::uuid,
      propagation, '{}'::uuid[], null, 'Merged from branch ' || b.name);
    impact_summary := impact_summary || jsonb_build_array(jsonb_build_object(
      'object_id', change_row.target_object_id, 'analysis_id', analysis->>'analysis_id',
      'mode', propagation, 'counts', analysis->'counts', 'marked', propagation_result->'marked',
      'requiring_review', propagation_result->'requiring_review', 'locked_skipped', propagation_result->'locked_skipped',
      'unresolved_count', propagation_result->'unresolved_count'));
  end loop;
  update tonde.merge_proposals p set state = 'merged', decided_by = auth.uid(), decided_at = now(),
    decision_note = left(coalesce(note_text,''), 800), applied = applied_items,
    impact = jsonb_set(p.impact, '{propagation}', to_jsonb(impact_summary), true)
    where p.id = proposal.id;
  update tonde.object_branches br set state = 'merged', merged_at = now(), merged_by = auth.uid(),
    merged_proposal_id = proposal.id where br.id = b.id;
  return jsonb_build_object('proposal_id', proposal.id, 'branch_id', b.id, 'state', 'merged',
    'applied', applied_items, 'applied_count', applied_count, 'skipped', skipped, 'propagation', propagation,
    'impact', impact_summary,
    'note', case when applied_count = 0
        then 'Nothing was merged: no clean change was selected.'
      else 'New mainline revisions were created. Branch history is preserved.' end);
end $$;


-- 13. RLS. Every new table is workspace-isolated; enabling RLS is not optional.
do $$ declare item text; begin
  foreach item in array array['object_branches','branch_changes','merge_proposals'] loop
    execute format('alter table tonde.%I enable row level security', item);
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_read'
    ) then
      execute format('create policy tenant_read on tonde.%I for select to authenticated using (tonde_private.is_workspace_member(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_insert'
    ) then
      execute format('create policy tenant_insert on tonde.%I for insert to authenticated with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    if not exists (
      select 1 from pg_policies
      where schemaname = 'tonde' and tablename = item and policyname = 'tenant_update'
    ) then
      execute format('create policy tenant_update on tonde.%I for update to authenticated using (tonde_private.can_edit_workspace(workspace_id)) with check (tonde_private.can_edit_workspace(workspace_id))', item);
    end if;
    execute format('grant select on tonde.%I to authenticated', item);
  end loop;
end $$;


-- 14. Mutation guards: identity stays immutable, revisions auto-bump, no row is rewritten.
do $$ declare item text; begin
  foreach item in array array['object_branches','branch_changes','merge_proposals'] loop
    execute format('drop trigger if exists guard_mutation on tonde.%I', item);
execute format('create trigger guard_mutation before insert or update on tonde.%I for each row execute function tonde_private.guard_mutation()', item);
  end loop;
end $$;


-- 15. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.version_list(uuid,uuid,uuid,text,integer,integer),
  tonde.version_get(uuid,uuid,uuid),
  tonde.version_compare(uuid,uuid,uuid,uuid),
  tonde.version_restore(uuid,uuid,uuid,text),
  tonde.branch_create(uuid,uuid,uuid,jsonb),
  tonde.branch_list(uuid,uuid,text,integer,integer),
  tonde.branch_detail(uuid,uuid,uuid),
  tonde.branch_change_set(uuid,uuid,uuid,jsonb),
  tonde.branch_change_clear(uuid,uuid,uuid,uuid,text),
  tonde.branch_state_set(uuid,uuid,uuid,text,text),
  tonde.merge_preview(uuid,uuid,uuid),
  tonde.merge_decide(uuid,uuid,uuid,text,uuid[],text,text)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.version_list(uuid,uuid,uuid,text,integer,integer),
  tonde.version_get(uuid,uuid,uuid),
  tonde.version_compare(uuid,uuid,uuid,uuid),
  tonde.version_restore(uuid,uuid,uuid,text),
  tonde.branch_create(uuid,uuid,uuid,jsonb),
  tonde.branch_list(uuid,uuid,text,integer,integer),
  tonde.branch_detail(uuid,uuid,uuid),
  tonde.branch_change_set(uuid,uuid,uuid,jsonb),
  tonde.branch_change_clear(uuid,uuid,uuid,uuid,text),
  tonde.branch_state_set(uuid,uuid,uuid,text,text),
  tonde.merge_preview(uuid,uuid,uuid),
  tonde.merge_decide(uuid,uuid,uuid,text,uuid[],text,text)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050023_approval_lock_readiness.sql
-- ==========================================================================

-- Additive migration: Prompt 9E approval, locks and Production readiness.
-- Approval stays the canonical tonde.approval enum and lock stays the canonical locked_at
-- column: this migration does NOT introduce a second vocabulary. What it adds is the missing
-- record - WHO decided, WHEN, WHY, and WHICH revision the decision named - and the derived,
-- deterministic Production readiness surface. A decision row is append-only: history is never
-- rewritten, and readiness is a category derived from real state, never a vanity percentage.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.access_action as enum ('approve','request_review','reopen','lock','unlock')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.readiness_state as enum ('ready','ready_with_warnings','needs_review','blocked','unknown')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.readiness_dimension as enum
  ('decisions','story','script','scene_plan','shots','continuity','resources','real_execution',
   'ai_execution','approvals','dependencies','results','delivery')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. Access decisions. Append-only. Each row names the object, the action, the approval and lock
-- state before and after, and - for an approval - the exact revision it accepted, so approval can
-- never silently describe newer content. Actor and time are recorded, so unlock is explicit.
create table if not exists tonde.access_decisions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  object_id uuid not null,
  object_kind text not null check (length(object_kind) between 1 and 40),
  action tonde.access_action not null,
  from_approval tonde.approval,
  to_approval tonde.approval,
  from_locked boolean not null default false,
  to_locked boolean not null default false,
  pinned_revision integer check (pinned_revision is null or pinned_revision > 0),
  note text not null default '' check (length(note) <= 800),
  actor_user_id uuid,
  created_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, object_id) references tonde.objects(workspace_id, id) on delete restrict
);

create index if not exists access_decisions_by_object on tonde.access_decisions(workspace_id, object_id, created_at desc, id);

create index if not exists access_decisions_recent on tonde.access_decisions(workspace_id, production_id, created_at desc, id);


-- A decision is a record of something that happened. It is never edited or deleted.
create or replace function tonde_private.access_decisions_immutable() returns trigger
language plpgsql set search_path = '' as $$
begin
  raise exception 'Access decisions are an append-only record and cannot be changed' using errcode = '23514';
end $$;

drop trigger if exists access_decisions_immutable on tonde.access_decisions;
create trigger access_decisions_immutable before update or delete on tonde.access_decisions
  for each row execute function tonde_private.access_decisions_immutable();

revoke all on function tonde_private.access_decisions_immutable() from public, anon, authenticated, service_role;


-- 3. Private helpers (not user-facing; reachable only through the security-definer RPCs below).

-- The approval of a canonical object, read from the table that owns it.
create or replace function tonde_private.ax_approval(target_workspace uuid, target_object uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
declare kind_value text; value text;
begin
  select o.kind into kind_value from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  case kind_value
    when 'production' then select approval::text into value from tonde.productions where id = target_object;
    when 'act' then select approval::text into value from tonde.acts where id = target_object;
    when 'sequence' then select approval::text into value from tonde.sequences where id = target_object;
    when 'scene' then select approval::text into value from tonde.scenes where id = target_object;
    when 'shot' then select approval::text into value from tonde.shots where id = target_object;
    when 'execution_plan' then select approval::text into value from tonde.execution_plans where id = target_object;
    when 'dialogue_line' then select approval::text into value from tonde.dialogue_lines where id = target_object;
    when 'creative_document' then select approval::text into value from tonde.creative_documents where id = target_object;
    when 'result' then select approval::text into value from tonde.results where id = target_object;
    when 'asset' then select approval::text into value from tonde.assets where id = target_object;
    else value := null;
  end case;
  return value;
end $$;

revoke all on function tonde_private.ax_approval(uuid,uuid) from public, anon, authenticated, service_role;


-- When a canonical object's own lock column was set (the enclosing scope is resolved by pi_is_locked).
create or replace function tonde_private.ax_locked_at(target_workspace uuid, target_object uuid) returns timestamptz
language plpgsql stable security definer set search_path = '' as $$
declare kind_value text; value timestamptz;
begin
  select o.kind into kind_value from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  case kind_value
    when 'production' then select locked_at into value from tonde.productions where id = target_object;
    when 'act' then select locked_at into value from tonde.acts where id = target_object;
    when 'sequence' then select locked_at into value from tonde.sequences where id = target_object;
    when 'scene' then select locked_at into value from tonde.scenes where id = target_object;
    when 'shot' then select locked_at into value from tonde.shots where id = target_object;
    when 'execution_plan' then select locked_at into value from tonde.execution_plans where id = target_object;
    when 'dialogue_line' then select locked_at into value from tonde.dialogue_lines where id = target_object;
    when 'creative_document' then select locked_at into value from tonde.creative_documents where id = target_object;
    when 'result' then select locked_at into value from tonde.results where id = target_object;
    when 'asset' then select locked_at into value from tonde.assets where id = target_object;
    else value := null;
  end case;
  return value;
end $$;

revoke all on function tonde_private.ax_locked_at(uuid,uuid) from public, anon, authenticated, service_role;


-- Write an approval to the table that owns the object. Returns the resulting revision, or null
-- when the object row is missing.
create or replace function tonde_private.ax_set_approval(target_workspace uuid, target_production uuid,
  target_object uuid, approval_value tonde.approval) returns integer
language plpgsql security definer set search_path = '' as $$
declare kind_value text; new_rev integer;
begin
  select o.kind into kind_value from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  case kind_value
    when 'production' then update tonde.productions set approval = approval_value
      where workspace_id = target_workspace and id = target_object returning revision into new_rev;
    when 'act' then update tonde.acts set approval = approval_value
      where workspace_id = target_workspace and id = target_object returning revision into new_rev;
    when 'sequence' then update tonde.sequences set approval = approval_value
      where workspace_id = target_workspace and id = target_object returning revision into new_rev;
    when 'scene' then update tonde.scenes set approval = approval_value
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'shot' then update tonde.shots set approval = approval_value
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'execution_plan' then update tonde.execution_plans set approval = approval_value
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'dialogue_line' then update tonde.dialogue_lines set approval = approval_value
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'creative_document' then update tonde.creative_documents set approval = approval_value
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'result' then update tonde.results set approval = approval_value
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    else raise exception 'That object kind cannot be approved' using errcode = '22023';
  end case;
  return new_rev;
end $$;

revoke all on function tonde_private.ax_set_approval(uuid,uuid,uuid,tonde.approval) from public, anon, authenticated, service_role;


-- Write a lock to the table that owns the object. Returns the resulting revision, or null.
create or replace function tonde_private.ax_set_lock(target_workspace uuid, target_production uuid,
  target_object uuid, locked_value boolean) returns integer
language plpgsql security definer set search_path = '' as $$
declare kind_value text; new_rev integer; stamp timestamptz;
begin
  stamp := case when coalesce(locked_value,false) then now() else null end;
  select o.kind into kind_value from tonde.objects o where o.workspace_id = target_workspace and o.id = target_object;
  case kind_value
    when 'production' then update tonde.productions set locked_at = stamp
      where workspace_id = target_workspace and id = target_object returning revision into new_rev;
    when 'act' then update tonde.acts set locked_at = stamp
      where workspace_id = target_workspace and id = target_object returning revision into new_rev;
    when 'sequence' then update tonde.sequences set locked_at = stamp
      where workspace_id = target_workspace and id = target_object returning revision into new_rev;
    when 'scene' then update tonde.scenes set locked_at = stamp
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'shot' then update tonde.shots set locked_at = stamp
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'execution_plan' then update tonde.execution_plans set locked_at = stamp
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'dialogue_line' then update tonde.dialogue_lines set locked_at = stamp
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'creative_document' then update tonde.creative_documents set locked_at = stamp
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    when 'result' then update tonde.results set locked_at = stamp
      where workspace_id = target_workspace and production_id = target_production and id = target_object returning revision into new_rev;
    else raise exception 'That object kind cannot be locked' using errcode = '22023';
  end case;
  return new_rev;
end $$;

revoke all on function tonde_private.ax_set_lock(uuid,uuid,uuid,boolean) from public, anon, authenticated, service_role;


-- One readiness blocker, with the real scope it points at so the surface can navigate to it.
create or replace function tonde_private.rd_blocker(code_value text, severity_value text, dimension_value text,
  problem_value text, object_id uuid, label_value text, kind_value text,
  why_value text, action_value text, source_value text) returns jsonb
language sql immutable set search_path = '' as $$
  select jsonb_build_object('code', code_value, 'severity', severity_value, 'dimension', dimension_value,
    'problem', problem_value, 'affected_object_id', object_id, 'affected_label', label_value,
    'affected_kind', kind_value, 'why_it_matters', why_value, 'required_action', action_value,
    'action_source', source_value);
$$;

revoke all on function tonde_private.rd_blocker(text,text,text,text,uuid,text,text,text,text,text)
  from public, anon, authenticated, service_role;


-- 4. Approval decision. The creator accepts a specific revision, requests review, or reopens.
-- An AI or service-role operation cannot manufacture this: guard_human_acceptance rejects it in
-- the database, and this RPC requires an authenticated workspace editor.
create or replace function tonde.approval_decide(target_workspace uuid, target_production uuid, target_object uuid,
  decision text, expected_revision integer default null, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare object_row tonde.objects; current_rev integer; from_approval text; from_locked boolean;
  desired tonde.approval; new_rev integer; approval_after text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  object_row := tonde_private.vb_object(target_workspace, target_production, target_object);
  if decision not in ('approve','request_review','reopen') then
    raise exception 'A review decision is approve, request_review or reopen' using errcode = '22023';
  end if;
  current_rev := tonde_private.pi_object_revision(target_workspace, target_object);
  if current_rev is null then raise exception 'That object cannot be reviewed' using errcode = '22023'; end if;
  -- Stale operations are rejected: an approval never lands on content the creator did not see.
  if expected_revision is not null and current_rev <> expected_revision then
    raise exception 'That object changed since you loaded it. Review the current revision.' using errcode = '40001';
  end if;
  from_approval := tonde_private.ax_approval(target_workspace, target_object);
  from_locked := tonde_private.pi_is_locked(target_workspace, target_object);
  desired := case decision when 'approve' then 'approved'::tonde.approval
    when 'request_review' then 'needs_review'::tonde.approval else 'draft'::tonde.approval end;
  new_rev := tonde_private.ax_set_approval(target_workspace, target_production, target_object, desired);
  if new_rev is null then raise exception 'That object is unavailable in this Production' using errcode = 'P0002'; end if;
  approval_after := tonde_private.ax_approval(target_workspace, target_object);
  insert into tonde.access_decisions(workspace_id, production_id, object_id, object_kind, action,
    from_approval, to_approval, from_locked, to_locked, pinned_revision, note, actor_user_id)
  values (target_workspace, target_production, target_object, object_row.kind, decision::tonde.access_action,
    from_approval::tonde.approval, approval_after::tonde.approval, coalesce(from_locked,false), coalesce(from_locked,false),
    case when decision = 'approve' then new_rev else null end, left(coalesce(note_text,''), 800), auth.uid());
  return jsonb_build_object('object_id', target_object, 'object_kind', object_row.kind,
    'label', tonde_private.pi_label(target_workspace, target_object),
    'action', decision, 'approval', approval_after, 'revision', new_rev,
    'approved_revision', case when decision = 'approve' then new_rev else null end,
    'locked', coalesce(from_locked,false), 'note', left(coalesce(note_text,''), 800),
    'actor_user_id', auth.uid(), 'decided_at', now(),
    'meaning', case when decision = 'approve'
        then 'A creator accepted this exact revision. Approval is a human decision, not a generation result.'
      when decision = 'request_review' then 'This revision is waiting for a creator review.'
      else 'This revision is back to draft.' end);
end $$;


-- 5. Lock decision. Locking protects a decision from incidental change; unlocking is explicit and
-- records actor, time and reason. Lock and approval stay independent.
create or replace function tonde.lock_set(target_workspace uuid, target_production uuid, target_object uuid,
  locked boolean, expected_revision integer default null, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare object_row tonde.objects; current_rev integer; was_locked boolean; new_rev integer; is_locked boolean;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  object_row := tonde_private.vb_object(target_workspace, target_production, target_object);
  current_rev := tonde_private.pi_object_revision(target_workspace, target_object);
  if current_rev is null then raise exception 'That object cannot be locked' using errcode = '22023'; end if;
  if expected_revision is not null and current_rev <> expected_revision then
    raise exception 'That object changed since you loaded it' using errcode = '40001';
  end if;
  was_locked := coalesce(tonde_private.pi_is_locked(target_workspace, target_object), false);
  if coalesce(locked,false) = was_locked then
    raise exception 'That object is already %', case when was_locked then 'locked' else 'unlocked' end using errcode = '23514';
  end if;
  new_rev := tonde_private.ax_set_lock(target_workspace, target_production, target_object, coalesce(locked,false));
  if new_rev is null then raise exception 'That object is unavailable in this Production' using errcode = 'P0002'; end if;
  is_locked := coalesce(tonde_private.pi_is_locked(target_workspace, target_object), false);
  insert into tonde.access_decisions(workspace_id, production_id, object_id, object_kind, action,
    from_approval, to_approval, from_locked, to_locked, pinned_revision, note, actor_user_id)
  values (target_workspace, target_production, target_object, object_row.kind,
    case when coalesce(locked,false) then 'lock' else 'unlock' end::tonde.access_action,
    tonde_private.ax_approval(target_workspace, target_object)::tonde.approval,
    tonde_private.ax_approval(target_workspace, target_object)::tonde.approval,
    was_locked, is_locked, current_rev, left(coalesce(note_text,''), 800), auth.uid());
  return jsonb_build_object('object_id', target_object, 'object_kind', object_row.kind,
    'label', tonde_private.pi_label(target_workspace, target_object),
    'task', case when coalesce(locked,false) then 'lock' else 'unlock' end,
    'locked', is_locked, 'revision', new_rev, 'was_locked', was_locked,
    'note', left(coalesce(note_text,''), 800), 'actor_user_id', auth.uid(), 'decided_at', now(),
    'meaning', case when is_locked
        then 'This object is protected from incidental change. Approval is unaffected.'
        else 'This object is unlocked. The unlock and its reason are on record.' end);
end $$;


-- 6. Approval and lock state of one object: the current approval, the revision it named, whether
-- content moved since, the reviewer and time, and whether it is locked and why.
create or replace function tonde.access_state(target_workspace uuid, target_production uuid, target_object uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare object_row tonde.objects; approval_text text; locked_value boolean; current_rev integer;
  approved_rev integer; approved_by uuid; approved_at timestamptz; locked_by uuid; lock_note text;
  lock_stamp timestamptz; decisions jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  object_row := tonde_private.vb_object(target_workspace, target_production, target_object);
  approval_text := tonde_private.ax_approval(target_workspace, target_object);
  locked_value := coalesce(tonde_private.pi_is_locked(target_workspace, target_object), false);
  current_rev := tonde_private.pi_object_revision(target_workspace, target_object);
  select d.pinned_revision, d.actor_user_id, d.created_at into approved_rev, approved_by, approved_at
    from tonde.access_decisions d where d.workspace_id = target_workspace and d.object_id = target_object
      and d.action = 'approve' order by d.created_at desc, d.id desc limit 1;
  select d.actor_user_id, d.created_at, d.note into locked_by, lock_stamp, lock_note
    from tonde.access_decisions d where d.workspace_id = target_workspace and d.object_id = target_object
      and d.action = 'lock' order by d.created_at desc, d.id desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('action', d.action, 'from_approval', d.from_approval,
      'to_approval', d.to_approval, 'from_locked', d.from_locked, 'to_locked', d.to_locked,
      'pinned_revision', d.pinned_revision, 'note', d.note, 'actor_user_id', d.actor_user_id,
      'created_at', d.created_at) order by d.created_at desc, d.id desc), '[]'::jsonb) into decisions
    from (select * from tonde.access_decisions d where d.workspace_id = target_workspace
      and d.object_id = target_object order by d.created_at desc, d.id desc limit 20) d;
  return jsonb_build_object(
    'object_id', target_object, 'object_kind', object_row.kind,
    'label', tonde_private.pi_label(target_workspace, target_object),
    'approval', approval_text, 'locked', locked_value, 'current_revision', current_rev,
    'approved_revision', approved_rev, 'approved_by', approved_by, 'approved_at', approved_at,
    'changed_since_approval', approval_text = 'changed_after_approval',
    'locked_at', case when locked_value then coalesce(tonde_private.ax_locked_at(target_workspace, target_object), lock_stamp) else null end,
    'locked_by', case when locked_value then locked_by else null end,
    'lock_reason', case when locked_value then coalesce(lock_note, '') else '' end,
    'decisions', decisions,
    'note', 'Approval names the exact revision it accepted. Newer content is reported as changed after approval, never as still approved. Lock and approval are independent.');
end $$;


-- 7. The recorded decision history of one object.
create or replace function tonde.access_history(target_workspace uuid, target_production uuid, target_object uuid,
  max_rows integer default 50, skip_rows integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare object_row tonde.objects; total integer; items jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  object_row := tonde_private.vb_object(target_workspace, target_production, target_object);
  select count(*) into total from tonde.access_decisions d
    where d.workspace_id = target_workspace and d.object_id = target_object;
  select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'action', d.action, 'from_approval', d.from_approval,
      'to_approval', d.to_approval, 'from_locked', d.from_locked, 'to_locked', d.to_locked,
      'pinned_revision', d.pinned_revision, 'note', d.note, 'actor_user_id', d.actor_user_id,
      'created_at', d.created_at) order by d.created_at desc, d.id desc), '[]'::jsonb) into items
    from (select * from tonde.access_decisions d where d.workspace_id = target_workspace
      and d.object_id = target_object order by d.created_at desc, d.id desc
      limit greatest(1, least(coalesce(max_rows,50), 200)) offset greatest(0, coalesce(skip_rows,0))) d;
  return jsonb_build_object('object_id', target_object, 'object_kind', object_row.kind,
    'total', total, 'items', items,
    'note', 'This is a record of creator decisions. It is append-only.');
end $$;


-- 8. Production readiness. A category derived from real criteria, with actionable dimensions and
-- drill-down blockers - never an arbitrary score. Provider availability is external and is not
-- guessed here; nothing unavailable is fabricated.
create or replace function tonde.production_readiness(target_workspace uuid, target_production uuid,
  expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare current tonde.productions; blockers jsonb := '[]'::jsonb; dims jsonb := '[]'::jsonb;
  blocking_count integer := 0; review_count integer := 0; warning_count integer := 0;
  state_value tonde.readiness_state; dim_state tonde.readiness_state;
  db integer; dr integer; dw integer; present boolean; dim_name text;
  has_story boolean; has_script boolean; has_scenes boolean; has_shots boolean; has_continuity boolean;
  has_resources boolean; has_real boolean; has_ai boolean; has_decisions boolean; has_dependencies boolean;
  has_results boolean; has_delivery boolean; rec record; headline text;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select * into current from tonde.productions where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and current.revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  if current.lifecycle <> 'active' then
    return jsonb_build_object('production_id', target_production, 'production_revision', current.revision,
      'title', current.title, 'state', 'unknown', 'dimensions', '[]'::jsonb, 'blockers', '[]'::jsonb,
      'counts', jsonb_build_object('blocking', 0, 'review', 0, 'warning', 0, 'total', 0),
      'headline', 'This Production is archived, so readiness is not evaluated.',
      'notes', jsonb_build_array('Archived Productions are not scored or judged.'),
      'generated_at', now());
  end if;

  has_story := exists (select 1 from tonde.creative_documents d where d.workspace_id = target_workspace
    and d.production_id = target_production and d.document_type in ('story','treatment') and length(btrim(d.content)) > 0);
  has_script := exists (select 1 from tonde.creative_documents d where d.workspace_id = target_workspace
    and d.production_id = target_production and d.document_type = 'script' and length(btrim(d.content)) > 0);
  has_scenes := exists (select 1 from tonde.scenes s where s.workspace_id = target_workspace and s.production_id = target_production and s.lifecycle = 'active');
  has_shots := exists (select 1 from tonde.shots h where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active');
  has_continuity := exists (select 1 from tonde.continuity_findings f where f.workspace_id = target_workspace and f.production_id = target_production);
  has_resources := exists (select 1 from tonde.real_plan_requirements r where r.workspace_id = target_workspace and r.production_id = target_production);
  has_real := exists (select 1 from tonde.execution_plans p where p.workspace_id = target_workspace and p.production_id = target_production and p.execution_method = 'real');
  has_ai := exists (select 1 from tonde.execution_plans p where p.workspace_id = target_workspace and p.production_id = target_production and p.execution_method = 'ai');
  has_decisions := exists (select 1 from tonde.director_decisions d where d.workspace_id = target_workspace and d.production_id = target_production);
  has_dependencies := exists (select 1 from tonde.stale_artifacts a where a.workspace_id = target_workspace and a.production_id = target_production and a.state <> 'current');
  has_results := exists (select 1 from tonde.results r where r.workspace_id = target_workspace and r.production_id = target_production);
  has_delivery := exists (select 1 from tonde.exports e where e.workspace_id = target_workspace and e.production_id = target_production);

  -- Unresolved blocking decisions the Director defaulted on and no creator has answered.
  for rec in select d.id, d.decision_id, d.question from tonde.director_decisions d
    where d.workspace_id = target_workspace and d.production_id = target_production
      and d.priority = 'blocking' and d.decided_by = 'tonde' order by d.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('unresolved_decision','blocking','decisions',
      'An open blocking decision has no creator answer', current.id, current.title, 'production',
      'A blocking intake decision is still on a TONDE default instead of a creator answer.',
      'Answer it, or record the decision, in Director intake.', 'director_decision');
  end loop;

  -- Story and script.
  if not has_story then
    blockers := blockers || tonde_private.rd_blocker('missing_story','review','story',
      'No story or treatment has been written yet', current.id, current.title, 'production',
      'There is no narrative foundation to plan scenes and shots against.',
      'Write a story or treatment, or record why none is needed.', 'creative_document');
  end if;
  if not has_script and has_scenes then
    blockers := blockers || tonde_private.rd_blocker('missing_script','warning','script',
      'No script exists for a production that already has scenes', current.id, current.title, 'production',
      'Dialogue and action cannot be checked against a script.',
      'Write a script, or accept that this production is planned without one.', 'creative_document');
  end if;

  -- Scene plan.
  if not has_scenes then
    blockers := blockers || tonde_private.rd_blocker('no_scenes','blocking','scene_plan',
      'No scenes have been planned', current.id, current.title, 'production',
      'Shots, timing and execution all depend on a scene plan.',
      'Plan the first Scene in Studio.', 'scene');
  end if;
  for rec in select s.id, s.title from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.lifecycle = 'active'
    and not exists (select 1 from tonde.shots h where h.workspace_id = s.workspace_id and h.scene_id = s.id and h.lifecycle = 'active')
    order by s.sort_order, s.title limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('scene_without_shots','warning','scene_plan',
      'A Scene has no Shots yet', rec.id, rec.title, 'scene',
      'A Scene with no Shots has no executable coverage.',
      'Add the Shots for this Scene.', 'scene');
  end loop;

  -- Shots.
  for rec in select h.id, h.title from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.lifecycle = 'active'
    and coalesce(h.planned_duration_ms, 0) = 0 order by h.sort_order limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('shot_without_duration','warning','shots',
      'A Shot has no planned duration', rec.id, rec.title, 'shot',
      'The Scene and Production runtime cannot be reconciled without it.',
      'Set the Shot duration.', 'shot');
  end loop;
  for rec in select h.id, h.title from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.lifecycle = 'active'
    and not exists (select 1 from tonde.execution_plans p where p.workspace_id = h.workspace_id and p.shot_id = h.id)
    order by h.sort_order limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('shot_unplanned','warning','shots',
      'A Shot has no execution plan', rec.id, rec.title, 'shot',
      'Without a Real or AI plan there is no way to execute this Shot.',
      'Choose Real or AI for this Shot and plan it.', 'shot');
  end loop;
  -- A Scene participant that names an archived Asset.
  for rec in select distinct h.id, h.title, a.name as asset_name from tonde.scene_participants sp
    join tonde.scenes s on s.workspace_id = sp.workspace_id and s.id = sp.scene_id
    join tonde.shots h on h.workspace_id = sp.workspace_id and h.scene_id = sp.scene_id and h.lifecycle = 'active'
    join tonde.assets a on a.workspace_id = sp.workspace_id and a.id = sp.asset_id
    where sp.workspace_id = target_workspace and sp.production_id = target_production and a.lifecycle <> 'active'
    limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('missing_asset','warning','scene_plan',
      'A Scene participant Asset is archived: ' || rec.asset_name, rec.id, rec.title, 'shot',
      'A Shot in this Scene expects an Asset that is no longer active.',
      'Restore the Asset or remove it from the Scene.', 'asset');
  end loop;

  -- Continuity.
  for rec in select f.id, f.explanation, f.severity from tonde.continuity_findings f
    where f.workspace_id = target_workspace and f.production_id = target_production and f.state = 'open'
      and f.severity = 'critical' order by f.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('continuity_critical','blocking','continuity',
      rec.explanation, rec.id, 'Continuity finding', 'continuity_finding',
      'A critical continuity conflict is unresolved.',
      'Resolve or explicitly accept the continuity finding.', 'continuity_finding');
  end loop;
  for rec in select f.id, f.explanation from tonde.continuity_findings f
    where f.workspace_id = target_workspace and f.production_id = target_production and f.state = 'open'
      and f.severity = 'warning' order by f.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('continuity_warning','review','continuity',
      rec.explanation, rec.id, 'Continuity finding', 'continuity_finding',
      'A continuity warning is unresolved.',
      'Review the finding and decide.', 'continuity_finding');
  end loop;

  -- References and media availability.
  for rec in select r.id, r.source_description, r.state from tonde.production_references r
    where r.workspace_id = target_workspace and r.production_id = target_production
      and r.state in ('inaccessible','failed') order by r.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('reference_unavailable','review','resources',
      'A Production Reference could not be read', rec.id, coalesce(nullif(rec.source_description, ''), 'Reference'),
      'reference', 'A reference that cannot be read cannot inform the production.',
      'Re-import or replace the reference.', 'reference');
  end loop;
  for rec in select r.id, r.source_description from tonde.production_references r
    where r.workspace_id = target_workspace and r.production_id = target_production
      and r.state = 'received' order by r.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('reference_media_unavailable','warning','resources',
      'A Production Reference has no available media yet', rec.id,
      coalesce(nullif(rec.source_description, ''), 'Reference'), 'reference',
      'Media that is not available cannot be analysed here.',
      'Upload the media, or record the reference as description-only.', 'reference');
  end loop;

  -- Resources and Real execution.
  for rec in select r.id, r.label, r.shot_id from tonde.real_plan_requirements r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.status = 'missing'
    order by r.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('missing_resource','blocking','resources',
      'A required resource is missing: ' || rec.label, rec.shot_id,
      tonde_private.pi_label(target_workspace, rec.shot_id), 'shot',
      'A Real Shot cannot be executed without its required resource.',
      'Assign a resource, a substitute, or switch the Shot to AI.', 'real_plan_requirement');
  end loop;
  for rec in select r.id, r.label, r.shot_id from tonde.real_plan_requirements r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.status = 'unverified'
    order by r.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('unverified_resource','review','resources',
      'A required resource is unverified: ' || rec.label, rec.shot_id,
      tonde_private.pi_label(target_workspace, rec.shot_id), 'shot',
      'An unverified resource may or may not be available on the day.',
      'Confirm the resource or its substitute.', 'real_plan_requirement');
  end loop;
  for rec in select h.id, h.title from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.lifecycle = 'active' and h.execution_method = 'real'
    and not exists (select 1 from tonde.execution_plans p where p.workspace_id = h.workspace_id
      and p.shot_id = h.id and p.execution_method = 'real')
    order by h.sort_order limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('real_shot_unplanned','review','real_execution',
      'A Real Shot has no Real plan', rec.id, rec.title, 'shot',
      'The Shot is marked Real but has no plan to shoot it.',
      'Plan the Real execution, or switch the Shot.', 'shot');
  end loop;
  for rec in select p.id, p.shot_id from tonde.execution_plans p where p.workspace_id = target_workspace
    and p.production_id = target_production and p.execution_method = 'real'
    and cardinality(p.safety_flags) > 0 order by p.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('safety_blocked','blocking','real_execution',
      'A Real plan carries an unresolved safety flag', rec.shot_id,
      tonde_private.pi_label(target_workspace, rec.shot_id), 'shot',
      'A safety flag must be resolved before this Shot is executed.',
      'Resolve the safety flag or replace the setup.', 'execution_plan');
  end loop;

  -- AI execution. Provider availability is external and is never guessed here: this reports only
  -- local, real state - an AI plan that is not yet approved.
  select count(*) into dw from tonde.execution_plans p where p.workspace_id = target_workspace
    and p.production_id = target_production and p.execution_method = 'ai'
    and p.approval in ('draft','needs_review');
  if dw > 0 then
    blockers := blockers || tonde_private.rd_blocker('ai_plan_unapproved','warning','ai_execution',
      dw || ' AI plan' || case when dw = 1 then ' is' else 's are' end || ' not approved yet', current.id,
      current.title, 'production', 'AI generation should not start from an unapproved plan.',
      'Approve the AI plan before generating.', 'execution_plan');
  end if;

  -- Approvals. Content that moved after approval needs a fresh review. Nothing is called
  -- "critical" without a real signal.
  for rec in select o.id, o.kind from tonde.objects o where o.workspace_id = target_workspace
    and o.production_id = target_production
    and tonde_private.ax_approval(target_workspace, o.id) = 'changed_after_approval'
    order by o.kind, o.id limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('changed_after_approval','review','approvals',
      'Approved content changed since it was approved', rec.id,
      tonde_private.pi_label(target_workspace, rec.id), rec.kind,
      'An approval describes a specific revision; it does not silently cover newer content.',
      'Review the new revision and approve it, or restore the approved revision.', rec.kind);
  end loop;
  select count(*) into dw from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.lifecycle = 'active' and h.approval <> 'approved'
    and exists (select 1 from tonde.execution_plans p where p.workspace_id = h.workspace_id and p.shot_id = h.id);
  if dw > 0 then
    blockers := blockers || tonde_private.rd_blocker('planned_shots_unapproved','warning','approvals',
      dw || ' planned Shot' || case when dw = 1 then ' is' else 's are' end || ' not approved', current.id,
      current.title, 'production', 'Planned Shots that are not approved are not cleared to execute.',
      'Review and approve the planned Shots.', 'shot');
  end if;

  -- Dependencies: stale artifacts and locked objects that need review.
  for rec in select a.id, a.object_id, a.reason from tonde.stale_artifacts a
    where a.workspace_id = target_workspace and a.production_id = target_production and a.state = 'conflicted'
    order by a.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('stale_conflicted','review','dependencies',
      rec.reason, rec.object_id, tonde_private.pi_label(target_workspace, rec.object_id), 'stale_artifact',
      'Approved content depends on a changed source and needs review.',
      'Review the dependent work against the new source.', 'stale_artifact');
  end loop;
  for rec in select a.id, a.object_id, a.reason from tonde.stale_artifacts a
    where a.workspace_id = target_workspace and a.production_id = target_production and a.state = 'stale'
    order by a.created_at limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('stale_artifact','warning','dependencies',
      rec.reason, rec.object_id, tonde_private.pi_label(target_workspace, rec.object_id), 'stale_artifact',
      'Derived work no longer matches the source it came from.',
      'Refresh or re-derive the affected work.', 'stale_artifact');
  end loop;
  for rec in select distinct a.object_id from tonde.stale_artifacts a
    where a.workspace_id = target_workspace and a.production_id = target_production and a.state <> 'current'
      and tonde_private.pi_is_locked(target_workspace, a.object_id)
    limit 25 loop
    blockers := blockers || tonde_private.rd_blocker('locked_needs_review','review','dependencies',
      'A locked object needs review', rec.object_id, tonde_private.pi_label(target_workspace, rec.object_id),
      'locked', 'Locked content was left untouched and needs an explicit unlock before it can change.',
      'Unlock it deliberately, or resolve the review without changing it.', 'locked');
  end loop;

  -- Results, when any exist.
  select count(*) filter (where r.state in ('raw','needs_review')), count(*) filter (where r.state = 'rejected')
    into dr, dw from tonde.results r where r.workspace_id = target_workspace and r.production_id = target_production;
  if dr > 0 then
    blockers := blockers || tonde_private.rd_blocker('result_needs_review','warning','results',
      dr || ' Result' || case when dr = 1 then ' needs' else 's need' end || ' review', current.id,
      current.title, 'production', 'A Result that is still raw or needs review is not final.',
      'Review the Result and accept or reject it.', 'result');
  end if;
  if dw > 0 then
    blockers := blockers || tonde_private.rd_blocker('result_rejected','warning','results',
      dw || ' Result' || case when dw = 1 then ' was' else 's were' end || ' rejected', current.id,
      current.title, 'production', 'A rejected Result means the Shot still needs a usable take.',
      'Re-plan or re-shoot the affected Shot.', 'result');
  end if;
  -- Shot Match pickup: only reported when a completed report actually requires it.
  select count(*) into dr from tonde.shot_match_reports m where m.workspace_id = target_workspace
    and m.production_id = target_production and m.state = 'complete'
    and m.severity in ('warning','critical') and m.approval in ('draft','needs_review');
  if dr > 0 then
    blockers := blockers || tonde_private.rd_blocker('shot_match_pickup','review','results',
      dr || ' completed Shot Match report' || case when dr = 1 then ' needs' else 's need' end || ' a decision',
      current.id, current.title, 'production', 'A shot match finding has not been picked up or dismissed.',
      'Open FIX THIS SHOT and accept or dismiss the recommendation.', 'shot_match_report');
  end if;

  -- Delivery, when any export exists.
  select count(*) into dw from tonde.exports e where e.workspace_id = target_workspace
    and e.production_id = target_production and e.completed_at is null;
  if dw > 0 then
    blockers := blockers || tonde_private.rd_blocker('export_incomplete','warning','delivery',
      dw || ' export' || case when dw = 1 then ' is' else 's are' end || ' not finished', current.id,
      current.title, 'production', 'An unfinished export is not a delivered package.',
      'Finish or re-run the export.', 'export');
  end if;

  -- Aggregate the category. Readiness is the worst category present; it is never a percentage.
  select count(*) filter (where b->>'severity' = 'blocking'), count(*) filter (where b->>'severity' = 'review'),
    count(*) filter (where b->>'severity' = 'warning')
    into blocking_count, review_count, warning_count from jsonb_array_elements(blockers) b;
  state_value := case when blocking_count > 0 then 'blocked'::tonde.readiness_state
    when review_count > 0 then 'needs_review'::tonde.readiness_state
    when warning_count > 0 then 'ready_with_warnings'::tonde.readiness_state
    else 'ready'::tonde.readiness_state end;

  for dim_name in select unnest(array['decisions','story','script','scene_plan','shots','continuity',
      'resources','real_execution','ai_execution','approvals','dependencies','results','delivery']) loop
    select count(*) filter (where b->>'severity' = 'blocking'), count(*) filter (where b->>'severity' = 'review'),
      count(*) filter (where b->>'severity' = 'warning')
      into db, dr, dw from jsonb_array_elements(blockers) b where b->>'dimension' = dim_name;
    present := case dim_name
      when 'decisions' then has_decisions when 'story' then has_story when 'script' then has_script
      when 'scene_plan' then has_scenes when 'shots' then has_shots when 'continuity' then has_continuity
      when 'resources' then has_resources when 'real_execution' then has_real when 'ai_execution' then has_ai
      when 'approvals' then (has_scenes or has_shots) when 'dependencies' then has_dependencies
      when 'results' then has_results when 'delivery' then has_delivery else false end;
    if present or (db + dr + dw) > 0 then
      dim_state := case when db > 0 then 'blocked'::tonde.readiness_state
        when dr > 0 then 'needs_review'::tonde.readiness_state
        when dw > 0 then 'ready_with_warnings'::tonde.readiness_state
        else 'ready'::tonde.readiness_state end;
      dims := dims || jsonb_build_array(jsonb_build_object('dimension', dim_name, 'state', dim_state,
        'present', present, 'counts', jsonb_build_object('blocking', db, 'review', dr, 'warning', dw)));
    end if;
  end loop;

  headline := case state_value
    when 'blocked' then blocking_count || ' blocker' || case when blocking_count = 1 then '' else 's' end
      || ' must be resolved before this Production can move forward.'
    when 'needs_review' then review_count || ' item' || case when review_count = 1 then '' else 's' end
      || ' need review before this Production can move forward.'
    when 'ready_with_warnings' then warning_count || ' warning' || case when warning_count = 1 then '' else 's' end
      || ' to consider. Nothing blocks moving forward.'
    when 'ready' then 'No blockers or warnings were found for this Production.'
    else 'There is not enough planned state to judge readiness yet.' end;

  return jsonb_build_object('production_id', target_production, 'production_revision', current.revision,
    'title', current.title, 'state', state_value, 'dimensions', dims, 'blockers', blockers,
    'counts', jsonb_build_object('blocking', blocking_count, 'review', review_count,
      'warning', warning_count, 'total', blocking_count + review_count + warning_count),
    'headline', headline,
    'notes', jsonb_build_array(
      'Readiness is a category derived from real production state, not a score or a percentage.',
      'AI provider availability is an external dependency and is not guessed here.',
      'Shot Match pickup is only reported when a completed report actually requires a decision.'),
    'generated_at', now());
end $$;


-- 9. RLS. The decision record is workspace-isolated and read-only to members; only the guarded
-- security-definer RPCs above write it, so a decision can never be altered after the fact.
alter table tonde.access_decisions enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'access_decisions'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.access_decisions for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.access_decisions to authenticated;


-- 10. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.approval_decide(uuid,uuid,uuid,text,integer,text),
  tonde.lock_set(uuid,uuid,uuid,boolean,integer,text),
  tonde.access_state(uuid,uuid,uuid),
  tonde.access_history(uuid,uuid,uuid,integer,integer),
  tonde.production_readiness(uuid,uuid,integer)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.approval_decide(uuid,uuid,uuid,text,integer,text),
  tonde.lock_set(uuid,uuid,uuid,boolean,integer,text),
  tonde.access_state(uuid,uuid,uuid),
  tonde.access_history(uuid,uuid,uuid,integer,integer),
  tonde.production_readiness(uuid,uuid,integer)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050024_results_shot_match.sql
-- ==========================================================================

-- Additive migration: Prompt 9F Results, Shot Match and FIX THIS SHOT.
-- A Result is what was actually created, not the plan. Shot Match diagnoses what is different and
-- how to fix it; it is NOT a vanity similarity score and it does NOT approve anything. Media
-- capability is verified in the database from real media rows before any analysis is recorded, so a
-- visual comparison cannot be claimed when frames are unavailable. FIX THIS SHOT is a scoped
-- correction with a previewed impact, never a whole-Production regeneration, and the previous
-- Result, plan, Take, Attempt and findings are all preserved.
begin;


-- 1. Vocabulary. Storage codes are the generated product vocabulary keys.
do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.match_verdict as enum
  ('matches_intent','acceptable_variation','needs_attention','mismatch','unknown')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.correction_state as enum ('proposed','applied','rejected')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.correction_recommendation as enum
  ('none','pickup_required','regeneration_recommended','both')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;

do $tonde_idem$
begin
  execute $tonde_idem_ddl$create type tonde.match_origin as enum ('deterministic','creator','ai_proposal')$tonde_idem_ddl$;
exception when duplicate_object then null;
end
$tonde_idem$;


-- 2. The Shot Match report already exists as a review artifact. It gains the record it was missing:
-- the verified modalities, the per-dimension verdicts, the summary, who produced the analysis, the
-- recommendation, and the creator's decision. It stays read-only to clients: only the guarded
-- security-definer RPCs below write it.
alter table tonde.shot_match_reports add column if not exists capabilities jsonb not null default '{}'::jsonb
  check (jsonb_typeof(capabilities) = 'object');

alter table tonde.shot_match_reports add column if not exists dimensions jsonb not null default '[]'::jsonb
  check (jsonb_typeof(dimensions) = 'array');

alter table tonde.shot_match_reports add column if not exists summary jsonb not null default '{}'::jsonb
  check (jsonb_typeof(summary) = 'object');

alter table tonde.shot_match_reports add column if not exists limitations text[] not null default '{}';

alter table tonde.shot_match_reports add column if not exists origin tonde.match_origin not null default 'deterministic';

alter table tonde.shot_match_reports add column if not exists recommendation tonde.correction_recommendation not null default 'none';

alter table tonde.shot_match_reports add column if not exists decision text
  check (decision is null or decision in ('pickup','regeneration','accepted','dismiss'));

alter table tonde.shot_match_reports add column if not exists decision_note text not null default ''
  check (length(decision_note) <= 800);

alter table tonde.shot_match_reports add column if not exists decided_by uuid;

alter table tonde.shot_match_reports add column if not exists decided_at timestamptz;

-- The report was the one history table without a workspace-scoped identity key, so nothing could
-- reference it. Adding it is additive and lets a correction point at the analysis it came from.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.shot_match_reports') and conname = 'shot_match_reports_workspace_identity'
  ) then
    execute $tonde_idem_ddl$alter table tonde.shot_match_reports add constraint shot_match_reports_workspace_identity unique (workspace_id, id)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

create index if not exists shot_match_reports_recent on tonde.shot_match_reports(workspace_id, production_id, shot_id, created_at desc, id);


-- 3. Corrections. A scoped fix for one Shot: a field patch on one real object, with the root cause,
-- the reason and the affected scope recorded so the correction is readable years later.
create table if not exists tonde.match_corrections (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  report_id uuid not null, shot_id uuid not null, result_id uuid,
  target_object_id uuid not null, target_kind text not null check (length(target_kind) between 1 and 40),
  target_label text not null default '' check (length(target_label) <= 160),
  source_revision integer not null check (source_revision > 0),
  patch jsonb not null check (jsonb_typeof(patch) = 'object' and patch <> '{}'::jsonb),
  root_cause text not null default '' check (length(root_cause) <= 800),
  why text not null default '' check (length(why) <= 800),
  affected text not null default '' check (length(affected) <= 400),
  recommendation tonde.correction_recommendation not null default 'none',
  continuity_finding_id uuid,
  state tonde.correction_state not null default 'proposed',
  preview jsonb not null default '{}'::jsonb check (jsonb_typeof(preview) = 'object'),
  applied_revision integer check (applied_revision is null or applied_revision > 0),
  applied_version_id uuid,
  propagation jsonb not null default '[]'::jsonb check (jsonb_typeof(propagation) = 'array'),
  decided_by uuid, decided_at timestamptz,
  note text not null default '' check (length(note) <= 800),
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, shot_id) references tonde.shots(workspace_id, id) on delete restrict,
  foreign key (workspace_id, report_id) references tonde.shot_match_reports(workspace_id, id) on delete restrict,
  foreign key (workspace_id, target_object_id) references tonde.objects(workspace_id, id) on delete restrict,
  foreign key (workspace_id, continuity_finding_id) references tonde.continuity_findings(workspace_id, id) on delete restrict
);

create index if not exists match_corrections_by_report on tonde.match_corrections(workspace_id, report_id, state);

create index if not exists match_corrections_by_shot on tonde.match_corrections(workspace_id, production_id, shot_id, created_at desc, id);


-- 4. Private helpers (not user-facing; reachable only through the security-definer RPCs below).

-- The writable field map is EXTENDED, never replaced: branching and versioning keep their existing
-- fields, and an execution plan gains the fields a scoped correction legitimately targets (prompt,
-- First Frame, last frame, motion, performance, blocking). Identity, ordering, approval and locks
-- stay out of every map.
create or replace function tonde_private.vb_fields(kind_value text) returns jsonb
language sql immutable set search_path = '' as $$
  select case kind_value
    when 'creative_document' then jsonb_build_object('table','creative_documents','scope','production',
      'fields', jsonb_build_object('title','text','content','text'))
    when 'scene' then jsonb_build_object('table','scenes','scope','production',
      'fields', jsonb_build_object('title','text','description','text','purpose','text','planned_duration_ms','bigint'))
    when 'shot' then jsonb_build_object('table','shots','scope','production',
      'fields', jsonb_build_object('title','text','description','text','action','text','purpose','text','subject','text','planned_duration_ms','bigint'))
    when 'execution_plan' then jsonb_build_object('table','execution_plans','scope','production',
      'fields', jsonb_build_object('shot_size','text','movement','text','framing','text','composition','text',
        'camera_position','text','camera_height','text','camera_angle','text','lighting_intent','text','plan_metadata','jsonb',
        'performance','text','blocking','text','product_direction','text','provider_prompt','text',
        'canonical_prompt','jsonb','first_frame','jsonb','last_frame','jsonb','motion','jsonb'))
    when 'asset' then jsonb_build_object('table','assets','scope','workspace',
      'fields', jsonb_build_object('name','text','description','text','search_metadata','jsonb','consistency_metadata','jsonb'))
    when 'result' then jsonb_build_object('table','results','scope','production',
      'fields', jsonb_build_object('provenance','jsonb'))
    else null end;
$$;

revoke all on function tonde_private.vb_fields(text) from public, anon, authenticated, service_role;


-- Resolve a Result with Production coherence.
create or replace function tonde_private.ms_result(target_workspace uuid, target_production uuid, target_result uuid)
returns tonde.results language plpgsql stable security definer set search_path = '' as $$
declare result_row tonde.results;
begin
  select * into result_row from tonde.results
    where workspace_id = target_workspace and production_id = target_production and id = target_result;
  if not found then raise exception 'That Result is unavailable in this Production' using errcode = 'P0002'; end if;
  return result_row;
end $$;

revoke all on function tonde_private.ms_result(uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- Which modality a comparison dimension needs. This is what stops a visual claim being made from
-- metadata alone, and a measured lens claim being made from an image.
create or replace function tonde_private.ms_dimension(dimension_value text) returns text
language sql immutable set search_path = '' as $$
  select case dimension_value
    when 'audio' then 'audio'
    when 'timing' then 'timeline'
    when 'transition' then 'timeline'
    else 'visual' end;
$$;

revoke all on function tonde_private.ms_dimension(text) from public, anon, authenticated, service_role;


-- VERIFIED media capability. The truth is derived from real media rows, in the database, before any
-- analysis is recorded: a thumbnail only counts when a thumbnail row exists, frames only when a
-- keyframe was actually extracted, audio only when the media is audio or an extracted track exists.
create or replace function tonde_private.ms_capabilities(target_workspace uuid, target_result uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare media tonde.media_files; ready boolean; notes jsonb := '[]'::jsonb;
  has_thumb boolean; has_image boolean; has_frames boolean; has_audio boolean; has_text boolean;
begin
  select * into media from tonde.media_files m where m.workspace_id = target_workspace
    and m.id = (select r.media_id from tonde.results r where r.workspace_id = target_workspace and r.id = target_result);
  if media.id is null then
    return jsonb_build_object('metadata', false, 'thumbnail', false, 'image', false, 'video_frames', false,
      'audio', false, 'text', false, 'media_state', 'missing', 'notes',
      jsonb_build_array('No media row exists for this Result, so nothing can be compared.'));
  end if;
  ready := media.upload_state = 'uploaded' and media.processing_state = 'ready';
  has_thumb := media.file_category = 'thumbnail' or exists (select 1 from tonde.media_files d
    where d.workspace_id = target_workspace and d.derived_from_id = media.id and d.file_category = 'thumbnail');
  has_image := media.file_category = 'image' or exists (select 1 from tonde.media_files d
    where d.workspace_id = target_workspace and d.derived_from_id = media.id and d.file_category = 'image');
  has_frames := exists (select 1 from tonde.media_files d
    where d.workspace_id = target_workspace and d.derived_from_id = media.id and d.file_category = 'keyframe');
  has_audio := media.file_category = 'audio' or exists (select 1 from tonde.media_files d
    where d.workspace_id = target_workspace and d.derived_from_id = media.id and d.file_category = 'extracted_audio');
  has_text := media.mime_type = 'text/plain' or exists (select 1 from tonde.media_files d
    where d.workspace_id = target_workspace and d.derived_from_id = media.id and d.mime_type = 'text/plain');
  if not ready then
    return jsonb_build_object('metadata', true, 'thumbnail', false, 'image', false, 'video_frames', false,
      'audio', false, 'text', false, 'media_state', media.upload_state || '/' || media.processing_state,
      'notes', jsonb_build_array('The media is ' || media.upload_state || ' and ' || media.processing_state
        || ', so visual, frame and audio comparison cannot be claimed yet.'));
  end if;
  if not has_thumb then notes := notes || jsonb_build_array('No thumbnail was generated, so a thumbnail view is not claimed.'); end if;
  if media.file_category = 'video' and not has_frames then
    notes := notes || jsonb_build_array('No keyframe was extracted, so frame-level visual comparison is not claimed.');
  end if;
  if not has_audio and media.file_category <> 'audio' then
    notes := notes || jsonb_build_array('No audio track was extracted, so audio comparison is not claimed.');
  end if;
  return jsonb_build_object('metadata', true, 'thumbnail', has_thumb, 'image', has_image,
    'video_frames', has_frames, 'audio', has_audio, 'text', has_text,
    'media_state', media.upload_state || '/' || media.processing_state,
    'file_category', media.file_category, 'mime_type', media.mime_type,
    'notes', notes);
end $$;

revoke all on function tonde_private.ms_capabilities(uuid,uuid) from public, anon, authenticated, service_role;


create or replace function tonde_private.ms_available(capabilities jsonb, need text) returns boolean
language sql immutable set search_path = '' as $$
  select case need
    when 'visual' then coalesce((capabilities->>'thumbnail')::boolean, false)
      or coalesce((capabilities->>'image')::boolean, false)
      or coalesce((capabilities->>'video_frames')::boolean, false)
    when 'audio' then coalesce((capabilities->>'audio')::boolean, false)
    when 'timeline' then coalesce((capabilities->>'metadata')::boolean, false)
    else coalesce((capabilities->>'metadata')::boolean, false) end;
$$;

revoke all on function tonde_private.ms_available(jsonb,text) from public, anon, authenticated, service_role;


create or replace function tonde_private.ms_severity_verdict(severity_value text) returns tonde.match_verdict
language sql immutable set search_path = '' as $$
  select case severity_value
    when 'critical' then 'mismatch'::tonde.match_verdict
    when 'warning' then 'needs_attention'::tonde.match_verdict
    when 'info' then 'acceptable_variation'::tonde.match_verdict
    else 'unknown'::tonde.match_verdict end;
$$;

revoke all on function tonde_private.ms_severity_verdict(text) from public, anon, authenticated, service_role;


-- Prioritization: production impact first. An unreadable Product mark matters more than a slight
-- background colour variation.
create or replace function tonde_private.ms_impact_weight(category_value text) returns integer
language sql immutable set search_path = '' as $$
  select case category_value
    when 'product_fidelity' then 95 when 'character_consistency' then 85 when 'continuity' then 80
    when 'wardrobe' then 70 when 'props' then 70 when 'performance' then 65
    when 'environment' then 60 when 'framing' then 60 when 'subject_position' then 55
    when 'screen_direction' then 55 when 'composition' then 50 when 'timing' then 50
    when 'audio' then 50 when 'lighting' then 45 when 'camera_movement' then 45
    when 'subject_movement' then 45 when 'lens_perspective' then 40 when 'transition' then 40
    when 'camera_height' then 35 when 'camera_angle' then 35 when 'depth_of_field' then 35
    when 'contrast' then 30 when 'background' then 25 when 'color' then 25
    else 30 end;
$$;

revoke all on function tonde_private.ms_impact_weight(text) from public, anon, authenticated, service_role;


-- The four-part summary, computed from the findings themselves. Nothing is invented here.
create or replace function tonde_private.ms_summary(findings jsonb) returns jsonb
language plpgsql immutable set search_path = '' as $$
declare item jsonb; verdict text; category_value text; weight integer; severity_value text;
  worked jsonb := '[]'::jsonb; drifted jsonb := '[]'::jsonb; ranked jsonb := '[]'::jsonb;
  fixes jsonb := '[]'::jsonb; ranked_row record;
begin
  for item in select * from jsonb_array_elements(coalesce(findings, '[]'::jsonb)) loop
    category_value := coalesce(item->>'category', 'other');
    verdict := coalesce(item->>'verdict', 'unknown');
    severity_value := coalesce(item->>'severity', 'info');
    if verdict in ('matches_intent','acceptable_variation') and coalesce(item->>'epistemic','unknown') <> 'unknown' then
      worked := worked || jsonb_build_array(jsonb_build_object('category', category_value,
        'verdict', verdict, 'observed', coalesce(item->>'observed', '')));
    elsif verdict in ('needs_attention','mismatch') then
      drifted := drifted || jsonb_build_array(jsonb_build_object('category', category_value,
        'verdict', verdict, 'severity', severity_value, 'difference', coalesce(item->>'difference', '')));
    end if;
  end loop;
  for ranked_row in
    select coalesce(f->>'category','other') as category,
      tonde_private.ms_impact_weight(coalesce(f->>'category','other')) as weight,
      case coalesce(f->>'severity','info') when 'critical' then 3 when 'warning' then 2 when 'info' then 1 else 0 end as rank,
      coalesce(f->>'difference','') as difference, coalesce(f->>'suggested_correction','') as fix,
      coalesce(f->>'verdict','unknown') as verdict
    from jsonb_array_elements(coalesce(findings, '[]'::jsonb)) f
    where coalesce(f->>'verdict','unknown') in ('needs_attention','mismatch')
    order by rank desc, weight desc, category asc limit 3
  loop
    ranked := ranked || jsonb_build_array(jsonb_build_object('category', ranked_row.category,
      'weight', ranked_row.weight, 'difference', ranked_row.difference, 'verdict', ranked_row.verdict));
    if ranked_row.fix <> '' then
      fixes := fixes || jsonb_build_array(jsonb_build_object('category', ranked_row.category, 'fix', ranked_row.fix));
    end if;
  end loop;
  return jsonb_build_object('what_worked', worked, 'what_drifted', drifted,
    'what_matters_most', ranked, 'what_to_fix_next', fixes,
    'note', 'Ordered by production impact, not by a similarity score.');
end $$;

revoke all on function tonde_private.ms_summary(jsonb) from public, anon, authenticated, service_role;


-- The execution method behind a Result, so a Real mismatch recommends a pickup and an AI mismatch
-- recommends regeneration instead of guessing.
create or replace function tonde_private.ms_method(target_workspace uuid, target_production uuid, target_result uuid,
  target_shot uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
declare method text;
begin
  select p.execution_method::text into method from tonde.execution_plans p
    join tonde.results r on r.workspace_id = p.workspace_id and r.execution_plan_id = p.id
    where r.workspace_id = target_workspace and r.id = target_result;
  if method is not null then return method; end if;
  select case when count(*) = 1 then min(p.execution_method::text) else null end into method
    from tonde.execution_plans p where p.workspace_id = target_workspace
      and p.production_id = target_production and p.shot_id = target_shot;
  return method;
end $$;

revoke all on function tonde_private.ms_method(uuid,uuid,uuid,uuid) from public, anon, authenticated, service_role;


-- 5. The Result surface. A Result is what was actually created: it links to its Production, Scene,
-- Shot, execution plan, generation Attempt or Real Take, and media, and it carries its provenance.
create or replace function tonde.result_register(target_workspace uuid, target_production uuid, payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare shot_row tonde.shots; media_row tonde.media_files; take_row tonde.shot_takes; attempt_row tonde.ai_generation_attempts;
  origin_value text; media_id uuid; plan_id uuid; reference_id uuid; take_id uuid; attempt_id uuid;
  created tonde.results; provenance jsonb; capabilities jsonb;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(payload) <> 'object' then raise exception 'Invalid Result payload' using errcode = '22023'; end if;
  origin_value := coalesce(nullif(payload->>'origin',''), 'manual_import');
  if origin_value not in ('real_take','ai_generation','hybrid','manual_import') then
    raise exception 'A Result comes from a Real Take, an AI Attempt, a Hybrid process or a manual import' using errcode = '22023';
  end if;
  select * into shot_row from tonde.shots h where h.workspace_id = target_workspace
    and h.production_id = target_production and h.id = nullif(payload->>'shot_id','')::uuid and h.lifecycle = 'active';
  if not found then raise exception 'That Shot is unavailable in this Production' using errcode = 'P0002'; end if;
  take_id := nullif(payload->>'take_id','')::uuid;
  attempt_id := nullif(payload->>'attempt_id','')::uuid;
  if take_id is not null then
    select * into take_row from tonde.shot_takes t where t.workspace_id = target_workspace and t.id = take_id;
    if not found then raise exception 'That Take is unavailable' using errcode = 'P0002'; end if;
    if take_row.shot_id <> shot_row.id then raise exception 'That Take belongs to another Shot' using errcode = '22023'; end if;
  end if;
  if attempt_id is not null then
    select * into attempt_row from tonde.ai_generation_attempts a where a.workspace_id = target_workspace and a.id = attempt_id;
    if not found then raise exception 'That Attempt is unavailable' using errcode = 'P0002'; end if;
    if attempt_row.shot_id <> shot_row.id then raise exception 'That Attempt belongs to another Shot' using errcode = '22023'; end if;
  end if;
  if origin_value = 'real_take' and take_id is null then
    raise exception 'A Real Take Result must name the Take it came from' using errcode = '22023';
  end if;
  if origin_value = 'ai_generation' and attempt_id is null and coalesce(payload->>'media_id','') = '' then
    raise exception 'An AI Result must name its Attempt or its media' using errcode = '22023';
  end if;
  media_id := coalesce(nullif(payload->>'media_id','')::uuid, take_row.media_id, attempt_row.output_media_id);
  if media_id is null then raise exception 'A Result needs the media that was created' using errcode = '22023'; end if;
  select * into media_row from tonde.media_files m where m.workspace_id = target_workspace and m.id = media_id;
  if not found then raise exception 'That media is unavailable' using errcode = 'P0002'; end if;
  plan_id := coalesce(nullif(payload->>'execution_plan_id','')::uuid, take_row.plan_id, attempt_row.plan_id);
  reference_id := nullif(payload->>'reference_id','')::uuid;
  provenance := jsonb_build_object('origin', origin_value, 'registered_by', auth.uid(),
    'take_id', take_id, 'take_number', take_row.take_number, 'take_status', take_row.status::text,
    'attempt_id', attempt_id, 'attempt_number', attempt_row.attempt_number,
    'provider', attempt_row.provider_key, 'model', attempt_row.model_key,
    'media_state', media_row.upload_state || '/' || media_row.processing_state,
    'note', left(coalesce(payload->>'note',''), 600), 'registered_at', now());
  -- A Result is created for review. It is never created approved and never created Final.
  insert into tonde.results(workspace_id, production_id, scene_id, shot_id, media_id, reference_id,
    execution_plan_id, state, provenance)
  values (target_workspace, target_production, shot_row.scene_id, shot_row.id, media_id, reference_id,
    plan_id, 'needs_review', provenance)
  returning * into created;
  capabilities := tonde_private.ms_capabilities(target_workspace, created.id);
  return jsonb_build_object('result_id', created.id, 'shot_id', created.shot_id, 'scene_id', created.scene_id,
    'state', created.state, 'approval', created.approval, 'revision', created.revision,
    'provenance', provenance, 'capabilities', capabilities,
    'note', 'A new Result starts as Needs review. Nothing is approved automatically, and Final is always an explicit creator decision.');
end $$;


create or replace function tonde.result_list(target_workspace uuid, target_production uuid,
  target_shot uuid default null, target_state text default null, max_rows integer default 50, skip_rows integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare items jsonb := '[]'::jsonb; total integer; result_row tonde.results; rec record; plan_row tonde.execution_plans;
  report_row record; capabilities jsonb; provenance jsonb; links jsonb;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  if target_state is not null and target_state not in ('raw','needs_review','approved','rejected','final') then
    raise exception 'Unsupported Result state filter' using errcode = '22023';
  end if;
  select count(*) into total from tonde.results r where r.workspace_id = target_workspace
    and r.production_id = target_production and (target_shot is null or r.shot_id = target_shot)
    and (target_state is null or r.state::text = target_state);
  for result_row in
    select * from tonde.results r where r.workspace_id = target_workspace
      and r.production_id = target_production and (target_shot is null or r.shot_id = target_shot)
      and (target_state is null or r.state::text = target_state)
      order by r.created_at desc, r.id limit greatest(1, least(coalesce(max_rows,50),200)) offset greatest(0, coalesce(skip_rows,0))
  loop
    capabilities := tonde_private.ms_capabilities(target_workspace, result_row.id);
    provenance := result_row.provenance;
    plan_row := null;
    if result_row.execution_plan_id is not null then
      select * into plan_row from tonde.execution_plans p where p.workspace_id = target_workspace and p.id = result_row.execution_plan_id;
    end if;
    select count(*) as reports, max(m.severity) as worst,
      (array_agg(m.recommendation::text order by m.created_at desc))[1] as recommendation,
      (array_agg(m.decision order by m.created_at desc))[1] as decision
      into report_row from tonde.shot_match_reports m
      where m.workspace_id = target_workspace and m.result_id = result_row.id;
    links := jsonb_build_object(
      'shot_id', result_row.shot_id, 'scene_id', result_row.scene_id,
      'execution_plan_id', result_row.execution_plan_id,
      'execution_plan_method', plan_row.execution_method::text,
      'execution_plan_revision', plan_row.revision,
      'reference_id', result_row.reference_id,
      'attempt_id', provenance->>'attempt_id', 'take_id', provenance->>'take_id',
      'media_id', result_row.media_id, 'media_state', capabilities->>'media_state',
      'media_file_category', capabilities->>'file_category');
    items := items || jsonb_build_array(jsonb_build_object(
      'result_id', result_row.id, 'state', result_row.state, 'approval', result_row.approval,
      'locked', result_row.locked_at is not null, 'revision', result_row.revision,
      'shot_id', result_row.shot_id, 'shot_label', tonde_private.pi_label(target_workspace, result_row.shot_id),
      'origin', provenance->>'origin', 'provenance', provenance, 'links', links,
      'capabilities', capabilities,
      'match_reports', coalesce(report_row.reports, 0), 'match_worst_severity', report_row.worst,
      'match_recommendation', coalesce(report_row.recommendation, 'none'),
      'match_decision', report_row.decision,
      'created_at', result_row.created_at));
  end loop;
  return jsonb_build_object('items', items, 'total', total,
    'limit', greatest(1, least(coalesce(max_rows,50),200)), 'offset', greatest(0, coalesce(skip_rows,0)),
    'note', 'A Result is what was created, not the plan. Media capabilities are derived from real media rows.');
end $$;


create or replace function tonde.result_detail(target_workspace uuid, target_production uuid, target_result uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare result_row tonde.results; plan_row tonde.execution_plans; capabilities jsonb; versions integer;
  reports jsonb; corrections jsonb; items jsonb := '[]'::jsonb; correction_row record;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  result_row := tonde_private.ms_result(target_workspace, target_production, target_result);
  capabilities := tonde_private.ms_capabilities(target_workspace, target_result);
  if result_row.execution_plan_id is not null then
    select * into plan_row from tonde.execution_plans p where p.workspace_id = target_workspace and p.id = result_row.execution_plan_id;
  end if;
  select count(*) into versions from tonde.object_versions v
    where v.workspace_id = target_workspace and v.object_id = target_result;
  select coalesce(jsonb_agg(jsonb_build_object('report_id', m.id, 'state', m.state, 'severity', m.severity,
      'recommendation', m.recommendation, 'decision', m.decision, 'origin', m.origin,
      'approval', m.approval, 'created_at', m.created_at) order by m.created_at desc), '[]'::jsonb)
    into reports from tonde.shot_match_reports m
    where m.workspace_id = target_workspace and m.result_id = target_result;
  for correction_row in select c.id, c.state, c.target_object_id, c.target_label, c.target_kind, c.root_cause,
      c.patch, c.applied_revision, c.note, c.created_at from tonde.match_corrections c
    where c.workspace_id = target_workspace and c.result_id = target_result order by c.created_at desc loop
    items := items || jsonb_build_array(jsonb_build_object('correction_id', correction_row.id,
      'state', correction_row.state, 'target_object_id', correction_row.target_object_id,
      'target_label', correction_row.target_label, 'target_kind', correction_row.target_kind,
      'root_cause', correction_row.root_cause, 'patch', correction_row.patch,
      'applied_revision', correction_row.applied_revision, 'note', correction_row.note,
      'created_at', correction_row.created_at));
  end loop;
  return jsonb_build_object('result_id', result_row.id, 'state', result_row.state, 'approval', result_row.approval,
    'locked', result_row.locked_at is not null, 'revision', result_row.revision,
    'shot_id', result_row.shot_id, 'shot_label', tonde_private.pi_label(target_workspace, result_row.shot_id),
    'scene_id', result_row.scene_id, 'media_id', result_row.media_id, 'capabilities', capabilities,
    'provenance', result_row.provenance,
    'plan', case when plan_row.id is null then null else jsonb_build_object('plan_id', plan_row.id,
      'execution_method', plan_row.execution_method, 'approval', plan_row.approval, 'revision', plan_row.revision,
      'shot_size', plan_row.shot_size, 'camera_position', plan_row.camera_position, 'framing', plan_row.framing,
      'movement', plan_row.movement, 'lighting_intent', plan_row.lighting_intent,
      'first_frame', plan_row.first_frame, 'provider_prompt', plan_row.provider_prompt) end,
    'version_count', versions, 'match_reports', reports, 'corrections', items,
    'note', 'The Result keeps its revision history. Corrections are recorded, never overwritten.');
end $$;


-- Result state is a creator decision. Final is always explicit and requires an approval first.
create or replace function tonde.result_state_set(target_workspace uuid, target_production uuid, target_result uuid,
  desired_state text, expected_revision integer default null, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare result_row tonde.results; current_state text; allowed boolean := false; new_revision integer;
  approval_now text;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  result_row := tonde_private.ms_result(target_workspace, target_production, target_result);
  if desired_state not in ('raw','needs_review','approved','rejected','final') then
    raise exception 'Unsupported Result state' using errcode = '22023';
  end if;
  current_state := result_row.state::text;
  if expected_revision is not null and result_row.revision <> expected_revision then
    raise exception 'That Result changed since you loaded it' using errcode = '40001';
  end if;
  -- Final is answered first: a creator asking for Final before accepting the Result is told what is
  -- actually missing instead of only that the move is unavailable.
  approval_now := tonde_private.ax_approval(target_workspace, target_result);
  if desired_state = 'final' and approval_now <> 'approved' then
    raise exception 'A Result becomes Final only after a creator approved it' using errcode = '23514';
  end if;
  allowed := case current_state
    when 'raw' then desired_state in ('needs_review','approved','rejected')
    when 'needs_review' then desired_state in ('approved','rejected')
    when 'approved' then desired_state in ('needs_review','final')
    when 'rejected' then desired_state = 'needs_review'
    when 'final' then desired_state = 'needs_review'
    else false end;
  if not allowed then
    raise exception 'A Result cannot move from % to %', current_state, desired_state using errcode = '23514';
  end if;
  update tonde.results set state = desired_state::tonde.result_state
    where workspace_id = target_workspace and id = target_result returning revision into new_revision;
  if new_revision is null then raise exception 'That Result is unavailable' using errcode = 'P0002'; end if;
  -- An explicit creator decision to accept a Result IS the approval. Shot Match itself never approves,
  -- and moving an accepted Result forward must not report it as merely changed after approval: the
  -- approval is written against the exact revision the creator just decided on.
  if desired_state in ('approved', 'final')
    and tonde_private.ax_approval(target_workspace, target_result) is distinct from 'approved' then
    new_revision := tonde_private.ax_set_approval(target_workspace, target_production, target_result, 'approved');
    if desired_state = 'approved' then
      insert into tonde.access_decisions(workspace_id, production_id, object_id, object_kind, action,
        from_approval, to_approval, from_locked, to_locked, pinned_revision, note, actor_user_id)
      values (target_workspace, target_production, target_result, 'result', 'approve',
        coalesce(approval_now, 'draft')::tonde.approval, 'approved',
        coalesce(tonde_private.pi_is_locked(target_workspace, target_result), false),
        coalesce(tonde_private.pi_is_locked(target_workspace, target_result), false), new_revision,
        left(coalesce(note_text,''), 800), auth.uid());
    end if;
  end if;
  return jsonb_build_object('result_id', target_result, 'state', desired_state, 'previous_state', current_state,
    'approval', tonde_private.ax_approval(target_workspace, target_result), 'revision', new_revision,
    'note', left(coalesce(note_text,''), 800),
    'meaning', case when desired_state = 'final'
        then 'Final is explicitly accepted evidence or deliverable state; generation completion never sets it.'
      when desired_state = 'approved' then 'A creator accepted this Result. Shot Match never approves a Result.'
      when desired_state = 'rejected' then 'This Result is rejected. The Shot still needs a usable take.'
      else 'This Result is waiting for a creator review.' end);
end $$;


-- 6. Shot Match. Records an analysis of what is different between Reference, Plan and Result, and how
-- to fix it. It never approves a Result and never launches generation.
create or replace function tonde.match_analyze(target_workspace uuid, target_production uuid, target_shot uuid, payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare result_row tonde.results; capabilities jsonb; claimed jsonb; item jsonb; key_value text;
  findings jsonb := '[]'::jsonb; normalized jsonb; dimension_value text; need text; severity_value text;
  verdict_value text; worst text := 'info'; worst_rank integer := 0; rank integer; category_value text;
  reference_id uuid; report tonde.shot_match_reports; method text; recommendation tonde.correction_recommendation;
  dimensions jsonb := '[]'::jsonb; dim record; continuity_id uuid; continuity_ids jsonb := '[]'::jsonb;
  limitations text[] := '{}'; origin_value tonde.match_origin; suggestions jsonb := '[]'::jsonb;
  allowed_keys text[] := array['category','verdict','expected','observed','difference','epistemic','confidence',
    'severity','evidence','suggested_correction','continuity_domain','subject_asset_id','region','time_range'];
  previous integer;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(payload) <> 'object' then raise exception 'Invalid Shot Match payload' using errcode = '22023'; end if;
  if not exists (select 1 from tonde.shots h where h.workspace_id = target_workspace
      and h.production_id = target_production and h.id = target_shot and h.lifecycle = 'active') then
    raise exception 'That Shot is unavailable in this Production' using errcode = 'P0002';
  end if;
  result_row := tonde_private.ms_result(target_workspace, target_production, nullif(payload->>'result_id','')::uuid);
  if result_row.shot_id <> target_shot then
    raise exception 'That Result belongs to another Shot' using errcode = '22023';
  end if;
  -- 110. Media capability truth: the verified modalities come from real media rows, and a claim the
  -- database cannot substantiate is refused rather than recorded.
  capabilities := tonde_private.ms_capabilities(target_workspace, result_row.id);
  claimed := coalesce(payload->'capabilities', '{}'::jsonb);
  if jsonb_typeof(claimed) <> 'object' then raise exception 'Capabilities must be an object' using errcode = '22023'; end if;
  for key_value in select jsonb_object_keys(claimed) loop
    if key_value in ('thumbnail','image','video_frames','audio','text')
      and coalesce((claimed->>key_value)::boolean, false)
      and not coalesce((capabilities->>key_value)::boolean, false) then
      raise exception 'That modality is not available for this Result: %', key_value using errcode = '23514';
    end if;
  end loop;
  if jsonb_array_length(coalesce(capabilities->'notes','[]'::jsonb)) > 0 then
    for key_value in select jsonb_array_elements_text(capabilities->'notes') loop
      limitations := limitations || key_value;
    end loop;
  end if;
  -- 111/112/113/114/115/116. Findings keep the evidence discipline.
  for item in select * from jsonb_array_elements(coalesce(payload->'findings','[]'::jsonb)) loop
    if jsonb_typeof(item) <> 'object' then raise exception 'A Shot Match finding must be an object' using errcode = '22023'; end if;
    for key_value in select jsonb_object_keys(item) loop
      if key_value ~ '(name|person|identity|face)' then
        raise exception 'Shot Match never identifies a person by name or by face' using errcode = '22023';
      end if;
      if not (key_value = any(allowed_keys)) then
        raise exception 'Unsupported finding field: %', key_value using errcode = '22023';
      end if;
    end loop;
    category_value := btrim(coalesce(item->>'category',''));
    if length(category_value) = 0 or length(category_value) > 60 then
      raise exception 'A finding names the dimension it compares' using errcode = '22023';
    end if;
    if coalesce(item->>'epistemic','') not in ('observed','estimated','recommended','unknown') then
      raise exception 'A finding carries a real epistemic state' using errcode = '22023';
    end if;
    if coalesce(item->>'confidence','') not in ('high','medium','low') then
      raise exception 'A finding carries a confidence of high, medium or low' using errcode = '22023';
    end if;
    severity_value := coalesce(nullif(item->>'severity',''), 'info');
    if severity_value not in ('info','warning','critical') then
      raise exception 'Unsupported finding severity' using errcode = '22023';
    end if;
    if jsonb_array_length(coalesce(item->'evidence','[]'::jsonb)) = 0 and coalesce(item->>'epistemic','') = 'observed' then
      raise exception 'An observed difference must cite the evidence it was seen on' using errcode = '23514';
    end if;
    dimension_value := coalesce(nullif(item->>'category',''), 'other');
    need := tonde_private.ms_dimension(dimension_value);
    if coalesce(item->>'epistemic','') = 'observed' and not tonde_private.ms_available(capabilities, need) then
      raise exception 'A % difference cannot be observed from the available media', dimension_value using errcode = '23514';
    end if;
    if dimension_value = 'lens_perspective' and coalesce(item->>'epistemic','') = 'observed'
      and coalesce(item->>'observed','') ~ '([0-9]+\s*(mm|deg|degree|f/[0-9]))' then
      raise exception 'Report an estimated look, never a measured focal length' using errcode = '22023';
    end if;
    if coalesce(item->>'continuity_domain','') <> '' and coalesce(item->>'continuity_domain','') not in
      ('character','wardrobe','prop','product','vehicle','injury','hair_makeup','weather','time_of_day',
       'environment','lighting','story_knowledge','dialogue_fact','screen_direction','eyeline',
       'camera_geography','position','product_condition','other') then
      raise exception 'Unsupported continuity domain' using errcode = '22023';
    end if;
    verdict_value := coalesce(nullif(item->>'verdict',''), tonde_private.ms_severity_verdict(severity_value)::text);
    if verdict_value not in ('matches_intent','acceptable_variation','needs_attention','mismatch','unknown') then
      raise exception 'Unsupported match verdict' using errcode = '22023';
    end if;
    if verdict_value = 'matches_intent' and jsonb_array_length(coalesce(item->'evidence','[]'::jsonb)) = 0 then
      raise exception 'A match claim must cite the evidence it was judged on' using errcode = '23514';
    end if;
    rank := case severity_value when 'critical' then 3 when 'warning' then 2 else 1 end;
    if rank > worst_rank then worst_rank := rank; worst := severity_value; end if;
    normalized := jsonb_build_object('category', dimension_value, 'verdict', verdict_value,
      'expected', left(coalesce(item->>'expected',''), 600), 'observed', left(coalesce(item->>'observed',''), 600),
      'difference', left(coalesce(item->>'difference',''), 600), 'epistemic', item->>'epistemic',
      'confidence', item->>'confidence', 'severity', severity_value,
      'evidence', coalesce(item->'evidence','[]'::jsonb),
      'suggested_correction', left(coalesce(item->>'suggested_correction',''), 600),
      'region', left(coalesce(item->>'region',''), 120), 'time_range', left(coalesce(item->>'time_range',''), 120),
      'subject_asset_id', nullif(item->>'subject_asset_id',''));
    -- 139. A continuity-relevant finding links into the existing continuity system instead of
    -- creating a second issue model.
    if coalesce(item->>'continuity_domain','') <> '' then
      insert into tonde.continuity_findings(workspace_id, production_id, kind, severity, domain,
        subject_object_id, at_scene_id, at_shot_id, explanation, suggested_resolution, origin,
        epistemic, confidence, evidence)
      values (target_workspace, target_production, 'unexplained_change', severity_value,
        (item->>'continuity_domain')::tonde.continuity_domain,
        nullif(item->>'subject_asset_id','')::uuid,
        (select h.scene_id from tonde.shots h where h.workspace_id = target_workspace and h.id = target_shot),
        target_shot, left(coalesce(item->>'difference', item->>'observed', 'A Shot Match finding'), 1200),
        left(coalesce(item->>'suggested_correction',''), 1200),
        (case when item->>'epistemic' = 'observed' then 'derived' else 'inferred' end)::tonde.continuity_origin,
        item->>'epistemic', coalesce(item->>'confidence','high'), coalesce(item->'evidence','[]'::jsonb))
      returning id into continuity_id;
      normalized := jsonb_set(normalized, '{continuity_finding_id}', to_jsonb(continuity_id));
      continuity_ids := continuity_ids || jsonb_build_array(continuity_id);
    end if;
    if coalesce(normalized->>'suggested_correction','') <> '' then
      suggestions := suggestions || jsonb_build_array(jsonb_build_object('category', dimension_value,
        'correction', normalized->>'suggested_correction', 'severity', severity_value));
    end if;
    findings := findings || jsonb_build_array(normalized);
  end loop;
  if jsonb_array_length(findings) = 0 then
    raise exception 'A Shot Match analysis records at least one finding' using errcode = '22023';
  end if;
  -- Per-dimension verdicts, worst first, derived from the findings themselves.
  for dim in
    select f->>'category' as category,
      case min(case f->>'severity' when 'critical' then 3 when 'warning' then 2 else 1 end)
        when 3 then 'mismatch' when 2 then 'needs_attention' else 'acceptable_variation' end as verdict,
      count(*) as findings
    from jsonb_array_elements(findings) f group by 1 order by 1
  loop
    dimensions := dimensions || jsonb_build_array(jsonb_build_object('dimension', dim.category,
      'verdict', dim.verdict, 'findings', dim.findings,
      'weight', tonde_private.ms_impact_weight(dim.category)));
  end loop;
  method := tonde_private.ms_method(target_workspace, target_production, result_row.id, target_shot);
  recommendation := case
    when worst_rank < 2 then 'none'::tonde.correction_recommendation
    when method = 'real' then 'pickup_required'::tonde.correction_recommendation
    when method = 'ai' then 'regeneration_recommended'::tonde.correction_recommendation
    when method = 'hybrid' then 'both'::tonde.correction_recommendation
    else 'none'::tonde.correction_recommendation end;
  if method is null then
    -- The cast matters: an untyped literal would be read as an array literal and fail at runtime.
    limitations := limitations || ('The execution method behind this Result is unknown, so no pickup or regeneration recommendation is made.')::text;
  end if;
  origin_value := coalesce(nullif(payload->>'origin',''), 'deterministic')::tonde.match_origin;
  reference_id := coalesce(nullif(payload->>'reference_id','')::uuid, result_row.reference_id);
  select count(*) into previous from tonde.shot_match_reports m
    where m.workspace_id = target_workspace and m.shot_id = target_shot;
  insert into tonde.shot_match_reports(workspace_id, production_id, shot_id, result_id, state, findings,
    severity, recommendations, approval, capabilities, dimensions, summary, limitations, origin, recommendation)
  values (target_workspace, target_production, target_shot, result_row.id, 'complete', findings, worst,
    suggestions, 'draft', capabilities, dimensions, tonde_private.ms_summary(findings), limitations, origin_value,
    recommendation)
  returning * into report;
  return jsonb_build_object('report_id', report.id, 'shot_id', target_shot, 'result_id', result_row.id,
    'reference_id', reference_id, 'state', report.state, 'severity', worst, 'approval', report.approval,
    'findings', findings, 'dimensions', dimensions, 'recommendations', suggestions,
    'summary', report.summary, 'capabilities', capabilities, 'limitations', limitations,
    'origin', origin_value, 'recommendation', recommendation, 'iteration', previous + 1,
    'continuity_finding_ids', continuity_ids,
    'note', 'Shot Match diagnoses what is different and how to fix it. It is not a similarity score, it does not approve the Result, and it launches no generation.');
end $$;


create or replace function tonde.match_reports(target_workspace uuid, target_production uuid, target_shot uuid default null,
  target_result uuid default null, max_rows integer default 25, skip_rows integer default 0)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare items jsonb := '[]'::jsonb; total integer; report_row record;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select count(*) into total from tonde.shot_match_reports m where m.workspace_id = target_workspace
    and m.production_id = target_production and (target_shot is null or m.shot_id = target_shot)
    and (target_result is null or m.result_id = target_result);
  for report_row in
    select m.id, m.shot_id, m.result_id, m.state, m.severity, m.recommendation, m.decision, m.decision_note,
      m.origin, m.approval, m.capabilities, m.limitations, m.decided_by, m.decided_at, m.created_at
    from tonde.shot_match_reports m where m.workspace_id = target_workspace
      and m.production_id = target_production and (target_shot is null or m.shot_id = target_shot)
      and (target_result is null or m.result_id = target_result)
    order by m.created_at desc, m.id limit greatest(1, least(coalesce(max_rows,25),100)) offset greatest(0, coalesce(skip_rows,0))
  loop
    items := items || jsonb_build_array(jsonb_build_object('report_id', report_row.id, 'shot_id', report_row.shot_id,
      'shot_label', tonde_private.pi_label(target_workspace, report_row.shot_id), 'result_id', report_row.result_id,
      'state', report_row.state, 'severity', report_row.severity, 'recommendation', report_row.recommendation,
      'decision', report_row.decision, 'decision_note', report_row.decision_note, 'origin', report_row.origin,
      'approval', report_row.approval, 'capabilities', report_row.capabilities,
      'limitations', to_jsonb(report_row.limitations), 'decided_by', report_row.decided_by,
      'decided_at', report_row.decided_at, 'created_at', report_row.created_at));
  end loop;
  return jsonb_build_object('items', items, 'total', total,
    'note', 'Each report is one analysis in the Shot iteration history. Earlier analyses are preserved.');
end $$;


create or replace function tonde.match_report_get(target_workspace uuid, target_production uuid, target_report uuid)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare report tonde.shot_match_reports; items jsonb := '[]'::jsonb; correction_row record; chain jsonb := '[]'::jsonb;
  result_row tonde.results;
begin
  perform tonde_private.pi_read_guard(target_workspace);
  select * into report from tonde.shot_match_reports m where m.workspace_id = target_workspace
    and m.production_id = target_production and m.id = target_report;
  if not found then raise exception 'That Shot Match report is unavailable' using errcode = 'P0002'; end if;
  result_row := tonde_private.ms_result(target_workspace, target_production, report.result_id);
  for correction_row in select c.id, c.state, c.target_object_id, c.target_label, c.target_kind, c.root_cause,
      c.why, c.affected, c.patch, c.recommendation, c.continuity_finding_id, c.preview, c.applied_revision,
      c.applied_version_id, c.propagation, c.decided_by, c.decided_at, c.note, c.created_at
    from tonde.match_corrections c where c.workspace_id = target_workspace and c.report_id = target_report
    order by c.created_at loop
    items := items || jsonb_build_array(jsonb_build_object('correction_id', correction_row.id,
      'state', correction_row.state, 'target_object_id', correction_row.target_object_id,
      'target_label', correction_row.target_label, 'target_kind', correction_row.target_kind,
      'root_cause', correction_row.root_cause, 'why', correction_row.why, 'affected', correction_row.affected,
      'patch', correction_row.patch, 'recommendation', correction_row.recommendation,
      'continuity_finding_id', correction_row.continuity_finding_id, 'preview', correction_row.preview,
      'applied_revision', correction_row.applied_revision, 'applied_version_id', correction_row.applied_version_id,
      'propagation', correction_row.propagation, 'decided_by', correction_row.decided_by,
      'decided_at', correction_row.decided_at, 'note', correction_row.note, 'created_at', correction_row.created_at));
  end loop;
  select coalesce(jsonb_agg(jsonb_build_object('report_id', h.id, 'created_at', h.created_at,
      'severity', h.severity, 'recommendation', h.recommendation, 'decision', h.decision)
      order by h.created_at), '[]'::jsonb) into chain
    from (select * from tonde.shot_match_reports m where m.workspace_id = target_workspace and m.shot_id = report.shot_id
      order by m.created_at limit 50) h;
  return jsonb_build_object('report_id', report.id, 'shot_id', report.shot_id,
    'shot_label', tonde_private.pi_label(target_workspace, report.shot_id), 'result_id', report.result_id,
    'result_state', result_row.state, 'state', report.state, 'severity', report.severity,
    'approval', report.approval, 'decision', report.decision, 'decision_note', report.decision_note,
    'decided_by', report.decided_by, 'decided_at', report.decided_at, 'origin', report.origin,
    'recommendation', report.recommendation, 'capabilities', report.capabilities,
    'findings', report.findings, 'dimensions', report.dimensions, 'summary', report.summary,
    'recommendations', report.recommendations, 'limitations', to_jsonb(report.limitations),
    'corrected_plan_id', report.corrected_plan_id, 'corrections', items, 'iteration_chain', chain,
    'note', 'The iteration history is preserved: each analysis and correction stays readable.');
end $$;


-- The creator decides what to do with a report. Picking up a Real pickup touches the Prompt 6
-- capture state explicitly; recommending regeneration launches nothing.
create or replace function tonde.match_report_decide(target_workspace uuid, target_production uuid, target_report uuid,
  decision_value text, note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare report tonde.shot_match_reports; capture tonde.shot_capture_state;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if decision_value not in ('pickup','regeneration','accepted','dismiss') then
    raise exception 'A Shot Match decision is pickup, regeneration, accepted or dismiss' using errcode = '22023';
  end if;
  select * into report from tonde.shot_match_reports m where m.workspace_id = target_workspace
    and m.production_id = target_production and m.id = target_report;
  if not found then raise exception 'That Shot Match report is unavailable' using errcode = 'P0002'; end if;
  if report.state <> 'complete' then raise exception 'Only a completed analysis can be decided' using errcode = '23514'; end if;
  if report.decision is not null then raise exception 'That Shot Match report was already decided' using errcode = '23514'; end if;
  if decision_value = 'pickup' then
    select * into capture from tonde.shot_capture_state c where c.workspace_id = target_workspace
      and c.production_id = target_production and c.shot_id = report.shot_id;
    if capture.id is null then
      insert into tonde.shot_capture_state(workspace_id, production_id, shot_id, status, notes)
      values (target_workspace, target_production, report.shot_id, 'pickup_needed',
        'A Shot Match pickup was required.') returning * into capture;
    else
      update tonde.shot_capture_state c set status = 'pickup_needed',
        notes = left(coalesce(nullif(c.notes,'') || ' ', '') || 'A Shot Match pickup was required.', 1200)
        where c.id = capture.id returning * into capture;
    end if;
  end if;
  update tonde.shot_match_reports m set decision = decision_value,
    decision_note = left(coalesce(note_text,''), 800),
    decided_by = auth.uid(), decided_at = now()
    where m.id = report.id returning * into report;
  -- The report's approval IS its review state: Prompt 9E readiness blocks on a completed report that
  -- is still draft or needs review. It is written on its own, because a combined content change and
  -- approval never approves work the creator has not reviewed.
  update tonde.shot_match_reports m set approval = 'approved'
    where m.id = report.id and m.approval <> 'approved' returning * into report;
  return jsonb_build_object('report_id', report.id, 'shot_id', report.shot_id, 'decision', decision_value,
    'approval', report.approval, 'recommendation', report.recommendation,
    'capture_status', case when decision_value = 'pickup' then 'pickup_needed' else null end,
    'note', case when decision_value = 'pickup'
        then 'The Shot is marked for a pickup in the On-Set capture state. The Result itself is unchanged.'
      when decision_value = 'regeneration'
        then 'Regeneration is recommended. Nothing was launched: generation still needs the normal explicit confirmation.'
      when decision_value = 'accepted' then 'The diagnosis is accepted. The Result is still reviewed separately.'
      else 'The analysis was dismissed. Nothing changed.' end,
    'meaning', 'Deciding a Shot Match report is not an approval of the Result.');
end $$;


-- 7. FIX THIS SHOT. A scoped correction: one real target object, one validated patch, a recorded root
-- cause, and a previewed impact. It never regenerates a whole Production.
create or replace function tonde.match_correction_propose(target_workspace uuid, target_production uuid, target_report uuid, payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare report tonde.shot_match_reports; target_object tonde.objects; map jsonb; field_name text;
  preview jsonb; analysis jsonb; correction tonde.match_corrections; recommendation_value tonde.correction_recommendation;
  continuity_id uuid;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if jsonb_typeof(payload) <> 'object' then raise exception 'Invalid correction payload' using errcode = '22023'; end if;
  select * into report from tonde.shot_match_reports m where m.workspace_id = target_workspace
    and m.production_id = target_production and m.id = target_report;
  if not found then raise exception 'That Shot Match report is unavailable' using errcode = 'P0002'; end if;
  if report.state <> 'complete' then raise exception 'Only a completed analysis can propose a correction' using errcode = '23514'; end if;
  target_object := tonde_private.vb_object(target_workspace, target_production, nullif(payload->>'target_object_id','')::uuid);
  map := tonde_private.vb_fields(target_object.kind);
  if map is null then
    raise exception 'That object kind cannot be corrected this way. Choose the Shot, the Real or AI execution plan, the prompt, the First Frame or the Story or Script.' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(payload->'patch','{}'::jsonb)) <> 'object' or coalesce(payload->'patch','{}'::jsonb) = '{}'::jsonb then
    raise exception 'A correction needs at least one field to change' using errcode = '22023';
  end if;
  for field_name in select jsonb_object_keys(payload->'patch') loop
    if not (map->'fields' ? field_name) then
      raise exception 'The field % cannot be corrected this way', field_name using errcode = '22023';
    end if;
  end loop;
  -- The impact is computed, never applied, by this proposal.
  analysis := tonde.impact_preview(target_workspace, target_production,
    target_object.id, 2, 200);
  preview := jsonb_build_object('analysis_id', analysis->>'analysis_id', 'counts', analysis->'counts',
    'explanation', analysis->'explanation',
    'note', 'Impact is computed by this proposal and applied only when you accept the correction.');
  recommendation_value := coalesce(nullif(payload->>'recommendation',''), report.recommendation::text)::tonde.correction_recommendation;
  continuity_id := nullif(payload->>'continuity_finding_id','')::uuid;
  insert into tonde.match_corrections(workspace_id, production_id, report_id, shot_id, result_id,
    target_object_id, target_kind, target_label, source_revision, patch, root_cause, why, affected,
    recommendation, continuity_finding_id, preview)
  values (target_workspace, target_production, report.id, report.shot_id, report.result_id,
    target_object.id, target_object.kind, tonde_private.pi_label(target_workspace, target_object.id),
    tonde_private.pi_object_revision(target_workspace, target_object.id), payload->'patch',
    left(coalesce(payload->>'root_cause',''), 800), left(coalesce(payload->>'why',''), 800),
    left(coalesce(payload->>'affected',''), 400), recommendation_value, continuity_id, preview)
  returning * into correction;
  return jsonb_build_object('correction_id', correction.id, 'report_id', report.id, 'shot_id', report.shot_id,
    'state', correction.state, 'target_object_id', target_object.id, 'target_kind', target_object.kind,
    'target_label', correction.target_label, 'source_revision', correction.source_revision,
    'patch', correction.patch, 'root_cause', correction.root_cause, 'why', correction.why,
    'affected', correction.affected, 'recommendation', correction.recommendation,
    'continuity_finding_id', correction.continuity_finding_id, 'preview', preview,
    'note', 'The correction is a proposal. Applying it creates a new revision; the previous plan and Result are preserved.');
end $$;


create or replace function tonde.match_correction_apply(target_workspace uuid, target_production uuid, target_correction uuid,
  expected_revision integer default null, propagation text default 'change_only_this', note_text text default '',
  record_candidate boolean default false)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare correction tonde.match_corrections; applied jsonb; analysis jsonb; propagation_result jsonb;
  target_object tonde.objects; later integer; candidate jsonb; report tonde.shot_match_reports;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  if coalesce(propagation,'') not in ('update_all','review_changes','change_only_this') then
    raise exception 'Unsupported propagation mode' using errcode = '22023';
  end if;
  select * into correction from tonde.match_corrections c where c.workspace_id = target_workspace
    and c.production_id = target_production and c.id = target_correction;
  if not found then raise exception 'That correction is unavailable' using errcode = 'P0002'; end if;
  if correction.state <> 'proposed' then raise exception 'That correction was already decided' using errcode = '23514'; end if;
  if expected_revision is not null and correction.source_revision <> expected_revision then
    raise exception 'That correction was proposed against a different revision' using errcode = '40001';
  end if;
  target_object := tonde_private.vb_object(target_workspace, target_production, correction.target_object_id);
  -- 93. A locked decision is never changed incidentally: unlock it deliberately first.
  if tonde_private.pi_is_locked(target_workspace, correction.target_object_id) then
    raise exception 'That object is locked. Unlock it deliberately before applying a correction.' using errcode = '23514';
  end if;
  select * into report from tonde.shot_match_reports m where m.workspace_id = target_workspace and m.id = correction.report_id;
  -- 140/141. Reusable memory needs a LATER analysis that confirmed the fix helped. The refusal happens
  -- before anything is applied, so a refused memory request never changes the plan.
  if record_candidate then
    select count(*) into later from tonde.shot_match_reports m where m.workspace_id = target_workspace
      and m.shot_id = correction.shot_id and m.created_at > report.created_at;
    if later = 0 then
      raise exception 'A correction does not become reusable memory until a later Shot Match confirms it helped' using errcode = '23514';
    end if;
  end if;
  applied := tonde_private.vb_patch_apply(target_workspace, target_production, correction.target_object_id,
    correction.patch, correction.source_revision, 'correction');
  -- Propagate the consequence through the Prompt 9A impact engine.
  analysis := tonde.impact_preview(target_workspace, target_production, correction.target_object_id, 2, 200);
  propagation_result := tonde.apply_impact(target_workspace, target_production, (analysis->>'analysis_id')::uuid,
    propagation, '{}'::uuid[], null, 'FIX THIS SHOT correction approved by the creator');
  if target_object.kind = 'execution_plan' then
    update tonde.shot_match_reports m set corrected_plan_id = correction.target_object_id where m.id = report.id;
  end if;
  -- 140/141. The correction becomes reusable memory ONLY through the existing memory policy, and only
  -- because a later analysis confirmed it helped. Nothing is remembered from a single Shot.
  if record_candidate then
    candidate := tonde.memory_candidate_record(target_workspace, target_production, jsonb_build_object(
      'kind', 'technique', 'proposed_source', 'historical_pattern',
      'subject_key', 'Fix for ' || correction.target_label,
      'statement', left('For ' || correction.target_label || ': ' || coalesce(nullif(correction.why,''), correction.root_cause), 600),
      'basis', jsonb_build_array(jsonb_build_object('kind', 'shot_match_correction',
        'correction_id', correction.id, 'report_id', correction.report_id, 'shot_id', correction.shot_id,
        'target_object_id', correction.target_object_id, 'applied_revision', (applied->>'revision')::integer,
        'confirmed_by_later_report', true)),
      'observed_count', 1,
      'source_object_id', correction.target_object_id,
      'source_revision', (applied->>'revision')::integer));
  end if;
  update tonde.match_corrections c set state = 'applied', applied_revision = (applied->>'revision')::integer,
    applied_version_id = tonde_private.vb_latest_version(target_workspace, correction.target_object_id),
    propagation = jsonb_build_array(jsonb_build_object('counts', analysis->'counts',
      'marked', propagation_result->'marked', 'requiring_review', propagation_result->'requiring_review',
      'locked_skipped', propagation_result->'locked_skipped', 'unresolved_count', propagation_result->'unresolved_count')),
    decided_by = auth.uid(), decided_at = now(), note = left(coalesce(note_text,''), 800)
    where c.id = correction.id returning * into correction;
  return jsonb_build_object('correction_id', correction.id, 'report_id', correction.report_id,
    'shot_id', correction.shot_id, 'state', 'applied', 'target_object_id', correction.target_object_id,
    'target_kind', target_object.kind, 'applied_revision', correction.applied_revision,
    'applied_version_id', correction.applied_version_id,
    'changed_fields', applied->'changed_fields', 'propagation', correction.propagation,
    'candidate', case when record_candidate then candidate else null end,
    'note', 'A new revision was created. The previous plan, the Result and every earlier analysis are preserved; approved content is reported for review rather than rewritten silently.');
end $$;


create or replace function tonde.match_correction_reject(target_workspace uuid, target_production uuid, target_correction uuid,
  note_text text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare correction tonde.match_corrections;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into correction from tonde.match_corrections c where c.workspace_id = target_workspace
    and c.production_id = target_production and c.id = target_correction;
  if not found then raise exception 'That correction is unavailable' using errcode = 'P0002'; end if;
  if correction.state <> 'proposed' then raise exception 'That correction was already decided' using errcode = '23514'; end if;
  update tonde.match_corrections c set state = 'rejected', decided_by = auth.uid(), decided_at = now(),
    note = left(coalesce(note_text,''), 800) where c.id = correction.id returning * into correction;
  return jsonb_build_object('correction_id', correction.id, 'state', 'rejected', 'note',
    'The correction was rejected. Nothing changed and nothing was overwritten.');
end $$;


-- 8. RLS. The correction record is workspace-isolated and read-only to clients: only the guarded
-- RPCs above write it. Reports are already read-only to clients.
alter table tonde.match_corrections enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'match_corrections'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.match_corrections for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.match_corrections to authenticated;


-- 9. Mutation guards: identity stays immutable, revisions auto-bump, nothing is rewritten.
drop trigger if exists guard_mutation on tonde.match_corrections;
create trigger guard_mutation before insert or update on tonde.match_corrections
  for each row execute function tonde_private.guard_mutation();


-- 10. Privileges: authenticated only, and the private helpers stay unreachable.
revoke all on function
  tonde.result_register(uuid,uuid,jsonb),
  tonde.result_list(uuid,uuid,uuid,text,integer,integer),
  tonde.result_detail(uuid,uuid,uuid),
  tonde.result_state_set(uuid,uuid,uuid,text,integer,text),
  tonde.match_analyze(uuid,uuid,uuid,jsonb),
  tonde.match_reports(uuid,uuid,uuid,uuid,integer,integer),
  tonde.match_report_get(uuid,uuid,uuid),
  tonde.match_report_decide(uuid,uuid,uuid,text,text),
  tonde.match_correction_propose(uuid,uuid,uuid,jsonb),
  tonde.match_correction_apply(uuid,uuid,uuid,integer,text,text,boolean),
  tonde.match_correction_reject(uuid,uuid,uuid,text)
  from public, anon, authenticated, service_role;

grant execute on function
  tonde.result_register(uuid,uuid,jsonb),
  tonde.result_list(uuid,uuid,uuid,text,integer,integer),
  tonde.result_detail(uuid,uuid,uuid),
  tonde.result_state_set(uuid,uuid,uuid,text,integer,text),
  tonde.match_analyze(uuid,uuid,uuid,jsonb),
  tonde.match_reports(uuid,uuid,uuid,uuid,integer,integer),
  tonde.match_report_get(uuid,uuid,uuid),
  tonde.match_report_decide(uuid,uuid,uuid,text,text),
  tonde.match_correction_propose(uuid,uuid,uuid,jsonb),
  tonde.match_correction_apply(uuid,uuid,uuid,integer,text,text,boolean),
  tonde.match_correction_reject(uuid,uuid,uuid,text)
  to authenticated;

commit;

-- ==========================================================================
-- 202610050025_prompt7_integrity_readiness.sql
-- ==========================================================================

-- Additive migration: Prompts 1-9 correction pass. Migration 017 is historical source and is
-- not rewritten; this migration repairs the two residual findings it left open.
--
-- 1. Relational integrity for AI plans. `execution_plans.model_profile_id` and
--    `fallback_model_profile_id` were added as bare uuid columns in 017. Only the
--    `save_ai_plan` RPC enforced that the profile belonged to the workspace, so a direct write
--    path could reference a nonexistent profile or another workspace's profile. This adds the
--    tenant-safe composite foreign keys `ai_generation_attempts` already carries, mirroring its
--    deletion behavior (`restrict`): a profile a plan depends on cannot be deleted. Both columns
--    stay nullable; a null profile is valid in either position.
--
-- 2. Redundant readiness computation. `ai_creation_surface` recomputed
--    `ai_readiness_state` once in the scenes lateral, once in the shots list, and three more
--    times in the summary filters (ready / manual_export / blocked) - up to four evaluations per
--    Shot - and `ai_selected_attempt` twice. It now derives each Shot's readiness and selection
--    once and reuses that value everywhere, so a large Production loads in one pass per Shot
--    instead of four. Nothing about a readiness reason, an order or a returned field changes:
--    the document keeps exactly its previous shape.
--
-- Nothing is dropped. No table, column, enum, row, approval, lock or history is altered. RLS and
-- tenant boundaries are untouched: the new foreign keys reinforce them.
begin;


-- 1. Tenant-safe model-profile integrity on execution plans.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.execution_plans') and conname = 'execution_plans_model_profile_fk'
  ) then
    execute $tonde_idem_ddl$alter table tonde.execution_plans
  add constraint execution_plans_model_profile_fk
  foreign key (workspace_id, model_profile_id)
  references tonde.ai_model_profiles(workspace_id, id) on delete restrict$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.execution_plans') and conname = 'execution_plans_fallback_model_profile_fk'
  ) then
    execute $tonde_idem_ddl$alter table tonde.execution_plans
  add constraint execution_plans_fallback_model_profile_fk
  foreign key (workspace_id, fallback_model_profile_id)
  references tonde.ai_model_profiles(workspace_id, id) on delete restrict$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

create index if not exists execution_plans_by_model_profile on tonde.execution_plans(workspace_id, model_profile_id)
  where model_profile_id is not null;

create index if not exists execution_plans_by_fallback_model_profile on tonde.execution_plans(workspace_id, fallback_model_profile_id)
  where fallback_model_profile_id is not null;


-- 2. One readiness evaluation per Shot, reused across the document.
create or replace function tonde.ai_creation_surface(target_workspace uuid, target_production uuid,
  expected_production_revision integer default null)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare prod tonde.productions; result jsonb;
begin
  if auth.uid() is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into prod from tonde.productions where workspace_id = target_workspace and id = target_production;
  if not found then raise exception 'Production unavailable' using errcode = 'P0002'; end if;
  if expected_production_revision is not null and prod.revision <> expected_production_revision then
    raise exception 'The Production changed since you loaded it' using errcode = '40001';
  end if;
  -- Each active Shot's readiness and selected Attempt are computed exactly once here and reused
  -- by the scene rollup, the Shot list and the summary.
  with base as (
    select h.id, h.workspace_id, h.production_id, h.scene_id, h.sort_order, h.title, h.purpose,
      h.execution_method, h.approval, h.locked_at, h.revision, h.planned_duration_ms,
      tonde_private.ai_readiness_state(target_workspace, target_production, h.id) as readiness,
      tonde_private.ai_selected_attempt(target_workspace, h.id) as selected_attempt_id
    from tonde.shots h
    where h.workspace_id = target_workspace and h.production_id = target_production and h.lifecycle = 'active'
  )
  select jsonb_build_object(
    'production', jsonb_build_object('id', prod.id, 'workspace_id', prod.workspace_id, 'title', prod.title,
      'production_type', prod.production_type, 'execution_method', prod.execution_method,
      'planned_duration_ms', prod.planned_duration_ms, 'approval', prod.approval,
      'locked_at', prod.locked_at, 'revision', prod.revision, 'lifecycle', prod.lifecycle),
    'execution_faces', to_jsonb(array['real','ai']),
    'connections', (select coalesce(jsonb_agg(jsonb_build_object(
        'provider_key', p.key, 'label', p.label, 'connection_required', p.connection_required,
        'manual_export_supported', p.manual_export_supported,
        'state', coalesce(c.state, 'not_connected'),
        'credential_reference', coalesce(c.credential_reference, ''),
        'connected_at', c.connected_at)
        order by p.key), '[]'::jsonb)
      from tonde.ai_providers p
      left join tonde.ai_provider_connections c on c.workspace_id = target_workspace and c.provider_key = p.key),
    'models', (select coalesce(jsonb_agg(jsonb_build_object(
        'model_profile_id', m.id, 'provider_key', m.provider_key, 'model_key', m.model_key,
        'label', m.label, 'operation', m.operation, 'capability_state', m.capability_state,
        'availability', m.availability, 'cost_known', m.cost_known, 'cost_unit', m.cost_unit,
        'cost_amount', m.cost_amount, 'cost_currency', m.cost_currency,
        'supports_image_reference', m.supports_image_reference,
        'supports_first_frame', m.supports_first_frame, 'supports_last_frame', m.supports_last_frame,
        'max_duration_ms', m.max_duration_ms, 'source', m.source)
        order by m.provider_key, m.model_key, m.operation), '[]'::jsonb)
      from tonde.ai_model_profiles m
      where m.workspace_id = target_workspace and m.lifecycle = 'active'),
    'known_models', (select coalesce(jsonb_agg(jsonb_build_object(
        'provider_key', m.provider_key, 'model_key', m.model_key, 'operation', m.operation,
        'declared', false, 'capability_state', m.capability_state)
        order by m.provider_key, m.model_key), '[]'::jsonb)
      from tonde.ai_model_profiles m where m.workspace_id is null),
    'locks', tonde_private.ai_locks_document(target_workspace, target_production),
    'scenes', (select coalesce(jsonb_agg(jsonb_build_object(
        'scene_id', s.id, 'order', s.sort_order, 'title', s.title, 'shots', s.shot_count,
        'ready', s.ready, 'blocked', s.blocked, 'unplanned', s.unplanned, 'selected', s.selected)
        order by s.sort_order, s.id), '[]'::jsonb)
      from (select sc.id, sc.sort_order, sc.title,
          count(h.id) as shot_count,
          count(h.id) filter (where h.readiness = 'ready_to_generate') as ready,
          count(h.id) filter (where h.readiness not in ('ready_to_generate','manual_export') and h.execution_method <> 'real') as blocked,
          count(h.id) filter (where h.execution_method in ('ai','hybrid') and h.readiness = 'unplanned') as unplanned,
          count(h.id) filter (where h.selected_attempt_id is not null) as selected
        from tonde.scenes sc
        left join base h on h.scene_id = sc.id
        where sc.workspace_id = target_workspace and sc.production_id = target_production and sc.lifecycle = 'active'
        group by sc.id, sc.sort_order, sc.title) s),
    'shots', (select coalesce(jsonb_agg(jsonb_build_object(
        'shot_id', h.id, 'scene_id', h.scene_id, 'title', h.title, 'purpose', h.purpose,
        'order', h.sort_order, 'execution_method', h.execution_method, 'approval', h.approval,
        'locked', h.locked_at is not null, 'revision', h.revision,
        'planned_duration_ms', h.planned_duration_ms,
        'readiness', h.readiness,
        'plan_id', p.id, 'plan_revision', p.revision, 'plan_status', p.plan_status,
        'prompt_version', p.prompt_version, 'prompt_stale', p.source_shot_revision is not null and p.source_shot_revision <> h.revision,
        'provider_target', p.provider_target, 'model_profile_id', p.model_profile_id,
        'model_label', coalesce(m.label, m.model_key), 'model_key', m.model_key,
        'capability_state', m.capability_state,
        'cost_state', coalesce(p.cost_state, 'unknown'), 'cost_amount', p.cost_amount,
        'cost_currency', p.cost_currency,
        'aspect_ratio', coalesce(nullif(p.aspect_ratio, ''), ''),
        'expected_duration_ms', coalesce(p.expected_duration_ms, h.planned_duration_ms),
        'hybrid', p.hybrid)
        order by h.sort_order, h.id), '[]'::jsonb)
      from base h
      left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
        and p.execution_method = 'ai'
      left join tonde.ai_model_profiles m on m.id = p.model_profile_id),
    'summary', (select jsonb_build_object(
        'shots', count(*),
        'ai_or_hybrid', count(*) filter (where h.execution_method in ('ai','hybrid')),
        'real', count(*) filter (where h.execution_method = 'real'),
        'planned', count(*) filter (where p.id is not null),
        'ready', count(*) filter (where h.readiness = 'ready_to_generate'),
        'manual_export', count(*) filter (where h.readiness = 'manual_export'),
        'blocked', count(*) filter (where h.execution_method in ('ai','hybrid')
          and h.readiness not in ('ready_to_generate','manual_export')),
        'stale', count(*) filter (where p.source_shot_revision is not null and p.source_shot_revision <> h.revision),
        'with_selected_result', count(*) filter (where h.selected_attempt_id is not null),
        'connected_providers', (select count(*) from tonde.ai_provider_connections c
          where c.workspace_id = target_workspace and c.state = 'connected'),
        'declared_models', (select count(*) from tonde.ai_model_profiles m
          where m.workspace_id = target_workspace and m.lifecycle = 'active'))
      from base h
      left join tonde.execution_plans p on p.workspace_id = h.workspace_id and p.shot_id = h.id
        and p.execution_method = 'ai'),
    'capabilities', jsonb_build_object(
      'prompt_compilation', true,
      'model_routing', true,
      'live_generation', exists (select 1 from tonde.ai_provider_connections c
        where c.workspace_id = target_workspace and c.state = 'connected'),
      'manual_export', true,
      'note', 'Provider-neutral. TONDE ranks only the models you have declared, and holds no vendor capability facts of its own.'))
  into result;
  return result;
end $$;

-- The ACLs are re-asserted exactly as migration 017 established them: authenticated only.
revoke all on function tonde.ai_creation_surface(uuid,uuid,integer) from public, anon, authenticated, service_role;

grant execute on function tonde.ai_creation_surface(uuid,uuid,integer) to authenticated;


commit;

-- ==========================================================================
-- 202610050026_pre_prompt10_product_amendment.sql
-- ==========================================================================

-- Additive pre-Prompt 10 product amendment: Production Kit is vocabulary only;
-- References gain separate identity/purpose; timed audiovisual work gains a shared,
-- versioned Audio Plan with distinct Scene Music and Sound Direction.
-- Existing rows and IDs are retained. Legacy References remain honestly incomplete.
begin;


-- Reference Truth is not Creator Intent. source_description keeps its historical meaning.
alter table tonde.production_references
  add column if not exists source_identity text check (source_identity is null or length(btrim(source_identity)) between 1 and 500);
alter table tonde.production_references
  add column if not exists source_provider text check (source_provider is null or length(btrim(source_provider)) <= 160);
alter table tonde.production_references
  add column if not exists identity_provenance text not null default 'unknown'
    check (identity_provenance in ('source_metadata','creator_supplied','inferred','unknown'));
alter table tonde.production_references
  add column if not exists source_identity_verified_at timestamptz;
alter table tonde.production_references
  add column if not exists creator_purpose text check (creator_purpose is null or length(btrim(creator_purpose)) between 1 and 2000);
alter table tonde.production_references
  add column if not exists learning_targets text[] not null default '{}'
    check (cardinality(learning_targets) <= 20);
alter table tonde.production_references
  add column if not exists identity_revision integer not null default 1 check (identity_revision > 0);
alter table tonde.production_references
  add column if not exists revision integer not null default 1 check (revision > 0);


-- The analysis is current only for the exact verified identity/purpose revision it analyzed.
alter table tonde.reference_analyses
  add column if not exists identity_revision integer check (identity_revision is null or identity_revision > 0);

create index if not exists production_references_identity_status
  on tonde.production_references(workspace_id, production_id, identity_provenance)
  where source_identity is not null;

-- Preserve the object registry: add the two new canonical, versioned audio object kinds.
do $tonde_idem$
begin
  if not exists (select 1 from pg_constraint c where c.conrelid=to_regclass('tonde.objects')
        and c.conname='objects_kind_check' and regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(pg_get_constraintdef(c.oid)), 'tonde\.', '', 'g'), '::[a-z_][a-z0-9_.]*', '', 'g'), '[\s()\[\]]', '', 'g'), '''', '', 'g'), '<>allarray', 'notin', 'g'), '=anyarray', 'in', 'g')='checkkindinproject,production,series,collection,act,sequence,scene,shot,asset,reference,creative_document,dialogue_line,execution_plan,result,episode,audio_plan,scene_audio_direction') then
    execute $tonde_idem_ddl$alter table tonde.objects drop constraint if exists objects_kind_check$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.objects') and conname = 'objects_kind_check'
  ) then
    execute $tonde_idem_ddl$alter table tonde.objects add constraint objects_kind_check check (kind in
  ('project','production','series','collection','act','sequence','scene','shot','asset','reference',
   'creative_document','dialogue_line','execution_plan','result','episode','audio_plan','scene_audio_direction'))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;


create table if not exists tonde.production_audio_plans (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null,
  overall_intent text not null default '' check (length(overall_intent) <= 2000),
  dialogue_strategy text not null default '' check (length(dialogue_strategy) <= 1600),
  music_strategy text not null default '' check (length(music_strategy) <= 1600),
  sound_design_strategy text not null default '' check (length(sound_design_strategy) <= 2000),
  ambience_strategy text not null default '' check (length(ambience_strategy) <= 1600),
  recording_considerations text not null default '' check (length(recording_considerations) <= 1600),
  silence_strategy text not null default '' check (length(silence_strategy) <= 1200),
  recurring_motifs text[] not null default '{}',
  continuity_considerations text not null default '' check (length(continuity_considerations) <= 1200),
  delivery_considerations text not null default '' check (length(delivery_considerations) <= 1200),
  intentional_silence boolean not null default false,
  master_song_reference_id uuid,
  master_song_provenance text not null default 'unknown'
    check (master_song_provenance in ('creator_supplied','licensed','original','generated','external_reference','unknown')),
  direction_state text not null default 'needs_direction'
    check (direction_state in ('needs_direction','planned','intentional_silence')),
  approval tonde.approval not null default 'draft', locked_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, production_id, id), unique (production_id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, master_song_reference_id) references tonde.production_references(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, id) references tonde.objects(workspace_id, production_id, id) deferrable initially deferred,
  check ((intentional_silence and direction_state = 'intentional_silence') or
         (not intentional_silence and direction_state <> 'intentional_silence'))
);


create table if not exists tonde.scene_audio_directions (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null, production_id uuid not null, scene_id uuid not null,
  music_use text not null default 'undecided'
    check (music_use in ('undecided','use','intentional_silence','not_applicable')),
  music_direction text not null default '' check (length(music_direction) <= 2000),
  cue_start_ms bigint check (cue_start_ms is null or cue_start_ms >= 0),
  cue_end_ms bigint check (cue_end_ms is null or cue_end_ms >= 0),
  cue_duration_ms bigint check (cue_duration_ms is null or cue_duration_ms >= 0),
  music_purpose text not null default '' check (length(music_purpose) <= 1000),
  rhythmic_quality text not null default '' check (length(rhythmic_quality) <= 500),
  instrumentation text not null default '' check (length(instrumentation) <= 800),
  dynamics text not null default '' check (length(dynamics) <= 800),
  diegetic boolean,
  dialogue_relationship text not null default '' check (length(dialogue_relationship) <= 800),
  action_relationship text not null default '' check (length(action_relationship) <= 800),
  motif_relationship text not null default '' check (length(motif_relationship) <= 800),
  master_song_reference_id uuid,
  sound_use text not null default 'undecided'
    check (sound_use in ('undecided','directed','intentional_silence','not_applicable')),
  sound_direction text not null default '' check (length(sound_direction) <= 2400),
  sound_events text[] not null default '{}',
  recording_needs text not null default '' check (length(recording_needs) <= 1200),
  microphone_considerations text not null default '' check (length(microphone_considerations) <= 800),
  voice_treatment text not null default '' check (length(voice_treatment) <= 800),
  continuity_considerations text not null default '' check (length(continuity_considerations) <= 1000),
  approval tonde.approval not null default 'draft', locked_at timestamptz,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid() references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  unique (workspace_id, id), unique (workspace_id, production_id, id), unique (scene_id),
  foreign key (workspace_id, production_id, scene_id) references tonde.scenes(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, master_song_reference_id) references tonde.production_references(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, id) references tonde.objects(workspace_id, production_id, id) deferrable initially deferred,
  check (cue_start_ms is null or cue_end_ms is null or cue_end_ms >= cue_start_ms),
  check (cue_duration_ms is null or (cue_start_ms is not null and cue_end_ms is not null and cue_duration_ms = cue_end_ms - cue_start_ms)),
  check (music_use <> 'use' or length(btrim(music_direction)) > 0),
  check (sound_use <> 'directed' or length(btrim(sound_direction)) > 0)
);

create index if not exists scene_audio_directions_timeline on tonde.scene_audio_directions(workspace_id, production_id, scene_id);


-- A legacy or newly captured Reference is usable for shaping only when its identity has
-- an honest source and provenance and the creator separately states why it matters.
create or replace function tonde_private.reference_shaping_ready(target_workspace uuid, target_reference uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from tonde.production_references r
    where r.workspace_id = target_workspace and r.id = target_reference
      and nullif(btrim(r.source_identity), '') is not null
      and r.identity_provenance in ('source_metadata','creator_supplied')
      and r.source_identity_verified_at is not null
      and nullif(btrim(r.creator_purpose), '') is not null)
$$;

revoke all on function tonde_private.reference_shaping_ready(uuid,uuid) from public, anon, authenticated, service_role;


create or replace function tonde_private.validate_reference_identity_insert() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.identity_provenance <> 'unknown' or new.source_identity_verified_at is not null then
    raise exception 'Reference identity can only be verified by the scoped creator-attestation action' using errcode='23514';
  end if;
  return new;
end $$;

revoke all on function tonde_private.validate_reference_identity_insert() from public,anon,authenticated,service_role;

drop trigger if exists validate_reference_identity_insert on tonde.production_references;
create trigger validate_reference_identity_insert before insert on tonde.production_references
  for each row execute function tonde_private.validate_reference_identity_insert();


create or replace function tonde_private.require_reference_shaping_ready() returns trigger
language plpgsql security definer set search_path = '' as $$
declare ref_id uuid; ref_production uuid; target_production uuid; target_kind text;
begin
  if tg_table_name = 'scope_bindings' then
    if tg_op = 'UPDATE' and new.reference_id is null then return new; end if;
    ref_id := new.reference_id;
    if ref_id is null then return new; end if;
    select o.production_id,o.kind into target_production,target_kind from tonde.objects o
      where o.workspace_id=new.workspace_id and o.id=new.scope_object_id;
    if target_kind = 'production' then target_production := new.scope_object_id; end if;
  elsif tg_table_name = 'object_dependencies' then
    if not new.active then return new; end if;
    select o.id into ref_id from tonde.objects o
      where o.workspace_id=new.workspace_id and o.id=new.source_object_id and o.kind='reference';
    if ref_id is null then return new; end if;
    select o.production_id,o.kind into target_production,target_kind from tonde.objects o
      where o.workspace_id=new.workspace_id and o.id=new.target_object_id;
    if target_kind = 'production' then target_production := new.target_object_id; end if;
  elsif tg_table_name = 'reference_analyses' then
    ref_id := new.reference_id;
    target_production := new.production_id;
  end if;
  if ref_id is not null then
    if tg_table_name = 'scope_bindings' and new.production_id is distinct from target_production then
      raise exception 'Reference binding must target its owning Production' using errcode='23514';
    end if;
    select r.production_id into ref_production from tonde.production_references r
      where r.workspace_id=new.workspace_id and r.id=ref_id;
    if ref_production is null or target_production is null or target_production is distinct from ref_production then
      raise exception 'Reference shaping target must belong to the Reference Production' using errcode='23514';
    end if;
    if not tonde_private.reference_shaping_ready(new.workspace_id,ref_id) then
      raise exception 'Complete the Reference identity and creator purpose before using it to shape a Production' using errcode='23514';
    end if;
  end if;
  return new;
end $$;

drop trigger if exists require_reference_identity_before_scope_binding on tonde.scope_bindings;
create trigger require_reference_identity_before_scope_binding before insert or update on tonde.scope_bindings
  for each row execute function tonde_private.require_reference_shaping_ready();

drop trigger if exists require_reference_identity_before_dependency on tonde.object_dependencies;
create trigger require_reference_identity_before_dependency before insert or update on tonde.object_dependencies
  for each row execute function tonde_private.require_reference_shaping_ready();

drop trigger if exists require_reference_identity_before_analysis on tonde.reference_analyses;
create trigger require_reference_identity_before_analysis before insert or update on tonde.reference_analyses
  for each row execute function tonde_private.require_reference_shaping_ready();


create or replace function tonde_private.bind_reference_analysis_identity_revision() returns trigger
language plpgsql security definer set search_path = '' as $$
declare current_identity_revision integer; pinned_identity_revision integer;
begin
  select r.identity_revision into current_identity_revision from tonde.production_references r
    where r.workspace_id=new.workspace_id and r.production_id=new.production_id and r.id=new.reference_id;
  if current_identity_revision is null then
    raise exception 'Reference identity revision is unavailable for this analysis' using errcode='P0002';
  end if;
  if tg_op = 'INSERT' then
    select a.identity_revision into pinned_identity_revision from tonde.reference_analyses a
      where a.workspace_id=new.workspace_id and a.reference_id=new.reference_id;
    if new.identity_revision is not null then
      pinned_identity_revision := new.identity_revision;
    elsif pinned_identity_revision is null then
      pinned_identity_revision := current_identity_revision;
    end if;
    new.identity_revision := pinned_identity_revision;
  end if;
  if new.identity_revision is null or new.identity_revision is distinct from current_identity_revision then
    raise exception 'Reference identity changed while this analysis was running' using errcode='40001';
  end if;
  if new.analyzed_at is not null and new.identity_revision is null then
    raise exception 'Analysis must be claimed against a verified Reference identity before completion' using errcode='23514';
  end if;
  return new;
end $$;

revoke all on function tonde_private.bind_reference_analysis_identity_revision() from public,anon,authenticated,service_role;

drop trigger if exists bind_reference_analysis_identity_revision on tonde.reference_analyses;
create trigger bind_reference_analysis_identity_revision before insert or update on tonde.reference_analyses
  for each row execute function tonde_private.bind_reference_analysis_identity_revision();


-- The first claim pins identity_revision. Later progress writes preserve that pin, and
-- save_reference_analysis can complete only if the Reference identity has not changed.
create or replace function tonde.claim_reference_analysis_pinned(
  target_workspace uuid, target_production uuid, target_reference uuid, expected_identity_revision integer,
  stage_status text, stage_list text[] default '{}', progress_pct integer default 0, producer_note text default ''
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.reference_analyses; reference_row tonde.production_references;
begin
  perform tonde_private.director_guard(target_workspace);
  if stage_status not in ('queued','preprocessing') then
    raise exception 'A pinned analysis claim must begin at queued or preprocessing' using errcode='22023';
  end if;
  select * into reference_row from tonde.production_references
    where workspace_id=target_workspace and production_id=target_production and id=target_reference for update;
  if not found then raise exception 'Reference unavailable in this Production' using errcode='P0002'; end if;
  if expected_identity_revision is null or reference_row.identity_revision <> expected_identity_revision then
    raise exception 'Reference identity changed before analysis began; reload and verify it again' using errcode='40001';
  end if;
  insert into tonde.reference_analyses as ra (workspace_id,production_id,reference_id,status,stages,progress,producer_note,identity_revision,analyzed_at)
  values (target_workspace,target_production,target_reference,stage_status,coalesce(stage_list,'{}'),
    greatest(0,least(100,coalesce(progress_pct,0))),left(coalesce(producer_note,''),600),reference_row.identity_revision,null)
  on conflict (workspace_id,reference_id) do update set
    status=excluded.status,stages=excluded.stages,progress=excluded.progress,
    producer_note=case when excluded.producer_note='' then ra.producer_note else excluded.producer_note end,
    identity_revision=excluded.identity_revision,analyzed_at=null
  returning * into saved;
  update tonde.production_references set state='processing'::tonde.reference_state
    where workspace_id=target_workspace and production_id=target_production and id=target_reference;
  return jsonb_build_object('analysis_id',saved.id,'identity_revision',saved.identity_revision,'status',saved.status,
    'progress',saved.progress,'stages',saved.stages);
end $$;

revoke all on function tonde.claim_reference_analysis_pinned(uuid,uuid,uuid,integer,text,text[],integer,text) from public,anon,authenticated,service_role;

grant execute on function tonde.claim_reference_analysis_pinned(uuid,uuid,uuid,integer,text,text[],integer,text) to authenticated;


create or replace function tonde.claim_reference_analysis(
  target_workspace uuid, target_production uuid, target_reference uuid, stage_status text,
  stage_list text[] default '{}', progress_pct integer default 0, producer_note text default ''
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare saved tonde.reference_analyses; reference_state text;
begin
  perform tonde_private.director_guard(target_workspace);
  if stage_status not in ('queued','preprocessing','analyzing','synthesizing','partial','failed','cancelled') then
    raise exception 'Unsupported analysis stage status' using errcode='22023';
  end if;
  if not exists(select 1 from tonde.production_references where workspace_id=target_workspace
    and production_id=target_production and id=target_reference) then
    raise exception 'Reference unavailable in this Production' using errcode='P0002';
  end if;
  insert into tonde.reference_analyses as ra (workspace_id,production_id,reference_id,status,stages,progress,producer_note)
  values (target_workspace,target_production,target_reference,stage_status,coalesce(stage_list,'{}'),
    greatest(0,least(100,coalesce(progress_pct,0))),left(coalesce(producer_note,''),600))
  on conflict (workspace_id,reference_id) do update set
    status=excluded.status,stages=excluded.stages,progress=excluded.progress,
    producer_note=case when excluded.producer_note='' then ra.producer_note else excluded.producer_note end
  returning * into saved;
  reference_state := case stage_status when 'failed' then 'failed' when 'partial' then 'partially_analyzed' else 'processing' end;
  update tonde.production_references set state=reference_state::tonde.reference_state where id=target_reference and workspace_id=target_workspace;
  return jsonb_build_object('analysis_id',saved.id,'identity_revision',saved.identity_revision,
    'status',saved.status,'progress',saved.progress,'stages',saved.stages);
end $$;

revoke all on function tonde.claim_reference_analysis(uuid,uuid,uuid,text,text[],integer,text) from public,anon,authenticated,service_role;

grant execute on function tonde.claim_reference_analysis(uuid,uuid,uuid,text,text[],integer,text) to authenticated;

create or replace function tonde_private.validate_reference_analysis_identity_pin() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.analyzed_at is not null and (old.analyzed_at is null or new.identity_revision is distinct from old.identity_revision) then
    if new.identity_revision is null then
      raise exception 'Analysis must be claimed against a verified Reference identity before completion' using errcode='23514';
    end if;
  end if;
  return new;
end $$;

revoke all on function tonde_private.validate_reference_analysis_identity_pin() from public,anon,authenticated,service_role;

drop trigger if exists require_reference_analysis_identity_pin on tonde.reference_analyses;
create trigger require_reference_analysis_identity_pin before update on tonde.reference_analyses
  for each row execute function tonde_private.validate_reference_analysis_identity_pin();


create or replace function tonde_private.advance_reference_identity_revision() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (new.source_identity,new.source_provider,new.identity_provenance,new.source_identity_verified_at,new.creator_purpose,new.learning_targets)
    is distinct from
     (old.source_identity,old.source_provider,old.identity_provenance,old.source_identity_verified_at,old.creator_purpose,old.learning_targets) then
    new.identity_revision := old.identity_revision+1;
  else
    new.identity_revision := old.identity_revision;
  end if;
  return new;
end $$;

revoke all on function tonde_private.advance_reference_identity_revision() from public,anon,authenticated,service_role;

drop trigger if exists advance_reference_identity_revision on tonde.production_references;
create trigger advance_reference_identity_revision before update on tonde.production_references
  for each row execute function tonde_private.advance_reference_identity_revision();


create or replace function tonde_private.prevent_reference_shaping_downgrade() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if (nullif(btrim(new.source_identity), '') is null
      or new.identity_provenance not in ('source_metadata','creator_supplied')
      or new.source_identity_verified_at is null
      or nullif(btrim(new.creator_purpose), '') is null)
     and ((exists(select 1 from tonde.scope_bindings b where b.workspace_id=new.workspace_id and b.reference_id=new.id)
       or exists(select 1 from tonde.object_dependencies d where d.workspace_id=new.workspace_id and d.source_object_id=new.id and d.active)
       or exists(select 1 from tonde.reference_analyses a where a.workspace_id=new.workspace_id and a.reference_id=new.id)
       or exists(select 1 from tonde.reference_technique_links l where l.workspace_id=new.workspace_id and l.reference_id=new.id))) then
    raise exception 'A Reference already used for analysis or Production-shaping must retain verified identity and creator purpose' using errcode='23514';
  end if;
  return new;
end $$;

revoke all on function tonde_private.prevent_reference_shaping_downgrade() from public,anon,authenticated,service_role;

drop trigger if exists prevent_reference_shaping_downgrade on tonde.production_references;
create trigger prevent_reference_shaping_downgrade before update of source_identity,identity_provenance,source_identity_verified_at,creator_purpose
  on tonde.production_references for each row execute function tonde_private.prevent_reference_shaping_downgrade();


create or replace function tonde_private.validate_audio_reference() returns trigger
language plpgsql security definer set search_path = '' as $$
declare reference_production uuid;
begin
  if tg_table_name = 'production_audio_plans' then
    if not exists(select 1 from tonde.productions p where p.workspace_id=new.workspace_id and p.id=new.production_id
      and tonde_private.audio_applies(p.production_type,p.planned_duration_ms)) then
      raise exception 'Audio Plan is available only for relevant timed audiovisual Productions' using errcode='23514';
    end if;
    if new.master_song_reference_id is not null then
      select production_id into reference_production from tonde.production_references
        where workspace_id = new.workspace_id and id = new.master_song_reference_id;
      if reference_production is distinct from new.production_id then
        raise exception 'Master song Reference belongs to another Production' using errcode = '23514';
      end if;
      if not tonde_private.reference_shaping_ready(new.workspace_id, new.master_song_reference_id) then
        raise exception 'Complete the master song Reference identity and creator purpose before mapping it' using errcode = '23514';
      end if;
      if new.master_song_provenance not in ('creator_supplied','licensed','external_reference','unknown') then
        raise exception 'A linked Reference must retain supplied, licensed, external, or unknown audio provenance' using errcode = '23514';
      end if;
    end if;
    if new.intentional_silence then new.direction_state := 'intentional_silence';
    elsif length(btrim(new.overall_intent)) > 0 or length(btrim(new.dialogue_strategy)) > 0
      or length(btrim(new.music_strategy)) > 0 or length(btrim(new.sound_design_strategy)) > 0
      or length(btrim(new.ambience_strategy)) > 0 or length(btrim(new.silence_strategy)) > 0
      then new.direction_state := 'planned';
    else new.direction_state := 'needs_direction'; end if;
  else
    if not exists(select 1 from tonde.productions p where p.workspace_id=new.workspace_id and p.id=new.production_id
      and tonde_private.audio_applies(p.production_type,p.planned_duration_ms))
      or not exists(select 1 from tonde.production_audio_plans p where p.workspace_id=new.workspace_id and p.production_id=new.production_id) then
      raise exception 'Scene audio direction requires an applicable Production Audio Plan' using errcode='23514';
    end if;
    if new.master_song_reference_id is not null then
    select production_id into reference_production from tonde.production_references
      where workspace_id = new.workspace_id and id = new.master_song_reference_id;
    if reference_production is distinct from new.production_id then
      raise exception 'Music Reference belongs to another Production' using errcode = '23514';
    end if;
    if not tonde_private.reference_shaping_ready(new.workspace_id, new.master_song_reference_id) then
      raise exception 'Complete the music Reference identity and creator purpose before mapping it' using errcode = '23514';
    end if;
    if not exists(select 1 from tonde.production_audio_plans p where p.workspace_id=new.workspace_id and p.production_id=new.production_id
      and p.master_song_reference_id=new.master_song_reference_id) then
      raise exception 'Scene Music Direction must use the master song Reference declared by this Audio Plan' using errcode = '23514';
    end if;
    end if;
  end if;
  return new;
end $$;

revoke all on function tonde_private.validate_audio_reference() from public, anon, authenticated, service_role;

drop trigger if exists validate_audio_plan_reference on tonde.production_audio_plans;
create trigger validate_audio_plan_reference before insert or update on tonde.production_audio_plans
  for each row execute function tonde_private.validate_audio_reference();

drop trigger if exists validate_scene_audio_reference on tonde.scene_audio_directions;
create trigger validate_scene_audio_reference before insert or update on tonde.scene_audio_directions
  for each row execute function tonde_private.validate_audio_reference();


-- Update the shared object registry and history triggers, not a parallel subsystem.
do $$ begin
  drop trigger if exists a_register_object on tonde.production_audio_plans;
  create trigger a_register_object after insert on tonde.production_audio_plans
    for each row execute function tonde_private.register_object('audio_plan');
  drop trigger if exists b_capture_revision on tonde.production_audio_plans;
  create trigger b_capture_revision after insert or update on tonde.production_audio_plans
    for each row execute function tonde_private.capture_revision();
  drop trigger if exists a_register_object on tonde.scene_audio_directions;
  create trigger a_register_object after insert on tonde.scene_audio_directions
    for each row execute function tonde_private.register_object('scene_audio_direction');
  drop trigger if exists b_capture_revision on tonde.scene_audio_directions;
  create trigger b_capture_revision after insert or update on tonde.scene_audio_directions
    for each row execute function tonde_private.capture_revision();
  drop trigger if exists guard_mutation on tonde.production_audio_plans;
  create trigger guard_mutation before insert or update on tonde.production_audio_plans
    for each row execute function tonde_private.guard_mutation();
  drop trigger if exists guard_mutation on tonde.scene_audio_directions;
  create trigger guard_mutation before insert or update on tonde.scene_audio_directions
    for each row execute function tonde_private.guard_mutation();
  drop trigger if exists a_human_acceptance on tonde.production_audio_plans;
  create trigger a_human_acceptance before insert or update on tonde.production_audio_plans
    for each row execute function tonde_private.guard_human_acceptance();
  drop trigger if exists a_human_acceptance on tonde.scene_audio_directions;
  create trigger a_human_acceptance before insert or update on tonde.scene_audio_directions
    for each row execute function tonde_private.guard_human_acceptance();
end $$;


-- Approval, lock, version comparison and impact helpers recognize the new canonical objects.
create or replace function tonde_private.pi_label(target_workspace uuid, target_object uuid) returns text
language plpgsql stable security definer set search_path = '' as $$
declare kind text; label text;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id=target_workspace and o.id=target_object;
  if kind is null then return null; end if;
  case kind
    when 'production' then select title into label from tonde.productions where workspace_id=target_workspace and id=target_object;
    when 'act' then select title into label from tonde.acts where workspace_id=target_workspace and id=target_object;
    when 'sequence' then select title into label from tonde.sequences where workspace_id=target_workspace and id=target_object;
    when 'scene' then select title into label from tonde.scenes where workspace_id=target_workspace and id=target_object;
    when 'shot' then select title into label from tonde.shots where workspace_id=target_workspace and id=target_object;
    when 'asset' then select name into label from tonde.assets where workspace_id=target_workspace and id=target_object;
    when 'reference' then select coalesce(nullif(source_identity,''),source_url,'Reference') into label from tonde.production_references where workspace_id=target_workspace and id=target_object;
    when 'execution_plan' then select case when execution_method='ai' then 'AI plan' else 'Real plan' end into label from tonde.execution_plans where workspace_id=target_workspace and id=target_object;
    when 'creative_document' then select coalesce(nullif(title,''),'Document') into label from tonde.creative_documents where workspace_id=target_workspace and id=target_object;
    when 'dialogue_line' then select left(coalesce(content,''),60) into label from tonde.dialogue_lines where workspace_id=target_workspace and id=target_object;
    when 'result' then label := 'Result';
    when 'episode' then select title into label from tonde.series_episodes where workspace_id=target_workspace and id=target_object;
    when 'series' then select title into label from tonde.series where workspace_id=target_workspace and id=target_object;
    when 'project' then select title into label from tonde.projects where workspace_id=target_workspace and id=target_object;
    when 'audio_plan' then label := 'Audio Plan';
    when 'scene_audio_direction' then select 'Scene audio direction' into label from tonde.scene_audio_directions where workspace_id=target_workspace and id=target_object;
    else label := kind;
  end case;
  return coalesce(nullif(btrim(coalesce(label,'')),''),kind);
end $$;


create or replace function tonde_private.pi_object_revision(target_workspace uuid, target_object uuid) returns integer
language plpgsql stable security definer set search_path = '' as $$
declare kind text; value integer;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id=target_workspace and o.id=target_object;
  case kind
    when 'production' then select revision into value from tonde.productions where workspace_id=target_workspace and id=target_object;
    when 'act' then select revision into value from tonde.acts where workspace_id=target_workspace and id=target_object;
    when 'sequence' then select revision into value from tonde.sequences where workspace_id=target_workspace and id=target_object;
    when 'scene' then select revision into value from tonde.scenes where workspace_id=target_workspace and id=target_object;
    when 'shot' then select revision into value from tonde.shots where workspace_id=target_workspace and id=target_object;
    when 'asset' then select revision into value from tonde.assets where workspace_id=target_workspace and id=target_object;
    when 'reference' then select revision into value from tonde.production_references where workspace_id=target_workspace and id=target_object;
    when 'execution_plan' then select revision into value from tonde.execution_plans where workspace_id=target_workspace and id=target_object;
    when 'creative_document' then select revision into value from tonde.creative_documents where workspace_id=target_workspace and id=target_object;
    when 'dialogue_line' then select revision into value from tonde.dialogue_lines where workspace_id=target_workspace and id=target_object;
    when 'result' then select revision into value from tonde.results where workspace_id=target_workspace and id=target_object;
    when 'episode' then select revision into value from tonde.series_episodes where workspace_id=target_workspace and id=target_object;
    when 'series' then select revision into value from tonde.series where workspace_id=target_workspace and id=target_object;
    when 'audio_plan' then select revision into value from tonde.production_audio_plans where workspace_id=target_workspace and id=target_object;
    when 'scene_audio_direction' then select revision into value from tonde.scene_audio_directions where workspace_id=target_workspace and id=target_object;
    else value := null;
  end case;
  return value;
end $$;


create or replace function tonde_private.pi_is_locked(target_workspace uuid, target_object uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare kind text; locked boolean := false; parent_id uuid; scene_ref uuid; sequence_ref uuid; act_ref uuid;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id=target_workspace and o.id=target_object;
  case kind
    when 'production' then select locked_at is not null into locked from tonde.productions where workspace_id=target_workspace and id=target_object;
    when 'act' then select locked_at is not null into locked from tonde.acts where workspace_id=target_workspace and id=target_object;
    when 'sequence' then
      select locked_at is not null,act_id into locked,act_ref from tonde.sequences where workspace_id=target_workspace and id=target_object;
      if not locked and act_ref is not null then locked := tonde_private.pi_is_locked(target_workspace,act_ref); end if;
    when 'scene' then
      select locked_at is not null,sequence_id,production_id into locked,sequence_ref,parent_id from tonde.scenes where workspace_id=target_workspace and id=target_object;
      if not locked and sequence_ref is not null then locked := tonde_private.pi_is_locked(target_workspace,sequence_ref); end if;
      if not locked and parent_id is not null then locked := tonde_private.pi_is_locked(target_workspace,parent_id); end if;
    when 'shot' then
      select locked_at is not null,scene_id into locked,scene_ref from tonde.shots where workspace_id=target_workspace and id=target_object;
      if not locked and scene_ref is not null then locked := tonde_private.pi_is_locked(target_workspace,scene_ref); end if;
    when 'asset' then select locked_at is not null into locked from tonde.assets where workspace_id=target_workspace and id=target_object;
    when 'reference' then locked := false;
    -- A derived artifact is locked only by its own lock. It must never inherit the lock of the
    -- object it was derived from: impact propagation has to be able to MARK a locked source's
    -- artifact stale and report it, instead of silently skipping it and hiding real staleness.
    -- Enclosing-scope locks still reach a Shot through its Scene, and an Audio Plan through its
    -- Production, because those are scopes the object lives inside rather than sources it derives from.
    when 'execution_plan' then select locked_at is not null into locked from tonde.execution_plans where workspace_id=target_workspace and id=target_object;
    when 'creative_document' then select locked_at is not null into locked from tonde.creative_documents where workspace_id=target_workspace and id=target_object;
    when 'dialogue_line' then select locked_at is not null into locked from tonde.dialogue_lines where workspace_id=target_workspace and id=target_object;
    when 'result' then select locked_at is not null into locked from tonde.results where workspace_id=target_workspace and id=target_object;
    when 'audio_plan' then select locked_at is not null,production_id into locked,parent_id from tonde.production_audio_plans where workspace_id=target_workspace and id=target_object;
    when 'scene_audio_direction' then
      select locked_at is not null,scene_id into locked,scene_ref from tonde.scene_audio_directions where workspace_id=target_workspace and id=target_object;
      if not locked and scene_ref is not null then locked := tonde_private.pi_is_locked(target_workspace,scene_ref); end if;
    else locked := false;
  end case;
  if not locked and parent_id is not null then locked := tonde_private.pi_is_locked(target_workspace,parent_id); end if;
  if not locked and kind='scene_audio_direction' and scene_ref is not null then
    select sequence_id,production_id into sequence_ref,parent_id from tonde.scenes where workspace_id=target_workspace and id=scene_ref;
    if sequence_ref is not null then locked := tonde_private.pi_is_locked(target_workspace,sequence_ref); end if;
    if not locked and parent_id is not null then locked := tonde_private.pi_is_locked(target_workspace,parent_id); end if;
  end if;
  return coalesce(locked,false);
end $$;


create or replace function tonde_private.pi_is_approved(target_workspace uuid, target_object uuid) returns boolean
language plpgsql stable security definer set search_path = '' as $$
declare kind text; status text;
begin
  select o.kind into kind from tonde.objects o where o.workspace_id=target_workspace and o.id=target_object;
  case kind
    when 'production' then select approval::text into status from tonde.productions where workspace_id=target_workspace and id=target_object;
    when 'act' then select approval::text into status from tonde.acts where workspace_id=target_workspace and id=target_object;
    when 'sequence' then select approval::text into status from tonde.sequences where workspace_id=target_workspace and id=target_object;
    when 'scene' then select approval::text into status from tonde.scenes where workspace_id=target_workspace and id=target_object;
    when 'shot' then select approval::text into status from tonde.shots where workspace_id=target_workspace and id=target_object;
    when 'asset' then select approval::text into status from tonde.assets where workspace_id=target_workspace and id=target_object;
    when 'execution_plan' then select approval::text into status from tonde.execution_plans where workspace_id=target_workspace and id=target_object;
    when 'creative_document' then select approval::text into status from tonde.creative_documents where workspace_id=target_workspace and id=target_object;
    when 'dialogue_line' then select approval::text into status from tonde.dialogue_lines where workspace_id=target_workspace and id=target_object;
    when 'result' then select approval::text into status from tonde.results where workspace_id=target_workspace and id=target_object;
    when 'audio_plan' then select approval::text into status from tonde.production_audio_plans where workspace_id=target_workspace and id=target_object;
    when 'scene_audio_direction' then select approval::text into status from tonde.scene_audio_directions where workspace_id=target_workspace and id=target_object;
    else status := null;
  end case;
  return status in ('approved','changed_after_approval');
end $$;


