-- ==========================================================================
-- 202610050035_prompt10_reconcile_guard_order.sql
-- ==========================================================================

-- 035 - publication_reconcile must decide authorization before it looks the row up.
--
-- Migration 032 defined tonde.publication_reconcile with the publication lookup first and the
-- workspace authorization second. A caller who is not a member of the target workspace therefore
-- received 'That publication does not exist in this workspace' (SQLSTATE P0002) instead of the
-- documented cross-tenant denial 42501, and PostgREST reports an unmapped P0002 as HTTP 500 - a
-- server error for what is a deterministic authorization answer, and an existence signal to a
-- caller who has no business knowing whether the row exists.
--
-- The expanded hosted acceptance runner caught exactly that after the Prompt 10 rollout:
--   FAIL cross-tenant RPC publication_reconcile denied HTTP 500 P0002
-- every other guarded TONDE function raises 42501 before it touches a tenant row, and this one now
-- does the same.
--
-- The repair is forward-only: 032 is an applied migration and is never rewritten. This file
-- re-defines the function with identical behavior, messages, security mode, search_path and ACLs;
-- only the order of the authorization decision changes. It is a targeted replace of one function,
-- not a replay of 032.

create or replace function tonde.publication_reconcile(target_workspace uuid, target_publication uuid, target_observed text,
  target_remote_resource_id text default null, target_remote_state text default '',
  target_failure_category text default null, note_text text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare publication tonde.publications; observed_state tonde.publication_state;
  source_value tonde.publication_reconciliation_source; allowed text[];
begin
  -- Authorization first: a non-member is refused as a denial and is never told whether the row
  -- exists. Everything below this block is unchanged from migration 032.
  if (select auth.role()) = 'service_role' then
    source_value := 'provider_api';
  else
    if auth.uid() is null or not tonde_private.can_edit_workspace(target_workspace) then
      raise exception 'Workspace access denied' using errcode = '42501';
    end if;
    source_value := 'manual_operator';
  end if;
  select * into publication from tonde.publications p
    where p.workspace_id = target_workspace and p.id = target_publication for update;
  if not found then raise exception 'That publication does not exist in this workspace' using errcode = 'P0002'; end if;
  if target_observed not in ('published','processing','removed','failed','unknown_remote_state') then
    raise exception 'A reconciliation observes published, processing, removed, failed or unknown_remote_state'
      using errcode = '22023';
  end if;
  allowed := case target_observed
    when 'published' then array['submitting','submitted','processing','published','unknown_remote_state']
    when 'processing' then array['submitting','submitted','unknown_remote_state']
    when 'failed' then array['submitting','submitted','processing','unknown_remote_state']
    when 'removed' then array['submitted','processing','published','unknown_remote_state']
    else array['submitting','submitted','processing','unknown_remote_state'] end;
  if not (publication.state::text = any(allowed)) then
    raise exception 'A publication in % cannot be reconciled to %', publication.state, target_observed
      using errcode = 'PT409';
  end if;
  if target_observed = 'published'
    and coalesce(btrim(target_remote_resource_id), publication.remote_resource_id) is null then
    raise exception 'A reconciliation to published records the remote resource it found' using errcode = '23514';
  end if;
  if target_observed = 'failed' and target_failure_category is null then
    target_failure_category := 'unknown';
  end if;
  observed_state := target_observed::tonde.publication_state;
  insert into tonde.publication_reconciliations(workspace_id, production_id, publication_id, observed_state,
    remote_state, remote_resource_id, source, note, actor_user_id)
  values (target_workspace, publication.production_id, target_publication, observed_state,
    left(coalesce(target_remote_state, ''), 200), nullif(btrim(target_remote_resource_id), ''), source_value,
    left(coalesce(note_text, ''), 800), auth.uid());
  update tonde.publications set state = observed_state,
    remote_resource_id = coalesce(nullif(btrim(target_remote_resource_id), ''), remote_resource_id),
    remote_state = left(coalesce(nullif(target_remote_state, ''), remote_state), 200),
    last_checked_at = now(),
    published_at = case when target_observed = 'published' then coalesce(published_at, now()) else published_at end,
    removed_at = case when target_observed = 'removed' then now() else removed_at end,
    failed_at = case when target_observed = 'failed' then now() end,
    failure_category = case when target_observed = 'failed'
      then target_failure_category::tonde.publication_failure_category end,
    failure_code = case when target_observed = 'failed' then null end,
    failure_message = case when target_observed = 'failed' then null end
  where workspace_id = target_workspace and id = target_publication;
  perform tonde_private.audit_event(target_workspace, 'publication.reconciled', target_publication, 'publication',
    jsonb_build_object('observed', target_observed, 'source', source_value,
      'remote_resource_id', coalesce(nullif(btrim(target_remote_resource_id), ''), publication.remote_resource_id)));
  return jsonb_build_object('publication_id', target_publication, 'previous_state', publication.state,
    'state', target_observed, 'source', source_value, 'remote_resource_id',
    coalesce(nullif(btrim(target_remote_resource_id), ''), publication.remote_resource_id),
    'remote_state', left(coalesce(nullif(target_remote_state, ''), publication.remote_state), 200),
    'failure_category', case when target_observed = 'failed' then target_failure_category end,
    'observed_at', now(), 'note', left(coalesce(note_text, ''), 800),
    'meaning', case target_observed
      when 'published' then 'The destination really holds this publication; published_at is when TONDE established it.'
      when 'processing' then 'The destination is still working on it.'
      when 'removed' then 'The destination no longer holds this publication.'
      when 'failed' then 'The destination has no usable copy and the cause is recorded.'
      else 'The destination state is still unconfirmed; nothing was claimed.' end);
end $$;


-- ACLs re-asserted exactly as 032 established them.
revoke all on function tonde.publication_reconcile(uuid,uuid,text,text,text,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.publication_reconcile(uuid,uuid,text,text,text,text,text)
  to authenticated, service_role;

-- ==========================================================================
-- 202610050036_prompt11_durable_jobs.sql
-- ==========================================================================

-- Prompt 11 packet 036 — the durable job platform.
--
-- Prompts 1–10 already created the persistence foundation this extends and never replaces:
-- `tonde.jobs` from migration 001 (`job_state`, `progress`, `attempts`/`max_attempts`,
-- `available_at`, `lease_owner`/`lease_expires_at`, `input_object_id`/`output_object_id`,
-- `input_metadata`, `requested_by`), the six lease/completion checks added by 005, the widened
-- `jobs_job_type_check` from 018, and the export job written inside the export transaction by 033.
-- This file adds capability to that one canonical job surface. It does not add a second job table.
--
-- Laws enforced here, not merely described:
--   * One job row is one durable request. Enqueue is idempotent by
--     (workspace, job_type, idempotency_key); the same key returns the existing job.
--   * A domain change that requires asynchronous work records the work in the SAME transaction:
--     directly (export_request already does this) and, for event-driven flows, through the outbox,
--     whose emission is a trigger on the domain row. State and work request cannot diverge.
--   * Claiming is atomic: one statement with FOR UPDATE SKIP LOCKED. Two workers cannot own one job,
--     and an unexpired lease cannot be taken away.
--   * Only the lease owner may start, heartbeat, complete, fail or release a job. Heartbeat fails
--     when the lease expired, the job was cancelled, or another worker now owns it.
--   * Retry is classification-aware. The effective classification is the more conservative of the
--     job type's declared policy and the one the worker reports; it is never silently relaxed.
--   * Completion is idempotent: a duplicate completion of a finished job changes nothing and says so.
--     Retry-exhausted and non-retryable work lands in DEAD_LETTER with its error, attempts, timestamps
--     and reconciliation status preserved.
--   * Job state moves only through the validated transition matrix
--     (tonde_private.job_transition_allowed); every state write in this file asserts it.
--   * Claiming is server authority only. A worker executes previously authorized operations and can
--     never manufacture a creator decision; a client session can read its workspace state and request
--     cancellation, nothing more.
--
-- Transactions are split deliberately: PostgreSQL cannot *use* an enum label in the same transaction
-- that adds it, so the new labels commit first and everything that compares against them runs
-- afterwards. This is also what keeps the single-file artifact (which re-emits statements with
-- existence guards) valid on a fresh database.
begin;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_enum e
    join pg_type t on t.oid = e.enumtypid
    where t.typnamespace = (select oid from pg_namespace where nspname = 'tonde')
      and t.typname = 'job_state'
      and e.enumlabel = 'leased'
  ) then
    execute $tonde_idem_ddl$alter type tonde.job_state add value 'leased'$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_enum e
    join pg_type t on t.oid = e.enumtypid
    where t.typnamespace = (select oid from pg_namespace where nspname = 'tonde')
      and t.typname = 'job_state'
      and e.enumlabel = 'waiting'
  ) then
    execute $tonde_idem_ddl$alter type tonde.job_state add value 'waiting'$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_enum e
    join pg_type t on t.oid = e.enumtypid
    where t.typnamespace = (select oid from pg_namespace where nspname = 'tonde')
      and t.typname = 'job_state'
      and e.enumlabel = 'cancel_requested'
  ) then
    execute $tonde_idem_ddl$alter type tonde.job_state add value 'cancel_requested'$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_enum e
    join pg_type t on t.oid = e.enumtypid
    where t.typnamespace = (select oid from pg_namespace where nspname = 'tonde')
      and t.typname = 'job_state'
      and e.enumlabel = 'timed_out'
  ) then
    execute $tonde_idem_ddl$alter type tonde.job_state add value 'timed_out'$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_enum e
    join pg_type t on t.oid = e.enumtypid
    where t.typnamespace = (select oid from pg_namespace where nspname = 'tonde')
      and t.typname = 'job_state'
      and e.enumlabel = 'dead_letter'
  ) then
    execute $tonde_idem_ddl$alter type tonde.job_state add value 'dead_letter'$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

commit;


begin;


-- 1. Job type definitions. The capability map: which worker class understands a job type, how much
--    priority it may ever hold, how long it may run, how a failure may be treated, and whether the
--    work is externally consequential (which is what makes reconciliation mandatory). A job type that
--    is not defined here cannot be enqueued and cannot be claimed.
create table if not exists tonde.job_type_definitions (
  job_type text primary key check (length(job_type) between 1 and 60),
  worker_class text not null check (worker_class in ('media','ai','export','publishing',
    'reconciliation','notification','maintenance','knowledge')),
  display_name text not null check (length(btrim(display_name)) between 1 and 120),
  description text not null default '' check (length(description) <= 600),
  default_priority integer not null default 50 check (default_priority between 0 and 100),
  max_priority integer not null default 50 check (max_priority between 0 and 100),
  default_max_attempts integer not null default 3 check (default_max_attempts between 1 and 10),
  -- The per-attempt bound. A claimed attempt that runs past it is a worker timeout, not a job-wide
  -- deadline: the two clocks are distinct.
  timeout_seconds integer not null default 900 check (timeout_seconds between 30 and 86400),
  -- The end-to-end retry window. A job that has not finished inside it stops instead of retrying for
  -- ever. This is the `deadline_at` every enqueued job receives.
  max_window_seconds integer not null default 3600 check (max_window_seconds between 60 and 604800),
  -- The most optimistic treatment a *reported* failure of this type may ever receive. A worker may be
  -- more conservative, never less. `requires_idempotency_key` means a retry is only acceptable because
  -- the job carries a stable operation identity (operation_id) that the adapter sends to the provider.
  retry_policy text not null default 'safe_to_retry'
    check (retry_policy in ('safe_to_retry','requires_idempotency_key','requires_reconciliation','must_not_retry')),
  -- The separate, stricter law for an *uncertain* outcome: a lost lease, or a deadline that passed
  -- while the work was in flight. Unless this is false, that work is reconciled before it is repeated.
  requires_reconciliation boolean not null default false,
  externally_consequential boolean not null default false,
  cancellable boolean not null default true,
  idempotent_completion boolean not null default true,
  payload_version integer not null default 1 check (payload_version >= 1),
  enabled boolean not null default true,
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  constraint job_type_priority_ceiling check (max_priority >= default_priority),
  -- Externally consequential work is always reconciled before it is repeated.
  constraint job_type_external_requires_reconciliation
    check (not externally_consequential or requires_reconciliation)
);

alter table tonde.job_type_definitions enable row level security;

do $tonde_idem$
