-- Idempotent enqueue identity, and the claim/scan indexes the real query patterns use.
create unique index if not exists jobs_idempotency on tonde.jobs(workspace_id, job_type, idempotency_key)
  where idempotency_key is not null;

drop index if exists tonde.jobs_claimable;

create index if not exists jobs_claimable on tonde.jobs(priority desc, available_at, created_at)
  where status in ('queued','retrying');

