-- 202610050040_prompt11_device_scene_settings.sql
-- ==========================================================================

-- Prompt 11 packet 040 — device and lens intelligence, scene intelligence, camera settings.
--
-- TONDE's promise is "make it with what you actually have". That promise is only honest if TONDE knows
-- what the equipment can DO, not merely that it exists. Prompts 1–9 already model equipment as
-- `tonde.production_resources` with `resource_compatibility` relations and per-shot `execution_plans`
-- (real: camera + lens, ai: provider + model). This packet adds the missing facts and the deterministic
-- engine that turns them into settings — and, just as important, into refusals.
--
-- Laws enforced here, not merely described:
--   * Capability is DECLARED and then VERIFIED. A declaration names its source; verification is a
--     separate, recorded act by a workspace admin. The engine reports which it is using, and never
--     presents an unverified declaration as a verified fact.
--   * The engine is deterministic arithmetic over declared capabilities and a stated intent. The same
--     inputs produce the same proposal, and every value carries its basis.
--   * A recommendation never exceeds the equipment. Where the intent cannot be satisfied, the engine
--     refuses with a named reason and the limit it hit (mount, image circle, frame rate, resolution,
--     codec, shutter, aperture, ISO, ND) instead of inventing a number.
--   * A measurement that was not supplied is not invented: with no scene exposure, ND is reported as
--     not determined and says why.
--   * Applying settings to a Production's execution plan is a creator decision. The engine proposes;
--     the creator accepts or rejects, and the acceptance is what writes into the plan.
--   * Scene requirements are the "what this scene needs" model: lighting, movement, framing,
--     environment, time of day, audio, permission, safety and cast, each mandatory or not, each with
--     its source. Scene intelligence reports the gaps rather than assuming they are covered.
begin;


-- 1. Device capability. One row per camera-class resource, with the limits that make advice possible.
create table if not exists tonde.device_capabilities (
  resource_id uuid primary key,
  workspace_id uuid not null,
  device_kind text not null check (device_kind in ('camera','phone_camera','drone','action_camera','other')),
  sensor_format text not null check (length(btrim(sensor_format)) between 2 and 60),
  crop_factor numeric(6,3) not null check (crop_factor > 0 and crop_factor <= 20),
  resolution_modes text[] not null default '{}',
  frame_rates numeric[] not null default '{}',
  max_frame_rate numeric check (max_frame_rate is null or max_frame_rate > 0),
  codecs text[] not null default '{}',
  mounts text[] not null default '{}',
  stabilization text not null default 'unknown'
    check (stabilization in ('none','optical','sensor_shift','electronic','hybrid','unknown')),
  nd_stops numeric(4,1) check (nd_stops is null or nd_stops >= 0),
  iso_min integer check (iso_min is null or iso_min > 0),
  iso_max integer check (iso_max is null or iso_max > 0),
  shutter_min_seconds numeric(10,6) check (shutter_min_seconds is null or shutter_min_seconds > 0),
  recording_limit_seconds integer check (recording_limit_seconds is null or recording_limit_seconds > 0),
  battery_runtime_minutes integer check (battery_runtime_minutes is null or battery_runtime_minutes > 0),
  raw_recording boolean not null default false,
  log_profile text,
  thermal_note text check (thermal_note is null or length(thermal_note) <= 400),
  source text not null default 'creator' check (source in ('manufacturer','creator','reference','import')),
  source_label text,
  notes text check (notes is null or length(notes) <= 1000),
  declared_by uuid references auth.users(id) on delete set null,
  verified_at timestamptz,
  verified_by uuid references auth.users(id) on delete set null,
  verification_note text check (verification_note is null or length(verification_note) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (workspace_id, resource_id) references tonde.production_resources(workspace_id, id) on delete restrict,
  constraint device_iso_range_ordered check (iso_min is null or iso_max is null or iso_min <= iso_max),
  -- A CHECK may not contain a subquery, so "max_frame_rate is at most the largest declared rate"
  -- is stated as the negation of "exceeds every declared rate". Empty arrays are allowed.
  constraint device_rates_bounded check (max_frame_rate is null or cardinality(frame_rates) = 0
    or not (max_frame_rate > all(frame_rates))),
  constraint device_source_is_named check (source in ('creator','import') or source_label is not null),
  constraint device_verification_is_stamped check ((verified_at is null) = (verified_by is null))
);

drop trigger if exists guard_mutation on tonde.device_capabilities;
create trigger guard_mutation before insert or update on tonde.device_capabilities
  for each row execute function tonde_private.guard_mutation();

alter table tonde.device_capabilities enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'device_capabilities'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.device_capabilities for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.device_capabilities to authenticated;

grant all on tonde.device_capabilities to service_role;


-- 2. Lens capability. A lens is a resource like any other; what it adds is reach and light.
create table if not exists tonde.lens_capabilities (
  resource_id uuid primary key,
  workspace_id uuid not null,
  mount text not null check (length(btrim(mount)) between 1 and 60),
  focal_min_mm numeric(7,2) not null check (focal_min_mm > 0),
  focal_max_mm numeric(7,2) not null check (focal_max_mm > 0),
  max_aperture numeric(4,1) not null check (max_aperture > 0 and max_aperture <= 64),
  min_aperture numeric(4,1) check (min_aperture is null or (min_aperture > 0 and min_aperture <= 64)),
  image_circle_mm numeric(6,2) check (image_circle_mm is null or image_circle_mm > 0),
  min_focus_m numeric(6,3) check (min_focus_m is null or min_focus_m > 0),
  stabilization text not null default 'unknown'
    check (stabilization in ('none','optical','sensor_shift','electronic','hybrid','unknown')),
  filter_thread_mm numeric(6,1) check (filter_thread_mm is null or filter_thread_mm > 0),
  source text not null default 'creator' check (source in ('manufacturer','creator','reference','import')),
  source_label text,
  notes text check (notes is null or length(notes) <= 1000),
  declared_by uuid references auth.users(id) on delete set null,
  verified_at timestamptz,
  verified_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (workspace_id, resource_id) references tonde.production_resources(workspace_id, id) on delete restrict,
  constraint lens_focal_range_ordered check (focal_min_mm <= focal_max_mm),
  constraint lens_aperture_range_ordered check (min_aperture is null or max_aperture <= min_aperture),
  constraint lens_source_is_named check (source in ('creator','import') or source_label is not null),
  constraint lens_verification_is_stamped check ((verified_at is null) = (verified_by is null))
);

drop trigger if exists guard_mutation on tonde.lens_capabilities;
create trigger guard_mutation before insert or update on tonde.lens_capabilities
  for each row execute function tonde_private.guard_mutation();

alter table tonde.lens_capabilities enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'lens_capabilities'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.lens_capabilities for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.lens_capabilities to authenticated;

grant all on tonde.lens_capabilities to service_role;


-- 3. Scene requirements. What a scene or shot needs before it can be filmed or generated.
create table if not exists tonde.scene_requirements (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  scene_id uuid,
  shot_id uuid,
  requirement_kind text not null check (requirement_kind in ('lighting','movement','framing','environment',
    'time_of_day','audio','permission','safety','cast','prop','wardrobe','location')),
  detail text not null check (length(btrim(detail)) between 3 and 600),
  mandatory boolean not null default true,
  source text not null default 'creator' check (source in ('creator','plan','import')),
  state text not null default 'open' check (state in ('open','met','waived')),
  resolution_note text check (resolution_note is null or length(resolution_note) <= 1000),
  resolved_by uuid references auth.users(id) on delete set null,
  resolved_at timestamptz,
  created_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, scene_id) references tonde.scenes(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  constraint scene_requirement_has_a_target check (scene_id is not null or shot_id is not null),
  constraint scene_requirement_settled_is_stamped check (state = 'open'
    or (resolved_at is not null and resolved_by is not null)),
  constraint scene_requirement_waiver_is_explained check (state <> 'waived' or resolution_note is not null)
);

drop trigger if exists guard_mutation on tonde.scene_requirements;
create trigger guard_mutation before insert or update on tonde.scene_requirements
  for each row execute function tonde_private.guard_mutation();

create unique index if not exists scene_requirement_unique on tonde.scene_requirements(production_id,
  coalesce(shot_id, scene_id), requirement_kind, detail);

create index if not exists scene_requirements_by_target on tonde.scene_requirements(workspace_id, production_id,
  requirement_kind, state);

alter table tonde.scene_requirements enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'scene_requirements'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.scene_requirements for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.scene_requirements to authenticated;

grant all on tonde.scene_requirements to service_role;


-- 4. Settings proposals. The engine's output, with its basis and its refusals kept as evidence.
create table if not exists tonde.camera_settings_proposals (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  scene_id uuid,
  shot_id uuid,
  camera_resource_id uuid not null,
  lens_resource_id uuid,
  intent jsonb not null default '{}'::jsonb check (jsonb_typeof(intent) = 'object'),
  settings jsonb not null default '{}'::jsonb check (jsonb_typeof(settings) = 'object'),
  basis jsonb not null default '{}'::jsonb check (jsonb_typeof(basis) = 'object'),
  refusals jsonb not null default '[]'::jsonb check (jsonb_typeof(refusals) = 'array'),
  satisfied boolean not null default false,
  capability_snapshot jsonb not null default '{}'::jsonb check (jsonb_typeof(capability_snapshot) = 'object'),
  capability_state text not null default 'declared' check (capability_state in ('missing','declared','verified')),
  engine_version text not null default '1',
  intent_hash text not null,
  state text not null default 'proposed' check (state in ('proposed','accepted','rejected','superseded')),
  proposed_by uuid references auth.users(id) on delete set null,
  proposed_at timestamptz not null default now(),
  decided_by uuid references auth.users(id) on delete set null,
  decided_at timestamptz,
  decision_note text check (decision_note is null or length(decision_note) <= 1000),
  applied_plan_id uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, scene_id) references tonde.scenes(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, camera_resource_id) references tonde.production_resources(workspace_id, id) on delete restrict,
  foreign key (workspace_id, lens_resource_id) references tonde.production_resources(workspace_id, id) on delete restrict,
  foreign key (workspace_id, applied_plan_id) references tonde.execution_plans(workspace_id, id) on delete restrict,
  -- A satisfied proposal has no refusals, and a refusal is never hidden by a satisfied flag.
  constraint settings_satisfied_has_no_refusals check (satisfied = (jsonb_array_length(refusals) = 0)),
  constraint settings_decision_is_stamped check (state in ('proposed','superseded')
    or (decided_at is not null and decided_by is not null))
);

create unique index if not exists camera_settings_proposal_unique on tonde.camera_settings_proposals(production_id,
  coalesce(shot_id, scene_id), camera_resource_id, coalesce(lens_resource_id, '00000000-0000-0000-0000-000000000000'::uuid),
  intent_hash) where state in ('proposed','accepted');

create index if not exists camera_settings_proposals_open on tonde.camera_settings_proposals(workspace_id, production_id,
  state, proposed_at desc);

drop trigger if exists guard_mutation on tonde.camera_settings_proposals;
create trigger guard_mutation before insert or update on tonde.camera_settings_proposals
  for each row execute function tonde_private.guard_mutation();

alter table tonde.camera_settings_proposals enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'camera_settings_proposals'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.camera_settings_proposals for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.camera_settings_proposals to authenticated;

grant all on tonde.camera_settings_proposals to service_role;


-- 5. Guards. A client may declare what it owns and may accept a proposal; it may not verify capability,
--    and it may not rewrite a decided proposal.
create or replace function tonde_private.guard_device_capability() returns trigger
language plpgsql security definer set search_path = '' as $$
declare admin boolean;
begin
  admin := (select auth.role()) = 'service_role' or auth.uid() is null
    or tonde_private.is_workspace_admin(new.workspace_id);
  if tg_op = 'INSERT' then
    if new.verified_at is not null and not admin then
      raise exception 'Capability is verified by a workspace admin, not by the session declaring it'
        using errcode = '42501';
    end if;
    return new;
  end if;
  if new.resource_id is distinct from old.resource_id or new.workspace_id is distinct from old.workspace_id then
    raise exception 'A capability belongs to the resource it describes' using errcode = '23514';
  end if;
  if (new.verified_at is distinct from old.verified_at or new.verified_by is distinct from old.verified_by)
    and not admin then
    raise exception 'Capability verification is recorded by a workspace admin' using errcode = '42501';
  end if;
  -- Verification is about exact facts. Changing a limit withdraws verification rather than refusing the
  -- correction, so a declared limit is always correctable; the withdrawn row drops back to 'declared' and
  -- must be verified again by a workspace admin before advice may call it verified.
  if new.verified_at is not null and (new.crop_factor is distinct from old.crop_factor
      or new.iso_max is distinct from old.iso_max or new.mounts is distinct from old.mounts
      or new.codecs is distinct from old.codecs or new.resolution_modes is distinct from old.resolution_modes
      or new.frame_rates is distinct from old.frame_rates or new.nd_stops is distinct from old.nd_stops
      or new.shutter_min_seconds is distinct from old.shutter_min_seconds
      or new.max_frame_rate is distinct from old.max_frame_rate) then
    new.verified_at := null;
    new.verified_by := null;
    new.verification_note := null;
  end if;
  return new;
end $$;

drop trigger if exists guard_device_capability on tonde.device_capabilities;
create trigger guard_device_capability before insert or update on tonde.device_capabilities
  for each row execute function tonde_private.guard_device_capability();

revoke all on function tonde_private.guard_device_capability() from public, anon, authenticated, service_role;


create or replace function tonde_private.guard_camera_settings() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if new.state <> 'proposed' then
      raise exception 'A settings proposal is proposed first and decided afterwards' using errcode = '42501';
    end if;
    return new;
  end if;
  if old.state in ('accepted','rejected') and (new.state is distinct from old.state
      or new.settings is distinct from old.settings or new.refusals is distinct from old.refusals) then
    raise exception 'A decided proposal is a closed record; propose again with a new intent'
      using errcode = '23514';
  end if;
  return new;
end $$;

drop trigger if exists guard_camera_settings on tonde.camera_settings_proposals;
create trigger guard_camera_settings before insert or update on tonde.camera_settings_proposals
  for each row execute function tonde_private.guard_camera_settings();

revoke all on function tonde_private.guard_camera_settings() from public, anon, authenticated, service_role;


-- 6. Private helpers: the arithmetic, named so a test can pin it.
create or replace function tonde_private.device_sensor_diagonal_mm(crop_factor numeric) returns numeric
language sql immutable set search_path = '' as $$
  -- Full-frame 36x24 has a 43.27mm diagonal; a crop factor scales the required image circle.
  select round((43.2666 / greatest(crop_factor, 0.1))::numeric, 2);
$$;

revoke all on function tonde_private.device_sensor_diagonal_mm(numeric)
  from public, anon, authenticated, service_role;


create or replace function tonde_private.exposure_ev(p_aperture numeric, p_shutter_seconds numeric, p_iso numeric)
returns numeric language sql immutable set search_path = '' as $$
  -- Exposure value at ISO 100 for an aperture and a shutter time, adjusted for the working ISO.
  select round((2 * log(2, greatest(p_aperture, 0.1)) - log(2, greatest(p_shutter_seconds, 0.000001))
    - log(2, greatest(p_iso, 1) / 100.0))::numeric, 2);
$$;

revoke all on function tonde_private.exposure_ev(numeric,numeric,numeric)
  from public, anon, authenticated, service_role;


create or replace function tonde_private.device_capability_state(target_workspace uuid, target_resource uuid) returns text
language sql stable security definer set search_path = '' as $$
  select case when c.resource_id is null then 'missing'
    when c.verified_at is not null then 'verified' else 'declared' end
  from (select 1) probe left join tonde.device_capabilities c
    on c.workspace_id = target_workspace and c.resource_id = target_resource;
$$;

revoke all on function tonde_private.device_capability_state(uuid,uuid)
  from public, anon, authenticated, service_role;


-- 7. Declaring, verifying and reading capability.
create or replace function tonde.device_capability_declare(target_workspace uuid, target_resource uuid, p_facts jsonb,
  p_source text default 'creator', p_source_label text default null, p_notes text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; resource tonde.production_resources; capability tonde.device_capabilities;
  existing tonde.device_capabilities;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  if jsonb_typeof(p_facts) <> 'object' then
    raise exception 'Capability is declared as an object' using errcode = '22023';
  end if;
  if p_source not in ('manufacturer','creator','reference','import') then
    raise exception 'A capability declaration names where it came from' using errcode = '22023';
  end if;
  select * into resource from tonde.production_resources r
    where r.workspace_id = target_workspace and r.id = target_resource;
  if not found then raise exception 'That production resource does not exist' using errcode = 'P0002'; end if;
  if resource.resource_type = 'lens' then
    raise exception 'A lens declares lens capability, not device capability' using errcode = '22023';
  end if;
  select * into existing from tonde.device_capabilities c where c.resource_id = target_resource;
  insert into tonde.device_capabilities(resource_id, workspace_id, device_kind, sensor_format, crop_factor,
    resolution_modes, frame_rates, max_frame_rate, codecs, mounts, stabilization, nd_stops, iso_min, iso_max,
    shutter_min_seconds, recording_limit_seconds, battery_runtime_minutes, raw_recording, log_profile,
    thermal_note, source, source_label, notes, declared_by)
  values (target_resource, target_workspace,
    coalesce(nullif(p_facts ->> 'device_kind', ''), case when resource.resource_type::text in ('camera','phone_camera','drone','action_camera')
      then resource.resource_type::text else 'other' end),
    coalesce(nullif(btrim(p_facts ->> 'sensor_format'), ''), 'unspecified'),
    coalesce(nullif(p_facts ->> 'crop_factor', '')::numeric, 1),
    coalesce((select array_agg(value::text) from jsonb_array_elements_text(coalesce(p_facts -> 'resolution_modes', '[]'::jsonb)) as value), '{}'),
    coalesce((select array_agg(value::numeric) from jsonb_array_elements_text(coalesce(p_facts -> 'frame_rates', '[]'::jsonb)) as value), '{}'),
    nullif(p_facts ->> 'max_frame_rate', '')::numeric,
    coalesce((select array_agg(value::text) from jsonb_array_elements_text(coalesce(p_facts -> 'codecs', '[]'::jsonb)) as value), '{}'),
    coalesce((select array_agg(value::text) from jsonb_array_elements_text(coalesce(p_facts -> 'mounts', '[]'::jsonb)) as value), '{}'),
    coalesce(nullif(p_facts ->> 'stabilization', ''), 'unknown'),
    nullif(p_facts ->> 'nd_stops', '')::numeric,
    nullif(p_facts ->> 'iso_min', '')::integer, nullif(p_facts ->> 'iso_max', '')::integer,
    nullif(p_facts ->> 'shutter_min_seconds', '')::numeric,
    nullif(p_facts ->> 'recording_limit_seconds', '')::integer,
    nullif(p_facts ->> 'battery_runtime_minutes', '')::integer,
    coalesce((p_facts ->> 'raw_recording')::boolean, false),
    nullif(btrim(coalesce(p_facts ->> 'log_profile', '')), ''),
    nullif(left(coalesce(p_facts ->> 'thermal_note', ''), 400), ''),
    p_source, nullif(btrim(coalesce(p_source_label, '')), ''), nullif(left(coalesce(p_notes, ''), 1000), ''), actor)
  on conflict (resource_id) do update set device_kind = excluded.device_kind,
    sensor_format = excluded.sensor_format, crop_factor = excluded.crop_factor,
    resolution_modes = excluded.resolution_modes, frame_rates = excluded.frame_rates,
    max_frame_rate = excluded.max_frame_rate, codecs = excluded.codecs, mounts = excluded.mounts,
    stabilization = excluded.stabilization, nd_stops = excluded.nd_stops, iso_min = excluded.iso_min,
    iso_max = excluded.iso_max, shutter_min_seconds = excluded.shutter_min_seconds,
    recording_limit_seconds = excluded.recording_limit_seconds,
    battery_runtime_minutes = excluded.battery_runtime_minutes, raw_recording = excluded.raw_recording,
    log_profile = excluded.log_profile, thermal_note = excluded.thermal_note, source = excluded.source,
    source_label = excluded.source_label, notes = excluded.notes, declared_by = excluded.declared_by,
    updated_at = now()
  returning * into capability;
  perform tonde_private.audit_event(target_workspace, 'device.capability_declared', target_resource,
    'production_resource', jsonb_build_object('device_kind', capability.device_kind, 'source', p_source,
      'source_label', p_source_label, 'crop_factor', capability.crop_factor,
      'verified', capability.verified_at is not null));
  return jsonb_build_object('resource_id', capability.resource_id, 'device_kind', capability.device_kind,
    'crop_factor', capability.crop_factor, 'sensor_format', capability.sensor_format,
    'sensor_diagonal_mm', tonde_private.device_sensor_diagonal_mm(capability.crop_factor),
    'capability_state', tonde_private.device_capability_state(target_workspace, target_resource),
    'replaced_existing_declaration', existing.resource_id is not null,
    'verification_withdrawn', existing.verified_at is not null and capability.verified_at is null,
    'meaning', 'The limits are recorded as declared. Advice built on them says so until a person verifies
      them.');
end $$;

revoke all on function tonde.device_capability_declare(uuid,uuid,jsonb,text,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.device_capability_declare(uuid,uuid,jsonb,text,text,text)
  to authenticated, service_role;


create or replace function tonde.lens_capability_declare(target_workspace uuid, target_resource uuid, p_facts jsonb,
  p_source text default 'creator', p_source_label text default null, p_notes text default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; resource tonde.production_resources; capability tonde.lens_capabilities;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  if jsonb_typeof(p_facts) <> 'object' then
    raise exception 'Capability is declared as an object' using errcode = '22023';
  end if;
  if p_source not in ('manufacturer','creator','reference','import') then
    raise exception 'A capability declaration names where it came from' using errcode = '22023';
  end if;
  select * into resource from tonde.production_resources r
    where r.workspace_id = target_workspace and r.id = target_resource;
  if not found then raise exception 'That production resource does not exist' using errcode = 'P0002'; end if;
  if resource.resource_type <> 'lens' then
    raise exception 'Lens capability is declared for a lens resource' using errcode = '22023';
  end if;
  insert into tonde.lens_capabilities(resource_id, workspace_id, mount, focal_min_mm, focal_max_mm,
    max_aperture, min_aperture, image_circle_mm, min_focus_m, stabilization, filter_thread_mm, source,
    source_label, notes, declared_by)
  values (target_resource, target_workspace, btrim(p_facts ->> 'mount'),
    (p_facts ->> 'focal_min_mm')::numeric, (p_facts ->> 'focal_max_mm')::numeric,
    (p_facts ->> 'max_aperture')::numeric, nullif(p_facts ->> 'min_aperture', '')::numeric,
    nullif(p_facts ->> 'image_circle_mm', '')::numeric, nullif(p_facts ->> 'min_focus_m', '')::numeric,
    coalesce(nullif(p_facts ->> 'stabilization', ''), 'unknown'),
    nullif(p_facts ->> 'filter_thread_mm', '')::numeric, p_source,
    nullif(btrim(coalesce(p_source_label, '')), ''), nullif(left(coalesce(p_notes, ''), 1000), ''), actor)
  on conflict (resource_id) do update set mount = excluded.mount, focal_min_mm = excluded.focal_min_mm,
    focal_max_mm = excluded.focal_max_mm, max_aperture = excluded.max_aperture,
    min_aperture = excluded.min_aperture, image_circle_mm = excluded.image_circle_mm,
    min_focus_m = excluded.min_focus_m, stabilization = excluded.stabilization,
    filter_thread_mm = excluded.filter_thread_mm, source = excluded.source,
    source_label = excluded.source_label, notes = excluded.notes, declared_by = excluded.declared_by,
    updated_at = now()
  returning * into capability;
  perform tonde_private.audit_event(target_workspace, 'lens.capability_declared', target_resource,
    'production_resource', jsonb_build_object('mount', capability.mount, 'focal_min_mm', capability.focal_min_mm,
      'focal_max_mm', capability.focal_max_mm, 'source', p_source));
  return jsonb_build_object('resource_id', capability.resource_id, 'mount', capability.mount,
    'focal_range', jsonb_build_array(capability.focal_min_mm, capability.focal_max_mm),
    'max_aperture', capability.max_aperture, 'image_circle_mm', capability.image_circle_mm,
    'capability_state', case when capability.verified_at is null then 'declared' else 'verified' end,
    'meaning', 'The lens limits are recorded as declared.');
end $$;

revoke all on function tonde.lens_capability_declare(uuid,uuid,jsonb,text,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.lens_capability_declare(uuid,uuid,jsonb,text,text,text)
  to authenticated, service_role;


create or replace function tonde.device_capability_verify(target_workspace uuid, target_resource uuid, p_note text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; device tonde.device_capabilities; lens tonde.lens_capabilities;
begin
  actor := tonde_private.knowledge_admin(target_workspace);
  select * into device from tonde.device_capabilities c
    where c.workspace_id = target_workspace and c.resource_id = target_resource;
  if device.resource_id is not null then
    update tonde.device_capabilities set verified_at = now(), verified_by = actor,
      verification_note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
      where resource_id = target_resource returning * into device;
  else
    select * into lens from tonde.lens_capabilities c
      where c.workspace_id = target_workspace and c.resource_id = target_resource;
    if lens.resource_id is null then
      raise exception 'That resource has no declared capability to verify' using errcode = 'PT409';
    end if;
    update tonde.lens_capabilities set verified_at = now(), verified_by = actor, updated_at = now()
      where workspace_id = target_workspace and resource_id = target_resource returning * into lens;
  end if;
  perform tonde_private.audit_event(target_workspace, 'device.capability_verified', target_resource,
    'production_resource', jsonb_build_object('note', p_note, 'verified_by', actor));
  return jsonb_build_object('resource_id', target_resource, 'capability_state', 'verified',
    'verified_by', actor,
    'meaning', 'A person verified these limits; advice built on them may be presented as verified.');
end $$;

revoke all on function tonde.device_capability_verify(uuid,uuid,text) from public, anon, authenticated, service_role;

grant execute on function tonde.device_capability_verify(uuid,uuid,text) to authenticated, service_role;


-- 8. The settings engine. Deterministic arithmetic over declared limits and a stated intent.
create or replace function tonde.camera_settings_propose(target_workspace uuid, target_production uuid, target_shot uuid,
  target_camera uuid, target_lens uuid default null, p_intent jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; camera tonde.device_capabilities; lens tonde.lens_capabilities;
  refused jsonb := '[]'::jsonb; basis jsonb := '{}'::jsonb; settings jsonb := '{}'::jsonb;
  required_circle numeric; frame_rate numeric; shutter_angle numeric; shutter_seconds numeric;
  aperture numeric; iso integer; nd numeric; ev_settings numeric; ev_needed numeric;
  capability_state text; proposal_hash text; production tonde.productions; shot tonde.shots;
  proposal tonde.camera_settings_proposals; existing tonde.camera_settings_proposals; mount_ok boolean;
  snapshots jsonb; lens_ready boolean := true; camera_ready boolean := true; lighting text;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  if jsonb_typeof(p_intent) <> 'object' then
    raise exception 'An intent is an object' using errcode = '22023';
  end if;
  select * into production from tonde.productions p where p.workspace_id = target_workspace
    and p.id = target_production;
  if not found then raise exception 'That Production does not exist' using errcode = 'P0002'; end if;
  select * into shot from tonde.shots s where s.workspace_id = target_workspace
    and s.production_id = target_production and s.id = target_shot;
  if not found then raise exception 'That shot does not exist in this Production' using errcode = 'P0002'; end if;
  select * into camera from tonde.device_capabilities c
    where c.workspace_id = target_workspace and c.resource_id = target_camera;
  capability_state := case when camera.resource_id is null then 'missing'
    when camera.verified_at is not null then 'verified' else 'declared' end;
  if camera.resource_id is null then
    -- No invented advice: the refusal names the missing input.
    raise exception 'CAPABILITY_MISSING: declare what this camera can do before asking for settings'
      using errcode = 'PT409';
  end if;
  if target_lens is not null then
    select * into lens from tonde.lens_capabilities c
      where c.workspace_id = target_workspace and c.resource_id = target_lens;
    if lens.resource_id is null then
      raise exception 'LENS_CAPABILITY_MISSING: declare what this lens can do first' using errcode = 'PT409';
    end if;
    mount_ok := lens.mount = any (camera.mounts) or exists (select 1 from tonde.resource_compatibility rc
      where rc.workspace_id = target_workspace and rc.relation = 'mount'
        and ((rc.resource_id = target_camera and rc.compatible_resource_id = target_lens)
          or (rc.resource_id = target_lens and rc.compatible_resource_id = target_camera)));
    if not mount_ok then
      refused := refused || jsonb_build_object('reason', 'MOUNT_MISMATCH', 'detail',
        format('The %s mount is not one of this camera''s mounts (%s)', lens.mount,
          array_to_string(camera.mounts, ', ')), 'limit', camera.mounts);
    end if;
    select * into lens from tonde.lens_capabilities c
      where c.workspace_id = target_workspace and c.resource_id = target_lens;
  end if;
  -- Frame rate and shutter: a stated intent, or the honest default of 24p at a 180 degree shutter.
  frame_rate := coalesce(nullif(p_intent ->> 'frame_rate', '')::numeric, 24);
  if camera.max_frame_rate is not null and frame_rate > camera.max_frame_rate then
    refused := refused || jsonb_build_object('reason', 'FRAME_RATE_UNSUPPORTED', 'requested', frame_rate,
      'limit', camera.max_frame_rate);
  elsif cardinality(camera.frame_rates) > 0 and not (frame_rate = any (camera.frame_rates)) then
    refused := refused || jsonb_build_object('reason', 'FRAME_RATE_UNSUPPORTED', 'requested', frame_rate,
      'limit', camera.frame_rates);
  else
    basis := basis || jsonb_build_object('frame_rate',
      case when p_intent ? 'frame_rate' then 'Requested and supported by the declared limit.'
        else 'No frame rate was requested, so the 24p default is used.' end);
  end if;
  shutter_angle := coalesce(nullif(p_intent ->> 'shutter_angle', '')::numeric, 180);
  if shutter_angle <= 0 or shutter_angle > 360 then
    raise exception 'A shutter angle is between 0 and 360 degrees' using errcode = '22023';
  end if;
  shutter_seconds := round((1 / frame_rate * shutter_angle / 360)::numeric, 6);
  if camera.shutter_min_seconds is not null and shutter_seconds < camera.shutter_min_seconds then
    refused := refused || jsonb_build_object('reason', 'SHUTTER_TOO_FAST', 'requested_seconds', shutter_seconds,
      'limit', camera.shutter_min_seconds);
  else
    basis := basis || jsonb_build_object('shutter_seconds', format(
      'A %s degree shutter at %s fps gives %s s (%s).', shutter_angle, frame_rate, shutter_seconds,
      case when p_intent ? 'shutter_angle' then 'requested' else 'the 180 degree default' end));
  end if;
  -- Aperture: from the lens range, never outside it.
  aperture := nullif(p_intent ->> 'aperture', '')::numeric;
  if target_lens is not null then
    if aperture is null then
      aperture := lens.max_aperture;
      basis := basis || jsonb_build_object('aperture',
        'No aperture was requested, so the lens is used wide open at f/' || lens.max_aperture || '.');
    elsif aperture < lens.max_aperture then
      refused := refused || jsonb_build_object('reason', 'APERTURE_UNAVAILABLE', 'requested', aperture,
        'limit', 'the lens opens to f/' || lens.max_aperture);
      aperture := lens.max_aperture;
    elsif lens.min_aperture is not null and aperture > lens.min_aperture then
      refused := refused || jsonb_build_object('reason', 'APERTURE_UNAVAILABLE', 'requested', aperture,
        'limit', 'the lens closes to f/' || lens.min_aperture);
      aperture := lens.min_aperture;
    else
      basis := basis || jsonb_build_object('aperture',
        'Requested and inside the lens range f/' || lens.max_aperture || '-f/' || lens.min_aperture || '.');
    end if;
  elsif aperture is not null then
    basis := basis || jsonb_build_object('aperture', 'Requested; no lens limit was supplied to check it against.');
  end if;
  -- ISO: the light level maps to a starting sensitivity, clamped to the declared range.
  lighting := nullif(p_intent ->> 'lighting', '');
  if lighting is not null and lighting not in ('low','medium','high') then
    raise exception 'A lighting level is low, medium or high' using errcode = '22023';
  end if;
  iso := nullif(p_intent ->> 'iso', '')::integer;
  if iso is null then
    iso := case lighting when 'low' then 200 when 'high' then 3200 when 'medium' then 800
      else camera.iso_min end;
    basis := basis || jsonb_build_object('iso', case lighting
      when 'low' then 'A low light level starts at ISO 200; raise it only if the scene needs it.'
      when 'medium' then 'A medium light level starts at ISO 800.'
      when 'high' then 'A bright scene starts at ISO 3200 only if the shutter and aperture are fixed.'
      else 'No light level or ISO was given, so the declared base sensitivity is used.' end);
  else
    basis := basis || jsonb_build_object('iso', 'Requested.');
  end if;
  if camera.iso_max is not null and iso > camera.iso_max then
    refused := refused || jsonb_build_object('reason', 'INSUFFICIENT_SENSITIVITY', 'requested', iso,
      'limit', camera.iso_max);
    iso := camera.iso_max;
  end if;
  if camera.iso_min is not null and iso < camera.iso_min then
    iso := camera.iso_min;
  end if;
  -- Resolution and codec: requested values must exist in the declared capability.
  if p_intent ? 'resolution' and nullif(p_intent ->> 'resolution', '') is not null then
    if cardinality(camera.resolution_modes) > 0
      and not (p_intent ->> 'resolution' = any (camera.resolution_modes)) then
      refused := refused || jsonb_build_object('reason', 'RESOLUTION_UNSUPPORTED',
        'requested', p_intent ->> 'resolution', 'limit', camera.resolution_modes);
    else
      settings := settings || jsonb_build_object('resolution', p_intent ->> 'resolution');
      basis := basis || jsonb_build_object('resolution', 'Requested and supported by the declared modes.');
    end if;
  end if;
  if p_intent ? 'codec' and nullif(p_intent ->> 'codec', '') is not null then
    if cardinality(camera.codecs) > 0 and not (p_intent ->> 'codec' = any (camera.codecs)) then
      refused := refused || jsonb_build_object('reason', 'CODEC_UNSUPPORTED', 'requested', p_intent ->> 'codec',
        'limit', camera.codecs);
    else
      settings := settings || jsonb_build_object('codec', p_intent ->> 'codec');
      basis := basis || jsonb_build_object('codec', 'Requested and supported by the declared codecs.');
    end if;
  end if;
  -- Focal length and coverage: the lens must reach the framing and cover the sensor.
  if target_lens is not null then
    required_circle := tonde_private.device_sensor_diagonal_mm(camera.crop_factor);
    if lens.image_circle_mm is not null and lens.image_circle_mm < required_circle then
      refused := refused || jsonb_build_object('reason', 'IMAGE_CIRCLE_TOO_SMALL',
        'required_mm', required_circle, 'limit', lens.image_circle_mm);
    else
      basis := basis || jsonb_build_object('coverage', format(
        'The sensor needs a %s mm image circle; the lens provides %s mm.', required_circle,
        coalesce(lens.image_circle_mm::text, 'an unstated circle')));
    end if;
    if p_intent ? 'focal_mm' and nullif(p_intent ->> 'focal_mm', '') is not null then
      if (p_intent ->> 'focal_mm')::numeric < lens.focal_min_mm
        or (p_intent ->> 'focal_mm')::numeric > lens.focal_max_mm then
        refused := refused || jsonb_build_object('reason', 'FOCAL_LENGTH_UNAVAILABLE',
          'requested', (p_intent ->> 'focal_mm')::numeric,
          'limit', format('%s-%s mm', lens.focal_min_mm, lens.focal_max_mm));
      else
        settings := settings || jsonb_build_object('focal_mm', (p_intent ->> 'focal_mm')::numeric);
        basis := basis || jsonb_build_object('focal_mm', 'Requested and inside the lens range.');
      end if;
    end if;
  end if;
  -- Neutral density: only from a stated scene exposure. Without a measurement, ND is not determined.
  if p_intent ? 'scene_ev' and nullif(p_intent ->> 'scene_ev', '') is not null then
    ev_needed := (p_intent ->> 'scene_ev')::numeric;
    if aperture is not null then
      ev_settings := tonde_private.exposure_ev(aperture, shutter_seconds, iso);
      nd := ceil(greatest(ev_needed - ev_settings, 0));
      if camera.nd_stops is not null and nd > camera.nd_stops then
        refused := refused || jsonb_build_object('reason', 'INSUFFICIENT_ND', 'required_stops', nd,
          'limit', camera.nd_stops);
        nd := camera.nd_stops;
      end if;
      -- Zero stops is a real answer (no filter needed), so it is recorded as a value, not as an absence.
      settings := settings || jsonb_build_object('nd_stops', nd);
      basis := basis || jsonb_build_object('nd_stops', format(
        'Scene EV %s against settings EV %s needs %s stop(s) of neutral density.', ev_needed, ev_settings,
        greatest(ceil(ev_needed - ev_settings), 0)));
    else
      nd := null;
      basis := basis || jsonb_build_object('nd_stops',
        'No aperture is available to compute an exposure, so neutral density is not determined.');
    end if;
  else
    nd := null;
    settings := settings || jsonb_build_object('nd_stops', null);
    basis := basis || jsonb_build_object('nd_stops',
      'No scene exposure was measured, so neutral density is not determined rather than guessed.');
  end if;
  settings := settings || jsonb_build_object('frame_rate', frame_rate, 'shutter_angle', shutter_angle,
    'shutter_seconds', shutter_seconds, 'iso', iso, 'aperture', aperture,
    'camera_resource_id', target_camera, 'lens_resource_id', target_lens);
  snapshots := jsonb_build_object('camera', jsonb_build_object('crop_factor', camera.crop_factor,
    'mounts', camera.mounts, 'iso_range', jsonb_build_array(camera.iso_min, camera.iso_max),
    'frame_rates', camera.frame_rates, 'max_frame_rate', camera.max_frame_rate,
    'resolution_modes', camera.resolution_modes, 'codecs', camera.codecs, 'nd_stops', camera.nd_stops,
    'shutter_min_seconds', camera.shutter_min_seconds, 'source', camera.source,
    'verified', camera.verified_at is not null),
    'lens', case when target_lens is null then null else jsonb_build_object('mount', lens.mount,
      'focal_range', jsonb_build_array(lens.focal_min_mm, lens.focal_max_mm),
      'aperture_range', jsonb_build_array(lens.max_aperture, lens.min_aperture),
      'image_circle_mm', lens.image_circle_mm, 'verified', lens.verified_at is not null) end);
  proposal_hash := encode(sha256(convert_to(jsonb_build_object('camera', target_camera, 'lens', target_lens,
    'intent', p_intent, 'capability', snapshots)::text, 'UTF8')), 'hex');
  select * into existing from tonde.camera_settings_proposals p
    where p.workspace_id = target_workspace and p.production_id = target_production
      and p.shot_id = target_shot and p.camera_resource_id = target_camera
      and p.lens_resource_id is not distinct from target_lens and p.intent_hash = proposal_hash
      and p.state in ('proposed','accepted');
  if existing.id is not null then
    return jsonb_build_object('proposal_id', existing.id, 'state', existing.state, 'satisfied', existing.satisfied,
      'settings', existing.settings, 'basis', existing.basis, 'refusals', existing.refusals,
      'capability_state', existing.capability_state, 'idempotent', true);
  end if;
  insert into tonde.camera_settings_proposals(workspace_id, production_id, scene_id, shot_id,
    camera_resource_id, lens_resource_id, intent, settings, basis, refusals, satisfied, capability_snapshot,
    capability_state, intent_hash, proposed_by)
  values (target_workspace, target_production, shot.scene_id, target_shot, target_camera, target_lens,
    p_intent, settings, basis, refused, jsonb_array_length(refused) = 0, snapshots, capability_state,
    proposal_hash, actor)
  returning * into proposal;
  perform tonde_private.audit_event(target_workspace, 'camera.settings_proposed', proposal.id,
    'camera_settings_proposal', jsonb_build_object('shot_id', target_shot, 'camera', target_camera,
      'lens', target_lens, 'satisfied', proposal.satisfied, 'refusals', refused,
      'capability_state', capability_state));
  return jsonb_build_object('proposal_id', proposal.id, 'state', proposal.state, 'satisfied', proposal.satisfied,
    'settings', proposal.settings, 'basis', proposal.basis, 'refusals', proposal.refusals,
    'capability_state', capability_state, 'engine_version', proposal.engine_version, 'idempotent', false,
    'meaning', case when proposal.satisfied
      then 'Every value follows from the declared limits and the stated intent; each value carries its basis.'
      else 'The equipment cannot satisfy this intent as stated. The refusals name the limit that was hit;
        nothing was invented to fill the gap.' end);
end $$;

revoke all on function tonde.camera_settings_propose(uuid,uuid,uuid,uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.camera_settings_propose(uuid,uuid,uuid,uuid,uuid,jsonb)
  to authenticated, service_role;


-- 9. Accepting a proposal is the creator's decision, and it is what writes into the execution plan.
create or replace function tonde.camera_settings_decide(target_workspace uuid, target_proposal uuid, p_decision text,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; proposal tonde.camera_settings_proposals; plan tonde.execution_plans; applied uuid;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  if p_decision not in ('accept','reject') then
    raise exception 'A proposal is accepted or rejected' using errcode = '22023';
  end if;
  select * into proposal from tonde.camera_settings_proposals p
    where p.workspace_id = target_workspace and p.id = target_proposal for update;
  if not found then raise exception 'That settings proposal does not exist' using errcode = 'P0002'; end if;
  if proposal.state <> 'proposed' then
    return jsonb_build_object('proposal_id', proposal.id, 'state', proposal.state, 'idempotent', true);
  end if;
  if p_decision = 'accept' and not proposal.satisfied then
    raise exception 'SETTINGS_UNSATISFIED: this proposal refuses part of the intent; change the equipment or the
      intent first' using errcode = 'PT409';
  end if;
  if p_decision = 'reject' and btrim(coalesce(p_note, '')) = '' then
    raise exception 'A rejection says why' using errcode = '22023';
  end if;
  select * into plan from tonde.execution_plans p where p.workspace_id = target_workspace
    and p.shot_id = proposal.shot_id and p.execution_method = 'real';
  if p_decision = 'accept' and plan.id is not null then
    update tonde.execution_plans set camera_resource_id = coalesce(proposal.camera_resource_id, camera_resource_id),
      lens_resource_id = coalesce(proposal.lens_resource_id, lens_resource_id),
      plan_metadata = plan_metadata || jsonb_build_object('camera_settings', proposal.settings,
        'camera_settings_proposal_id', proposal.id, 'camera_settings_basis', proposal.basis),
      updated_at = now()
      where id = plan.id returning * into plan;
    applied := plan.id;
  end if;
  update tonde.camera_settings_proposals set state = case when p_decision = 'accept' then 'accepted' else 'rejected' end,
    decided_by = actor, decided_at = now(), decision_note = nullif(left(coalesce(p_note, ''), 1000), ''),
    applied_plan_id = applied, updated_at = now()
    where id = proposal.id returning * into proposal;
  perform tonde_private.audit_event(target_workspace, 'camera.settings_' || p_decision, proposal.id,
    'camera_settings_proposal', jsonb_build_object('shot_id', proposal.shot_id, 'applied_plan_id', applied,
      'note', p_note, 'settings', proposal.settings));
  return jsonb_build_object('proposal_id', proposal.id, 'state', proposal.state, 'idempotent', false,
    'applied_plan_id', applied,
    'meaning', case when p_decision = 'accept' and applied is not null
      then 'The creator accepted the settings and they are recorded on this shot''s real execution plan.'
      when p_decision = 'accept' then 'The creator accepted the settings; no real execution plan existed to
        record them on yet.'
      else 'The proposal was rejected with a reason and nothing was applied.' end);
end $$;

revoke all on function tonde.camera_settings_decide(uuid,uuid,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.camera_settings_decide(uuid,uuid,text,text) to authenticated, service_role;


-- 10. Scene requirements and the scene intelligence read.
create or replace function tonde.scene_requirement_add(target_workspace uuid, target_production uuid,
  requirement_kind text, detail text, target_scene uuid default null, target_shot uuid default null,
  p_mandatory boolean default true, p_source text default 'creator') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; requirement tonde.scene_requirements; existing tonde.scene_requirements;
  v_kind text; v_detail text;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  -- The names a client sends and the names of the columns are the same words, so they are copied into
  -- unambiguous locals before any statement that reads the table.
  v_kind := requirement_kind;
  v_detail := btrim(coalesce(detail, ''));
  if v_kind not in ('lighting','movement','framing','environment','time_of_day','audio','permission',
    'safety','cast','prop','wardrobe','location') then
    raise exception 'That is not a TONDE scene requirement' using errcode = '22023';
  end if;
  if p_source not in ('creator','plan','import') then
    raise exception 'A requirement names where it came from' using errcode = '22023';
  end if;
  if target_scene is null and target_shot is null then
    raise exception 'A requirement belongs to a scene or a shot' using errcode = '22023';
  end if;
  if target_shot is not null then
    select s.scene_id into target_scene from tonde.shots s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.id = target_shot;
    if target_scene is null then
      raise exception 'That shot does not exist in this Production' using errcode = 'P0002';
    end if;
  end if;
  select * into existing from tonde.scene_requirements r where r.production_id = target_production
    and coalesce(r.shot_id, r.scene_id) = coalesce(target_shot, target_scene)
    and r.requirement_kind = v_kind and r.detail = v_detail;
  if existing.id is not null then
    return jsonb_build_object('requirement_id', existing.id, 'state', existing.state, 'idempotent', true);
  end if;
  insert into tonde.scene_requirements(workspace_id, production_id, scene_id, shot_id, requirement_kind,
    detail, mandatory, source, created_by)
  values (target_workspace, target_production, target_scene, target_shot, v_kind,
    left(v_detail, 600), coalesce(p_mandatory, true), p_source, actor)
  returning * into requirement;
  perform tonde_private.audit_event(target_workspace, 'scene.requirement_added', requirement.id,
    'scene_requirement', jsonb_build_object('kind', v_kind, 'mandatory', requirement.mandatory,
      'shot_id', target_shot, 'scene_id', target_scene));
  return jsonb_build_object('requirement_id', requirement.id, 'state', requirement.state,
    'mandatory', requirement.mandatory, 'idempotent', false);
end $$;

revoke all on function tonde.scene_requirement_add(uuid,uuid,text,text,uuid,uuid,boolean,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.scene_requirement_add(uuid,uuid,text,text,uuid,uuid,boolean,text)
  to authenticated, service_role;


create or replace function tonde.scene_requirement_settle(target_workspace uuid, target_requirement uuid, p_state text,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; requirement tonde.scene_requirements;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  if p_state not in ('met','waived','open') then
    raise exception 'A requirement is met, waived or open' using errcode = '22023';
  end if;
  select * into requirement from tonde.scene_requirements r
    where r.workspace_id = target_workspace and r.id = target_requirement for update;
  if not found then raise exception 'That requirement does not exist' using errcode = 'P0002'; end if;
  if p_state = 'waived' and btrim(coalesce(p_note, '')) = '' then
    raise exception 'Waiving a requirement says why' using errcode = '22023';
  end if;
  update tonde.scene_requirements set state = p_state,
    resolution_note = nullif(left(coalesce(p_note, ''), 1000), ''),
    resolved_by = case when p_state = 'open' then null else actor end,
    resolved_at = case when p_state = 'open' then null else now() end, updated_at = now()
    where id = requirement.id returning * into requirement;
  return jsonb_build_object('requirement_id', requirement.id, 'state', requirement.state,
    'meaning', case when p_state = 'waived'
      then 'The requirement was waived and the reason is recorded with it.'
      else 'The requirement state is recorded as it is.' end);
end $$;

revoke all on function tonde.scene_requirement_settle(uuid,uuid,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.scene_requirement_settle(uuid,uuid,text,text) to authenticated, service_role;


create or replace function tonde.scene_intelligence(target_workspace uuid, target_production uuid, target_scene uuid default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare by_service boolean := (select auth.role()) = 'service_role'; requirements jsonb; shots jsonb;
  devices jsonb; gaps jsonb; scene_count integer;
begin
  if not by_service and (auth.uid() is null or not tonde_private.is_workspace_member(target_workspace)) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  if not exists (select 1 from tonde.productions p where p.workspace_id = target_workspace
      and p.id = target_production) then
    raise exception 'That Production does not exist' using errcode = 'P0002';
  end if;
  select count(*) into scene_count from tonde.scenes s where s.workspace_id = target_workspace
    and s.production_id = target_production and (target_scene is null or s.id = target_scene);
  select coalesce(jsonb_agg(jsonb_build_object('requirement_id', r.id, 'kind', r.requirement_kind,
    'detail', r.detail, 'mandatory', r.mandatory, 'state', r.state, 'source', r.source,
    'scene_id', r.scene_id, 'shot_id', r.shot_id, 'resolution_note', r.resolution_note)
    order by r.mandatory desc, r.requirement_kind), '[]'::jsonb) into requirements
    from tonde.scene_requirements r where r.workspace_id = target_workspace
      and r.production_id = target_production
      and (target_scene is null or r.scene_id = target_scene or exists (
        select 1 from tonde.scenes s2 where s2.id = r.scene_id and s2.id = target_scene));
  select coalesce(jsonb_agg(jsonb_build_object('shot_id', s.id, 'scene_id', s.scene_id, 'title', s.title,
    'execution_method', s.execution_method, 'camera_resource_id', p.camera_resource_id,
    'lens_resource_id', p.lens_resource_id, 'settings_accepted',
      coalesce(p.plan_metadata ? 'camera_settings', false),
    'settings', p.plan_metadata -> 'camera_settings') order by s.sort_order), '[]'::jsonb) into shots
    from tonde.shots s left join tonde.execution_plans p on p.shot_id = s.id and p.execution_method = 'real'
    where s.workspace_id = target_workspace and s.production_id = target_production
      and s.lifecycle = 'active' and (target_scene is null or s.scene_id = target_scene);
  select coalesce(jsonb_agg(jsonb_build_object('resource_id', r.id, 'name', r.name, 'resource_type', r.resource_type,
    'capability_state', case when d.resource_id is not null and d.verified_at is not null then 'verified'
      when d.resource_id is not null then 'declared' when l.resource_id is not null and l.verified_at is not null
        then 'verified' when l.resource_id is not null then 'declared' else 'missing' end)
    order by r.resource_type, r.name), '[]'::jsonb) into devices
    from tonde.production_resources r
      left join tonde.device_capabilities d on d.resource_id = r.id
      left join tonde.lens_capabilities l on l.resource_id = r.id
    where r.workspace_id = target_workspace and r.lifecycle = 'active'
      and r.resource_type in ('camera','phone_camera','lens','drone','action_camera','light');
  -- A gap is a mandatory requirement that nothing satisfies. It is reported, never assumed away.
  select coalesce(jsonb_agg(jsonb_build_object('requirement_id', r.id, 'kind', r.requirement_kind,
    'detail', r.detail, 'scene_id', r.scene_id, 'shot_id', r.shot_id,
    'reason', case when r.shot_id is not null and not exists (select 1 from tonde.execution_plans p
        where p.workspace_id = target_workspace and p.shot_id = r.shot_id) then 'NO_EXECUTION_PLAN'
      when r.requirement_kind in ('lighting','framing','movement','location')
        and not exists (select 1 from tonde.production_resources px where px.workspace_id = target_workspace
          and px.lifecycle = 'active' and px.resource_type in ('camera','phone_camera','lens','drone','action_camera'))
        then 'NO_DEVICE_DECLARED' else 'UNRESOLVED' end) order by r.requirement_kind), '[]'::jsonb)
    into gaps
    from tonde.scene_requirements r where r.workspace_id = target_workspace
      and r.production_id = target_production and r.state = 'open' and r.mandatory
      and (target_scene is null or r.scene_id = target_scene);
  return jsonb_build_object('workspace_id', target_workspace, 'production_id', target_production,
    'scene_id', target_scene, 'scenes_considered', scene_count, 'requirements', requirements, 'shots', shots,
    'devices', devices, 'gaps', gaps,
    'meaning', 'Intelligence is reported as requirements, per-shot execution, available devices with their
      capability state, and the mandatory requirements nothing yet satisfies. Where a device limit is
      unknown it is reported as missing rather than assumed.');
end $$;

revoke all on function tonde.scene_intelligence(uuid,uuid,uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.scene_intelligence(uuid,uuid,uuid) to authenticated, service_role;


create or replace function tonde.device_readiness(target_workspace uuid, target_production uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare by_service boolean := (select auth.role()) = 'service_role'; devices jsonb; refusals jsonb;
  coverage jsonb;
begin
  if not by_service and (auth.uid() is null or not tonde_private.is_workspace_member(target_workspace)) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('resource_id', r.id, 'name', r.name, 'resource_type',
    r.resource_type, 'mount', r.mount, 'manufacturer', r.manufacturer, 'model', r.model,
    'capability_state', case when d.resource_id is not null and d.verified_at is not null then 'verified'
      when d.resource_id is not null then 'declared' when l.resource_id is not null and l.verified_at is not null
        then 'verified' when l.resource_id is not null then 'declared' else 'missing' end,
    'device_kind', d.device_kind, 'crop_factor', d.crop_factor, 'sensor_diagonal_mm',
      case when d.crop_factor is null then null else tonde_private.device_sensor_diagonal_mm(d.crop_factor) end,
    'lens', case when l.resource_id is null then null else jsonb_build_object('mount', l.mount,
      'focal_range', jsonb_build_array(l.focal_min_mm, l.focal_max_mm), 'max_aperture', l.max_aperture,
      'image_circle_mm', l.image_circle_mm) end,
    'source', coalesce(d.source, l.source), 'source_label', coalesce(d.source_label, l.source_label))
    order by r.resource_type, r.name), '[]'::jsonb) into devices
    from tonde.production_resources r
      left join tonde.device_capabilities d on d.resource_id = r.id
      left join tonde.lens_capabilities l on l.resource_id = r.id
    where r.workspace_id = target_workspace and r.lifecycle = 'active'
      and r.resource_type in ('camera','phone_camera','lens','drone','action_camera');
  select coalesce(jsonb_agg(jsonb_build_object('proposal_id', p.id, 'shot_id', p.shot_id,
    'camera_resource_id', p.camera_resource_id, 'lens_resource_id', p.lens_resource_id,
    'satisfied', p.satisfied, 'refusals', p.refusals, 'capability_state', p.capability_state,
    'state', p.state) order by p.proposed_at desc), '[]'::jsonb) into refusals
    from tonde.camera_settings_proposals p where p.workspace_id = target_workspace
      and p.production_id = target_production and not p.satisfied and p.state in ('proposed','rejected');
  select coalesce(jsonb_agg(jsonb_build_object('shot_id', s.id, 'execution_method', s.execution_method,
    'has_real_plan', p.id is not null, 'settings_accepted', coalesce(p.plan_metadata ? 'camera_settings', false))
    order by s.sort_order), '[]'::jsonb) into coverage
    from tonde.shots s left join tonde.execution_plans p on p.shot_id = s.id and p.execution_method = 'real'
    where s.workspace_id = target_workspace and s.production_id = target_production and s.lifecycle = 'active';
  return jsonb_build_object('workspace_id', target_workspace, 'production_id', target_production,
    'devices', devices, 'shots', coverage, 'unsatisfied_proposals', refusals,
    'meaning', 'Readiness reports the equipment, what is actually known about it, which shots have an
      execution plan, and every proposal the equipment could not satisfy.');
end $$;

revoke all on function tonde.device_readiness(uuid,uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.device_readiness(uuid,uuid) to authenticated, service_role;


alter default privileges in schema tonde revoke execute on functions from public;

alter default privileges in schema tonde_private revoke execute on functions from public;


commit;

-- ==========================================================================
-- 202610050041_prompt11_discover_engine.sql
-- ==========================================================================

-- Prompt 11 packet 041 — the Discover content engine and "Create This".
--
-- The responsibility matrix gives DISCOVER one job: production knowledge, techniques,
-- references/examples/templates, movie references, saved inspiration and collections, with
-- DIRECT THIS / USE THIS TECHNIQUE / SAVE REFERENCE. It must never become a mere image gallery or a
-- stock marketplace. This packet makes that concrete, and makes the honesty laws enforceable:
--
--   * A discover item states where it came from. `provenance` is required, and where it came from is
--     immutable: a client cannot re-attribute an item to a different source after the fact.
--   * Knowledge becomes discoverable only when it is usable. An item built on a knowledge item is
--     registered only while that knowledge passes the Production Knowledge Engine's own usability law
--     (`tonde_private.knowledge_is_usable`), and its usability is re-read from the live source row on
--     every read — so knowledge that is later rejected, retired or superseded makes the item
--     unusable, and the index says so instead of presenting it as guidance.
--   * An item carries the source's own substance, not a paraphrase of it: registering an item on a
--     knowledge source copies that source's category, purpose, effect and limits with its revision.
--   * SAVING is not applying. A save is a creator's private note against an item and changes no
--     production.
--   * DIRECT THIS / USE THIS TECHNIQUE is a two-step creator decision. A PREVIEW writes down exactly
--     what would be created and creates nothing; APPLY spends creator authority, requires the item's
--     canonical id to be typed back, re-checks that the source is still usable, and records the exact
--     object it created. An applied application is a closed record.
--   * Where an item cannot support an action at all, the action is refused with the named reason
--     (no technique substance, no locator, no directions) rather than a fabricated object.
begin;


-- 1. Discover items. Curated TONDE content is global; everything a workspace adds is workspace-scoped.
create table if not exists tonde.discover_items (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid,
  visibility text not null default 'workspace' check (visibility in ('workspace','global')),
  canonical_id text not null check (canonical_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(canonical_id) between 3 and 120),
  item_kind text not null check (item_kind in ('technique','knowledge','tutorial','reference_example',
    'movie_reference','template','inspiration')),
  title text not null check (length(btrim(title)) between 3 and 200),
  summary text not null check (length(btrim(summary)) between 3 and 600),
  directions text not null default '' check (length(directions) <= 6000),
  applicability jsonb not null default '{}'::jsonb check (jsonb_typeof(applicability) = 'object'),
  provenance jsonb not null check (jsonb_typeof(provenance) = 'object'),
  source_kind text not null check (source_kind in ('knowledge','tutorial','production_reference','creator',
    'import','tonde_canon')),
  source_technique_id uuid,
  source_tutorial_id uuid,
  source_reference_id uuid,
  source_media_id uuid,
  review_state text not null default 'creator_asserted' check (review_state in ('creator_asserted','curated')),
  registered_by uuid references auth.users(id) on delete set null,
  notes text check (notes is null or length(notes) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict,
  foreign key (workspace_id, source_technique_id) references tonde.creative_techniques(workspace_id, id) on delete restrict,
  foreign key (workspace_id, source_tutorial_id) references tonde.knowledge_tutorials(workspace_id, id) on delete restrict,
  foreign key (workspace_id, source_reference_id) references tonde.production_references(workspace_id, id) on delete restrict,
  foreign key (workspace_id, source_media_id) references tonde.media_files(workspace_id, id) on delete restrict,
  -- Curated content has no workspace; workspace content always has one.
  constraint discover_item_is_owned check ((visibility = 'workspace') = (workspace_id is not null)),
  -- An item names its source row, or it is honestly authored rather than derived.
  constraint discover_item_source_identified check (
    (source_kind = 'knowledge' and source_technique_id is not null)
    or (source_kind = 'tutorial' and source_tutorial_id is not null)
    or (source_kind = 'production_reference' and source_reference_id is not null)
    or source_kind in ('creator','import','tonde_canon')),
  -- Provenance always names where it came from.
  constraint discover_item_provenance_is_named check (provenance ? 'source_label'),
  constraint discover_curated_names_its_attribution check (review_state <> 'curated'
    or (provenance ? 'attribution'))
);

create unique index if not exists discover_item_workspace_canonical on tonde.discover_items(workspace_id, canonical_id)
  where workspace_id is not null;

create unique index if not exists discover_item_global_canonical on tonde.discover_items(canonical_id)
  where workspace_id is null;

create index if not exists discover_items_kind on tonde.discover_items(visibility, item_kind, title);

drop trigger if exists guard_mutation on tonde.discover_items;
create trigger guard_mutation before insert or update on tonde.discover_items
  for each row execute function tonde_private.guard_mutation();

alter table tonde.discover_items enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'discover_items'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.discover_items for select to authenticated
  using (visibility = 'global' or tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.discover_items to authenticated;

grant all on tonde.discover_items to service_role;


-- 2. SAVE REFERENCE. A save is a creator's own note against an item; it creates no production work.
create table if not exists tonde.discover_saves (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  item_id uuid not null references tonde.discover_items(id) on delete restrict,
  saved_by uuid not null,
  note text check (note is null or length(note) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, item_id, saved_by),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict,
  foreign key (workspace_id, saved_by) references tonde.workspace_members(workspace_id, user_id) on delete restrict
);

drop trigger if exists guard_mutation on tonde.discover_saves;
create trigger guard_mutation before insert or update on tonde.discover_saves
  for each row execute function tonde_private.guard_mutation();

alter table tonde.discover_saves enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'discover_saves'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.discover_saves for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.discover_saves to authenticated;

grant all on tonde.discover_saves to service_role;


-- 3. Collections: saved inspiration the creator grouped on purpose.
create table if not exists tonde.discover_collections (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  name text not null check (length(btrim(name)) between 1 and 160),
  description text check (description is null or length(description) <= 1000),
  created_by uuid not null references auth.users(id) on delete restrict,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, name),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict
);

drop trigger if exists guard_mutation on tonde.discover_collections;
create trigger guard_mutation before insert or update on tonde.discover_collections
  for each row execute function tonde_private.guard_mutation();

alter table tonde.discover_collections enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'discover_collections'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.discover_collections for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.discover_collections to authenticated;

grant all on tonde.discover_collections to service_role;


create table if not exists tonde.discover_collection_items (
  workspace_id uuid not null,
  collection_id uuid not null,
  item_id uuid not null references tonde.discover_items(id) on delete restrict,
  added_by uuid not null references auth.users(id) on delete restrict,
  note text check (note is null or length(note) <= 1000),
  added_at timestamptz not null default now(),
  primary key (collection_id, item_id),
  foreign key (workspace_id, collection_id) references tonde.discover_collections(workspace_id, id) on delete restrict,
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict
);

alter table tonde.discover_collection_items enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'discover_collection_items'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.discover_collection_items for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.discover_collection_items to authenticated;

grant all on tonde.discover_collection_items to service_role;


-- 4. Applications: the two-step DIRECT THIS / USE THIS TECHNIQUE record.
create table if not exists tonde.discover_applications (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  item_id uuid not null references tonde.discover_items(id) on delete restrict,
  application_kind text not null check (application_kind in ('use_technique','attach_reference','direct_this')),
  production_id uuid not null,
  scene_id uuid,
  shot_id uuid,
  intent_note text check (intent_note is null or length(intent_note) <= 1000),
  impact jsonb not null check (jsonb_typeof(impact) = 'object'),
  state text not null default 'previewed' check (state in ('previewed','applied','withdrawn','expired')),
  applied_object_kind text check (applied_object_kind is null
    or applied_object_kind in ('creative_technique','production_reference')),
  applied_object_id uuid,
  previewed_by uuid references auth.users(id) on delete set null,
  previewed_at timestamptz not null default now(),
  applied_by uuid references auth.users(id) on delete set null,
  applied_at timestamptz,
  note text check (note is null or length(note) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict,
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, production_id, scene_id) references tonde.scenes(workspace_id, production_id, id) on delete restrict,
  foreign key (workspace_id, production_id, shot_id) references tonde.shots(workspace_id, production_id, id) on delete restrict,
  -- Applied means an object exists and a person applied it. Previewed means neither is true yet.
  constraint application_applied_is_stamped check (state <> 'applied'
    or (applied_at is not null and applied_by is not null and applied_object_kind is not null
      and applied_object_id is not null)),
  constraint application_preview_has_not_applied check (state = 'applied' or applied_object_id is null)
);

create unique index if not exists discover_application_live on tonde.discover_applications(workspace_id, item_id,
  application_kind, production_id, coalesce(scene_id, '00000000-0000-0000-0000-000000000000'::uuid),
  coalesce(shot_id, '00000000-0000-0000-0000-000000000000'::uuid))
  where state in ('previewed','applied');

create index if not exists discover_application_queue on tonde.discover_applications(workspace_id, state, previewed_at desc);

drop trigger if exists guard_mutation on tonde.discover_applications;
create trigger guard_mutation before insert or update on tonde.discover_applications
  for each row execute function tonde_private.guard_mutation();

alter table tonde.discover_applications enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'discover_applications'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.discover_applications for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.discover_applications to authenticated;

grant all on tonde.discover_applications to service_role;


-- 5. Guards. Curated content and applied work are both closed records.
create or replace function tonde_private.guard_discover_item() returns trigger
language plpgsql security definer set search_path = '' as $$
declare curator boolean := (select auth.role()) = 'service_role' or auth.uid() is null;
begin
  if tg_op = 'INSERT' then
    if new.visibility = 'global' or new.review_state = 'curated' then
      if not curator then
        raise exception 'Curated discover content is registered by TONDE, not by a workspace client'
          using errcode = '42501';
      end if;
    end if;
    return new;
  end if;
  -- Where an item came from, and what it is, never change after the fact.
  if new.canonical_id is distinct from old.canonical_id or new.visibility is distinct from old.visibility
    or new.workspace_id is distinct from old.workspace_id or new.item_kind is distinct from old.item_kind
    or new.source_kind is distinct from old.source_kind
    or new.source_technique_id is distinct from old.source_technique_id
    or new.source_tutorial_id is distinct from old.source_tutorial_id
    or new.source_reference_id is distinct from old.source_reference_id
    or new.source_media_id is distinct from old.source_media_id
    or new.provenance is distinct from old.provenance
    or new.registered_by is distinct from old.registered_by then
    raise exception 'Where a discover item came from never changes' using errcode = '23514';
  end if;
  if old.review_state = 'curated' and not curator then
    raise exception 'Curated discover content is edited by TONDE' using errcode = '42501';
  end if;
  return new;
end $$;

drop trigger if exists guard_discover_item on tonde.discover_items;
create trigger guard_discover_item before insert or update on tonde.discover_items
  for each row execute function tonde_private.guard_discover_item();

revoke all on function tonde_private.guard_discover_item() from public, anon, authenticated, service_role;


create or replace function tonde_private.guard_discover_application() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if new.state <> 'previewed' then
      raise exception 'An application is previewed first and applied afterwards' using errcode = '42501';
    end if;
    return new;
  end if;
  if old.state = 'applied' and (new.state is distinct from old.state
      or new.impact is distinct from old.impact or new.item_id is distinct from old.item_id
      or new.application_kind is distinct from old.application_kind
      or new.production_id is distinct from old.production_id
      or new.applied_object_kind is distinct from old.applied_object_kind
      or new.applied_object_id is distinct from old.applied_object_id
      or new.note is distinct from old.note) then
    raise exception 'An applied application is a closed record; what was created stays as it was recorded'
      using errcode = '23514';
  end if;
  if old.state in ('withdrawn','expired') and new.state = 'applied' then
    raise exception 'A withdrawn preview cannot be applied' using errcode = '23514';
  end if;
  if new.state = 'applied' and (new.applied_at is null or new.applied_by is null
      or new.applied_object_kind is null or new.applied_object_id is null) then
    raise exception 'An applied application names the object it created and who applied it'
      using errcode = '23514';
  end if;
  return new;
end $$;

drop trigger if exists guard_discover_application on tonde.discover_applications;
create trigger guard_discover_application before insert or update on tonde.discover_applications
  for each row execute function tonde_private.guard_discover_application();

revoke all on function tonde_private.guard_discover_application() from public, anon, authenticated, service_role;


-- 6. Private helpers. Usability is read from the live source row, never cached on the item.
create or replace function tonde_private.discover_source_state(item tonde.discover_items) returns text
language sql stable security definer set search_path = '' as $$
  select case
    when item.source_technique_id is not null then (
      select case when t.retired_at is not null then 'retired'
        when tonde_private.knowledge_is_usable(t.review_state, t.source_kind) then 'usable'
        else t.review_state end
      from tonde.creative_techniques t where t.id = item.source_technique_id)
    when item.source_tutorial_id is not null then (
      select case when u.state = 'published' then 'usable' else u.state end
      from tonde.knowledge_tutorials u where u.id = item.source_tutorial_id)
    when item.source_reference_id is not null then (
      select case when r.state = 'inaccessible' then 'unusable' else 'available' end
      from tonde.production_references r where r.id = item.source_reference_id)
    else 'authored' end;
$$;

revoke all on function tonde_private.discover_source_state(tonde.discover_items)
  from public, anon, authenticated, service_role;


create or replace function tonde_private.discover_is_usable(item tonde.discover_items) returns boolean
language sql stable security definer set search_path = '' as $$
  select tonde_private.discover_source_state(item) in ('usable','available','authored');
$$;

revoke all on function tonde_private.discover_is_usable(tonde.discover_items)
  from public, anon, authenticated, service_role;


-- Any workspace member may read; service_role reads on behalf of the platform.
create or replace function tonde_private.discover_member(target_workspace uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare actor uuid := (select auth.uid());
begin
  if (select auth.role()) = 'service_role' then return actor; end if;
  if actor is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  return actor;
end $$;

revoke all on function tonde_private.discover_member(uuid) from public, anon, authenticated, service_role;


-- Curation and application both read an item under the caller's visibility.
create or replace function tonde_private.discover_item_for(target_workspace uuid, target_item uuid) returns tonde.discover_items
language plpgsql stable security definer set search_path = '' as $$
declare item tonde.discover_items;
begin
  select * into item from tonde.discover_items i where i.id = target_item
    and (i.visibility = 'global' or i.workspace_id = target_workspace);
  if item.id is null then
    raise exception 'DISCOVER_ITEM_NOT_VISIBLE: that discover item is not visible to this workspace'
      using errcode = 'PT409';
  end if;
  return item;
end $$;

revoke all on function tonde_private.discover_item_for(uuid,uuid) from public, anon, authenticated, service_role;


-- What each action could do with this item, and the named reason when it could not.
create or replace function tonde_private.discover_support(item tonde.discover_items) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare state text := tonde_private.discover_source_state(item); usable boolean;
begin
  usable := state in ('usable','available','authored');
  return jsonb_build_object(
    'source_state', state,
    'usable', usable,
    'use_technique', case
      when item.source_technique_id is null and not (item.applicability ? 'category') then
        jsonb_build_object('available', false, 'reason', 'ITEM_HAS_NO_TECHNIQUE',
          'detail', 'This item carries no technique substance to add to the workspace.')
      when not usable then
        jsonb_build_object('available', false, 'reason', 'SOURCE_NOT_USABLE',
          'detail', format('The knowledge behind this item is %s, so it cannot guide a production.', state))
      else jsonb_build_object('available', true, 'reason', null, 'detail', null) end,
    'attach_reference', case
      when item.source_media_id is null
        and not (item.provenance ? 'locator' and length(btrim(coalesce(item.provenance ->> 'locator', ''))) > 0) then
        jsonb_build_object('available', false, 'reason', 'ITEM_HAS_NO_LOCATOR',
          'detail', 'This item names no accessible reference to attach.')
      when item.source_reference_id is not null and state = 'unusable' then
        jsonb_build_object('available', false, 'reason', 'REFERENCE_INACCESSIBLE',
          'detail', 'The reference this item came from is recorded as inaccessible.')
      else jsonb_build_object('available', true, 'reason', null, 'detail', null) end,
    'direct_this', case
      when length(btrim(item.directions)) = 0 then
        jsonb_build_object('available', false, 'reason', 'ITEM_HAS_NO_DIRECTIONS',
          'detail', 'This item states no directions to direct with.')
      else jsonb_build_object('available', true, 'reason', null, 'detail', null) end);
end $$;

revoke all on function tonde_private.discover_support(tonde.discover_items)
  from public, anon, authenticated, service_role;


-- A deterministic, copy-ready direction: the same item always states the same thing.
create or replace function tonde_private.discover_directive(item tonde.discover_items) returns text
language sql immutable set search_path = '' as $$
  select format('%s — %s%s', item.title, item.summary,
    case when length(btrim(item.directions)) = 0 then '' else ' Directions: ' || item.directions end);
$$;

revoke all on function tonde_private.discover_directive(tonde.discover_items)
  from public, anon, authenticated, service_role;


-- 7. Registering items. Knowledge only becomes discoverable while it is usable.
create or replace function tonde.discover_register_item(target_workspace uuid, p_item jsonb,
  p_visibility text default 'workspace') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; curator boolean := (select auth.role()) = 'service_role' or auth.uid() is null;
  item tonde.discover_items; existing tonde.discover_items; technique tonde.creative_techniques;
  tutorial tonde.knowledge_tutorials; reference tonde.production_references;
  -- The client's words and the column names are the same words; the locals are prefixed so no
  -- statement in this function can be ambiguous about which one it means.
  v_canonical text; v_kind text; v_source text; v_state text; v_applicability jsonb; v_provenance jsonb;
begin
  if jsonb_typeof(p_item) <> 'object' then
    raise exception 'A discover item is registered as an object' using errcode = '22023';
  end if;
  if p_visibility not in ('workspace','global') then
    raise exception 'A discover item is workspace-scoped or TONDE-curated' using errcode = '22023';
  end if;
  if p_visibility = 'global' then
    if not curator then
      raise exception 'Curated discover content is registered by TONDE' using errcode = '42501';
    end if;
    actor := null;
  else
    actor := tonde_private.knowledge_editor(target_workspace);
    if not exists (select 1 from tonde.workspaces w where w.id = target_workspace) then
      raise exception 'That workspace does not exist' using errcode = 'P0002';
    end if;
  end if;
  v_canonical := btrim(coalesce(p_item ->> 'canonical_id', ''));
  if v_canonical !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(v_canonical) not between 3 and 120 then
    raise exception 'A discover item needs a slug canonical id' using errcode = '22023';
  end if;
  v_kind := btrim(coalesce(p_item ->> 'item_kind', ''));
  if v_kind not in ('technique','knowledge','tutorial','reference_example','movie_reference','template',
    'inspiration') then
    raise exception 'That is not a TONDE discover item kind' using errcode = '22023';
  end if;
  v_source := btrim(coalesce(p_item ->> 'source_kind', ''));
  if v_source not in ('knowledge','tutorial','production_reference','creator','import','tonde_canon') then
    raise exception 'A discover item names where it came from' using errcode = '22023';
  end if;
  -- Only TONDE records canon content: a client can neither curate nor claim canon provenance.
  if v_source = 'tonde_canon' and not curator then
    raise exception 'Canon discover content is registered by TONDE' using errcode = '42501';
  end if;
  v_provenance := coalesce(p_item -> 'provenance', '{}'::jsonb);
  if jsonb_typeof(v_provenance) <> 'object'
    or length(btrim(coalesce(v_provenance ->> 'source_label', ''))) = 0 then
    raise exception 'Provenance must name the source it came from' using errcode = '22023';
  end if;
  v_applicability := coalesce(p_item -> 'applicability', '{}'::jsonb);
  if jsonb_typeof(v_applicability) <> 'object' then
    raise exception 'Applicability is recorded as an object' using errcode = '22023';
  end if;
  -- Knowledge, tutorials and references must exist here, and knowledge must be usable NOW.
  if v_source = 'knowledge' then
    select * into technique from tonde.creative_techniques t
      where t.workspace_id = target_workspace and t.id = (p_item ->> 'source_technique_id')::uuid;
    if technique.id is null then
      raise exception 'That knowledge item does not exist in this workspace' using errcode = 'P0002';
    end if;
    if technique.retired_at is not null then
      raise exception 'KNOWLEDGE_RETIRED: this knowledge was retired and cannot become discoverable'
        using errcode = 'PT409';
    end if;
    if not tonde_private.knowledge_is_usable(technique.review_state, technique.source_kind) then
      raise exception 'KNOWLEDGE_NOT_USABLE: this knowledge is % / % and cannot become discoverable',
        technique.review_state, technique.source_kind using errcode = 'PT409';
    end if;
    -- The item carries the source's own substance with the revision it was read at, never a paraphrase.
    v_applicability := v_applicability || jsonb_build_object('category', technique.category,
      'purpose', technique.purpose, 'effect', technique.effect, 'description', technique.description,
      'conditions', technique.conditions, 'limitations', technique.limitations,
      'importance', technique.importance, 'practical_concept', technique.practical_concept,
      'ai_concept', technique.ai_concept, 'confidence', technique.confidence,
      'knowledge_class', technique.knowledge_class,
      'source_revision', technique.revision, 'review_state', technique.review_state);
  elsif v_source = 'tutorial' then
    select * into tutorial from tonde.knowledge_tutorials u
      where u.workspace_id = target_workspace and u.id = (p_item ->> 'source_tutorial_id')::uuid;
    if tutorial.id is null then
      raise exception 'That tutorial does not exist in this workspace' using errcode = 'P0002';
    end if;
    if tutorial.state <> 'published' then
      raise exception 'TUTORIAL_NOT_PUBLISHED: this tutorial is % and is not yet discoverable', tutorial.state
        using errcode = 'PT409';
    end if;
    v_applicability := v_applicability || jsonb_build_object('step_count', tutorial.step_count,
      'source_kind', tutorial.source_kind, 'attribution', tutorial.attribution, 'license', tutorial.license);
  elsif v_source = 'production_reference' then
    select * into reference from tonde.production_references r
      where r.workspace_id = target_workspace and r.id = (p_item ->> 'source_reference_id')::uuid;
    if reference.id is null then
      raise exception 'That reference does not exist in this workspace' using errcode = 'P0002';
    end if;
    if reference.state = 'inaccessible' then
      raise exception 'REFERENCE_INACCESSIBLE: that reference is recorded as inaccessible'
        using errcode = 'PT409';
    end if;
    v_applicability := v_applicability || jsonb_build_object('source_type', reference.source_type,
      'rights_classification', reference.rights_classification, 'state', reference.state);
  end if;
  v_state := case when curator and p_visibility = 'global' then 'curated' else 'creator_asserted' end;
  select * into existing from tonde.discover_items i where i.canonical_id = v_canonical
    and i.workspace_id is not distinct from (case when p_visibility = 'global' then null else target_workspace end);
  if existing.id is not null then
    update tonde.discover_items set title = btrim(p_item ->> 'title'), summary = btrim(p_item ->> 'summary'),
      directions = coalesce(p_item ->> 'directions', ''), applicability = v_applicability,
      notes = nullif(left(coalesce(p_item ->> 'notes', ''), 1000), ''), updated_at = now()
      where id = existing.id returning * into item;
    if item.workspace_id is not null then
      perform tonde_private.audit_event(target_workspace, 'discover.item_reregistered', item.id, 'discover_item',
        jsonb_build_object('canonical_id', v_canonical, 'item_kind', v_kind, 'source_kind', v_source,
          'source_state', tonde_private.discover_source_state(item)));
    end if;
    return jsonb_build_object('item_id', item.id, 'canonical_id', item.canonical_id, 'visibility', item.visibility,
      'item_kind', item.item_kind, 'review_state', item.review_state,
      'source_state', tonde_private.discover_source_state(item), 'usable', tonde_private.discover_is_usable(item),
      'support', tonde_private.discover_support(item), 'replaced_existing', true, 'idempotent', true,
      'meaning', 'The item was already here; its content was updated and its provenance left exactly as it was.');
  end if;
  insert into tonde.discover_items(workspace_id, visibility, canonical_id, item_kind, title, summary,
    directions, applicability, provenance, source_kind, source_technique_id, source_tutorial_id,
    source_reference_id, source_media_id, review_state, registered_by, notes)
  values (case when p_visibility = 'global' then null else target_workspace end, p_visibility, v_canonical,
    v_kind, btrim(p_item ->> 'title'), btrim(p_item ->> 'summary'), coalesce(p_item ->> 'directions', ''),
    v_applicability, v_provenance, v_source, (p_item ->> 'source_technique_id')::uuid,
    (p_item ->> 'source_tutorial_id')::uuid, (p_item ->> 'source_reference_id')::uuid,
    (p_item ->> 'source_media_id')::uuid, v_state, actor,
    nullif(left(coalesce(p_item ->> 'notes', ''), 1000), ''))
  returning * into item;
  if item.workspace_id is not null then
    perform tonde_private.audit_event(target_workspace, 'discover.item_registered', item.id, 'discover_item',
      jsonb_build_object('canonical_id', v_canonical, 'item_kind', v_kind, 'source_kind', v_source,
        'source_state', tonde_private.discover_source_state(item)));
  end if;
  return jsonb_build_object('item_id', item.id, 'canonical_id', item.canonical_id, 'visibility', item.visibility,
    'item_kind', item.item_kind, 'review_state', item.review_state,
    'source_state', tonde_private.discover_source_state(item), 'usable', tonde_private.discover_is_usable(item),
    'support', tonde_private.discover_support(item), 'replaced_existing', false, 'idempotent', false,
    'meaning', case when tonde_private.discover_is_usable(item)
      then 'The item is discoverable and states where it came from and what it can do.'
      else 'The item is recorded but its source is not usable, so it can guide nothing yet.' end);
end $$;

revoke all on function tonde.discover_register_item(uuid,jsonb,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_register_item(uuid,jsonb,text) to authenticated, service_role;


-- 8. Reading Discover. Usability is re-read from the live source on every call.
create or replace function tonde.discover_index(target_workspace uuid, p_kind text default null, p_query text default null,
  p_limit integer default 50) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; items jsonb; total integer;
begin
  actor := tonde_private.discover_member(target_workspace);
  if p_kind is not null and p_kind not in ('technique','knowledge','tutorial','reference_example',
    'movie_reference','template','inspiration') then
    raise exception 'That is not a TONDE discover item kind' using errcode = '22023';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'A discover page is between 1 and 200 items' using errcode = '22023';
  end if;
  if p_query is not null and length(p_query) > 200 then
    raise exception 'A discover search is at most 200 characters' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(entry order by entry ->> 'item_kind', entry ->> 'title'), '[]'::jsonb),
    count(*)::integer
    into items, total
    from (
      select jsonb_build_object('item_id', i.id, 'canonical_id', i.canonical_id, 'item_kind', i.item_kind,
        'title', i.title, 'summary', i.summary, 'visibility', i.visibility, 'review_state', i.review_state,
        'provenance', i.provenance, 'applicability', i.applicability,
        'source_state', tonde_private.discover_source_state(i),
        'usable', tonde_private.discover_is_usable(i),
        'support', tonde_private.discover_support(i),
        'saved', actor is not null and exists (select 1 from tonde.discover_saves s
          where s.workspace_id = target_workspace and s.item_id = i.id and s.saved_by = actor),
        'save_count', (select count(*) from tonde.discover_saves s
          where s.workspace_id = target_workspace and s.item_id = i.id),
        'applied', exists (select 1 from tonde.discover_applications a
          where a.workspace_id = target_workspace and a.item_id = i.id and a.state = 'applied')) as entry
      from tonde.discover_items i
      where (i.visibility = 'global' or i.workspace_id = target_workspace)
        and (p_kind is null or i.item_kind = p_kind)
        and (p_query is null or i.title ilike '%' || p_query || '%' or i.summary ilike '%' || p_query || '%'
          or i.directions ilike '%' || p_query || '%' or i.canonical_id ilike '%' || p_query || '%')
      order by i.item_kind, i.title limit p_limit) listed;
  return jsonb_build_object('workspace_id', target_workspace, 'items', items, 'count', total,
    'kind', p_kind, 'query', p_query, 'limit', p_limit,
    'meaning', 'Every item states where it came from and whether its source is usable right now. An item
      whose source is not usable is listed with that state and cannot be applied.');
end $$;

revoke all on function tonde.discover_index(uuid,text,text,integer)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_index(uuid,text,text,integer) to authenticated, service_role;


create or replace function tonde.discover_item_status(target_workspace uuid, target_item uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; item tonde.discover_items; support jsonb;
begin
  actor := tonde_private.discover_member(target_workspace);
  item := tonde_private.discover_item_for(target_workspace, target_item);
  support := tonde_private.discover_support(item);
  return jsonb_build_object('item_id', item.id, 'canonical_id', item.canonical_id, 'item_kind', item.item_kind,
    'title', item.title, 'summary', item.summary, 'directions', item.directions,
    'applicability', item.applicability, 'provenance', item.provenance,
    'visibility', item.visibility, 'review_state', item.review_state,
    'source_state', support ->> 'source_state', 'usable', (support ->> 'usable')::boolean,
    'support', support, 'directive', tonde_private.discover_directive(item),
    'saved_by_you', actor is not null and exists (select 1 from tonde.discover_saves s
      where s.workspace_id = target_workspace and s.item_id = item.id and s.saved_by = actor),
    'saves', (select coalesce(jsonb_agg(jsonb_build_object('saved_by', s.saved_by, 'note', s.note,
        'saved_at', s.created_at) order by s.created_at), '[]'::jsonb)
      from tonde.discover_saves s where s.workspace_id = target_workspace and s.item_id = item.id),
    'collections', (select coalesce(jsonb_agg(jsonb_build_object('collection_id', c.id, 'name', c.name)
        order by c.name), '[]'::jsonb)
      from tonde.discover_collection_items ci join tonde.discover_collections c on c.id = ci.collection_id
      where ci.workspace_id = target_workspace and ci.item_id = item.id),
    'applications', (select coalesce(jsonb_agg(jsonb_build_object('application_id', a.id,
        'application_kind', a.application_kind, 'production_id', a.production_id, 'scene_id', a.scene_id,
        'shot_id', a.shot_id, 'state', a.state, 'applied_object_kind', a.applied_object_kind,
        'applied_object_id', a.applied_object_id, 'previewed_at', a.previewed_at, 'applied_at', a.applied_at)
        order by a.previewed_at desc), '[]'::jsonb)
      from tonde.discover_applications a where a.workspace_id = target_workspace and a.item_id = item.id),
    'meaning', 'What this item is, where it came from, what can be done with it right now, and every
      application of it in this workspace.');
end $$;

revoke all on function tonde.discover_item_status(uuid,uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.discover_item_status(uuid,uuid) to authenticated, service_role;


-- 9. SAVE REFERENCE, and collections of saved inspiration.
create or replace function tonde.discover_save(target_workspace uuid, target_item uuid, p_note text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; item tonde.discover_items; existing tonde.discover_saves; saved tonde.discover_saves;
begin
  actor := tonde_private.discover_member(target_workspace);
  if actor is null then
    raise exception 'A save belongs to a person, not to the platform' using errcode = '42501';
  end if;
  item := tonde_private.discover_item_for(target_workspace, target_item);
  select * into existing from tonde.discover_saves s
    where s.workspace_id = target_workspace and s.item_id = item.id and s.saved_by = actor;
  if existing.id is not null then
    if coalesce(p_note, '') is not distinct from coalesce(existing.note, '') then
      return jsonb_build_object('save_id', existing.id, 'item_id', item.id, 'idempotent', true,
        'meaning', 'This item was already saved by you, with the same note.');
    end if;
    update tonde.discover_saves set note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
      where id = existing.id returning * into saved;
    return jsonb_build_object('save_id', saved.id, 'item_id', item.id, 'idempotent', true,
      'meaning', 'The save was already there; its note is updated.');
  end if;
  insert into tonde.discover_saves(workspace_id, item_id, saved_by, note)
  values (target_workspace, item.id, actor, nullif(left(coalesce(p_note, ''), 1000), ''))
  returning * into saved;
  perform tonde_private.audit_event(target_workspace, 'discover.saved', saved.id, 'discover_item',
    jsonb_build_object('item_id', item.id, 'canonical_id', item.canonical_id));
  return jsonb_build_object('save_id', saved.id, 'item_id', item.id, 'idempotent', false,
    'meaning', 'Saved as a reference for later. Nothing about a production changed.');
end $$;

revoke all on function tonde.discover_save(uuid,uuid,text) from public, anon, authenticated, service_role;

grant execute on function tonde.discover_save(uuid,uuid,text) to authenticated, service_role;


create or replace function tonde.discover_unsave(target_workspace uuid, target_item uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; item tonde.discover_items; removed integer;
begin
  actor := tonde_private.discover_member(target_workspace);
  if actor is null then
    raise exception 'A save belongs to a person, not to the platform' using errcode = '42501';
  end if;
  item := tonde_private.discover_item_for(target_workspace, target_item);
  delete from tonde.discover_saves s where s.workspace_id = target_workspace and s.item_id = item.id
    and s.saved_by = actor;
  get diagnostics removed := row_count;
  if removed = 0 then
    raise exception 'SAVE_NOT_FOUND: you had not saved that item' using errcode = 'PT409';
  end if;
  return jsonb_build_object('item_id', item.id, 'removed', removed,
    'meaning', 'The save is gone. The item itself is unchanged.');
end $$;

revoke all on function tonde.discover_unsave(uuid,uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.discover_unsave(uuid,uuid) to authenticated, service_role;


create or replace function tonde.discover_collection_create(target_workspace uuid, p_name text, p_description text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; collection tonde.discover_collections; existing tonde.discover_collections;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'A collection needs a name' using errcode = '22023';
  end if;
  select * into existing from tonde.discover_collections c
    where c.workspace_id = target_workspace and c.name = btrim(p_name);
  if existing.id is not null then
    return jsonb_build_object('collection_id', existing.id, 'name', existing.name, 'idempotent', true);
  end if;
  insert into tonde.discover_collections(workspace_id, name, description, created_by)
  values (target_workspace, left(btrim(p_name), 160), nullif(left(coalesce(p_description, ''), 1000), ''), actor)
  returning * into collection;
  perform tonde_private.audit_event(target_workspace, 'discover.collection_created', collection.id,
    'discover_collection', jsonb_build_object('name', collection.name));
  return jsonb_build_object('collection_id', collection.id, 'name', collection.name, 'idempotent', false);
end $$;

revoke all on function tonde.discover_collection_create(uuid,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_collection_create(uuid,text,text) to authenticated, service_role;


create or replace function tonde.discover_collection_add(target_workspace uuid, target_collection uuid, target_item uuid,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; collection tonde.discover_collections; item tonde.discover_items; existing integer;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  select * into collection from tonde.discover_collections c
    where c.workspace_id = target_workspace and c.id = target_collection;
  if collection.id is null then
    raise exception 'That collection does not exist' using errcode = 'P0002';
  end if;
  item := tonde_private.discover_item_for(target_workspace, target_item);
  select count(*) into existing from tonde.discover_collection_items ci
    where ci.collection_id = collection.id and ci.item_id = item.id;
  if existing > 0 then
    return jsonb_build_object('collection_id', collection.id, 'item_id', item.id, 'idempotent', true);
  end if;
  insert into tonde.discover_collection_items(workspace_id, collection_id, item_id, added_by, note)
  values (target_workspace, collection.id, item.id, actor, nullif(left(coalesce(p_note, ''), 1000), ''));
  return jsonb_build_object('collection_id', collection.id, 'item_id', item.id, 'idempotent', false);
end $$;

revoke all on function tonde.discover_collection_add(uuid,uuid,uuid,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_collection_add(uuid,uuid,uuid,text) to authenticated, service_role;


create or replace function tonde.discover_collection_remove(target_workspace uuid, target_collection uuid, target_item uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; removed integer;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  delete from tonde.discover_collection_items ci where ci.workspace_id = target_workspace
    and ci.collection_id = target_collection and ci.item_id = target_item;
  get diagnostics removed := row_count;
  if removed = 0 then
    raise exception 'COLLECTION_ITEM_NOT_FOUND: that item is not in that collection' using errcode = 'PT409';
  end if;
  return jsonb_build_object('collection_id', target_collection, 'item_id', target_item, 'removed', removed);
end $$;

revoke all on function tonde.discover_collection_remove(uuid,uuid,uuid)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_collection_remove(uuid,uuid,uuid) to authenticated, service_role;


-- 10. DIRECT THIS / USE THIS TECHNIQUE: a preview that creates nothing, then the creator's apply.
create or replace function tonde.discover_preview(target_workspace uuid, target_item uuid, p_kind text,
  target_production uuid, target_scene uuid default null, target_shot uuid default null,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; item tonde.discover_items; support jsonb; production tonde.productions;
  existing tonde.discover_applications; application tonde.discover_applications; v_impact jsonb;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  item := tonde_private.discover_item_for(target_workspace, target_item);
  support := tonde_private.discover_support(item);
  if p_kind is null or p_kind not in ('use_technique','attach_reference','direct_this') then
    raise exception 'That is not a TONDE discover action' using errcode = '22023';
  end if;
  if not (support -> p_kind ->> 'available')::boolean then
    raise exception '%: %', support -> p_kind ->> 'reason', support -> p_kind ->> 'detail'
      using errcode = 'PT409';
  end if;
  select * into production from tonde.productions p
    where p.workspace_id = target_workspace and p.id = target_production;
  if production.id is null then
    raise exception 'That Production does not exist' using errcode = 'P0002';
  end if;
  if target_scene is not null and not exists (select 1 from tonde.scenes s
      where s.workspace_id = target_workspace and s.production_id = production.id and s.id = target_scene) then
    raise exception 'That scene does not exist in this Production' using errcode = 'P0002';
  end if;
  if target_shot is not null and not exists (select 1 from tonde.shots sh
      where sh.workspace_id = target_workspace and sh.production_id = production.id and sh.id = target_shot) then
    raise exception 'That shot does not exist in this Production' using errcode = 'P0002';
  end if;
  -- The preview states exactly what applying would create, and that string is the confirmation.
  v_impact := jsonb_build_object('application_kind', p_kind, 'item_id', item.id, 'canonical_id', item.canonical_id,
    'item_kind', item.item_kind, 'title', item.title, 'source_state', support ->> 'source_state',
    'production_id', production.id, 'production_title', production.title, 'scene_id', target_scene,
    'shot_id', target_shot, 'confirmation', item.canonical_id,
    'changes', case p_kind
      when 'use_technique' then jsonb_build_array(jsonb_build_object('object', 'creative_technique',
        'action', 'create_or_reuse', 'detail', format('A workspace technique "%s" carrying this item''s own substance.',
          item.title), 'canonical_id', item.canonical_id,
        'category', item.applicability ->> 'category'))
      when 'attach_reference' then jsonb_build_array(jsonb_build_object('object', 'production_reference',
        'action', 'create', 'detail', format('A reference on "%s" pointing at where this item came from.',
          production.title), 'locator', item.provenance ->> 'locator'))
      else jsonb_build_array(jsonb_build_object('object', 'production_reference', 'action', 'create',
        'detail', format('A description reference on "%s" carrying these directions.', production.title),
        'source_type', 'description'))
    end,
    'creates_nothing', true,
    'meaning', 'This is a preview. Nothing has been created. Applying is a separate decision that requires
      the canonical id to be typed back.');
  select * into existing from tonde.discover_applications a
    where a.workspace_id = target_workspace and a.item_id = item.id and a.application_kind = p_kind
      and a.production_id = production.id
      and a.scene_id is not distinct from target_scene and a.shot_id is not distinct from target_shot
      and a.state = 'previewed';
  if existing.id is not null then
    return jsonb_build_object('application_id', existing.id, 'state', existing.state, 'impact', existing.impact,
      'idempotent', true, 'meaning', 'This preview was already open; it is the same draft.');
  end if;
  insert into tonde.discover_applications(workspace_id, item_id, application_kind, production_id, scene_id,
    shot_id, intent_note, impact, previewed_by)
  values (target_workspace, item.id, p_kind, production.id, target_scene, target_shot,
    nullif(left(coalesce(p_note, ''), 1000), ''), v_impact, actor)
  returning * into application;
  perform tonde_private.audit_event(target_workspace, 'discover.previewed', application.id, 'discover_application',
    jsonb_build_object('item_id', item.id, 'application_kind', p_kind, 'production_id', production.id,
      'scene_id', target_scene, 'shot_id', target_shot));
  return jsonb_build_object('application_id', application.id, 'state', application.state,
    'impact', application.impact, 'idempotent', false,
    'meaning', 'The preview is recorded and nothing was created.');
end $$;

revoke all on function tonde.discover_preview(uuid,uuid,text,uuid,uuid,uuid,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_preview(uuid,uuid,text,uuid,uuid,uuid,text)
  to authenticated, service_role;


create or replace function tonde.discover_apply(target_workspace uuid, target_application uuid, p_confirmation text,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; application tonde.discover_applications; item tonde.discover_items; support jsonb;
  production tonde.productions; technique tonde.creative_techniques; reference tonde.production_references;
  v_object_kind text; v_object_id uuid; v_locator text; v_source_type tonde.reference_source;
  v_rights tonde.reference_rights; v_category text;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  select * into application from tonde.discover_applications a
    where a.workspace_id = target_workspace and a.id = target_application for update;
  if application.id is null then
    raise exception 'That discover application does not exist' using errcode = 'P0002';
  end if;
  if application.state = 'applied' then
    return jsonb_build_object('application_id', application.id, 'state', 'applied', 'idempotent', true,
      'applied_object_kind', application.applied_object_kind, 'applied_object_id', application.applied_object_id);
  end if;
  if application.state <> 'previewed' then
    raise exception 'APPLICATION_NOT_OPEN: this application is % and cannot be applied', application.state
      using errcode = 'PT409';
  end if;
  item := tonde_private.discover_item_for(target_workspace, application.item_id);
  if coalesce(btrim(p_confirmation), '') <> item.canonical_id then
    raise exception 'APPLICATION_CONFIRMATION_REQUIRED: type the item''s canonical id (% ) to apply it',
      item.canonical_id using errcode = 'PT409';
  end if;
  -- The world may have moved since the preview: re-check the source and the target.
  support := tonde_private.discover_support(item);
  if not (support -> application.application_kind ->> 'available')::boolean then
    raise exception 'APPLICATION_NO_LONGER_VALID: %: %', support -> application.application_kind ->> 'reason',
      support -> application.application_kind ->> 'detail' using errcode = 'PT409';
  end if;
  select * into production from tonde.productions p
    where p.workspace_id = target_workspace and p.id = application.production_id;
  if production.id is null then
    raise exception 'That Production no longer exists' using errcode = 'P0002';
  end if;
  if application.application_kind = 'use_technique' then
    -- The creator's own technique, carrying the item's recorded substance and naming its origin. No
    -- category is invented: an item without one cannot become a workspace technique.
    v_category := nullif(item.applicability ->> 'category', '');
    if v_category is null or v_category not in ('camera','composition','lighting','blocking','performance',
      'product','edit','transition','sound','color','story','typography') then
      raise exception 'ITEM_HAS_NO_TECHNIQUE: this item records no technique category, so nothing is created'
        using errcode = 'PT409';
    end if;
    select * into technique from tonde.creative_techniques t
      where t.workspace_id = target_workspace and t.canonical_id = item.canonical_id;
    if technique.id is null then
      insert into tonde.creative_techniques(workspace_id, canonical_id, name, category, description, purpose,
        effect, conditions, practical_concept, ai_concept, limitations, importance, confidence,
        technique_source, knowledge_class, source_kind, applicability, tonde_guidance, created_by)
      values (target_workspace, item.canonical_id, item.title, v_category,
        left(coalesce(nullif(item.applicability ->> 'description', ''), item.summary), 1200),
        left(coalesce(nullif(item.applicability ->> 'purpose', ''), item.summary), 600),
        left(coalesce(nullif(item.applicability ->> 'effect', ''), item.summary), 600),
        coalesce(item.applicability -> 'conditions', '[]'::jsonb),
        left(coalesce(item.applicability ->> 'practical_concept', ''), 900),
        left(coalesce(item.applicability ->> 'ai_concept', ''), 900),
        coalesce(item.applicability -> 'limitations', '[]'::jsonb),
        coalesce(nullif(item.applicability ->> 'importance', ''), 'supporting'),
        coalesce(nullif(item.applicability ->> 'confidence', ''), 'medium'), 'reference',
        coalesce(nullif(item.applicability ->> 'knowledge_class', ''), 'technique'), 'reference',
        item.applicability, left(coalesce(item.applicability ->> 'ai_concept', ''), 4000), actor)
      returning * into technique;
    end if;
    v_object_kind := 'creative_technique'; v_object_id := technique.id;
  else
    v_locator := nullif(btrim(coalesce(item.provenance ->> 'locator', '')), '');
    v_rights := 'unknown';
    if coalesce(item.provenance ->> 'rights_classification', '') in ('user_owned','licensed','brand_owned',
        'authorized_identity','public_reference','third_party_inspiration','unknown') then
      v_rights := (item.provenance ->> 'rights_classification')::tonde.reference_rights;
    end if;
    if application.application_kind = 'direct_this' then
      v_source_type := 'description';
    elsif item.source_media_id is not null then
      v_source_type := 'asset';
    elsif item.item_kind = 'movie_reference' then
      v_source_type := 'movie';
    elsif v_locator ~ '^https?://' then
      v_source_type := 'url';
    else
      raise exception 'REFERENCE_LOCATOR_NOT_A_URL: this item''s locator is not an address that can be
        attached' using errcode = 'PT409';
    end if;
    insert into tonde.production_references(workspace_id, production_id, source_type, source_url,
      source_description, rights_classification, state, media_id, provenance)
    values (target_workspace, production.id, v_source_type,
      case when v_source_type in ('url','movie') then v_locator else null end,
      case when v_source_type = 'description' then left(item.directions, 4000)
        else left(item.summary, 4000) end,
      v_rights, 'received', item.source_media_id,
      jsonb_build_object('discover_item_id', item.id, 'canonical_id', item.canonical_id,
        'item_kind', item.item_kind, 'source_label', item.provenance ->> 'source_label',
        'attribution', item.provenance ->> 'attribution', 'license', item.provenance ->> 'license',
        'application_id', application.id))
    returning * into reference;
    v_object_kind := 'production_reference'; v_object_id := reference.id;
  end if;
  update tonde.discover_applications set state = 'applied', applied_object_kind = v_object_kind,
    applied_object_id = v_object_id, applied_by = actor, applied_at = now(),
    note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
    where id = application.id returning * into application;
  perform tonde_private.audit_event(target_workspace, 'discover.applied', application.id, 'discover_application',
    jsonb_build_object('item_id', item.id, 'application_kind', application.application_kind,
      'production_id', production.id, 'applied_object_kind', v_object_kind, 'applied_object_id', v_object_id,
      'confirmation', item.canonical_id));
  return jsonb_build_object('application_id', application.id, 'state', 'applied', 'idempotent', false,
    'applied_object_kind', v_object_kind, 'applied_object_id', v_object_id, 'production_id', production.id,
    'meaning', case v_object_kind
      when 'creative_technique' then format('"%s" is now a technique in this workspace, carrying its own
        recorded substance and naming where it came from.', item.title)
      else format('The reference is recorded on "%s" with the rights class it honestly has.', production.title)
      end);
end $$;

revoke all on function tonde.discover_apply(uuid,uuid,text,text) from public, anon, authenticated, service_role;

grant execute on function tonde.discover_apply(uuid,uuid,text,text) to authenticated, service_role;


create or replace function tonde.discover_withdraw(target_workspace uuid, target_application uuid, p_note text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; application tonde.discover_applications;
begin
  actor := tonde_private.knowledge_editor(target_workspace);
  select * into application from tonde.discover_applications a
    where a.workspace_id = target_workspace and a.id = target_application for update;
  if application.id is null then
    raise exception 'That discover application does not exist' using errcode = 'P0002';
  end if;
  if application.state = 'applied' then
    raise exception 'APPLICATION_ALREADY_APPLIED: what was applied is a real record; withdrawing does not
      remove it' using errcode = 'PT409';
  end if;
  if application.state = 'withdrawn' then
    return jsonb_build_object('application_id', application.id, 'state', 'withdrawn', 'idempotent', true);
  end if;
  update tonde.discover_applications set state = 'withdrawn',
    note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
    where id = application.id returning * into application;
  return jsonb_build_object('application_id', application.id, 'state', 'withdrawn', 'idempotent', false,
    'meaning', 'The preview is withdrawn. Nothing had been created, so nothing is removed.');
end $$;

revoke all on function tonde.discover_withdraw(uuid,uuid,text) from public, anon, authenticated, service_role;

grant execute on function tonde.discover_withdraw(uuid,uuid,text) to authenticated, service_role;


create or replace function tonde.discover_application_status(target_workspace uuid, target_application uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; application tonde.discover_applications; item tonde.discover_items;
begin
  actor := tonde_private.discover_member(target_workspace);
  select * into application from tonde.discover_applications a
    where a.workspace_id = target_workspace and a.id = target_application;
  if application.id is null then
    raise exception 'That discover application does not exist' using errcode = 'P0002';
  end if;
  item := tonde_private.discover_item_for(target_workspace, application.item_id);
  return jsonb_build_object('application_id', application.id, 'state', application.state,
    'application_kind', application.application_kind, 'item_id', item.id, 'canonical_id', item.canonical_id,
    'title', item.title, 'source_state', tonde_private.discover_source_state(item),
    'production_id', application.production_id, 'scene_id', application.scene_id, 'shot_id', application.shot_id,
    'impact', application.impact, 'applied_object_kind', application.applied_object_kind,
    'applied_object_id', application.applied_object_id, 'previewed_at', application.previewed_at,
    'previewed_by', application.previewed_by, 'applied_at', application.applied_at,
    'applied_by', application.applied_by, 'note', application.note,
    'meaning', 'A preview that created nothing, or the applied record naming the exact object it created.');
end $$;

revoke all on function tonde.discover_application_status(uuid,uuid)
  from public, anon, authenticated, service_role;

grant execute on function tonde.discover_application_status(uuid,uuid) to authenticated, service_role;


-- 11. The retention registry learns about discover data. Knowledge is durable: a routine sweep retains
--     it, and a creator-authorized workspace deletion is what removes workspace-scoped items.
insert into tonde.retention_classes(data_class, display_name, description, table_names, age_column,
  default_retention_days, purge_action, purge_exempt, purge_order) values
  ('discover_content','Discover content','Discover items, saves, collections and their members. Production
   knowledge is durable: a routine sweep retains it, a workspace deletion removes the workspace rows.',
   '{discover_items,discover_saves,discover_collections,discover_collection_items}','created_at',null,
   'retain',false,32),
  ('discover_application','Discover applications','Previews and the records of what applying created.',
   '{discover_applications}','created_at',null,'retain',false,34)
on conflict (data_class) do update set display_name = excluded.display_name,
  description = excluded.description, table_names = excluded.table_names, age_column = excluded.age_column,
  default_retention_days = excluded.default_retention_days, purge_action = excluded.purge_action,
  purge_exempt = excluded.purge_exempt, purge_order = excluded.purge_order, updated_at = now();


alter default privileges in schema tonde revoke execute on functions from public;

alter default privileges in schema tonde_private revoke execute on functions from public;


commit;

-- ==========================================================================
-- 202610050042_prompt11_observability.sql
-- ==========================================================================

-- Prompt 11 packet 042 — observability, health, readiness and the alert seam.
--
-- Deployment hardening is not a promise that everything is configured. It is the opposite: the system
-- must be able to say, in machine-readable form, what it can do right now, what it cannot, and why.
-- This packet adds exactly that, and nothing that claims more than the database can observe:
--
--   * METRICS ARE LIVE ROWS, never a cached dashboard number. Each metric is a count or an age read
--     from the durable tables (jobs, outbox, media, storage purge queue, deletions, discover) at the
--     moment it is asked for, and the payload says which window it was taken over.
--   * A SNAPSHOT IS EVIDENCE. Capturing metrics writes an immutable, idempotent record of what was
--     observed; an observation is never edited afterwards.
--   * ALERTS ARE DETERMINISTIC. A rule names one metric from a closed set, a comparator and a
--     threshold. Evaluation opens exactly one event per breaching rule, keeps observing it, and when
--     the metric comes back in range the SYSTEM resolves it with the evidence of its own observation —
--     never a human claiming recovery. A person can acknowledge an alert; nobody can fake a resolution.
--   * HEALTH answers "can this system work at all" from real invariants: the database answers, every
--     tenant table carries row level security, no job is stuck holding an expired lease, there are no
--     dead letters, no sweep or deletion is stuck mid-phase, and the storage purge backlog is not
--     silently growing.
--   * READINESS answers "what is configured for this deployment", dependency by dependency, naming the
--     row or function it read. A provider whose adapter was never verified against the real provider
--     reports 'degraded'; an unconfigured dependency reports 'not_configured'; nothing reports 'ready'
--     because a table merely exists. Email delivery has no configuration surface in this schema at all,
--     and readiness says so instead of implying that mail is sent.
--   * A RELEASE RECORD names the environment and the migration range that was applied. Only the
--     service role writes one; it is the traceability anchor the runbook points at.
begin;


-- 1. Operational snapshots: an immutable record of what the system looked like at a moment.
create table if not exists tonde.operational_snapshots (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  window_minutes integer not null check (window_minutes between 1 and 10080),
  cutoff_at timestamptz not null,
  metrics jsonb not null check (jsonb_typeof(metrics) = 'object'),
  source text not null default 'metrics_read' check (source in ('metrics_read','worker','schedule','manual')),
  captured_by uuid references auth.users(id) on delete set null,
  note text check (note is null or length(note) <= 1000),
  captured_at timestamptz not null default now(),
  constraint operational_snapshot_cutoff_is_hourly check (date_trunc('hour', cutoff_at) = cutoff_at),
  unique (workspace_id, window_minutes, cutoff_at),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict
);

create index if not exists operational_snapshots_recent on tonde.operational_snapshots(workspace_id, captured_at desc);

drop trigger if exists guard_mutation on tonde.operational_snapshots;
create trigger guard_mutation before insert or update on tonde.operational_snapshots
  for each row execute function tonde_private.guard_mutation();

alter table tonde.operational_snapshots enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'operational_snapshots'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.operational_snapshots for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.operational_snapshots to authenticated;

grant all on tonde.operational_snapshots to service_role;


-- 2. Alert rules. One metric from the closed set the metrics read actually produces.
create table if not exists tonde.alert_rules (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  name text not null check (length(btrim(name)) between 1 and 120),
  metric text not null check (metric in ('jobs_queued','jobs_running','jobs_failed','jobs_dead_letter',
    'jobs_timed_out','oldest_queued_seconds','expired_leases','reconciliation_pending','outbox_pending',
    'oldest_outbox_seconds','storage_purge_pending','media_awaiting_verification','deletion_requests_open',
    'settings_proposals_unsatisfied','scene_requirement_gaps','discover_previews_open','workers_live',
    'alerts_open')),
  comparator text not null check (comparator in ('gt','gte','lt','lte')),
  threshold numeric not null,
  severity text not null default 'warning' check (severity in ('info','warning','critical')),
  window_minutes integer not null default 60 check (window_minutes between 1 and 10080),
  enabled boolean not null default true,
  note text check (note is null or length(note) <= 1000),
  created_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, name),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict
);

drop trigger if exists guard_mutation on tonde.alert_rules;
create trigger guard_mutation before insert or update on tonde.alert_rules
  for each row execute function tonde_private.guard_mutation();

alter table tonde.alert_rules enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'alert_rules'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.alert_rules for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.alert_rules to authenticated;

grant all on tonde.alert_rules to service_role;


-- 3. Alert events. One live event per rule; the recovery is observed, not asserted.
create table if not exists tonde.alert_events (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  rule_id uuid not null,
  metric text not null,
  comparator text not null check (comparator in ('gt','gte','lt','lte')),
  threshold numeric not null,
  observed numeric not null,
  severity text not null check (severity in ('info','warning','critical')),
  state text not null default 'open' check (state in ('open','acknowledged','resolved')),
  detected_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  observations integer not null default 1 check (observations >= 1),
  acknowledged_by uuid references auth.users(id) on delete set null,
  acknowledged_at timestamptz,
  resolved_at timestamptz,
  resolution text check (resolution is null or resolution in ('observed_in_range','superseded_by_rule_change')),
  evidence jsonb not null default '{}'::jsonb check (jsonb_typeof(evidence) = 'object'),
  note text check (note is null or length(note) <= 1000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict,
  foreign key (workspace_id, rule_id) references tonde.alert_rules(workspace_id, id) on delete restrict,
  -- Acknowledged and resolved both say who and when; resolved says why.
  constraint alert_acknowledged_is_stamped check (state <> 'acknowledged'
    or (acknowledged_at is not null and acknowledged_by is not null)),
  constraint alert_resolved_is_stamped check (state <> 'resolved'
    or (resolved_at is not null and resolution is not null))
);

create unique index if not exists alert_event_live on tonde.alert_events(rule_id) where state in ('open','acknowledged');

create index if not exists alert_events_queue on tonde.alert_events(workspace_id, state, detected_at desc);

drop trigger if exists guard_mutation on tonde.alert_events;
create trigger guard_mutation before insert or update on tonde.alert_events
  for each row execute function tonde_private.guard_mutation();

alter table tonde.alert_events enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'alert_events'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.alert_events for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.alert_events to authenticated;

grant all on tonde.alert_events to service_role;


-- 4. Recorded health and readiness checks: what was checked, when, what was seen.
create table if not exists tonde.system_checks (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid,
  check_kind text not null check (check_kind in ('health','readiness')),
  state text not null check (state in ('ok','degraded','failed','not_configured')),
  summary jsonb not null check (jsonb_typeof(summary) = 'object'),
  checked_by uuid references auth.users(id) on delete set null,
  duration_ms integer check (duration_ms is null or duration_ms >= 0),
  checked_at timestamptz not null default now()
);

create index if not exists system_checks_recent on tonde.system_checks(check_kind, checked_at desc);

drop trigger if exists guard_mutation on tonde.system_checks;
create trigger guard_mutation before insert or update on tonde.system_checks
  for each row execute function tonde_private.guard_mutation();

alter table tonde.system_checks enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'system_checks'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.system_checks for select to authenticated
  using (workspace_id is not null and tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.system_checks to authenticated;

grant all on tonde.system_checks to service_role;


-- 5. Deployment releases: which migration range is applied where, and who recorded it.
create table if not exists tonde.deployment_releases (
  id uuid primary key default gen_random_uuid(),
  environment text not null check (environment in ('local','hosted','preview')),
  release_id text not null check (length(btrim(release_id)) between 1 and 120),
  migrated_through text not null check (length(btrim(migrated_through)) between 1 and 60),
  notes text check (notes is null or length(notes) <= 2000),
  evidence jsonb not null default '{}'::jsonb check (jsonb_typeof(evidence) = 'object'),
  recorded_by uuid references auth.users(id) on delete set null,
  recorded_at timestamptz not null default now(),
  unique (environment, migrated_through)
);

alter table tonde.deployment_releases enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'deployment_releases'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.deployment_releases for select to authenticated
  using (true)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.deployment_releases to authenticated;

grant all on tonde.deployment_releases to service_role;


-- 6. Guards. Evidence and release records do not change; an alert moves forward only.
create or replace function tonde_private.guard_operational_snapshot() returns trigger
language plpgsql security definer set search_path = '' as $$
declare curator boolean := (select auth.role()) = 'service_role' or auth.uid() is null;
begin
  if tg_op = 'DELETE' then
    if not curator then
      raise exception 'A recorded operational snapshot is evidence and is not deleted by a client'
        using errcode = '42501';
    end if;
    return old;
  end if;
  raise exception 'A recorded operational snapshot is evidence; it is never edited'
    using errcode = '23514';
end $$;

drop trigger if exists guard_operational_snapshot on tonde.operational_snapshots;
create trigger guard_operational_snapshot before update or delete on tonde.operational_snapshots
  for each row execute function tonde_private.guard_operational_snapshot();

revoke all on function tonde_private.guard_operational_snapshot()
  from public, anon, authenticated, service_role;


create or replace function tonde_private.guard_system_check() returns trigger
language plpgsql security definer set search_path = '' as $$
declare curator boolean := (select auth.role()) = 'service_role' or auth.uid() is null;
begin
  if tg_op = 'DELETE' then
    if not curator then
      raise exception 'A recorded check is evidence and is not deleted by a client' using errcode = '42501';
    end if;
    return old;
  end if;
  raise exception 'A recorded check states what was observed at a moment and is never rewritten'
    using errcode = '23514';
end $$;

drop trigger if exists guard_system_check on tonde.system_checks;
create trigger guard_system_check before update or delete on tonde.system_checks
  for each row execute function tonde_private.guard_system_check();

revoke all on function tonde_private.guard_system_check() from public, anon, authenticated, service_role;


create or replace function tonde_private.guard_deployment_release() returns trigger
language plpgsql security definer set search_path = '' as $$
declare curator boolean := (select auth.role()) = 'service_role' or auth.uid() is null;
begin
  if tg_op = 'DELETE' then
    if not curator then
      raise exception 'A release record is not deleted by a client' using errcode = '42501';
    end if;
    return old;
  end if;
  raise exception 'A release record states what was applied and is never rewritten'
    using errcode = '23514';
end $$;

drop trigger if exists guard_deployment_release on tonde.deployment_releases;
create trigger guard_deployment_release before update or delete on tonde.deployment_releases
  for each row execute function tonde_private.guard_deployment_release();

revoke all on function tonde_private.guard_deployment_release()
  from public, anon, authenticated, service_role;


create or replace function tonde_private.guard_alert_event() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    if new.state <> 'open' then
      raise exception 'An alert is opened by observation; it is acknowledged or resolved afterwards'
        using errcode = '42501';
    end if;
    return new;
  end if;
  if old.state = 'resolved' and (new.state is distinct from old.state or new.resolution is distinct from old.resolution
      or new.resolved_at is distinct from old.resolved_at
      or new.observed is distinct from old.observed or new.evidence is distinct from old.evidence) then
    raise exception 'A resolved alert is a closed record' using errcode = '23514';
  end if;
  if old.state = 'open' and new.state = 'acknowledged' then
    if new.acknowledged_at is null or new.acknowledged_by is null then
      raise exception 'Acknowledging an alert says who did it and when' using errcode = '23514';
    end if;
    return new;
  end if;
  if new.state = 'resolved' and old.state is distinct from 'resolved' then
    -- Resolution is written by the observation that recovers the metric, or by the rule change that
    -- supersedes the alert. Both set a private marker for the length of their own statement, so a direct
    -- write to resolved - by anyone, including the platform - is refused rather than taken on trust.
    if coalesce(current_setting('tonde.alert_resolution', true), '') <> new.resolution then
      raise exception 'An alert is resolved by the observation that recovers it, not by a direct write'
        using errcode = '42501';
    end if;
    return new;
  end if;
  return new;
end $$;

drop trigger if exists guard_alert_event on tonde.alert_events;
create trigger guard_alert_event before insert or update on tonde.alert_events
  for each row execute function tonde_private.guard_alert_event();

revoke all on function tonde_private.guard_alert_event() from public, anon, authenticated, service_role;


-- 7. Private helpers: who may read the operations surface, and the live metric arithmetic.
create or replace function tonde_private.observability_admin(target_workspace uuid) returns uuid
language plpgsql stable security definer set search_path = '' as $$
declare actor uuid := (select auth.uid());
begin
  if (select auth.role()) = 'service_role' then return actor; end if;
  if actor is null or not tonde_private.is_workspace_admin(target_workspace) then
    raise exception 'Operations authority required' using errcode = '42501';
  end if;
  return actor;
end $$;

revoke all on function tonde_private.observability_admin(uuid)
  from public, anon, authenticated, service_role;


-- Every number below is a live count or age from a durable table. Nothing is cached, estimated or
-- invented, and the flattening in `values` is the exact bridge the alert rules compare against.
create or replace function tonde_private.workspace_metrics(target_workspace uuid, p_window_minutes integer) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare payload jsonb; flattened jsonb;
begin
  select jsonb_build_object(
    'jobs', jsonb_build_object(
      'by_state', coalesce((select jsonb_object_agg(status, total) from (
        select j.status::text as status, count(*) as total from tonde.jobs j
        where j.workspace_id = target_workspace group by 1) states), '{}'::jsonb),
      'queued', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'queued'),
      'running', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status in ('leased','running')),
      'retrying', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'retrying'),
      'waiting', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'waiting'),
      'failed', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'failed'),
      'dead_letter', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'dead_letter'),
      'timed_out', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'timed_out'),
      'cancel_requested', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'cancel_requested'),
      'succeeded', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'succeeded')),
    'oldest_queued_seconds', (select coalesce(round(extract(epoch from (now() - min(j.available_at)))), 0)
      from tonde.jobs j where j.workspace_id = target_workspace and j.status = 'queued'),
    'expired_leases', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace
      and j.status in ('leased','running') and j.lease_expires_at is not null and j.lease_expires_at <= now()),
    'reconciliation_pending', (select count(*) from tonde.jobs j where j.workspace_id = target_workspace
      and j.reconciliation_required),
    'outbox', jsonb_build_object(
      'pending', (select count(*) from tonde.outbox_events o where o.workspace_id = target_workspace and o.state = 'pending'),
      'processing', (select count(*) from tonde.outbox_events o where o.workspace_id = target_workspace and o.state = 'processing'),
      'failed', (select count(*) from tonde.outbox_events o where o.workspace_id = target_workspace and o.state = 'failed'),
      'oldest_pending_seconds', (select coalesce(round(extract(epoch from (now() - min(o.available_at)))), 0)
        from tonde.outbox_events o where o.workspace_id = target_workspace and o.state = 'pending')),
    'storage_purge', jsonb_build_object(
      'pending', (select count(*) from tonde.storage_purge_queue q where q.workspace_id = target_workspace and q.state = 'pending'),
      'claimed', (select count(*) from tonde.storage_purge_queue q where q.workspace_id = target_workspace and q.state = 'claimed'),
      'failed', (select count(*) from tonde.storage_purge_queue q where q.workspace_id = target_workspace and q.state = 'failed')),
    'media_awaiting_verification', (select count(*) from tonde.media_files m where m.workspace_id = target_workspace
      and m.upload_state in ('uploading','verifying')),
    'deletion_requests_open', (select count(*) from tonde.deletion_requests d where d.workspace_id = target_workspace
      and d.state not in ('completed','failed','cancelled')),
    'settings_proposals_unsatisfied', (select count(*) from tonde.camera_settings_proposals c
      where c.workspace_id = target_workspace and not c.satisfied and c.state = 'proposed'),
    'scene_requirement_gaps', (select count(*) from tonde.scene_requirements r where r.workspace_id = target_workspace
      and r.state = 'open' and r.mandatory),
    'discover_previews_open', (select count(*) from tonde.discover_applications a
      where a.workspace_id = target_workspace and a.state = 'previewed'),
    'workers_live', (select count(*) from tonde.workers w where w.status <> 'offline'
      and w.heartbeat_at > now() - interval '5 minutes'),
    'alerts_open', (select count(*) from tonde.alert_events e where e.workspace_id = target_workspace
      and e.state in ('open','acknowledged')))
    into payload;
  flattened := jsonb_build_object(
    'jobs_queued', payload -> 'jobs' ->> 'queued',
    'jobs_running', payload -> 'jobs' ->> 'running',
    'jobs_failed', payload -> 'jobs' ->> 'failed',
    'jobs_dead_letter', payload -> 'jobs' ->> 'dead_letter',
    'jobs_timed_out', payload -> 'jobs' ->> 'timed_out',
    'oldest_queued_seconds', payload ->> 'oldest_queued_seconds',
    'expired_leases', payload ->> 'expired_leases',
    'reconciliation_pending', payload ->> 'reconciliation_pending',
    'outbox_pending', payload -> 'outbox' ->> 'pending',
    'oldest_outbox_seconds', payload -> 'outbox' ->> 'oldest_pending_seconds',
    'storage_purge_pending', payload -> 'storage_purge' ->> 'pending',
    'media_awaiting_verification', payload ->> 'media_awaiting_verification',
    'deletion_requests_open', payload ->> 'deletion_requests_open',
    'settings_proposals_unsatisfied', payload ->> 'settings_proposals_unsatisfied',
    'scene_requirement_gaps', payload ->> 'scene_requirement_gaps',
    'discover_previews_open', payload ->> 'discover_previews_open',
    'workers_live', payload ->> 'workers_live',
    'alerts_open', payload ->> 'alerts_open');
  return payload || jsonb_build_object('workspace_id', target_workspace, 'window_minutes', p_window_minutes,
    'computed_at', now(), 'source', 'live rows',
    'values', (select jsonb_object_agg(key, value::numeric) from jsonb_each_text(flattened) entry(key, value)));
end $$;

revoke all on function tonde_private.workspace_metrics(uuid,integer)
  from public, anon, authenticated, service_role;


create or replace function tonde_private.metric_value(metrics jsonb, metric text) returns numeric
language sql immutable set search_path = '' as $$
  select nullif(metrics -> 'values' ->> metric, '')::numeric;
$$;

revoke all on function tonde_private.metric_value(jsonb,text)
  from public, anon, authenticated, service_role;


create or replace function tonde_private.rule_breached(observed numeric, comparator text, threshold numeric)
returns boolean language sql immutable set search_path = '' as $$
  select case comparator when 'gt' then observed > threshold when 'gte' then observed >= threshold
    when 'lt' then observed < threshold when 'lte' then observed <= threshold else null end;
$$;

revoke all on function tonde_private.rule_breached(numeric,text,numeric)
  from public, anon, authenticated, service_role;


-- 8. Reading and recording metrics.
create or replace function tonde.metrics_read(target_workspace uuid, p_window_minutes integer default 60) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; metrics jsonb;
begin
  actor := tonde_private.discover_member(target_workspace);
  if p_window_minutes is null or p_window_minutes < 1 or p_window_minutes > 10080 then
    raise exception 'A metrics window is between 1 and 10080 minutes' using errcode = '22023';
  end if;
  metrics := tonde_private.workspace_metrics(target_workspace, p_window_minutes);
  return jsonb_build_object('metrics', metrics,
    'meaning', 'These are live counts and ages read from the durable tables at this moment. Nothing here
      is cached and nothing is estimated; a metric that has no rows reports zero.');
end $$;

revoke all on function tonde.metrics_read(uuid,integer) from public, anon, authenticated, service_role;

grant execute on function tonde.metrics_read(uuid,integer) to authenticated, service_role;


create or replace function tonde.metrics_capture(target_workspace uuid, p_window_minutes integer default 60,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; metrics jsonb; cutoff timestamptz; existing tonde.operational_snapshots;
  snapshot tonde.operational_snapshots;
begin
  actor := tonde_private.observability_admin(target_workspace);
  if p_window_minutes is null or p_window_minutes < 1 or p_window_minutes > 10080 then
    raise exception 'A metrics window is between 1 and 10080 minutes' using errcode = '22023';
  end if;
  -- The cutoff is truncated to the hour so the same observation window is one record, not many.
  cutoff := date_trunc('hour', now());
  select * into existing from tonde.operational_snapshots s
    where s.workspace_id = target_workspace and s.window_minutes = p_window_minutes and s.cutoff_at = cutoff;
  if existing.id is not null then
    return jsonb_build_object('snapshot_id', existing.id, 'cutoff_at', existing.cutoff_at,
      'captured_at', existing.captured_at, 'idempotent', true,
      'meaning', 'This window was already captured; the earlier observation stands.');
  end if;
  metrics := tonde_private.workspace_metrics(target_workspace, p_window_minutes);
  insert into tonde.operational_snapshots(workspace_id, window_minutes, cutoff_at, metrics, source,
    captured_by, note)
  values (target_workspace, p_window_minutes, cutoff, metrics, 'metrics_read', actor,
    nullif(left(coalesce(p_note, ''), 1000), ''))
  returning * into snapshot;
  perform tonde_private.audit_event(target_workspace, 'observability.metrics_captured', snapshot.id,
    'operational_snapshot', jsonb_build_object('window_minutes', p_window_minutes, 'cutoff_at', cutoff,
      'values', metrics -> 'values'));
  return jsonb_build_object('snapshot_id', snapshot.id, 'cutoff_at', snapshot.cutoff_at,
    'captured_at', snapshot.captured_at, 'window_minutes', snapshot.window_minutes,
    'metrics', snapshot.metrics, 'idempotent', false,
    'meaning', 'The observation is recorded as evidence. It is immutable and the same window is never
      captured twice.');
end $$;

revoke all on function tonde.metrics_capture(uuid,integer,text) from public, anon, authenticated, service_role;

grant execute on function tonde.metrics_capture(uuid,integer,text) to authenticated, service_role;


create or replace function tonde.snapshots_read(target_workspace uuid, p_limit integer default 24) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; snapshots jsonb;
begin
  actor := tonde_private.discover_member(target_workspace);
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'A snapshot page is between 1 and 200 records' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('snapshot_id', s.id, 'cutoff_at', s.cutoff_at,
    'captured_at', s.captured_at, 'window_minutes', s.window_minutes, 'values', s.metrics -> 'values',
    'note', s.note, 'captured_by', s.captured_by) order by s.captured_at desc), '[]'::jsonb)
    into snapshots
    from (select * from tonde.operational_snapshots s where s.workspace_id = target_workspace
      order by s.captured_at desc limit p_limit) s;
  return jsonb_build_object('workspace_id', target_workspace, 'snapshots', snapshots, 'count', jsonb_array_length(snapshots));
end $$;

revoke all on function tonde.snapshots_read(uuid,integer) from public, anon, authenticated, service_role;

grant execute on function tonde.snapshots_read(uuid,integer) to authenticated, service_role;


-- 9. Alert rules, evaluation and acknowledgement.
create or replace function tonde.alert_rule_set(target_workspace uuid, p_name text, p_metric text, p_comparator text,
  p_threshold numeric, p_severity text default 'warning', p_window_minutes integer default 60,
  p_enabled boolean default true, p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; existing tonde.alert_rules; rule tonde.alert_rules;
begin
  actor := tonde_private.observability_admin(target_workspace);
  if length(btrim(coalesce(p_name, ''))) = 0 then
    raise exception 'An alert rule needs a name' using errcode = '22023';
  end if;
  if p_metric not in ('jobs_queued','jobs_running','jobs_failed','jobs_dead_letter','jobs_timed_out',
    'oldest_queued_seconds','expired_leases','reconciliation_pending','outbox_pending','oldest_outbox_seconds',
    'storage_purge_pending','media_awaiting_verification','deletion_requests_open',
    'settings_proposals_unsatisfied','scene_requirement_gaps','discover_previews_open','workers_live',
    'alerts_open') then
    raise exception 'That is not a metric this system observes' using errcode = '22023';
  end if;
  if p_comparator not in ('gt','gte','lt','lte') then
    raise exception 'A rule compares with gt, gte, lt or lte' using errcode = '22023';
  end if;
  if p_threshold is null then
    raise exception 'A rule needs a threshold' using errcode = '22023';
  end if;
  if p_severity not in ('info','warning','critical') then
    raise exception 'That is not a TONDE alert severity' using errcode = '22023';
  end if;
  if p_window_minutes is null or p_window_minutes < 1 or p_window_minutes > 10080 then
    raise exception 'A metrics window is between 1 and 10080 minutes' using errcode = '22023';
  end if;
  select * into existing from tonde.alert_rules r
    where r.workspace_id = target_workspace and r.name = btrim(p_name);
  if existing.id is not null then
    update tonde.alert_rules set metric = p_metric, comparator = p_comparator, threshold = p_threshold,
      severity = p_severity, window_minutes = p_window_minutes, enabled = coalesce(p_enabled, true),
      note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
      where id = existing.id returning * into rule;
    -- A rule that changed its meaning cannot keep an old event against it: the event is resolved as
    -- superseded, with the change recorded as the reason.
    perform set_config('tonde.alert_resolution', 'superseded_by_rule_change', true);
    update tonde.alert_events e set state = 'resolved', resolved_at = now(),
      resolution = 'superseded_by_rule_change', updated_at = now(),
      evidence = e.evidence || jsonb_build_object('superseded_by_rule_change', true,
        'previous_metric', e.metric, 'previous_threshold', e.threshold, 'new_metric', p_metric,
        'new_threshold', p_threshold)
      where e.rule_id = rule.id and e.state in ('open','acknowledged')
        and (e.metric <> p_metric or e.threshold <> p_threshold or e.comparator <> p_comparator);
    perform set_config('tonde.alert_resolution', '', true);
    perform tonde_private.audit_event(target_workspace, 'observability.alert_rule_updated', rule.id,
      'alert_rule', jsonb_build_object('name', rule.name, 'metric', rule.metric,
        'comparator', rule.comparator, 'threshold', rule.threshold, 'severity', rule.severity));
    return jsonb_build_object('rule_id', rule.id, 'name', rule.name, 'metric', rule.metric,
      'comparator', rule.comparator, 'threshold', rule.threshold, 'severity', rule.severity,
      'window_minutes', rule.window_minutes, 'enabled', rule.enabled, 'replaced_existing', true,
      'meaning', 'The rule is updated, and any live alert that was opened against the old meaning is
        resolved as superseded rather than left pointing at a rule that no longer says that.');
  end if;
  insert into tonde.alert_rules(workspace_id, name, metric, comparator, threshold, severity, window_minutes,
    enabled, note, created_by)
  values (target_workspace, left(btrim(p_name), 120), p_metric, p_comparator, p_threshold, p_severity,
    p_window_minutes, coalesce(p_enabled, true), nullif(left(coalesce(p_note, ''), 1000), ''), actor)
  returning * into rule;
  perform tonde_private.audit_event(target_workspace, 'observability.alert_rule_created', rule.id,
    'alert_rule', jsonb_build_object('name', rule.name, 'metric', rule.metric, 'comparator', rule.comparator,
      'threshold', rule.threshold, 'severity', rule.severity));
  return jsonb_build_object('rule_id', rule.id, 'name', rule.name, 'metric', rule.metric,
    'comparator', rule.comparator, 'threshold', rule.threshold, 'severity', rule.severity,
    'window_minutes', rule.window_minutes, 'enabled', rule.enabled, 'replaced_existing', false,
    'meaning', 'The rule is recorded. It fires nothing by itself: evaluation compares it against live
      metrics and records what it observed.');
end $$;

revoke all on function tonde.alert_rule_set(uuid,text,text,text,numeric,text,integer,boolean,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.alert_rule_set(uuid,text,text,text,numeric,text,integer,boolean,text)
  to authenticated, service_role;


create or replace function tonde.alert_evaluate(target_workspace uuid, p_limit integer default 100) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; metrics jsonb; rule tonde.alert_rules; event tonde.alert_events;
  v_observed numeric; breached boolean; outcomes jsonb := '[]'::jsonb; opened integer := 0;
  updated integer := 0; resolved integer := 0; skipped integer := 0; evaluated integer := 0;
begin
  actor := tonde_private.observability_admin(target_workspace);
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'An alert evaluation is between 1 and 500 rules' using errcode = '22023';
  end if;
  metrics := tonde_private.workspace_metrics(target_workspace, 60);
  for rule in select * from tonde.alert_rules r where r.workspace_id = target_workspace and r.enabled
    order by r.name limit p_limit loop
    evaluated := evaluated + 1;
    v_observed := tonde_private.metric_value(metrics, rule.metric);
    if v_observed is null then
      skipped := skipped + 1;
      outcomes := outcomes || jsonb_build_object('rule_id', rule.id, 'metric', rule.metric,
        'outcome', 'metric_unavailable', 'reason', 'the metrics read produced no value for this metric');
      continue;
    end if;
    breached := tonde_private.rule_breached(v_observed, rule.comparator, rule.threshold);
    select * into event from tonde.alert_events e where e.rule_id = rule.id and e.state in ('open','acknowledged')
      order by e.detected_at desc limit 1;
    if breached then
      if event.id is null then
        insert into tonde.alert_events(workspace_id, rule_id, metric, comparator, threshold, observed,
          severity, state, evidence)
        values (target_workspace, rule.id, rule.metric, rule.comparator, rule.threshold, v_observed,
          rule.severity, 'open', jsonb_build_object('first_observation', v_observed, 'window_minutes', 60,
            'evaluated_by', coalesce(actor::text, 'service_role')))
        returning * into event;
        opened := opened + 1;
        outcomes := outcomes || jsonb_build_object('rule_id', rule.id, 'metric', rule.metric,
          'outcome', 'opened', 'alert_id', event.id, 'observed', v_observed, 'threshold', rule.threshold,
          'severity', rule.severity);
      else
        update tonde.alert_events e set observed = v_observed, last_seen_at = now(),
          observations = e.observations + 1, updated_at = now(),
          evidence = e.evidence || jsonb_build_object('last_observation', v_observed,
            'observations', e.observations + 1)
          where e.id = event.id returning * into event;
        updated := updated + 1;
        outcomes := outcomes || jsonb_build_object('rule_id', rule.id, 'metric', rule.metric,
          'outcome', 'still_breaching', 'alert_id', event.id, 'observed', v_observed, 'state', event.state);
      end if;
    else
      if event.id is not null then
        perform set_config('tonde.alert_resolution', 'observed_in_range', true);
        update tonde.alert_events e set state = 'resolved', resolved_at = now(), observed = v_observed,
          resolution = 'observed_in_range', updated_at = now(),
          evidence = e.evidence || jsonb_build_object('resolved_by', 'observation', 'observed', v_observed,
            'threshold', rule.threshold, 'seen_in_range_at', now())
          where e.id = event.id returning * into event;
        perform set_config('tonde.alert_resolution', '', true);
        resolved := resolved + 1;
        outcomes := outcomes || jsonb_build_object('rule_id', rule.id, 'metric', rule.metric,
          'outcome', 'resolved', 'alert_id', event.id, 'observed', v_observed,
          'meaning', 'The metric came back inside the threshold; the system observed the recovery.');
      else
        outcomes := outcomes || jsonb_build_object('rule_id', rule.id, 'metric', rule.metric,
          'outcome', 'within_threshold', 'observed', v_observed, 'threshold', rule.threshold);
      end if;
    end if;
  end loop;
  return jsonb_build_object('workspace_id', target_workspace, 'evaluated', evaluated, 'opened', opened,
    'updated', updated, 'resolved', resolved, 'skipped', skipped, 'metrics', metrics -> 'values',
    'computed_at', metrics -> 'computed_at', 'outcomes', outcomes,
    'meaning', 'Every enabled rule was compared against live metrics. A recovery is resolved by the
      observation that showed it, and a rule whose metric cannot be read is reported as unavailable
      rather than assumed healthy.');
end $$;

revoke all on function tonde.alert_evaluate(uuid,integer) from public, anon, authenticated, service_role;

grant execute on function tonde.alert_evaluate(uuid,integer) to authenticated, service_role;


create or replace function tonde.alert_acknowledge(target_workspace uuid, target_event uuid, p_note text default '')
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; event tonde.alert_events;
begin
  actor := tonde_private.observability_admin(target_workspace);
  select * into event from tonde.alert_events e
    where e.workspace_id = target_workspace and e.id = target_event for update;
  if event.id is null then
    raise exception 'That alert does not exist' using errcode = 'P0002';
  end if;
  if event.state = 'resolved' then
    raise exception 'ALERT_ALREADY_RESOLVED: this alert was resolved by observation at %', event.resolved_at
      using errcode = 'PT409';
  end if;
  if event.state = 'acknowledged' then
    return jsonb_build_object('alert_id', event.id, 'state', event.state, 'idempotent', true);
  end if;
  update tonde.alert_events set state = 'acknowledged', acknowledged_by = actor, acknowledged_at = now(),
    note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
    where id = event.id returning * into event;
  perform tonde_private.audit_event(target_workspace, 'observability.alert_acknowledged', event.id,
    'alert_event', jsonb_build_object('metric', event.metric, 'observed', event.observed,
      'threshold', event.threshold, 'note', p_note));
  return jsonb_build_object('alert_id', event.id, 'state', event.state, 'acknowledged_by', actor,
    'acknowledged_at', event.acknowledged_at, 'idempotent', false,
    'meaning', 'A person acknowledged the alert. Acknowledging does not resolve it; only an observation
      inside the threshold resolves it.');
end $$;

revoke all on function tonde.alert_acknowledge(uuid,uuid,text) from public, anon, authenticated, service_role;

grant execute on function tonde.alert_acknowledge(uuid,uuid,text) to authenticated, service_role;


create or replace function tonde.alert_events_read(target_workspace uuid, p_state text default null,
  p_limit integer default 100) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; events jsonb; rules jsonb;
begin
  actor := tonde_private.discover_member(target_workspace);
  if p_state is not null and p_state not in ('open','acknowledged','resolved') then
    raise exception 'An alert is open, acknowledged or resolved' using errcode = '22023';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 500 then
    raise exception 'An alert page is between 1 and 500 records' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('alert_id', e.id, 'rule_id', e.rule_id, 'metric', e.metric,
    'comparator', e.comparator, 'threshold', e.threshold, 'observed', e.observed, 'severity', e.severity,
    'state', e.state, 'detected_at', e.detected_at, 'last_seen_at', e.last_seen_at,
    'observations', e.observations, 'acknowledged_by', e.acknowledged_by, 'acknowledged_at', e.acknowledged_at,
    'resolved_at', e.resolved_at, 'resolution', e.resolution, 'evidence', e.evidence, 'note', e.note)
    order by e.detected_at desc), '[]'::jsonb) into events
    from (select * from tonde.alert_events e where e.workspace_id = target_workspace
      and (p_state is null or e.state = p_state) order by e.detected_at desc limit p_limit) e;
  select coalesce(jsonb_agg(jsonb_build_object('rule_id', r.id, 'name', r.name, 'metric', r.metric,
    'comparator', r.comparator, 'threshold', r.threshold, 'severity', r.severity, 'enabled', r.enabled,
    'window_minutes', r.window_minutes) order by r.name), '[]'::jsonb) into rules
    from tonde.alert_rules r where r.workspace_id = target_workspace;
  return jsonb_build_object('workspace_id', target_workspace, 'state', p_state, 'rules', rules,
    'events', events, 'count', jsonb_array_length(events));
end $$;

revoke all on function tonde.alert_events_read(uuid,text,integer) from public, anon, authenticated, service_role;

grant execute on function tonde.alert_events_read(uuid,text,integer) to authenticated, service_role;


-- 10. Health: can this system work at all? Every answer carries the observation behind it.
-- Every check is read live from the durable table it names. The private function is the single
-- implementation; the public function below exposes it to the platform alone, because these are
-- platform-wide counts and one tenant must not learn another tenant's backlog through them. A workspace
-- admin reads the same picture, scoped to the read they are already allowed, through operations_status.
create or replace function tonde_private.infrastructure_health() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare started timestamptz := clock_timestamp(); checks jsonb := '[]'::jsonb;
  state text := 'ok'; rls_count integer; expired integer; dead integer;
  stuck_sweeps integer; stuck_deletions integer; purge_pending integer; purge_oldest numeric;
  duration integer;
begin
  select count(*) into rls_count from information_schema.columns c
    join information_schema.tables t on t.table_schema = c.table_schema and t.table_name = c.table_name
    join pg_class pc on pc.relname = c.table_name
    join pg_namespace pn on pn.oid = pc.relnamespace and pn.nspname = c.table_schema
    where c.table_schema = 'tonde' and t.table_type = 'BASE TABLE' and c.column_name = 'workspace_id'
      and pc.relrowsecurity = false;
  checks := checks || jsonb_build_object('check', 'database_answers', 'state', 'ok',
    'observed', jsonb_build_object('now', now(), 'server_version', current_setting('server_version')),
    'detail', 'The database answered this query, which is what this check observes.');
  checks := checks || jsonb_build_object('check', 'tenant_tables_have_rls', 'state',
    case when rls_count = 0 then 'ok' else 'degraded' end,
    'observed', jsonb_build_object('tables_without_rls', rls_count),
    'detail', case when rls_count = 0 then 'Every tenant table carries row level security.'
      else 'A tenant table without row level security is a leak waiting to happen.' end);
  select count(*) into expired from tonde.jobs j where j.status in ('leased','running')
    and j.lease_expires_at is not null and j.lease_expires_at <= now();
  checks := checks || jsonb_build_object('check', 'expired_job_leases', 'state',
    case when expired = 0 then 'ok' else 'degraded' end,
    'observed', jsonb_build_object('expired_leases', expired),
    'detail', case when expired = 0 then 'No worker is holding a lease past its expiry.'
      else 'Lease recovery reclaims these on its next pass; work is not lost, it is late.' end);
  select count(*) into dead from tonde.jobs j where j.status = 'dead_letter';
  checks := checks || jsonb_build_object('check', 'dead_letter_jobs', 'state',
    case when dead = 0 then 'ok' else 'degraded' end,
    'observed', jsonb_build_object('dead_letter', dead),
    'detail', case when dead = 0 then 'No job exhausted its attempts.'
      else 'Dead letters are work that will never finish by itself and needs a person.' end);
  select count(*) into stuck_sweeps from tonde.retention_sweeps s
    where s.state = 'running' and s.started_at < now() - interval '1 hour';
  checks := checks || jsonb_build_object('check', 'stuck_retention_sweeps', 'state',
    case when stuck_sweeps = 0 then 'ok' else 'degraded' end,
    'observed', jsonb_build_object('stuck_sweeps', stuck_sweeps),
    'detail', case when stuck_sweeps = 0 then 'No retention sweep is stuck mid-run.'
      else 'A sweep that has been running for over an hour stopped making progress.' end);
  select count(*) into stuck_deletions from tonde.deletion_requests d
    where d.state in ('revoking','purging','verifying') and d.updated_at < now() - interval '2 hours';
  checks := checks || jsonb_build_object('check', 'stuck_deletion_requests', 'state',
    case when stuck_deletions = 0 then 'ok' else 'degraded' end,
    'observed', jsonb_build_object('stuck_deletions', stuck_deletions),
    'detail', case when stuck_deletions = 0 then 'Every open deletion moved in the last two hours.'
      else 'A deletion that stopped moving is unfinished work the creator is waiting on.' end);
  select count(*), coalesce(round(extract(epoch from (now() - min(q.requested_at)))), 0)
    into purge_pending, purge_oldest from tonde.storage_purge_queue q where q.state = 'pending';
  checks := checks || jsonb_build_object('check', 'storage_purge_backlog', 'state',
    case when purge_pending = 0 then 'ok' when purge_oldest < 86400 then 'degraded' else 'failed' end,
    'observed', jsonb_build_object('pending', purge_pending, 'oldest_seconds', purge_oldest),
    'detail', case when purge_pending = 0 then 'Nothing is waiting to be purged from storage.'
      when purge_oldest < 86400 then 'Objects are queued for purging and will be drained by a worker.'
      else 'Objects have been queued for over a day: the purge worker is not keeping up.' end);
  select case
    when exists (select 1 from jsonb_array_elements(checks) c where c ->> 'state' = 'failed') then 'failed'
    when exists (select 1 from jsonb_array_elements(checks) c where c ->> 'state' = 'degraded') then 'degraded'
    else 'ok' end into state;
  duration := round(extract(epoch from (clock_timestamp() - started)) * 1000);
  return jsonb_build_object('state', state, 'checks', checks, 'check_count', jsonb_array_length(checks),
    'duration_ms', duration, 'checked_at', now(), 'source', 'live rows',
    'meaning', 'Health is what the database can observe about its own ability to work: the tenant surface
      is protected, work is not stuck, and nothing is silently piling up. It is not a claim about any
      external provider.');
end $$;

revoke all on function tonde_private.infrastructure_health() from public, anon, authenticated, service_role;


create or replace function tonde.health_check(p_record boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; result jsonb;
begin
  -- Platform infrastructure information. Not a workspace owner, not a viewer: an owner of some workspace
  -- would otherwise learn every other tenant's dead letters and purge backlog from a platform-wide count.
  if not ((select auth.role()) = 'service_role' or auth.uid() is null) then
    raise exception 'Platform authority required for platform-wide health; a workspace admin reads the
      same picture through tonde.operations_status' using errcode = '42501';
  end if;
  actor := (select auth.uid());
  result := tonde_private.infrastructure_health();
  if coalesce(p_record, false) then
    insert into tonde.system_checks(workspace_id, check_kind, state, summary, checked_by, duration_ms)
    values (null, 'health', result ->> 'state', jsonb_build_object('checks', result -> 'checks'), actor,
      (result ->> 'duration_ms')::integer);
  end if;
  return result || jsonb_build_object('recorded', coalesce(p_record, false), 'recorded_by', actor);
end $$;

revoke all on function tonde.health_check(boolean) from public, anon, authenticated, service_role;

grant execute on function tonde.health_check(boolean) to service_role;


-- 11. Readiness: what is actually configured for this deployment, and what is not.
create or replace function tonde.readiness_check(target_workspace uuid default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; dependencies jsonb := '[]'::jsonb; state text; workers_live integer;
  scanner jsonb; purge_pending integer; providers jsonb; ai_connections jsonb; billing integer;
  email_surface integer; provider_states jsonb; by_service jsonb;
begin
  if target_workspace is not null then
    actor := tonde_private.observability_admin(target_workspace);
  elsif (select auth.role()) = 'service_role' then
    actor := (select auth.uid());
  else
    raise exception 'Operations authority required' using errcode = '42501';
  end if;
  -- Worker fleet: is anything actually claiming work?
  select count(*) into workers_live from tonde.workers w where w.status <> 'offline'
    and w.heartbeat_at > now() - interval '5 minutes';
  dependencies := dependencies || jsonb_build_object('dependency', 'worker_fleet',
    'state', case when workers_live > 0 then 'ok' else 'not_configured' end,
    'detail', case when workers_live > 0 then 'A worker instance is online and heartbeating.'
      else 'No worker has heartbeated in the last five minutes, so queued jobs will not run.' end,
    'source', 'tonde.workers');
  -- Media scanning: declared honestly by the media limits function itself.
  scanner := tonde.media_upload_limits();
  dependencies := dependencies || jsonb_build_object('dependency', 'media_scanner',
    'state', case when (scanner ->> 'scanner_configured')::boolean then 'ok' else 'not_configured' end,
    'detail', case when (scanner ->> 'scanner_configured')::boolean
      then 'A scanner is recorded, so uploads can be checked for malware.'
      else 'No malware scanner is configured. An infected file can only be quarantined after the fact,
        and TONDE says so rather than implying uploads are scanned.' end,
    'source', 'tonde.media_upload_limits().scanner_configured');
  select count(*) into purge_pending from tonde.storage_purge_queue q where q.state = 'pending';
  dependencies := dependencies || jsonb_build_object('dependency', 'storage_purge_queue',
    'state', case when purge_pending = 0 then 'ok' else 'degraded' end,
    'detail', case when purge_pending = 0 then 'No object is waiting to be purged.'
      else format('%s object(s) are queued for purging and need a running purge worker.', purge_pending) end,
    'source', 'tonde.storage_purge_queue');
  -- Provider adapters: 'verified' means a real call to the real provider succeeded, not that a row exists.
  select coalesce(jsonb_agg(jsonb_build_object('provider', p.key, 'category', p.category,
    'adapter_state', p.adapter_state, 'enabled', p.enabled,
    'state', case p.adapter_state when 'verified' then 'ok' when 'implemented' then 'degraded'
      else 'not_configured' end,
    'connections', (select count(*) from tonde.integration_connections c
      where c.provider = p.key and c.status = 'connected')) order by p.key), '[]'::jsonb) into providers
    from tonde.integration_providers p;
  provider_states := jsonb_build_object('providers', providers,
    'verified', coalesce((select jsonb_agg(p.key order by p.key) from tonde.integration_providers p
      where p.adapter_state = 'verified'), '[]'::jsonb),
    'unverified', coalesce((select jsonb_agg(p.key order by p.key) from tonde.integration_providers p
      where p.adapter_state <> 'verified'), '[]'::jsonb));
  dependencies := dependencies || jsonb_build_object('dependency', 'integration_providers',
    'state', case when exists (select 1 from tonde.integration_providers p where p.adapter_state = 'verified')
      then 'ok' else 'not_configured' end,
    'detail', case when exists (select 1 from tonde.integration_providers p where p.adapter_state = 'verified')
      then 'At least one provider adapter was verified against the real provider.'
      else 'No provider adapter has been verified against a real provider. Nothing here can publish,
        deliver or bill, and TONDE claims none of it.' end,
    'source', 'tonde.integration_providers + tonde.integration_connections', 'providers', provider_states);
  -- AI generation: a connection row is not a capability claim; the state is what the row says.
  select coalesce(jsonb_agg(jsonb_build_object('provider_key', c.provider_key, 'state', c.state) order by c.provider_key),
    '[]'::jsonb) into ai_connections from tonde.ai_provider_connections c
    where target_workspace is null or c.workspace_id = target_workspace;
  dependencies := dependencies || jsonb_build_object('dependency', 'ai_generation',
    'state', case when exists (select 1 from jsonb_array_elements(ai_connections) c where c ->> 'state' = 'connected')
      then 'ok' else 'not_configured' end,
    'required_for_core', false,
    'detail', case when exists (select 1 from jsonb_array_elements(ai_connections) c where c ->> 'state' = 'connected')
      then 'A provider connection is recorded as connected for this scope, so a Shot could also be run
        inside TONDE. The core product does not need it.'
      else 'No AI provider connection is recorded as connected. That is not a blocker for the core product:
        TONDE directs the Shot, compiles the playbook prompt and the creator runs it in the external tool
        they own, then the Result comes back here to be checked.' end,
    'source', 'tonde.ai_provider_connections', 'connections', ai_connections);
  -- Billing: a subscription row is the only evidence, and 'none' is not a subscription.
  select count(*) into billing from tonde.billing_accounts b
    where b.subscription_status in ('trialing','active');
  dependencies := dependencies || jsonb_build_object('dependency', 'billing',
    'state', case when billing > 0 then 'ok' else 'not_configured' end,
    'detail', case when billing > 0 then format('%s workspace(s) have an active or trialing subscription.', billing)
      else 'No workspace has an active subscription record. Billing is off, which is a configuration,
        not a failure.' end,
    'source', 'tonde.billing_accounts');
  -- Email delivery has no configuration surface in this schema. Saying so is the honest answer.
  select count(*) into email_surface from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where c.relkind in ('r','p') and c.relname ilike '%email%';
  dependencies := dependencies || jsonb_build_object('dependency', 'email_delivery',
    'state', 'not_configured',
    'detail', case when email_surface = 0
      then 'This deployment has no email provider configuration surface at all, so signup confirmation,
        verification and password reset mail cannot be delivered or claimed.'
      else 'An email surface exists but nothing records a verified provider, so delivery is not claimed.' end,
    'source', case when email_surface = 0 then 'schema scan: no relation named like email'
      else 'schema scan: email surface present, provider unverified' end);
  select case
    when exists (select 1 from jsonb_array_elements(dependencies) d where d ->> 'state' = 'failed') then 'failed'
    when exists (select 1 from jsonb_array_elements(dependencies) d where d ->> 'state' = 'degraded') then 'degraded'
    when exists (select 1 from jsonb_array_elements(dependencies) d where d ->> 'state' = 'ok') then 'degraded'
    else 'not_configured' end into state;
  return jsonb_build_object('workspace_id', target_workspace, 'state', state,
    'ready_for_work', exists (select 1 from jsonb_array_elements(dependencies) d
      where d ->> 'dependency' = 'worker_fleet' and d ->> 'state' = 'ok'),
    'dependencies', dependencies, 'checked_at', now(),
    'meaning', 'Readiness is a report, not a promise: each dependency names the row or function it was
      read from, and an unconfigured dependency is reported as not configured instead of assumed ready.');
end $$;

revoke all on function tonde.readiness_check(uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.readiness_check(uuid) to authenticated, service_role;


-- 12. The operations console read: health, readiness, metrics and alerts in one answer.
create or replace function tonde.operations_status(target_workspace uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid;
begin
  actor := tonde_private.observability_admin(target_workspace);
  return jsonb_build_object('workspace_id', target_workspace,
    'health', tonde_private.infrastructure_health(),
    'readiness', tonde.readiness_check(target_workspace),
    'metrics', tonde_private.workspace_metrics(target_workspace, 60),
    'alerts', tonde.alert_events_read(target_workspace, 'open', 50),
    'read_at', now(),
    'meaning', 'One read of what the system can observe about itself and this workspace. It reports
      what is true now, including everything that is not configured.');
end $$;

revoke all on function tonde.operations_status(uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.operations_status(uuid) to authenticated, service_role;


-- 13. Release records: the traceability anchor the runbook points at.
create or replace function tonde.release_record(p_environment text, p_release_id text, p_migrated_through text,
  p_notes text default '', p_evidence jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid()); existing tonde.deployment_releases;
  release tonde.deployment_releases;
begin
  if (select auth.role()) <> 'service_role' and auth.uid() is not null then
    raise exception 'A release is recorded by the platform, not by a client' using errcode = '42501';
  end if;
  if p_environment not in ('local','hosted','preview') then
    raise exception 'A release names local, hosted or preview' using errcode = '22023';
  end if;
  if length(btrim(coalesce(p_release_id, ''))) = 0 or length(btrim(coalesce(p_migrated_through, ''))) = 0 then
    raise exception 'A release names itself and the migration range it applied' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(p_evidence, '{}'::jsonb)) <> 'object' then
    raise exception 'Release evidence is recorded as an object' using errcode = '22023';
  end if;
  select * into existing from tonde.deployment_releases r where r.environment = p_environment
    and r.migrated_through = btrim(p_migrated_through);
  if existing.id is not null then
    return jsonb_build_object('release_id', existing.id, 'environment', existing.environment,
      'migrated_through', existing.migrated_through, 'recorded_at', existing.recorded_at,
      'idempotent', true, 'meaning', 'That environment already has a record for this migration range.');
  end if;
  insert into tonde.deployment_releases(environment, release_id, migrated_through, notes, evidence, recorded_by)
  values (p_environment, left(btrim(p_release_id), 120), left(btrim(p_migrated_through), 60),
    nullif(left(coalesce(p_notes, ''), 2000), ''), coalesce(p_evidence, '{}'::jsonb), actor)
  returning * into release;
  return jsonb_build_object('release_id', release.id, 'environment', release.environment,
    'migrated_through', release.migrated_through, 'recorded_at', release.recorded_at,
    'idempotent', false,
    'meaning', 'The applied migration range is recorded as evidence. Recording it does not apply it.');
end $$;

revoke all on function tonde.release_record(text,text,text,text,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.release_record(text,text,text,text,jsonb) to service_role;


-- 14. Retention registry: observability evidence is retained by routine sweeps and removed with the
--     workspace on an authorized deletion.
insert into tonde.retention_classes(data_class, display_name, description, table_names, age_column,
  default_retention_days, purge_action, purge_exempt, purge_order) values
  ('operational_evidence','Operational evidence','Metric snapshots, recorded health and readiness checks
   and the alert trail. Retained as history by a routine sweep; removed with the workspace on deletion.',
   '{operational_snapshots,system_checks,alert_events}','captured_at',null,'retain',false,36),
  ('alert_configuration','Alert rules','The alert rules a workspace defined. Configuration, not evidence.',
   '{alert_rules}','created_at',null,'retain',false,37)
on conflict (data_class) do update set display_name = excluded.display_name,
  description = excluded.description, table_names = excluded.table_names, age_column = excluded.age_column,
  default_retention_days = excluded.default_retention_days, purge_action = excluded.purge_action,
  purge_exempt = excluded.purge_exempt, purge_order = excluded.purge_order, updated_at = now();


alter default privileges in schema tonde revoke execute on functions from public;

alter default privileges in schema tonde_private revoke execute on functions from public;


commit;

-- ==========================================================================
-- 202610050043_prompt11_ai_director.sql
-- ==========================================================================

-- 043 - Prompt 11 -- THE DIRECTOR CORRECTION
--
-- Owner product law this migration implements: TONDE does not generate final images or videos
-- itself. TONDE directs. The product model is
--
--   IDEA / REFERENCE -> TONDE DIRECTOR -> PRODUCTION PLAN -> SHOT/SCENE PLAYBOOK
--     -> EXECUTION (REAL, or an EXTERNAL AI TOOL, or HYBRID) -> THE CREATOR EXECUTES
--     -> RESULT UPLOADED TO TONDE -> TONDE CHECKS THE RESULT -> ACCEPT or FIX -> CONTINUE.
--
-- What this migration does NOT do, deliberately:
--   * it adds no image/video-generation provider client, worker class, queue, webhook or attempt path
--     whose purpose is calling a generation service. `ai_generation_attempts` already models an attempt
--     as `live` or `manual`, and `live` needs a connection row that only exists when a real adapter was
--     verified. The core product path is the external tool the creator runs, which needs no credential.
--   * it does not turn TONDE into a media host, a reseller of third-party generation, or the owner of
--     any tool's capabilities. A tool profile is documented knowledge with a citation, not an API.
--   * it does not touch the Prompt 10 provider architecture. That general seam stays for publishing,
--     billing, OAuth, email and integrations.
--
-- Additive and forward-only. 001-042 are untouched.
begin;


-- 1. AI Tool Knowledge: what TONDE has been taught about an external creative tool.
--
-- TONDE holds no vendor capability facts of its own. A profile is knowledge a person entered or a
-- tutorial/documentation import produced, it names the documentation it came from once it is relied
-- on, it is versioned, and reviewed knowledge is never silently rewritten: a changed fact is a new
-- version, and the row that was relied on keeps saying what it said. A profile is NOT a connection.
create table if not exists tonde.ai_tool_profiles (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  tool_key text not null check (tool_key ~ '^[a-z][a-z0-9_]{1,59}$'),
  display_name text not null check (length(btrim(display_name)) between 1 and 120),
  capability_type text not null check (capability_type in ('video_generation','image_generation',
    'audio_generation','editing','compositing','upscaling','other')),
  media_kind text not null check (media_kind in ('video','image','audio','other')),
  input_types text[] not null default '{}',
  supports_reference_image boolean not null default false,
  supports_reference_video boolean not null default false,
  supports_first_frame boolean not null default false,
  supports_last_frame boolean not null default false,
  supports_negative_prompt boolean not null default false,
  supports_seed boolean not null default false,
  supports_camera_control boolean not null default false,
  max_duration_ms bigint check (max_duration_ms is null or max_duration_ms > 0),
  aspect_ratios text[] not null default '{}',
  prompt_characteristics text not null default '' check (length(prompt_characteristics) <= 4000),
  known_strengths text not null default '' check (length(known_strengths) <= 2000),
  known_limitations text not null default '' check (length(known_limitations) <= 2000),
  workflow_guidance text not null default '' check (length(workflow_guidance) <= 4000),
  typical_external_cost_note text not null default '' check (length(typical_external_cost_note) <= 600),
  tool_version text not null default '' check (length(tool_version) <= 120),
  documented_at date,
  source_title text check (source_title is null or length(btrim(source_title)) between 2 and 300),
  source_url text check (source_url is null or length(source_url) <= 1000),
  source_publisher text check (source_publisher is null or length(source_publisher) <= 200),
  source_kind text not null default 'creator' check (source_kind in ('creator','tutorial','import',
    'manufacturer','external_publication','standards_body')),
  review_state text not null default 'draft' check (review_state in ('draft','reviewed','retired')),
  reviewed_by uuid references auth.users(id) on delete set null,
  reviewed_at timestamptz,
  review_note text check (review_note is null or length(review_note) <= 1000),
  superseded_by uuid,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  unique (workspace_id, tool_key, tool_version),
  -- A kit entry points at the profile of the tool it names, enforced by the composite key rather than
  -- by a check constraint, because a check cannot read another row.
  unique (workspace_id, tool_key, id),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict,
  foreign key (workspace_id, superseded_by) references tonde.ai_tool_profiles(workspace_id, id)
    on delete restrict,
  -- The closed input vocabulary, so a documented input type is never a typo.
  constraint ai_tool_profile_input_types_closed
    check (input_types <@ array['text','image','video','audio']),
  -- Knowledge that will be relied on names its documentation. A draft may be unattributed.
  constraint ai_tool_profile_reviewed_is_sourced
    check (review_state <> 'reviewed' or source_title is not null or source_url is not null),
  -- A review decision names who made it and when.
  constraint ai_tool_profile_review_is_stamped
    check (review_state = 'draft' or (reviewed_by is not null and reviewed_at is not null)),
  -- A retired profile is superseded by something, or it says why in the review note.
  constraint ai_tool_profile_retirement_is_explained
    check (review_state <> 'retired' or superseded_by is not null
      or (review_note is not null and length(btrim(review_note)) > 0)),
  -- A superseded row cannot be the thing that supersedes another row.
  constraint ai_tool_profile_supersession_is_forward check (superseded_by is null or superseded_by <> id),
  -- Documented limits are bounded by what the formats can express.
  constraint ai_tool_profile_duration_sane
    check (max_duration_ms is null or max_duration_ms between 100 and 7200000)
);

drop trigger if exists guard_mutation on tonde.ai_tool_profiles;
create trigger guard_mutation before insert or update on tonde.ai_tool_profiles
  for each row execute function tonde_private.guard_mutation();

create index if not exists ai_tool_profiles_by_tool on tonde.ai_tool_profiles(workspace_id, tool_key, revision desc);

create index if not exists ai_tool_profiles_usable on tonde.ai_tool_profiles(workspace_id, capability_type)
  where review_state = 'reviewed';

alter table tonde.ai_tool_profiles enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'ai_tool_profiles'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.ai_tool_profiles for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.ai_tool_profiles to authenticated;

grant all on tonde.ai_tool_profiles to service_role;


-- 2. The Production Kit names the external AI tools the creator actually has.
--
-- Kit entry, not a dependency: TONDE adapts its direction to these tools, and it never needs a
-- credential for one. A tool may be in the kit with no profile, in which case TONDE says it knows
-- nothing about how that tool reads a prompt instead of inventing it.
create table if not exists tonde.production_ai_tools (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null,
  production_id uuid not null,
  tool_key text not null check (tool_key ~ '^[a-z][a-z0-9_]{1,59}$'),
  display_name text not null check (length(btrim(display_name)) between 1 and 120),
  tool_profile_id uuid,
  note text not null default '' check (length(note) <= 600),
  sort_order integer not null default 0,
  revision integer not null default 1 check (revision > 0),
  created_by uuid not null default auth.uid(),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, production_id, tool_key),
  unique (workspace_id, id),
  foreign key (workspace_id) references tonde.workspaces(id) on delete restrict,
  foreign key (workspace_id, production_id) references tonde.productions(workspace_id, id) on delete restrict,
  foreign key (workspace_id, tool_key, tool_profile_id)
    references tonde.ai_tool_profiles(workspace_id, tool_key, id) on delete restrict
);

drop trigger if exists guard_mutation on tonde.production_ai_tools;
create trigger guard_mutation before insert or update on tonde.production_ai_tools
  for each row execute function tonde_private.guard_mutation();

create index if not exists production_ai_tools_by_production on tonde.production_ai_tools(workspace_id, production_id, sort_order);

alter table tonde.production_ai_tools enable row level security;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'production_ai_tools'
      and policyname = 'tenant_read'
  ) then
    execute $tonde_idem_ddl$create policy tenant_read on tonde.production_ai_tools for select to authenticated
  using (tonde_private.is_workspace_member(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.production_ai_tools to authenticated;

grant all on tonde.production_ai_tools to service_role;


-- 3. The Result check is a check against the playbook, recorded as evidence.
--
-- A REAL Result and an AI Result are checked the same way: the shot_match report already carries the
-- findings, the severity and the recommendations. A Director check adds what the playbook is compared
-- against, the verdict, the instructions a FIX carries, the prompt that was checked and the prompt the
-- correction produces. Both prompt texts are kept, so the loop PROMPT V1 -> RESULT V1 -> CHECK ->
-- CORRECTION -> PROMPT V2 is a record rather than a claim.
alter table tonde.shot_match_reports add column if not exists execution_method text
  check (execution_method is null or execution_method in ('real','ai','hybrid'));

alter table tonde.shot_match_reports add column if not exists tool_key text
  check (tool_key is null or tool_key ~ '^[a-z][a-z0-9_]{1,59}$');

alter table tonde.shot_match_reports add column if not exists verdict text
  check (verdict is null or verdict in ('accept','fix'));

alter table tonde.shot_match_reports add column if not exists instructions text
  check (instructions is null or length(instructions) <= 4000);

alter table tonde.shot_match_reports add column if not exists criteria jsonb not null default '[]'::jsonb
  check (jsonb_typeof(criteria) = 'array');

alter table tonde.shot_match_reports add column if not exists prompt_text text
  check (prompt_text is null or length(prompt_text) <= 12000);

alter table tonde.shot_match_reports add column if not exists next_prompt text
  check (next_prompt is null or length(next_prompt) <= 12000);

alter table tonde.shot_match_reports add column if not exists previous_check_id uuid;

alter table tonde.shot_match_reports add column if not exists what_changed jsonb not null default '{}'::jsonb
  check (jsonb_typeof(what_changed) = 'object');

alter table tonde.shot_match_reports add column if not exists checked_by uuid references auth.users(id) on delete set null;

alter table tonde.shot_match_reports add column if not exists checked_at timestamptz;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.shot_match_reports') and conname = 'shot_match_reports_previous_fk'
  ) then
    execute $tonde_idem_ddl$alter table tonde.shot_match_reports add constraint shot_match_reports_previous_fk
  foreign key (workspace_id, previous_check_id) references tonde.shot_match_reports(workspace_id, id)
  on delete restrict$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

-- A FIX without instructions is not direction; an ACCEPT carries none.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.shot_match_reports') and conname = 'shot_match_reports_fix_is_instructed'
  ) then
    execute $tonde_idem_ddl$alter table tonde.shot_match_reports add constraint shot_match_reports_fix_is_instructed
  check (verdict is distinct from 'fix' or (instructions is not null and length(btrim(instructions)) > 0))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.shot_match_reports') and conname = 'shot_match_reports_accept_is_quiet'
  ) then
    execute $tonde_idem_ddl$alter table tonde.shot_match_reports add constraint shot_match_reports_accept_is_quiet
  check (verdict is distinct from 'accept' or instructions is null)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

-- A verdict is a Director decision, so it names who made it and when.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.shot_match_reports') and conname = 'shot_match_reports_verdict_is_stamped'
  ) then
    execute $tonde_idem_ddl$alter table tonde.shot_match_reports add constraint shot_match_reports_verdict_is_stamped
  check (verdict is null or (checked_by is not null and checked_at is not null))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

-- A correction chain never points at itself.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_constraint
    where conrelid = to_regclass('tonde.shot_match_reports') and conname = 'shot_match_reports_chain_is_forward'
  ) then
    execute $tonde_idem_ddl$alter table tonde.shot_match_reports add constraint shot_match_reports_chain_is_forward
  check (previous_check_id is null or previous_check_id <> id)$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;


-- 4. Private helpers.

-- Direction on how a tool reads a prompt is workspace knowledge: an editor maintains it.
create or replace function tonde_private.ai_tool_librarian(target_workspace uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid());
begin
  if actor is null or (select auth.role()) <> 'authenticated'
    or not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Authenticated workspace editor required' using errcode = '42501';
  end if;
  return actor;
end $$;

revoke all on function tonde_private.ai_tool_librarian(uuid) from public, anon, authenticated, service_role;


-- Relying on knowledge is a review decision, so it takes workspace admin authority.
create or replace function tonde_private.ai_tool_reviewer(target_workspace uuid) returns uuid
language plpgsql security definer set search_path = '' as $$
declare actor uuid := (select auth.uid());
begin
  if actor is null or not tonde_private.is_workspace_admin(target_workspace) then
    raise exception 'Workspace review authority required' using errcode = '42501';
  end if;
  return actor;
end $$;

revoke all on function tonde_private.ai_tool_reviewer(uuid) from public, anon, authenticated, service_role;


-- One profile, as a stable document. A profile is knowledge; the connection state is not part of it.
create or replace function tonde_private.ai_tool_profile_json(profile tonde.ai_tool_profiles) returns jsonb
language sql immutable set search_path = '' as $$
  select jsonb_build_object(
    'profile_id', profile.id, 'tool_key', profile.tool_key, 'display_name', profile.display_name,
    'capability_type', profile.capability_type, 'media_kind', profile.media_kind,
    'input_types', to_jsonb(profile.input_types),
    'supports_reference_image', profile.supports_reference_image,
    'supports_reference_video', profile.supports_reference_video,
    'supports_first_frame', profile.supports_first_frame,
    'supports_last_frame', profile.supports_last_frame,
    'supports_negative_prompt', profile.supports_negative_prompt,
    'supports_seed', profile.supports_seed, 'supports_camera_control', profile.supports_camera_control,
    'max_duration_ms', profile.max_duration_ms, 'aspect_ratios', to_jsonb(profile.aspect_ratios),
    'prompt_characteristics', profile.prompt_characteristics, 'known_strengths', profile.known_strengths,
    'known_limitations', profile.known_limitations, 'workflow_guidance', profile.workflow_guidance,
    'typical_external_cost_note', profile.typical_external_cost_note,
    'tool_version', profile.tool_version, 'documented_at', profile.documented_at,
    'source_title', profile.source_title, 'source_url', profile.source_url,
    'source_publisher', profile.source_publisher, 'source_kind', profile.source_kind,
    'review_state', profile.review_state, 'reviewed_at', profile.reviewed_at,
    'review_note', profile.review_note, 'revision', profile.revision, 'superseded_by', profile.superseded_by);
$$;

revoke all on function tonde_private.ai_tool_profile_json(tonde.ai_tool_profiles)
  from public, anon, authenticated, service_role;


-- The knowledge a playbook may rely on for one tool, plus the honest state of it.
--   reviewed  a person reviewed documented knowledge, and it is applied
--   draft     knowledge exists but nobody reviewed it, so it is reported and NOT applied
--   absent    TONDE knows nothing about this tool's prompt behaviour and says so
create or replace function tonde_private.ai_tool_knowledge(target_workspace uuid, p_tool_key text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare profile tonde.ai_tool_profiles; state text;
begin
  if p_tool_key is null then
    return jsonb_build_object('status', 'absent', 'applied', false, 'profile', null,
      'detail', 'No external tool was named, so no tool-specific knowledge is applied.');
  end if;
  select * into profile from tonde.ai_tool_profiles p
    where p.workspace_id = target_workspace and p.tool_key = p_tool_key and p.review_state = 'reviewed'
      and p.superseded_by is null
    order by p.revision desc, p.updated_at desc limit 1;
  if profile.id is not null then
    return jsonb_build_object('status', 'reviewed', 'applied', true,
      'profile', tonde_private.ai_tool_profile_json(profile),
      'detail', 'Reviewed, documented knowledge of this tool is applied to the playbook.');
  end if;
  select * into profile from tonde.ai_tool_profiles p
    where p.workspace_id = target_workspace and p.tool_key = p_tool_key and p.review_state = 'draft'
    order by p.revision desc, p.updated_at desc limit 1;
  if profile.id is not null then
    return jsonb_build_object('status', 'draft', 'applied', false,
      'profile', tonde_private.ai_tool_profile_json(profile),
      'detail', 'A draft profile exists for this tool but nobody reviewed it, so TONDE reports it and
        does not let it change the prompt.');
  end if;
  return jsonb_build_object('status', 'absent', 'applied', false, 'profile', null,
    'detail', 'TONDE holds no knowledge of how this tool reads a prompt, so the playbook is compiled
      without tool-specific notes rather than guessed.');
end $$;

revoke all on function tonde_private.ai_tool_knowledge(uuid,text)
  from public, anon, authenticated, service_role;


-- The closed set of things a Director check compares. Kept as a function so a test can pin it and so
-- a check can never invent a criterion that nothing evaluates.
create or replace function tonde_private.ai_playbook_criteria() returns text[]
language sql immutable set search_path = '' as $$
  select array['shot_objective','subject_identity','continuity','composition','lighting',
    'camera_movement','environment','wardrobe','props','performance','timing','reference_relationship'];
$$;

revoke all on function tonde_private.ai_playbook_criteria() from public, anon, authenticated, service_role;


-- The plan a Director playbook is compiled from. A Shot without an approved, saved AI plan is not a
-- playbook yet: TONDE says that instead of compiling a prompt from a plan nobody wrote.
create or replace function tonde_private.ai_playbook_basis(target_workspace uuid, target_production uuid,
  target_shot uuid, expected_plan_revision integer default null)
returns tonde.execution_plans language plpgsql stable security definer set search_path = '' as $$
declare plan tonde.execution_plans;
begin
  select * into plan from tonde.execution_plans p
    where p.workspace_id = target_workspace and p.production_id = target_production
      and p.shot_id = target_shot and p.execution_method = 'ai';
  if plan.id is null then
    raise exception 'PLAYBOOK_NEEDS_PLAN: this Shot has no AI plan to direct from. Save the Shot''s AI
      plan first, then the playbook is compiled from it.' using errcode = 'PT404';
  end if;
  if expected_plan_revision is not null and plan.revision <> expected_plan_revision then
    -- The mapped conflict code, never the retryable SQLSTATE 40001 that PostgREST would retry forever.
    raise exception 'The Shot''s AI plan changed since you loaded it' using errcode = 'PT409';
  end if;
  return plan;
end $$;

revoke all on function tonde_private.ai_playbook_basis(uuid,uuid,uuid,integer)
  from public, anon, authenticated, service_role;


-- The tool-specific prompt. One deterministic compilation from the plan plus documented tool
-- knowledge: same inputs, same prompt, and every adaptation is named rather than silent.
create or replace function tonde_private.ai_playbook_prompt(target_workspace uuid, target_production uuid,
  target_shot uuid, p_tool_key text, p_expected_plan_revision integer default null,
  p_correction text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare plan tonde.execution_plans; shot tonde.shots; knowledge jsonb; profile jsonb;
  sections text[] := '{}'; adaptations jsonb := '[]'::jsonb; conflicts text[] := '{}';
  duration_ms bigint; declared_aspect text; prompt text; target_media text;
begin
  plan := tonde_private.ai_playbook_basis(target_workspace, target_production, target_shot,
    p_expected_plan_revision);
  select * into shot from tonde.shots s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.id = target_shot;
  knowledge := tonde_private.ai_tool_knowledge(target_workspace, p_tool_key);
  profile := knowledge -> 'profile';
  target_media := case tonde_private.ai_primary_operation(target_workspace, target_production, target_shot)::text
    when 'video' then 'video' when 'image' then 'image' when 'voice' then 'audio'
    when 'speech' then 'audio' when 'music' then 'audio' when 'sound_effect' then 'audio'
    when 'image_to_video' then 'video' when 'video_to_video' then 'video'
    when 'frame_interpolation' then 'video' when 'lipsync' then 'video' when 'upscaling' then 'video'
    else 'other' end;
  duration_ms := coalesce(plan.expected_duration_ms, shot.planned_duration_ms);
  declared_aspect := nullif(btrim(coalesce(plan.aspect_ratio, '')), '');
  -- The prompt is assembled from the plan and the Shot. A section the plan does not carry says so.
  sections := sections || format('SHOT: %s', shot.title);
  if length(btrim(coalesce(shot.description, ''))) > 0 then
    sections := sections || format('OBJECTIVE: %s', btrim(shot.description));
  end if;
  if length(btrim(coalesce(shot.action, ''))) > 0 then
    sections := sections || format('ACTION: %s', btrim(shot.action));
  end if;
  sections := sections || format('SUBJECT AND ENVIRONMENT: %s',
    coalesce(nullif(btrim(coalesce(plan.product_direction, '')), ''),
      nullif(btrim(coalesce(plan.performance, '')), ''), 'not specified in the plan'));
  sections := sections || format('CAMERA: %s %s %s',
    coalesce(nullif(btrim(coalesce(plan.shot_size, '')), ''), 'shot size not specified'),
    coalesce(nullif(btrim(coalesce(plan.framing, '')), ''), 'framing not specified'),
    coalesce(nullif(btrim(coalesce(plan.composition, '')), ''), 'composition not specified'));
  if length(btrim(coalesce(plan.movement, ''))) > 0
    or length(btrim(coalesce(plan.movement_purpose, ''))) > 0 then
    sections := sections || format('CAMERA MOVEMENT: %s %s', coalesce(nullif(btrim(coalesce(plan.movement, '')), ''),
      'movement not specified'), coalesce(nullif(btrim(coalesce(plan.movement_purpose, '')), ''), ''));
  end if;
  if coalesce(plan.motion, '{}'::jsonb) <> '{}'::jsonb then
    sections := sections || format('MOTION: %s', plan.motion::text);
  end if;
  if length(btrim(coalesce(plan.lighting_intent, ''))) > 0 then
    sections := sections || format('LIGHTING: %s', btrim(plan.lighting_intent));
  end if;
  if length(btrim(coalesce(plan.performance, ''))) > 0 then
    sections := sections || format('PERFORMANCE: %s', btrim(plan.performance));
  end if;
  if coalesce(plan.continuity, '{}'::jsonb) <> '{}'::jsonb then
    sections := sections || format('CONTINUITY: %s', plan.continuity::text);
  end if;
  if coalesce(plan.first_frame, '{}'::jsonb) <> '{}'::jsonb then
    sections := sections || format('START FRAME: %s', plan.first_frame::text);
  end if;
  if coalesce(plan.last_frame, '{}'::jsonb) <> '{}'::jsonb then
    sections := sections || format('END FRAME: %s', plan.last_frame::text);
  end if;
  if coalesce(plan.audio, '{}'::jsonb) <> '{}'::jsonb then
    sections := sections || format('AUDIO: %s', plan.audio::text);
  end if;
  if length(btrim(coalesce(plan.sound_plan, ''))) > 0 then
    sections := sections || format('SOUND: %s', btrim(plan.sound_plan));
  end if;
  if declared_aspect is not null then
    sections := sections || format('ASPECT RATIO: %s', declared_aspect);
  end if;
  if duration_ms is not null then
    sections := sections || format('DURATION: %s ms', duration_ms);
  end if;
  if cardinality(plan.negative_constraints) > 0 then
    sections := sections || format('MUST NOT APPEAR: %s', array_to_string(plan.negative_constraints, '; '));
  end if;
  if p_correction is not null and length(btrim(p_correction)) > 0 then
    sections := sections || format('CORRECTION FROM THE LAST CHECK: %s', btrim(p_correction));
  end if;
  -- Tool-specific adaptation. Only reviewed knowledge changes the prompt, and every change or
  -- disagreement is reported by name.
  if (knowledge ->> 'applied')::boolean and profile is not null then
    if length(btrim(coalesce(profile ->> 'prompt_characteristics', ''))) > 0 then
      -- The notes are named for the tool the prompt is compiled for, which may be a different tool from
      -- the one the plan targeted.
      sections := sections || format('TOOL NOTES (%s): %s', coalesce(p_tool_key, plan.provider_target),
        btrim(profile ->> 'prompt_characteristics'));
      adaptations := adaptations || jsonb_build_object('kind', 'prompt_characteristics',
        'applied', true, 'detail', 'Documented prompting behaviour for this tool is added to the prompt.');
    end if;
    if length(btrim(coalesce(profile ->> 'workflow_guidance', ''))) > 0 then
      sections := sections || format('TOOL WORKFLOW: %s', btrim(profile ->> 'workflow_guidance'));
    end if;
    if (profile ->> 'max_duration_ms') is not null and duration_ms is not null
      and duration_ms > (profile ->> 'max_duration_ms')::bigint then
      conflicts := array_append(conflicts, 'duration_beyond_documented_limit');
      adaptations := adaptations || jsonb_build_object('kind', 'duration_split_required', 'applied', true,
        'planned_duration_ms', duration_ms, 'documented_max_duration_ms',
        (profile ->> 'max_duration_ms')::bigint,
        'detail', 'The planned Shot is longer than this tool documents. Split the Shot into consecutive
          generations that cut together, or plan a longer static take for a tool that allows it.');
    end if;
    if declared_aspect is not null and jsonb_array_length(coalesce(profile -> 'aspect_ratios', '[]'::jsonb)) > 0
      and not (profile -> 'aspect_ratios') @> to_jsonb(array[declared_aspect]) then
      conflicts := array_append(conflicts, 'aspect_ratio_not_documented');
      adaptations := adaptations || jsonb_build_object('kind', 'aspect_ratio_not_documented', 'applied', true,
        'planned_aspect_ratio', declared_aspect,
        'documented_aspect_ratios', profile -> 'aspect_ratios',
        'detail', 'The documented aspect ratios for this tool do not include the planned one. Confirm the
          deliverable with the tool before you rely on this Shot matching the Production.');
    end if;
    if cardinality(plan.negative_constraints) > 0
      and coalesce((profile ->> 'supports_negative_prompt')::boolean, false) is not true then
      conflicts := array_append(conflicts, 'negative_prompt_unsupported');
      adaptations := adaptations || jsonb_build_object('kind', 'negative_prompt_needs_phrasing', 'applied', true,
        'detail', 'This tool is not documented as taking a separate negative prompt, so the exclusions must
          be phrased inside the prompt itself.');
    end if;
    if coalesce(plan.first_frame, '{}'::jsonb) <> '{}'::jsonb
      and coalesce((profile ->> 'supports_first_frame')::boolean, false) is not true then
      conflicts := array_append(conflicts, 'start_frame_unsupported');
      adaptations := adaptations || jsonb_build_object('kind', 'start_frame_needs_another_route', 'applied', true,
        'detail', 'This tool is not documented as accepting a start frame. Capture the frame practically or
          use a tool documented to accept one.');
    end if;
  end if;
  prompt := array_to_string(sections, E'\n');
  return jsonb_build_object(
    'tool_key', p_tool_key, 'target_media', target_media, 'prompt', prompt,
    'prompt_length', length(prompt), 'prompt_version', plan.prompt_version,
    'plan_revision', plan.revision, 'plan_approval', plan.approval,
    'knowledge', knowledge,
    'knowledge_status', knowledge ->> 'status',
    'adaptations', adaptations,
    'conflicts', to_jsonb(conflicts),
    'tool_connection', case when p_tool_key is null then 'not_applicable'
      when exists (select 1 from tonde.ai_provider_connections c
        where c.workspace_id = target_workspace and c.provider_key = p_tool_key and c.state = 'connected')
        then 'connected' else 'none' end,
    'meaning', 'The prompt is compiled by TONDE from the Shot''s plan and the documented behaviour of the
      tool you chose. TONDE does not run the tool, and this prompt is executed in the tool you own.');
end $$;

revoke all on function tonde_private.ai_playbook_prompt(uuid,uuid,uuid,text,integer,text)
  from public, anon, authenticated, service_role;


-- 5. Public reads and writes.

-- Knowledge maintenance. A draft may be corrected in place; knowledge that was reviewed is never
-- rewritten, so a changed fact is a new version that says which version it replaces.
create or replace function tonde.ai_tool_profile_save(target_workspace uuid, p_tool_key text, p_payload jsonb)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare actor uuid; existing tonde.ai_tool_profiles; profile tonde.ai_tool_profiles; new_version text;
begin
  actor := tonde_private.ai_tool_librarian(target_workspace);
  if p_payload is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception 'A tool profile must be a JSON object' using errcode = '22023';
  end if;
  if p_tool_key is null or p_tool_key !~ '^[a-z][a-z0-9_]{1,59}$' then
    raise exception 'A tool key is lower-case letters, digits and underscores' using errcode = '22023';
  end if;
  new_version := left(btrim(coalesce(p_payload ->> 'tool_version', '')), 120);
  select * into existing from tonde.ai_tool_profiles p
    where p.workspace_id = target_workspace and p.tool_key = p_tool_key
      and p.tool_version = new_version and p.superseded_by is null;
  if existing.id is not null and existing.review_state <> 'draft' then
    -- Reviewed knowledge is a record. Change it by version, so a playbook that relied on it still has
    -- the version it used.
    raise exception 'TOOL_PROFILE_VERSION_REQUIRED: version %s of this tool was %s by review. Save the change as a new tool_version, so the version that was relied on keeps saying what it said.',
      coalesce(nullif(new_version, ''), '(unversioned)'), existing.review_state using errcode = 'PT409';
  end if;
  if existing.id is not null then
    update tonde.ai_tool_profiles set
      display_name = coalesce(nullif(btrim(coalesce(p_payload ->> 'display_name', '')), ''), existing.display_name),
      capability_type = coalesce(nullif(p_payload ->> 'capability_type', ''), existing.capability_type),
      media_kind = coalesce(nullif(p_payload ->> 'media_kind', ''), existing.media_kind),
      input_types = case when p_payload ? 'input_types'
        then tonde_private.ai_json_text_array(p_payload, 'input_types') else existing.input_types end,
      supports_reference_image = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_reference_image', null),
        existing.supports_reference_image),
      supports_reference_video = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_reference_video', null),
        existing.supports_reference_video),
      supports_first_frame = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_first_frame', null),
        existing.supports_first_frame),
      supports_last_frame = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_last_frame', null),
        existing.supports_last_frame),
      supports_negative_prompt = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_negative_prompt', null),
        existing.supports_negative_prompt),
      supports_seed = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_seed', null), existing.supports_seed),
      supports_camera_control = coalesce(tonde_private.ai_json_bool(p_payload, 'supports_camera_control', null),
        existing.supports_camera_control),
      max_duration_ms = case when p_payload ? 'max_duration_ms'
        then nullif(p_payload ->> 'max_duration_ms', '')::bigint else existing.max_duration_ms end,
      aspect_ratios = case when p_payload ? 'aspect_ratios'
        then tonde_private.ai_json_text_array(p_payload, 'aspect_ratios') else existing.aspect_ratios end,
      prompt_characteristics = coalesce(p_payload ->> 'prompt_characteristics', existing.prompt_characteristics),
      known_strengths = coalesce(p_payload ->> 'known_strengths', existing.known_strengths),
      known_limitations = coalesce(p_payload ->> 'known_limitations', existing.known_limitations),
      workflow_guidance = coalesce(p_payload ->> 'workflow_guidance', existing.workflow_guidance),
      typical_external_cost_note = coalesce(p_payload ->> 'typical_external_cost_note',
        existing.typical_external_cost_note),
      documented_at = case when p_payload ? 'documented_at'
        then nullif(p_payload ->> 'documented_at', '')::date else existing.documented_at end,
      source_title = coalesce(nullif(btrim(coalesce(p_payload ->> 'source_title', '')), ''), existing.source_title),
      source_url = coalesce(nullif(btrim(coalesce(p_payload ->> 'source_url', '')), ''), existing.source_url),
      source_publisher = coalesce(nullif(btrim(coalesce(p_payload ->> 'source_publisher', '')), ''),
        existing.source_publisher),
      source_kind = coalesce(nullif(p_payload ->> 'source_kind', ''), existing.source_kind),
      updated_at = now()
      where id = existing.id returning * into profile;
    perform tonde_private.audit_event(target_workspace, 'ai_tool_profile.updated', profile.id, 'ai_tool_profile',
      jsonb_build_object('tool_key', profile.tool_key, 'tool_version', profile.tool_version,
        'revision', profile.revision, 'review_state', profile.review_state));
    return tonde_private.ai_tool_profile_json(profile) || jsonb_build_object('created', false,
      'usable_for_direction', false,
      'meaning', 'The draft is updated. Nothing relies on it until a reviewer approves it.');
  end if;
  insert into tonde.ai_tool_profiles(workspace_id, tool_key, display_name, capability_type, media_kind,
    input_types, supports_reference_image, supports_reference_video, supports_first_frame,
    supports_last_frame, supports_negative_prompt, supports_seed, supports_camera_control, max_duration_ms,
    aspect_ratios, prompt_characteristics, known_strengths, known_limitations, workflow_guidance,
    typical_external_cost_note, tool_version, documented_at, source_title, source_url, source_publisher,
    source_kind, created_by)
  values (target_workspace, p_tool_key,
    left(btrim(coalesce(p_payload ->> 'display_name', p_tool_key)), 120),
    coalesce(nullif(p_payload ->> 'capability_type', ''), 'video_generation'),
    coalesce(nullif(p_payload ->> 'media_kind', ''), 'video'),
    case when p_payload ? 'input_types' then tonde_private.ai_json_text_array(p_payload, 'input_types') else '{}' end,
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_reference_image', false), false),
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_reference_video', false), false),
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_first_frame', false), false),
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_last_frame', false), false),
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_negative_prompt', false), false),
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_seed', false), false),
    coalesce(tonde_private.ai_json_bool(p_payload, 'supports_camera_control', false), false),
    case when p_payload ? 'max_duration_ms' then nullif(p_payload ->> 'max_duration_ms', '')::bigint end,
    case when p_payload ? 'aspect_ratios' then tonde_private.ai_json_text_array(p_payload, 'aspect_ratios') else '{}' end,
    coalesce(p_payload ->> 'prompt_characteristics', ''), coalesce(p_payload ->> 'known_strengths', ''),
    coalesce(p_payload ->> 'known_limitations', ''), coalesce(p_payload ->> 'workflow_guidance', ''),
    coalesce(p_payload ->> 'typical_external_cost_note', ''), new_version,
    case when p_payload ? 'documented_at' then nullif(p_payload ->> 'documented_at', '')::date end,
    nullif(btrim(coalesce(p_payload ->> 'source_title', '')), ''),
    nullif(btrim(coalesce(p_payload ->> 'source_url', '')), ''),
    nullif(btrim(coalesce(p_payload ->> 'source_publisher', '')), ''),
    coalesce(nullif(p_payload ->> 'source_kind', ''), 'creator'), actor)
  returning * into profile;
  perform tonde_private.audit_event(target_workspace, 'ai_tool_profile.created', profile.id, 'ai_tool_profile',
    jsonb_build_object('tool_key', profile.tool_key, 'tool_version', profile.tool_version,
      'capability_type', profile.capability_type, 'review_state', profile.review_state,
      'sourced', profile.source_title is not null or profile.source_url is not null));
  return tonde_private.ai_tool_profile_json(profile) || jsonb_build_object('created', true,
    'usable_for_direction', false,
    'meaning', 'The documented knowledge is recorded as a draft. Review it before TONDE directs a Shot
      with it, because until then TONDE reports it and does not apply it.');
end $$;

revoke all on function tonde.ai_tool_profile_save(uuid,text,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_tool_profile_save(uuid,text,jsonb) to authenticated, service_role;


create or replace function tonde.ai_tool_profile_review(target_workspace uuid, target_profile uuid, p_decision text,
  p_note text default '') returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; profile tonde.ai_tool_profiles; replacement uuid;
begin
  actor := tonde_private.ai_tool_reviewer(target_workspace);
  if p_decision not in ('review','retire','return_to_draft') then
    raise exception 'A review decision is review, retire or return_to_draft' using errcode = '22023';
  end if;
  select * into profile from tonde.ai_tool_profiles p
    where p.workspace_id = target_workspace and p.id = target_profile for update;
  if profile.id is null then
    raise exception 'That tool profile does not exist in this workspace' using errcode = 'P0002';
  end if;
  if p_decision = 'review' then
    if profile.source_title is null and profile.source_url is null then
      raise exception 'TOOL_PROFILE_NEEDS_SOURCE: knowledge TONDE will rely on names the documentation it
        came from.' using errcode = 'PT400';
    end if;
    if profile.review_state = 'reviewed' then
      return tonde_private.ai_tool_profile_json(profile) || jsonb_build_object('idempotent', true);
    end if;
    update tonde.ai_tool_profiles set review_state = 'reviewed', reviewed_by = actor, reviewed_at = now(),
      review_note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
      where id = profile.id returning * into profile;
    perform tonde_private.audit_event(target_workspace, 'ai_tool_profile.reviewed', profile.id, 'ai_tool_profile',
      jsonb_build_object('tool_key', profile.tool_key, 'tool_version', profile.tool_version,
        'source_title', profile.source_title));
    return tonde_private.ai_tool_profile_json(profile) || jsonb_build_object('idempotent', false,
      'usable_for_direction', true,
      'meaning', 'This documented knowledge may now change how TONDE compiles a prompt for this tool.');
  end if;
  if p_decision = 'return_to_draft' then
    update tonde.ai_tool_profiles set review_state = 'draft', reviewed_by = null, reviewed_at = null,
      review_note = nullif(left(coalesce(p_note, ''), 1000), ''), updated_at = now()
      where id = profile.id returning * into profile;
    perform tonde_private.audit_event(target_workspace, 'ai_tool_profile.returned_to_draft', profile.id,
      'ai_tool_profile', jsonb_build_object('tool_key', profile.tool_key, 'note', left(coalesce(p_note, ''), 400)));
    return tonde_private.ai_tool_profile_json(profile) || jsonb_build_object('idempotent', false,
      'usable_for_direction', false,
      'meaning', 'This knowledge is a draft again, so it is reported and no longer applied.');
  end if;
  select p.id into replacement from tonde.ai_tool_profiles p
    where p.workspace_id = target_workspace and p.tool_key = profile.tool_key and p.id <> profile.id
      and p.superseded_by is null and p.review_state in ('draft','reviewed')
    order by p.revision desc limit 1;
  if replacement is null and (p_note is null or length(btrim(p_note)) = 0) then
    raise exception 'A retired profile says why, or names the version that replaces it' using errcode = '22023';
  end if;
  update tonde.ai_tool_profiles set review_state = 'retired', reviewed_by = actor, reviewed_at = now(),
    review_note = nullif(left(coalesce(p_note, ''), 1000), ''), superseded_by = replacement,
    updated_at = now() where id = profile.id returning * into profile;
  perform tonde_private.audit_event(target_workspace, 'ai_tool_profile.retired', profile.id, 'ai_tool_profile',
    jsonb_build_object('tool_key', profile.tool_key, 'superseded_by', replacement, 'note', left(coalesce(p_note, ''), 400)));
  return tonde_private.ai_tool_profile_json(profile) || jsonb_build_object('idempotent', false,
    'usable_for_direction', false,
    'meaning', 'This version is retired. TONDE stops applying it, and it stays readable as what was known.');
end $$;

revoke all on function tonde.ai_tool_profile_review(uuid,uuid,text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_tool_profile_review(uuid,uuid,text,text) to authenticated, service_role;


-- What TONDE has been taught about the tools a creator might use. A connection is never implied.
create or replace function tonde.ai_tool_catalog(target_workspace uuid, p_capability_type text default null,
  p_include_drafts boolean default false) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare profiles jsonb; actor uuid := (select auth.uid());
begin
  if actor is null or not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  if p_capability_type is not null and p_capability_type not in ('video_generation','image_generation',
    'audio_generation','editing','compositing','upscaling','other') then
    raise exception 'That is not a documented tool capability type' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(tonde_private.ai_tool_profile_json(p) || jsonb_build_object(
      'tonde_connection', case when p.tool_key in (select c.provider_key from tonde.ai_provider_connections c
        where c.workspace_id = target_workspace and c.state = 'connected')
        then 'connected' else 'none' end,
      'is_connected_provider', p.tool_key in (select ap.key from tonde.ai_providers ap))
    order by p.display_name, p.revision desc), '[]'::jsonb) into profiles
    from tonde.ai_tool_profiles p
    where p.workspace_id = target_workspace
      and (p_include_drafts or p.review_state = 'reviewed')
      and p.superseded_by is null
      and (p_capability_type is null or p.capability_type = p_capability_type);
  return jsonb_build_object('workspace_id', target_workspace, 'tools', profiles,
    'count', jsonb_array_length(profiles),
    'returned_drafts', coalesce(p_include_drafts, false),
    'meaning', 'This is documented production knowledge about external tools, with its source and review
      state. It is not a list of API connections: TONDE holding knowledge about a tool never means TONDE
      can run that tool or bill for it.');
end $$;

revoke all on function tonde.ai_tool_catalog(uuid,text,boolean) from public, anon, authenticated, service_role;

grant execute on function tonde.ai_tool_catalog(uuid,text,boolean) to authenticated, service_role;


-- The Production Kit's AI TOOLS: the tools this creator actually has.
create or replace function tonde.production_ai_tool_set(target_workspace uuid, target_production uuid, p_tool_key text,
  p_display_name text default null, p_tool_profile_id uuid default null, p_note text default '',
  p_remove boolean default false, p_sort_order integer default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; entry tonde.production_ai_tools; profile tonde.ai_tool_profiles; production_row tonde.productions;
begin
  actor := tonde_private.ai_tool_librarian(target_workspace);
  select * into production_row from tonde.productions pr
    where pr.workspace_id = target_workspace and pr.id = target_production;
  if production_row.id is null then
    raise exception 'That Production does not exist in this workspace' using errcode = 'P0002';
  end if;
  if p_tool_key is null or p_tool_key !~ '^[a-z][a-z0-9_]{1,59}$' then
    raise exception 'A tool key is lower-case letters, digits and underscores' using errcode = '22023';
  end if;
  select * into entry from tonde.production_ai_tools t
    where t.workspace_id = target_workspace and t.production_id = target_production and t.tool_key = p_tool_key;
  if coalesce(p_remove, false) then
    if entry.id is null then
      return jsonb_build_object('tool_key', p_tool_key, 'removed', false, 'idempotent', true);
    end if;
    delete from tonde.production_ai_tools where id = entry.id;
    perform tonde_private.audit_event(target_workspace, 'production_ai_tool.removed', entry.id,
      'production_ai_tool', jsonb_build_object('tool_key', p_tool_key, 'production_id', target_production));
    return jsonb_build_object('tool_key', p_tool_key, 'removed', true, 'idempotent', false,
      'meaning', 'The tool is no longer part of this Production''s kit. Nothing else changed.');
  end if;
  if p_tool_profile_id is not null then
    select * into profile from tonde.ai_tool_profiles p
      where p.workspace_id = target_workspace and p.id = p_tool_profile_id;
    if profile.id is null or profile.tool_key <> p_tool_key then
      raise exception 'That profile is not a profile of this tool' using errcode = '22023';
    end if;
    if profile.review_state = 'retired' then
      raise exception 'That profile version is retired' using errcode = 'PT409';
    end if;
  end if;
  if entry.id is null then
    insert into tonde.production_ai_tools(workspace_id, production_id, tool_key, display_name,
      tool_profile_id, note, sort_order, created_by)
    values (target_workspace, target_production, p_tool_key,
      left(btrim(coalesce(p_display_name, initcap(replace(p_tool_key, '_', ' ')))), 120),
      p_tool_profile_id, left(coalesce(p_note, ''), 600), coalesce(p_sort_order, 0), actor)
    returning * into entry;
    perform tonde_private.audit_event(target_workspace, 'production_ai_tool.added', entry.id,
      'production_ai_tool', jsonb_build_object('tool_key', p_tool_key, 'production_id', target_production,
        'profile_id', p_tool_profile_id));
    return jsonb_build_object('tool_key', entry.tool_key, 'display_name', entry.display_name,
      'tool_profile_id', entry.tool_profile_id, 'removed', false, 'created', true,
      'meaning', 'The tool is part of this Production''s kit. TONDE can now direct a Shot towards it, and
        it still needs no credential for it.');
  end if;
  update tonde.production_ai_tools set
    display_name = coalesce(nullif(btrim(coalesce(p_display_name, '')), ''), entry.display_name),
    tool_profile_id = coalesce(p_tool_profile_id, entry.tool_profile_id),
    note = coalesce(nullif(btrim(coalesce(p_note, '')), ''), entry.note),
    sort_order = coalesce(p_sort_order, entry.sort_order),
    updated_at = now()
    where id = entry.id returning * into entry;
  perform tonde_private.audit_event(target_workspace, 'production_ai_tool.updated', entry.id,
    'production_ai_tool', jsonb_build_object('tool_key', p_tool_key, 'profile_id', entry.tool_profile_id));
  return jsonb_build_object('tool_key', entry.tool_key, 'display_name', entry.display_name,
    'tool_profile_id', entry.tool_profile_id, 'removed', false, 'created', false,
    'meaning', 'The kit entry is updated.');
end $$;

revoke all on function tonde.production_ai_tool_set(uuid,uuid,text,text,uuid,text,boolean,integer)
  from public, anon, authenticated, service_role;

grant execute on function tonde.production_ai_tool_set(uuid,uuid,text,text,uuid,text,boolean,integer)
  to authenticated, service_role;


-- The Director's workstation read for one Shot: what to make, how, with which tool, why, the prompt to
-- copy, what must stay unchanged, the expected Result and how TONDE will judge it.
create or replace function tonde.ai_playbook_for_shot(target_workspace uuid, target_production uuid, target_shot uuid,
  p_tool_key text default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare actor uuid; shot tonde.shots; plan tonde.execution_plans; production_row tonde.productions;
  kit jsonb; recommended text; recommended_name text; why text; compiled jsonb; criteria jsonb; check_row tonde.shot_match_reports;
  cost jsonb; profile jsonb;
begin
  if auth.uid() is not null and not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  actor := (select auth.uid());
  select * into production_row from tonde.productions pr
    where pr.workspace_id = target_workspace and pr.id = target_production;
  if production_row.id is null then
    raise exception 'That Production does not exist in this workspace' using errcode = 'P0002';
  end if;
  select * into shot from tonde.shots s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.id = target_shot;
  if shot.id is null then
    raise exception 'That Shot does not exist in this Production' using errcode = 'P0002';
  end if;
  select * into plan from tonde.execution_plans p
    where p.workspace_id = target_workspace and p.production_id = target_production and p.shot_id = target_shot
      and p.execution_method = 'ai';
  -- The kit, with the documented knowledge state of each tool, so the recommendation can only ever name
  -- a tool the creator actually has.
  select coalesce(jsonb_agg(jsonb_build_object(
      'tool_key', t.tool_key, 'display_name', t.display_name, 'profile_id', t.tool_profile_id,
      'kit_note', t.note, 'knowledge_status',
      (tonde_private.ai_tool_knowledge(target_workspace, t.tool_key) ->> 'status'))
    order by t.sort_order, t.display_name), '[]'::jsonb) into kit
    from tonde.production_ai_tools t
    where t.workspace_id = target_workspace and t.production_id = target_production;
  -- The tool the playbook is compiled for: the one asked for, else the one the plan targets and the kit
  -- carries, else the first kit tool with reviewed knowledge.
  if p_tool_key is not null then
    recommended := p_tool_key;
  elsif plan.provider_target is not null and exists (select 1 from tonde.production_ai_tools t
    where t.workspace_id = target_workspace and t.production_id = target_production
      and t.tool_key = plan.provider_target) then
    recommended := plan.provider_target;
  else
    select t.tool_key into recommended from tonde.production_ai_tools t
      where t.workspace_id = target_workspace and t.production_id = target_production
        and (tonde_private.ai_tool_knowledge(target_workspace, t.tool_key) ->> 'status') = 'reviewed'
      order by t.sort_order, t.display_name limit 1;
    if recommended is null then
      select t.tool_key into recommended from tonde.production_ai_tools t
        where t.workspace_id = target_workspace and t.production_id = target_production
        order by t.sort_order, t.display_name limit 1;
    end if;
  end if;
  select t.display_name into recommended_name from tonde.production_ai_tools t
    where t.workspace_id = target_workspace and t.production_id = target_production
      and t.tool_key = recommended;
  if plan.id is not null then
    compiled := tonde_private.ai_playbook_prompt(target_workspace, target_production, target_shot,
      recommended, null, null);
  else
    compiled := null;
  end if;
  profile := compiled -> 'knowledge' -> 'profile';
  why := case
    when recommended is null then
      'No external AI tool is in this Production''s kit yet, so TONDE directs the Shot without naming a
        tool. Add the tools you own, and the playbook adapts to the one you choose.'
    when (compiled ->> 'knowledge_status') = 'reviewed' then format(
      '%s is in your kit and TONDE holds reviewed, documented knowledge of how it reads a prompt, so the
        prompt is adapted for it.', coalesce(recommended_name, initcap(replace(recommended, '_', ' '))))
    when (compiled ->> 'knowledge_status') = 'draft' then format(
      '%s is in your kit. A draft profile exists for it, but nobody reviewed it, so TONDE reports that
        knowledge and does not apply it.', coalesce(recommended_name, initcap(replace(recommended, '_', ' '))))
    else format(
      '%s is in your kit, and TONDE holds no documented knowledge of how it reads a prompt. The playbook is
        compiled from the Shot''s plan alone, and TONDE says so rather than guessing.',
      coalesce(recommended_name, initcap(replace(recommended, '_', ' ')))) end;
  select coalesce(jsonb_agg(jsonb_build_object('criterion', c, 'what_tonde_checks', case c
      when 'shot_objective' then 'the Result serves the Shot''s stated objective'
      when 'subject_identity' then 'the same subject, recognisably, as the plan and locks describe'
      when 'continuity' then 'the traits locked for this Production are preserved'
      when 'composition' then 'the framing and composition the plan asked for'
      when 'lighting' then 'the lighting intent, not merely pleasant light'
      when 'camera_movement' then 'the movement, or the absence of it, that the plan asked for'
      when 'environment' then 'the environment the Shot is set in'
      when 'wardrobe' then 'the wardrobe, as planned'
      when 'props' then 'the props the Shot depends on'
      when 'performance' then 'the performance the Shot needs'
      when 'timing' then 'duration and beat timing against the planned cut'
      when 'reference_relationship' then 'the relationship to the reference the creator started from'
      else 'the criterion the playbook names' end)), '[]'::jsonb) into criteria
    from unnest(tonde_private.ai_playbook_criteria()) as c;
  select * into check_row from tonde.shot_match_reports r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.shot_id = target_shot
      and r.verdict is not null
    order by r.checked_at desc nulls last, r.created_at desc limit 1;
  cost := jsonb_build_object(
    'tonde_cost', jsonb_build_object('state', case when plan.cost_state = 'known' then 'known' else 'unknown' end,
      'amount', plan.cost_amount, 'currency', plan.cost_currency, 'note', plan.cost_note,
      'basis', 'what TONDE would charge for the direction of this Shot, if anything'),
    'external_tool_cost', jsonb_build_object('state', 'estimate', 'kind', 'external',
      'amount', null, 'currency', '', 'note', coalesce(profile ->> 'typical_external_cost_note', ''),
      'basis', 'what the external tool may charge on the creator''s own account; it is never a TONDE charge'),
    'resold_by_tonde', false,
    'estimate_or_actual', 'estimate',
    'meaning', 'Two different costs are named separately: what TONDE charges for directing, and what the
      creator''s own external tool may charge them. TONDE does not resell generation and does not invent a
      figure for a tool whose cost it cannot document.');
  return jsonb_build_object(
    'workspace_id', target_workspace, 'production_id', target_production, 'shot_id', target_shot,
    'shot_objective', jsonb_build_object('title', shot.title, 'description', shot.description,
      'action', shot.action, 'planned_duration_ms', shot.planned_duration_ms),
    'execution', jsonb_build_object('shot_execution_method', shot.execution_method,
      'has_ai_plan', plan.id is not null, 'plan_approval', plan.approval,
      'plan_revision', plan.revision, 'prompt_version', plan.prompt_version,
      'strategies', to_jsonb(array['real','ai','hybrid']),
      'detail', 'REAL captures it, AI executes it in an external tool, HYBRID does both and TONDE
        coordinates the steps. The external tool is where the media is made.'),
    'target_media', compiled ->> 'target_media',
    'recommended_tool', recommended,
    'recommended_tool_name', recommended_name,
    'why', why,
    'kit_tools', kit,
    'prompt', compiled -> 'prompt',
    'prompt_length', compiled -> 'prompt_length',
    'reference_inputs', coalesce((select jsonb_agg(jsonb_build_object('reference_id', r.id,
        'role', r.reference_role, 'priority', r.priority, 'origin', r.origin, 'note', r.note,
        'asset_id', r.asset_id, 'media_id', r.media_id) order by r.priority, r.sort_order, r.id)
      from tonde.ai_shot_references r
      where r.workspace_id = target_workspace and r.production_id = target_production and r.shot_id = target_shot),
      '[]'::jsonb),
    'continuity', coalesce((select jsonb_agg(jsonb_build_object('scope', l.scope, 'label', l.label,
        'locked', l.locked, 'priority', l.priority, 'locked_traits', to_jsonb(l.locked_traits),
        'prohibited_changes', to_jsonb(l.prohibited_changes)) order by l.scope, l.label, l.id)
      from tonde.ai_continuity_locks l
      where l.workspace_id = target_workspace and l.production_id = target_production), '[]'::jsonb),
    'settings', jsonb_build_object('aspect_ratio', plan.aspect_ratio, 'expected_duration_ms',
      plan.expected_duration_ms, 'operation', tonde_private.ai_primary_operation(target_workspace,
        target_production, target_shot), 'model_profile_id', plan.model_profile_id,
      'model_version', plan.model_version, 'provider_target', plan.provider_target),
    'negative_constraints', to_jsonb(plan.negative_constraints),
    'limitations', to_jsonb(plan.limitations),
    'tool_knowledge', case when compiled is null then jsonb_build_object('status', 'absent', 'applied', false,
      'profile', null, 'detail', 'No AI plan is saved for this Shot yet, so there is no playbook prompt and
        no tool knowledge is applied.') else compiled -> 'knowledge' end,
    'adaptations', coalesce(compiled -> 'adaptations', '[]'::jsonb),
    'conflicts', coalesce(compiled -> 'conflicts', '[]'::jsonb),
    'tool_connection', coalesce(compiled ->> 'tool_connection', 'not_applicable'),
    'expected_result', jsonb_build_object('deliverable', compiled ->> 'target_media',
      'detail', 'Upload the file the tool produced back to this Shot. The Result is the return point for
        every execution strategy.'),
    'evaluation_criteria', criteria,
    'cost', cost,
    'last_check', case when check_row.id is null then null else jsonb_build_object(
      'check_id', check_row.id, 'verdict', check_row.verdict, 'instructions', check_row.instructions,
      'tool_key', check_row.tool_key, 'checked_at', check_row.checked_at, 'criteria', check_row.criteria,
      'next_prompt', check_row.next_prompt, 'previous_check_id', check_row.previous_check_id) end,
    'meaning', 'This is direction, not generation. TONDE names what to make, how you can execute it, which
      of your tools fits, why, and the prompt to run there. The media is produced in your tool or on your
      camera, and the Result comes back here to be checked.');
end $$;

revoke all on function tonde.ai_playbook_for_shot(uuid,uuid,uuid,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_playbook_for_shot(uuid,uuid,uuid,text) to authenticated, service_role;


-- The compiled tool-specific prompt on its own, for COPY PROMPT, and for adapting to another of the
-- creator's tools without touching the Shot's plan.
create or replace function tonde.ai_playbook_prompt_compile(target_workspace uuid, target_production uuid,
  target_shot uuid, p_tool_key text default null, p_expected_plan_revision integer default null)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare compiled jsonb; kit_entry tonde.production_ai_tools;
begin
  if auth.uid() is not null and not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  if p_tool_key is not null then
    select * into kit_entry from tonde.production_ai_tools t
      where t.workspace_id = target_workspace and t.production_id = target_production
        and t.tool_key = p_tool_key;
    if kit_entry.id is null then
      raise exception 'TOOL_NOT_IN_KIT: % is not part of this Production''s kit. Add the tools you
        actually have, and TONDE adapts to them.', p_tool_key using errcode = 'PT404';
    end if;
  end if;
  compiled := tonde_private.ai_playbook_prompt(target_workspace, target_production, target_shot,
    p_tool_key, p_expected_plan_revision, null);
  perform tonde_private.audit_event(target_workspace, 'ai_playbook.prompt_compiled', target_shot, 'shot',
    jsonb_build_object('tool_key', p_tool_key, 'knowledge_status', compiled ->> 'knowledge_status',
      'conflicts', compiled -> 'conflicts', 'plan_revision', compiled -> 'plan_revision'));
  return compiled;
end $$;

revoke all on function tonde.ai_playbook_prompt_compile(uuid,uuid,uuid,text,integer)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_playbook_prompt_compile(uuid,uuid,uuid,text,integer)
  to authenticated, service_role;


-- The check. TONDE compares the uploaded Result against the playbook and returns ACCEPT or FIX with
-- instructions, and a FIX produces the next prompt in the same answer.
create or replace function tonde.ai_result_check(target_workspace uuid, target_production uuid, target_shot uuid,
  target_result uuid, p_payload jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare actor uuid; shot tonde.shots; result_row tonde.results; plan tonde.execution_plans;
  previous tonde.shot_match_reports; report tonde.shot_match_reports; payload jsonb := coalesce(p_payload, '{}'::jsonb);
  verdict text; criteria_in jsonb; criteria jsonb; findings jsonb; instructions text; tool_key text;
  prompt_text text; next_prompt text; severe integer; conflicts jsonb; changed jsonb; closed text[];
begin
  actor := tonde_private.ai_tool_librarian(target_workspace);
  if jsonb_typeof(payload) <> 'object' then
    raise exception 'A Director check must be a JSON object' using errcode = '22023';
  end if;
  verdict := payload ->> 'verdict';
  if verdict not in ('accept','fix') then
    raise exception 'A Director check returns accept or fix' using errcode = '22023';
  end if;
  instructions := nullif(btrim(coalesce(payload ->> 'instructions', '')), '');
  if verdict = 'fix' and instructions is null then
    raise exception 'A FIX says what to change' using errcode = '22023';
  end if;
  criteria_in := coalesce(payload -> 'criteria', '[]'::jsonb);
  if jsonb_typeof(criteria_in) <> 'array' or jsonb_array_length(criteria_in) = 0 then
    raise exception 'A Director check names the criteria it judged' using errcode = '22023';
  end if;
  closed := tonde_private.ai_playbook_criteria();
  if exists (select 1 from jsonb_array_elements(criteria_in) c
      where not ((c ->> 'criterion') = any(closed))) then
    raise exception 'CHECK_CRITERION_UNKNOWN: a check judges only %.', array_to_string(closed, ', ')
      using errcode = '22023';
  end if;
  select * into shot from tonde.shots s
    where s.workspace_id = target_workspace and s.production_id = target_production and s.id = target_shot;
  if shot.id is null then
    raise exception 'That Shot does not exist in this Production' using errcode = 'P0002';
  end if;
  select * into result_row from tonde.results r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.id = target_result;
  if result_row.id is null then
    raise exception 'That Result does not exist in this Production' using errcode = 'P0002';
  end if;
  if result_row.shot_id is distinct from target_shot then
    raise exception 'That Result belongs to a different Shot' using errcode = 'PT409';
  end if;
  select * into plan from tonde.execution_plans p
    where p.workspace_id = target_workspace and p.production_id = target_production
      and p.shot_id = target_shot and p.execution_method = 'ai';
  tool_key := coalesce(nullif(btrim(coalesce(payload ->> 'tool_key', '')), ''), plan.provider_target);
  if tool_key is not null and tool_key !~ '^[a-z][a-z0-9_]{1,59}$' then
    raise exception 'A tool key is lower-case letters, digits and underscores' using errcode = '22023';
  end if;
  prompt_text := nullif(coalesce(payload ->> 'prompt_text', ''), '');
  if prompt_text is null and plan.id is not null and length(btrim(plan.provider_prompt)) > 0 then
    prompt_text := plan.provider_prompt;
  end if;
  select * into previous from tonde.shot_match_reports r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.shot_id = target_shot
      and r.verdict is not null
    order by r.checked_at desc nulls last, r.created_at desc limit 1;
  -- What changed since the last check, criterion by criterion, so an iteration is understood rather
  -- than merely counted.
  changed := jsonb_build_object('previous_check_id', previous.id,
    'previous_verdict', previous.verdict, 'previous_instructions', previous.instructions);
  if previous.id is not null then
    changed := changed || jsonb_build_object('criteria_now_passing', coalesce((select jsonb_agg(c ->> 'criterion')
      from jsonb_array_elements(criteria_in) c
      where (c ->> 'result') = 'pass' and exists (select 1 from jsonb_array_elements(previous.criteria) o
        where (o ->> 'criterion') = (c ->> 'criterion') and (o ->> 'result') = 'fail')), '[]'::jsonb),
      'criteria_still_failing', coalesce((select jsonb_agg(c ->> 'criterion')
      from jsonb_array_elements(criteria_in) c
      where (c ->> 'result') = 'fail' and exists (select 1 from jsonb_array_elements(previous.criteria) o
        where (o ->> 'criterion') = (c ->> 'criterion') and (o ->> 'result') = 'fail')), '[]'::jsonb),
      'criteria_newly_failing', coalesce((select jsonb_agg(c ->> 'criterion')
      from jsonb_array_elements(criteria_in) c
      where (c ->> 'result') = 'fail' and not exists (select 1 from jsonb_array_elements(previous.criteria) o
        where (o ->> 'criterion') = (c ->> 'criterion') and (o ->> 'result') = 'fail')), '[]'::jsonb));
  end if;
  findings := coalesce(payload -> 'findings', '[]'::jsonb);
  if jsonb_typeof(findings) <> 'array' then
    raise exception 'Findings are an array' using errcode = '22023';
  end if;
  select count(*) into severe from jsonb_array_elements(criteria_in) c
    where (c ->> 'result') = 'fail' and coalesce(c ->> 'severity', 'material') = 'material';
  if verdict = 'accept' and severe > 0 then
    raise exception 'CHECK_CONTRADICTS_ITSELF: a material criterion is failing, so the Result cannot be
      accepted.' using errcode = 'PT409';
  end if;
  criteria := coalesce((select jsonb_agg(jsonb_build_object('criterion', c ->> 'criterion',
      'result', c ->> 'result', 'severity', coalesce(nullif(c ->> 'severity', ''), 'info'),
      'note', nullif(left(coalesce(c ->> 'note', ''), 1000), '')) order by c ->> 'criterion')
    from jsonb_array_elements(criteria_in) c), '[]'::jsonb);
  -- A FIX produces the next prompt for the same tool, with the correction in it. This is direction, not
  -- a media call: nothing is executed here.
  if verdict = 'fix' and plan.id is not null then
    next_prompt := tonde_private.ai_playbook_prompt(target_workspace, target_production, target_shot,
      tool_key, null, instructions) ->> 'prompt';
  end if;
  insert into tonde.shot_match_reports(workspace_id, production_id, shot_id, result_id, state, findings,
    severity, recommendations, approval, execution_method, tool_key, verdict, instructions, criteria,
    prompt_text, next_prompt, previous_check_id, what_changed, checked_by, checked_at)
  values (target_workspace, target_production, target_shot, target_result, 'complete', findings,
    case when severe > 0 then 'critical' else 'info' end,
    coalesce(payload -> 'recommendations', '[]'::jsonb), 'draft', shot.execution_method, tool_key, verdict,
    instructions, criteria, prompt_text, next_prompt, previous.id, changed, actor, now())
  returning * into report;
  perform tonde_private.audit_event(target_workspace, 'ai_result.checked', report.id, 'shot_match_report',
    jsonb_build_object('shot_id', target_shot, 'result_id', target_result, 'verdict', verdict,
      'tool_key', tool_key, 'failing', severe, 'previous_check_id', previous.id));
  return jsonb_build_object('check_id', report.id, 'shot_id', target_shot, 'result_id', target_result,
    'verdict', verdict, 'instructions', instructions, 'criteria', criteria, 'findings', findings,
    'severity', report.severity, 'tool_key', tool_key, 'checked_at', report.checked_at,
    'prompt_checked', prompt_text, 'next_prompt', next_prompt,
    'what_changed', changed,
    'prompt_version', coalesce(plan.prompt_version, 0),
    'next_step', case when verdict = 'accept'
      then 'The Result is accepted. The Shot is done until something upstream changes.'
      else 'Run the next prompt in your external tool, then upload the new Result and check it again.' end,
    'meaning', case when verdict = 'accept'
      then 'Every criterion TONDE checked is satisfied by the uploaded Result.'
      else 'TONDE found what does not match the playbook and what to change. It did not produce the media:
        the correction is a prompt for the tool you run.' end);
end $$;

revoke all on function tonde.ai_result_check(uuid,uuid,uuid,uuid,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_result_check(uuid,uuid,uuid,uuid,jsonb) to authenticated, service_role;


-- The iteration record for one Shot: every attempt executed externally and every Director check, in
-- order, so PROMPT V1 -> RESULT V1 -> CHECK -> CORRECTION -> PROMPT V2 is readable.
create or replace function tonde.ai_playbook_history(target_workspace uuid, target_production uuid, target_shot uuid,
  p_limit integer default 50) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare attempts jsonb; checks jsonb;
begin
  if auth.uid() is not null and not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'A history read is between 1 and 200 records' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object('attempt_id', a.id, 'attempt_number', a.attempt_number,
      'mode', a.mode, 'provider_key', a.provider_key, 'prompt_version', a.prompt_version,
      'status', a.status, 'result_id', a.result_id, 'output_media_id', a.output_media_id,
      'creator_decision', a.creator_decision, 'created_at', a.created_at)
    order by a.attempt_number), '[]'::jsonb) into attempts
    from tonde.ai_generation_attempts a
    where a.workspace_id = target_workspace and a.production_id = target_production and a.shot_id = target_shot;
  select coalesce(jsonb_agg(jsonb_build_object('check_id', r.id, 'result_id', r.result_id,
      'verdict', r.verdict, 'tool_key', r.tool_key, 'instructions', r.instructions, 'criteria', r.criteria,
      'prompt_checked', r.prompt_text, 'next_prompt', r.next_prompt, 'previous_check_id', r.previous_check_id,
      'what_changed', r.what_changed, 'checked_at', r.checked_at) order by r.checked_at nulls last, r.created_at),
    '[]'::jsonb) into checks
    from tonde.shot_match_reports r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.shot_id = target_shot
      and r.verdict is not null;
  return jsonb_build_object('workspace_id', target_workspace, 'production_id', target_production,
    'shot_id', target_shot, 'attempts', attempts, 'checks', checks,
    'meaning', 'The attempts are what the creator executed in the external tool; the checks are what TONDE
      said about each Result. The media was never produced by TONDE.');
end $$;

revoke all on function tonde.ai_playbook_history(uuid,uuid,uuid,integer)
  from public, anon, authenticated, service_role;

grant execute on function tonde.ai_playbook_history(uuid,uuid,uuid,integer) to authenticated, service_role;


-- The product boundary, stated by the database so an interface can show it and a test can pin it.
create or replace function tonde.ai_director_boundary() returns jsonb
language sql stable set search_path = '' as $$
  select jsonb_build_object(
    'product_role', 'director',
    'direct_media_generation', false,
    'generation_provider_required', false,
    'media_generation_provider_dependency', 'none for the core product',
    'ai_creation', 'external tool playbook plus result checking',
    'execution_strategies', to_jsonb(array['real','ai','hybrid']),
    'tonde_generates_final_media', false,
    'external_tools_are_tonde_truth', false,
    'results_return_to_tonde', true,
    'tonde_compiles_prompts_for_external_tools', true,
    'tonde_evaluates_results', true,
    'tonde_bills_for_tonde_service_only', true,
    'tool_knowledge_is_documented_and_sourced', true,
    'optional_future_connector', 'allowed, optional, and not built',
    'meaning', 'TONDE is the production Director. It analyses, plans, recommends, writes the playbook and
      the prompt for the tool the creator owns, and checks the Result the creator uploads. It does not
      host image or video generation and needs no credential for one.');
$$;

revoke all on function tonde.ai_director_boundary() from public, anon, authenticated, service_role;

grant execute on function tonde.ai_director_boundary() to authenticated, service_role;


alter default privileges in schema tonde revoke execute on functions from public;

alter default privileges in schema tonde_private revoke execute on functions from public;


commit;

-- ==========================================================================
-- 202610050044_prompt11_media_upload_authorization.sql
-- ==========================================================================

-- Prompt 11 repair 044: the inherited Storage INSERT policy looked only at a pending media_files
-- row, so legacy metadata inserts also authorized direct uploads while a newly created intent could
-- not transition the storage object's authorization. Require the matching creator-owned, open intent.
begin;


create or replace function tonde_private.can_upload_storage_object(target_bucket text, target_name text)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1
    from tonde.media_upload_intents i
    join tonde.media_files m on m.workspace_id = i.workspace_id and m.id = i.media_id
    where i.bucket = target_bucket and i.object_key = target_name
      and m.storage_provider = 'supabase' and m.bucket = target_bucket and m.object_key = target_name
      and i.created_by = (select auth.uid()) and m.created_by = (select auth.uid())
      and tonde_private.can_edit_workspace(i.workspace_id)
      and i.state in ('created','uploading','completing') and i.expires_at > now()
      and m.upload_state in ('pending','uploading') and target_bucket <> 'tonde-exports'
      and (m.expires_at is null or m.expires_at > now())
  );
$$;

revoke all on function tonde_private.can_upload_storage_object(text,text)
  from public, anon, authenticated, service_role;

grant execute on function tonde_private.can_upload_storage_object(text,text)
  to authenticated;


alter default privileges in schema tonde revoke execute on functions from public;

commit;

-- ==========================================================================
-- 202610050045_prompt11_signed_upload_authorization.sql
-- ==========================================================================

begin;


-- Storage's signed-upload token bypasses object RLS at upload time, so minting that token must be
-- preceded by this authenticated, workspace-scoped check. It returns only the server-derived object
-- identity for an intent created by this same editor; it never reads a vault secret or creates a URL.
create or replace function tonde.media_upload_signed_request(target_workspace uuid, target_intent uuid)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare intent tonde.media_upload_intents; media tonde.media_files;
begin
  if auth.uid() is null or not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into intent from tonde.media_upload_intents i
    where i.workspace_id = target_workspace and i.id = target_intent;
  if not found then
    raise exception 'That upload intent does not exist in this workspace' using errcode = 'P0002';
  end if;
  if intent.created_by is distinct from auth.uid() then
    raise exception 'Only the creator who opened this upload may receive its signed upload token'
      using errcode = '42501';
  end if;
  if intent.state not in ('created','uploading','completing') or intent.expires_at <= now() then
    raise exception 'UPLOAD_INTENT_CLOSED: this upload is no longer open' using errcode = 'PT409';
  end if;
  select * into media from tonde.media_files m
    where m.workspace_id = target_workspace and m.id = intent.media_id;
  if not found or media.created_by is distinct from auth.uid()
    or media.storage_provider <> 'supabase' or media.bucket <> intent.bucket
    or media.object_key <> intent.object_key or media.upload_state not in ('pending','uploading')
    or (media.expires_at is not null and media.expires_at <= now())
    or intent.bucket = 'tonde-exports' then
    raise exception 'The upload intent no longer authorizes this Storage object' using errcode = 'PT409';
  end if;
  return jsonb_build_object('workspace_id', target_workspace, 'intent_id', intent.id,
    'media_id', media.id, 'bucket', intent.bucket, 'object_key', intent.object_key,
    'expected_mime_type', intent.expected_mime_type, 'expected_bytes', intent.expected_bytes,
    'max_bytes', intent.max_bytes, 'expires_at', intent.expires_at,
    'meaning', 'This authenticated creator may upload once to the exact object named by this open intent.');
end $$;

revoke all on function tonde.media_upload_signed_request(uuid,uuid) from public, anon, authenticated, service_role;

grant execute on function tonde.media_upload_signed_request(uuid,uuid) to authenticated;


alter default privileges in schema tonde revoke execute on functions from public;

commit;

-- ==========================================================================
-- 202610050046_prompt11_storage_limit_enforcement.sql
-- ==========================================================================

begin;


-- Store the MIME allowlist for each protected bucket from the shared media contract. The per-bucket
-- byte ceiling is intentionally preserved: the hosted project currently caps these at 50 MiB.
update storage.buckets set allowed_mime_types = array[
  'image/jpeg','image/png','image/webp','image/gif','image/tiff','image/heic',
  'video/mp4','video/quicktime','video/webm','audio/mpeg','audio/wav','audio/mp4','audio/aac','audio/flac',
  'application/pdf','text/plain','text/vtt','application/x-subrip','application/json',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/zip'
] where id in ('tonde-asset-references','tonde-production-media');

update storage.buckets set allowed_mime_types = array[
  'image/jpeg','image/png','image/webp','image/gif','image/tiff','image/heic',
  'video/mp4','video/quicktime','video/webm','audio/mpeg','audio/wav','audio/mp4','audio/aac','audio/flac'
] where id = 'tonde-results';

update storage.buckets set allowed_mime_types = array[
  'application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/zip','application/json','text/plain'
] where id = 'tonde-exports';


-- Storage bucket limits, not the broader logical media ceilings, are the hard ceiling for an
-- upload. Derive the creator-facing per-purpose limits from the deployed bucket configuration so
-- API clients and the intent-creation RPC publish/enforce the same limit.
create or replace function tonde.media_upload_limits() returns jsonb
language sql stable security definer set search_path = '' as $$
  with base as (
    select jsonb_build_object(
      'schema_version', '1',
      'supported_mime_types', jsonb_build_array('image/jpeg','image/png','image/webp','image/gif',
        'image/tiff','image/heic','video/mp4','video/quicktime','video/webm','audio/mpeg','audio/wav',
        'audio/mp4','audio/aac','audio/flac','application/pdf','text/plain','text/vtt',
        'application/x-subrip','application/json',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document'),
      'purposes', jsonb_build_array(
        jsonb_build_object('purpose','result','max_bytes',34359738368,'note','Captured camera or phone results.'),
        jsonb_build_object('purpose','reference','max_bytes',2147483648,'note','Reference material the creator supplies.'),
        jsonb_build_object('purpose','asset','max_bytes',2147483648,'note','Reusable Assets.'),
        jsonb_build_object('purpose','attachment','max_bytes',536870912,'note','Supporting files.'),
        jsonb_build_object('purpose','export_artifact','max_bytes',21474836480,'note','TONDE-generated export files.')),
      'absolute_max_bytes', 137438953472,
      'resumable_threshold_bytes', 8388608,
      'default_intent_expiry_hours', 24,
      'scanner_configured', exists (select 1 from tonde.media_scans s where s.scanner <> 'none'),
      'note', 'The upload intent carries the ceiling that applies to this configured Storage bucket. A client never chooses the bucket or the object key.') as value
  ), bucket_purposes as (
    select item.value, item.ordinality,
      case item.value ->> 'purpose'
        when 'result' then 'tonde-results'
        when 'export_artifact' then 'tonde-exports'
        when 'attachment' then 'tonde-production-media'
        else 'tonde-asset-references' end as bucket_id
    from base cross join lateral jsonb_array_elements(base.value -> 'purposes') with ordinality as item(value, ordinality)
  ), normalized_purposes as (
    select item.ordinality,
      jsonb_set(
      jsonb_set(item.value, '{max_bytes}', to_jsonb(case
        when bucket.id is null or bucket.file_size_limit is null then 0
        else least((item.value ->> 'max_bytes')::bigint, bucket.file_size_limit) end)),
        '{supported_mime_types}',
        coalesce((
          select jsonb_agg(supported.mime order by supported.mime)
          from jsonb_array_elements_text(base.value -> 'supported_mime_types') as supported(mime)
          where bucket.id is not null
            and (bucket.allowed_mime_types is null or supported.mime = any(bucket.allowed_mime_types))
        ), '[]'::jsonb)
      ) as value
    from bucket_purposes item
    cross join base
    left join storage.buckets as bucket on bucket.id = item.bucket_id
  ), purposes as (
    select coalesce(jsonb_agg(value order by ordinality), '[]'::jsonb) as value
    from normalized_purposes
  ), supported_mimes as (
    select coalesce(jsonb_agg(distinct mime order by mime), '[]'::jsonb) as value
    from normalized_purposes,
      lateral jsonb_array_elements_text(normalized_purposes.value -> 'supported_mime_types') as supported(mime)
  )
  select jsonb_set(jsonb_set(base.value, '{purposes}', purposes.value, true),
    '{supported_mime_types}', supported_mimes.value, true)
  from base cross join purposes cross join supported_mimes;
$$;

revoke all on function tonde.media_upload_limits() from public, anon, authenticated, service_role;

grant execute on function tonde.media_upload_limits() to authenticated, service_role;


-- The caller-visible limits are not the only guard: this trigger also protects intents if a client
-- calls the RPC directly or a bucket's supported MIME list changes after application deployment.
create or replace function tonde_private.guard_media_upload_bucket_limits() returns trigger
language plpgsql security definer set search_path = '' as $$
declare bucket_limit bigint; bucket_mimes text[];
begin
  select b.file_size_limit, b.allowed_mime_types into bucket_limit, bucket_mimes
    from storage.buckets b where b.id = new.bucket;
  if not found then
    raise exception 'The Storage bucket for this upload is not configured' using errcode = '22023';
  end if;
  if bucket_limit is null then
    raise exception 'This Storage bucket has no explicit upload size limit; the deployment limit is unknown'
      using errcode = '22023';
  end if;
  if new.expected_bytes is not null and new.expected_bytes > bucket_limit then
    raise exception 'This upload exceeds the configured Storage bucket limit of % bytes', bucket_limit
      using errcode = '22023';
  end if;
  new.max_bytes := least(new.max_bytes, bucket_limit);
  if bucket_mimes is not null and new.expected_mime_type <> all(bucket_mimes) then
    raise exception 'This file type is not enabled for the configured Storage bucket' using errcode = '22023';
  end if;
  return new;
end $$;

revoke all on function tonde_private.guard_media_upload_bucket_limits() from public, anon, authenticated, service_role;

drop trigger if exists guard_media_upload_bucket_limits on tonde.media_upload_intents;
create trigger guard_media_upload_bucket_limits before insert on tonde.media_upload_intents
  for each row execute function tonde_private.guard_media_upload_bucket_limits();


alter default privileges in schema tonde revoke execute on functions from public;

commit;

-- ==========================================================================
-- 202610050047_publish_verified_media.sql
-- ==========================================================================

-- Prompt 11 repair 047: verification (037) moves media to 'verified', but the Prompt 10
-- publishability gates only accepted 'uploaded', so honestly verified media could never be
-- published, previewed, or downloaded. 'verified' is strictly stronger than 'uploaded'
-- (bytes observed plus recorded checksum), so every gate now accepts both states.
begin;


-- 1. publication_create: verified media carries an observed checksum to pin.
create or replace function tonde.publication_create(target_workspace uuid, target_production uuid, target_result uuid,
  target_provider text, target_media uuid default null, target_destination text default '',
  target_account uuid default null, target_title text default '', target_caption text default '',
  target_visibility text default 'private', target_scheduled_for timestamptz default null,
  target_config jsonb default '{}'::jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare production tonde.productions; result_row tonde.results; media tonde.media_files;
  new_id uuid; category text;
begin
  if not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into production from tonde.productions p
    where p.workspace_id = target_workspace and p.id = target_production and p.lifecycle = 'active';
  if not found then raise exception 'That Production is not available for publishing' using errcode = 'P0002'; end if;
  select * into result_row from tonde.results r
    where r.workspace_id = target_workspace and r.production_id = target_production and r.id = target_result;
  if not found then raise exception 'That Result is not available in this Production' using errcode = 'P0002'; end if;
  select * into media from tonde.media_files m
    where m.workspace_id = target_workspace and m.id = coalesce(target_media, result_row.media_id);
  if not found then raise exception 'That media file is not available in this workspace' using errcode = 'P0002'; end if;
  if media.upload_state not in ('uploaded','verified') then
    raise exception 'Only an uploaded or verified media file can be published' using errcode = 'PT409';
  end if;
  if not exists (select 1 from tonde.integration_providers p where p.key = target_provider) then
    raise exception 'That destination provider is not registered' using errcode = '22023';
  end if;
  if target_account is not null and not exists (select 1 from tonde.integration_connections c
    where c.workspace_id = target_workspace and c.id = target_account and c.provider = target_provider) then
    raise exception 'That destination account is not connected to this provider' using errcode = '22023';
  end if;
  if target_visibility not in ('private','unlisted','public','scheduled') then
    raise exception 'Visibility is private, unlisted, public or scheduled' using errcode = '22023';
  end if;
  if target_visibility = 'scheduled' and (target_scheduled_for is null or target_scheduled_for <= now()) then
    raise exception 'A scheduled publication needs a future time' using errcode = '22023';
  end if;
  if target_visibility <> 'scheduled' and target_scheduled_for is not null then
    raise exception 'Only a scheduled publication carries a scheduled time' using errcode = '22023';
  end if;
  category := case media.file_category when 'video' then 'video' when 'image' then 'image'
    when 'audio' then 'audio' else 'document' end;
  insert into tonde.publications(workspace_id, production_id, production_revision, result_id, result_revision,
    media_id, media_checksum, destination_provider, destination_account_id, destination, destination_config,
    media_type, visibility, scheduled_for, title, caption, created_by)
  values (target_workspace, target_production, production.revision, target_result, result_row.revision,
    media.id, coalesce(media.checksum, ''), target_provider, target_account,
    left(coalesce(target_destination, ''), 300), coalesce(target_config, '{}'::jsonb),
    category, target_visibility, target_scheduled_for,
    left(coalesce(target_title, ''), 300), left(coalesce(target_caption, ''), 5000), auth.uid())
  returning id into new_id;
  return jsonb_build_object('publication_id', new_id, 'state', 'draft',
    'production_id', target_production, 'production_revision', production.revision,
    'result_id', target_result, 'result_revision', result_row.revision,
    'media_id', media.id, 'media_checksum', coalesce(media.checksum, ''),
    'destination_provider', target_provider, 'destination_account_id', target_account,
    'destination', left(coalesce(target_destination, ''), 300),
    'visibility', target_visibility, 'scheduled_for', target_scheduled_for,
    'created_by', auth.uid(), 'created_at', now(),
    'note', 'Nothing was submitted. A creator must mark this ready and authorize this exact version and destination.');
end $$;


-- 2. publication_preview: thumbnail lookup and availability block.
create or replace function tonde.publication_preview(target_workspace uuid, target_publication uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare publication tonde.publications; production tonde.productions; result_row tonde.results;
  media tonde.media_files; provider tonde.integration_providers; connection tonde.integration_connections;
  authorization_row tonde.publication_authorizations; capability_row tonde.integration_provider_capabilities;
  capability text; account_label text := ''; fingerprint text; thumbnail uuid;
  missing text[]; blocked text[] := '{}';
begin
  if not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into publication from tonde.publications p
    where p.workspace_id = target_workspace and p.id = target_publication;
  if not found then raise exception 'That publication does not exist in this workspace' using errcode = 'P0002'; end if;
  select * into production from tonde.productions p
    where p.workspace_id = target_workspace and p.id = publication.production_id;
  select * into result_row from tonde.results r
    where r.workspace_id = target_workspace and r.id = publication.result_id;
  select * into media from tonde.media_files m
    where m.workspace_id = target_workspace and m.id = publication.media_id;
  select id into thumbnail from tonde.media_files m
    where m.workspace_id = target_workspace and m.derived_from_id = publication.media_id
      and m.file_category = 'thumbnail' and m.upload_state in ('uploaded','verified') limit 1;
  select * into provider from tonde.integration_providers p where p.key = publication.destination_provider;
  select * into capability_row from tonde.integration_provider_capabilities c
    where c.provider_key = publication.destination_provider and c.capability_key = 'publish';
  if publication.destination_account_id is not null then
    select * into connection from tonde.integration_connections c
      where c.workspace_id = target_workspace and c.id = publication.destination_account_id;
    account_label := coalesce(connection.external_account_label, '');
  end if;
  select * into authorization_row from tonde.publication_authorizations a
    where a.id = publication.authorization_id;
  capability := tonde_private.integration_capability_reason(target_workspace,
    publication.destination_provider, 'publish');
  fingerprint := tonde_private.publication_fingerprint(target_workspace, target_publication);
  missing := case when connection.id is null or capability_row.provider_key is null then '{}'::text[]
    else array(select s from unnest(capability_row.required_scopes) s
      where not (s = any(coalesce(connection.scopes, '{}')))) end;
  if production.id is null or production.lifecycle <> 'active' then
    blocked := array_append(blocked, 'PRODUCTION_INACTIVE');
  end if;
  if result_row.id is null then
    blocked := array_append(blocked, 'RESULT_MISSING');
  elsif result_row.revision <> publication.result_revision or result_row.media_id <> publication.media_id then
    blocked := array_append(blocked, 'RESULT_CHANGED_SINCE_PINNED');
  end if;
  if media.id is null or media.upload_state not in ('uploaded','verified') then
    blocked := array_append(blocked, 'MEDIA_NOT_AVAILABLE');
  end if;
  if provider.key is null then blocked := array_append(blocked, 'UNKNOWN_PROVIDER'); end if;
  if capability <> 'AVAILABLE' then blocked := array_append(blocked, 'CAPABILITY_UNAVAILABLE'); end if;
  if array_length(missing, 1) is not null then blocked := array_append(blocked, 'MISSING_SCOPE'); end if;
  if authorization_row.id is null or authorization_row.decision <> 'authorize' then
    blocked := array_append(blocked, 'AUTHORIZATION_REQUIRED');
  elsif authorization_row.request_fingerprint <> fingerprint
    or authorization_row.production_revision <> publication.production_revision
    or authorization_row.result_revision <> publication.result_revision
    or authorization_row.media_id <> publication.media_id
    or authorization_row.media_checksum <> publication.media_checksum
    or authorization_row.destination_provider <> publication.destination_provider
    or authorization_row.destination_account_id is distinct from publication.destination_account_id
    or authorization_row.destination <> publication.destination then
    blocked := array_append(blocked, 'AUTHORIZATION_STALE');
  end if;
  if publication.state <> 'ready' then
    blocked := array_append(blocked, 'STATE_' || upper(publication.state::text));
  end if;
  return jsonb_build_object('publication_id', target_publication, 'state', publication.state,
    'production', jsonb_build_object('id', publication.production_id, 'title', production.title,
      'pinned_revision', publication.production_revision, 'current_revision', production.revision),
    'result', jsonb_build_object('id', publication.result_id, 'state', result_row.state,
      'approval', result_row.approval, 'pinned_revision', publication.result_revision,
      'current_revision', result_row.revision),
    'media', jsonb_build_object('id', publication.media_id, 'media_type', publication.media_type,
      'mime_type', media.mime_type, 'bytes', media.bytes, 'pinned_checksum', publication.media_checksum,
      'current_checksum', media.checksum, 'upload_state', media.upload_state,
      'thumbnail_media_id', thumbnail),
    'destination', jsonb_build_object('provider', publication.destination_provider,
      'provider_name', provider.name, 'account_id', publication.destination_account_id,
      'account_label', account_label, 'target', publication.destination,
      'visibility', publication.visibility, 'scheduled_for', publication.scheduled_for),
    'content', jsonb_build_object('title', publication.title, 'caption', publication.caption,
      'settings', publication.destination_config, 'fingerprint', fingerprint),
    'provider_constraints', coalesce(provider.restrictions, '{}'::jsonb),
    'capability', capability, 'missing_scopes', coalesce(missing, '{}'),
    'authorization', jsonb_build_object('authorization_id', publication.authorization_id,
      'decision', authorization_row.decision, 'actor_user_id', authorization_row.actor_user_id,
      'authorized_at', authorization_row.authorized_at),
    'retry_safety', tonde.publication_retry_safety(target_workspace, target_publication),
    'can_submit', array_length(blocked, 1) is null, 'blocked_by', blocked,
    'note', case when array_length(blocked, 1) is null
      then 'Everything this publication needs is present; a creator action may submit it.'
      else 'This publication cannot be submitted yet; blocked_by lists every reason.' end);
end $$;


-- 3. guard_export trigger: a ready export may name a verified artifact.
create or replace function tonde_private.guard_export() returns trigger
language plpgsql security definer set search_path = '' as $$
declare production tonde.productions; artifact tonde.media_files; result_row tonde.results;
  entry jsonb; file_path text; media_id uuid; allowed text[];
begin
  if tg_op = 'INSERT' then
    if new.state <> 'requested' then
      raise exception 'An export begins as a request; its states record what actually happened'
        using errcode = '23514';
    end if;
    if new.generated_media_id is not null or new.manifest <> '{}'::jsonb then
      raise exception 'An export request carries no artifact yet' using errcode = '23514';
    end if;
    -- The revision pin comes from the Production, never from the caller's opinion of it.
    select * into production from tonde.productions p
      where p.workspace_id = new.workspace_id and p.id = new.production_id;
    if not found then
      raise exception 'That Production does not exist in this workspace' using errcode = 'P0002';
    end if;
    if new.production_revision is null then
      new := jsonb_populate_record(new, jsonb_build_object('production_revision', production.revision));
    elsif new.production_revision <> production.revision then
      raise exception 'A new export pins the Production revision it was requested at'
        using errcode = '23514';
    end if;
    return new;
  end if;
  -- The product identity and the pinned version are what the export was requested for; they are
  -- never rewritten afterwards. (guard_mutation covers id/workspace/production/created_at.) `kind` is
  -- absent from this comparison on purpose: it is a stored generated column, so it is hashed from the
  -- requested format and PostgreSQL computes it only after BEFORE triggers have run.
  if (new.requested_format, new.package_type, new.production_version_id,
      new.production_revision, new.job_id, new.requested_by)
    is distinct from
    (old.requested_format, old.package_type, old.production_version_id,
     old.production_revision, old.job_id, old.requested_by) then
    raise exception 'This export already names the exact product and Production version it was requested for'
      using errcode = '23514';
  end if;
  if new.state <> old.state then
    allowed := case old.state
      when 'requested' then array['building','failed','expired']
      when 'building' then array['ready','failed','expired']
      when 'ready' then array['expired']
      else array[]::text[] end;
    if not (new.state::text = any(allowed)) then
      raise exception 'An export in % cannot become %; that did not happen', old.state, new.state
        using errcode = 'PT409';
    end if;
  end if;
  if new.state = 'expired' and new.expired_at is null then
    new := jsonb_populate_record(new, jsonb_build_object('expired_at', now()));
  end if;
  if new.state <> 'ready' then return new; end if;
  -- READY names a real artifact: an uploaded export file in the private exports bucket.
  select * into artifact from tonde.media_files m
    where m.workspace_id = new.workspace_id and m.id = new.generated_media_id;
  if not found or artifact.bucket <> 'tonde-exports' or artifact.file_category <> 'export'
    or artifact.upload_state not in ('uploaded','verified') then
    raise exception 'A ready export names an uploaded or verified export artifact in the private exports bucket'
      using errcode = '23514';
  end if;
  -- The manifest describes exactly this export, this version and this format.
  if not (new.manifest ? 'schema_version' and new.manifest ? 'export_id' and new.manifest ? 'workspace_id'
    and new.manifest ? 'production_id' and new.manifest ? 'production_revision'
    and new.manifest ? 'generated_at' and new.manifest ? 'format'
    and jsonb_typeof(new.manifest->'files') = 'array') then
    raise exception 'An export manifest names the export, its Production version, its format and its files'
      using errcode = '23514';
  end if;
  if (new.manifest->>'export_id')::uuid <> new.id
    or (new.manifest->>'workspace_id')::uuid <> new.workspace_id
    or (new.manifest->>'production_id')::uuid <> new.production_id
    or (new.manifest->>'production_revision')::integer <> new.production_revision
    or new.manifest->>'format' <> new.requested_format then
    raise exception 'The manifest must describe exactly the version and format this export pins'
      using errcode = '23514';
  end if;
  -- Every file has a deterministic relative path; checksums are recorded or omitted, never faked.
  for entry in select * from jsonb_array_elements(new.manifest->'files') loop
    file_path := entry->>'path';
    if file_path is null or file_path = '' or file_path like '/%'
      or file_path ~ '(^|/)\.\.(/|$)' or file_path !~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$' then
      raise exception 'Every export file has a deterministic relative path' using errcode = '23514';
    end if;
    if entry ? 'checksum' and length(coalesce(entry->>'checksum', '')) < 8 then
      raise exception 'A file checksum is recorded or omitted, never invented' using errcode = '23514';
    end if;
    if entry ? 'bytes' and coalesce((entry->>'bytes')::bigint, 0) < 0 then
      raise exception 'An exported file cannot have a negative size' using errcode = '23514';
    end if;
    if entry ? 'media_id' then
      media_id := (entry->>'media_id')::uuid;
      select * into artifact from tonde.media_files m
        where m.workspace_id = new.workspace_id and m.id = media_id;
      if not found then
        raise exception 'An exported file can only reference media of this workspace' using errcode = '23514';
      end if;
    end if;
  end loop;
  -- References are shipped as metadata; copied media requires rights TONDE actually has.
  for entry in select * from jsonb_array_elements(coalesce(new.manifest->'references', '[]'::jsonb)) loop
    if entry ? 'copied_media_id' then
      if coalesce(entry->>'rights_classification', 'unknown') not in
        ('user_owned','licensed','brand_owned','authorized_identity') then
        raise exception 'A Reference TONDE does not own is exported as metadata, never as copied media'
          using errcode = '23514';
      end if;
      select * into artifact from tonde.media_files m
        where m.workspace_id = new.workspace_id and m.id = (entry->>'copied_media_id')::uuid;
      if not found then
        raise exception 'A copied Reference can only use media of this workspace' using errcode = '23514';
      end if;
    end if;
  end loop;
  -- Results in a package belong to this Production, and only an accepted Result ships its media.
  for entry in select * from jsonb_array_elements(coalesce(new.manifest->'results', '[]'::jsonb)) loop
    if not (entry ? 'result_id') then
      raise exception 'Every exported Result names the Result it describes' using errcode = '23514';
    end if;
    select * into result_row from tonde.results r
      where r.workspace_id = new.workspace_id and r.production_id = new.production_id
        and r.id = (entry->>'result_id')::uuid;
    if not found then
      raise exception 'An export can only name Results of this Production' using errcode = '23514';
    end if;
    if entry ? 'media_id' then
      if result_row.approval <> 'approved' and result_row.state not in ('approved','final') then
        raise exception 'Only an accepted Result ships its media in an export' using errcode = '23514';
      end if;
      if result_row.media_id <> (entry->>'media_id')::uuid then
        raise exception 'An exported Result names the media of that Result' using errcode = '23514';
      end if;
    end if;
  end loop;
  return new;
end $$;


-- 4. export_download: verified export files remain downloadable.
create or replace function tonde.export_download(target_workspace uuid, target_export uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare export_row tonde.exports; artifact tonde.media_files;
begin
  if not tonde_private.is_workspace_member(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into export_row from tonde.exports e
    where e.workspace_id = target_workspace and e.id = target_export;
  if not found then raise exception 'That export does not exist in this workspace' using errcode = 'P0002'; end if;
  if export_row.state = 'expired' then
    raise exception 'This export expired and has no file to download' using errcode = 'PT409';
  end if;
  if export_row.state <> 'ready' then
    raise exception 'This export is % and has no file to download yet', export_row.state using errcode = 'PT409';
  end if;
  if export_row.expires_at is not null and export_row.expires_at <= now() then
    raise exception 'This export has reached the end of its download window' using errcode = 'PT409';
  end if;
  select * into artifact from tonde.media_files m
    where m.workspace_id = target_workspace and m.id = export_row.generated_media_id
      and m.upload_state in ('uploaded','verified') and m.file_category = 'export';
  if not found then
    raise exception 'The export file is not available' using errcode = 'PT409';
  end if;
  return jsonb_build_object('export_id', target_export, 'authorized', true,
    'kind', export_row.kind, 'format', export_row.requested_format,
    'production_id', export_row.production_id, 'production_revision', export_row.production_revision,
    'media_id', artifact.id, 'bucket', artifact.bucket, 'object_key', artifact.object_key,
    'bytes', artifact.bytes, 'file_count', export_row.file_count,
    'content_checksum', export_row.content_checksum,
    'download_expires_at', now() + interval '5 minutes',
    'note', 'The backend mints a short-lived signed URL for exactly these coordinates; the export bucket has no client read path.');
end $$;


commit;

-- ==========================================================================
-- 202610050048_revoke_anon_function_execute.sql
-- ==========================================================================

-- Prompt 11 repair 048: functions default to PUBLIC execute, and earlier packets granted
-- authenticated/service_role without revoking that default, so anon can route to RPCs
-- (every RPC still denies anonymous in-body with 42501). Strip the default surface while
-- preserving every explicit grant. Idempotent: revoking an absent privilege is a no-op.
begin;

do $$
declare fn record;
begin
  for fn in
    select n.nspname as schema_name, p.proname as fn_name,
      pg_get_function_identity_arguments(p.oid) as args
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname in ('tonde', 'tonde_private') and p.prokind in ('f', 'p')
  loop
    execute format('revoke all on function %I.%I(%s) from public, anon',
      fn.schema_name, fn.fn_name, fn.args);
  end loop;
end $$;

commit;

-- ==========================================================================
-- 202610050049_team_invites.sql
-- ==========================================================================

-- Additive migration: team workspace invitations via single-use links.
--
-- There is no email delivery in this deployment, so an invitation is a
-- single-use token link the owner/admin shares manually. The raw token is
-- shown once at creation; only its SHA-256 hash is stored. All writes pass
-- through the guarded RPCs below, which run as SECURITY DEFINER and re-check
-- owner/admin authority on every call. No grants on the table itself are
-- given to authenticated users, so invite hashes are never client-readable.
-- The invites table is deliberately excluded from the audit trigger: audit
-- rows would persist token hashes alongside history.
begin;

create table if not exists tonde.workspace_invites (
  id uuid primary key default gen_random_uuid(),
  workspace_id uuid not null references tonde.workspaces(id) on delete cascade,
  role tonde.member_role not null check (role in ('admin', 'editor', 'viewer')),
  token_hash text not null unique check (token_hash <> ''),
  created_by uuid not null references auth.users(id) on delete cascade,
  expires_at timestamptz not null,
  accepted_at timestamptz,
  accepted_user_id uuid references auth.users(id) on delete set null,
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (workspace_id, id),
  check (expires_at > created_at),
  check ((accepted_at is null) = (accepted_user_id is null))
);

create index if not exists workspace_invites_by_workspace on tonde.workspace_invites(workspace_id);

alter table tonde.workspace_invites enable row level security;

-- Owner/admin read of invite records for the manage view. Creation,
-- revocation and acceptance go through the guarded RPCs, never RLS writes.
do $tonde_idem$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'tonde'
      and tablename = 'workspace_invites'
      and policyname = 'invites_admin_read'
  ) then
    execute $tonde_idem_ddl$create policy invites_admin_read on tonde.workspace_invites for select to authenticated
  using (tonde_private.is_workspace_admin(workspace_id))$tonde_idem_ddl$;
  end if;
end
$tonde_idem$;

grant select on tonde.workspace_invites to authenticated;

create or replace function tonde.create_workspace_invite(target_workspace uuid, invite_role tonde.member_role,
  token_hash text, expires_at timestamptz)
returns uuid language plpgsql security definer set search_path = '' as $$
declare invite_id uuid;
begin
  if (select auth.uid()) is null then
    raise exception sqlstate '42501' using message = 'Sign in to continue.';
  end if;
  if not tonde_private.is_workspace_admin(target_workspace) then
    raise exception sqlstate '42501' using message = 'Only a workspace owner or administrator can invite.';
  end if;
  if invite_role not in ('admin', 'editor', 'viewer') then
    raise exception sqlstate '22023' using message = 'Invites grant admin, editor, or viewer. Ownership is never granted by invite.';
  end if;
  if token_hash is null or token_hash !~ '^[0-9a-f]{64}$' then
    raise exception sqlstate '22023' using message = 'The invite credential is malformed.';
  end if;
  if expires_at is null or expires_at <= now() + interval '1 hour' or expires_at > now() + interval '30 days' then
    raise exception sqlstate '22023' using message = 'An invite lasts between one hour and thirty days.';
  end if;
  insert into tonde.workspace_invites(workspace_id, role, token_hash, created_by, expires_at)
    values (target_workspace, invite_role, token_hash, (select auth.uid()), expires_at)
    returning id into invite_id;
  return invite_id;
end;
$$;

create or replace function tonde.revoke_workspace_invite(invite_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare invite_workspace uuid;
begin
  if (select auth.uid()) is null then
    raise exception sqlstate '42501' using message = 'Sign in to continue.';
  end if;
  select workspace_id into invite_workspace from tonde.workspace_invites where id = invite_id;
  if not found then
    raise exception sqlstate 'P0002' using message = 'That invite does not exist.';
  end if;
  if not tonde_private.is_workspace_admin(invite_workspace) then
    raise exception sqlstate '42501' using message = 'Only a workspace owner or administrator can revoke invites.';
  end if;
  update tonde.workspace_invites set revoked_at = now(), updated_at = now()
    where id = invite_id and revoked_at is null and accepted_at is null;
end;
$$;

create or replace function tonde.accept_workspace_invite(p_token_hash text)
returns table(workspace_id uuid, role tonde.member_role)
language plpgsql security definer set search_path = '' as $$
declare invite_row tonde.workspace_invites%rowtype;
declare caller uuid;
begin
  caller := (select auth.uid());
  if caller is null then
    raise exception sqlstate '42501' using message = 'Sign in to accept this invite.';
  end if;
  select * into invite_row from tonde.workspace_invites
    where token_hash = p_token_hash
    for update;
  if not found or invite_row.revoked_at is not null
    or invite_row.accepted_at is not null or invite_row.expires_at <= now() then
    raise exception sqlstate 'PT409' using message = 'This invite link is invalid, expired, revoked, or already used.';
  end if;
  if not exists (select 1 from tonde.workspaces w
    where w.id = invite_row.workspace_id and w.lifecycle = 'active') then
    raise exception sqlstate 'PT409' using message = 'That workspace is no longer active.';
  end if;
  if exists (select 1 from tonde.workspace_members m
    where m.workspace_id = invite_row.workspace_id and m.user_id = caller) then
    raise exception sqlstate 'PT409' using message = 'You are already a member of this workspace.';
  end if;
  insert into tonde.workspace_members(workspace_id, user_id, role)
    values (invite_row.workspace_id, caller, invite_row.role);
  update tonde.workspace_invites set accepted_at = now(), accepted_user_id = caller, updated_at = now()
    where id = invite_row.id;
  workspace_id := invite_row.workspace_id;
  role := invite_row.role;
  return next;
end;
$$;

grant execute on function tonde.create_workspace_invite(uuid, tonde.member_role, text, timestamptz),
  tonde.revoke_workspace_invite(uuid),
  tonde.accept_workspace_invite(text) to authenticated;

commit;

-- ==========================================================================
-- 202610050050_card_download_scope.sql
-- ==========================================================================

-- 050: card-scoped downloads ride the Prompt 10 export law, unchanged.
--
-- A download is still a pinned-version export built by the server and served through authorized
-- expiring access. This migration only records *which cards* a full-document PDF covers, so Studio
-- can offer Current Card / Selected Cards / Episode / Shot-prompt downloads without a second system:
--
-- * `scope_type` names the download shape; `scope_refs` carries the card/shot selection.
-- * `full_production` is the previous behavior (every card, in production order) and stays default.
-- * A non-full scope is only honest for a full_document PDF: the card renderer is a PDF renderer,
--   and a production package is a different product with its own package_type narrowing.
-- * Requested ids are verified against this production at request time; the builder additionally
--   filters everything it renders to this production, so an unknown id can only narrow, never leak.
--
-- Schema impact: two additive columns on tonde.exports (text + jsonb with justification below).
-- Ownership/hierarchy/status/timing/revision/access/storage/index notes:
-- * No new table, no new bucket, no RLS change: the columns inherit the exports row policy.
-- * No status/approval/lock semantics change; plain text/jsonb hold no durations or versions.
-- * No new index: exports are read by id; scope is never a query predicate.
-- * Backfill: existing rows read as full_production via the column defaults; old clients that omit
--   scope keep previous behavior. Rollback: drop the columns and the replaced function version.
-- * Invariants: INV-EXPORT-PIN (Amendment D law 9, constitution section 12/21).

begin;


alter table tonde.exports
  add column if not exists scope_type text not null default 'full_production';
alter table tonde.exports
  add column if not exists scope_refs jsonb not null default '{}'::jsonb;


-- The creator action is replaced, not edited in place: the previous 5-argument version stays in
-- history (migration 033) and this 7-argument version carries scope forward.
drop function if exists tonde.export_request(uuid,uuid,text,text,text);


create or replace function tonde.export_request(target_workspace uuid, target_production uuid, target_kind text,
  target_format text, target_package_type text default 'complete',
  target_scope_type text default 'full_production', target_scope_refs jsonb default '{}'::jsonb)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare production tonde.productions; version_id uuid; job_id uuid; export_id uuid;
declare scope_refs jsonb := coalesce(target_scope_refs, '{}'::jsonb);
declare scene_id uuid; shot_id uuid; scene_text text; shot_text text;
begin
  if not tonde_private.can_edit_workspace(target_workspace) then
    raise exception 'Workspace access denied' using errcode = '42501';
  end if;
  select * into production from tonde.productions p
    where p.workspace_id = target_workspace and p.id = target_production and p.lifecycle = 'active';
  if not found then raise exception 'That Production is not available for export' using errcode = 'P0002'; end if;
  if target_kind not in ('full_document','production_package') then
    raise exception 'An export is a full_document or a production_package' using errcode = '22023';
  end if;
  if target_format not in ('pdf','docx','zip','json') then
    raise exception 'Export formats are pdf, docx, zip and json' using errcode = '22023';
  end if;
  if target_kind = 'full_document' and target_format not in ('pdf','docx') then
    raise exception 'A full document is PDF or DOCX; a ZIP is the production package'
      using errcode = '22023';
  end if;
  if target_kind = 'production_package' and target_format not in ('zip','json') then
    raise exception 'A production package is a ZIP (or its structured-data JSON); a PDF is the full document'
      using errcode = '22023';
  end if;
  if target_package_type not in ('complete','script','shot_list','storyboard','prompt_pack',
    'camera_plan','continuity_report','audio_plan','edit_plan','structured_data') then
    raise exception 'That is not a supported export package type' using errcode = '22023';
  end if;
  if target_scope_type not in ('full_production','current_card','selected_cards','episode','shot_prompt') then
    raise exception 'That is not a supported download scope' using errcode = '22023';
  end if;
  if target_scope_type <> 'full_production'
    and (target_kind <> 'full_document' or target_format <> 'pdf') then
    raise exception 'A card download is a PDF full document; other products keep their own narrowing'
      using errcode = '22023';
  end if;
  if jsonb_typeof(scope_refs) <> 'object' then
    raise exception 'Download scope must name its cards as an object' using errcode = '22023';
  end if;
  -- Every requested card and shot must belong to this production; anything else is refused here,
  -- and the builder filters to this production again, so scope can only narrow, never leak.
  -- The id lists are validated as UUID text before casting: a malformed id is an honest 22023
  -- refusal, never a bare cast error, and `#>>` is never applied to text (it is a jsonb operator).
  if jsonb_typeof(coalesce(scope_refs->'scene_ids', '[]'::jsonb)) <> 'array' then
    raise exception 'Download scope must name its cards as a list' using errcode = '22023';
  end if;
  if jsonb_typeof(coalesce(scope_refs->'shot_ids', '[]'::jsonb)) <> 'array' then
    raise exception 'Download scope must name its shots as a list' using errcode = '22023';
  end if;
  for scene_text in select value from jsonb_array_elements_text(
    coalesce(scope_refs->'scene_ids', '[]'::jsonb)) as value loop
    if scene_text !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      raise exception 'A download can only name cards of this Production' using errcode = '22023';
    end if;
    scene_id := scene_text::uuid;
    if not exists (select 1 from tonde.scenes s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.id = scene_id and s.lifecycle = 'active') then
      raise exception 'A download can only name cards of this Production' using errcode = '22023';
    end if;
  end loop;
  for shot_text in select value from jsonb_array_elements_text(
    coalesce(scope_refs->'shot_ids', '[]'::jsonb)) as value loop
    if shot_text !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
      raise exception 'A download can only name shots of this Production' using errcode = '22023';
    end if;
    shot_id := shot_text::uuid;
    if not exists (select 1 from tonde.shots s where s.workspace_id = target_workspace
      and s.production_id = target_production and s.id = shot_id and s.lifecycle = 'active') then
      raise exception 'A download can only name shots of this Production' using errcode = '22023';
    end if;
  end loop;
  -- The version this export names comes from the canonical history, not from the caller.
  select id into version_id from tonde.object_versions v
    where v.workspace_id = target_workspace and v.object_id = target_production and v.branch_name = 'main'
    order by v.revision desc limit 1;
  if version_id is null then
    raise exception 'This Production has no recorded version to export' using errcode = 'PT409';
  end if;
  insert into tonde.jobs(workspace_id, production_id, job_type, requested_by, input_metadata)
  values (target_workspace, target_production, 'export', auth.uid(),
    jsonb_build_object('export_kind', target_kind, 'format', target_format,
      'package_type', target_package_type, 'scope_type', target_scope_type))
  returning id into job_id;
  insert into tonde.exports(workspace_id, production_id, job_id, requested_format, package_type,
    production_version_id, production_revision, requested_by, scope_type, scope_refs)
  values (target_workspace, target_production, job_id, target_format, target_package_type,
    version_id, production.revision, auth.uid(), target_scope_type, scope_refs)
  returning id into export_id;
  perform tonde_private.audit_event(target_workspace, 'export.requested', export_id, 'export',
    jsonb_build_object('kind', target_kind, 'format', target_format,
      'package_type', target_package_type, 'scope_type', target_scope_type,
      'production_revision', production.revision, 'job_id', job_id));
  return jsonb_build_object('export_id', export_id, 'job_id', job_id, 'state', 'requested',
    'kind', target_kind, 'format', target_format, 'package_type', target_package_type,
    'scope_type', target_scope_type, 'scope_refs', scope_refs,
    'production_id', target_production, 'production_revision', production.revision,
    'production_version_id', version_id,
    'note', 'The export is requested and pinned to this Production version. Building runs as durable work; no file exists yet and no download is available.');
end $$;


revoke all on function tonde.export_request(uuid,uuid,text,text,text,text,jsonb)
  from public, anon, authenticated, service_role;

grant execute on function tonde.export_request(uuid,uuid,text,text,text,text,jsonb) to authenticated;


commit;

-- ==========================================================================
-- 202610050052_card_direction_system.sql
-- ==========================================================================

-- Additive migration: the Production Card direction system.
--
-- A Card IS the canonical Scene. This migration deliberately adds no second Card table: the
-- Card-level direction, its provenance and its last validation report live on the Scene row that
-- Scene already is, so there is exactly one Master Production truth (constitution: one Master
-- Production; the Card is a view of it, never a parallel copy).
--
-- Everything the Card needs from the persistence layer already exists on tonde.scenes and is
-- therefore reused rather than re-implemented:
--   * guard_mutation()      - a locked Card refuses edits, revisions are database-managed, and an
--                             approved Card becomes changed_after_approval instead of silently
--                             staying approved.
--   * capture_revision()    - every change is snapshotted into tonde.object_versions, so a Card has
--                             real revisions and undo/redo history for free.
--   * register_object()     - the Card is already a registered `scene` object.
--
-- The single new write path is one guarded RPC. It re-checks the workspace guard, the Card's
-- lifecycle, the lock and the caller's expected revision, and only then patches the Card columns.
-- A stale write raises PT409 so PostgREST returns HTTP 409 instead of retrying a conflict forever
-- (migration 030's rule: never raise a bare class-40 SQLSTATE for a product decision).
begin;


-- 1. Card-level direction on the canonical Card. `card_mode` reuses the execution_method type
-- (real / ai / hybrid) because a Card's mode is the same vocabulary as its Shots'.
alter table tonde.scenes
  add column if not exists card_mode tonde.execution_method not null default 'real';

alter table tonde.scenes
  add column if not exists card_direction jsonb not null default '{}'::jsonb
    check (jsonb_typeof(card_direction) = 'object');

alter table tonde.scenes
  add column if not exists card_provenance jsonb not null default '{}'::jsonb
    check (jsonb_typeof(card_provenance) = 'object');

alter table tonde.scenes
  add column if not exists card_validation jsonb not null default '{}'::jsonb
    check (jsonb_typeof(card_validation) = 'object');

alter table tonde.scenes
  add column if not exists card_generated_by text not null default 'deterministic'
    check (card_generated_by in ('deterministic', 'director', 'creator'));


-- Which Cards have direction at all is a common Studio question, so it is indexed.
create index if not exists scenes_with_card_direction on tonde.scenes(workspace_id, production_id, sort_order)
  where card_direction <> '{}'::jsonb;


-- 2. Writing a Card's direction. One row, one revision, one authority check.
create or replace function tonde.card_direction_write(
  target_workspace uuid, target_production uuid, target_scene uuid,
  direction jsonb, mode_input text, provenance jsonb, validation jsonb,
  generated_by text, expected_revision integer)
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  current tonde.scenes;
  desired_mode tonde.execution_method;
  section text;
  section_text text;
  saved tonde.scenes;
begin
  perform tonde_private.studio_guard(target_workspace, target_production, null);
  select * into current from tonde.scenes
    where workspace_id = target_workspace and production_id = target_production and id = target_scene;
  if not found then
    raise exception 'Card unavailable' using errcode = 'P0002';
  end if;
  if current.lifecycle <> 'active' then
    raise exception 'This Card is archived' using errcode = '23514';
  end if;
  -- A locked Card is the creator's authority over a version: refuse, and say how to proceed.
  if current.locked_at is not null then
    raise exception 'This Card is locked. Unlock it before changing its direction' using errcode = 'PT409';
  end if;
  if expected_revision is not null and current.revision <> expected_revision then
    raise exception 'This Card changed since you loaded it' using errcode = 'PT409';
  end if;

  if direction is null or jsonb_typeof(direction) <> 'object' then
    raise exception 'Card direction must be a JSON object' using errcode = '22023';
  end if;
  if length(btrim(coalesce(direction ->> 'title', ''))) < 2 then
    raise exception 'A Card needs a title before its direction can be saved' using errcode = '22023';
  end if;
  if length(coalesce(direction ->> 'title', '')) > 160 then
    raise exception 'A Card title is at most 160 characters' using errcode = '22023';
  end if;
  if coalesce(mode_input, '') not in ('real', 'ai', 'hybrid') then
    raise exception 'Unsupported Card mode' using errcode = '22023';
  end if;
  if coalesce(generated_by, 'director') not in ('deterministic', 'director', 'creator') then
    raise exception 'Unsupported Card direction source' using errcode = '22023';
  end if;
  desired_mode := mode_input::tonde.execution_method;

  -- Bounds keep a Card a Card: a runaway generation must not store a production manual in one
  -- section, and a value that is not text is a rejected request rather than a silent cast.
  for section in select jsonb_object_keys(direction) loop
    if jsonb_typeof(direction -> section) not in ('string', 'array') then
      raise exception 'Card direction section % must be text', section using errcode = '22023';
    end if;
    if jsonb_typeof(direction -> section) = 'string' then
      section_text := direction ->> section;
    else
      select string_agg(value, ' ') into section_text from jsonb_array_elements_text(direction -> section) as value;
    end if;
    if length(coalesce(section_text, '')) > 6000 then
      raise exception 'Card direction section % is too long to store', section using errcode = '22023';
    end if;
  end loop;
  if octet_length(direction::text) > 40000 then
    raise exception 'This Card direction is too large to store as one Card' using errcode = '22023';
  end if;

  update tonde.scenes
    set card_direction = direction,
        card_mode = desired_mode,
        card_provenance = coalesce(provenance, '{}'::jsonb),
        card_validation = coalesce(validation, '{}'::jsonb),
        card_generated_by = coalesce(generated_by, 'director')
    where workspace_id = target_workspace and production_id = target_production and id = target_scene
    returning * into saved;

  return jsonb_build_object(
    'id', saved.id, 'revision', saved.revision, 'card_mode', saved.card_mode,
    'card_generated_by', saved.card_generated_by, 'card_direction', saved.card_direction,
    'card_validation', saved.card_validation, 'card_provenance', saved.card_provenance,
    'approval', saved.approval, 'updated_at', saved.updated_at);
end $$;

revoke all on function tonde.card_direction_write(uuid, uuid, uuid, jsonb, text, jsonb, jsonb, text, integer)
  from public, anon, authenticated, service_role;

grant execute on function tonde.card_direction_write(uuid, uuid, uuid, jsonb, text, jsonb, jsonb, text, integer)
  to authenticated;


-- 3. Reading is a plain RLS-filtered select on tonde.scenes: Card direction is production truth, not
-- a private side channel, so no read RPC is added. The existing tenant policies already cover it,
-- and `zz_stale_on_scene_change` / `zz_continuity_on_scene_change` already mark dependent analyses
-- stale when a Card's row changes, so a new direction automatically ages the recorded analyses
-- that read it. Nothing else needs to be wired for that.

-- Rollback note: this migration is additive and forward-only. Reverting it means dropping the five
-- card_* columns and the card_direction_write function in a NEW migration; applied history is never
-- rewritten.

commit;

-- ==========================================================================
-- 202610050053_director_operation_key_idempotency.sql
-- ==========================================================================

-- Forward repair: a Director operation is identified by its idempotency key, not only by the
-- process-local UUID the caller happened to generate.
--
-- Reproduced on the linked project through the deployed API (2026-10-14): pressing DIRECT twice with
-- unchanged intake returned HTTP 503
--   duplicate key value violates unique constraint "director_operations_workspace_id_idempotency_key_key"
-- The deterministic envelopes (OperationEnvelope.with_idempotency_key: intent_interpretation,
-- story_generation, ...) derive a stable key from the operation type, the Production revision, the
-- intake revision and a payload digest, so an identical repeat request carries the same key. Migration
-- 012 reconciled only by operation_id, so the repeat request found no row, inserted, and failed the
-- unique (workspace_id, idempotency_key) constraint instead of returning the operation already
-- recorded. The creator's own retry path ("DIRECT THIS again to retry the plan") was therefore broken
-- after the first press, and a page reload that replays a saved intake failed the same way.
--
-- The product rule is unchanged and the database stays the authority for idempotency: the same key
-- means the same operation. A repeat with the same key returns the recorded row (idempotent true) and
-- updates the still-open fields exactly as an operation_id match does. A repeat that carries a
-- different payload hash for a completed, hashed operation is a genuine conflict and is refused with
-- PT409 (maps to HTTP 409). The two operations-id integrity rules already refused in 012 (an operation
-- id reused with a different key, or a completed operation rewritten with different content) now use
-- the same mapped PT409 instead of returning an opaque class-23 failure as HTTP 503.
--
-- Access is unchanged: create or replace keeps the existing owner, security definer mode, search_path
-- and grants from migration 012 (authenticated EXECUTE, revoked from anon and service_role).
--
-- Rollback note: forward-only. Reverting means dropping this reconciliation from a NEW migration;
-- applied history is never rewritten.
begin;


create or replace function tonde.record_director_operation(
  target_workspace uuid, target_production uuid, operation_record jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare existing tonde.director_operations; saved tonde.director_operations;
  desired_status text;
begin
  perform tonde_private.director_guard(target_workspace);
  if jsonb_typeof(operation_record) <> 'object' or pg_column_size(operation_record) > 500000
    or coalesce(length(operation_record->>'operation_id'), 0) <> 36
    or coalesce(length(btrim(operation_record->>'operation_type')), 0) = 0
    or coalesce(length(btrim(operation_record->>'idempotency_key')), 0) = 0 then
    raise exception 'Invalid Director operation record' using errcode = '22023';
  end if;
  if not exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production) then
    raise exception 'Production unavailable' using errcode = 'P0002';
  end if;
  desired_status := coalesce(operation_record->>'status', 'queued');
  if desired_status not in ('queued','preprocessing','analyzing','synthesizing','succeeded','partial','failed','cancelled') then
    raise exception 'Unsupported operation status' using errcode = '22023';
  end if;
  -- Same operation id: resume the recorded operation.
  select * into existing from tonde.director_operations
    where workspace_id = target_workspace and operation_id = (operation_record->>'operation_id')::uuid for update;
  if found then
    if existing.idempotency_key <> operation_record->>'idempotency_key' then
      raise exception 'An operation id cannot be reused with a different idempotency key' using errcode = 'PT409';
    end if;
    if existing.status in ('succeeded','partial') and existing.payload_hash is not null
      and operation_record->>'payload_hash' is not null and existing.payload_hash <> operation_record->>'payload_hash' then
      raise exception 'A completed operation cannot be rewritten with different content' using errcode = 'PT409';
    end if;
    update tonde.director_operations set status = desired_status,
      producer = coalesce(operation_record->>'producer', producer),
      provider = coalesce(operation_record->>'provider', provider),
      model = coalesce(operation_record->>'model', model),
      model_profile = coalesce(operation_record->>'model_profile', model_profile),
      attempts = coalesce((operation_record->>'attempts')::integer, attempts),
      repaired = coalesce((operation_record->>'repaired')::boolean, repaired),
      rationale = coalesce(operation_record->>'rationale', rationale),
      limitations = coalesce(operation_record->'limitations', limitations),
      payload = coalesce(operation_record->'payload', payload),
      payload_hash = coalesce(operation_record->>'payload_hash', payload_hash),
      error_code = coalesce(operation_record->>'error_code', error_code),
      error_message = coalesce(operation_record->>'error_message', error_message),
      completed_at = case when desired_status in ('succeeded','partial','failed','cancelled') then now() else completed_at end
      where id = existing.id returning * into saved;
    return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
      'revision', saved.revision, 'idempotent', true);
  end if;
  -- Same idempotency key from an earlier attempt: this is that operation, not a second one.
  select * into existing from tonde.director_operations
    where workspace_id = target_workspace and idempotency_key = operation_record->>'idempotency_key' for update;
  if found then
    if existing.status in ('succeeded','partial') and existing.payload_hash is not null
      and operation_record->>'payload_hash' is not null and existing.payload_hash <> operation_record->>'payload_hash' then
      raise exception 'A completed operation cannot be rewritten with different content' using errcode = 'PT409';
    end if;
    update tonde.director_operations set status = desired_status,
      producer = coalesce(operation_record->>'producer', producer),
      provider = coalesce(operation_record->>'provider', provider),
      model = coalesce(operation_record->>'model', model),
      model_profile = coalesce(operation_record->>'model_profile', model_profile),
      attempts = coalesce((operation_record->>'attempts')::integer, attempts),
      repaired = coalesce((operation_record->>'repaired')::boolean, repaired),
      rationale = coalesce(operation_record->>'rationale', rationale),
      limitations = coalesce(operation_record->'limitations', limitations),
      payload = coalesce(operation_record->'payload', payload),
      payload_hash = coalesce(operation_record->>'payload_hash', payload_hash),
      error_code = coalesce(operation_record->>'error_code', error_code),
      error_message = coalesce(operation_record->>'error_message', error_message),
      completed_at = case when desired_status in ('succeeded','partial','failed','cancelled') then now() else completed_at end
      where id = existing.id returning * into saved;
    return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
      'revision', saved.revision, 'idempotent', true);
  end if;
  insert into tonde.director_operations(workspace_id, production_id, operation_id, operation_type, scope, schema_version,
    source_revision, source_intake_revision, status, producer, provider, model, model_profile, attempts, repaired,
    idempotency_key, collaboration_mode, reference_ids, constraint_summary, rationale, limitations, payload, payload_hash,
    error_code, error_message, started_at, completed_at, created_by)
  values (target_workspace, target_production, (operation_record->>'operation_id')::uuid, operation_record->>'operation_type',
    coalesce(operation_record->>'scope', 'production'), coalesce(operation_record->>'schema_version', 'tonde.director.1'),
    (operation_record->>'source_revision')::integer, nullif(operation_record->>'source_intake_revision','')::integer,
    desired_status, coalesce(operation_record->>'producer', 'deterministic'), operation_record->>'provider', operation_record->>'model',
    coalesce(operation_record->>'model_profile', 'default'), coalesce((operation_record->>'attempts')::integer, 0),
    coalesce((operation_record->>'repaired')::boolean, false), operation_record->>'idempotency_key',
    coalesce(operation_record->>'collaboration_mode', 'stop_at_major_decisions'),
    coalesce((select array_agg(value::uuid) from jsonb_array_elements_text(coalesce(operation_record->'reference_ids','[]'::jsonb)) as value), '{}'),
    coalesce(operation_record->'constraint_summary','{}'::jsonb), coalesce(operation_record->>'rationale',''),
    coalesce(operation_record->'limitations','[]'::jsonb), coalesce(operation_record->'payload','{}'::jsonb),
    operation_record->>'payload_hash', operation_record->>'error_code', operation_record->>'error_message',
    now(), case when desired_status in ('succeeded','partial','failed','cancelled') then now() else null end, auth.uid())
  returning * into saved;
  return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
    'revision', saved.revision, 'idempotent', false);
end;
$$;


commit;

-- ==========================================================================
-- 202610050054_director_retry_scope.sql
-- ==========================================================================

-- Forward hardening of 053 (already applied): workspace-wide keys must never reconcile another
-- Production's operation, and simultaneous retries must not race the unique constraint.
-- INV-01/26/27/29: one canonical Production, explicit scope, deterministic retry identity, tenant guard.
-- No table, RLS, grant or data changes. The transaction lock serializes operation recording within
-- one workspace only; a hash collision merely serializes unrelated work, never grants access.
begin;


create or replace function tonde.record_director_operation(
  target_workspace uuid, target_production uuid, operation_record jsonb
) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare existing tonde.director_operations; saved tonde.director_operations;
  desired_status text;
begin
  perform tonde_private.director_guard(target_workspace);
  if operation_record is null or jsonb_typeof(operation_record) <> 'object'
    or pg_column_size(operation_record) > 500000
    or coalesce(length(operation_record->>'operation_id'), 0) <> 36
    or coalesce(length(btrim(operation_record->>'operation_type')), 0) = 0
    or coalesce(length(btrim(operation_record->>'idempotency_key')), 0) = 0 then
    raise exception 'Invalid Director operation record' using errcode = '22023';
  end if;
  if not exists(select 1 from tonde.productions p where p.workspace_id = target_workspace and p.id = target_production) then
    raise exception 'Production unavailable' using errcode = 'P0002';
  end if;
  desired_status := coalesce(operation_record->>'status', 'queued');
  if desired_status not in ('queued','preprocessing','analyzing','synthesizing','succeeded','partial','failed','cancelled') then
    raise exception 'Unsupported operation status' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('tonde:director-operation:' || target_workspace::text, 0));
  select * into existing from tonde.director_operations
    where workspace_id = target_workspace and operation_id = (operation_record->>'operation_id')::uuid for update;
  if not found then
    select * into existing from tonde.director_operations
      where workspace_id = target_workspace and idempotency_key = operation_record->>'idempotency_key' for update;
  end if;
  if found then
    if existing.production_id <> target_production or existing.operation_type <> operation_record->>'operation_type' then
      raise exception 'An operation identity cannot be reused in a different Production or operation type' using errcode = 'PT409';
    end if;
    if existing.idempotency_key <> operation_record->>'idempotency_key' then
      raise exception 'An operation id cannot be reused with a different idempotency key' using errcode = 'PT409';
    end if;
    if existing.status in ('succeeded','partial') and existing.payload_hash is not null
      and operation_record->>'payload_hash' is not null and existing.payload_hash <> operation_record->>'payload_hash' then
      raise exception 'A completed operation cannot be rewritten with different content' using errcode = 'PT409';
    end if;
    update tonde.director_operations set status = desired_status,
      producer = coalesce(operation_record->>'producer', producer),
      provider = coalesce(operation_record->>'provider', provider),
      model = coalesce(operation_record->>'model', model),
      model_profile = coalesce(operation_record->>'model_profile', model_profile),
      attempts = coalesce((operation_record->>'attempts')::integer, attempts),
      repaired = coalesce((operation_record->>'repaired')::boolean, repaired),
      rationale = coalesce(operation_record->>'rationale', rationale),
      limitations = coalesce(operation_record->'limitations', limitations),
      payload = coalesce(operation_record->'payload', payload),
      payload_hash = coalesce(operation_record->>'payload_hash', payload_hash),
      error_code = coalesce(operation_record->>'error_code', error_code),
      error_message = coalesce(operation_record->>'error_message', error_message),
      completed_at = case when desired_status in ('succeeded','partial','failed','cancelled') then now() else completed_at end
      where id = existing.id returning * into saved;
    return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
      'revision', saved.revision, 'idempotent', true);
  end if;
  insert into tonde.director_operations(workspace_id, production_id, operation_id, operation_type, scope, schema_version,
    source_revision, source_intake_revision, status, producer, provider, model, model_profile, attempts, repaired,
    idempotency_key, collaboration_mode, reference_ids, constraint_summary, rationale, limitations, payload, payload_hash,
    error_code, error_message, started_at, completed_at, created_by)
  values (target_workspace, target_production, (operation_record->>'operation_id')::uuid, operation_record->>'operation_type',
    coalesce(operation_record->>'scope', 'production'), coalesce(operation_record->>'schema_version', 'tonde.director.1'),
    (operation_record->>'source_revision')::integer, nullif(operation_record->>'source_intake_revision','')::integer,
    desired_status, coalesce(operation_record->>'producer', 'deterministic'), operation_record->>'provider', operation_record->>'model',
    coalesce(operation_record->>'model_profile', 'default'), coalesce((operation_record->>'attempts')::integer, 0),
    coalesce((operation_record->>'repaired')::boolean, false), operation_record->>'idempotency_key',
    coalesce(operation_record->>'collaboration_mode', 'stop_at_major_decisions'),
    coalesce((select array_agg(value::uuid) from jsonb_array_elements_text(coalesce(operation_record->'reference_ids','[]'::jsonb)) as value), '{}'),
    coalesce(operation_record->'constraint_summary','{}'::jsonb), coalesce(operation_record->>'rationale',''),
    coalesce(operation_record->'limitations','[]'::jsonb), coalesce(operation_record->'payload','{}'::jsonb),
    operation_record->>'payload_hash', operation_record->>'error_code', operation_record->>'error_message',
    now(), case when desired_status in ('succeeded','partial','failed','cancelled') then now() else null end, auth.uid())
  returning * into saved;
  return jsonb_build_object('id', saved.id, 'status', saved.status, 'operation_id', saved.operation_id,
    'revision', saved.revision, 'idempotent', false);
end;
$$;


